INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni İçiyorum Seni!', 'seni-i-ciyorum-seni-mustafa-ceylan-r6mor', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '* Ne yapardım bilmiyorum? ! 

•	Sen olmasaydın? 

Seni içiyorum seni

Gül kokan nefesini

İpeksi  tenini, yosun gözlerini

Doldurmuşum kadehime

Seni içiyorum seni...

Öyle serinsin, öyle hafif

Damla damlasın dudaklarımda

Alev damaklarım oh çekiyor

Sen varsın bütünüyle kadehimde

Kadehim avuçlarımda...

Islaklığın dilimin kilidini açtı

Türküler, şarkılar gır’ la gidiyor.

Ateş gömlekli öfkemi paketledim

Ötelere tır’ la gidiyor...

Seni içiyorum seni! 

Gel, beraber içelim 

Olmaz mı? ...

 Vakit gırgırla geçiyor! ! !', '* Ne yapardım bilmiyorum? !  •	Sen olmasaydın?  Seni içiyorum seni Gül kokan nefesini İpeksi  tenini, yosun gözlerini Doldurmuşum kadehime S...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-iciyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluş', 'bulus-mustafa-ceylan-nzrvp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '•	Buldum, duydum

•	Zerreden sonsuza

•	Aşkın şarkısı...

Gökler, siz şahitsiniz sevgime

Yüreğimi biliyorsunuz...

Bulutlarınıza doldurdum umutlarımı

Haydi ıslatın yeryüzünü! 

Yok edin içimde hüznü

Ne duruyorsunuz? ! ..

Güneş, sırıtıp durma karşımda

Nikâh şahidim olacaktın hani? 

Ay, hani ışığında buluşacaktık

Sabaha dek konuşacaktık hani? 

Anladım, siz de yalancısınız...

Dağ, deniz, taş, toprak

Ağaç, çiçek, yılan, böcek

Yol, köprü, ev, duvar, masa, kasa

Dil, göz, baş, ayak el

Ne varsa ne, hoş

Hepsi de bomboş...

Şahidim sanık, sanığım tanık

Gözlük camım kırıldı herhalde

Her şey bulanık...

Düşlerim ipekli mendilde saklı

Kelepçede ellerim...

Kurşun yemiş tam göğsünden

Ayaklar altına düşmüş

Fikirlerim...

Önce göğü vermeliyim mahkemeye

Sonra yeri her şeyiyle...

Ben sevgiye mahkumum

İnanıyorum, haklı benim! ..

Dava dilekçesini yazarken

Girdim maddenin içine

Gördüm gerçeği, gördüm de vaz geçtim

Faniyi, fenayı, baki’ yi buldum

Yok oldum...

		11.07.2003', '•	Buldum, duydum •	Zerreden sonsuza •	Aşkın şarkısı... Gökler, siz şahitsiniz sevgime Yüreğimi biliyorsunuz... Bulutlarınıza doldurdum umutl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bulus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suya Hasret', 'suya-hasret-mustafa-ceylan-v5n4a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SUYA HASRET

Ateşler içindeyim

Kökten yaprağa kurumaktayım

Feryadım arşı kapladı

Bulut aramaktayım...

Anadolu’yum suya hasret

Yanmaktayım...

Asya’ dan Avrupa’ ya uzanmaktayım

Üç tarafım masmavi deniz

Kilometrelerce uzar nehirlerim

Peki neden

Ormanlarımla birlikte cayır cayır

Yanmaktayım? ..

Ateşler içindeyim

Bağ, bahçe, bostanım susuz; 

Köylüm uykusuz.

Haydi uzatın ellerinizi

Çare bulun derdime evlâtlarım! 

Sizden uzakta değilim

Sizinleyim...

		Ocak / 2003', 'SUYA HASRET Ateşler içindeyim Kökten yaprağa kurumaktayım Feryadım arşı kapladı Bulut aramaktayım... Anadolu’yum suya hasret Yanmaktayım... ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/suya-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N e var, 30 Yıl Daha Yaşasam?', 'n-e-var-30-yil-daha-yasasam-mustafa-ceylan-w6c6o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şöyle otuz yıl daha yaşasam

Dünya mı batar? Ne var yani? 

Bu gelişme, bu devran, bu eylem

Bana mı yasak? Ne desem? ..

İpi mi kopar kahpe dünyanın? 

Mili mi çıkar ha? Deyin hele! 

Otuz yıl daha yaşasam fena mı olur? 

İfrata mı kaçtım? Neden bu velvele? 

Bu gök yüzüne yerden uzanan cümbüş,

Bu sanal dünya, internet

Bu bilgisayar, bu kavun kokulu et

Hayret! 

Bana mı fazla yani? 

Ne var? Ne var sanki? 

Terazi mi eğilir? 

Kantar mı yamulur? 

Batar mı köhne dünya? 

Bir otuz yıl daha kalsam? 

Sakız, lâstik top: Hop! Hop! Hop! 

Kağnı, kara saban

Gölge oyunu cillop! 

Bacağım kopmak üzre bir yerinden

Eyvallah dememizi bekliyorlar baksana

Oyunu bitir diye sesleniyorlar! 

Vaz geçtim istemekten otuz yılı,

Her şeyi oluruna bıraktım hasılı...', 'Şöyle otuz yıl daha yaşasam Dünya mı batar? Ne var yani?  Bu gelişme, bu devran, bu eylem Bana mı yasak? Ne desem? .. İpi mi kopar kahpe dün...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/n-e-var-30-yil-daha-yasasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrail'' e', 'azrail-e-mustafa-ceylan-0hplx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nerdesin? 

Nerelerdesin? 

Duymadın mı sesimi gayri sen? 

Hadi yapsana görevini! 

Vakit mi var yoksa? 

Söyler misin? ..

Ben, emir kulu

Ya sen? Sen de aynısın! 

Havalandığını görüyorum

Yanına kimse yaklaşamaz neden? 

Geciktin ya merak ettim

Şikâyetçi misin kendinden? 

Görevini yap desem yapamazsın

Zira, sen de emir kulusun...

Ben yaşadım yalan, yanlış işte

Sense yaşadın mı bilmiyorum? 

Nerdesin, nerelerdesin? 

Bilmem ki hangi yerdesin? 

Hani alacaktın beni dünyadan? 

Almadığına göre,

Anlaşıldı, emir beklemektesin...

Ne yapalım, biz de attık kolumuzdan saati

Yolduk örümcek tutmuş takvimi duvardan

Gün doğmuş, gün batmış beyhude gayri

Dön bana, gel bana uzaklardan

Seni beklemekteyim...

		Ağustos / 2003', 'Nerdesin?  Nerelerdesin?  Duymadın mı sesimi gayri sen?  Hadi yapsana görevini!  Vakit mi var yoksa?  Söyler misin? .. Ben, emir kulu Ya sen...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/azrail-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-burhan-kucuk-z484k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdim

Sevdim Işığı, ışık da parıldayıp,yansıyan yüzleri

Sevdim tüm  çiçekleri,çiçeklerden bal yapan arıları

Sevdim koza yapan böceği, kozadan çıkan kelebeği

Sevdim bir fidanı, fidan dan oluşan ormanları

Sevdim dereleri,dereden oluşan nehirleri,gölleri

Sevdim harfleri,harflerden oluşan kelimeleri,kitapları

Gözlerinde kendimi gördüğümde,sevdim birde seni

Burhan KÜÇÜK

Kdz.EREĞLİ', 'Sevdim Sevdim Işığı, ışık da parıldayıp,yansıyan yüzleri Sevdim tüm  çiçekleri,çiçeklerden bal yapan arıları Sevdim koza yapan böceği, kozad...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Arıyorum', 'dost-ariyorum-halil-kesken-7hku0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlıkta çevrem ışıktır benim

Elimde şimşek var, mum tutmuyorum

Dostluğa delice aşıktır kalbim

Varmısın arkadaş dost arıyorum

Mazluma kurbanım, zalimi sevmem

Düşenin ardından bakıpta gülmem

Ben taşra çocuğu ihanet bilmem

Varmısın arkadaş dost arıyorum

Yalnız kalmak için bulunmaz tasam

Mertlik kuralımdır, doğruluk yasam

Halil dost demektir, kurulmuş masam

Varmısın arkadaş dost arıyorum

Düşmanı kafaya takmamalısın

Paraya pula hiç bakmamalısın

Sırtını dönmekten korkmamalısın

Varmısın arkadaş dost arıyorum

Halil Kesken                                   07.05.2000', 'Karanlıkta çevrem ışıktır benim Elimde şimşek var, mum tutmuyorum Dostluğa delice aşıktır kalbim Varmısın arkadaş dost arıyorum Mazluma kurb...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dost-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum Of Aman', 'agliyorum-of-aman-i-brahim-dikmen-2-4bwa1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretinin ateşi,

Yüreğimi dağlasın.

Varsın gönlüm,bu gece,

Sensizliğe ağlasın.

Bende tükenmez bir aşk,

Delice sevdalar var.

Senin olsun,anılar,

Sensiz geçen,o''yıllar.

Nezaman bitecek bu,

Hasretin ah! nezaman,

Gözlerimde bir hüzün,

Ağlıyorum of! aman.', 'Hasretinin ateşi, Yüreğimi dağlasın. Varsın gönlüm,bu gece, Sensizliğe ağlasın. Bende tükenmez bir aşk, Delice sevdalar var. Senin olsun,anı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agliyorum-of-aman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandil', 'kandil-i-brahim-dikmen-2-d0o6d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerimde,damla damla yaş,

Ellerimde,ıslanmış mendil.

Yüreğimde,kasırgalar,

Başucumda,yanar kandil.

Duvardaki resmine,bakarım bazan,

Gözlerinde kaldı,yaslı gözlerim.

Sanki uzaklardan,gel der gibisin,

Yalvarırcasına,titrekti seslerin.', 'Gözlerimde,damla damla yaş, Ellerimde,ıslanmış mendil. Yüreğimde,kasırgalar, Başucumda,yanar kandil. Duvardaki resmine,bakarım bazan, Gözler...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kandil-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal Diyemem Sana', 'kal-diyemem-sana-i-brahim-dikmen-2-5h4fm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son bir defa,öp beni,

Sarıl bana,bir tanem.

Yinemi gidiyorsun,

Veda bile etmeden.

Kal diyememki sana,

Koymuşsun sen kafana.

Gideceksin,besbelli,

Benden çok uzaklara.

Elin elime değsin,

Canlansın,hatıralar.

Hayal olup bitmesin,

Sevda yüklü,o''yıllar.

Aşkla dolu,o''yıllar.', 'Son bir defa,öp beni, Sarıl bana,bir tanem. Yinemi gidiyorsun, Veda bile etmeden. Kal diyememki sana, Koymuşsun sen kafana. Gideceksin,besbe...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kal-diyemem-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır Yarab', 'sabir-yarab-i-brahim-dikmen-2-famia', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düştüm mapus damlarına,

Vurdum başım duvarlara.

Güneş doğmaz koğuşlara,

Sabır YARAB sabır bana.

Sabır YARAB biraz sabır.

Ağlar yarim,kaderime,

Yaşlar dolmuş gözlerine.

Yazık oldu,yazık bize,

İnsaf YARAB bize insaf.

İnsaf YARAB insaf bize.

Yarim giymiş beyazları,

Kaldıramam acıları.

Kıramadım taş duvarı,

Öldür YARAB öldür beni,

Öldür YARAB,beni öldür.

Ay tutulmuş bilemedim,

Yarim ölmüş gidemedim.

Yıllar oldu göremedim,

Doya doya sevemedim,

Öldür YARAB,beni öldür.

Öldür YARAB,öldür beni.', 'Düştüm mapus damlarına, Vurdum başım duvarlara. Güneş doğmaz koğuşlara, Sabır YARAB sabır bana. Sabır YARAB biraz sabır. Ağlar yarim,kaderim...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yarab-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamın Yıldızı', 'sevdamin-yildizi-murat-demir-rv1ia', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğime kötü dertler doluştu

Acılarım hasret ile buluştu

Gözlerim arıyor sense yanımda

Yoksunya sevdamın yıldızı düştü

Düştü bak sevdamın yıldızı düştü

Hasret pınarımın suları coştu

O zaman anlardın beni o zaman

Seni sevse idi adamın puştu

Seni sarsa idi adamın puştu

Karabulut gibi doluyum dolu

Şimşekler çakıyor gözlerim sulu

Çoktan beni sensiz koyardım ama

Bir garip sevdanın kuluyum kulu

Düştü bak sevdamın yıldızı düştü

Hasret pınarımın suları coştu

O zaman anlardın beni o zaman

Seni sarsa idi adamın puştu

Seni sevse idi adamın puştu', 'Yüreğime kötü dertler doluştu Acılarım hasret ile buluştu Gözlerim arıyor sense yanımda Yoksunya sevdamın yıldızı düştü Düştü bak sevdamın y...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdamin-yildizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tay Tay Bebeğim', 'tay-tay-bebegim-mehmed-arif-cx830', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bebeğim bilmez düşmeyi,

koşar uçurumlara

bebeğim bilmez ateşi 

düşer yangınlara

tay tay bebeğim

tay tay sana

gülücükler verdin

neşe saldın ocağıma

bebeğim açar kollarını

koşar kucağıma

çakır gözlerin bebeğim

can katar canıma

tay tay bebeğim 

tay tay sana

seni güldüren melekler

uğrasınlar akşama

hımm hımm dersin uyku vakti

geçti bizim meme saati

süt ver bana annecim 

gözlerimi uyku bastı

tay tay bebeğim 

tay tay sana

salih kılsın seni dilerim

hazreti Mevla', 'bebeğim bilmez düşmeyi, koşar uçurumlara bebeğim bilmez ateşi  düşer yangınlara tay tay bebeğim tay tay sana gülücükler verdin neşe saldın o...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Arif']::text[], 8.5, '{"poet":"Mehmed Arif","poet_slug":"mehmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tay-tay-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Serzenişi Bir', 'yurek-serzenisi-bir-mehmet-emin-fidan-51qms', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürek Serzenişi Bir

Babadağın serin yaylalarının ardından

yanan kalbimin ilacı bir bakışında gizli

nazar boncuklu gözlüm, elif boylum,dişi kısrağım,

gözlerinin içindeki ince sızının

tutsağıyım her bakışında ki gizin; 

ben ecdat kokulu toprağın 

her zerresinde, her bütününde,

ishak baba da, gazi paşa da, 

sarı saltuk ta, bayram dede de

hep seni aradım

evet, bilirim ben aşk kokan yaylaları; 

kılıç şakıyan meydanları, ilim tüten medreseleri,

hu hu lara karışan tekkeleri, alperenlerin ocağını; 

dar a düşenlerin himmetkarını

ama her şey biryana Anadolum

sevda kokulu yanık türkülerini hatırlamalıyım! ..

seni hatırlatan her anı unutmamalıyım

adın anıldığı zaman can kuşum, bir tanem, 

Anadolum...

gözlerim dolar, yüreğime kan yumağı düşer

dobruca da bir duygu seli, bir kara sevda

taşında, toprağında, bir gencin yüreğinde, 

bir kızın gözlerinde

bir bakışında, bir dokunuşunda

sen buralandan gittin gideli Anadolum

dobruca öksüz, tuna mahzun

ishakca nın sırtlarından Tuna yı her görüşümde 

Fırat aklıma düşer

tuna nın fırat a, dobruca nın Anadolu ya olan

sevdası böyle bitmez', 'Yürek Serzenişi Bir Babadağın serin yaylalarının ardından yanan kalbimin ilacı bir bakışında gizli nazar boncuklu gözlüm, elif boylum,dişi k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Fidan']::text[], 8.5, '{"poet":"Mehmet Emin Fidan","poet_slug":"mehmet-emin-fidan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yurek-serzenisi-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buyurun Sohbetimize', 'buyurun-sohbetimize-yusuf-dagitmac-l6xdk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönlüne huzur dolsun, sohbetimden bilenin.

Diline bade dolsun, suyumuzdan içenin

Dosta kapımız açık, düşmana kapısızız.

Bizi övene kızar, kızana sarılırız...', 'Gönlüne huzur dolsun, sohbetimden bilenin. Diline bade dolsun, suyumuzdan içenin Dosta kapımız açık, düşmana kapısızız. Bizi övene kızar, kı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Dağıtmaç']::text[], 8.5, '{"poet":"Yusuf Dağıtmaç","poet_slug":"yusuf-dagitmac","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/buyurun-sohbetimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir oyun bu...', 'bir-oyun-bu-yildiz-ark-jwm24', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen beni anlayamazsın, ben seni

Biz onları, onlar hiçkimseyi.

Bir oyundur inanılması umulan

Anlamsız bir sürü fikirlere.

Saygı diyorlar adına, sevmesen de

Bir sabah kendim için ama sırf kendim için

Alıp başımı gitsem uzaklara

Anlayabilir miydin beni...

Yoksa okuduğun kitapları mı oynardın,

Saygı duyarak bana.

Bencil olma! 

Anlayamadığım suskunluklar, yanıtsız sorular

Yanıtsızlığın takriri gösteren boyutu...

Kabullenmezlik görüldüğü halde,

Ben haklıyım oyunu; 

Önce kendine oynanan...

Yazık kandıysan', 'Sen beni anlayamazsın, ben seni Biz onları, onlar hiçkimseyi. Bir oyundur inanılması umulan Anlamsız bir sürü fikirlere. Saygı diyorlar adın...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Ark']::text[], 8.5, '{"poet":"Yıldız Ark","poet_slug":"yildiz-ark","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-oyun-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Günün Hikayesi', 'bir-gunun-hikayesi-i-brahim-dikmen-2-5ojgf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabah yedi oldu,başladı yeni bir gün,

Karanlığın arkasında kaldı,o''eski dün.

İnsanlar, sokaklara döküldü,pür telaş,

Yaşama sevinci,ekmek peşinde hepsi.

Kimi memur,kimi işçi,kimisi işveren,

Hepsinin ortak yanı,bir lokma ekmek parası.

Kimi masa başında,kimisi maden ocağında,

Kiminin elinde kalem,kiminin yağlı karası.

Öğlen olunca,simitçinin yüzü güler,

Doyurur karnını,memurum biraz.

İşçi kardeş,evden getirmiş aşını,

Simit yiyen memur değil,millet utansın.

Akşam eve döner baba,eli boş,

Çocuklar bakar,gözleri bir hoş.

Evde ana,ne pişirsem diye düşünür,

Yorgunluktan biçare,sanki sarhoş.

Gece aç yatar,çoluk çocuk,

Rüyasında görür,kangallı sucuk.

Terlemiş alnı,boncuk boncuk olmuş,

Hasta yavrum,hasta olduk.

Utanmaz eli yağda,balda olan,

Kuş tüğü yastıklarda yatan.

Kızlarla diskolarda,cenk atan,

Rezil olmuş,millet utansın.', 'Sabah yedi oldu,başladı yeni bir gün, Karanlığın arkasında kaldı,o''eski dün. İnsanlar, sokaklara döküldü,pür telaş, Yaşama sevinci,ekmek peş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-gunun-hikayesi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüncü Göz', 'ucuncu-goz-tolga-yildiz-6iiwp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zorlamakla olmuyor bu iş

İnsanın içinden gelmeli

Elinden Tuttuğunda

Elinin, olduğu yerde isteyerek olması gerekli

Gözüne baktığında umudun şafağını seyretmelisin

Konuştuğunda dilin değil, yüreğin kurmalı cümleleri

Paylaşılması gerektiğinde sen daha çok vermelisin

Onun iki gözü varsa üçüncü gözü de sen olmalısın

Aşkı beyninde değil, O''nun yüreğinde aramalısın.', 'Zorlamakla olmuyor bu iş İnsanın içinden gelmeli Elinden Tuttuğunda Elinin, olduğu yerde isteyerek olması gerekli Gözüne baktığında umudun ş...', ARRAY['Türk Edebiyatı','Şiir','Tolga Yıldız']::text[], 8.5, '{"poet":"Tolga Yıldız","poet_slug":"tolga-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ucuncu-goz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben / Sen', 'ben-sen-halit-demir-srxil', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben: Munzur dağlarının deli poyrazı

Ben: Yolları tozlu Erzincan''lıyım

Ben: İlkbaharda coşan deli Fıratı

Ben: Dut ağacında ki sevgi  dalıyım.

Sen: Bu bahtsız şehrin gizemindesin

Sen: Munzur da açan dağ nilüferisin

Sen: Umut kaynağım ilham perimsin

Sen: Bu şehirde bulunmaz eşsiz birisin

Ben: Bu bedenle çektim yıllarca sancı

Ben: Bende değilim bir görsen hancı

Ben: Sevgi yüküyle yüklenmiş kağnı

Ben: Rüzgar önündeki yaprak gibiyim.

Sen: Gece doğan yıldız, uykularımda düş...

Sen: Gök kubbe altındaki, kehribar, gümüş

Sen: Damarımda dolaşan kana bürünmüş..

Sen: Bu bedenin aldığı nefes gibisin', 'Ben: Munzur dağlarının deli poyrazı Ben: Yolları tozlu Erzincan''lıyım Ben: İlkbaharda coşan deli Fıratı Ben: Dut ağacında ki sevgi  dalıyım....', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-sen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tecrit', 'tecrit-adnan-ferit-nryku', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beynime ispiyonlamışlar; 

-Bahar geldi

kalp bir garip,

sanki biti pirelendi.

Yerinde duramıyor,

pek bir deli bakıyor,

diye.....

Beyin emir verdi,

Bende 

Tecrit edip kilitledim,

Göğüs kafesime....', 'Beynime ispiyonlamışlar;  -Bahar geldi kalp bir garip, sanki biti pirelendi. Yerinde duramıyor, pek bir deli bakıyor, diye..... Beyin emir v...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tecrit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekler Yetişmez Saksıda', 'cicekler-yetismez-saksida-necmi-unsal-lezys', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizim  oralarda,

Çiçekler  yetişmez  saksıda.

Ya  bir  dere  kenarında,

Ya  bir  kaya  çatlağında

Askıda.

Veya  örme  taş  duvarında,

Karşıda.

Bir  bakmışsın

Beton  yığınlar  arasında

Parayla  satılır  çarşıda.

Ben  şaşkın,

Sevdam  şaşkın.

Hasret  ıstırabıyla

Gurbetler  taşkın.

Bizim  oralarda

Çiçekler  yetişmez  saksıda.

Ya  bir  nadas  tarlasında  küskün.

Yada  bir  yem  torbasında  suskun.

Kurtulur  gövdesi  kalın  olanlar.

Tohum  olur  güneşte  solanlar.

Seni  göremeyince

Ben  askıda,

Sevdam  askıda...

15 Mart 2004 Pazartesi, Danimarka-Køge  20.40', 'Bizim  oralarda, Çiçekler  yetişmez  saksıda. Ya  bir  dere  kenarında, Ya  bir  kaya  çatlağında Askıda. Veya  örme  taş  duvarında, Karşıd...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cicekler-yetismez-saksida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzeli..Susmak..!', 'en-guzeli-susmak-hasan-basri-kale-1owd2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.......her taraf şiir.! 

.......birbirinden güzel.

.......her taraf şair.! 

.......kimi değerli/çoğu birbirinden güzel.

artık en doğrusu

susmak/ve/seyretmek/güzel.', '.......her taraf şiir.!  .......birbirinden güzel. .......her taraf şair.!  .......kimi değerli/çoğu birbirinden güzel. artık en doğrusu sus...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/en-guzeli-susmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol-cu', 'yol-cu-piranli-zaza-ijzvg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Otobüsün altında

Akıyor, çizgi çizgi

Birçok yolcu tükendi; 

Yollarsa hiç bitmedi.

Ayakların altında

Geçiyor, çizgi çizgi

Tükenen yol değil ki; 

Sadece birkaç çizgi.

Bir adamın alnına

Vuruyor, çizgi çizgi

Yıllar bir bir tükendi; 

Yollar hiç tükenmedi! ..

          28.03.2004

             Pozantı', 'Otobüsün altında Akıyor, çizgi çizgi Birçok yolcu tükendi;  Yollarsa hiç bitmedi. Ayakların altında Geçiyor, çizgi çizgi Tükenen yol değil k...', ARRAY['Türk Edebiyatı','Şiir','Piranli Zaza']::text[], 8.5, '{"poet":"Piranli Zaza","poet_slug":"piranli-zaza","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yol-cu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumral', 'kumral-esma-ozdemir-a8u2o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün, demini almış

Kor gibi aleviyle

Bırakır suya eteklerinin rengini…

Eritir özünden

Dağıtır gökkuşağı harelerini...

Deryada yarım elma

Yıkar bedenini

Gözlerinden yakamozlar saçarak

Soğutur yüreğini

Yoğurur yeniden

Hazırlar yarına kendini...

Gün, demini almış 

Yarım elma...

Bırakır kalbini semaya...

Bir efkâr akşamında

Düşer üstüme

Bakır kızılı saçlarının gölgesi

Vurur gözlerimden

Dolar içeri

Dağıtır renklerini…

Bir tutam perçeme bağlanır ömrüm

Dökülür alnına bir demet; açılır gönlüm

Kumral sevdalarda dalgalanır yüreğim...', 'Gün, demini almış Kor gibi aleviyle Bırakır suya eteklerinin rengini… Eritir özünden Dağıtır gökkuşağı harelerini... Deryada yarım elma Yıka...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kumral-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Kıyısında Çığlıklarım', 'gecenin-kiyisinda-cigliklarim-leyla-ayyildiz-93dhf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin siyahı yorganım,

Gelme...

.....

.....

Gecenin sesinde hıçkırıklarım,

Gelme...

.....

.....

Gecenin kollarında sancılarım,

Gelme...

.....

.....

Gecenin tırnaklarında acılarım, 

Gelme...

.....

.....

Gecenin kıyısında çığlıklarım,

Gelme...

.....

.....

Gecenin ayazında yaralarım,

Gelme...

.....

.....

Gecenin koynunda bedenim,

Gelme...

.....

.....

Gelme! 

Tüm gülüşlerin kalleşti.', 'Gecenin siyahı yorganım, Gelme... ..... ..... Gecenin sesinde hıçkırıklarım, Gelme... ..... ..... Gecenin kollarında sancılarım, Gelme... .....', ARRAY['Türk Edebiyatı','Şiir','Leyla Ayyıldız']::text[], 8.5, '{"poet":"Leyla Ayyıldız","poet_slug":"leyla-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gecenin-kiyisinda-cigliklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kız gider', 'bir-kiz-gider-mustafa-ceylan-olsw4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kız gider sabah, akşam

Penceremin, kapımın önünden; edalı

Yüreğim tekeri kırılmış çocuk arabası

Söz dinlemez yüreğim,

Yüreğim o kıza sevdalı...

Okyanus ötesi yemişi mübârek

Bir yürüyüşü, bir bakışı var ki

Sormayın be birader,

Neyin nesi, kimin fesi bilemem

Bir kız ki gün onunla gelir, gider

Bense  benimle kavgalı...

Dalsa yeşil, hem de yemyeşil 

Üstelik incirleri olgunlaşmak üzere

Kaldırımdaki dala uzanır, 

Uzanan belki de annesi

Koparır birer birer yemişleri

Kız güler, güler de bakar cama doğru

Ben elin oğlu...

Ya üst kat, ya yandaki apartmandan

Bana ne, kimden, şundan, bundan? ! 

Bir kız gider sabah akşam

Ben giderim, 

İçim gider arkasından...

Bir adam başını uzatır

Garip, anlaşılmaz bir şekilde bakar bana

Sakın olmasın, kızın babası! 

İçkiyse içiyorum, sarhoşun birisiyim

Verme kızını bana emmi! 

Aşkım kaybolur gider,

Çünkü,

Ben onun delisiyim...

Şurada üç kuruşluk keyfim var,

Zararım yok kimseye görüyorsun

O geçen bahar gülüşlü kız kimin? 

Kimin hadi söyle desem söylemezsin? 

Gel bir kadeh parlatalım desem,

İçmezsin...

Git be adam kapımın önünden, git be! 

İncir ağacı neyse ben oyum işte

Var mı ötesi? ! 

			2.08.2003', 'Bir kız gider sabah, akşam Penceremin, kapımın önünden; edalı Yüreğim tekeri kırılmış çocuk arabası Söz dinlemez yüreğim, Yüreğim o kıza sev...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-kiz-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunu Bil', 'bunu-bil-oguzkan-bolukbasi-z76va', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seninle kaybettiğim umudumun peşindeyim

bunu bil

umudum sensin

gece görüşlerine çıkıyor gözlerim

çıplak

ışığın izindeyim

o da sensin

bunu bil

umut  ışığa esir

ben sana

umut da yalnız

ben de

bunu bil', 'seninle kaybettiğim umudumun peşindeyim bunu bil umudum sensin gece görüşlerine çıkıyor gözlerim çıplak ışığın izindeyim o da sensin bunu bi...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bunu-bil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya mı Batar Sanki?', 'dunya-mi-batar-sanki-mustafa-ceylan-ec409', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle sıkıntılar içindeyim ki

Rakamlarla ifadesi mümkün değil,

Ama şu başkasında göbek atan 

Rakamlar var ya

Bir de bana baksa dünya mı batar yani? 

Mesela şu sayısal loto tutsa cebimdeki

Rakamları yanyana bir altılı gelse

Anasını sattığımın sayıları

Ömrüm boyunca gülmediniz yüzüme

Şu sıkıntımı bari görün

Kör mü gözünüz be! 

Öyle sıkıntılar içindeyim ki

Bana yakışmıyor, 

Aşıyor boyumu kat be kat

Tanrı biliyor...

Sadece ben olsam gene iyi,

Evlâtlarım da aynı durumda

Öyleyse ulan oğlum rakamlar

Ömürde bir kere gülün be! 

Bir kere olmaz mı yani? 

Artık şansa kaldı işimiz, 

Ya da yok yere satılık evimiz

Alan yok mu he fırsatçılar, alan yok mu? ! 

Üç otuz paraya desem leş kargaları,

Hep beraber tünerler başıma...

Yardım edin, faizsiz borç verin desem

Güler, burun kıvırırlar şu elli yaşıma...

Ulan sayılar be, bir kere dönün de gelin

Bir de biz olalım ne olur damatla gelin, 

Dünya mı batar? 

Sıranız mı bozulur anasını satayım? 

Banka kredi kartları bir taraftan,

Gırtlağa kadar borç cabası,

Kazancımın tamamı faize yetmiyor 

Neredesiniz be rakamlar? 

Kurtarın bu gece beni,

Yoksa burnumdan kan damlar! ! ! 

			2.08.2003', 'Öyle sıkıntılar içindeyim ki Rakamlarla ifadesi mümkün değil, Ama şu başkasında göbek atan  Rakamlar var ya Bir de bana baksa dünya mı batar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dunya-mi-batar-sanki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sabah', 'bu-sabah-volkan-tekin-borvt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu Sabah

Niye uyandım bilmiyorum bu sabah,

Sıkıntılar zaten uyutmamış tüm gece.

Ne bileyim uyandım işte,

Belki bir mucize olur diye.

Olur da bu kötü rüya biter diye.

Bir mucize hiç beklenmeyen bir anda.

Hiç beklemediğim bir yerden

Geçmişimden, senden bile uzaktan 

Unuttuğum, kırdığım, üzdüğüm yüreklerden

Yalnızlığımın derinliklerinden

Belki bir mucize olur diye

Uyandım bu sabah.

Çok şey istiyorum biliyorum

Ama neden olmasın 

Neden son bir şans olmasın? 

Çok mu geç kaldım', 'Bu Sabah Niye uyandım bilmiyorum bu sabah, Sıkıntılar zaten uyutmamış tüm gece. Ne bileyim uyandım işte, Belki bir mucize olur diye. Olur da...', ARRAY['Türk Edebiyatı','Şiir','Volkan Tekin']::text[], 8.5, '{"poet":"Volkan Tekin","poet_slug":"volkan-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-sabah-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-volkan-tekin-5n5lz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl oldu bilmiyorum

Bugün gerçekten anladım,

Seni sevdiğimi, senin beni sevdiğini.

Ve anladım ki hiç beraber olamayacağız,

Birbirimize sevgi sözcükleri fısıldamayacağız,

Kırlarda gezmeyeceğiz,

Şarkılar söylemeyeceğiz birbirimize.

Ama bileceğiz yüreğimizin nerede olduğunu

O neye üzülmüş hissedecek yüreklerimiz

Mutsuz olmayacağız biliyorum,

Senin beni sevdiğini bilmek bile yetiyor.

Seni yüreğimde hissetmek yetecek

Tenini tenimde hissetmeme

Bunu hiç bilmesen 

Sana itiraf edemesem de sevgimi

Biliyorum her başlayan güne

Merhaba demek bile yetecek

Sana sevgimi anlatmaya...', 'Nasıl oldu bilmiyorum Bugün gerçekten anladım, Seni sevdiğimi, senin beni sevdiğini. Ve anladım ki hiç beraber olamayacağız, Birbirimize sev...', ARRAY['Türk Edebiyatı','Şiir','Volkan Tekin']::text[], 8.5, '{"poet":"Volkan Tekin","poet_slug":"volkan-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/merhaba-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marifet', 'marifet-mustafa-ceylan-j9ntc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yuvasında “Hak” diyerek ağlayan

Karıncanın feryadında marifet.

Sevdamızı çiçek çiçek taşıyan

Kelebeğin kanadında marifet.

İnsanların kalp gözüyle baktığı,

Yağmurların “Allah” deyip aktığı,

Ruhumuzun sonsuz hızla çıktığı

Gök kubbenin çatısında marifet.

Mevlâna’ yla yüreğinde Konya’ nın,

Leyla, Mecnun arasında sevdanın,

Kuzeyinde, güneyinde dünyanın

Doğusunda-batısında marifet.

O’ ndan ayrı olmuyor ki bir anım,

Yalnız O’ ndan O’ nu ister bu canım,

Mucizeler mucizesi Kur’ an’ ım

Hakikatin ortasında marifet.', 'Yuvasında “Hak” diyerek ağlayan Karıncanın feryadında marifet. Sevdamızı çiçek çiçek taşıyan Kelebeğin kanadında marifet. İnsanların kalp gö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/marifet-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar İçinde Yalnızım', 'i-nsanlar-i-cinde-yalnizim-mustafa-ceylan-i5s39', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alâkayı kestim devri devrandan

Yalnızım milyonlar içinde yalnız.

Ceylanı kovmuşum garip ceylandan

Yalnızım insanlar içinde yalnız.

İpini kopardım maddenin, pulun

Yükledim yükünü kızın, oğulun

Öfkeyi, kavgayı artık durdurun! 

Yalnızım dünyalar içinde yalnız.

Silip te süpürdüm şanı, şöhreti

Şimdi yaşıyorum sessiz gurbeti

Kestim atomlarla çılgın sohbeti

Yalnızım figanlar içinde yalnız.

İçimdeki nefsi fırlatıp attım,

Kendi sarayımda gölgemle yattım.

Hep bana konuştum, bana anlattım

Yalnızım feryatlar içinde yalnız.

Maddede yalnızım, manâda Hakk’ la

Birlikteyim... Hem de kara toprakla,

Sessizim, sakinim büyük firakla

Yalnızım zamanlar içinde yalnız.', 'Alâkayı kestim devri devrandan Yalnızım milyonlar içinde yalnız. Ceylanı kovmuşum garip ceylandan Yalnızım insanlar içinde yalnız. İpini kop...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/insanlar-icinde-yalnizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biricik Varlık', 'biricik-varlik-mustafa-ceylan-x1qng', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Terk etmişim, terk etmişim, terki terk

Bir Sen varsın, bir ben varım, başka yok.

Ötelerde kaldı gayri, bunca cenk

Bir Sen varsın, bir ben varım, başka yok.

Kâinatı sayfa sayfa yazansın,

Türlü türlü nimetleri dizensin

Rahim sensin, Kerim sensin, Bir sensin

Bir Sen varsın, bir ben varım, başka yok.

Yeryüzüne yaptın beni halife,

Verdin bana Kur’ an ile tarife,

Örnek oldum cahile ve arife

Bir Sen varsın, bir ben varım, başka yok.

Mevcudata nakşetmişsin adını

Bahşetmişsin bir ömürlük yarını,

Ruh kökümle haykırmışım aşkını

Bir Sen varsın, bir ben varım, başka yok.', 'Terk etmişim, terk etmişim, terki terk Bir Sen varsın, bir ben varım, başka yok. Ötelerde kaldı gayri, bunca cenk Bir Sen varsın, bir ben va...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biricik-varlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir''lik', 'bir-lik-mustafa-ceylan-r9dlu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sancılı geceler geçmez diyordum

Çiçekler bir daha açmaz diyordum

Kelebek her bahar uçmaz diyordum

Meğer yanılmışım hepsi oluyor,

Hepsinin özünde aşkın duruyor...

Kırk parça aynayım, hepsinde varsın

Cümle aynaları birliğin sarsın

Bana çok yakınsın, gayri’ ye sırsın

Gönlüm birliğinden ilham alıyor,

Zerrede, ummanda seni buluyor.

Birlik ırmağında çağlayıp aktım,

Mucize Kur’ an’ la dünyaya baktım

Çok şükür, aşkını böylece tattım

Sevdan ile gözüm, gönlüm parlıyor,

Parladıkça bir’ de bir’ i bir’ liyor...', 'Sancılı geceler geçmez diyordum Çiçekler bir daha açmaz diyordum Kelebek her bahar uçmaz diyordum Meğer yanılmışım hepsi oluyor, Hepsinin öz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-lik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesaplaşma', 'hesaplasma-nevzat-bayramoglu-hurdemi-8mx8a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok şey yaşadım, neler tanıdım kırkına varmadan,

Beni üzenler oldu, ben üzdüm farkına varmadan,

Gül yüzlü güleç dostları çağırdım gönül evime,

Madrabazın, namerdin şu dönen çarkına sarmadan.

Hürdemi', 'Çok şey yaşadım, neler tanıdım kırkına varmadan, Beni üzenler oldu, ben üzdüm farkına varmadan, Gül yüzlü güleç dostları çağırdım gönül evim...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hesaplasma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemim Var!', 'sitemim-var-ahmet-agdere-7ae6p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgilim, bu sensiz kaçıncı gecem bilmem..

Bilmem ki kaçıncı gözyaşı gözlerden düşen.. 

Bilmem kaçıncı yudumum hayattan çaldığım..

Bilmem kaçıncı ak, bu saçlarıma üşüsen..

Takvimden bunca sayfayı koparmana rağmen,

Gönülden silinen ne sen, ne de sevgindir; ben! ..

Her tarafta varken onca güldürecek sebep,

Vazgeçtim beni güldüren bunca eğlenceden...

Merak edip ne bir kere arayıp sorarsın

Sensiz ne yapar bu gönül, hiç kafa yormazsın

Çat kapı geleceksin diye beklerim sense; 

Bir çalıkuşu, o daldan bu dala konarsın! ..

Hasret kaldım sevgine ve güzel sözlerine,

Hiç sönmeyecekmiş gibi yanan gözlerine,

Olmazken beni yaratana isyanım bile,

Bitmez sitemim var o müstebit yüreğine! ..', 'Sevgilim, bu sensiz kaçıncı gecem bilmem.. Bilmem ki kaçıncı gözyaşı gözlerden düşen..  Bilmem kaçıncı yudumum hayattan çaldığım.. Bilmem ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sitemim-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağınık Oda-1', 'daginik-oda-1-sirma-mersin-w2zr2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duvarda, duran saat durmuş; 

Sensizliğin, başladığı bi anda! 

Dağınık odadaki; kirli çarşaflara sarılmış anıları, toplamadan! 

Düş bozgunu yangınlardan kaçan; bir yürek sustu...

Kalemle cümleler arasında; 

Yazılmamış sevda dizelerine,

Savurulan kırıntılarla, parçalanmış bir hayat tükendi...

Bir çekmecede, sararmış gönül defterin sayfalarında; 

Bastırılmış özlemlerin izine dokundu, bi başkası...

Yaldızı dökük aynanın karşısında; 

Perçemine ak düşmüş yalnızlığın sureti göründü...

............................................................

............................................................

Suskunluğun mührü vurulmuş; 

Kimliksizlerin anların, imzasız kahramanlarından sonra...

Herşey olduğu gibi kalakalmış; 

Bu dağınık odada...

6.4.04', 'Duvarda, duran saat durmuş;  Sensizliğin, başladığı bi anda!  Dağınık odadaki; kirli çarşaflara sarılmış anıları, toplamadan!  Düş bozgunu y...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/daginik-oda-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Kabri ve Dünyası', 'sairin-kabri-ve-dunyasi-mustafa-ceylan-nfofb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yerim bir koltuğun üç minderi kadarsa

Niçin başıma yıkılır koskoca dünya? 

Cismim bu kadar, ismim sıfırsa

Unutulacaksam bana ne 

Geceden, doğan günden

Ve bana ne bildiğimden, gördüğümden! 

Saat bire çeyrek varmış, yat dedi Gülay

Ya bu saatte gelen uçak neyin nesi? 

Ya bu ağustos böceğinin 

Bitmeyen teranesi? 

Ya bu yoldan geçen taksi? 

Balkonlardan yankılanan ses? 

Dumanı yan çiziyor sigaramın dünyaya

Bana ne herkes? 

Horlarım diye korkuyorum

Aman, konu komşu 

Yeter ki rahatsız olmasın

Sırtımı duvara dayamalı,

Yetimler gibi yatmalıyım; 

Tansiyonumu silip süpürmeli,

Sabaha bir ceylan gibi kalkmalıyım,

Nasipse şayet! 

Nasip olacağı yok ya gülen seherlerin

Zaten davası var benle gökle yerin

Yerim bir koltuğun üç minderi kadar

Kollarım yana açık değil dostum

Merak etme geliyorum

Göğsüme dolalı ellerim...

II

De ki veliydi,

De ki deliydi

Yok, vaz geçtim

Her ikisi de değil

De ki:

Adamın birisiydi...

İşte şu kadar kabrim

Bir koltuğun üç minderi

Balkonda bir çizgi bile değil 

Kapladığım yer; 

Örtme üstümü

Bir taş bile koyma baş ucuma

İstersen eğer...

Karşı balkonlarda kahkaha

Sohbetin en güzeli ötelerde

Bense üç minderlik yerde yer beğenirim

Bense benden bana gider gelirim...

Farzet öldüm, işte ölçülerim

Kabrim bu kadar olacak

Fazla mı yoksa? 

Ben unutulup gideceğim biliyorum,

Yağmur öpecek üstümdeki toprağı

Yel süpürecek, ben duymayacağım

Ama iyi bildiğim bir şey daha var

Şiirlerim konuşacak, susmayacak', 'Yerim bir koltuğun üç minderi kadarsa Niçin başıma yıkılır koskoca dünya?  Cismim bu kadar, ismim sıfırsa Unutulacaksam bana ne  Geceden, do...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/sairin-kabri-ve-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yaz', 'bu-yaz-sirma-mersin-dpkja', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mavi beyaz köpükler,

Islak kumun üzerinde yürüyorken; 

Ayaklarımı okşuyor...

Sarı kızıl saçları ile güneş,

Bedenimi ısıtırken...

Tatlı bir esinti  nefesini, yüzüme üflüyor...

Yüreğim; 

Yaza uyanışı ile kıpır kıpır oluyor! 

Sensizliğin kıyısında; 

Adım adım yalnızlığa doğru ilerlesemde,

Umudun, özlemin hayali ile; 

Mor kayaların altında beni bekleyen sen olmasan,

Yaşar mıydım? ben bu yazı...

Gözlerimin derinliğine dalıp gitmiş olduğumu; 

Dudaklarıma kondurduğun,

O ateşli öpüşünle anladım...

Ben yazı; 

Senin içinde yaşadım...

4.4.04', 'Mavi beyaz köpükler, Islak kumun üzerinde yürüyorken;  Ayaklarımı okşuyor... Sarı kızıl saçları ile güneş, Bedenimi ısıtırken... Tatlı bir e...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-yaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Sensiz Çok Güzel', 'hayat-sensiz-cok-guzel-mustafa-ceylan-8qqq0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu son olsun, bu son; dönme geriye

Gelirsen yüzüne bakmayacağım.

Yıktığın köprünün altında kaldın

Vallahi elinden tutmayacağım.

İnşallah çiçeğin dalında kurur! 

Teninde yılanlar, çıyanlar yürür

Bedduam tutsun da yere kan tükür! 

Hatırını bile sormayacağım.

Üç koca boşasın anla dünyayı

Anla düş te yere Hanya, Konya’ yı

Mendil ser de dilen, bulma parayı

Artık bir kuruş ta vermeyeceğim.

Sahte gururunun esiri oldun

Küçük rakamların küsuru oldun

Çamurlu ayağın hasırı oldun

Ayağımı bile sürmeyeceğim.

Sensiz daha güzel bu tatlı hayat

El sürsen ekmeğe olurdu bayat,

Evsiz, barksız kalıp sokaklarda yat! 

Altına döşekler sermeyeceğim.

Beklediğin haber karalı gelsin

Elemler, kederler sıralı gelsin

Askerden sevdiğin yaralı gelsin

Yalvarsan da yara sarmayacağım.

O yalancı dünyan başına çöksün

Gözlerin sürekli göz yaşı döksün

Söz verdim, tarihler bir yiğit görsün

Bir daha adını anmayacağım.

Ey küçük beyinli, ufuksuz kadın

Kalasın güneşsiz, şafaksız kadın

Desin eşin, dostun “ahlâksız kadın”

Uğrunda Mecnunca yanmayacağım.

Ceylan’ ın duası tutar yakandan

Milyar mikrop gezsin damarda kandan

Hep kahkaha atsın millet arkandan

Veren eldim, elim sunmayacağım.

		26/ 27.05.2003', 'Bu son olsun, bu son; dönme geriye Gelirsen yüzüne bakmayacağım. Yıktığın köprünün altında kaldın Vallahi elinden tutmayacağım. İnşallah çiç...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/hayat-sensiz-cok-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar Bir Kişilik', 'aynalar-bir-kisilik-mustafa-ceylan-20usq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kişilik aynaları hararet bastı

Gözlerin var içinde bayram yeri,

Hissediyor, görüyorum

Yetim bir çocuğum bayram yerinde...

Gülüşün başkalarına

Balonların, şekerlerin de, 

Yalanların bana...

	

Gece, aynalar da kör benim gibi

Gece, aynalar da yalnız, kederli

Çaresizim, kimsesizim, bakmam

Bakamam kahrolası bir kişilik aynalara

Kar yağan şakaklarımda hüzün türkülerinin dansı var

Yağmur yüklü bulutlar geçer içimden...

Pamuk şekerlerin, tatlı dillerin var bilirim

Yorgun sahillere vuran, dalgalardır kahkahan

Acıların, hasretin bana...

Bir kişilik aynalar buz tutmuş biliyor musun? 

Cam kırıkları dolu yakamoz baştanbaşa pul pul...

Kelepçe, ranza, kapı, gardiyan bir tarafım

Öte yanım yapayalnız İstanbul...

Bugün böyle yalnız geçiyor canım! 

Kimseler bilmez aynalarla kavgamı

Bir sen bilirsin, bir gözlerin bilir

Gözlerin, yalnızlığımın ufkunda

Gök aynadır ufka yükselir...

Gel diyorum, gül diyorum duymazsın

Yakasından tutup atalım diyorum

Bitsin bir kişilik aynaların, yalnızlığı bitsin

Çünkü, sen bana aitsin...

Anlaşıldı gelmeyecek, gelemeyeceksin

Kırıp kör aynaları tuzla buz edip

Bitireceğim sancısını ayrılıkların

Yarın, yarın, yarın...', 'Bir kişilik aynaları hararet bastı Gözlerin var içinde bayram yeri, Hissediyor, görüyorum Yetim bir çocuğum bayram yerinde... Gülüşün başkal...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aynalar-bir-kisilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadere Sitem', 'kadere-sitem-mustafa-ceylan-v1uxz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözünü sevdiğim kader

Canıma okuduğun yeter! 

Silin, düş iki yakamdan

Oldum dertliden beter...

Sevsem ihanet çıkar

Kaşık uzatsam, pis kokar

Çıkarcılar leşimi beklerken

Gölgemde takla atar...

Bir faydalı ağacım

Meyvelerim kapış kapış, ama; 

Arşa yükselir de  kimse duymaz

Kimse bilmez, feryadım, acım...

Bostan yeri yüreğim

Verir de almaz ellerim,

Geriye sermayem kalır

O da, yarım kalan şiirlerim...

Diplomam, sertifikam

Boyum kadar, ağam...

Yayan gidip gelirim eve

İçimi anlatamam...

Ne adım kalacak burada

Ne de söylediklerim.

Gözünü sevdiğim kader

Yeter! Sızlıyor kemiklerim...', 'Gözünü sevdiğim kader Canıma okuduğun yeter!  Silin, düş iki yakamdan Oldum dertliden beter... Sevsem ihanet çıkar Kaşık uzatsam, pis kokar ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kadere-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz', 'buz-atila-gunal-zagfa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerin ellerimdeyken

Terlemiyorsam

Ürpermiyorsam

Kalbimin atışlarını duyamıyorsan

Elveda sevdiğim

Meğer ben ölmüşüm

07-04-2004', 'Ellerin ellerimdeyken Terlemiyorsam Ürpermiyorsam Kalbimin atışlarını duyamıyorsan Elveda sevdiğim Meğer ben ölmüşüm 07-04-2004...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/buz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verelim Gitsin', 'verelim-gitsin-umit-kilislioglu-ozger-k0p8e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendi gönlüm diye söylemiyorum; 

On parmağında on marifet var.

Şiir yazar, beste yapar,

Gerçeği alır, sahteyi kovar.

Kimler  kimler istedi de vermedim.

Biraz kırılgandır; incindiği an,

Dünyayı eder kendine de, size de dar.

E! Kadı kızında da kusur olur o kadar.

Bize söz düşmez, baksanıza onlar anlaşmış...

Her an kaçabilirler can havliyle

Onun için  bir an önce işlem bitsin

Allah’ın emri, Peygamber''in kavliyle

Verelim gitsin.

(7.4.2004)', 'Kendi gönlüm diye söylemiyorum;  On parmağında on marifet var. Şiir yazar, beste yapar, Gerçeği alır, sahteyi kovar. Kimler  kimler istedi d...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/verelim-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*çingene Kız*', 'cingene-kiz-tansel-yegen-r9c76', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''bir ateş yaktılar ve etrafında toplandılar bir akşam üstü''

o,  çingene kız

savururken eteklerini coşkuyla

boyuyor yüreğini pembeye

saçlarında papatyalar

dönerken kendi etrafında

açılan beyaz baldırlarında

aç gözler dolaşmada

eflatun inerken gece ormana

tepesinde ışık huzmeleri 

/ne çok yıldız var bu gece

-notalar ona çalarken melodilerini

o ellerindeki zilleri birbirine vurduğunda

dünyada kaç aşk başlar

raks ederken tüm şehvetiyle

ayak parmaklarının ucunda

göz kırpıyordu 

en çok sevdiği yıldıza

durduğunda çingene kız

papatyalar dökülmüştü saçlarından

kimsenin bilmediği bir renk

kaldı avuçlarında

/ yalnızlığı

düşlerindeyse

saman sarısı saçlarını

sevdiği gencin

parmaklarıydı okşayan

-hissettim...

 06-08-2003, 12:29', '''bir ateş yaktılar ve etrafında toplandılar bir akşam üstü'' o,  çingene kız savururken eteklerini coşkuyla boyuyor yüreğini pembeye saçların...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yegen']::text[], 8.5, '{"poet":"Tansel Yegen","poet_slug":"tansel-yegen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cingene-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oh Ne Güzel!', 'oh-ne-guzel-mustafa-ceylan-mpf28', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzun, çok uzun yolculuktayım

Kervanlardan başım dönüyor.

Çöl yağmura gebe sen yoksun ya

Ayaklarım yanmıyor gayri,

Azat ettim deli gönlümü şükür

Çifte kapılı hanlarda mutluluk

Benimle bölüşür de bölüşür zamanı,

Oh ne güzel! ...

Oh ne güzel yeni sevdalarda kanatlanmak

Oh ne güzel yeni bayramlara kavuşmak

Ve oh ne güzel seven, değer bilen,

Hatır soran yüreklerle buluşmak

Oh ne güzel! ...

Hepsi de sen gibi kadınların

Topuz yapıp bağladıysa saçını,

Hiç olmazsa ipekçe-pamuksu dilleri

Hiç olmazsa gül üstüne gül taşır bana

Gül kokulu elleri,

Oh ne güzel! ...

Uzun, çok uzun yolculuktayım

Deli kuşlarla aya ıslık çalıyorum,

Gölgemle birlikte gün ışığında

Uzanıp kısalıyorum...

İçimde suların valsı

Yerli yerinde tansiyonum

Kel kafamın tası atmıyor,

Sensiz yaşamak öyle güzelmiş

Oh ne güzel! ...

Oh ne güzel, aramadan aranmak

Oh ne güzel, kulağı çınlamak, anılmak

Ve oh ne güzel sevenin sevileni olmak

Ne güzel oh! ...

Hepsi de senden daha güzel,

Yüreğinde bir ceylanım hepsinin

Bora, tayfun, fırtınayım hem de...

Durun ey beynimin hücreleri 

Burada durun! 

Geçen köhne zamanı

Bir unutayım, bir unutayım...

Susun ey eşyanın makaraları

Burada susun! 

Yeni, yepyeni aşklarda özelden özelim

Kurtuldum ya senin prangalarından

Oh ne güzelim! ..', 'Uzun, çok uzun yolculuktayım Kervanlardan başım dönüyor. Çöl yağmura gebe sen yoksun ya Ayaklarım yanmıyor gayri, Azat ettim deli gönlümü şü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/oh-ne-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Dünyanın Dibine! !', 'vur-dunyanin-dibine-mustafa-ceylan-0ojoy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kim demiş yalan diye? 

Bu dünya yalan olsa gene iyi

Hiç olmazsa yalanın yumuşak bir yanı vardır.

Zulüm ve işkenceden başka ne? 

Vur gitsin be dostum,

Vur gitsin bu dünyanın dibine! 

İnsanı canavar, yılanı melek geçinir

Şekeri zehir, güzeli fingir fingir

Bize göre dizayn edilmemiş işte

Bıktım yaşamaktan bıktım

Neredesin Azrail? 

Para denen adinin kölesi her şey, herkes

Bu parayı icad edenin taaa! ! 

Her neyse üç nokta yanyana

Utanır oldum insanlığımdan...

Selam versen, su içsen

Ya da tuvalete gitsen para,

Oğlum bile parasızken yüzüme bakmaz

Kara, kapkara kader yakamı bırakmaz

Bir şey var sanki kirli yakamda? ! 

Kim demiş yalan diye

Yalan olsa gene iyi bu dünya,

Emekli maaşım su, elektrik, telefon, kira

Gerisi fasifos, gerisi ya angarya, ya icra...

Kravat takmışım diplomanın boynuna

Ayaklarım vücudumu taşımaz,

Yol geçen hanı cebim,

Vur oyna, çal oyna, şıkı şık Recebim! ..', 'Kim demiş yalan diye?  Bu dünya yalan olsa gene iyi Hiç olmazsa yalanın yumuşak bir yanı vardır. Zulüm ve işkenceden başka ne?  Vur gitsin b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vur-dunyanin-dibine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(GÜLCE-Buluşma) Aferin Sana!', 'gulce-bulusma-aferin-sana-mustafa-ceylan-iwr7w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kadar kolay mı terkedip gitmek? 

Mâziyi hangi silgidir bir anda siliveren? 

Sen mi icad ettin asırlara kafa tutan

Kale surlarını toz edip yerle yeksan etmeyi? 

Senin buluşun mu Leyla''dan Aslı''dan önce

Çöllerde yürek kavurması pişirmek? 

....De hadi! 

.......Söyle! 

.........Çekinme! 

............İtiraf et! 

...............Konuş! ...

Pılını pırtını toplayıverdin

Çekirge misali hoplayıverdin

Sırtıma hançeri saplayıverdin

Aldattın sen beni, aferin sana! 

Bu kadar kolay mı terkedip gitmek? 

Hani nerde kaldı sabahı olmayan aşk gecelerimiz

Hani bir dilim ekmeği, yokluğu, fukaralığı

Bölüşüp; sarı lâcivert yastığa 

Yorgun akşamlarda düşen başımız

Hani, şiirlerime ruh katan bestelerin nerde kaldı? 

....De hadi! 

.......Söyle! 

.........Çekinme! 

............İtiraf et! 

...............Konuş! ...

Dilerim Mevlâ’ dan yüzün gülmesin

Aşkın kıyamete kadar sürmesin

Düşesin diline birgün herkesin

Ağlattın sen beni, aferin sana! 

Hani geceleri ay’ dın, ışıktın? 

Tenime dolanan bir sarmaşıktın

Hani yalnız bana, bana aşıktın? 

Söylettin sen beni, aferin sana! 

Kopardın dalımdan bir yaprak gibi

Boynumda dururken çıngırak gibi

İçinden kan akan bir ırmak gibi

Çağlattın sen beni, aferin sana! 

Geçme sakın ola geçme yanımdan

Aman ha, ölürsem tutma salımdan

Denizin göğsüne yat limanından

Fırlattın sen beni, aferin sana! 

Bu kadar kolay mı terkedip gitmek? 

Nerdesin, nerelerdesin? 

Zindana düşsen kelepçe erir,

Açılır kapılar çıkar gelirdin...

Cehennem dibine taht mı kurdun yoksa

Cehennemi yaşatırsın bana böyle? ! 

....De hadi! 

.......Söyle! 

.........Çekinme! 

............İtiraf et! 

...............Konuş! ...

Demek içindeydi bu kötü niyet

Unutma adımı her yerde söz et

Soyadın işkence, adın eziyet

İnlettin sen beni, aferin sana! 

			8 Mayıs 2003/16.04.2010', 'Bu kadar kolay mı terkedip gitmek?  Mâziyi hangi silgidir bir anda siliveren?  Sen mi icad ettin asırlara kafa tutan Kale surlarını toz edip...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/gulce-bulusma-aferin-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadan Doğmuşa Döndüm', 'anadan-dogmusa-dondum-mustafa-ceylan-ymvj3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mayıs ortasında inceden ince

Gül üstüne yağmur yağmışa döndüm

Ayın on üçünde gidiverince

Vallahi anamdan doğmuşa döndüm

Güle güle demek noter tasdiki

Hiç bire döner mi yamulan iki? 

Yosun gözlüleri balık istifi

Bedava taşıyan dolmuşa döndüm

Haram etmiş idim göze uykuyu

Şimdi kırbaçladım atsız kovboyu

Gölgemle başbaşa caddeler boyu

Yürürken on milyar bulmuşa döndüm

Sardım sarmaladım ipekli şala

Öğleden sonraydı, üçe beş kala

Yıkadım, arıttım, yatırdım sala

Camide namazın kılmışa döndüm

Uzatma Ceylan’a sakın elini

Yüz bin arı soksun meşhur dilini

Kırarak kafesin demir telini

Kuşları havaya salmışa döndüm.', 'Mayıs ortasında inceden ince Gül üstüne yağmur yağmışa döndüm Ayın on üçünde gidiverince Vallahi anamdan doğmuşa döndüm Güle güle demek note...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anadan-dogmusa-dondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amin Diyorum', 'amin-diyorum-mustafa-ceylan-gbjuf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ceylan’ ın adını unutacakmış

İnşallah unutur, amin diyorum

Göz pınarlarını kurutacakmış

İnşallah kurutur, amin diyorum

Veremezmiş bana bütün ömrünü

Boşuna geçirmiş bu geçen günü

Yepyeni aşkıyla çılgın gönlünü

İnşallah avutur, amin diyorum

Bir gün kurtulacak tuzaklarda ki

Eyvallah, hoşça kal, böylolsun, peki! 

Yanına gelince uzaklarda ki

Ayakta uyutur, amin diyorum

Günah kovanının zehirli balı

Nasıl umursamaz, nasıl edalı? 

Boş sandığı gökler yıldızla dolu

Herhalde doludur, amin diyorum

İnsan sevdiğine böyle mi eder? 

Yeter yaptıkların bu kadar yeter! 

Belki de alnına yazılmış kader

Eğriyi doğrultur, amin diyorum', 'Ceylan’ ın adını unutacakmış İnşallah unutur, amin diyorum Göz pınarlarını kurutacakmış İnşallah kurutur, amin diyorum Veremezmiş bana bütün...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/amin-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırak Aranıyor', 'cirak-araniyor-huseyin-cayikli-qbk3b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yıllar geride kalmıştı.geride kalan yılların günlerine bakınca bir kaç arkadaşla emindik birşeylerin değişeceğine.Azimliydik kararlıydık bir şeylerin bizi bulup bu karanlıktan kurtulacağımızı biliyorduk.yıllar geçip bu zamana gelince kafama bir balyoz düştü.evet birşeyler değişti değişen biz olmuştuk.değişen zamandı zamanla beraber sevdiklerimizde değişiyordu ne apansız bir süreçti bu sev sevil ve terket.istemeden terkettik bazı yerleri.büyüdüğümüz şehirden kaynaklanıyor olması gerek ki dostluk arkadaşlık marşları deniz kenarında söylenirdi.çamlıklarda kızlarla sevişmezdik biz meydanlarda büyüdük meydanlarda sevişip meydanlarda ölürdük.biz sadece buna inanmıştık.kısacası kaybetmeye.biz kaybetmeye alışmıştık.kaybeden hep biz olmuştuk.mazoşistlik değildir ama zevk alıyorduk artık acı çekmekten bir süreden sonra alışkanlık yapıyordu.biz kaybetmeyi lise yıllarında benimsemişiz o zaman tutturursan yazar olacağım diye kaybedersin tabi.her zaman kendimizi avuturduk şimdi olduğu gibi ne zormuş yaşamak ne zormuş birşeylere baştan başlamak.tekrar aşk yaşamak ne kadar yabancıymış bu coğrafyada ne kadar korkakça ne kadar korkuyorum aslında uzak bir aşka sevdalanmış bir yüreği intihara meğilli yürekle değiştirmeyi.şu kente baktığımda her tarafında ayrı bir acı ayrı kederler.bize türkülerimizi söyletmiyorlar bu şehirde.biz türkülerimizde kaybettik.şimdi diyeceksiniz bana bu kadar acı ne işi,bu kadar acı özgürlüğün emeğin tutsak kalmış sevdaların bu kadar acı bu sehrin kendinde var biz onun yanında yalan ama sadece bir sorun var bizim gibi olacak kısacası kaybedecek bir çırak arıyoruz son kuşağın temsili için...', 'yıllar geride kalmıştı.geride kalan yılların günlerine bakınca bir kaç arkadaşla emindik birşeylerin değişeceğine.Azimliydik kararlıydık bir...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/cirak-araniyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alimallah', 'alimallah-mustafa-ceylan-e4e1v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Madem ki sevmiyorsun, madem ki git diyorsun

Alimallah bir daha yüzüne bakmaz Ceylan

Dert ortağı sanarak, için için yanarak

Alimallah bir daha derdini dökmez Ceylan

Çek gayri üzerimden, hain gölgeni çek, çek

Aldattığın besbelli, yalan değil som gerçek

Uçurum kenarından kurtulursun diyerek

Alimallah bir daha dizini çökmez Ceylan

Sakın ola aşkını hiçbir yerde anlatma

Gözünü gözlerinden yâdellere kaçırtma

Masmavi göklerdesin ey kâğıttan uçurtma

Alimallah bir daha ipini çekmez Ceylan

Alıştırıp sonunda çekilmez her çileye

Benzetmiştin değil mi yaralı bir köleye? 

Yemin etti bin kere, fethettiği  kaleye

Alimallah bir daha bayrağı dikmez Ceylan

Var git göklerde uçur, gönlündeki kuşunu

Var git başka bir tüple ısıt, kaynat aşını

Bu son olsun diyerek söz dinlemez başını

Alimallah bir daha belâya sokmaz Ceylan', 'Madem ki sevmiyorsun, madem ki git diyorsun Alimallah bir daha yüzüne bakmaz Ceylan Dert ortağı sanarak, için için yanarak Alimallah bir dah...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alimallah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak', 'uzak-huseyin-cayikli-2w4m5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kadın uzaktı

uzak olan sadece kadındı.

kadının adı artık önemlide değil

gelene kadar başka bir kadın öpülmeyecek

ama adıda anılmayacak.', 'kadın uzaktı uzak olan sadece kadındı. kadının adı artık önemlide değil gelene kadar başka bir kadın öpülmeyecek ama adıda anılmayacak....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uzak-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(GÜLCE-Buluşma) Al Senin Olsun!', 'gulce-bulusma-al-senin-olsun-mustafa-ceylan-0hvbt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasretin vurduğunda sevdamın toprağına 

Haykırışını alıp gitti sular göğe 

..Geri döner mi, dönmez mi bilinmez, 

……Gümüş tel büklümünde inceldi zaman 

………Sensizliği solumada ufkumun ötesi 

………….Bıktım, usandım yaşamaktan; 

Şimdi yapayalnız yorgun gecede 

Kan ağlar yüreğim al senin olsun 

Aşkın incisiydim istiridyede 

Düştüm denizlere, bul senin olsun 

Bul, 

…Bul ki boğulmak neymiş 

……….Sensizlik denizinde boğulmak; 

……………Anlarsın bakınca yüzüme 

……………………….Ve bel ki de acırsın 

…………………..Acırsın halime de 

……………….Basarsın göğsüne, 

………….Yaralarıma 

…....Merhem olsun sıcaklığın diye… 

Baykuş yuvasına döndü şu gönlüm 

Çok basite indi gözümde ölüm 

Bilirim kalmadı geriye ömrüm 

Ömrüm senin olsun, gel senin olsun 

Gel be hayın! 

…..Gel be zalım! 

……….Gel neredeysen ses ver sesime 

………….Bir sarı gelin ol da gel! 

……………Azrailim ol istersen 

……………..Yeter ki çık gel 

……………….Yürek adresime! … 

İki düş kurmuşum sağ ve soluma 

İki düş boyunca girdin koluma.. 

Hicran mayınını dizip yoluma 

En içli şarkıyı çal senin olsun 

Hasretin vurduğunda sevdamın toprağına 

Alıp gitti sular haykırışını 

Ölüm döşeğinde ırmaklar susuz, 

…Yapışkan bir sıcaklık 

…….Gökyüzünün camında.. 

………Köz ateş yangınlarda içim,dışım 

…………Neredeysen çık gel! 

………….Sevdiğim, bir tanem 

…………..Hayat arkadaşım 

Ceylanım, diyorlar adıma garip 

Yazılmış bahtıma uçurumla dip, 

Özlem sehpasında boynumdadır ip, 

Tenimden canımı al senin olsun...', 'Hasretin vurduğunda sevdamın toprağına  Haykırışını alıp gitti sular göğe  ..Geri döner mi, dönmez mi bilinmez,  ……Gümüş tel büklümünde ince...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gulce-bulusma-al-senin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alil Alil', 'alil-alil-mustafa-ceylan-3tb2i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ne biçim insansın anlamadım ki? 

Bundan sonra adımı yaz alil alil

O sahte sevgilinin tutup elinden

Akdeniz kıyısında gez alil alil

Sevda mesleğinde çıktık ya çırak

Yüreğimde çalkanan şu dalgaya bak

Gayri okyanusları sen bana bırak

Derelerin içinde yüz alil alil

Diyorlar ki: Yüreği yol geçen hanı

Haksız yere harcadı koca Ceylan’ı

Pişman olup da bir gün geçen zamanı

İstersen kurşunlara diz alil alil

Elinde kurumasın yaktığın kına

Şayet gelemiyorsan bana, yakına.

Bulutlar morardıkça çöksün bağrına

Gözün yağmura dönsün kız alil alil

Hep karşında gördüğün bir yorgun dede

Geçip gitti ömrü yalnız sevgide

Sen kahkaha patlatıp gezin caddede

Dolaşalım burada biz alil alil', 'Sen ne biçim insansın anlamadım ki?  Bundan sonra adımı yaz alil alil O sahte sevgilinin tutup elinden Akdeniz kıyısında gez alil alil Sevda...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alil-alil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Bak Dayanamam', 'aglama-bak-dayanamam-huseyin-cayikli-7u7ud', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ağlama baba

ne oldu anlayamam ama

ağlamak yakışmıyor

hele birde aylardan haziransa

dayanamam', 'ağlama baba ne oldu anlayamam ama ağlamak yakışmıyor hele birde aylardan haziransa dayanamam...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aglama-bak-dayanamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(GÜLCE-Yunusca/Ziyadeli) Acayip Dünya', 'gulce-yunusca-ziyadeli-acayip-dunya-mustafa-ceylan-xvjhe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acayip fingirdek bu yalan dünya

Tepemde döner aldatır...

.....................Döner ha döner...

Çılgın saatlerle yolumu kesmiş

Beynime iner balyozu 

.....................İner ha iner...

Misafir gelmişiz hem de üç günlük

Giyeriz sonunda cepsiz bir önlük

Kıldan ince aklı parçalayan yük

Çilesi biner omzuma 

.....................Biner ha biner... 

Ele pamuk bulut, yandığım ateş

Yoklukla yalnızlık tek bende kardeş

Kargalar eylemde, sokaklarda leş

Kokusu siner üstüme 

.....................Siner ha siner...

Mısra mısra şiir, ceylan ağıdı

Maziden âtiye yansır öğüdü

Önüme koyarak siyah kâğıdı

Durmadan dener sınavda

.....................Dener ha dener...

Ey Ceylan sen öğren nasıldır sonun? 

Tahtadan bir atla bitecek sorun

Ermeden sabaha umut mumunun

Titreyip söner ışığı 

.....................Söner ha söner...', 'Acayip fingirdek bu yalan dünya Tepemde döner aldatır... .....................Döner ha döner... Çılgın saatlerle yolumu kesmiş Beynime iner ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gulce-yunusca-ziyadeli-acayip-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntikam', 'i-ntikam-mustafa-ceylan-km2ze', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kandil akşamına ermeden daha

Vurdum bir yıldızla ben seni vurdum

Sesinden belliydi ah ile vah’ ın

Duydum da göklere dilek savurdum

İçin ağlıyordu “iy’olmuş” derken

Nasıl bu intikam oldu mu erken? 

Tozlanmış takvime seni gömerken

Düğünüme ay’ ı bile çağırdım

Dedim ki “teslim ol” bayrağı indir

Ağlayan ben değil, hain kalbindir

Kalktı da üstümden koca silindir

Sahil boyu koştum, coştum, bağırdım

Gayri deli gönlüm bey, paşa, ağa

Neşeli bir türkü koydum dudağa

Aşk lokantasında girip mutfağa

Pilavın üstüne ciğer kavurdum

Vallahi keyiften sigara yaktım

Öcümü aldım da kalmadı ahtım

Parlak yıldızlarla donandı bahtım

Tuttum fincanları terse çevirdim', 'Kandil akşamına ermeden daha Vurdum bir yıldızla ben seni vurdum Sesinden belliydi ah ile vah’ ın Duydum da göklere dilek savurdum İçin ağlı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/intikam-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(GÜLCE-Bahçe)  Abluka', 'gulce-bahce-abluka-mustafa-ceylan-0xgy7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuşattım duayla çevreni senin

Artık nefes bile alamazsın sen

Halatla bağlandı ayağın, elin

Benden uzaklarda kalamazsın sen

Yaktığın ateşte kavrulacaksın

Ağlayıp, sızlayıp kahrolacaksın

Vicdan azabıyla kıvranacaksın

Dünyada bir huzur bulamazsın sen

Sen

Kara

Kapkara

Büyülerde

Üç vakte kadar

Kıvranırken garip

Yollar çizeceğim ben

O muhteşem dönüşüne

Konfeti yağan, yakın, uzak 

Dolambaçlı, yılanlı, acaip

Bıçak yarasından daha da keskin

Daha da alevli yüreğim volkandan

Anla gayri,anla, öfkeli dilim

Sen çizdin kaderini ben değil

Gel koyma hasreti araya

Gel salkım söğüt, gel eğil

Söyletme bu deliyi

Söyletme gel yeter! 

Nerelerdesin? 

Yüzün göster,

Duy beni,

İşit,

Gel! 

Karıştım suyuna, girdim havana

Sen benimsin benim, ey hain Suna! 

Aşkın hesabını vermeden bana

Öleyim desen de ölemezsin sen

(Ö)   lemezsin diyorsam, ölemezsin inan ki

İ(Z)   in duruyor halâ kapımın eşiğinde

El(L)   lerin suluyor kahır çiçeklerimi

Özl(E)   dim diyorum, duvardaki resmine arada bir

Özle(D)   im anlıyor musun? 

Özled(İ)   mmmm..

Dualarım yüreğinin içinde

Nefes alışında çepeçevredir...

Ölemezsin diyorsam, aynen öyledir

Bu sebeple 

Diyorum ki sana:

Eleği eledik duvara astık

Sonunda selâmı, sabahı kestik

Davacı olacak başından yastık

Rahatça uykuya dalamazsın sen

Ceylan’ ın sözünde bulunmaz hile

Doğuştan yazımsın düşmüşüz dile

Oynatsan dünyayı parmağın ile

Kahkaha savurup gülemezsin sen', 'Kuşattım duayla çevreni senin Artık nefes bile alamazsın sen Halatla bağlandı ayağın, elin Benden uzaklarda kalamazsın sen Yaktığın ateşte k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/gulce-bahce-abluka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-i-nci-bakrac-k5jpd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Defalarca ''kal'' dedim gitmek isterken sen...

Hata benim, suç benim.

Haksızım ve haklısın sonuna dek,

Gideceğim dediğinde bırakmalıydım.

Affet yapamadım.

Habersiz gitmene gerek yoktu.

Seni zorla tutacak değildim.

Neyse...Boşuna ağrıtmayayım başını.

Artık yoksun ve yokum hatta.

İnan dönsen de farketmez.

Yani sormam hiç bir şeyin hesabını.

Sen de haklısın.

Belki giderken hoşçakal deseydin,

Yani veda etseydin,

Belki son kez ben yine ''kal'' derdim.

Sen git...Git tabi....

Ben burdayım nasıl olsa,

Yani sonsuza dek olmasa da,

Bir kaç yüzyıl daha.

Düşünüyorum da; 

Haklısın be, sonuna kadar haklısın.

Ben deli divane, kalbini kırmayı beceremem.

Sen git eniyisi...

Benim yalnız olduğumu kim söyledi? 

Sen varsın ya bende.

Acı depoladığın bedenim var.

Ha bi'' de yanında dökemediğim gözyaşlarım var.

Daha sayayım mı? 

Kırık dökük düşlerim, paramparça umutlarım var.

Sen beni boşver de git en iyisi.

Ha git dediğime bakma, ben burdayım hala.

Nasıl mı? ...Bıraktığın gibi...

Canın sıkıldıkça ara, gel, istediğini söyle...

İster sev, ister kır.

Korkma kızmam, biliyorsun kırmam kıramam...

Beceremem yani, yapamam.

Hakılısın sonuna kadar....

Sen de sıkılmışsındır.

Her şarkıda düşünülmek, her dakika özlenmek,

Ve hatta sevilmek...

Sıktıysam üzgünüm, affet...

Çok tuttum seni sen git en iyisi.

Yani git ama beni unutma...

Boşver sen unut...Unut da,

Özür dilerim ben unutamayacağım.

Sen git,

Ama sigara içme olur mu? ? 

Allah kahretsin.

Bunca umursamazlığından, bunca yaptığından sonra...

Sen git en iyisi yoksa kırmaya başlayacağım seni.

İnanmıyorsun di mi? 

Ben de...

Ama sen yine de git...

Beddua mı? ? ? 

Ne kadar mutluluk varsa dünyada,

Senin olsun hepsi.

Ben daha ne isterim ki? 

Kahretsin...

Bunca yaptığından sonra

Neden neden hala sen? 

Git diyemeyeceğim biliyorum boşuna heveslendim ben,

Sonbaharda bekledim çiçeklerin açmasını,

Kışın istedim, yazın en sevdiğim meyvayı,

Doğruluğuna kapıldığım yalanlar zinciriydi senin sevdan,

Bile bile sevdim seni...

Yalanlığına inandım, yalanlarına inandım tüm kalbimle,

Gitme derdim veda etseydin! 

Yalanlarını bile özledim,

Hatta rüyalarıma çıkmanı bile...

Yine gel öksüz bırakma uykularımı.

Sen git en iyisi,

Ben burdayım nasıl olsa,

Yani sonsuza dek olmasa da,

Birkaç yüzyıl daha,

Burdayım nasıl olsa...', 'Defalarca ''kal'' dedim gitmek isterken sen... Hata benim, suç benim. Haksızım ve haklısın sonuna dek, Gideceğim dediğinde bırakmalıydım. Affe...', ARRAY['Türk Edebiyatı','Şiir','İnci Bakraç']::text[], 8.5, '{"poet":"İnci Bakraç","poet_slug":"i-nci-bakrac","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/tutsak-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana aksın...', 'bana-aksin-yusuf-ziya-leblebici-2j2i8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir damla gözyaşın  akacaksa eğer

Bırak benim gözlerimden aksın

Ağlaman çare olacaksa eğer

Sen ağlama, gözyaşların benden aksın

Sen söyle, ben dinleyeyim derdini

Yeter ki yıpratma sen kendini

Kalbinin bir parçası say beni

Sen üzülme, dertlerin bana aksın

Saçlarında hissettiğim o çiçekler

Ne olur daha fazla kurumasın

Cenneti gördüğüm o kapkara gözler

Seninle birlikte gözüme aksın', 'Bir damla gözyaşın  akacaksa eğer Bırak benim gözlerimden aksın Ağlaman çare olacaksa eğer Sen ağlama, gözyaşların benden aksın Sen söyle, b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bana-aksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-mustafa-duman-qsho8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dallarına söz bağladığımız ağaç

dökmeye başlayınca yapraklarını

bitmişti...

gideceği yer hanesi boş sanmışsak da değildi

aldığım biletin sensiz bir şehre olduğu

belliydi...

elindeki sıcaklık bir fotoğrafa sığar

ve orada kalır sanmak,

zorda kaldıkça cebindeki aşkı harcamak demeye de gelirdi

istemezdik

bilemezdik de

en yakınken en uzak olmak

biraz gözyaşı ve bir kaç seneymiş demek ki.

(2003)', 'dallarına söz bağladığımız ağaç dökmeye başlayınca yapraklarını bitmişti... gideceği yer hanesi boş sanmışsak da değildi aldığım biletin sen...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Duman']::text[], 8.5, '{"poet":"Mustafa Duman","poet_slug":"mustafa-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrilik-156-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsiz', 'belirsiz-mustafa-ceylan-pi55h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüzgârın önünde kâğıt gibisin

Boş hayâle kandın yerin belirsiz

Bir çöp tenekesi olmuş ki kalbin

Yüzünde, gözünde nurun belirsiz

Gayri demem sana: “Ey sevgili yâr! ”

En mahir saatçi yapamaz ayar

Öfkemin yağmuru başına yağar

Oldun sırılsıklam terin belirsiz

Ruhsuz bir şekilsin, sessiz bir heykel

Dilerim olursun benden daha kel! 

İnsafsız elinde kırılmış cetvel

Sildin sayıları bir’in belirsiz

Kalbimden daha çok gördün cebimi

Susma haydi söyle, gizli sevgini! 

Almanya’ da ki mi, askerde ki mi? 

Bu nasıl aşk, Ferhat-Şirin belirsiz

Gözlerim kör değil, değilim salak

Dersini verecek, dersini felek

Ey çamura düşmüş turşumuş kelek! 

Koyu gölgedesin kirin belirsiz', 'Rüzgârın önünde kâğıt gibisin Boş hayâle kandın yerin belirsiz Bir çöp tenekesi olmuş ki kalbin Yüzünde, gözünde nurun belirsiz Gayri demem ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/belirsiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimki', 'benimki-mustafa-duman-7u1bp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'benimki

beyaz ve bahar bir yastıkta, ''uyanmamak''tı yalnızca

az çıkmış sakalımla gülümsemekti bıyığımın üstünden, uyurken

ne yastıkta bıraktığın o ılık kokun

ne göğsümde kokunla sürdüğün uykun

en çok gözlerim kapalı gözlerini seyretmekti benimki

ellerin bir çiçek demeti, ellerimde dururken

(2002)', 'benimki beyaz ve bahar bir yastıkta, ''uyanmamak''tı yalnızca az çıkmış sakalımla gülümsemekti bıyığımın üstünden, uyurken ne yastıkta bıraktı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Duman']::text[], 8.5, '{"poet":"Mustafa Duman","poet_slug":"mustafa-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdüm mü ne?', 'buyudum-mu-ne-i-nci-bakrac-6sitd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani çocukken,

Annem uyardığı halde,

Her geçişimde,

O eşiğe takılıp düşerdim ya,

Büyüyünce de değişmiyormuş bazı şeyler,

Çünkü senin her gelişinde,

İnatla kabul edişim seni,

Değişmeyen ruhumun kanıtı değil mi? ? 

Ve ne yazık ki farkındayım,

Senin olmuş yüreğimin,

Kendi sözümü bile 

Dinlemediğinin...

...........

En çok eksiksiz uyanmayı özlemiştim galiba,

Acımadan yüreğim,

Bugün ne olacak korkusu olmadan,

Ve gelişini beklemeden uyanmayı..

..........

Günaydın sevgilim! 

Bu sabah acımıyor yüreğim.

Ve artık annem bile istese,

Sana koşmayacak bedenim...', 'Hani çocukken, Annem uyardığı halde, Her geçişimde, O eşiğe takılıp düşerdim ya, Büyüyünce de değişmiyormuş bazı şeyler, Çünkü senin her gel...', ARRAY['Türk Edebiyatı','Şiir','İnci Bakraç']::text[], 8.5, '{"poet":"İnci Bakraç","poet_slug":"i-nci-bakrac","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/buyudum-mu-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baston', 'baston-mustafa-ceylan-u4fpb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yırtık cüzdanımı bostan sanarak

Olgun kiraz gibi allanmayı gör

Yorgun ellerimi baston sanarak

Olur olmaz yerde kullanmayı gör

Elini tutacak bulamazsın sen

Tahtlarda otursan, köşkte gezinsen

Karışsın iç içe acıyla neşen

Her iki yana da sallanmayı gör

Bunca iyilikler gözüne dursun

Şiirim yarana merhemi sürsün

Felek düşünmeden defterin dürsün

Adressiz mektupsun, pullanmayı gör

Güvendiğin dağa karlar yağacak

Düştüğün son ırmak seni boğacak

Gittin ya ufkuma güneş doğacak

Aşkta yaprak yaprak dallanmayı gör

Adını, tadını unutacağım

Ağlayan gözümü kurutacağım

Yeni filizlere gebe toprağım

Aşkla sulanmayı, bellenmeyi gör

Ceylan bastonunu ateşe attı

Bu dertli konuyu burda kapattı

Senden kurtuldu ya şapka çıkardı

Bir kara sevdayla sallanmayı gör', 'Yırtık cüzdanımı bostan sanarak Olgun kiraz gibi allanmayı gör Yorgun ellerimi baston sanarak Olur olmaz yerde kullanmayı gör Elini tutacak ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/baston-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş...', 'arkadas-yusuf-ziya-leblebici-xca8a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugünler de geçer takma arkadaş

Her inişin bir de çıkışı vardır

Dünyaya karamsar bakma arkadaş

Bugünlerin bir de yarını vardır

Elini uzatsan bir tutan olmaz

Bir de bakarsın el uzatan vardır

Sakın düşmeye gör bakan olmaz

Bir bakarsın seninle yatan vardır

Bu dünya hakikat değil arkadaş

Bu cihanda doğru insan da vardır

Onlara ister yar de, ister yoldaş

Doğru yolda seninle yanan vardır', 'Bugünler de geçer takma arkadaş Her inişin bir de çıkışı vardır Dünyaya karamsar bakma arkadaş Bugünlerin bir de yarını vardır Elini uzatsan...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/arkadas-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basit', 'basit-mustafa-ceylan-7zufc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hazırla valizi, çıkalım yola

Gideceğimiz yer, o kadar basit

Öyle dolambaçlı, bilmece değil

Gideceğimiz yer, o kadar basit

İşte şuracıkta anamla babam

Nazlı gelin olman yaptığım çabam

Severek el ele, göz göze akşam

Edeceğimiz yer, o kadar basit

Kokunu duyarım sabah seherde

Bu sebeple düştüm onulmaz derde

Farklı bir ortamda, farklı bir yerde

Biteceğimiz yer, o kadar basit

Güzelsin dedim ya, billah ece''den 

Kaderim ol, emir geldi Yüce’den

Avuç avuç yıldızları geceden

Tutacağımız yer, o kadar basit

İhtiyacım yoktur bir başka tada

Çok şükür erdim ya senle murada

Yıldızlı gecede, serin yaylada

Yatacağımız yer, o kadar basit', 'Hazırla valizi, çıkalım yola Gideceğimiz yer, o kadar basit Öyle dolambaçlı, bilmece değil Gideceğimiz yer, o kadar basit İşte şuracıkta ana...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/basit-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımız Sevda...', 'adimiz-sevda-yusuf-ziya-leblebici-sgrhy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizim adımız sevda

Gönlümüzün aşı

       suyu ve kanı! ..

Bir nefes inerken gırtlaklarımıza

yutkunduğumuz hayattır bu dava.

Kuş gibi hafif sevdalar 

 bizlere mutluluk getirmez.

Biz seveceksek; 

Adam gibi sonuna kadar

mahşere kadar severiz...

Ağaçların yerine

     yüreğimize kazıdığımız,

Ekmek niyetine

     suya bandığımız 

         bir dava bu

bu davanın adı sevda...

Bizim adımız sevda

Biz, resimleri cüzdanımıza değil

     kalbimize çizeriz.

Sevdalımızın gözlerini

     gözlerimize dikeriz...', 'Bizim adımız sevda Gönlümüzün aşı        suyu ve kanı! .. Bir nefes inerken gırtlaklarımıza yutkunduğumuz hayattır bu dava. Kuş gibi hafif s...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adimiz-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr Elinden Bâde İçtim', 'y-r-elinden-b-de-i-ctim-mustafa-ceylan-jvauv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yâr elinden bâde içtim ayıldım

Gerçeklerde geziyorum çok şükür.

Aşk bir deniz, hasret dalga, ben ceviz

Ortasında yüzüyorum çok şükür.

Yâr elinden bâde içtim beş kabtan

İlham aldım çöllerdeki seraptan

Sevda neymiş elimdeki kitaptan

Okudukça yazıyorum çok şükür.

Unutmuştum yalnızlığı, hüzünü

Anımsadım Ceylan diyen sözünü

Bebek kadar masum olan yüzünü

Duvarlara çiziyorum çok şükür.

Yâr elinden bâde içtim n’ ideyim? 

Bir ceylanım hangi dağa gideyim? 

Yalancıyla söyle nasıl edeyim? 

Oyunları bozuyorum çok şükür.

Yâr elinden bâde içtim aşk için

Suçiçeği oluverdim Haliç’ in

Ateş döküp ciğer yakan sevincin

Rüzgârıyla tozuyorum çok şükür.', 'Yâr elinden bâde içtim ayıldım Gerçeklerde geziyorum çok şükür. Aşk bir deniz, hasret dalga, ben ceviz Ortasında yüzüyorum çok şükür. Yâr el...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yar-elinden-bade-ictim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bacak Kadar Boyunla', 'bacak-kadar-boyunla-mustafa-ceylan-jxumv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bacak kadar boyunla

Türlü çeşit huyunla

Akıl ermez oyunla

Fırıldağa dönmüşsün

Dönek, kaypak denilen

Güyâ adam sanılan

Üzerine binilen

Bir kızağa dönmüşsün

Sırtı yerde padişah

Hem eziyet, hem ferah

En sonunda maşallah

Buzağıya dönmüşsün

Bu nasıl aşk, nasıl iş? 

Gözler ateş, dudak kiş

Orta yerden delinmiş

Cıngırdağa dönmüşsün

Yerden yere vurulan

Mahkemeden sorulan

Boşaldıkça kırılan

Bir bardağa dönmüşsün

Aslında sen köteklik

Yaptığın şey yataklık

Evin olsun bataklık

Kurbağaya dönmüşsün', 'Bacak kadar boyunla Türlü çeşit huyunla Akıl ermez oyunla Fırıldağa dönmüşsün Dönek, kaypak denilen Güyâ adam sanılan Üzerine binilen Bir kı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bacak-kadar-boyunla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-mustafa-ceylan-0qyg7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Kardeşim Şenol YAĞAR’ A

Bir gün kulakların çınlarsa eğer

İnan ki adını anmışımdır ben

Yolda yanıp tüten bir duman görsen

Vallahi, billahi yanmışımdır ben

Yokluğu paylaşmak dostluk içindir

Gel de çalıp söyle acımı dindir

Dedimse o yâre: Kalbim senindir

Tatlı sözlerine kanmışımdır ben

Ağlayan, inleyen ud’ un elinde

Hicran şarkıları durur dilinde

Bıraktım kalbimi zalim birinde

Peri padişahı sanmışımdır ben

Üçe böler iken bir sigarayı

Tuttuk yere çaldık geceden ayı

Unutma kardeşim bu Mustafa’ yı

Mutlaka hâyale dalmışımdır ben

			2. Mayıs. 2003', '-Kardeşim Şenol YAĞAR’ A Bir gün kulakların çınlarsa eğer İnan ki adını anmışımdır ben Yolda yanıp tüten bir duman görsen Vallahi, billahi y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutma-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr Sesini Duyduğumda', 'y-r-sesini-duydugumda-mustafa-ceylan-0ekz0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümsüzlük türküsünü duyarım

Yâr sesini duyduğumda inan ki

Gök yüzünü umudumla boyarım

Yâr sesini duyduğumda inan ki

Ab-ı hayat kaynağımsın doğuştan

Senle doğar güneş, senle atar tan

Kurtulurum korkulardan, telâştan

Yâr sesini duyduğumda inan ki

Ay geceyi yıldızlarla bölüşür

Hasret biter ayrılanlar görüşür

Hayâllerim gerçeklere dönüşür

Yâr sesini duyduğumda inan ki

Bakışınla umut yağar her sabah

Gülüşünle ediyorum bak siftah

Karnım doyar, borcum biter demem ah! 

Yâr sesini duyduğumda inan ki

Yüce dağdan çığ misali koparım

Can evimde düğün, dernek yaparım

Piyangodan trilyonu kaparım

Yâr sesini duyduğumda inan ki

Katlanarak mor menekşe nazıma

Bir kulak ver şu inleyen sazıma

Çiçek dolar gönül denen vazoma

Yâr sesini duyduğumda inan ki

“Gecelere hep gözlerin doluyor”

Dudakların dudağımı buluyor

Vallahi bak içim bir hoş oluyor

Yâr sesini duyduğumda inan ki

Ceylan’ ıma kursalar da tunçtan ağ

Aşkın vardır, yol gösteren bir çerağ

Ruh kökünde patlamakta yanardağ

Yâr sesini duyduğumda inan ki', 'Ölümsüzlük türküsünü duyarım Yâr sesini duyduğumda inan ki Gök yüzünü umudumla boyarım Yâr sesini duyduğumda inan ki Ab-ı hayat kaynağımsın ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yar-sesini-duydugumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı', 'olmadi-i-nci-bakrac-t2mem', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Terkettim seni sonunda.

Hiç de bize yakışmayan bi'' ayrılıktı.

Bedenim,

Karşında ağlamamak için hızla uzaklaşırken yanından,

Yüreğim yığılıp kaldı olduğu yere

Görmedin...

Aylardır nasıl da yenik düşmüştüm sana,

Nasıl da görmezlikten gelmiştim.

Yüreğimden çekip sürüklediğin,

Adı ayrılık olan o günde bile,

Tek bi'' söz bekledim senden.

Bi'' gülümseme ya da ''kal'' demeni bekledim.

Demedin...

Sayfalarca mektuplar yazdım sana,

Haketmediğin şiirler...

Karşına geçince dilimin ucunda kilitlenip kalan

Bütün o sözlerin,

Kalemimden nasıl umursuzca çıktığını gör istedim

Adının adımla düğümlendiği satırları,

Oku istedim bi'' kez,

Okumadın...

Dudaklarım susarken,

''Niye yaptın bunu bize'' diyordu gözlerim

Ellerim göğsüne dokunmak,

Avuç içlerim yüreğini hissetmek istiyordu.

Kalbim adınla atıyordu.

''Ayırma bizi'' diye bağırıyordu bakışlarım,

Duymadın...

Şimdi; 

Sen hesapsız sevgilerden uzak,

Ben aşka, sevgiye, sana yasak

Çaresizliğimi gurur zannedip,

Avutuyorum yüreğimi.

Her gün yeniden başlayıp sana,

Seni yeniden bitiriyorum.

Bu sabah ta dön istedim bana.

Sana yeniden başlamak,

Ve hiç bitirmemek için...

Dönmedin....', 'Terkettim seni sonunda. Hiç de bize yakışmayan bi'' ayrılıktı. Bedenim, Karşında ağlamamak için hızla uzaklaşırken yanından, Yüreğim yığılıp ...', ARRAY['Türk Edebiyatı','Şiir','İnci Bakraç']::text[], 8.5, '{"poet":"İnci Bakraç","poet_slug":"i-nci-bakrac","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/olmadi-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(GÜLCE-Buluşma) Abondone', 'gulce-bulusma-abondone-mustafa-ceylan-v8vs3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mâtem tülbentini çekmiş yüzüne, 

.................İki ateş arasında bu zaman

Bayati şarkılar gramofonda, 

.................Düşen yapraklarda özlemin ağlar

Şimdi en uzak sahillerde şavkın, 

.................Hüzünlü gözlerindir hatırlanan

Nisan menekşesi saksılarda sen

.................Saksılar ki yaban pençerelerde...

Niçin? 

Tutamam ellerinden, bakamam gözlerine

Portakal tenini koklayamam, n''ideyim? 

N''ideyim sensiz bu ömrü, bu akıp giden saatleri

En iyisi mi, kahrolası bu takvimi

Parça parça edeyim? 

Çağırma boşuna sancılı seherlere

Çağırma beni ey serçe kanatlım,

Ey nazar boncuğum, omzumdaki güvercin...

Çıkamam, çıkıp gelemem iyi bil

Kaçak mevsimlerin kaçak yağmurunda saçların

Başını dik tutsan da biliyorum

Kan ağlar için...

Ben senin karşına nasıl çıkarım? 

Böyle köşe bucak kaçtıktan sonra

Büyük zaferini söyler kahkahan

Başıma bin belâ açtıktan sonra

Teslim bayrağını çektim kaleme

Gönlümü verdin de dertle eleme

Şimdi rezil oldum cümle âleme

Sen de buralardan göçtükten sonra

Cümbüşlü sabahlarda düş kurdum hep yarım yamalak

Gerçeğin yelkenlisi kaçkez battı sularımda

Kaç kez aşkında kürek mahkumu 

...........................Tayfa olup boğuldum

Yorgun akşamlara yürüdüm gözlerinden

..........................O gözlerde kayboldum

Dilin alev alev öfkeyle nefret

Oysa yüreğinde gül açar cennet

Bu kara sevdama edersin hayret

Aşkı tırpan tırpan biçtikten sonra

Şiirde imgeydim, fallarda sırdım

Yapıştı mindere sonunda sırtım

Kurşun yarasını hasretle sardım

Ayrılık tasından içtikten sonra

Mâtem tülbentini çekmiş yüzüne, 

.................İki ateş arasında bu zaman

Bayati şarkılar gramofonda, 

.................Düşen yapraklarda özlemin ağlar

Sonbaharı yaşıyorum yokluğunda

Ceylan’ ım boş yere demeki o ne? 

Nasılmış öğrendin bu abondone

Bülbüller kan ağlar, kan ağlar yine

Aşkı tohum tohum saçtıktan sonra.', 'Mâtem tülbentini çekmiş yüzüne,  .................İki ateş arasında bu zaman Bayati şarkılar gramofonda,  .................Düşen yapraklarda...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/gulce-bulusma-abondone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(GÜLCE-Buluşma) Abaküs', 'gulce-bulusma-abakus-mustafa-ceylan-pkon4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman turnusol kâğıdı değil ki gülüm

Geçip giden sudur çağlayan

Deli kuşları havalandırmaya devam et hele

Göklerin dibi bucağı yok ki zaten

Yitirme umudunu asla

.............Erime şeker olup, dayan, diren biraz..

Şiirin dili çözülsün,

Yazılmamış kelimelerle yapılsın tasvirin

Söylenmemiş imge çiçek açsın gözbebeklerin gibi 

Bırak kendi seyrine saatleri

Bırak yeniden rüzgâr ıslığında tebessüm etsin

.............Gönül bahçemizde, ağaçlar içinden

................Sana bakan çifte kiraz...

Gider...

Her şey gider sen gittiğinde,

Gitmeyenlerin pas tutan dilinde yazgı

Ayırmadım gidenle gitmeyeni

................Bölmedim, parçalamadım mevsimleri

....................Seni beklerken bu yaz...

Topla, çıkart, çarp, böl; ne yaparsan yap

Altmıştan öteye yol gitmiyor ki.

Parmakla, takvimle yapsan da hesap

Boğazın kırk boğum, dil gitmiyor ki

Çocukluk ve gençlik kanatlı kuştu

Farkına varmadan nasıl da uçtu? 

Bakmayın çiçeğe kökler tutuştu	

Su yerde akıyor, dal gitmiyor ki

Ceviz kadar akıl, tüp kadar mide

Eğdiler kantarı şimdi gitgide

Ölmüş bal arısı kalmış petek de

Kovan darma duman, bal gitmiyor ki

Renkli boncukları saydık kaç kere

Söyle de bilelim, yüz, bin, on nere? 

Cümle varlıkların sevdiği yâre

Mektubun içinde gül gitmiyor ki

Kader, alnımıza çizilen çizgi

Bu çizgide gizli ömürlük yazgı

Hep geçim derdiyle söyledik ezgi

Şu sazın göğsüne el gitmiyor ki

Mevlâ bir can vermiş yeşil yaprağa

Nice sır gizlemiş denize, dağa

Bir cami önünden kara toprağa

Giden yalnız insan, sal gitmiyor ki

Ceylan’ ım ayrılma bir’ in biriyle

Üçe bakma sakın, gitme ikiyle

Bütün gönüllerde aşk kibritiyle

Ocak yanar amma kül gitmiyor ki', 'Zaman turnusol kâğıdı değil ki gülüm Geçip giden sudur çağlayan Deli kuşları havalandırmaya devam et hele Göklerin dibi bucağı yok ki zaten ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gulce-bulusma-abakus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevirdim Başımı Sol Yanıma', 'cevirdim-basimi-sol-yanima-melih-coskun-vk90e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çevirdim başımı sol yanıma 

Gülümsüyordu duvarımda

En yakışıklı fotoğrafı devrimin 

Bir sonbahar şafağında doğuşumdandır belki 

Böyle dişlerimi sıkarak okumam bütün türküleri 

Rüzgarsız göçen her kahramanın 

Aydınlık izi düşer karanlık sokaklara 

Ve her sesin yankısı vardır 

Her düşüşün yarattığı bir deprem vardır mutlaka 

Martın, Eylülün çocuklarıdır onlar 

Kimse sormamıştır onlara

Karartırken gökyüzünün mavisini

Çalarken beyazını

Kanla, emekle yaratılmış cennetlerin

Ve kanunları yapanlar 

Hiç şiir okumamışlardır belki hayatlarında 

Yüceliği üzerine insanlığın 

Yaratmanın ve yaratılmanın 

Yani onuru üzerine insan olmanın

Kanunları yapanlar güçlüler midir o zaman

Türküleri yaratanlar kadar

Halkının kaderini kanla yazarken tarih 

Yumruklaşan bir heyecanla 

Kırılıyor paslı zincirleri sessizliğin

Koşuyor güzel kızları 

Ve yakışıklı çocukları devrimin

Düşüşlerinde depremler saklıyorlar 

Ve güneşten ödünç almışçasına 

Alev gözlerini 

Öyle güzel bakıyorlar hala 

O alev gözleriyle 

Gülümsüyor hala duvarımda 

En yakışıklı fotoğrafı devrimin

Bir sonbahar şafağında doğmuş olduğumdan mıdır bilinmez 

Ne zaman bir marş dinlesem sıkıyorum dişlerimi...', 'Çevirdim başımı sol yanıma  Gülümsüyordu duvarımda En yakışıklı fotoğrafı devrimin  Bir sonbahar şafağında doğuşumdandır belki  Böyle dişler...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/cevirdim-basimi-sol-yanima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(GÜLCE-Buluşma) A a! A a! ! !', 'gulce-bulusma-a-a-a-a-mustafa-ceylan-bzjut', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırılan, tuz buz olan aynaların

Her bir zerresinde kahkaham durur,

Işığın raksıyla yansır da sesim

Sen duymazsın ki

.........Duyamazsın ki

Aklınca dikine giden karıncasın işte

Bakarım cam kırıklarından manzaraya

Bir tebessüm, bin buse yağar içimden

Şaşırır kalırım bazen olmuşa, olacağa

Çocuk olur, bile bile aldanırım

Kanarım, inanırım zamana

En çok da sana

Ve

Düşer dilimden harfler, yuvarlanır şiir ikindisine

Der ki:

Koca fili bir karınca sırtlamış

Orta yerde döndürüyor A a! a! 

Kara gözlüm bunca yılı yok saymış

Güya beni kandırıyor A a! a! 

Yaşıyorum gözlerimde sel ile

Umudumu silip geçti el ile

Saçlarından eksilmeyen yel ile

Işığımı söndürüyor A a! a! 

Nerden aldım bu başıma belâmı? 

Düşünmeden kesiverdi selâmı

Ağızlarda çürütülmüş kelâmı

Lâstik gibi sündürüyor A a! a! 

Nasıl düştüm uçuruma, tuzağa? 

Kurulup ta hasret adlı kızağa

Umutları gitsin diye uzağa

Gemileri bindiriyor A a! a! 

Beraberce söylüyorken şarkıyı

Sebep buldu para, pulu, takıyı

Gelme diye kapatarak kapıyı

Perdeleri indiriyor A a! a! 

Bu Ceylan’ ım sorar bir gün elbette

Geze dursun bu senede gurbette

El âlemle nazlı gülüm sohbette

Acıları dindiriyor A a! a! 

*

Nisan 2003 / Ocak 2010', 'Kırılan, tuz buz olan aynaların Her bir zerresinde kahkaham durur, Işığın raksıyla yansır da sesim Sen duymazsın ki .........Duyamazsın ki A...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gulce-bulusma-a-a-a-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Güzele', 'zalim-guzele-mustafa-ceylan-ypagz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Böyle boynu bükük bırakıp beni

Bir veda etmeden gittin güzelim.

Sevgi denizinin kıyısındaydım 

Kader girdabına ittin güzelim.

Çocuksu halini öyle özledim,

Aşkımı sır gibi tuttum gizledim,

Ferhatça dağlarda yolun gözledim

Dağdan dağa beni, attın güzelim.

Ağlayan gözümü kuruttum sanma,

Tenini, kokunu unuttum sanma,

Bu deli yüreği avuttum sanma

Sanki üç kuruşa sattın güzelim.

Hasret dağlarının yeli olurum,

Gönül sazlarının teli olurum,

Duymasam sesini deli olurum

Sağırlar içine kattın güzelim.

Değerdi bakışın elli seneme,

Hasret ateşini yaktın sineme

Seviyor mu diye asla deneme? ! 

Ceylan gözlerimde tüttün güzelim.', 'Böyle boynu bükük bırakıp beni Bir veda etmeden gittin güzelim. Sevgi denizinin kıyısındaydım  Kader girdabına ittin güzelim. Çocuksu halini...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zalim-guzele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemim Seni Yazar', 'kalemim-seni-yazar-mustafa-ceylan-hyw65', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaçıncı  ayrılışımız bilmiyorum

Ama bu sefer farklı oldu.

Ne kavga, ne öfke vardı aramızda

Sanki, salkım söğüt türküsüydü sularda

Sanki, bitimsiz rüyaydı uykularda...

Kaçıncı veda edişimizdi bu? 

Yaban güllerin haykırışı vardı masada

Bir gül rahatsız etti ilk defa beni

Öfke saçıyordu rengi vazodan...

Ve o gül kurulup kalmışken oracıkta

Bir de bana, bir de can evime 

Uzanmışken hoyratça; 

Uğurluyordun beni allayıp pullayıp; 

Dilerim düşersin dengine! 

Yüreğin var ya yüreğin

Dilini ağır cezaya verecek biliyorum.

Gönderdin bir meçhule, postaladın 

Çok şükür bu yaralı ceylanı,

Bu söz dinlemez sevdanı...

Gözün aydın olsun! 

Mutluluklar diliyorum! 

Benden kurtulabilirsin, 

Kurtuldun hem de çok kolay.

Ama, ya kalemimden,

Ya mısralarımdan kurtulman olanaksız

Hep seni ve aşkımızı yazacağım...

Evet param yoktu, varlığım

Bana bile yetmiyordu.

Ancak, gönlüm tıka basa doluydu

Seninle sende kalsaydım

Deprem mi olurdu?', 'Kaçıncı  ayrılışımız bilmiyorum Ama bu sefer farklı oldu. Ne kavga, ne öfke vardı aramızda Sanki, salkım söğüt türküsüydü sularda Sanki, bit...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kalemim-seni-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-mustafa-ceylan-lvkz8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Böyle bir ayrılığı yaşamadım ben,

Ağlasam ağlayamam, gülsem gülemem.

Kendi ellerinle gömüp mezara

Bir de buse kondurman yok mu? 

Asıl deli eden bu....

Nice ayrılık yaşadım, nice hüzün

Hepsi de ölümden beterdi inan...

Bir anlam veremiyorum seninkisine,

İzah et bana...

Oysa, delicesine aşıktım sana

Oysa, silip süpürmüştüm onca maziyi

Ve ellerimde tutuyordum umutla

Muhteşem geleceği...

Şimdi ne oldu? 

Kim girdi, kimler girdi aramıza? 

Anlat bana...

Şimdi, ne yapmam gerek? 

Onu dahi bilmiyorum.

Kocaman bir kent düştü üstüme

“İmdat! İmdat! ! ! ” diyorum...

Şimdi kime diyeyim “sarı civcivim”? 

Şimdi hangi limana sığınayım? 

Kahrolası geceleri yıldız yıldız

Yalnızlığıma mı anlatayım? 

Söyle bana! ...

Kim girecek koynuma? 

Kim atılacak boynuma? 

Kim kavga yapacak geceler boyu? 

Çaresizim, çaresiz...', 'Böyle bir ayrılığı yaşamadım ben, Ağlasam ağlayamam, gülsem gülemem. Kendi ellerinle gömüp mezara Bir de buse kondurman yok mu?  Asıl deli e...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/veda-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Ultimatom', 'sevgiliye-ultimatom-mustafa-ceylan-rplc1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Operasyon yapacağım gelmezsen

Harp gemilerime emir verdim

Bulunduğun sahilleri bombalayacağım

Gelip beni sevmezsen...

Biliyorum kapalı kapılar ardındasın,

Biliyorum gönlümün haritasındasın,

Füze duygularımı ateşledim işte

Hedefimin tam ortasındasın

Gülmezsen...

Sana tanıdığım son süreydi bu

Gerisini sen düşün, sorumluluk senin.

Günah gitti benden

Farkında olamazsın hiç bir şeyin

Sevdiğimi bilmezsen...

Operasyon yapacağım, operasyon

Bir ordu kurmuşum şiirlerimden,

Gücün yetmez, durduramazsın

Uğraşma, direnme boşuna...! 

Öpücük alamazsın benden

Öpmezsen...

			21. 02. 2003', 'Operasyon yapacağım gelmezsen Harp gemilerime emir verdim Bulunduğun sahilleri bombalayacağım Gelip beni sevmezsen... Biliyorum kapalı kapıl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevgiliye-ultimatom-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Üstüne', 'gul-ustune-mustafa-ceylan-95qs7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çarşafın, yorganın, perden

Gül üstüne güller açıyor.

Fakirim, yoksulum; lâkin yüreğim

Gül üstüne güller açıyor.

Bitmesin gece kollarında,

Tükensin ömrüm yollarında,

Baharı yaşarken senin yanında

Gül üstüne güller açıyor.

Çağırır gözlerin beni uzaktan,

Kurtarır ipek tenin büyük tuzaktan,

İnan ki seni sevdiğim zaman

Gül üstüne güller açıyor.

Uykun, uykun karanfil uykusu

Duygun, duygun ırmaklar dolusu,

Kalbim, kalbim seninle doğrusu

Gül üstüne güller açıyor.

Beste: Mevlüde BUDAK', 'Çarşafın, yorganın, perden Gül üstüne güller açıyor. Fakirim, yoksulum; lâkin yüreğim Gül üstüne güller açıyor. Bitmesin gece kollarında, Tü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gul-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Güneş', 'ask-ve-gunes-hasan-arican-thgzn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başlangıçsız olur mu hiç bir şey

Elbette her güzel şeyinde var bir başlangıcı

Güneşin doğuşu bir güzel başlangıç 

Ve

Tüm güzelliklerin göstergesidir Gülün ve çiçeğin açması

Bu güzellikler içinde bir aşkın başlaması tamamlar güzellikleri

Aşk ortaya çıkmışsa vardır birde sevgili

Aşk varsa mutluluk ve heyecanda beraberindedir.

Bir sis çöker bütün güzelliklerin üzerine güneşin batışı ile

Aşk ne türlü yaşanırsa (karşılıklı-karşılıksız)  yaşansın

Her insan görecektir güneşin batımını; 

O insan, güzellikleri yaşasa da yaşamasa da...

Aşkı yaşadıktan sonra güneşin batımına erişmiş olanlara ne mutlu; 

Karşılıksız olsa bile.

Aşk yaşamamış olanlar çiçek bahçesinde doğmuş olsalar dahi maalesef güneşleri doğmadan batmıştır; 

Güneşleri hiç doğmamıştır.', 'Başlangıçsız olur mu hiç bir şey Elbette her güzel şeyinde var bir başlangıcı Güneşin doğuşu bir güzel başlangıç  Ve Tüm güzelliklerin göste...', ARRAY['Türk Edebiyatı','Şiir','Hasan Arıcan']::text[], 8.5, '{"poet":"Hasan Arıcan","poet_slug":"hasan-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-ve-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun Sonu / Uçurum...', 'yolun-sonu-ucurum-cigdem-agbulak-gjuwk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen, evet sen sanma başkasına seslendiğimi. Sana, aşık olduğum adama tüm sözüm. Seni  görmediğim zamanlardan beri, hani hiç bilmediğim tatmadığım o günlerden, sözcüklerimin henüz senin için olmadığı karanlıklardan beri tanıyorum. 

Görmediğin bir uçurum kenarında ayaklarım

Gözlerim bilmediğim uzaklara bakıyor

Kapatıp sessizce suretimi

Sesleri dinliyorum

Sensiz sanma beni

Ellerinden tutuyorum

Sıcak

Yüzüne dokunuyorum

Traş olmamışsın

Olma

Sen uyurken bilmediğim uzaklarda

Ben 

Kimseyi duymuyorum

Ellerim üşüyor

Rüzgar sert, acımasız

Uçurum çağırıyor yanına

Açıyorum suretimi

Sensizliğe yanıyorum

Yanmalara doyamamak

Ve

Çağırsa da bilmediğim ruhlar 

Gidememek

Yorgun olmamalıyım

Hala atabilirim

Hala bir adım

Hala...

Susturup kurduğum ve kuracağım tüm cümleleri, seni dinliyorum. Nefes alıp verişlerin, kalp atışlarıma can veriyor. Gözlerin kapalı, kim bilir hangi alemin, hangi bilmediğim alemin tam ortasındasın.

Saçlarına dokunuyorum

Uzamışlar ne zamandır

Ne zamandır değmemiş

Yüzüne mutluluğun baharı

Kapatıyorum suretimi

Ben oluyorum

Daha zor sensizliğe yummak

Ben kolayı seçiyorum...

Taşlar yuvarlanıyor altımdan, uçurum çağırıyor. Duymamalıyım deyip, denizin çığlıklarına karışıyorum. Bir gemi geçiyor, görmüyorum. Görmüyorum demirlerine yaslanmış kadını, içtiği sigaranın dumanını, saçlarının ıslanışını. Denize bakmadığını, bakamadığını. Sevdasını bir direğin tepesine çekip bir bayrak gibi, dalgalanışını seyrettiğini, görmüyorum, bilmiyorum usulca ağladığını.

Deniz

Saydamlığı ile içine alıyor

Kendimi hissediyorum

Bir bebeğin gülümsemesi doluyor avuçlarıma

Sen oluyorum

Seni bensiz yaşatamayacağım

Biliyorum

Bir balık geçiyor içimden

Şaşırıyorum

Kimsesizliğime dokunuyor

Kimsesizliğime ağlıyor

Bir kolu kopmuş denizyıldızı

Susup izliyorum...

Açıyorum gözlerimi

Göz kapaklarım inatçı

Kamaşıyor bakamıyorum

Yalnız bir ağaç gibi dayadığım sırtımı

O deniz feneri hala diyor

Hala bir adım atma şansın var

Yüzyıllardır buradayım

Senin hala... 

Yapamam diyorum olmaz, duymamam gerek deyip, bir martının kanadına takılıyorum. Bir bulut geçiyor önümden, bırakıveriyorum kendimi içine. Yumuşak, sessiz bir düşüş. Sanki hayata, sevdaya, sana tutunuyorum. Yüzüm sesine değiyor, gülümsüyorum. Düşüşüm hızlanıyor, sen gidiyorsun, martım ağlıyor. 

Olmayacak böyle

Güneşim saklanıyor

Kapatıyorum bu alemi

Dönüyorum sana

Senin olmadığın zamanlara

Sensiz olduğum 

Yanmadığım

Yanamadığım zamanlara

Bir kedinin peşi sıra

Yürüdüğüm taş yollara

Yollar ki sonu hep uçurum

Ve

Buradayım

İşte tam sonunda yolun

Bir adım atma şansım var hala, ya sevdanın yangınına ya da sonsuz düşüşe. Korkuyorum başımı çevirmekten, arkamda birikmiş karanlık ürkütüyor içimdeki çocuğu. Seslerini duyuyorum, biliyorum beni almak için çırpınıyor içine. Aslında siz benim her şeyimsiniz, görüyorum. Ama her şeyime elimi uzatamıyorum. 

Uzak yolların

Zalim sevdası

İçim acıyor

Ben duruyorum

Kendimi sessizce bırakıyorum

Huzur deniz de biliyorum...

Sensizliğin ne demek olduğunu şimdi daha iyi anlıyorum. Fark ediyorum ki, sensizlik diye bir şey yok aslında, seni bana katalı kendimi bensiz bırakmışım bu uçurum kenarında. Sen neysen o olmuşum. Yalan demişsin yalan, sevda demişsin sevda, ölüm demişsin ölüm olmuşum köhnemiş yüreklere. Ben sen olalı, benim ölümüm olmuşum az biraz da sen ben olamamışsın yıllar boyunca.

Ayak izlerimi arkada bırakıp ta yürüdüm yolları

Tek başıma belki

Belki hala sevdalı...

Korkularımın yakalarından tutup silkiyorum artık. Artık başımı dimdik tutup, gözlerinin içine baka baka git diyebiliyorum. Ben beni, sana armağan ettim bebeğim, sevdalı yüreğimden yeni bir ben yaratıyorum...

06.04.2004 / 12:08', 'Sen, evet sen sanma başkasına seslendiğimi. Sana, aşık olduğum adama tüm sözüm. Seni  görmediğim zamanlardan beri, hani hiç bilmediğim tatma...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Ağbulak']::text[], 8.5, '{"poet":"Çiğdem Ağbulak","poet_slug":"cigdem-agbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/yolun-sonu-ucurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Üşüyor', 'bahar-usuyor-hasan-bahadir-ewzzb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'son durağı da uğurladım gözlerimle

sıhiye''den geçiyorum şimdi

sevdiğim yüreğinden geçer gibi

sabahın berrak havası eksoz dumanına bulanmış

cadde sokak cümle insan,telaş,ıslanmış

kiminin ekmek parası

kiminde irfan tasası

bir de soğuk

yağmursa göz süzüyor ankaramın üzerine şimdi

kömür sinmiş soluklar uçuşur oldu etrafta

gökyüzü tutuşmuyor kaç zamandır

yıldızlar düşmüyor

kurşun yüzüyor semâsında kentimin

bahar gözlerimin önünde üşüyor', 'son durağı da uğurladım gözlerimle sıhiye''den geçiyorum şimdi sevdiğim yüreğinden geçer gibi sabahın berrak havası eksoz dumanına bulanmış c...', ARRAY['Türk Edebiyatı','Şiir','Hasan Bahadır']::text[], 8.5, '{"poet":"Hasan Bahadır","poet_slug":"hasan-bahadir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bahar-usuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paşa Gönlüm', 'pasa-gonlum-mustafa-ceylan-b5il6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Paşa gönlüm coştu yine,

Oluruna gitmiyor olayların

Meydan okuyorum zamana işte

Ne mi yapıyorum? 

Dinleyin hele! ..

Paşa gönlüm coştu yine,

Banka kasalarını yoksullara

Fırınları verdim açlara...

Yolda bir ceylan gördüm

Kalbimi bağladım zeytin saçlara.

Dağlar boynunu büktü,

Okyanuslar diz çöktü

Bulutlar şapka çıkardı aşkıma...

Ceylan gitti, ben gittim

Peşindeyim, eridim...

Paşa gönlüm coştu yine,

Körlerin açtım gözlerini

Fırlattılar bastonları,

Doldurdular bostanları...

Sağırların açtım kulaklarını

Misket oynadık o an...

Elsizlere el, ayaksızlara ayak

Yurtsuzlara ev, yayanlara uçak

Her ne istiyorsam yaptım işte...

Paşa gönlüm coştu yine,

Bütün mağazalarda her şey bedava.

Kıyma alabilene bin dolar üste,

Karanfil kokuyor rüzgâr

Mutluluk dağıtıyor hava...

Yok ettim geceleri, boşalttım zindanları

Bir çocuğun gülücüğüne verdim cümle yılları...

Pazarlar kurdum, parasız her şey

Meyhanelerde avantadan mey,

Hey ki hey! Hey ki heyy! ! ! 

Paşa gönlüm coştu yine,

Nuh’ un gemisine benziyorum

Sonsuzluklarda geziniyorum...

Borsayı, lotoyu, totoyu kaldırdım

Herkes insan ya, herkes şanslı artık

Yok bundan sonra

Yok diyorum yok! .. Hasret, ayrılık! ..

Silâhları topladım attım denize

Gül verdim ellere...

Öfkeyi, nefreti, kini sildim, süpürdüm

Güneşe bile öğrettim şarkı söylemesini

Onun da tuttum kulağından

Bendeki bana götürdüm...

Paşa gönlüm coştu yine,

Beton yığını şehirleri çiçekle donattım,

Tarlalar buğday, başak...

Gel be dostum, gel, sen de gel! 

Şu işe bak!', 'Paşa gönlüm coştu yine, Oluruna gitmiyor olayların Meydan okuyorum zamana işte Ne mi yapıyorum?  Dinleyin hele! .. Paşa gönlüm coştu yine, B...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/pasa-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerimde Ayışığı', 'ellerimde-ayisigi-mustafa-ceylan-glqwe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün harmanında savrulmuşum ben

Gün yanığı yüzüme bakın da görün

Ateşler içinde kavrulmuşum ben

Suların uykusuna verin de görün...

Pembeler karanın en yasak aşkı

Ressam fırçasını sallayıp gider.

Tutmak elimde değildir zamanı

Postacı mektubu pullayıp gider...

Bir gülün sevdası kefen biçiyor

Ölmek istiyorum, lâkin ne mümkün.

Gecenin koynundan ses verir sesim

Bakış kurşunuyla vurulur dün, bugün.

Pınarların şırıltısı hüznüme gebe

İçimde tayfunlar oynar körebe...

Kalbim son ağrısını çekiyor işte

Bir saniye içine girin de görün...

Ben, yazılmamış şiirlerin aşığı,

Ben, yorgun duvarların sarmaşığı

Anlamak isterseniz, bilmek, öğrenmek

Gelirim düşlerinize bekleyin bir gün

Saçlarımda çiğ, ellerimde ay ışığı...', 'Gün harmanında savrulmuşum ben Gün yanığı yüzüme bakın da görün Ateşler içinde kavrulmuşum ben Suların uykusuna verin de görün... Pembeler k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ellerimde-ayisigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimi tut', 'elimi-tut-zafer-zengin-etnika-swr3o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimi 

tut

ilk

fırsat da

Beni

sahipsiz

bırakma

Sevdaya 

nerden

gidilir

bilemem

kaybolmayayım

yolunda...

Sana yakınken

Uzak olmayı yaşadımya

Ne desem kendime

Aklım almıyor

Şans kapıma uğramayı kesmiş

Gülümsemem tükeniyor

Yokluğunda

Sen yaşlarda

Dumanlar tüterdi başımda

Beni anlamasanda

Aynı yaştayız hala

Gülüp gitme ne olur

Sevda yollarını kapatma

Başka isimleri anma

Yalnız kalınca

Ağladığın sahili anlatmıştın bana

Ben de ağlardım yanında

Gülme koca adama

Son gördüğüm ışık sendin

Şimdi resmine bakıp

seni merak ediyorum sadece

Uyurken düşlerin

Uyurken ellerin nerede

Çatlatıp gülme koca adama

Söyle...

Sevgili tutmaz ellerim..Utangaç dilerim..sana sadece şiirler dizerim...

Seni seviyorum dememiş bir şairin..kendine saklayamadığı sözlerdir bunlar

Bir ucunda yar...Desem mi! 

7 Nisan 2004  '' İçimin Kitabı ''', 'Elimi  tut ilk fırsat da Beni sahipsiz bırakma Sevdaya  nerden gidilir bilemem kaybolmayayım yolunda... Sana yakınken Uzak olmayı yaşadımya ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/elimi-tut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkeden Terkedilendir Aslında', 'terkeden-terkedilendir-aslinda-nal-n-yildiz-s6zei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni uyurken bırakıp çıktım

Biraz içim acıdı o kadar…

Çok şey değişecekti konuşsaydık,

Sonra yine aynı olmak için değişecekti.

Seni uyurken bırakıp çıktım

Yapacak bir şey yok! 

Mutsuzum,

Eksiğim,

Terkedilmiş gibiyim

Hepsi o kadar…

Geceleyin 

Geçip giden gemiler gibi 

Sularda 

İzim yok

Bütün numaralarımdan 

Kalıcı olarak taşındım. 

Adresim sürgün…

Seni ben öptüm kalbinden 

Geçti sabahlar', 'Seni uyurken bırakıp çıktım Biraz içim acıdı o kadar… Çok şey değişecekti konuşsaydık, Sonra yine aynı olmak için değişecekti. Seni uyurken ...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/terkeden-terkedilendir-aslinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Siyah', 'hep-siyah-nal-n-yildiz-6ztuq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pişmanlık,

Bencilliğimden aldığım tat.

“Bile bile lâdes” demenin çekici yanı

Aynı şanslar yine tanınsa,

Aynı renge oynayacağımı 

Bildiğim kumar.', 'Pişmanlık, Bencilliğimden aldığım tat. “Bile bile lâdes” demenin çekici yanı Aynı şanslar yine tanınsa, Aynı renge oynayacağımı  Bildiğim ku...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hep-siyah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tersakan Dereyi İnekler İçti', 'tersakan-dereyi-i-nekler-i-cti-nal-n-yildiz-sxjxw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tersakan derede yıkanır

Masalları olmayan çocuklar

Kuşları kekliktir; 

Kak gubarak, kalk gubarak…

Tersakan derede

Kurbağaları yeşil gıdılarından

Öpmek makbûldür; 

Kak gudurak, kalk gudurak…', 'Tersakan derede yıkanır Masalları olmayan çocuklar Kuşları kekliktir;  Kak gubarak, kalk gubarak… Tersakan derede Kurbağaları yeşil gıdıları...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tersakan-dereyi-inekler-icti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-erdem-demirkol-9aawl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar çok yerdeysen,

O kadar hayatın içindesin.

Ne kadar çok hayattaysan,

O kadar çok gözdesin.

Ne kadar çok ayaktaysan,

O kadar çok eldesin.

Ne kadar çok zamanın içindeysen,

O kadar çok zamana hakimsin.

Ne kadar çok ilgiliysen,

O kadar çok ilgilenilirsin.

Kıyıda köşede kalmışsan,

Ve bıkkın, yorgunsan hayattan,

Herkes habersiz ve ilgisizdir varlığına.

İnan! Gelmezsin kimsenin umuruna.

Ve yarimin söylediği kadardır aşk:

Saklama tükenir diye duygularını.

Çünkü yoktur aşkın miktarı.

Bunu yaşarsan, seversen bilirsin.

Ne kadar çok seversen,

O kadar çok sevilirsin.

(20.02.2004-Cevizli-İST.-saat:01.00)', 'Ne kadar çok yerdeysen, O kadar hayatın içindesin. Ne kadar çok hayattaysan, O kadar çok gözdesin. Ne kadar çok ayaktaysan, O kadar çok elde...', ARRAY['Türk Edebiyatı','Şiir','Erdem Demirkol']::text[], 8.5, '{"poet":"Erdem Demirkol","poet_slug":"erdem-demirkol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayata-dair-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansızlık', 'i-mkansizlik-gok-tengri-dm0q9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk zaten imkansızlıktır

Olanaksızlığı yapılabilire çevirmektir aşk.

Benim için aşk gökyüzünden tek tek toplayıp yıldızları

Ve en renkli gökkuşağına bezeyip onları

Sunmaktır sana

Ve sen buna imkansızlık diyorsun

Aşk zaten imkansızlıktır be gülüm

Anlamıyorsun..

2Aralık2003  11.51', 'Aşk zaten imkansızlıktır Olanaksızlığı yapılabilire çevirmektir aşk. Benim için aşk gökyüzünden tek tek toplayıp yıldızları Ve en renkli gök...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/imkansizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gibi*', 'gibi-kubilay-enginol-7ecjy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi seninle sevişmek vardı

Üzüm yer gibi

Buğusunda yıkanmak üzümün

Mutluluk yağmuruna yakalanmış gibi

Şimdi seni yudumlamak vardı

Şerbet gibi rakı gibi

Buğusunda yakalamak bardağın

Yağmur ormanlarında görmüş gibi

Şimdi seni sevmek vardı

Toprak gibi su gibi

Yüreğinde göllenmek vardı

Sevgi gibi aşk gibi

Seni şimdi hatırlamak vardı

Su gibi hayal gibi', 'Şimdi seninle sevişmek vardı Üzüm yer gibi Buğusunda yıkanmak üzümün Mutluluk yağmuruna yakalanmış gibi Şimdi seni yudumlamak vardı Şerbet g...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gibi-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hercaî', 'herca-nal-n-yildiz-go0tp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Prag''da

Yabancı bir yelin

Uçuşturduğu 

Sonbahar

Ne kadar tanıdık

Ellerin

Çingene bir kemana

Uyanır mı

Büyür mü 

Kedi gözlerin

Sustuğunda çıtırdayan

Bir mevsim sesin

Sevgilim

Seni yedi iklim, dört kıta sevmekteyim', 'Prag''da Yabancı bir yelin Uçuşturduğu  Sonbahar Ne kadar tanıdık Ellerin Çingene bir kemana Uyanır mı Büyür mü  Kedi gözlerin Sustuğunda çıt...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hercai-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OkuN UcUnDaKi GeRçEk', 'okun-ucundaki-gercek-mine-ozdemirtas-nss05', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'o

Son 

Sorguyu

Sorguluyor

Olmalı ki; yargıçlar

Salonda  bir sessizlik var

sahne bize mazi’ yi hatırlatmalı aslında....A

Duman   işaretleri;  artık  susmuş   rolü...........F

Yapsalar   ve    duvarlara  asılı   sanılsa..................F

Bile, özel  itina ile    biletilmiş      kılıçlar..........................E

İnsan   etine  girmek  için  o sivri   uçlar.................................T

Nasılsa; geçerli  birer  bahane  bulurlar........................................B

Merakım o dur ki;  birleşecek   olanlar................................................İ

Gerdek  Öncesi;  imamın  huzuruna mı.......................................................Z

Yoksa  papazın huzuruna mı çıkacaklar...............................................................İ  

Neyse ne aman. Elbet bir çare  bulurlar.......................................................K

Madem ki, başkan Erdoğan buyurdular.................................................I

O halde çalmak zorunda artık   davullar.........................................B

Tam burun ucumuza    konuşlandırılırsa..................................R

Sinekler; kaşındıracaktır elbet   larvalar...........................I

Ama, kimin umurunda ola ki bu ihtimal..................S

El uzatanın; eli, dil uzatanınsa dili yanar........... I

Herkes  kesesinden yiyip içip  oynasın... M

Satılan  ada da şenlik var.

Esaretin yeni  adına-

referandum

diyorlar

diyor

o

02/04/2004', 'o Son  Sorguyu Sorguluyor Olmalı ki; yargıçlar Salonda  bir sessizlik var sahne bize mazi’ yi hatırlatmalı aslında....A Duman   işaretleri; ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/okun-ucundaki-gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Bahçe', 'mavi-bahce-fatih-ersin-ktxdn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen beyaz güvercin

 konar göçersin

 bir aşktan diğerine

 bense ayrılıkları sayıklamaktan 

 adını unutmuş yorgun bir şairim

 fakat çok iyi bilirim

 gözlerinden girilebilir ancak

 cennetin mavi bahçelerine...', 'sen beyaz güvercin  konar göçersin  bir aşktan diğerine  bense ayrılıkları sayıklamaktan   adını unutmuş yorgun bir şairim  fakat çok iyi bi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Ersin']::text[], 8.5, '{"poet":"Fatih Ersin","poet_slug":"fatih-ersin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mavi-bahce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çokcuk Parkı', 'cokcuk-parki-fatih-ersin-gc4sq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir çocuk parkında öğrendim aşık olmayı

  salıncakta sallanırken

  ya da kaydırakta kayarken değil

  bir ucuna oturup boş bir tahteravallinin

  çocukluğumun yere vurduğu her an

  karşımda oturan

  yalnızlığım

  yırtıcı bir kuş gibi yükselirken..

  bir çocuk parkında ayrıldım sevgilimden

  öyle mızıkçılık yapıp

  en sevdiğim oyunu

  yarıda bırakır gibi değil

  yokluğunda anladım 

  zamanmış meğer içimdeki tek düşman

  avuç içi sürekli terlediği için

  büyük sevinçle aldığı balonu

  elinden kaçıran

  aşık bir çocuktum ben..', 'bir çocuk parkında öğrendim aşık olmayı   salıncakta sallanırken   ya da kaydırakta kayarken değil   bir ucuna oturup boş bir tahteravallini...', ARRAY['Türk Edebiyatı','Şiir','Fatih Ersin']::text[], 8.5, '{"poet":"Fatih Ersin","poet_slug":"fatih-ersin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cokcuk-parki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninni', 'ninni-hurrem-yalcin-eevl5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyu bebeğim

Ninni

Kapat süt bakan gözlerini

Duydukça nazlı nefesini

Huzur sarar yüreğimi

Uyu masum yavrum 

Ninni

Büyü ilkbaharımın kelebeği

Büyü elleri kınalı kuzum

Teni gül, bakışı masumum

Uyu minik bebeğim

Yum ceylan gözlerini

Ailemizin en değerli

DEFİNE’si

Ninni

Ninni

02.04.2004

Minik Yeğen Define''ye.................', 'Uyu bebeğim Ninni Kapat süt bakan gözlerini Duydukça nazlı nefesini Huzur sarar yüreğimi Uyu masum yavrum  Ninni Büyü ilkbaharımın kelebeği ...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ninni-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi cinnetinde yalnız', 'kendi-cinnetinde-yalniz-omur-kemal-ozlu-066u2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biraz sanık olduğumuz bu dünyada 

tanıklık ediyorum katlime

herkes kendi cinnetinde yalnız

cinayetinde toplu

el üstündeyiz şimdi/ellerimiz ölümün üstünde', 'biraz sanık olduğumuz bu dünyada  tanıklık ediyorum katlime herkes kendi cinnetinde yalnız cinayetinde toplu el üstündeyiz şimdi/ellerimiz ö...', ARRAY['Türk Edebiyatı','Şiir','Ömür Kemal Özlü']::text[], 8.5, '{"poet":"Ömür Kemal Özlü","poet_slug":"omur-kemal-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kendi-cinnetinde-yalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasın ve Dönüş Yok', 'olmasin-ve-donus-yok-i-brahim-asli-yzbqx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'olmasın istediğim kış

hep olunca arkadaş edindim.

kardan herşeyi taşıyorum.

o zaman beni de aşıyor, 

atıyorum üzerimdeki karları.

düşünmeliydim.

kirli sakallarıyla koşanın bir gün

beyazdan görünmeyeceğini.

v e gelemeyeceğini........', 'olmasın istediğim kış hep olunca arkadaş edindim. kardan herşeyi taşıyorum. o zaman beni de aşıyor,  atıyorum üzerimdeki karları. düşünmeliy...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Aslı']::text[], 8.5, '{"poet":"İbrahim Aslı","poet_slug":"i-brahim-asli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olmasin-ve-donus-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Hallerime', 'benim-hallerime-hifzi-ozbekmez-5a1aj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyku tutmuyor güzelim 

Acı benim hallerime

Derdim bitmiyor güzelim

Acı benim hallerime

Artık uyur gezer oldum

Özlemle sarardım soldum

Ortada perişan kaldım

Acı benim hallerime

Olma gülüm böyle zalim

Nereye varacak halim

Kurudu bak ağzım dilim

Acı benim hallerime

Sevdiysem suç mu işledim

Senden gönlünü istedim

Derdinden kafayı yedim

Acı benim hallerime', 'Uyku tutmuyor güzelim  Acı benim hallerime Derdim bitmiyor güzelim Acı benim hallerime Artık uyur gezer oldum Özlemle sarardım soldum Ortada...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-hallerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Şiiri 1', 'deli-siiri-1-i-brahim-asli-9dmf6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'karanlığın içinde bir avuç aydınlığı da

karartan şenliğin acımasız kollarında 

dans etsen dahi anlayacağın

o karanlığın içinde aydınlığımdın.

dalların üstünden atlıyorum

karanfil kokusu.

evlerin içinden geçiyorm

leş kokusu.

senin yanından geçerken 

asabi bir vaziyetim var 

aması da mevcut

benim kokum,

sana bulaşmış.

aması her an mevcut bir şüphe

yıkım acılar içinde sevinç

bir kere bile razıyım 

gelmesende.', 'karanlığın içinde bir avuç aydınlığı da karartan şenliğin acımasız kollarında  dans etsen dahi anlayacağın o karanlığın içinde aydınlığımdın...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Aslı']::text[], 8.5, '{"poet":"İbrahim Aslı","poet_slug":"i-brahim-asli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/deli-siiri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-guler-ilgaz-almb6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'TUTSAKK  almayı

Koparsak

Yesek yasak meyveyi

Unutsak gerçek bilgiyi

Yazsak yanılsı sözleri

Kapasak gerçeğe gözleri

Yaşasak düşler içinde

Kursak nice oyunlar

Oynarken inansak içinde

Kederi, acıyı, nefreti

Gerçek sanarak yaşasak

Oynarken öğrensek içinde

Renk renk kostümler giyerek

Çeşit çeşit maskeler takarak

Saklasak, unutsak, arasak

Oyunun içinde öğrensek

Gülmeyi, sevmeyi niyeti

Yalansız, mekansız, sonsuza

Almayı  TUTSAKKK içinden

Çıkarsak özgür bıraksak

Seyretsek içinden bakarak

Binbir yaşamı BİRLİKTE', 'TUTSAKK  almayı Koparsak Yesek yasak meyveyi Unutsak gerçek bilgiyi Yazsak yanılsı sözleri Kapasak gerçeğe gözleri Yaşasak düşler içinde Kur...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tutsak-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Çeliğe Su Verilmez', 'her-celige-su-verilmez-zeki-ergin-7r16x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-1-

duracak sanma

zaman olduğu yerde

kozmozun sonsuzluğuna dek

sürecek bu yolculuk

acıyla 

coşkuyla

perçinlenmiş hücrelerimizde kavga

sürecek bu yolculuk

bayrak değiştirmek gerekebilir

apansız

her çeliğe suverilmez

her kuşun da eti yenmez

ve herşeye rağmen

bu yolculuk burda bitmez

el yordamıyla bulacaksın yolunu

karanlığın böğrüne girip

yürüyeceksin

uzun sürse de bu yolculuk

karanlığın gözü kör 

karanlığın özü kahpe

sonu aydınlık

bizi acılar büyüttü

türkülerde hep özlem tüttü 

bir ince duman

biz yürek yangınlarından hız aldık

tutamaz seni 

çağdışı zaman

yılgınlık ve bıkkınlık 

yazmaz defterimizde

zulüm ve işkence 

alsa da alınterimizi

ve  alsa da kanımızı

gücü yeter mi

denizi özlemiş ırmağı durdurmaya

gücü yeter mi 

zamanı durdurmaya

-2-

bu akşam sevdamı düşündüm uzun uzun

yanan bedenleri gördüm düşümde

gecenin bilmem kaçıncı zamanında

gökyüzü kangüllerle doluydu

ve her çeliğe su verilmediğini gördüm

kör kandillerin

titrek sarı ışıklarıydı özlem

dofarda

santiyagoda

bunca kanlar 

neden kim için aktı

oralarda

üst üste yığılmış yatan canlar

birer bayraktı

parababaları

bir gün yıkılır duvarları

gözlerimize bak ey dolar

gözlerimize bak ey mark

gözlerimize bak

gözleri yuvasından fırlamış

parababalarına bak

avuçlarında günah

ökseotuna tutulmuş 

bir avuç satılmış

ve aldatılmış

ve gündoğumu kaçkınları

görmüyordu gözleri

akan kanları

kan sızıyordu mızraklarından

namluları kan kusuyordu 

kan ağlıyordu dünya

ve tüm uğraşlara rağmen 

her çeliğe su verilemiyordu

sür arabacı arabanı

daha hızlı

zamanın sınırlarını aşmalıyız

vakit dar

yol uzun

işte gene yatıyor

bir ceset upuzun

atina sokakları kan

viyetnamda durmuyor bombardıman

_istanbul 1974

_dağlara ver sırtını yt:haz09', '-1- duracak sanma zaman olduğu yerde kozmozun sonsuzluğuna dek sürecek bu yolculuk acıyla  coşkuyla perçinlenmiş hücrelerimizde kavga sürece...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/her-celige-su-verilmez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zerre', 'bir-zerre-cuneyt-sahinoz-e314r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Okyanustan bir damla kayboldu,

Buharlaşıp gözümden akan yaş oldu.

Yüce dağlardan bir kaya koptu,

Rüzgârla savrulup ayağıma toz oldu.

Gökyüzünden bir yıldız kaydı,

Yağmur olup üzerime yağdı.

Ne okyanus fark edebildi bir damlayı,

Ne yüce dağlar kopan bir kayayı,

Ne de gökyüzü kayan bir yıldızı.

İşte bu sebepten dolayı,

Yüreğim deki sevgim

Bir zerre dahi azalmadı…

“Sevdiceğim”', 'Okyanustan bir damla kayboldu, Buharlaşıp gözümden akan yaş oldu. Yüce dağlardan bir kaya koptu, Rüzgârla savrulup ayağıma toz oldu. Gökyüzü...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Şahinöz']::text[], 8.5, '{"poet":"Cüneyt Şahinöz","poet_slug":"cuneyt-sahinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-zerre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin ( Şarkı )', 'nerdesin-sarki-atilla-yildiz-rhnvb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerdesin nerdesin bilmem nerdesin

Sevgin benim kalbimde sen nerdesin

Kimbilir kiminle hangi eldesin

Bir bilseydim mutlu mu kiminlesin 

Derdim depreşir hep seni anınca

Kalbim kanar içten ismin duyunca

Hani gelecektin bahar olunca

Yine de beklerim ömür boyunca', 'Nerdesin nerdesin bilmem nerdesin Sevgin benim kalbimde sen nerdesin Kimbilir kiminle hangi eldesin Bir bilseydim mutlu mu kiminlesin  Derdi...', ARRAY['Türk Edebiyatı','Şiir','Atilla Yıldız']::text[], 8.5, '{"poet":"Atilla Yıldız","poet_slug":"atilla-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nerdesin-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-mutlu-ezgi-durak-8avu0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman bir yalan,

Hani herşeyi unuttururdu zaman,

Hani görmemişe dönerdi insan.

Yoksa budamı bir yalan...', 'Zaman bir yalan, Hani herşeyi unuttururdu zaman, Hani görmemişe dönerdi insan. Yoksa budamı bir yalan......', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ezgi Durak']::text[], 8.5, '{"poet":"Mutlu Ezgi Durak","poet_slug":"mutlu-ezgi-durak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalan-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Çocuk', 'dinle-cocuk-zafer-zengin-etnika-w5o60', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öykümü

Dinle

Çocuk

Ben

Büyüdüm

O 

Küçük

Kaldı

Dünya

Kadardı

Mavi perdeye tutunmuş

Deniz gibi

Okyanuslar sapladılar

Karalar üstüne

İç denizlerde yazıldı

Sevdanın öyküleri

Hep büyükler özlerdi

Öykümüzü

Dinle

Çocuk

Sen

Kadardı

Saçları 

maytaplı

Sevdaya

Yakalanınca

Patlardı...

7 Nisan 2004 '' İçimin Kitabı ''', 'Öykümü Dinle Çocuk Ben Büyüdüm O  Küçük Kaldı Dünya Kadardı Mavi perdeye tutunmuş Deniz gibi Okyanuslar sapladılar Karalar üstüne İç denizle...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dinle-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Esim', 'can-esim-halit-demir-39g08', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlümü sundum, hayatım sana

Kömür gözlerinden, girsem ruyana

Benim ruhum tutsak, olmustur sana

Sevdigim kadınım, Can Esim Benim

Esen rüzgarların ugultulu sesi

Can kusum, sevdigim, sevgimin dili

Divane gecelerimin, essiz emeli

Hayat arkadasım, Can Esim Benim

Bu bir ruya değil, mevsim İlkbahar

Ebedi gönlümde, solmayan Bahar

Neseyle yasadıgım, o güzel Yıllar

Cocuklarımın annesi, Can Esim Benim

Sensizken virane, olur yüregim

Günesim dogmaz ki, benim cicegim

Sen gül ki neseyle, bende guleyim

Hayat kaynagımsın, Can Esim Benim

Degmesin ayagın, tasa topraga

İncinmeni istemem, hayat boyunca

Senden önce girersem kara topraga

Fatihanı esirgeme, Can Esim Benim', 'Gönlümü sundum, hayatım sana Kömür gözlerinden, girsem ruyana Benim ruhum tutsak, olmustur sana Sevdigim kadınım, Can Esim Benim Esen rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/can-esim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arka Bahçe', 'arka-bahce-musa-oz-zzmu2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evin gölgesidir arka bahçe

Bir yatak odasının

Usulca taşan sıcağı

Çocuğun dokunuşu

Annenin durgunluğudur arka bahçe

Dudakta öpücük izi

Bir yaradır kuşun kanadında

Elmaya düşen ala

Çatlayan yüreği narın

Seksek için yollara

Çizilen şekillerdir arka bahçe

Bir gelinin ilk gecede

Yere düşen duvağı

Dul bir kadının

En tenha yeridir arka bahçe

İşveli ve içli sözleri

Ya da yanlış yorumlanan

Pembe gülüşü

Asker mektuplarının

Okunduğu yerdir arka bahçe

Ve üzgün bir sevdanın

O solgun haresi

Şairin haremidir arka bahçe', 'Evin gölgesidir arka bahçe Bir yatak odasının Usulca taşan sıcağı Çocuğun dokunuşu Annenin durgunluğudur arka bahçe Dudakta öpücük izi Bir y...', ARRAY['Türk Edebiyatı','Şiir','Musa Öz']::text[], 8.5, '{"poet":"Musa Öz","poet_slug":"musa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/arka-bahce-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlemedin', 'dinlemedin-kamil-aydemir-kndjp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sana doğma demedim mi bebek

aç kalırsın

büyümeden yaşamı sırtlanırsın

büyürsün joplanırsın

haksızlılara dayanamasın

baban gibi tutuklanırsın

ve ağladıkça bizi utandırısın

demedim mi bebek

dinlemedin

pazarlardan boş filelerle dönüşümüze

odunsuz kalışımıza

hoş geldin fakirliğimize

hoş geldin bebeğim kirlettiğimiz dünyamıza

tek güzel yanısın evimizin

meyvesi sevgimizin

böyle karşılamak istemezdik seni

bağışla çaresizliğimizi

birileri insanı çirkinleştirmede yarışıyor

ve onlar değer görünce akıllar karışıyor

güzel günlerin gönüllü hamalları

karanlığa karşı işiyor

emek hırsızları hemen o güzel insanların peşine düşüyor

bizim emeğimizle onlar kırallar gibi yaşıyor

günlerin avlusunda ufalanan sevinçlerimiz üşüyor

doğma dedim bebeğim doğma

dünyamızda zaman yeni hüzünlere koşuyor

bataklıkta sevgiler

                              aşklarda kirleniyor

yürekler yanıyor

naklen savaşlar 

televizyonlarda film gibi izleniyor

mınacık yüreğine bomba gibi düşer çığlıklar

savaşlarda harcanan parayla

doyar dünyadaki açlar

baharda bile sarı sarı ağaçlar

kirletilmiş toprak

kirletilmiş hava su

çiçeklerde barut kokusu

daha dünki gibi 

beleklerde vietnam halepçe

herkeste zehirli gaz korkusu

dünyamıza anternatif sanal dünya

chatlarda palavra mastırı yapıyor çogusu

ardımda onurlu bir yaşam var

işte buna kızar onursuzlar

onlar bizim yüreğimizi beynimizi

bir de dağları tutuklayamazlar

ama yakarlar dağları

                              ve insanları

sokaklar canpazarı

bildiğimden bunu doğma dedim bebeğim

dinlemedin

asi olusan

ve bir kurşuna yenilirsen

dayanır mı sanıyorsun bebeğim

bu yorgun yüreğim

binlerce çocuk tarafından 

köprü altlarında karşılanıyor sabahlar

ve başlıyor

hiç bir çocuğun hak etmediği günler

babalarımıza da babalarından

babalarımızdan da bize

görünen o ki çocuğum

bizden de size miras kalacak zülümler

doğmanı istemedim

zalımı zülümü bol dünyaya

dinlemedin

insanlar yem olmayacak bir gün

atmacalara kargalara

hoş geldin bebeğim sevdalara

hoş geldin bebeğim kavgalara', 'sana doğma demedim mi bebek aç kalırsın büyümeden yaşamı sırtlanırsın büyürsün joplanırsın haksızlılara dayanamasın baban gibi tutuklanırsın...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/dinlemedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELEMiYORUM...!', 'gelemiyorum-baki-son-zz1sb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey sevgili...

_______Seni..! 

Almak istiyorlar 

Ellerimden

________Yüreğimden...! 

Ta uzaklardan gelip

Yabancı 

_______Rüzgarlar.

Seni çalıyorlar

___________Avuçlarımdan.

Yıldızlı gökyüzünde

_______________Geceyarısı

Dağların zirvelerinde

Ve

Denizlerin derinliklerinde

Gizliyorlar,

_______Seni..! 

Mutsuzluk perileri,

_____________Yalan.! 

_________________Ve nefret bekçileri,

Boşluklarda

Zincire vuruyorlar...

_______Seni..! 

Benden

Ayırıyorlar...

Gelemiyorum 

_______ey sevgili...

Geceleri

Karanlık köşe başlarında

Korkunun gölgeleri

Pusuda..! 

Gelemiyorum 

_______ey sevgili...

Yolumu kesiyor

Bildiklerin..! 

Sana sakladığım

Sımsıcak Sevgileri

Atıyorlar...! 

Gözlerimden koparıp.

Sensiz..! 

_______Beni

Bilinmiş bir sır gibi

_____________Rüzgarlara savuruyorlar...', 'Ey sevgili... _______Seni..!  Almak istiyorlar  Ellerimden ________Yüreğimden...!  Ta uzaklardan gelip Yabancı  _______Rüzgarlar. Seni çalıy...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gelemiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran Yaresi', 'hicran-yaresi-atilla-yildiz-p1t2r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir hicran yaresi var

Benim gönlüm içinde

Yaremin dermanı var

O da yarin içinde

Kaderimmiş benim bu

Düştüm yarin eline

Çekerim ömür boyu

Yar dinlemez kime ne', 'Bir hicran yaresi var Benim gönlüm içinde Yaremin dermanı var O da yarin içinde Kaderimmiş benim bu Düştüm yarin eline Çekerim ömür boyu Yar...', ARRAY['Türk Edebiyatı','Şiir','Atilla Yıldız']::text[], 8.5, '{"poet":"Atilla Yıldız","poet_slug":"atilla-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hicran-yaresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz', 'olmaz-sabit-i-nce-ua2d3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnan ki hasretim dost meclisine,

Ne kadar kendimi avutsam olmaz.

Kulağım hasrettir dostun sesine,

Kırat''a binip de seğirtsem olmaz.

İnceden söylersin bilirim sözü,

Dostu görmeyince neylerim gözü,

Dağlardan aştım da geçemem düzü,

Tellallar tutup da bağırtsam olmaz.

İnşallah kalına muhtaç olmazsın,

Dilerim mevladan darda kalmazsın,

Goncasın kocamaz asla solmazsın,

Hurilerle seni çağırtsam olmaz.

Gönülün yaşına rakamlar yetmez,

Yüreğe kazınmış sevdalar bitmez,

İnce gönüldeki  bu gençlik gitmez,

Parça parça edip dağıtsam olmaz.

Sabit İnce Kayseri 7.4.2004', 'İnan ki hasretim dost meclisine, Ne kadar kendimi avutsam olmaz. Kulağım hasrettir dostun sesine, Kırat''a binip de seğirtsem olmaz. İnceden ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olmaz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NaSıL KıYaBildiN KiRpiKleRimE?', 'nasil-kiyabildin-kirpiklerime-mine-ozdemirtas-7g8zz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aman Allahım! ! , aman Allahım! ! 

En sevdiğim bakışımdı o benim.

Nasıl? nasıl kıyabildin kirpiklerime? 

Makasın ucundan ben,

dökülürken parçalar halinde yere

söyle! yakıştımı hiç o boş çerçeve

konsol üstüne? 

Şimdi ben, şimdi ben seni; 

Badi parmağımın ucunda

göstermek için  herkese; 

Ve beddua niyetine; 

benden soyulmuş bu kabuksuz

bu en komik halinle

kazımazmıyım şiirlere? 

07/04/2004', 'Aman Allahım! ! , aman Allahım! !  En sevdiğim bakışımdı o benim. Nasıl? nasıl kıyabildin kirpiklerime?  Makasın ucundan ben, dökülürken par...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nasil-kiyabildin-kirpiklerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam Kazansın', 'anlam-kazansin-sadik-softa-rgcyc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimiz sevişir, engel tanımaz; 

Mesafeler fersahlara uzansın.

Mutluluk bizimle can bulur canım; 

Bırak sevda biraz anlam kazansın.

Mutluluk sevdanın kutlu düğünü; 

Duyarak yaşamak kalpte her günü; 

Arkada bırakıp geçen her dünü; 

Bırak sevda biraz anlam kazansın.

Her günü dop dolu yaşarız günle; 

İki kalp bir olup coşarız günle; 

Aşkın zirvesine koşarız günle

Bırak sevda biraz anlam kazansın.

Nasıl ki yıkarsa, seller bendini; 

Sevdamın koluna bırak kendini; 

Kıralım, dökelim, aşkın fendini; 

Bırak sevda biraz anlam kazansın.

Bekleyen özlemler, murada ersin; 

Geceler çözülsün, günlere sersin; 

Sen başımda duman duman tütersin; 

Bırak sevda biraz anlam kazansın.

Bütün yollar birleşsinler sevdada; 

Bütün kullar birleşsinler sevdada; 

Bütün yıllar birleşsinler sevdada; 

Bırak sevda biraz anlam kazansın.

Çankırı-07.04.2004', 'Kalbimiz sevişir, engel tanımaz;  Mesafeler fersahlara uzansın. Mutluluk bizimle can bulur canım;  Bırak sevda biraz anlam kazansın. Mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anlam-kazansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toy Bir Çocuktu Yüreğim...', 'toy-bir-cocuktu-yuregim-hurrem-yalcin-mcgiz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toy bir çocuktu yüreğim

Seni çocuk yüreğimle sevdim

Şimdi gözü yaşlı öksüz ve yetim

Yaşamadan yaşlandı yüreğim....

15.02.2002', 'Toy bir çocuktu yüreğim Seni çocuk yüreğimle sevdim Şimdi gözü yaşlı öksüz ve yetim Yaşamadan yaşlandı yüreğim.... 15.02.2002...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/toy-bir-cocuktu-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Duygular', 'son-duygular-atilla-yildiz-870kp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir başka geldi bana bu bahar

İçimde nedensiz bir acı var

Sanki izinim buraya kadar

Yoksa buradan bir yolcu mu var 

Baharlar bitmez canlanır her yer

Bana neşe değil kasvet çöker 

Sanki ilk değil mevsim sonbahar

Galiba her şeyin bir sonu var...', 'Bir başka geldi bana bu bahar İçimde nedensiz bir acı var Sanki izinim buraya kadar Yoksa buradan bir yolcu mu var  Baharlar bitmez canlanır...', ARRAY['Türk Edebiyatı','Şiir','Atilla Yıldız']::text[], 8.5, '{"poet":"Atilla Yıldız","poet_slug":"atilla-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arsız', 'arsiz-serdar-safran-73yuo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan kılığındaydın

Gülüyordun yüzüme

Beni kandırmadaydın

Bilemedim ben,arsız…

Seni anlayana dek

Çözemedim sırrın pek

Ben de yok o yetenek

Göremedim ben,arsız…

Sahte maske takmışsın

Bir çok canlar yakmışsın

Aldatmaktan bıkmışsın

Sezemedim ben,arsız…

Kandırmaktan zevk aldın

Ne bulsan çaldın,çırptın

Allah’tan da korkmadın

Ben korktum senden,arsız…

Zengin-fakir demedin

Çaldığım hep kâr dedin

Hayatı,çıkar bildin

Uslanmazsın sen,arsız…

Ar damarın çatlamış

Şeytan kalbini sarmış

Yalan dolan kuşatmış

Doğruyu görmez,arsız…

Anlatmaktan doğruyu 

Bıkmasam usanmasam

Sen kadar arsız olsam

Utanır mısın sen,arsız…

(Mart/2004-Kastamonu)', 'İnsan kılığındaydın Gülüyordun yüzüme Beni kandırmadaydın Bilemedim ben,arsız… Seni anlayana dek Çözemedim sırrın pek Ben de yok o yetenek G...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/arsiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-serdar-safran-0dy8s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canlanıyor tabiat,yine bahar geliyor 

Gönlüm yokluğun da derin kış uykusunda

Cemreler düştü,tomurcuklar canlanıyor 

Uyansam,gönlümün cemresi de düşer mi? ..

Kış çetin geçerse tadına doyulmazmış baharın

Bereketli olurmuş mahsul,doldururmuş ambarın

Tadı yok sensiz geçen ne baharın,ne yazın

Rüyamda nağmeler,uyansam baharla gelir misin? .. 

Geliversen  gönlüm de açar yediveren güller

Bak etrafa,sensizim diye uçmuyor kelebekler

Gönlümün bakkalın da dolaylanmış  sinekler

Gel gönlümün baharı,öksüz kalmış cemreler…

(Mart/2004-Kastamonu)', 'Canlanıyor tabiat,yine bahar geliyor  Gönlüm yokluğun da derin kış uykusunda Cemreler düştü,tomurcuklar canlanıyor  Uyansam,gönlümün cemresi...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bahar-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğinde...', 'gittiginde-zafer-zengin-etnika-y80q8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Süpriz yapacağım demişti

Şair ruhlu kadın

- Bekle akşama

Beş saati 

Üç gün yapıp

Bir telaş

Bir sabırsızlık

Çocuk gibi 

Şeker bekleyen 

Bir çift göz hasretiyle

Bekledim

Işık  saçan

Ne olur ki! 

Bir kadının

Toy bir delikanlıya süprizi

Gece lambasına tül atar

Kimse görmesin diye bizi

Hem de kırmızı renklisi

Geceye

Akraba etmiştik düşlerimizi

Bir aç''a vermişti

Sessiz gülümsemesini

Diriydi açlığı/Büyüktü kahkahası

Gittiğinde  hüzünlüydü

Herkese görünmeyen 

Yaz gecesi..

Eski bir sevgilinin bıraktığı İ Z

Hatırladıkça G Ü L Ü M S E R i Z...

16 mart 2004 '' Gülümseyenlere''', 'Süpriz yapacağım demişti Şair ruhlu kadın - Bekle akşama Beş saati  Üç gün yapıp Bir telaş Bir sabırsızlık Çocuk gibi  Şeker bekleyen  Bir ç...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gittiginde-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılların İntikamını Çarşaftan Aldım / deneme', 'yillarin-i-ntikamini-carsaftan-aldim-deneme-k-muran-esen-3zpb8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zamandı hatırlamıyorum. İşte öylesine sıradan günlerden biriydi. Alışkanlığım olduğu üzere sabahleyin erken kalktım. Evimin günlük işlerini bitirdim falan. Sıra geldi ütüye. Ütüyü günlük işlerin dışında tutuyorum ve en sona bırakıyorum her zaman.Çünkü ütü yapmak bana günlük iş değil de işkence gibi geliyor.

Başladım içimden homurdana homurdana ütüyü yapmaya, her zamanki gibi. Elime aldığım her çamaşırı ütülerken, o çamaşırla ilgili birşeyler hatırlıyorum. Ne zaman aldığım, nasıl beğenerek aldığım ya da almak için o günün parasıyla ne kadar çok para verdiğim gibi.

Sıra geldi çarşaflara. Büyük oldukları için zor ütüleniyorlar ya, bu nedenle onları en sona bırakıyorum. Canım hiç ütülemek istemiyor aslında. Mecburen ütüleyeceğim. Öffff! .....Kötü kötü bakıyorum o koca koca çarşaflara. Derken pembe bir çarşaf var, sıra ona geldi. Nevresim takımının çarşafı. Çarşafı ütülerken, onu ne kadar beğenerek ve taksitle aldığımı hatırladım. En az onbeş yıl önce.

Birden, bu çarşafın bu kadar yıldan sonra nasıl olup da böyle taş gibi sapasağlam kaldığını düşündüm. Ne kadar sık kullanmasam ve ne kadar sık yıkamasam da; çarşafın bu kadar yıla rağmen böyle sağlam ve yeni kalmış olması beni şaşırttı. Öyle ya; senede en az dört kez yıkasam, onbeş yılda altmış kez yıkamış olurum. Hayret! Rengini bile atmamış. Kâğıt gibi duruyor.

Sonra kendimi düşündüm. Bu çarşafı aldığımda ne kadar gençtim.Ya şimdi? Yüzüme çizgiler çekildi, saçlarım ağardı...Ama çarşaf hâlâ sapasağlam. Büyüklerden duyardım sık sık: ”İnsanın çul kadar ömrü yok,” diye.....Ne kadar doğru. Ben yaşlandım, bizim çarşaf öyle duruyor, genç kız gibi. Neredeyse ölüp gideceğim, benim çarşaf hâlâ hayatta......Birden sinir geldi. Çarşafı kıskanmıştım yani, yıllara meydan okuduğu için; bir çarşaf kadar dayanıklı olmadığım için. Hemen bıraktım ütülemeyi. Ben biliyorum yapacağımı....Makas aramaya bile tahammülüm yok. Bir hırsla alırsın çarşafı eline; önce ikiye, sonra dörde, sonra sekize ayırırsın caaaart diye. Yırttım, parçaladım çarşafı, toz bezi yapmaya karar verdim. Hadi şimdi eskimesin de göreyim. Bir çarşafa mı yenileceğim? 

Kısacası yepyeni çarşafı toz bezi yaptım.”Şimdi yeni kal da göreyim,” diye söylendim içimden.Yaşadığım ve benden çok şey alan yıllardan alamayacağım intikamı, zavallı çarşaftan işte böyle çıkardım.Temizlik yaparken hep o çarşaftan yaptığım toz bezlerini kullandım. Sonra ne mi oldu? Ne olacak; kısa bir süre sonra rengi soldu, birçok yerinden delindi, uçları lime lime oldu. Sonunda attım çöpe. Ohhh! 

Eğer sizin de evinizde yıllara meydan okumuş, eskimemiş böyle çarşaflarınız varsa, benim yaptığımı yapın, tavsiye ederim. Eminim kendinizi çok iyi hissedeceksiniz. Bana çok iyi geldi doğrusu.....Bir çarşafa yenilemezdim ya! Nitekim yenilmedim.............

Bizim çarşaf çoktan çöpe gitti. Ama gördüğünüz(!)   gibi ben buradayım, dimdik ayaktayım. En azından şimdilik. Allah sonumu hayır etsin.', 'Ne zamandı hatırlamıyorum. İşte öylesine sıradan günlerden biriydi. Alışkanlığım olduğu üzere sabahleyin erken kalktım. Evimin günlük işleri...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yillarin-intikamini-carsaftan-aldim-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık!', 'yazik-gulden-karabudak-lgght', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlla sağnak mı yağmalı yağmur ardımdan

İlla nehirler mi boşalmalı gönül yaramdan

İlla sen mi olmalısın hep zafer kazanan

Ben bu borcu sana ödememiş miydim

Unutulmazı başarmaktı ahdım

Didarın,canın, yongan olmaktı bahtım

Sana yangınlarımı anlatamadım

Ben bu acıyı sana yad etmemiş miydim

Niceleriyle kal o yürekli sofranda

Ağlasan yaşına değmez dostlarınla

Canımı acıtan eğilmez başınla 

Ben bu ömrü sana yar etme mişmiydim!', 'İlla sağnak mı yağmalı yağmur ardımdan İlla nehirler mi boşalmalı gönül yaramdan İlla sen mi olmalısın hep zafer kazanan Ben bu borcu sana ö...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yazik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Şiirlerimi,Sana Yazıyorum.', 'tum-siirlerimi-sana-yaziyorum-ali-osman-yilmaz-ppddo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sahi sen,

Çıplak ayaklarınla yürürdün,

Sizin oralardaki,

Irmakların üzerinde.

Ayaklarında ıslanmazdı,

Saçların hep kuruydu,

Arzulayarak seyrederdim seni,

Sahi en son,

Ne zaman öpmüştün beni.

Sana hiç şarkı söylemedim,

Yazdığım öyküleri de okumadım,

Gözlerine bakmaktan,

Sarı saçlarını okşamaktan,

Teninin kokusunu çekmekten,

Vakit mi bulamadım ne? 

Sende istememiştin hiç.

Ama şimdi bak,

Tüm şiirlerimi,

Sana yazıyorum.

Sen yoksun ya,ardından,

Aşk şarkılarımı,

Sevda türkülerimi,

Ağıt ağıt yakıp,

Esen yel’e yükleyerek,

Sana yolluyorum.', 'Sahi sen, Çıplak ayaklarınla yürürdün, Sizin oralardaki, Irmakların üzerinde. Ayaklarında ıslanmazdı, Saçların hep kuruydu, Arzulayarak seyr...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tum-siirlerimi-sana-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir bak', 'bir-bak-gulden-karabudak-ggjle', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canımda sen olanlara bir bak,

Sende yeşeren bir ağaç

Seninle uyanan bir kuşa benzerler

Ellerini çeksen üzerlerinden

Güneşi alınmış yaza benzerler

Ağlamaz,ağlayamazlar yürekten

Seni çalınmış bana benzerler...!', 'Canımda sen olanlara bir bak, Sende yeşeren bir ağaç Seninle uyanan bir kuşa benzerler Ellerini çeksen üzerlerinden Güneşi alınmış yaza benz...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Geldi Ya', 'bahar-geldi-ya-ali-osman-yilmaz-5ot5y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahar geldi ya,

Dün tatlı bir meltem esiyordu.

İki güzel kelebeğin kanatlarına,

Çiğdemlerin kokuları yüklenmiş,

Senin kokun gibi,aynı,

İnanır mısın sevdiğim? 

Sende çiğdem gibi,

Kokardın,biliyor musun? 

Bahar geldi ya,

Dün tatlı bir meltem esiyordu.

Esintinin önünde,

İki güzel kelebek,uçuyordu.

Kanatlarına birinin,

Çiğdem kokuları yüklenmiş,

Diğerinin kanatlarında,

Senin kokun vardı.

Nasıl mutlu oldum? 

İnanır mısın? 

Anlıyorum ki,bu bahar,

Çiğdem kokuları ve,

Senin çiğdemleri kıskandıran,

O güzel rayihanla,

Yeniden sarhoş olacağım.', 'Bahar geldi ya, Dün tatlı bir meltem esiyordu. İki güzel kelebeğin kanatlarına, Çiğdemlerin kokuları yüklenmiş, Senin kokun gibi,aynı, İnanı...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bahar-geldi-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorun Gitmek Değil', 'sorun-gitmek-degil-melih-coskun-rvyvn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sorun gitmek değil 

Yada kalmak 

Bana kal diyen kimse olmayacak 

Bu şehirde

Ağlayışım bu yüzden...

16 Mart 2003

20: 29', 'Sorun gitmek değil  Yada kalmak  Bana kal diyen kimse olmayacak  Bu şehirde Ağlayışım bu yüzden... 16 Mart 2003 20: 29...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sorun-gitmek-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Senin Orospuluğuna Vurgunum', 'ben-senin-orospuluguna-vurgunum-ali-osman-yilmaz-rycn1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden vazgeçemiyorum,

Nedenini ben de bilmiyorum.

Bazıları buna sevda diyor,

Bense şaşkınım.

Sevdalı mıyım sana? yoksa,

Tenine mi tutkunum? 

Belki de orospuluğuna vurgunum,

Senin gibi oynak ve sıcak,

Yatakta muhteşem kadın,

Tanımadım şimdiye kadar.

Evet biliyorum şimdi,

Ben senin orospuluğuna,

Vurgunum.', 'Senden vazgeçemiyorum, Nedenini ben de bilmiyorum. Bazıları buna sevda diyor, Bense şaşkınım. Sevdalı mıyım sana? yoksa, Tenine mi tutkunum?...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-senin-orospuluguna-vurgunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Panik İçindeyim.', 'panik-i-cindeyim-ali-osman-yilmaz-fi1re', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir panik içindeyim ki,

Sorma? 

Dün bütün yıldızları,

Güneşe bağlamıştım.

Bu gece gökyüzünde,

Tüm yıldızları,

Öyle bir başına yalnız görünce,

Bir panik başladı ki,sorma? 

Güneşte yok ortalıkta,

Halbuki ben,yıldızları,

Güneşe bağlamıştım,tek tek.

Ve gecenin bu vaktinde

Güneşte yok,

Yıldızlar bir başına sahipsiz,

Hepsi düşecekler,yeryüzüne,

O yüzden bu gece ben,

Panik içindeyim.', 'Bir panik içindeyim ki, Sorma?  Dün bütün yıldızları, Güneşe bağlamıştım. Bu gece gökyüzünde, Tüm yıldızları, Öyle bir başına yalnız görünce...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/panik-icindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamoz Ektim Arka Bahçeye.', 'yakamoz-ektim-arka-bahceye-ali-osman-yilmaz-zfc6v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deniz kıyısında,akşam vakti,

Yakamozlar parıldamakta.

Seni düşünüyorum sahilde,

Torbama yakamozları doldurup,

Eve dönünce arka bahçeye,

Yakamoz ekerim belki.

Sen ay ışığı gönderirsin geceleri,

Ay ışığında arka bahçede,

Yakamozları büyütürken,

Seni düşünür,

Yakamozlara denizin türküsünü,

Martılarla birlikte,

Söylerim.', 'Deniz kıyısında,akşam vakti, Yakamozlar parıldamakta. Seni düşünüyorum sahilde, Torbama yakamozları doldurup, Eve dönünce arka bahçeye, Yaka...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yakamoz-ektim-arka-bahceye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tane Kırmızı Gül.', 'bir-tane-kirmizi-gul-ali-osman-yilmaz-m4nca', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir Tane Kırmızı Gül.

İstediğin buysa kolay,

Söz sana; 

Bir tane kırmızı gül,

Sadece bir tane ama,

Her sabah uyandığında,

Kapını açtığında,

Elimde bir tane,

Kırmızı gül ile,

Günaydın diyeceğim sana.', 'Bir Tane Kırmızı Gül. İstediğin buysa kolay, Söz sana;  Bir tane kırmızı gül, Sadece bir tane ama, Her sabah uyandığında, Kapını açtığında, ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-tane-kirmizi-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Kuşu.', 'sevda-kusu-ali-osman-yilmaz-x0u8v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin için,

Tuttuğum dilekleri,

Ne kadar yalvarsam da,

Rüzgar,oralara götürmüyor.

Bende söyledim,

Sevda kuşuna,

Aşkımı sana,

Getirecek yakında.

Hadi benim,

Nazlı İpek Böceğim,

Ördüğün Koza dan,

Çık artık dışarıya.

Bak gelmekte sevda kuşu,

Kanatlarında,

Sana olan sevdam,

Çık Koza dan,aç ellerini,

Bak göklerden sana doğru,

Gelmekte,sana olan aşkımla,

Sevda kuşu.', 'Senin için, Tuttuğum dilekleri, Ne kadar yalvarsam da, Rüzgar,oralara götürmüyor. Bende söyledim, Sevda kuşuna, Aşkımı sana, Getirecek yakın...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevda-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tren Camları.', 'tren-camlari-ali-osman-yilmaz-qe5k8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umutlarımı,

Trenlere bağladım.

Sana olan aşkımı,sevdamı,

Tüm istasyonlarda,

Bir,bir trenlerin,

Camlarına yazdım.

Sizin oralardan sevdiğim,

Tren geçerken bak,

Camlarında,sana olan aşkımın,

Sana olan özlemimin,

Sana kavuşma umutlarımın,

Ve tanrıya ettiğim dualarımın,

Seni hasretle beklediğimin,

Tren camlarında,

Yazılı olduğunu,

Göreceksin.', 'Umutlarımı, Trenlere bağladım. Sana olan aşkımı,sevdamı, Tüm istasyonlarda, Bir,bir trenlerin, Camlarına yazdım. Sizin oralardan sevdiğim, T...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tren-camlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehrin Sokaklarında Arıyorum Seni.', 'bu-sehrin-sokaklarinda-ariyorum-seni-ali-osman-yilmaz-yo83a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu şehrin sokaklarında,

Seni aramaktan yoruldum.

Kaç köşe başında,

Sen diye koşturdum,

Sen olmayan yabancıların ardından.

Her köşe başında,

Seni bulamadığımda,

Göz yaşlarım sel oldu aktı,

Şehrin sokakları,

O yüzden ıslak.

Bu şehrin sokaklarında,

Seni arıyorum hala,

Gözlerimden yaş yerine,

Kan damlıyor artık,

O yüzen bu sabah,

Tan yeri kıpkırmızı.

Bu şehrin sokaklarında,

Gözlerim görmez oldu ama,

Seni arıyorum hala.

Soğuk mu soğuk hava? 

Buz tutmuş göz yaşlarım,

Tan yeri kızıl güller gibi kırmızı,

Ve sen güzelim,

Yağan yağmurla,karla,

Islanmaz mısın hiç? 

Ellerin donmaz mı soğuktan? 

Seni bulduğumda sevgilim,

Ellerini ellerime alıp,

Bir güzel ısıtacağım.

Sana sıkıca sarılıp,

Arzularımla ıslaklığını,

Bir güzel kurutacağım.', 'Bu şehrin sokaklarında, Seni aramaktan yoruldum. Kaç köşe başında, Sen diye koşturdum, Sen olmayan yabancıların ardından. Her köşe başında, ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-sehrin-sokaklarinda-ariyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delicesine Seviyorum.', 'delicesine-seviyorum-ali-osman-yilmaz-f60s5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum; 

Hem de delicesine,

Demekten korkanlardan,

Asla değilim ben.

Seviyorum seni,

Hem de delicesine,

Bu yürek,

Bu gönül,

Senden başkasını,

Seversem eğer./............./Beni,

Bilirsin sen değil mi? 

Ben seni yüreğimle,

Bu koca ellerimle,

Seviyorum.', 'Seni seviyorum;  Hem de delicesine, Demekten korkanlardan, Asla değilim ben. Seviyorum seni, Hem de delicesine, Bu yürek, Bu gönül, Senden b...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/delicesine-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup Yazmayı Unutma.', 'mektup-yazmayi-unutma-ali-osman-yilmaz-mfudg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana gittiğin yerlerden,

Mektup yazmayı unutma? 

Uzun ve anlamsız da olsa,

Mektup senden gelecek ya,

O yeter bana.

Kokunu duyayım senin,

Anlamsız sözlerinin içinde,

Seni arayayım.

Bulduğumda ellerimi açıp,

Boynuna dolayayım.

Belki mektubunu okurken,ağlarım,

Damla,damla yaşlar dökülür gözlerimden,

Güneşin ışıkları,

Damlalardan geçerken,

Aşkımızın gökkuşağını,

Rengarenk,oluşturur belki,.

Seni,sana olan aşkımı,

Göz yaşlarımdan süzülen,

Işıkların oluşturduğu,

Gökkuşağının renkleriyle,

Yeniden kurarım gökyüzüne.

Sensizlikten doğan korkularımı,

Gökyüzüne savururum,

Yüksek dağların tepelerine,

Yağar,korkularım tane,tane.

Bana gittiğin o yerlerden,

Mektup yazmayı unutma? 

Yaşadığını bileyim,

Sevdiğini yazmasan da,

Senin iyi haberlerini,

Duyayım.', 'Bana gittiğin yerlerden, Mektup yazmayı unutma?  Uzun ve anlamsız da olsa, Mektup senden gelecek ya, O yeter bana. Kokunu duyayım senin, Anl...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mektup-yazmayi-unutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Annelere Kırgınım.', 'butun-annelere-kirginim-ali-osman-yilmaz-3dmwl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün Annelere kırgınım,

Kendi Anneme olduğu gibi,

Yaşamın kucağına bıraktığı,

Bu oğluna aşktan,

Hiç söz etmediği için.

Duydum ki,

Bütün Anneler de,

Çocuklarına aşktan,

Aşık olmaktan,

Sevdalanmaktan,hiç,

Ama hiç söz etmemişler.

O yüzden bütün Annelere,

Ve kendi Anneme,

Kırgınım.', 'Bütün Annelere kırgınım, Kendi Anneme olduğu gibi, Yaşamın kucağına bıraktığı, Bu oğluna aşktan, Hiç söz etmediği için. Duydum ki, Bütün Ann...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/butun-annelere-kirginim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Ateşinde Yanmak İstiyorum.', 'senin-atesinde-yanmak-i-stiyorum-ali-osman-yilmaz-j3w44', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yer yüzü ile gök yüzü arasındaki,

O daracık alanda,

Mahpusum.

Tepelerden,denizlere düşmekten,

Ve boğulmaktan,

Sonsuza kadar soluksuz kalmaktan,

Sensizliğin girdabında,

Yok olmaktan korkuyorum.

Bana aşk adamı diyorlar,

Böyle yaşamdan korkan biri,

Aşk adamı olabilir mi? 

Yağmur mevsimini bekle diyorlar,

Yeniden çiçek olarak açacak,

Sevda gülü olacakmışım? 

Sen yoksan ve olmayacaksan? 

Neye yarar yeniden açmak? 

Ben yeni aşklara değil,

Sana kavuşmak,

Sana aşık olmak,

Senin ateşinde yanmak,

İstiyorum.', 'Yer yüzü ile gök yüzü arasındaki, O daracık alanda, Mahpusum. Tepelerden,denizlere düşmekten, Ve boğulmaktan, Sonsuza kadar soluksuz kalmakt...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senin-atesinde-yanmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Parfümleri', 'sokak-parfumleri-genco-yilmaz-7eu9k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 've yine akşam oldu sevgili

bütün sokak dalmak üzere uykuya

ve bu gece sokaklarda dolaşıcam yine

çocukluğumu ısıtan ateşler yakıcam

soğuk ve ıssız ankara gecelerinde

ve ben yine

sokak parfümlerinde arıyacam seni...', 've yine akşam oldu sevgili bütün sokak dalmak üzere uykuya ve bu gece sokaklarda dolaşıcam yine çocukluğumu ısıtan ateşler yakıcam soğuk ve ...', ARRAY['Türk Edebiyatı','Şiir','Genco Yilmaz']::text[], 8.5, '{"poet":"Genco Yilmaz","poet_slug":"genco-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sokak-parfumleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Gelir Her Şey.', 'zamansiz-gelir-her-sey-ali-osman-yilmaz-hjtlw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölümünde,

Aşkında zamanı yoktur.

Habersizce gelirler,

Habersizce ölürsün,

Habersizce gidersin.

Ama aşka tutulmaya gör? 

Ansızın gelir amma,

On şiddetinde depremle,

Yıkar gider insanı.

Enkaz altında bile,

Bulamazlar seni.', 'Ölümünde, Aşkında zamanı yoktur. Habersizce gelirler, Habersizce ölürsün, Habersizce gidersin. Ama aşka tutulmaya gör?  Ansızın gelir amma, ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zamansiz-gelir-her-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçedeki O Anı, Özlüyorum.', 'bahcedeki-o-ani-ozluyorum-ali-osman-yilmaz-jrjr1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saçlarının yumuşaklığını,

Gözlerinin maviliğini,

Teninin tadını özlüyorum.

Hani komşunun bahçesinden,

Çaldığımız şeftaliler gibi,

Renklerin içindesin,

Her ısırışta bir başka tatlı,

Bitmesini istemezsin.

İşte o an gibi,

Duvar diplerindeki,

Gizli öpüşmelerimizi,

Elimi beline dolamamı,

Teninin kokusunu doyarcasına,

İçime çektiğimi,

İşte ben seni,

Duvar dibindeki,

O anı özlüyorum.', 'Saçlarının yumuşaklığını, Gözlerinin maviliğini, Teninin tadını özlüyorum. Hani komşunun bahçesinden, Çaldığımız şeftaliler gibi, Renklerin ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bahcedeki-o-ani-ozluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadere Küfretmiyorum Artık.', 'kadere-kufretmiyorum-artik-ali-osman-yilmaz-3so4c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıkılan hayallerimin,

Altında eğilmiyorum artık,

Kadere de küfretmiyorum,

Sensizliğe de ağlamıyorum,

Bende bu yürek,

Bu gönül oldukça,

Sana yer yok güzelim.

Bu günleri yarınlara,

Sensizde bağlıyorum.', 'Yıkılan hayallerimin, Altında eğilmiyorum artık, Kadere de küfretmiyorum, Sensizliğe de ağlamıyorum, Bende bu yürek, Bu gönül oldukça, Sana ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kadere-kufretmiyorum-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Farkettim.', 'simdi-farkettim-ali-osman-yilmaz-rfdhx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne kadar oldu,

Bilemiyorum.

Asırlar gibi geçen zaman,

O kadar uzun süre,

Kendimi bile görmeden,

Erkekçe sevdalara,

Hasret kaldığımı,

Şimdi fark ettim.

Seni görünceye,

Gözlerine dalıncaya,

Sende ateş olup yanıncaya,

Erkekçe sevda nedir,

Bilemedim.

Şimdi erkek gibi,

Bir kadına,

Ben sana sevdalandım.

Anlıyorum ki erkek olmak,

Bir kadına sevdalanmak,

Bir kadında aşkı,

Tanımakla mümkünmüş.

İyi ki varsın,

Ve sana sevdalandım,

Aşkı sende tanıdım,

Erkek olduğumu,

Sana sevdalanınca anladım.', 'Ne kadar oldu, Bilemiyorum. Asırlar gibi geçen zaman, O kadar uzun süre, Kendimi bile görmeden, Erkekçe sevdalara, Hasret kaldığımı, Şimdi f...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/simdi-farkettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşümüyorum Artık', 'usumuyorum-artik-ali-osman-yilmaz-53fo4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günlerdir uykusuzum,

Sen yoksun ya,

Gözüme uyku girmiyor.

Gecenin bir yarısı,

Hatta sabah olmada,

Yavaş adımlarla,

Sahile inip,

Denizi seyrediyorum.

Serin bir rüzgar esiyor,

Üşüyorum,

Kimseler yok ortalıkta,

Yanımda yalnızca hayalin var,

Sımsıkı sarılıyorum hayaline,

Kokunu çekiyorum ciğerlerime,

Sende deniz gibi,tuz kokardın ya,

Tatlı bir sıcaklık sarıyor bedenimi,

Ve artık üşümüyorum.

Martılar uçuşuyor çevremde,

Bir türküdür,söylüyorlar,

Denizin türküsüymüş,söyledikleri,

Binlerce yıldır,

Aşklardan,sevdalardan biriken,

Ve usulca hayalinin,

Dudaklarını öpüyorum gizlice,

Martılar bana gülüyorlar,

Seni öpmemi alkışlıyor,tüm martılar,

Ateş sarıyor bedenimi,

Sarılmışım hayaline,

Dudaklarım dudaklarında,

Martılar türkü söylemede,

Ve sevgilim artık,

Üşümüyorum.', 'Günlerdir uykusuzum, Sen yoksun ya, Gözüme uyku girmiyor. Gecenin bir yarısı, Hatta sabah olmada, Yavaş adımlarla, Sahile inip, Denizi seyre...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/usumuyorum-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı', 'kalmadi-zafer-karalar-lixvu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle başladı seninle geldi

Kalır mı dersin

İster kalsın ister gitsin

Sen hep güzelsin

Seninle geldi seninle gitti

Ne gelir elden

Uymadı ölçüleri

Aşklar da beden beden', 'Seninle başladı seninle geldi Kalır mı dersin İster kalsın ister gitsin Sen hep güzelsin Seninle geldi seninle gitti Ne gelir elden Uymadı ö...', ARRAY['Türk Edebiyatı','Şiir','Zafer Karalar']::text[], 8.5, '{"poet":"Zafer Karalar","poet_slug":"zafer-karalar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalmadi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen yıllar', 'gecen-yillar-ali-umran-sonmez-jn5uq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne geçen yıllar,ne ağaran saçlar uslandırdı beni.

Koşarım peşinden hâla gördükçe böyle bir güzeli.

Can veriyor sevdan getirmesede hatıraları geri.

Koşarım peşinden hâla gördükçe böyle bir güzeli.', 'Ne geçen yıllar,ne ağaran saçlar uslandırdı beni. Koşarım peşinden hâla gördükçe böyle bir güzeli. Can veriyor sevdan getirmesede hatıraları...', ARRAY['Türk Edebiyatı','Şiir','Ali Ümran Sönmez']::text[], 8.5, '{"poet":"Ali Ümran Sönmez","poet_slug":"ali-umran-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gecen-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-ali-soyyigit-1xrf7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Al kazmayı sen tut, küreği de ben

Üçte başlıyoruz ikimiz birden

Yorulmak durmak yok bundan sonra

Açılacak çukurun boyutu dünya

Vur! ümitsizliğe sen, mutsuzluğa da ben

Nasıl çaresiz acılar can çekişirken

Aldırma, bırak, inlesin ayrılıklar

Bu gelen kaçıncı yalancı bahar

Gecesi uzun bu diyarın, ismi kabus

Çığlıklar atıyor şafak, yollar pus

Sor! güneşe sen, yıldızlara da ben

Hep kaçarlar en zor anımızda neden? 

Gülüşler paslı, gıcırdayıp durur

İnsafsız öfke, söyle bu ne gurur

Zifiri karanlıklarda elimi tut

Yalnızlık olmalı gömdüğümüz tabut

Son bir buse koyupta başucuna

Haydi gel evimize gidelim  baba kız, BABA

F.H. Soyyiğit', 'Al kazmayı sen tut, küreği de ben Üçte başlıyoruz ikimiz birden Yorulmak durmak yok bundan sonra Açılacak çukurun boyutu dünya Vur! ümitsizl...', ARRAY['Türk Edebiyatı','Şiir','Ali Soyyiğit']::text[], 8.5, '{"poet":"Ali Soyyiğit","poet_slug":"ali-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/baba-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk...', 'yolculuk-nergis-demet-wlqpy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yolculuk başlayınca,

yokuşlar çıkacak karşına,

nefesin daralacak bazen,

yollar uzayacak,

yorulacaksın.

''gitme'' demiyorum,

gideceksin biliyorum.

git,

git de,

nefesini iyi ayarla,

yanına azık almayı,

yoldaşlarını iyi seçmeyi,

ara sıra dinlenmeyi,

yürürken,

güzel şeyler düşünmeyi,

hatta arasıra şarkı söylemeyi,

ihmal etme! 

bir de doğru hedef seçersen kendine,

o zaman hiç yorulmazsın...', 'yolculuk başlayınca, yokuşlar çıkacak karşına, nefesin daralacak bazen, yollar uzayacak, yorulacaksın. ''gitme'' demiyorum, gideceksin biliyor...', ARRAY['Türk Edebiyatı','Şiir','Nergis Demet']::text[], 8.5, '{"poet":"Nergis Demet","poet_slug":"nergis-demet","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yolculuk-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Anne Gitme*', 'gitme-anne-gitme-bayram-tunca-p88wo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gitme anne gitme daha küçüğüm 

Sensiz gecelerde ben çok üşürüm 

Sensiz dertlerimi kimle bölüşürüm

Gece gündüz hep seni düşünürüm 

Gitme anne gitme daha büyümedim 

Yürüyemem patika yollarda düşerim 

Ben de bir beşerim belki de şaşarım 

Ben sensiz şu hayatta nasıl yaşarım 

Gitme anne gitme henüz doyamadım 

Doğru dürüst göğsünde uyuyamadım 

Daha sorularımın cevabını bulamadım 

Gitme ana gitme sevgine doyamadım 

Sen gidince kim bana kol kanat gerer 

Şu dünyada senin gibi beni kim sever 

İhtimal öksüzüm diye, çoğu kul yerer 

Ah anam ah, senin gibi beni kim över 

Ne çok yalvardım sesimi duyuramadım 

O gül yüzlümün gidişini durduramadım 

Çok aradım, annem gibisini bulamadım 

Aç susuz durdum da onsuz duramadım 

Aah çok geç anladım, anne başa taçmış 

Bir evlat pir olsa da, anneye muhtaçmış 

Ana gibi yar/vatan gibi de diyar yokmuş 

O, cennet için anne rızasını şart koşmuş 

08.04.2004-08.04-İst.', 'Gitme anne gitme daha küçüğüm  Sensiz gecelerde ben çok üşürüm  Sensiz dertlerimi kimle bölüşürüm Gece gündüz hep seni düşünürüm  Gitme anne...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gitme-anne-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Demiş Yazar', 'ne-demis-yazar-oguzkan-bolukbasi-4t0e6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne demiş burada yazar

Kimi düşünmüş

Neyi 

Belli ki sevmeyi

Baştan ayağa bir kenti

Giydirmeyi hiç düşünmüş müdür

Renkler kentin sokakları tarafından

Seçilecek güzel bir kızın gözleri olacak damlarda

Ön cephesi varoşların 

Bir başka kızın sütbeyaz teni

Kırmızıyı kimin dudaklarından alacağız

Delikanlı bir çocuğun umutlarını 

Mavi olarak boyayacağız

Ne demiş burada yazar

Ne yazar, ne demişse demiş denir mi

İnsan anlamadan dinlenir mi', 'Ne demiş burada yazar Kimi düşünmüş Neyi  Belli ki sevmeyi Baştan ayağa bir kenti Giydirmeyi hiç düşünmüş müdür Renkler kentin sokakları tar...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-demis-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayım Dedim', 'aglayim-dedim-hifzi-ozbekmez-asx5v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Durmadan kanıyor gönül yaresi

oturup halime ağlayım dedim

Baktım ki derdimin yoktur çaresi

Oturup halime ağlayım dedim

Uykular kaçınca gece yarısı

Aklıma gelince sevda perisi

Bu gönül dertlerin yeni varisi

Oturup halime ağlayım dedim

Baktım ki dertlerim binleri aşmış

Baktım ki bu gönül sevdadan şaşmış

Baktım ki gönlümü özlemin basmış

Oturup halime ağlayım dedim

Çaresiz kalınca Latif meydanda

Mecalim kalmadı sinemde canda

Benim gibi dertli yoktur cihanda

Oturup halime ağlayım dedim

30 Mart 2004 Saat: 04.00', 'Durmadan kanıyor gönül yaresi oturup halime ağlayım dedim Baktım ki derdimin yoktur çaresi Oturup halime ağlayım dedim Uykular kaçınca gece ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aglayim-dedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Aşk', 'artik-ask-nal-n-yildiz-8qqki', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimiz birbirinden kaçıyor. 

“Artık, diye başlamak istemedim çünkü “artık” diye başlayan cümleler bir dönemin bittiğine, başlayan yeni dönemin de eskisinden farklı olduğuna ve olacağına işaret eder. Bu yeni süreç “artık” la başlamıştır. Biten, geçmiş döneme sığmayan, kelimenin gerçek manâsını da hatırlatan, “artık” duygulara, düşüncelere bulanmış bir bilinmezlik halini anlatır.

Artık, gözlerimiz birbirinden kaçıyor desem, gözlerimizin birbirinden kaçmaya devam edeceği bir süreci kabullenmiş gibi olacağımı vehmediyorum. Bu, “artık”la, “artık ellerimiz de birbirinden kaçıyor”, “artık seni hissetmiyorum”, “artık senin farkında olmak istemiyorum”, hatta “artık seni sevmiyorum” a kadar uzanacak, en alttaki kutuyu çekip, biriktirdiğimiz ve korumakla yükümlü olduğumuz piramidimizi yıkacak bir uğursuz hareketin başlayacağını düşünüyorum. 

Bu piramidi oluşturan kutularda, çok özel antikalarımız var. Acılı, sancılı kimi zaman da neşe ile sevinçlerimizle oluşturduğumuz yalnızca ikimize ait, ilişkimize form kazandıran duyguların kutulanmış halleri. Piramidimize eklediğimiz yeni kutular da en az diğerleri kadar nadide parçaları koruyorlar. İncelikle dokunmalıyız, onlarda geleceğimize ait ümitlerimiz, hayallerimiz var. Biliyorsun kolay hazırlanmıyor bir kutu, içini doldururken emek istiyor, yerine koyarken dikkat istiyor, korurken de hepsini birden. 

Bizi birbirimize mecbur eden çaresizliğimiz, alternatifsizliğimiz değil elbette. İkimiz için de daha kolay, daha az yorucu başka birileri bulunabilir ama eminim ki onlarla bundan daha iyisini yapamayız. 

Hayatımda bir daha hiç kimseyle bu kadar emek harcanmış bu kadar zirveye yaklaşmış bir piramit oluşturamayacağım biliyorum. Korkularım bencilliğimden anlayacağın. Yeni biriyle yeni bir piramit için, sabrım yok, gücüm yok, isteğim yok. Olsa bile piramidin dününe malzeme olacak ortak bir geçmişim, kısaca zamanım yok. Gelecek için bile zamanım yok. Senin var mı?

Seni seviyorum. 

Piramidin başında nöbetteyim.

Yardıma ihtiyacım var.

Yanımda ol. Yanımdayken seni özlemeyeyim. Sorunlarımız var. Sorunlardan en çok sorumlumuzda, peki neden ortak çözümlerimiz yok? Niye tek kabul edilebilir gördüklerin senin çözümlerin? Benim çözümlerim ne diye her seferinde yokluğunla tehdit ediliyor? Kendini temize çekerken, benim üstümü hangi akla hizmetle habire karalıyorsun? 

Şu anı yaşama tembelisin, geleceğe yatırım yaparken şimdiyi çok kolay harcıyorsun. Şu anın hakkını verirsek, gelecek kendini zaten kurtaracak ama geçiştirilen bir şimdi, gerçekleşmeyecek bir gelecek hayalinden başka bir şey değildir belki...

Gözlerini benden kaçırma artık!', 'Gözlerimiz birbirinden kaçıyor.  “Artık, diye başlamak istemedim çünkü “artık” diye başlayan cümleler bir dönemin bittiğine, başlayan yeni d...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüyorum', 'oluyorum-ozan-ozel-tailc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sırtımda ağır bir yük 

çıkıyorum yokuşlardan 

çukurlar, engeller 

taşlar, çakıllar 

yürüyorum 

ardıma bakmadan 

gidiyorum… 

gittikçe ağırlaşıyor yüküm 

dizlerim titriyor yorgunluktan 

olsun 

durmak yok, dinlenmek yok 

gideceğim yere varmadan 

sabah oluyor, akşam oluyor 

kar-yağmur yağıyor 

güneş açıyor 

yükümün üstüne yükler biniyor 

çok yorgunum 

acılar içinde bedenim 

yere daha bir yaklaşıyor 

sırtım ve belim 

sanki tek başımayım 

kimseler görmüyor ve bilmiyor 

imdat 

diye haykıramadan 

eziliyorum 

ölüyorum…', 'sırtımda ağır bir yük  çıkıyorum yokuşlardan  çukurlar, engeller  taşlar, çakıllar  yürüyorum  ardıma bakmadan  gidiyorum…  gittikçe ağırlaş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oluyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Ve Ebediyet', 'i-nsan-ve-ebediyet-firat-celik-v5uc9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerede, hangi zamandasın? 

                 Düşün, ufkunla harbet

                 Varlığın hangi mânasındasın? 

                 Bilmek istiyorsan iman et

                 Bâki bir hayata başlamak mı? 

                 Ölümü bekle, biraz sabret

                 Fıtratındaki tek hakikât

                 Cennet içinde ebediyet

15/Şubat/2004

Malatya', 'Nerede, hangi zamandasın?                   Düşün, ufkunla harbet                  Varlığın hangi mânasındasın?                   Bilmek ist...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çelik']::text[], 8.5, '{"poet":"Fırat Çelik","poet_slug":"firat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/insan-ve-ebediyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtarıcı', 'kurtarici-firat-celik-11d7m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yeni bir günün başlangıcı

Ayrı bir ıstırap, ayrı bir acı

Gül kokulu bir devir için

Bu kaçıncı serzeniş, kaçıncı sancı.

Gel artık ey kurtarıcı! 

Gözümüzün nuru ol, başımızın tac’ı.

İmanınla gel, nurunla gel

Yeryüzüne lider ol, zalime karşı akıncı

05/Kasım/2003

Malatya', 'Her yeni bir günün başlangıcı Ayrı bir ıstırap, ayrı bir acı Gül kokulu bir devir için Bu kaçıncı serzeniş, kaçıncı sancı. Gel artık ey kurt...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çelik']::text[], 8.5, '{"poet":"Fırat Çelik","poet_slug":"firat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kurtarici-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küheylan', 'kuheylan-firat-celik-6lpcu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koş hedefe, haykır ebediyeti

Durma hadi; duranlar oldu hüsrân

Sende gördü dünya, medeniyeti

Sen ki; gül kokulu yağız küheylan.

15/Şubat/2004

Malatya', 'Koş hedefe, haykır ebediyeti Durma hadi; duranlar oldu hüsrân Sende gördü dünya, medeniyeti Sen ki; gül kokulu yağız küheylan. 15/Şubat/2004...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çelik']::text[], 8.5, '{"poet":"Fırat Çelik","poet_slug":"firat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kuheylan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-firat-celik-xbvf1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimdeki derdime ortak ol gel

Dualarımla birleş, kalbimde derinleş

Dermanımsın benim; gözyaşımsın

Sensin benim gözlerime yeni bir eş.

Aradım aradım kimseyi bulamadım

Zamanın raksına dert yanamadım

Yıkık minareyi görmemek için

Gözlerimi hep, yaşlarla sakladım.

28/Ocak/2004

İstânbul', 'İçimdeki derdime ortak ol gel Dualarımla birleş, kalbimde derinleş Dermanımsın benim; gözyaşımsın Sensin benim gözlerime yeni bir eş. Aradım...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çelik']::text[], 8.5, '{"poet":"Fırat Çelik","poet_slug":"firat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozyasi-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümü Özledim', 'koyumu-ozledim-bekir-gedikoglu-q5me3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baba ocağına özlem duyarım

Yaş elli oldu bir kez varmadım

Her gün sılada gece ağlarım

Köyümü düşleyerek öyle yaşarım

Şırahne  kurulur mevsim bağ bozumu

Ezilirdi asmalar balla doldumu

Şırası dökülür  pekmez tavasına

Tadına doyulmaz pekmeze bandığımda

Şu gurbetin kahrını hep çekiyorum

Hasretim köyüme bunu da biliyorum

Evin önündeki mandalinayı rüyamda soyuyorum

Odamdaki kokuyu köyümün sanıyorum

Evin arkasındaki mısır tarlası

İçinde saklıdır yemyeşil salatası

Saymadım çitteki acı biberi

Ağzımızı tatlandırırdı kuş incirleri

Kara yemiş, armut, dut, kiraz, incir

Meyvelerin tadı dünyada bulunmaz

Evin çevresinde hep nöbet tutarlar

Kışında kuzey rüzgarlarından evleri korurlar

Evin önünde lahana tarlası

Ünlüdür bu sebzenin diblesi, dolması

Bir de ekleyelim  biberli çorbasını

Nasıl hayal etmem yer sofrasını

Var ya! ocakta kestane kütüğünün yanışı

Odayı aydınlatırdı çırakman ışığı

Baş köşedeki  babamın bağlama tıngırdattığını

Köyümü özlerim vardır yarası...

Ankara,06.04.2004', 'Baba ocağına özlem duyarım Yaş elli oldu bir kez varmadım Her gün sılada gece ağlarım Köyümü düşleyerek öyle yaşarım Şırahne  kurulur mevsim...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/koyumu-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gözlerine Bıraktım Seni', 'yagmur-gozlerine-biraktim-seni-ali-osman-donmez-3ra6e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nurrevan, nağmeydin dudaklarımda! 

Nazenin teninde güldü nevbahar

Gittin, sesin çınlar kulaklarımda

Gittin, avaredir bütün şarkılar

Nurrevan, nağmeydin dudaklarımda! 

***

Akar son menzile her dem ırmaklar

Hıçkırıklar ölüm kazır duvara

Gecenin tahtını isyanım sallar

Matemim sığınır karanlıklara

Akar son menzile her dem ırmaklar...

Eser, deli rüzgar, deniz dalgalı

Mehtap kâh güler kâh ağlar semada

Islık çalıp geçen iki sevdalı

Gecede bırakır aykırı seda

Eser deli rüzgar deniz dalgalı

Gecede elim ve gözlerim kalır

Şehre tepelerden iner ordular

Gelir, kuytulardan beni de alır

Pençelerinden kan sızan korkular

Gecede elim ve gözlerim kalır...

Halay çeker isyan, kan kusar silah

Bil ki; arzulara avsan Nurrevan! 

Uzar şimşeğe eş,dillerde bir ah

Gönüllere düşen lavsan Nurrevan! 

Halay çeker isyan kan kusar silah

Anla, bu fırtına senin içindir

Asi bir ırmakla akar kıyına

Ah Nurrevan, aşkın içimde kindir! 

Adı “şimşek” olur çakar kıyına

Anla bu fırtına senin içindir

Nal sesleri gelir ta uzaklardan

Bölerler geceyi bölerler beni

Usandım, hülyamı üşüten kardan! 

Usandım, koklamaktan her dikeni! 

Nal sesleri gelir ta uzaklardan

* * *

İsyan denizinde ellerim kanlı

Cehennem soğuğu tenimi yakan

Ferhat’ım dağlarda, başım dumanlı

Buzdan bedenimi ısıt Nurrevan! 

İsyan denizinde ellerim kanlı

Yağmur gözlerine bıraktım seni

Yağmur gözlerinde bulacak mıyım? 

Yağmurlardan alıp o narin teni

Tekrar, yağmurlara salacak mıyım? 

Yağmur gözlerine bıraktım seni

İçimde küllenir mehtapsı düşler

Hayal tepeler, sen ve erguvanlar

Zümrütten denizler, baygın gülüşler

Masaldan güzeldi ah ki o anlar! 

İçimde küllenir mehtapsı düşler

Titrek adımlarım, titrek bakışım

Sanma ki; sonumdur benim Nurrevan

Efkârlı ırmaksam sensin akışım

Sırlı bir ummansam sensin coşturan

Titrek adımlarım titrek bakışım

Ritmik yağmurlarla ağlarken gece

Gözlerin ışıyor ufukta birden

Her şey gözlerine kulken öylece

Seni sensizlikte buluyorum ben

Ritmik yağmurlarla ağlarken gece

Üşür hatıralar, üşür Manisa

Yorgun sokaklarda matem havası

Ah! Beni hasretin kadar dert sarsa

Bulunur elbette bunun devası

Üşür hatıralar, üşür Manisa

Karanlık tünedi son ağaçlara

Helezonlar çizer boşlukta zaman

Vuslatı yılların koynunda ara

Umutlar sırroldu artık Nurrevan! 

Karanlık tünedi son ağaçlara

* * *

Nurrevan, nağmeydin dudaklarımda! 

Nazenin teninde güldü nevbahar

Gittin, sesin çınlar kulaklarımda

Gittin, avaredir bütün şarkılar

Nurrevan, nağmeydin dudaklarımda! 

(Adına Islanıyor Saçlarım''dan)', 'Nurrevan, nağmeydin dudaklarımda!  Nazenin teninde güldü nevbahar Gittin, sesin çınlar kulaklarımda Gittin, avaredir bütün şarkılar Nurrevan...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Dönmez']::text[], 8.5, '{"poet":"Ali Osman Dönmez","poet_slug":"ali-osman-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/yagmur-gozlerine-biraktim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey sendeydi', 'hersey-sendeydi-mutlu-ayar-xo2pl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kıskanırım

Düşmanını öldüren askeri

Ne de kıskanırım

Kutsal bir memeden süt emen bebeği

Geçen yıl bu saatlerde senin olan

Beni kıskandığım gibi! ...', 'Ne kıskanırım Düşmanını öldüren askeri Ne de kıskanırım Kutsal bir memeden süt emen bebeği Geçen yıl bu saatlerde senin olan Beni kıskandığı...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hersey-sendeydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yeni Günle', 'her-yeni-gunle-zeki-ergin-xc888', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her bahar

yüreğimi titreten

içimde kanat çırpan kuşlar

içimde açan çiçekler var ya

yani içimizdeki cevahir

yani yaşama sevincimiz

her bahar

dalarım derinlere

denizlerin derinliğince

anılara dalarım

gündoğumlarında yeniden doğmak buysa

ben her yeni günde

yeniden doğarım

_erenköy may03

_sevgiliye isyan yt:haz04', 'her bahar yüreğimi titreten içimde kanat çırpan kuşlar içimde açan çiçekler var ya yani içimizdeki cevahir yani yaşama sevincimiz her bahar ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/her-yeni-gunle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkbahar', 'i-lkbahar-ensar-cevval-fgeie', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprakta çatırtılar

Yol alıp gidiyor sular

Damarlardaki kan gibi; 

Ağaç ayaklarından soluyor yaşamı

Belli ki bir doğumun heyecanı var.

Bu gelişin farklı olsun diğerinden 

Yeşilinin tonu ağır olsun, yemyeşil

Adına bahar söylendi ya ey mevsim! 

İlk göz ağrımız ol,kop benliğinden.

Bembeyaz karlarla süslü dağlar canlandı

Başkaldırdı soğuk sular,yükseklerden atladı

Uyumuş kalmışken bir dağ yamacında

Seninle mahzun uçurum çiçekleri  uyandı.

07 Mart''04 Üsküdar-İstanbul', 'Toprakta çatırtılar Yol alıp gidiyor sular Damarlardaki kan gibi;  Ağaç ayaklarından soluyor yaşamı Belli ki bir doğumun heyecanı var. Bu ge...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ilkbahar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma düşmeye gör', 'aklima-dusmeye-gor-seynur-i-nal-b74n0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklıma düşmeye gör,

Yeşil bir rüzgâr gibi eser gözlerin

Yüreğimden çığlar düşürür...

Özlemin yıkar bentleri

Gözlerimin nehirlerinden süzülür..

Aklıma düşmeye gör,

Sevdaya uçan bir biçâre güvercin

Menzile varamadan vurulur...

Mahzun bir çiçeğin yapraklarına

İmkânsızlığın buseleri dokunur...

Aklıma düşmeye gör,

Hüzün makamında bestelenir sözlerin

gönlümün dilinde, söylenir durur...

Asıp kanatlarına vuslatları,

Uçar içimden vefasız kumrular,

Bende kalan yine hasretin olur...

Aklıma düşmeye gör,

Umutlarım gezinir

Bakışlarının koylarında

Ve 

Kapatırsın gözlerini ansızın,

Vurgun yer yarınlarım,

Gömülür ummanlara...', 'Aklıma düşmeye gör, Yeşil bir rüzgâr gibi eser gözlerin Yüreğimden çığlar düşürür... Özlemin yıkar bentleri Gözlerimin nehirlerinden süzülür...', ARRAY['Türk Edebiyatı','Şiir','Seynur İnal']::text[], 8.5, '{"poet":"Seynur İnal","poet_slug":"seynur-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aklima-dusmeye-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilsen ki', 'bilsen-ki-gulay-yildiz-wvw8a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilsen ki duygunun başka türlü anlatıldığı yerdir kelimeler

Ve bilsen ki içindeki kirli kanı atar şiir

Okumaktan daha da ileri gider yazarsın 

Yazdıkça anlarsın, kelimelerle ağlarsın', 'Bilsen ki duygunun başka türlü anlatıldığı yerdir kelimeler Ve bilsen ki içindeki kirli kanı atar şiir Okumaktan daha da ileri gider yazarsı...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bilsen-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz Deli Olabilmeli İnsan', 'biraz-deli-olabilmeli-i-nsan-halil-kesken-45vsu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biraz çılgın olduğumu söylüyorlar

Biraz da deli

Ne diyebilirim ki? 

Çok oluyor aklım başımdan gideli.

Taa ilk aşkımdan kaldı; 

Çiçeklere olan,

Yeşile, maviye olan,

Güllere olan aşkımdan kaldı bu delilik.

Aslında insan biraz deli olmalı

Ne biliyim işte

Mesela olur olmaz gülmeli,

Sabahın köründe kalkıp amaçsızca koşabilmeli,

Hiç birşeyden utanmadan

(Buna yırtık elbiseleri de dahil) 

İnsan içine çıkabilmeli,

Biraz deli olmalı insan

Gülü sevdiği kadar; 

Dikeni de sevebilmeli

Büyükle büyük,

Çocukla çocuk olabilmeli,

Veya ömür boyu çocuk kalabilmeli,

En önemlisi ise herşeye rağmen,

Karşılıksız sevebilmeli

Biraz çılgın olduğumu söylüyorlar

Biraz da deli...

Halil KESKEN  08.04.2004', 'Biraz çılgın olduğumu söylüyorlar Biraz da deli Ne diyebilirim ki?  Çok oluyor aklım başımdan gideli. Taa ilk aşkımdan kaldı;  Çiçeklere ola...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/biraz-deli-olabilmeli-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Saygılı Ceninler,', 'kendine-saygili-ceninler-mine-ozdemirtas-hlc4r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'M.....ehmet’e gebe kalmamı Mehmet’e aşermemi bekliyor vatan benden biliyor musunuz? 

A.....ğrılar ve sancılar içinde kıvranarak ve kan denizinde  yüzerek  mehmet’ler doğurmamı.

Y.....emeden yedirmemi, giymeden giydirmemi onu ak sütümle helalinden emzirmemi.

D.....ahası  yalanı dolanı öğretmemi istiyorlar benden. Yani onu da tıpkı bize benzetmemi.

A.....nasını satıyorlar utanmadan analığımın. Harçsız ipotekliyerek Rehine veriyorlar döl yatağımı.

Y.....üreğimi kuşatıyorlar sinsice yılanlar gibi kıvırarak. Nifak ekiyorlar Haberiniz var mı? 

M.....ehmet’i almak için gelecekler kapıma biliyorum. Er ya da geç. Dünya jandarmaları

A.....rsız bir düzenin dönsün diye insan öğüten, aç ve doymayan doyurulamayan çarkları

Y.....a vereceğim Mehmet’imi  onurlu başına çuvalı geçiriversin diye o birileri......... ya da

D...ağlara vuracak kendini  Mehmet, yanına alarak diğer bütün Mehmetleri. Bozacak niyeti

..

A.....rtı oy toplayacak diye yine yeniden yeni birileri sürekli kurban vermemek için Mehmet’leri

Y.....a, aslını inkarsız döllesinler ceninleri. Ya da,  var sayılsın ki;  bu bir çağrıdır hadım olmaya erkekleri.

08/04/2004', 'M.....ehmet’e gebe kalmamı Mehmet’e aşermemi bekliyor vatan benden biliyor musunuz?  A.....ğrılar ve sancılar içinde kıvranarak ve kan deniz...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kendine-saygili-ceninler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört duvar', 'dort-duvar-tamer-sonmezisik-p4c76', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayalin yaşanması ve hayalin kırılması dört duvar arasında.

Baside indirgenmiş anlamlar var şiirin umut deminde.

Mavi cümleler ıslattım, karanlığımın en alçak yerinde...', 'Hayalin yaşanması ve hayalin kırılması dört duvar arasında. Baside indirgenmiş anlamlar var şiirin umut deminde. Mavi cümleler ıslattım, kar...', ARRAY['Türk Edebiyatı','Şiir','Tamer Sönmezışık']::text[], 8.5, '{"poet":"Tamer Sönmezışık","poet_slug":"tamer-sonmezisik","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/dort-duvar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''da kar var ben yanıyorum', 'i-stanbul-da-kar-var-ben-yaniyorum-tamer-sonmezisik-sqlu4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kar tanesi bakışının ısıttığı gecemin, dumanaltı olası yankıları.

Ezikliği firariliğimin toplantı salonlarında,

Tutanaklara geçen asiliğin avuçlarımda kayıtsız...', 'Kar tanesi bakışının ısıttığı gecemin, dumanaltı olası yankıları. Ezikliği firariliğimin toplantı salonlarında, Tutanaklara geçen asiliğin a...', ARRAY['Türk Edebiyatı','Şiir','Tamer Sönmezışık']::text[], 8.5, '{"poet":"Tamer Sönmezışık","poet_slug":"tamer-sonmezisik","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/istanbul-da-kar-var-ben-yaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayıflanış', 'hayiflanis-tansel-yegen-jo4yw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'özgür mü bırakılmıştı gelmeler

kainat açılırken ağır ağır

üç boyutlu patikalarında

ürkek nefesler miydi alınan

kaçış yolu kapalı kader

yaşanması gereken bir kaç an

Eros atmamıştı oku belki de

kor halinde bir buse

ah...kimdi o tenine dokunan...

ufak bir zaman dilimine

gençliğini sığdırmamışlığı

neydi bu hata mıydı

nasıl bir duyguydu...ki

adına aşk bile konamayan

böyle korkmamıştı kadın oysa

yaşadığı o ilk gecede bile

böyle ağlamamıştı gözleri

ilk aşkın yüreğinden koptuğu an

sevapları onu terkederken

günahlar hiç  güzel yaşanmamıştı

anladı ki artık

gitmelerdi zor olan 

-şimdi esen her hoyrat rüzgarda

bir avuç mutluluk kalbinden havalanan

10-11-2003, 12:29', 'özgür mü bırakılmıştı gelmeler kainat açılırken ağır ağır üç boyutlu patikalarında ürkek nefesler miydi alınan kaçış yolu kapalı kader yaşan...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yegen']::text[], 8.5, '{"poet":"Tansel Yegen","poet_slug":"tansel-yegen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayiflanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirim Bitti', 'siirim-bitti-meral-yagcioglu-z4h6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatımın şiiri bitti.

Gökkuşağım silindi

Soldu renkleri 

Kırmızı,yeşil ve de mavi,

Buz kovasındalar şimdi

Kelimelerin kırıldı beli

Uçurumda süzüldü

Bir, bir harfleri

Yerlere serildi.

Karmakarışık

Hecelemem mümkün değildi

Okumayı unuttum

Ya da yazmayı, 

Döndüğü gün ''dönerse eğer''

Yeniden sökerim belki

Hayatımın şiiri kırıldı

Orta yerinden çatırdadı

Tuz buz oldu cam misali

Bölük pörçük kelimeleri.

Boş kadehten

Sarhoş olmuş harfleri

Eğri büğrü sıraladım

Pelür kağıda gözü yaşlı

''İmdat gökkuşağım nerdesin''

Sıkı, sıkı kapalı

Rakı şişesini

Çağlayan sel suyuna

Kattım gözlerimde

Hayatımın mezesi tükendi

Şiirim bitti biteli

Sevgili duy beni

Gönder yüreğini.

Yudumlasam sevgini

Onarsam kırık şiirimi.

mavi; merhem olsa,çalsam yüreğime

Kırmızı; alev olsa yaksa kavursa yalnızlığımı

Beyaz; temiz bir sayfa olsa yeniden yazsam şiirimi

Yeşil; yağmur olsa,filizlensem sevdaya

Sarı; umut olsa,yorgan misali örtse kederimi

Kalan diğerleri; havlu olsa,kurulasam tüm bedenimi

Yağmurdan sonra ki 

Gökkuşağına ulaşırım belki

                            18.04.2003', 'Hayatımın şiiri bitti. Gökkuşağım silindi Soldu renkleri  Kırmızı,yeşil ve de mavi, Buz kovasındalar şimdi Kelimelerin kırıldı beli Uçurumda...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/siirim-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yolculuğu', 'gece-yolculugu-sirma-mersin-yavgr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece yolculuğu başlıyor...

Bilinmeyen adresin karanlığında yol alan; gönül yolcuları ile! 

Yorgun söylentilerden kaçmak,

Vadesi dolmuş hayalleri unutmak,

Yasak ilişkilerden kopmak için; 

Kederli kentin başkentinden, unutulmuşluğun başkentine doğru...

Uzun gece yolculuğunun, tenhasına takılan; parçalanmış yürekler

susma hakkını kullanarak, düş karası umudun peşinde! 

Deli sevdalılar, gönül yaralılarla bir başka mekanda; 

Anıları birbir terkedip gittiler, kederli kentten.

Yeni bi başlangıca doğru; 

Gizli özlemlerin içine, adım adım yol alıyorlar...

Yaralı sevgilerine inat; 

Yarına umutla başlayacak, bir zamanda...

Yaşayacaklar yaşanacaklar...

7.4.04', 'Gece yolculuğu başlıyor... Bilinmeyen adresin karanlığında yol alan; gönül yolcuları ile!  Yorgun söylentilerden kaçmak, Vadesi dolmuş hayal...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-yolculugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkediliş', 'terkedilis-sirma-mersin-gzf6f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamsız bir bakışla; 

Terkedilişimi seyrederken...

Önce, sen terkettin! 

Sonra; anılar birbir terketti, bu yüreği...

Sensizliğin gölgesinde; 

''Bu yerde; seni sana bırakıp gitmek, zor oldu! '' desende...

Terketmekten vazgeçtin bu yüreği...

Söylesene neden? 

30.3.04', 'Anlamsız bir bakışla;  Terkedilişimi seyrederken... Önce, sen terkettin!  Sonra; anılar birbir terketti, bu yüreği... Sensizliğin gölgesinde...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/terkedilis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Sevginle Güzel', 'senin-sevginle-guzel-cafer-tayyar-ozkan-gp1gk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana uzanırken ellerim gönül penceremden,

Senle bakışırken, nefesimi tutup vermeden,

Düşlerimi giyinip seninle geceye varmadan,

Gördüğüm rüya bile senin sevginle güzel,

Seninle bir ömür boyu yaşamayı isterim,

Kalbini kalbime mihrap yapmayı dilerim,

Aşkın badesinden kanarak içmek isterim,

Aldığım nefes bile senin sevginle güzel, 

Adın dilimdeyken mutluluktan uçuyorum,

Dileğine eren canıma daha iyi sarılıyorum,

Gönlümün miracına çıkmayı umuyorum,

Tanrıdan dileğim bile senin sevginle güzel, 

Ayrılığın acı şerbeti beni öldürmüyorsa,

Gözyaşım sessizce içime kadar akıyorsa,

Özlemin kor ateş olup kalbimi dağlıyorsa,

Kalbimin atışı bile senin sevginle güzel... 

03.10.2002 İstanbul', 'Sana uzanırken ellerim gönül penceremden, Senle bakışırken, nefesimi tutup vermeden, Düşlerimi giyinip seninle geceye varmadan, Gördüğüm rüy...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/senin-sevginle-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık...', 'yalnizlik-i-brahim-ethem-bingul-5cemh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözyaşı değildir yürek acısı

Kimlere anlatsam anlar acı yaşımı

Kuşlar konmuş paylaşmışlar aşımı

Yalnızlık öyle garip, öyle burukmuş insan, anlatamadım

Paylaşmayı denesem başaramadım

Başımı yaslayacak omuz bulamadım

Eller bayram derdinde ben mahsun kalakaldım

Yalnızlık öyle garip, öyle burukmuş insan, anlatamadım

Geceler düşman oldu uykularım çalınmış

Herkes bir çatı altında sobaları yakılmış

Bilmem anlımıza hangi yarım sevda yazılmış

Yalnızlık öyle garip, öyle burukmuş insan, anlatamadım

Adımız anılmış dost sohbetinde

Belki bir sokak başı,belki bir kır kahvesinde

Özenmiş yaşantımıza niceleri bizi bilmese de

Yalnızlık öyle garip, öyle burukmuş insan, anlatamadım

Bilirim artık şiirin bitmesi gerek

Öyle demiş büyükler bu günler de bitecek

Gün olur devran döner yüzler artık gülecek

Hayat dersi pek zormuş, bu güne dek bir bunu anladım', 'Gözyaşı değildir yürek acısı Kimlere anlatsam anlar acı yaşımı Kuşlar konmuş paylaşmışlar aşımı Yalnızlık öyle garip, öyle burukmuş insan, a...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizlik-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Hüzünler', 'islak-huzunler-i-lhan-sahinoglu-tm64y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yıldızları hüzünler sakladı 

  boşlukta bulutlar ağladı 

  ıslak bir şehirde 

  biri seni kendine 

  sordu bu gece de 

  yıldızları hüzünler saklarken 

  uykular insanlara rüyalar verdi 

  boşlukta bulutlar ağlarken', 'yıldızları hüzünler sakladı    boşlukta bulutlar ağladı    ıslak bir şehirde    biri seni kendine    sordu bu gece de    yıldızları hüzünler...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/islak-huzunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortak', 'ortak-i-lhan-sahinoglu-ilbmu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayat bazen senin 

  bazen sen hayatınsındır

  her şeyde olduğu gibi

  ne her şey senin 

  ne sen her şeyinsindir', 'hayat bazen senin    bazen sen hayatınsındır   her şeyde olduğu gibi   ne her şey senin    ne sen her şeyinsindir...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ortak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para', 'para-i-lhan-sahinoglu-k0e6l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nedir senden çektiğim para 

hayatım zehrolmuş 

günlerim kara 

bela olmalısın 

sen benim yaşamıma

yada ceza

artık uyuyamaz oldum 

her gece sensin düşünce kafamda

bir  günde rahatça uykuya dalayım 

şa dikenleştirdiğin yatağımda 

bir günde seni düşünmeden yürüyeyim

şu yollarda

hiç mi sevmezsin be beni

vicdansız para 

bir günde bana  çıksan 

loto da toto da piyango da 

hiç fena olmaz hani 

şu çulsuz garibana 

haklısın bütün bu yakınmalarım boşuna 

iyi geceler sana 

ben ancak seni

rüyalarımda elde edebiliyorum 

yalanda olsa. 

        - ulan para banada bunu yazdırdın ya helal olsun sana-', 'nedir senden çektiğim para  hayatım zehrolmuş  günlerim kara  bela olmalısın  sen benim yaşamıma yada ceza artık uyuyamaz oldum  her gece se...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/para-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim', 'benim-i-lhan-sahinoglu-enc4a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göçebe gönlümün yorgunu benim 

gittiği sevgilerin yolunu bilmeyenlerdenim 

selamsız sevdaların hasretini çekenlerdenim 

ne Kerem le kaderim kesişir 

ne de Mecnun la yolum tanışır 

bir Karacaoğlan la gözlerim ağlaşır

bir de  Yunus a sevdam yanaşır', 'Göçebe gönlümün yorgunu benim  gittiği sevgilerin yolunu bilmeyenlerdenim  selamsız sevdaların hasretini çekenlerdenim  ne Kerem le kaderim ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/benim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.:: GÖNLÜNE GiRDiM::.', 'gonlune-girdim-baki-son-g58fq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ulu çınarların, 

.....................Aydınlık 

Ve serin gölgesinde 

.....................Bir temmuz öğlesi, 

Uzak limanlara giden 

Ayrılık ve hasret yüklü 

.....................Gemileri 

Boğazın mavisini 

.....................Ve seni 

Bir kadeh buzlu rakıda 

Eritip, 

.....................İçtim... 

Yepyeni bir dünyaya açılan 

Kapalı kapıları sordum,

.....................Korkunun devlerine.! 

İstanbul''a bakan aynaları 

Ve sevgiye açılan kanatlarıyla 

.....................Süzülen martıları, 

Denizin mavisinden, 

.....................Çınarın yeşiline, 

Bütün çiçekleri topladım, 

.....................Kadehimde... 

Sensizliğin rengini 

Bulmak için 

.....................İçtim. 

Ve seni 

Tekrar bana getirsinler diye 

.....................Parmaklarımı 

Saldım, boğazın sularına. 

İnce bir sis gibi 

.....................Marmara dan 

Ellerini uzatan 

.....................Umutsuzluğa, 

Beni sımsıkı tutan 

.....................Serin 

Mavi sulara 

.....................Seni sordum... 

Seni anlattım İstanbul''a 

.....................Yollara. 

Onlar ki ayrılığı 

.....................Uzatıp gider, 

Dağlara, ormanlara 

Bazen de 

.....................Yok oluşlara... 

Seni düşünüyorum 

Bir temmuz İstanbul unda. 

Yanı başımda 

.....................Bir meltem gibi serin. 

Seni düşünüyorum, 

Üstüme düşen gölgeler gibi, 

.....................Ellerin.! 

Yılları...

.....................Zamanı...

.....................Ve hatıraları 

Bir giysi gibi 

Soyunup boğazın sularına, 

.....................Serin 

.....................Işıklı 

Ve mavi denizin, 

Gönlüne girdim...!', 'Ulu çınarların,  .....................Aydınlık  Ve serin gölgesinde  .....................Bir temmuz öğlesi,  Uzak limanlara giden  Ayrılık ...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/gonlune-girdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Labirent', 'labirent-i-lhan-sahinoglu-0x6ix', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bulmadan kendimizi kendimizde 

her karanlıkta siyahın tonunu seçmeler 

bazen daldığımız her noktada  kör olmalar

belki arayışlarımız

şaşırtmacasında yaşamın 

bir o yana bir bu yana koşuşturmalar

bazen çaresizlikten çıldırmalar

belki yolculuklarımız

olur olmazında anlık kararların 

her bir adım sonrasındaki pişmanlıklar

bazen umutsuzluktan tükenmeler 

belki kaybolmalarımız

girdabında zamanın

bugünü yaşamadan dünü ve yarını düşünmeler 

bazen üşümeden titremeler 

belki de intaharlarımız', 'bulmadan kendimizi kendimizde  her karanlıkta siyahın tonunu seçmeler  bazen daldığımız her noktada  kör olmalar belki arayışlarımız şaşırtm...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/labirent-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi', 'neydi-i-lhan-sahinoglu-oeui7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'belki de doğumdur ölüm

öleceğim ve anlayacağım

rüya mıydı? yaşam

gerçek miydi? ölümün sonrası

güzellikler gördüğüm müydü? 

yoksa düşlerim miydi? 

duyduğum melodiler', 'belki de doğumdur ölüm öleceğim ve anlayacağım rüya mıydı? yaşam gerçek miydi? ölümün sonrası güzellikler gördüğüm müydü?  yoksa düşlerim mi...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/neydi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşamamak', 'konusamamak-metin-oz-kzwak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir''de bana sor konuşamamak nasıl

İçimi parçalıyor

Yarıyor göğsümü

Dikenli bir hıçkırık

Kanıyor kalbim 

Ama yinede konuşamıyorum', 'Bir''de bana sor konuşamamak nasıl İçimi parçalıyor Yarıyor göğsümü Dikenli bir hıçkırık Kanıyor kalbim  Ama yinede konuşamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Metin Öz']::text[], 8.5, '{"poet":"Metin Öz","poet_slug":"metin-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/konusamamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-i-lhan-sahinoglu-amc3k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'nerdesin sevgili

bulamıyorum seni gecelerimde 

sanki aramızda 

gökyüzünen uzanan 

aşılmaz bir siyah perde 

ne sesin duyulur 

ne de yüzün gözükür

üşüyorum sensiz

özlüyorum sessiz

ağlıyorum sesli

bul beni bul 

gözlerini göğe çevir 

göğe sevgili

bak 

bir çift yıldız kayıyor

tıpkı gözlerim

görün onlara bir kez olsun

bulsunlar seni

sonrada çek istersen

gündüzlerimede 

o siyah perdeyi', 'nerdesin sevgili bulamıyorum seni gecelerimde  sanki aramızda  gökyüzünen uzanan  aşılmaz bir siyah perde  ne sesin duyulur  ne de yüzün göz...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nerdesin-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çürük', 'curuk-nalan-kazazoglu-3rt6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşlerimi çürük iplere dizip duruyorum

Sonrasında  da aklıma bakıp,

aklıma şaşıyorum......', 'Düşlerimi çürük iplere dizip duruyorum Sonrasında  da aklıma bakıp, aklıma şaşıyorum.........', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/curuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazı Tura', 'yazi-tura-i-lhan-sahinoglu-x4fjr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bizim aşkımız 

metal para yuvarlaklığında 

bir yüzünde sen 

öteki yüzünde ben 

kader yazı tura oynuyor 

aşkımızla

atıyor zamanın boşluğuna 

acının kara yüzüne düşen ben

hasretin gökyüzüne bakan sen', 'bizim aşkımız  metal para yuvarlaklığında  bir yüzünde sen  öteki yüzünde ben  kader yazı tura oynuyor  aşkımızla atıyor zamanın boşluğuna  ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yazi-tura-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma', 'korkma-i-lhan-sahinoglu-ncss3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ışıltılar var gözlerinde

belli belirsiz bana bakan 

fısıltılar kadar ürkek 

utangaçlıklar kadar suskun 

buğday rengi tenin solacak sevgisizlikten 

hadi sevdiğim konuş benimle beni tanı 

bak haline nasılda sıkılıyorsun kimsesizlikten

hadi yüreğim sevginin en mert yanı', 'ışıltılar var gözlerinde belli belirsiz bana bakan  fısıltılar kadar ürkek  utangaçlıklar kadar suskun  buğday rengi tenin solacak sevgisizl...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korkma-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Koynunda', 'gecenin-koynunda-mustafa-ceylan-6g7nb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece saat üç kırk sekiz

Tenini arıyorum, kokun gerek bana

Çık gel neredeysen, ne haldeysen? ! 

Aşkın engerek bana! 

Gece sat üç kırk dokuz

Hasretin içimde sonsuz...

Çılgınım, deliyim yollara düştüm

Geceler kar, geceler buz...

Gece sat üç elli

Seni, sadece seni sevdim, yüzümden belli

Zıpkın olup saplandın ciğerime

Bendesin temelli...

Gece saat üç elli bir

Gel, gel artık koynuma gir! 

Aklım iflâs topunu atıyor

Beynimi çevir...

Gece saat üç elli iki

Öldüğümde anımsarsın belki

Nefesin gül açıyor kalbimin toprağında

Sevmek mi senin ki? ..

Gece saat üç elli üç

Kahrolası ayaklarım sana koşuyor

Peşimde gece bekçisinin düdüğü

Sırtımda seneler hörgüç...

Gece sat üç elli dört

Kırdım kalemi, sensizlik başa dert

Aşkının fırınına düştüm, neyleyim

Ateşinle üstümü ört...

Gece saat üç elli beş

Hastane önünde mahalleli, ağlaşır bacı-kardeş.

Baykuş sesinden çöker çatılar; 

Cennet hesaplı, Cehennem beleş...

Gece saat üç elli altı

Tenini, kokunu arıyorum; çağ kısaldı.

Çık gel neredeysen bir tanem? ! 

Buselerin masaldı...', 'Gece saat üç kırk sekiz Tenini arıyorum, kokun gerek bana Çık gel neredeysen, ne haldeysen? !  Aşkın engerek bana!  Gece sat üç kırk dokuz H...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gecenin-koynunda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canıma Okudu Bu Şehirler, Bu Şiirler', 'canima-okudu-bu-sehirler-bu-siirler-mustafa-ceylan-4vu3k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canıma okudu bu şiirler, bu şehirler

Şarkılara işledim çağrılarımı

Ve ağrılarıma ağrı kattı küf kokan meyhaneler.

Çare bulmaz, bulamaz Lokman Hekim,

Kırılan aynalarda bir yetim memleketim

Serçe kanadıyla geliyor musun? 

Seni sevdiğimi biliyor musun? 

Canıma okudu bu şiirler, bu şehirler

Karınca solumasında yıkılası terminaller

Yığınla insan taşır otobüsler, minibüsler

Ama bir tek sen yoksun içlerinde, sen yoksun...

Mektubun geldi okudum, anlamadım

Söyle, söyle bana geliyor musun? 

Sensiz yandığımı biliyor musun? 

Canıma okudu bu şiirler, bu şehirler

Sabah, selâmsız asık surat yüzler

Akşam, yüzümde yüz arar yüzsüzler

Kulun, kurbanın olayım mıknatısım benim,

Çek, çıkar beni buralardan, ne olursun? 

Bahar esintileri geçmeden yüreğimden

Kurtar beni, anlıyor musun? 

Sensiz yandığımı biliyor musun? 

Canıma okudu bu şiirler, bu şehirler

Kırık dökük sözcükler,taş duvar caddeler...

Birinden kan akar, birinden pislik kokar

Adamı günaha sokar, bunlar güzelim! 

Şu kara bahtıma oturup, bir güzel ağlıyor musun 

Sensiz yandığımı biliyor musun? 

Canıma okudu bu şiirler, bu şehirler

Saz desen susmuş, park desen uyumuş

Aslında her ikisi birbirine uymuş,

Benim de yazgım buymuş güzelim

Ağrılarım ondan, çağrılarım sana

Söyle, çabuk söyle, durma öyle! 

Ellerinde gül, saçlarında dolunay geliyor musun? 

Seni sevdiğimi biliyor musun?', 'Canıma okudu bu şiirler, bu şehirler Şarkılara işledim çağrılarımı Ve ağrılarıma ağrı kattı küf kokan meyhaneler. Çare bulmaz, bulamaz Lokma...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/canima-okudu-bu-sehirler-bu-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke toprak olsaydım', 'keske-toprak-olsaydim-metin-oz-43kr4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşke toprak olsaydım,bir avuç toprak

Renk renk çiçekler açan

Ağaçlar yetişseydi bağrımda

Hayat verseydim  keşke,taze fidanlara

Keşke toprak olsaydım,bir avuç toprak

Yorgun karıncalara ev olsaydım

Bir solucan dolaşsaydı içimde,aylak aylak

Keşke,bir yılan kıvrılıp yatsaydı göğsümde

Keşke toprak olsaydım,bir avuç toprak 

Adem''le havva''yı benden yaratsaydı tanrı

Göz olsaydım,kaş olsaydım

El,ayak dilinde söz olsaydım keşke

Keşke toprak olsaydım,bir avuç toprak

Rüzgar savursaydı beni,Dolaşsaydım dünyayı

Yansaydım,soğusaydım,ıslansaydım keşke

Ve,hep bir avuç toprak kalsadım.

25/07/2003

GAZİANTEP', 'Keşke toprak olsaydım,bir avuç toprak Renk renk çiçekler açan Ağaçlar yetişseydi bağrımda Hayat verseydim  keşke,taze fidanlara Keşke toprak...', ARRAY['Türk Edebiyatı','Şiir','Metin Öz']::text[], 8.5, '{"poet":"Metin Öz","poet_slug":"metin-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/keske-toprak-olsaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körebe', 'korebe-i-lhan-sahinoglu-umujg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'belki bir oyundu bu 

rüyalarda oynanan 

gözlerim kapalı 

her yer karanlıktı

seni bulamıyordum

sanki yüreğim

sevgiye körebe oynuyordu da

bir tek senin sevgini bulamıyordu

ve her gün 

görünmez ayrılıklar 

çeliyordu ayaklarımı da 

sevgisizliğin çukuruna düşüyordum 

sanki', 'belki bir oyundu bu  rüyalarda oynanan  gözlerim kapalı  her yer karanlıktı seni bulamıyordum sanki yüreğim sevgiye körebe oynuyordu da bir ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/korebe-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Gök Delindi', 've-gok-delindi-mustafa-ceylan-4gnaz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '*Susuzum güzelim

		 Sensizim,

		 Uykusuzum...

Çeşmeler, çeşmeler yetmez susuzluğuma

Çünkü yoksun yanımda.

Çöl yangınında şimdi hafızam

Bir feryat, bir acılı türkü ki duyabilsen 

Ceylanında...

Yüz bıçak, düz bıçak attım göğün göğsüne

Yazdım yeniden alınlara kaderi

Çekip çıkardım girdaplardan

Kendim için seni,

Gel hele beri! ..

Sen var ya sen, sen değişmez iklimimsin

Ruhum, canım, her şeyim, deliren kalbimsin

Ayırma ellerini elimde kalsın! 

Sahibimsin...

Yoksan eğer, yolların hepsi çıkmaz sokak

Varsan eğer cümbüşe, curcunaya bak

İkimize doğar gün, ikimize iner şafak,

Seher yelimsin...

Çeşmelerin nabzında nabzım güp güp atar...

Dualar dilimde alev alev, sımsıcak

Bulutları hamur ettim dizelerimde,

Yağmurum sensin...

Islat sicim sicim, şemsiyem olmasın hiç.

Kaldırım taşlarında sona ersin nefesim

Öfken olayım yıldırımlara eş,

Sevgilimsin

Sevgilimsin...', '*Susuzum güzelim 		 Sensizim, 		 Uykusuzum... Çeşmeler, çeşmeler yetmez susuzluğuma Çünkü yoksun yanımda. Çöl yangınında şimdi hafızam Bir f...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ve-gok-delindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi bu', 'hepsi-bu-i-lhan-sahinoglu-r3au8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne bana aitsin sen 

nede sana aitim ben 

kiralamışız sadece 

boş yüreklerimizi birbirimize

hepsi bu 

ne kaçabildin bana sen 

ne de sınırları aşabildim ben 

bakıştık sadece

uzaktan seviştik gizlice 

hepsi bu', 'ne bana aitsin sen  nede sana aitim ben  kiralamışız sadece  boş yüreklerimizi birbirimize hepsi bu  ne kaçabildin bana sen  ne de sınırları...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hepsi-bu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değil', 'degil-mustafa-ceylan-4vqzh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaydımı kütükten silin gitsin

Şampiyonluk yarışında yokum

Fil gibi oturmuş göğsüme zaman

İlân edilsin ilân:

		Sonunculuğum...

Korkarım böcekten, devden değil

Kaygım dosttan ayrılmaktır

Ölümden değil...

Saray listesine almayın beni

Derdim dağ kadar yüce beynimde

Kaynağı kendimden

Gülümden değil...

Ölüyorsa bebekler

Düşüyorsa kelebekler

Çağırmayın safınıza ne olur! 

Ne olur, bir çizgi çekin adımın üstüne! 

Olamam bendeki ceylana kefil,

Ölümüm bir ceylan gözlüden olacak

Elimden değil...

Kütükten kaydımı silin gitsin,

Bu sahte oyun burada bitsin! 

Haykırışlarım canımın çekirdeğinden

Dilimden değil...', 'Kaydımı kütükten silin gitsin Şampiyonluk yarışında yokum Fil gibi oturmuş göğsüme zaman İlân edilsin ilân: 		Sonunculuğum... Korkarım böcek...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/degil-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne olur ki', 'ne-olur-ki-i-lhan-sahinoglu-jgdog', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir adayım sanki gökyüzünde 

altımda boşluk üstümde

bir hiçim sanki kaderin gözünde

görse ne olur görmese ne', 'bir adayım sanki gökyüzünde  altımda boşluk üstümde bir hiçim sanki kaderin gözünde görse ne olur görmese ne...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-olur-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Geceler', 'mor-geceler-i-brahim-dikmen-2-ryy05', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda deyip,geçme sakın,

Alev alev yakar aşkım.

Nasıl bitti anlamadım,

Pembe düşler,mor geceler.

Geçip gitti,güzel günler,

Sazım kırık,mızrap inler.

Ayrılığa yok çareler,

Pembe düşler,mor geceler.

Gülüşmeler,kahkahayla,

Sevişmeler,doyumsuzca.

Yaşanır hep,sorumsuzca,

Pembe düşler,mor geceler.', 'Sevda deyip,geçme sakın, Alev alev yakar aşkım. Nasıl bitti anlamadım, Pembe düşler,mor geceler. Geçip gitti,güzel günler, Sazım kırık,mızra...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mor-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parça Parça', 'parca-parca-mustafa-ceylan-sx2an', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '•	Gör

•	Bir’ in

•	Nasıl sonsuz olduğunu...

Sevdim, 

Çağlaya döndüğünde çiçek.

Sevdim, 

Hasretim-ıstırabım bir gerçek...

Düşlerim gerçekleşecek diye

Bekledim, çok bekledim...

Acılar tayfununda yüreğim,

Can parça parça...

Demir attım zamanlar ötesine

Kervan yollarında boyun büktü çiğdemim

Yağız atlıların nal seslerini,

Kendini beğenmiş güzellerin 

topuk seslerini duyarım

Ne gelen var, ne giden var

Kapı tokmaklarını öpüyor rüzgâr

Han parça parça...

Evveli böyleydi baharların

Ökse otlarından aşka pusula

Göçmen kuşlar yuva yaptı dalıma

Kapı kilide emanet, duvar yıkık

Öncesinde idamım var dost dergâhının

Son parça parça...

Cam parça parça

Gözümde gözlük, karşımda ayna

Sılayı bekleyen pencerem

Ekran, lâmba, kadeh, şişe...

Akıl  erdiremedim gitti, bu gidişe

Her parçada yansır tebessümlerim

Hoşgörü ırmağında yıkanır öfkem

Kin parça parça...

Bugünden bellidir yarınlar

Sigara dumanında, örümcek ağında sabrım.

Aklım düşlerimin nakışında tutuklu

Dün parça parça...

Bırakın beni bana kuyruklu yıldızlar

Bırakın yaşadığım ana

Sonsuzlar, bitiveren hızlar

Işıktan elbisemi giymeliyim canıma

Heyhat! 

Gün parça parça...', '•	Gör •	Bir’ in •	Nasıl sonsuz olduğunu... Sevdim,  Çağlaya döndüğünde çiçek. Sevdim,  Hasretim-ıstırabım bir gerçek... Düşlerim gerçekleşec...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/parca-parca-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladın mı Hayat Bu! !', 'anladin-mi-hayat-bu-mustafa-ceylan-9awkz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güvenme dağların bozardığına

İnanma narların kızardığına! 

.................Gözlerimden akan Ceyhun’a bak

......................................Her şeyin bir sonu var bilirsin.

Dünyan, kırlangıç ıslığından 

Duygun, akasya kokusundan,

Sonsuza yelken açar uykun

.................İnceden inceye, gül yaprağından; 

.....................................Gülme! .. Boşuna gülersin...

Sarılma bozkırın otlarına

Yel eser, gün vurur, yok olur...

Bir ezgiyle geçiyor koskoca ömrün

Farkında değilsin belki de; 

................Bayırlarda çğdemlerin dilindesin,

Takvim takvim, saat saat

.....................................Özlem kokan türkülerdesin...

Bebek ellerinde masum öpücük,

Kapanan perdelerde çıkmazımsın; 

Balkon tellerinde asılı kalan

Deli dolu arzularımsın; 

.....................................Söyle şimdi nerdesin? 

Işık yanar, kâğıt uçar, yel eser

Kapılar açılmamak için küser

Vurur duvarların 

Beton göğsüne çığlığın

Yanımda, kanımda değilsin ya; 

Biliyorum mutlu değilsin, biliyorum

...................................Gecelerin içindesin...

Güvenme seslerin yansıdığına

Hangi sözcük kalacak, bilinmez yarına

Derman olmaz efkârına

Kara biber kokusunda mevsimler

...................................Gurbetimdesin...

...................................Sevda şiirlerinin gurbetindesin...

Hayat bu sarmal sarmal pamuk ipliği

İçindeki lâcivert garipliği, elleriyle

Koparıveren sensin; 

..................................Evet sadece sensin

Bilmem, benden daha ne istersin? 

Deprem olur, dağ çöker, bulut gider

Bir başkası çıkar balkona göremezsin

Ellerini uzatır boşluğun ortasına

...................Ellerin bende kalmıştır

...................Ürkek, titrek ellerin

.................................Ellerini veremezsin...', 'Güvenme dağların bozardığına İnanma narların kızardığına!  .................Gözlerimden akan Ceyhun’a bak .....................................', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/anladin-mi-hayat-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtleme', 'dortleme-mustafa-ceylan-dtdqt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Domatesin kabuğu, soğanın zarı

Ten kafesinde çırpınan kuştur can

Gök renginde doğu, akça batı

Kan kırmızı güney ve simsiyah kuzey 

Çırpınıp durmada sebep sebebe

Yön içinde yön, can içinde can

Gerçeğin aynasının sırrı dörtleme

Dört kapı, dört usül, dört mevsim

Kudret helvasını verdim serçeye

Dört arzu, dört unsur, dört secde

Bıçak atmak bulutlara boşuna  	

Bir baştan bir başa aşktır kütük...', 'Domatesin kabuğu, soğanın zarı Ten kafesinde çırpınan kuştur can Gök renginde doğu, akça batı Kan kırmızı güney ve simsiyah kuzey  Çırpınıp ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dortleme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-i-lhan-sahinoglu-cfwqe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yağmurlu sonbaharlarda 

üşütmekten korkup 

yüreğime sakladığım 

gizli sevdamsın 

savrulan umutlarımın 

sebebisin

uçan yaprakların sebebi 

rüzgarlara eş', 'yağmurlu sonbaharlarda  üşütmekten korkup  yüreğime sakladığım  gizli sevdamsın  savrulan umutlarımın  sebebisin uçan yaprakların sebebi  rü...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-357-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başımda Sonbahar', 'basimda-sonbahar-mustafa-ceylan-oy58c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ev yirmi beş, büro yirmi yedi

Bu dert, bu çile ömrümü yedi.

Göçmen kuşlar bile şaşırdı

Son bahar başımda gümüledi...

Yeşil pancurlu ev kaldı rüyâlarımda

İçimde boydan boya, halı döşeli büro

Gönül dallarıma yağan kar dindi...

Senelerin avcundaki bu efkâr dindi.

Ev yirmi beş, büro yirmi yedi

Yaşıyor her biri anılarımda...

Eylül akşamlarında bir yalnızlık 

Bir yalnızlık alır beni kollarına.

Çalkalar, çalkalar düşüncemi

Artık son limana demir attı atacak

Bu yorgun gemi...

Seherde uyanır, güne horozlanırım

Kamyonlar gelir şehre,

Üstünde ev eşyası...

Ve ben soluyan devlere eş duygularda

Göçmen kuşlaradır şarkılarım...', 'Ev yirmi beş, büro yirmi yedi Bu dert, bu çile ömrümü yedi. Göçmen kuşlar bile şaşırdı Son bahar başımda gümüledi... Yeşil pancurlu ev kaldı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/basimda-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anamın Türküleri', 'anamin-turkuleri-mustafa-ceylan-hi3ac', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tandır başlarında duman duman

Terleyen alnında zamanın adımları

Yorgunluğunu savururdu ateş külünde

Çoktandır duymaz, duyamaz oldum

Anamın türkülerini...

Asmalardan sarkan üzümdü

Kalbim, ışığım, iki gözümdü...

Bağ bozumlarında yeşil, yemyeşil

Yaprak toplardık çotuklardan...

Anam söylerdi, biz oynardık

Duymaz, duyamaz oldum çok zamandır

Anamın türkülerini...

Yanıktı ama yakmazdı,

Neşeliydi ama anlam doluydu.

Testide ayran kadar güzel,

Arklarda su kadar hayat taşırdı.

En uzak mesafelerden bile

Bize ulaşırdı.

Duymaz, duyamaz oldum, seneler oldu

Anamın türkülerini...', 'Tandır başlarında duman duman Terleyen alnında zamanın adımları Yorgunluğunu savururdu ateş külünde Çoktandır duymaz, duyamaz oldum Anamın t...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anamin-turkuleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya Tarlası', 'papatya-tarlasi-mustafa-ceylan-zlp9c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi altın sarısı tepsi

Kimi göğsünde taşır güneşi

Kimi kan kırmızı gelinciğin kardeşi

Vah ki yüreğimin sancılarına vah! 

Oldum olası uykularımı haram etti

Hepsi...

Hepsi de aynı sevdamın seherinde uyur

Gün ortasında, bembeyaz etekleri 

Işıldar, yüzümün yorgun aynasında...

Hepsi de kelebek masumluğunda duru

Vah ki açılmamış gözümün perdesi vah! 

Yanyana dizilmişler, ne güzel...

Ne güzel dağların çiçeği güneşi öpmek

Ve ne güzel kıldan ince köklerle

“Su! Su! ..”diye toprağa gömülmek...

Bu haylaz kız nereden geldi bilemem? ! 

Kim öğretti ona? 

Fal bakmasını papatyalardan...

Vah ki zamanenin 

İpi kopmuş uçurtmasına vah! 

Bir de demez mi:

	-“Mersi! ...”', 'Kimi altın sarısı tepsi Kimi göğsünde taşır güneşi Kimi kan kırmızı gelinciğin kardeşi Vah ki yüreğimin sancılarına vah!  Oldum olası uykula...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/papatya-tarlasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Antalya', 'sevgili-antalya-mustafa-ceylan-a4yl1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tünek Tepesi’ nden seyrettim seni,

Afrodit misâli göz kırptın bana; 

Masmavi sularla, altın kumlarla

Portakal bahçelerinde gezinen

Yosun gözlü kızlarla

“Gel! Gel! ” diyordun...

Geyik Bayırı’ ndan seyrettim seni,

Nar çiçeği gibi gülümsedin bana; 

Sihirli, ılık bir nefesin vardı,

Saçlarını yıkıyordun

Düden’ de, Kurşunlu’ da.

Zümrüt kıyılarınla, cam piramitinle

Ayna tutuyordun bana

“Gel! Gel! ” diyordun...

Mazı Dağı’ ndan seyrettim seni

Gizlice “Beni seviyor musun? ” dedin 

Dağların denizlerin kadar güzel

Poyrazın meltemin kadar efsunlu,

Seni sevmemek mümkün mü? 

İmkânsız seni bırakıp gitmek

Sensiz yaşamak ölüm, biliyor musun? 

Kepez Varyantı’ ndan seyrettim seni,

“Akşam oluyor, ışıklarımı yak! ” dedin 

Çam kokan, muz kokan havanı soludum

Donattım ışıklarla her yanını

On dördünde bir ay ışığı

On binlerce parlak yıldızla

Bezedim gök yüzünü...

Parklarımda, bahçelerimde gezin

“Haydi gel! Gel! ” diyordun...

Sonra,

Tutuştuk el ele

Yat limanında iki bira salladık

Konyaaltı Sahilinde taş attık denize,

Dans ettik kızlarla Lâra’ da,

Saklıkent’ ten gelen kar üstüne

Tatlı döküp yedik...

Sen beni, ben seni

Ölesiye sevdik

Ölesiye sevdik...', 'Tünek Tepesi’ nden seyrettim seni, Afrodit misâli göz kırptın bana;  Masmavi sularla, altın kumlarla Portakal bahçelerinde gezinen Yosun göz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sevgili-antalya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Ümit Vermeseydin', 'bana-umit-vermeseydin-i-brahim-dikmen-2-bdzpo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana ümit vermeseydin,

Seni böyle sevmezdim.

Ruhumu okşayan,sözlerinle,

Kalbimi,mest etmeseydin.

Gitti yıllar,karayelin peşinden,

Kalbim,bomboş kaldı,sensiz.

Bilki sensiz yaşayamam,

Gel neredeysen,gel kalpsiz.

Bana bakıp,gülmeseydin,

Sana böyle bağlanmazdım.

Aklımı alan bakışlarınla,

Yüreğimi,yakmasaydın.', 'Bana ümit vermeseydin, Seni böyle sevmezdim. Ruhumu okşayan,sözlerinle, Kalbimi,mest etmeseydin. Gitti yıllar,karayelin peşinden, Kalbim,bom...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bana-umit-vermeseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimi Çok Sevdi İsem', 'kimi-cok-sevdi-i-sem-mustafa-ceylan-khazn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimi çok sevdi isem,

Önce, o terketti beni...

Çünkü,

Hep yanlış anladı sözlerimi,

Okuyamadı gözlerimi,

Hele yüreğimi

Hele yüreğimi! 

Var,

Sen de git! 

Sen de terket! 

Ne yazar? ...

Kimi çok sevdi isem,

Önce o hançerledi beni...

Çünkü,

Hep tersine anladı sözlerimi

Göremedi can evimi,

Hele kalbimi

Hele kalbimi! 

Var,

Sen de git! 

Ancak varırsın! 

Güle güle! 

Mektup yaz e mi? 

Kimi çok sevdi isem,

Önce o yıktı beni,

Başkasına ne hacet! ! 

Düşmanım duymasın aman! 

“Sevdiklerim pek yaman! ”

Kimi çok sevdi isem,

Açtım sonuna dek gönül kapımı,

Döktüm içimde ne varsa

Yalansız, dümdüz...

Yunus’ un odunu oldum da

Odun sanıp yakıverdi.

Sonra, köhne bir direğin dibine

Unutup bırakıverdi...

Kimi çok sevdi isem,

En gizli sırlarımı söyledi cihana.

Gazeteye, ajansa,

Radyoya söylese gene iyi

Yıkmaya çalıştı evimin direğini

Anlamadı ki ozanın yüreğini...

Sonrası mı be muhterem? 

Bükmeye çalıştı bükülmez bileğimi

Yaa! ! 

İşte böyleyken böyle dost

Olduk mu verem...

Kimi çok sevdi isem,

Evrak havale eder gibi

Bir başkasına postaladı.

Oysa bilmiyordu ki katarlara sığmaz

Zarflardan taşar,

Trenlere takla attırırdım...

Kimi çok sevdi isem,

Değiştirmek istedi gömlek sanıp

Çömlek sanıp boşaltmak...

Bilmediler, bilemediler asla! 

Maviye, yeşile, elâya

Bahara tutkunluğumu

Bir de portakal rengiyle

Dantel dantel kırmızılara...

Ne bilsinler? 

Hep zarfa baktılar, içine değil! 

Kimi çok sevdi isem,

Beyazlarla yoğurdu,

Kırmızılarla çağırdı,

Kahverengilerle aldattı,

Ağladı siyahlarla rol icabı...

Artık paletlerdeki renklere inat

Yeni bir renk bulmaya koştum

Alacalı...

Kazıdım sakalları yeniden

Bir fotoğraf çektirdim, fiyakalı...

Ama saçlarım şeffaf, ne yapayım? 

Güzelsin, hoşsun, sana aşığım

İklimleri değiştirip

Rüzgârlara yön veririm; 

Sana hayatı yalansız, sade, yalın

Gösteririm dedim,

Nafile...

Dudak bükmeseydi keşke

Keşke gülüp geçmeseydi! 

Bir kere olsa inansaydı,

Bir kere olsa, benim gibi yansaydı! 

Kimi çok sevdi isem,

Önce gözlerinden kovdu beni...

Oysa ben, o gözlere meftun

O gözlere vurgunum...

Bilmez, bilemezdi ki...

“Var, git! ” dediler

“Kaybol, yok ol, ver kurtul! ”

Verdim canımı,

Döktüm kanımı

Kurtulamadım bir türlü

Sevdiklerimden...

“Sevmeyin, sormayın ben

Aramayın, tanımayan, unutun! ” dedim

Ne onlar unuttu, ne de terk ettiler

Ne de ben? ! 

“Sonumuz Allah kerim! ”', 'Kimi çok sevdi isem, Önce, o terketti beni... Çünkü, Hep yanlış anladı sözlerimi, Okuyamadı gözlerimi, Hele yüreğimi Hele yüreğimi!  Var, Se...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/kimi-cok-sevdi-isem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durup Dururken', 'durup-dururken-mustafa-ceylan-ryzdx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nereden karşıma çıktı, anlamadım

Taş kesilen zamanın ellinci boyutunda

Bu sürmeli gözlü, yanık yürekli güzel? 

Bölük pörçük etti uykularımı birden; 

Durup dururken...

Tutuşturdu şarkıları ruhumu alev alev

Nice ezgiler yakaladı

Gönlümün tellerinden; 

Çiğ damlatan seher yeliydi dudakları

Özlem iniyordu göz bebeklerinden...

Nereden karşıma çıktı, anlamadım? 

Durup dururken...

İklimler ağaran saçlarımda

Deli taylar gibi soluyorken,

Kentin kulesindeki saat

Acımasız tokmağını ömrüme

Güm güm vuruyorken 

Bebek gülmesinde masum,

Derviş zikrinde kanatlanan kuşum

Gün güneşlikken havalar

Nereden karşıma çıktı, anlamadım? 

Durup dururken...

Yüreğimin saçaklarında umutlar

Kılıç kılıç uzanmış buzken

Kardelenler misali çıkıverdi karşıma

Bir bahar, bir çiçek yağmuru ki

Diyecek yok telâşıma! 

Yorgun postacının titrek elleriyle

Verdiği mektupları okurken

Nereden karşıma çıktı anlamadım? 

Durup dururken...

Paydos demiştim şiire

Şairlere küsmüştüm inanın! 

Duyguları paslı kutulara kilitlemiştim

Yanılmışım, bilmemişim...

Toprak sonsuzluğuna

Gel gel diye çağırırken

Yeniden ellerim aldı kalemi,

Yeniden kâğıtlarda mısra mısra

Şarkılarım...

Şimdi o ağlar, ben yanarım! 

Anlamadım, bu güzel

Karşıma çıktı nereden? 

Durup dururken...', 'Nereden karşıma çıktı, anlamadım Taş kesilen zamanın ellinci boyutunda Bu sürmeli gözlü, yanık yürekli güzel?  Bölük pörçük etti uykularımı ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/durup-dururken-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-i-brahim-dikmen-2-sv71x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimde tütüyorsun,

Sana kavuşmak,hayalim.

O şirin gerdanında,

Bir gezinti,düşlerim.

İstanbul bekle beni,

İnan çok özledim seni.

Kanlıca,sarıyeri,

Hasretim sana,istanbul.

Masmavi denizlerin,

Buram buram,kokusu.

Ada vapuruyla,bir gün,

Gezmek isterim doğrusu.', 'Gözlerimde tütüyorsun, Sana kavuşmak,hayalim. O şirin gerdanında, Bir gezinti,düşlerim. İstanbul bekle beni, İnan çok özledim seni. Kanlıca,...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istanbul-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiire Şiir', 'siire-siir-mustafa-ceylan-1siqp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ihlamur kokan nefesinle

Karşıma çıkıverdin...

Mısra mısra, hece hece

Gündüz gece

Yerlere yıkıverdin...

Büyüksün, güçlüsün cihan biliyor

Otur da bir konuşalım.

Beynimin dehlizlerini bombaladığın Yeter! 

Sokul göğsüme, bırakma ellerimi

İyice koklaşalım...

Kaderimsin, en büyük kederimsin

Sen bende ben, her şeyimsin! 

Gir koluma haydi, bulutları aşalım

Dudak dudağa evreni dolaşalım...

Dedikodu çıksın hakkımızda

Bir deliye vurulmuş desinler ceylanı

Oh iyi olmuş diye

Sevinsin düşmanlarım

Sokul göğsüme, bırakma ellerimi

Seni sevdiğimden perişanım...

Çıktın madem karşıma

Dur hele! Dur biraz! 

Tam otuzbeş yıldır peşindeyim

Gölgenle, ayak izlerinle

Sevişmedeyim...

Kalemim, kâğıdım hazır işte

Tut ellerimden, tut biraz...

Adını sorsam söylemezsin

Belini sarsam “oh ne güzel! ” demezsin

Sahi sen nesin? 

Krallara baş eğdirdin,

Çağlara yön verdin,

Sevdiğini ilden ile atıp

Derisini bile yüzüverdin...

Saz mı? Onsuz edemezsin

Söz mü? Dilleri bilemezsin

Naz mı? Anladığın tek şey

Hele gecelerde, hele yakamozda

Öyle naz edersin ki...

Sahi, sen kimsin? 

Durma, çabucak söyle! 

İn misin, cin misin? 

Çıktın madem karşıma

Otuz beş yıldır

Zehir kattın ekmeğime, aşıma

Ve çile dağlarını yıktın dertli döşüme

Yazmam ha! .. Sevmem haa! ..

Sesime kulak ver, haylaz! 

Otur da söyleşelim biraz!', 'Ihlamur kokan nefesinle Karşıma çıkıverdin... Mısra mısra, hece hece Gündüz gece Yerlere yıkıverdin... Büyüksün, güçlüsün cihan biliyor Otur...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/siire-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yazıyorum Seni', 'seni-yaziyorum-seni-mustafa-ceylan-robkr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni yazıyorum seni,

Bendeki seni...

Geri verdiğin günden beri

Sendeki beni...

Seni yazıyorum seni,

İnadını, öfkeni, ihanetini

Ellerini, gözlerini, her yerini

Çelik tutkularını, kadife nefesini

Kalemimin ağıdını duyuyorum,

Dünyama karalara boyuyorum

Boğuluyorum doğrusu...

Seni yazıyorum seni,

Yaptım muhasebesini bir yılın

Buz gibi suyla seni ve zamanı yıkadım

Gül suyu serptim anılara

Çıkmadı ihanetinin kokusu

Öfkem dizildi boğazıma

Bir avuç dolusu...

Seni yazıyorum seni,

Kimyası değişiyor vücudumun her satırda

Duygularım yeniyor mantığımı

Kırıp parçalıyorum akıl sandığımı

Oldu mu? 

Seni yazıyorum seni,

Gölgemdin, gövdemi silip süpürdün

Devdim, cüceleri üstüme güldürdün

Gömüldün boğazına dek çamura

Sığındın günah gecekondusuna

Gelinlik bile giysen sonun hüsran

Nasılmış görecek, bilecek, hissedeceksin 

Ölüm korkusu...

Seni yazıyorum seni,

Küf kokan masalarda sarhoşlara

Meze olduğun günleri duyacağım...

Para istemiştin benden unuttun mu? 

Hangi pavyondaysan bulacağım seni

Ve çil çil paraları önüne sayacağım, 

Al bunu diyeceğim, al bunu! 

Az kaldı, bekle, bekle 

O...pu! ..', 'Seni yazıyorum seni, Bendeki seni... Geri verdiğin günden beri Sendeki beni... Seni yazıyorum seni, İnadını, öfkeni, ihanetini Ellerini, göz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/seni-yaziyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Tarifi', 'askin-tarifi-hakki-hakan-kaya-lzoao', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlatıldı yıllar boyu

anlaşıldığı kadar aşk

bazen bir ozanın kaleminde

şiir oldu döküldü dizelere

yada hasrete büründü

yol aldığı gizemlere

söylendi bir çırpıda

iki dudak arası iki kelime

matematiğe bile döküldü

dört artı dokuz ile

anlatıldıkça eksildi anlamı

anlaşılamaz oldu

bilinen manası 

çözülemeyen gizlilik içinde...', 'Anlatıldı yıllar boyu anlaşıldığı kadar aşk bazen bir ozanın kaleminde şiir oldu döküldü dizelere yada hasrete büründü yol aldığı gizemlere ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askin-tarifi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ceylan Ağlıyordu', 'bir-ceylan-agliyordu-mustafa-ceylan-jw81a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ceylan ağlıyordu

Yılları birbirine sarıp sarmalıyordu

İhanete uğramış, kurşun yemişti böğründen

Kurtardın ceylanını bir tanem

Mucize misin sen? 

Bir ceylan ağlıyordu

Sular çekilmiş, dereler kurumuş

Ormanlar, dağlar, bir bir yok olmuştu

Hıçkırıktı karınca ayağının çizdiği

Yalnızlıktı çöl rüzgârının savurduğu

Sen döndürdün hayata,

Sen bağışladın sanata,

Ve ellerinle yağmurlara emanet bıraktın

Bu ceylanı birden...

Söyle bakalım bir tanem

Mucize misin sen? 

Bir ceylan ağlıyordu

Şiirde, şarkıda, nağmede, ezgide yıkık

Bir ceylan ağlıyordu

Koskoca bir ormanda,

Devasa bir şehirde

Dudağında hıçkırık...

Denizleri buharlaştırıp bulut yapan sen

Göktaşı benzeri ötelerden kopan sen

Su getiren, hayat veren, gülen, güldüren

Ağıdını neşelere çeviren

Başını üstelik fırıl fırıl döndüren

Sen

Mucize misin anlamadım ben? 

Bir ceylan ağlıyordu 

Zulmü, zulmeti işkenceyi görmüştü

Davacıydı avcılardan

Kalbimden vurmadılar diye...

Döndün bana, döndün ya çok şükür

Dudaklarında tebessüm

Gözlerinde pırıltı

Ve ışıltı ellerinde

Döndün ya sımsıcak, hayat dolu müjdelerle

Uzakta kal ziyanı yok, ama canımdasın ya

Ama kanımda, özümde, sözümde, 

gözümdesin ya...

Varsın, kavuşsun yüreğinde iki ayrı dünya

Söyle bana bebeğim

Mucizemsin ya

Öyle değil mi? ...', 'Bir ceylan ağlıyordu Yılları birbirine sarıp sarmalıyordu İhanete uğramış, kurşun yemişti böğründen Kurtardın ceylanını bir tanem Mucize mis...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bir-ceylan-agliyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahverengiyim', 'kahverengiyim-mustafa-ceylan-rbp1n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sormayın bana, sorsanız da nafile söylemem

Koskoca bir Selçuklu beyiyim...

İki binli yıllarda bir serçeye tutuldum

Balkonlarda, tellerdeyim

Renklerden renk seçer göz bebeğim

Kahverengiyim...

Yâr kitap kapatır dudaklarına

Bakarım gözlerine, gözüm mıknatıs

Kaldırır kitabı gözlerinin üstüne

“İndir be kız! ”

Sonra? Sonrası mı cancağızım? 

Dokunsam tenine ihtilâl olur içinde

Bilirim deprem olur Filipinlerde ve Çin’ de...

Gülücükleri saklı bulutlarımda

Martılarının ahengindeyim

Renklerden renk seçer ellerim

Kahverengiyim...

Tebessümünle, sıcaklığınla, gülücüğünle

Döndün, geldin ya; mutluyum işte

Yüreğim luna park, aklım çarpışan oto

Tüm varlığım sevinçte, seninle...

Paşa gönlüm kahve ister tarihten

Paşa gönlüm seni ister sahiden

Bir karıncanın gölgesindeyim

Yipelek otu sanki, ip ince

Zayıf, rakik, titrek

Ve de dokunsam ürkek üstelik...

O kıllı, ben kıllı

Nerede akıllı? 

Nasıl döndü bu devran, anlayamadım? 

Gülsem, gülemedim

Ağlasam ağlayamadım...

Sonunda anladım

Öfke, nefret değilim ben

Dipten bucağa sevgiyim, tek kelimeyle

Kahverengiyim...

Bir karıncaya yenilmiş

Koskoca Selçuklu beyiyim...', 'Sormayın bana, sorsanız da nafile söylemem Koskoca bir Selçuklu beyiyim... İki binli yıllarda bir serçeye tutuldum Balkonlarda, tellerdeyim ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kahverengiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pamukkale Türküsü', 'pamukkale-turkusu-mustafa-ceylan-5jxab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Adına kentler yapılan Hiera ve Selena’ ya...

Bilmem kaç asır geçti aradan

Kaç mevsim? 

Ne sen sayabilirsin yılları

Ne yangınlar, ne seller, ne deprem...

Ne şu üstümüzden geçip giden bulutlar...

Yaşamaktayım yorgun senelerin

Göğsündeki sessizliği...

Senden bana kalanlar:

Ayakta durabilmiş birkaç sütun

Aklını kıvrım kıvrım kaybetmiş mermer

Efsânelerin korkunç sessizliği

Ve taş kesilmiş umutlar...

İşte bu türkü senin türkün

Oku okuyabilirsen, duy duyabilirsen

Ya da ıslat dudaklarını ılıman sularda

Çağları üzerinden atabilirsen...

Büyü nedir anlamazdım

Sana tutulmadan önce yüreğim...

Mısra mısra, hece hece

Ben seni yazdım, sana yazdım...

Ben hiç tanımadım seni,

Görmedim gözlerimle...

Gözlerin nasıldır? Ellerin nasıl? 

Belli ki güzelden öte güzelsin, zira

Adına kentler yapılmış

Sütunlardan, mermerlerden...

Hangi delişmen rüzgâr öpücüklerle

İnmiştir şakaklarından, kirpiklerinden? 

Hangi su raks etmiştir

Omuz başlarında? 

Kaç yiğidin nabzı atmıştır

Avuçlarında bilemem? ! 

Gönlümün içine girdin bir kere,

Başkasını sevemem! 

Bu türküyü asırlar sonra,

Söylüyorsam sana,

Bil ki sana yandığım içindir Selena! 

Ben hiç tanımadım seni,

Görmedim gözlerimle...

Adına hamamlar, saraylar yapılmış

Kutsal seramiklerden, defne dallarından

Kokun sinmiş mermerlere

Silinmemiş yıllardan...

Büyük taş salonlarda

İpek giysiler içinde dolaşan sensin.

Kemerlere iz bırakmış ayakların,

Bakışlarınla şekillenmiş kayalardan

Halâ yansımakta kahkahaların...

Afrodit’ i bile deli edensin,

Gün ışığında her sabah

Hamamlarda burcu burcudur nefesin.

Bu türküyü asırlar sonra,

Söylüyorsam sana

Bil ki seni sevdiğim içindir Selena! 

Ben hiç tanımadım seni

Görmedim gözlerimle...

Gözlerin nasıldır? Ya göz bebeklerin? 

Bak Selena, kulak ver bana

Artık Kral Midas hakem değil

Apollonla Marsias’ ın flüt kavgasına...

Artık kavgayı Midas yapıyor

Biliyor musun? 

O kocaman kulakları

Kocaman kocaman parmaklarıyla...

Artık ay Tanrıçaları

İklimleri değiştirmiyor dudaklarıyla

Anlıyor musun? ...

Asırlar geçti, geçecek daha

Midas yok, Apollan yok, Marsias yok

Midaslar Tanrılaşmış,

Tanrılar, Tanrıçalar öylesine çok! 

Gel desem, gel desem sana

Asırları fırlatıp bir kenara

Gelir misin bana Selena? 

Ben hiç tanımadım seni

Görmedim gözlerimle

Dinle, duy, işit beni! 

Del asırların bağrını kirpiklerinle

Işıt beni, ısıt beni! 

Ben şu karşı ovaların esmer çocuğu

Çıkınımda tuz, şepit, çökelek

Testim omuzlarımda, içi dopdolu ayran.

Ne babam Zeus, ne Evmenes, ne Midas? 

Ne adına kentler kurabilirim

Ne sütunlar, saraylar? 

Yapayalnız, sade bir insanım

Türkü yakmasını,

Kaval çalmasını bilirim.

Gün ışığıdır heybemdeki yük

Derdim asırlar kadar büyük.

Saçlarının rüzgârını arıyorum

Bak yana yana...

Gel, birlikte haykıralım cihana

Selena! 

Bilmem kaç asır geçti aradan

Kaç iklim? 

Ne sen sayabilirsin yılları

Ne köşe süsleri, ne kartal başları...

Nice savaşlar yapıldı senin için,

Kanlar döküldü nice...

Bırakmam ellerini,

Mermer de olsa ellerin

Tutmuşum ya yenice...

Şu yarısı yıkık duvarda gezinen gölge

Senin değil mi? Kimin? 

Ya şu yollar hangi sancıya gebe? 

Yollar urganıdır sana olan hasretimin.

Ya şu ılıman suyun sesi, sıcaklığı

Sıcaklığı değil mi teninin? 

İpek ipek giysilerin içindesin mermerden

Çağrımı bir duysan acımasız senelerden

Uzanıvermişsin boylu boyunca

Uyur, uyur, uyursun...

Taş kesildi takvimlerin elleri,

Canlan, atıl kollarıma ne olursun! 

Bu türküyle hicranımı,

Hasretimi, gurbetimi anlatıyorum sana

Selena! ...

09.06.1982 / Pamukkale', '-Adına kentler yapılan Hiera ve Selena’ ya... Bilmem kaç asır geçti aradan Kaç mevsim?  Ne sen sayabilirsin yılları Ne yangınlar, ne seller,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":120,"source_url":"https://www.antoloji.com/pamukkale-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Yürekli Kum Tanecikleri...', 'kayip-yurekli-kum-tanecikleri-hurrem-yalcin-7cfgv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göçmen Kuşların

Hüzünlü

Kanatları

Asıldığınca

Gök yüzüne....

Güneşin

Kırmızı

Yüzü

Yaslandığınca

Dalgaların

İnsafına....

Hırçın

Dalga

Hoyrat

Kırbacıyla

Dövdüğünce

Sahili...

Dağılır

Kumların

Naçar

Yürekleri...

Akışır

Dalgaya...

Karşı koyuşsuz

Dönüşsüz

Geri...

İşte

Onlar

Kayıp

Yürekli

Naçar

Kum

Tanecikleri....

08.04.2004', 'Göçmen Kuşların Hüzünlü Kanatları Asıldığınca Gök yüzüne.... Güneşin Kırmızı Yüzü Yaslandığınca Dalgaların İnsafına.... Hırçın Dalga Hoyrat ...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kayip-yurekli-kum-tanecikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Şehir', 'beyaz-sehir-pasa-ceten-1cxz5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canana can olmuş renkler,beyaz şehirde

Çocukluğumun geçtiği,büyüdüğüm sokaklarda

Yaramazlık yapıyorum,oynadığım yerlerde

Şelale saçlı yaprakların naraları ağaçlarda

Gözlerinin içine baka baka gülüyorum

Neşe; gecenin sessizliğinde dirilmiş sevgili

Yıldızların varlığı,gözlerimin denizinde

Yatarak göklerin tavanına bakıyorum

Yıldızlar aşk deryasından başka diyara kayıyorlar

Hayalime sesleniyorum,aşıkların şenliği var

Beyaz şehrin cadde ve sokaklarında

Beynim yorulup uykuya dalıyorum; bülbülün sesinde 

Hırsını yitirmiş dağlar gibi kalkıyorum yerimden

Mavinin kanatlarında gözlerimi açıyorum

Kelebekler alnımda oynaşıyorlar,telaşlanıyorum

Halime gülenleri,renklerin aynasında görüyorum

Beyaz şehrin cadde ve sokaklarında

Kalbim öyle çarpıyor ki fışkıran nurda

Halka,halka büyüyor heyecan damarlarımda

Bütün dualar sütten damlayan süt gibi

Melekler ruhumu terbiye etmiye geliyor

Şahadet güllerinde kılavuzun kokusu var

Beyaz şehrin cadde ve sokaklarında

Titrek rüzgar varlığımı fısıldıyor

Tebessümde coşuyorum,tebessümde yüzüyorum

Koşuyorum tutamıyorum kendimi kendimden

Ruhumun bülbülü konuyor beyaz yağmura

Şefaatçi; karanfili sunuyor Rabbim''e

Şelale saçlı yaprakların altında

Güneş gibi bakıyorum

Beyaz şehrin cadde ve sokaklarında', 'Canana can olmuş renkler,beyaz şehirde Çocukluğumun geçtiği,büyüdüğüm sokaklarda Yaramazlık yapıyorum,oynadığım yerlerde Şelale saçlı yaprak...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/beyaz-sehir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasaydın...', 'anlasaydin-i-brahim-ethem-bingul-ngdld', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey avcumdaki tohum

Cansız duran çekirdek

Toprağa düşmeye gör...

Düşenin dostu olmaz, deseler de

Şimdi bu toprak sana

Dost olacak

Ve hatta

Aşık sana, baksana...

Aşkını sunan toprak

Sarar, sarar gövdeni

Nem verir

Güven verir

Sana oksijen verir

Sonra eğilip sessiz

Fısıldar kulağına

Belki de bu bir emir

Çatlat çekirdeğini

Boyun göğe yükselir

Kesin, böyle der sana

Bu sevda

Anlasana...

Zaman hızla ilerler

Dediği olur bir gün

Köklerini kavrayan, saran bu kara toprak

Bağrını kanatarak

Sana saltanat verir

Gün yüzüne çıkartır

Bundan gurur duyarak...

Der ki: İşte eserim

Aşkım ve şaheserim

Ben aşkı sunmasaydım

Sen de benim kalbimde azıcık durmasaydın

Ey çekirdek senin sonun hiçlik olurdu

Yar, bunu anlasaydın...', 'Ey avcumdaki tohum Cansız duran çekirdek Toprağa düşmeye gör... Düşenin dostu olmaz, deseler de Şimdi bu toprak sana Dost olacak Ve hatta Aş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/anlasaydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak', 'uzak-cigdem-bir-genc-j0v8i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir adım ötede

Bir görünüp bir kayboluyor suretin

Gölgeler arasından gülümsüyorsun

Yabancı bir şehir gibi uzak

Uzak şehirler gibi yabancı...', 'Bir adım ötede Bir görünüp bir kayboluyor suretin Gölgeler arasından gülümsüyorsun Yabancı bir şehir gibi uzak Uzak şehirler gibi yabancı......', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uzak-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakikat', 'hakikat-orhan-tuncay-bs9wg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Konuştu Azrail:

Dedi ''Kalksın ayağa varsa bilen.''

Gök gürledi, şimşekler çaktı

Çıt yok, soluk yok yerde

Yalnızca ürperdi yeşil çimen.

''Bilen varsa kurtulur'' dedi,

''Cezadan, ıstırapdan, cehennemden.

Bilen varsa söylesin,

Söylesin hakikati hemen! ''

Bir kuş uçtu, Ebabil,

Mezarlığın üzerinden,

Gördü ölüleri,

Duyumsadı Azrail''i

Titredi yaşam sevinciyle

Düşündü: ''İnsanoğlu nasıl bilir,

Cenneti, cehennemi görmeden? 

İnsanoğlu anlatısa hakikati

Bağışlard onu Azrail.

Oysa Azrail iyi bilir

Hakikate eren için

Zaten ölmek, ölüme ölmek değil.', 'Konuştu Azrail: Dedi ''Kalksın ayağa varsa bilen.'' Gök gürledi, şimşekler çaktı Çıt yok, soluk yok yerde Yalnızca ürperdi yeşil çimen. ''Bilen...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hakikat-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkımız', 'sarkimiz-mustafa-ceylan-6tlqs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başının belâsı,

Gözünün elâsı,

Aşkının kölesi

Olurum, olurum...

	Uğruna, uğrunda

	Ölürüm, ölürüm...

Alnının yazısı,

Kalbinin sızısı,

Aşkının yıldızı

Olurum, olurum...

Uğruna, uğrunda

Ölürüm, ölürüm...

Başına aşk tacın,

Dudağa şarabın,

Derdine ilâcın

Olurum, olurum...

	Uğruna, uğrunda

	Ölürüm, ölürüm...

Hasreti dindiren,

Ateşin söndüren,

Başını döndüren

Olurum, olurum...

	Uğruna, uğrunda

	Ölürüm, ölürüm...', 'Başının belâsı, Gözünün elâsı, Aşkının kölesi Olurum, olurum... 	Uğruna, uğrunda 	Ölürüm, ölürüm... Alnının yazısı, Kalbinin sızısı, Aşkının...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sarkimiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Çeşitleme', 'sevgiliye-cesitleme-orhan-tuncay-40zlu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Diyorlar kül olmaz ateş yanmadan,

Denizler durulmaz dalgalanmadan''

Bakıp kendine düşlere dalma

''Güzelliğin (de)   on para etmez

Bu bendeki aşk olmadan! ''', '''Diyorlar kül olmaz ateş yanmadan, Denizler durulmaz dalgalanmadan'' Bakıp kendine düşlere dalma ''Güzelliğin (de)   on para etmez Bu bendeki ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgiliye-cesitleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bahçesine Uğra Bu Gece', 'gonul-bahcesine-ugra-bu-gece-mustafa-ceylan-ms7ct', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül bahçesine uğra bu gece,

Aşkın çiçeğini deriver gitsin.

Bir yıldız misali kayma ufkumdan

Gece ol, koynuna sarıver gitsin.

Gölgem ol, peşimden ayrılma sakın! 

Nasıl bıçağından ayrılmazsa kın? ! 

Ellerin bu kadar Ceylan’a yakın

Avcısın bilirim, vuruver gitsin.

Sıkıca kapat da açma perdeyi,

Unut dertlerini, unut her şeyi.

Bayram sabahına çevir geceyi

Gâribi, yetimi sarıver gitsin.

Kapılar, kapılar dursun sürgülü

Siyah saçın belik belik örgülü.

Mahzun gecelerin solmayan gülü

Dalımda goncalaş, duruver gitsin.

Usul usul yürü, ışığı söndür

Sarhoş et aşkınla, başımı döndür.

Gülmeyen bahtımı bir kere güldür,

Zevkten kahkaha at, gülüver gitsin! 

Benim ol, benim ol, benim ol artık! 

Yaktı ciğerimi zalim ayrılık.

Duyur nefesini hep ılık ılık

Uykumu yarıya bölüver gitsin.', 'Gönül bahçesine uğra bu gece, Aşkın çiçeğini deriver gitsin. Bir yıldız misali kayma ufkumdan Gece ol, koynuna sarıver gitsin. Gölgem ol, pe...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonul-bahcesine-ugra-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yumrukladım Saatleri', 'yumrukladim-saatleri-mustafa-ceylan-z7fqw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yumrukladım saatleri son defa

Eğdim, büktüm yelkovanı, akrebi.

Duvardaki takvim ile bir sefa

Süremedim... Yuvası çöp sepeti...

Seneleri, haftaları, ayları

Birer birer kurşunlayıp öldürdüm.

Tekmeleyip “gün” isimli tayları

Ufukların ötesini buldurdum...

Boyutları, ölçüleri yok ettim

Kuşak yaptım Ekvator’ u belime.

Sayıları defterlerden hep sildim

Beyaz aldım yaprakları elime.

İsyandayım, akıp giden zamana

Zerrelerin şarkısına hasretim.

Sonsuzluğun koynundaki divana

Çağırıyor içimdeki gurbetim...', 'Yumrukladım saatleri son defa Eğdim, büktüm yelkovanı, akrebi. Duvardaki takvim ile bir sefa Süremedim... Yuvası çöp sepeti... Seneleri, haf...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yumrukladim-saatleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Essin Deli Rüzgâr', 'essin-deli-ruzg-r-mustafa-ceylan-gwgm1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Essin deli rüzgâr, içimde yangın

Yalnızım, sensizim ah yanıyorum! 

Sardıkça ruhumu o güzel aşkın

Alevler içinde uyanıyorum...

Kışın ortasında bahar gibisin,

Beni benden alır ılık nefesin,

Billâhi sevdiğim sen de delisin! 

Hasrete sabırla dayanıyorum...

Essin deli rüzgâr, içimde deprem

Bu ayrılık değil korkunç cehennem...

Alevler içinde ufkum, çerçevem

Ateşin rengiyle boyanıyorum...

Gönül dağlarımda açan kardelen,

Simsiyah geceyi ortadan bölen.

Karşıma geçip de naz edip gülen

Doru tay, ben sana kıyamıyorum...

Essin deli rüzgâr, tüter dumanım

Gurbet ellerimde geçmez zamanım.

Sevdanla akıyor damarda kanım,

İnan ki, sevgine doyamıyorum...

Soğuktur geceler geçmek bilmiyor,

Ne kadar çağırsam yârim gelmiyor.

Gökten yağmur yağsa beni bulmuyor,

Nice bulut geçti sayamıyorum...

Essin deli rüzgâr, Ceylan ağlasın

Çıldırsın, yas tutsun, kara bağlasın.

Söyleyin gelmezse mektup yollasın

Bu sıra sesini duyamıyorum...

                             Beste: Mevlüde BUDAK', 'Essin deli rüzgâr, içimde yangın Yalnızım, sensizim ah yanıyorum!  Sardıkça ruhumu o güzel aşkın Alevler içinde uyanıyorum... Kışın ortasınd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/essin-deli-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman?', 'ne-zaman-mustafa-ceylan-6o7rn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bal arısı çiçeğe

Konar amma, ne zaman? 

Yanlış olan, gerçeğe

Döner amma, ne zaman? 

Yazılınca yazılar,

Gül doluyor asırlar.

Yüreğimden sızılar

Diner amma, ne zaman? 

Deli gönül aşk eri,

Bu kaçıncı seferi? 

Diyojen’ in feneri

Yanar amma, ne zaman? 

Bakma sakın halime,

Sarılmışım takvime.

Dudaklarda kelime

Donar amma, ne zaman? 

Dert kapladı özümü,

Döndüm sana yüzümü.

Sevda bağı üzümü

Sunar amma, ne zaman?', 'Bal arısı çiçeğe Konar amma, ne zaman?  Yanlış olan, gerçeğe Döner amma, ne zaman?  Yazılınca yazılar, Gül doluyor asırlar. Yüreğimden sızıl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-zaman-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gurbet Bu Ayrılık', 'bu-gurbet-bu-ayrilik-mustafa-ceylan-z8hf4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprağı çatlatan şey

Bu gurbet, bu ayrılık.

Yanardağ patlatan şey

Bu gurbet, bu ayrılık.

Çeşmenin gârip tası,

Beynimin haritası,

Bulutun ağlaması

Bu gurbet, bu ayrılık.

Yollara yıkan bizi,

Çileye sokan bizi,

Kudretten yakan bizi

Bu gurbet, bu ayrılık.

Dönmesi dünyamızın,

Özüdür duamızın,

Temeli sevdamızın

Bu gurbet, bu ayrılık.

Atın çifte tekmesi,

Göğün yeri öpmesi,

Ceylan’ ın yâr demesi

Bu gurbet, bu ayrılık.', 'Toprağı çatlatan şey Bu gurbet, bu ayrılık. Yanardağ patlatan şey Bu gurbet, bu ayrılık. Çeşmenin gârip tası, Beynimin haritası, Bulutun ağl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-gurbet-bu-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşı Balkonlar', 'karsi-balkonlar-mustafa-ceylan-tvklz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karşı balkonlarda söyleşip durur

Ayı gökyüzünden ayartıyor can.

Alıp hançerini bağrıma vurur

İy’olmaz yâremi kanatıyor can.

Karşı balkonlarda bülbül sesi var,

Bilemem kalbinde acep nesi var? 

Orada mutluluk burda yası var,

Ağlarım... Yüzümü morartıyor can.

Karşı balkonlarda gülün kokusu,

Koku değil sanki yârin uykusu...

Yusuf’ un düştüğü sevda kuyusu

Nerdedir? Söylemez, aratıyor can.

Karşı balkonlarda asılı mendil,

Yorgun penceremde yanmıyor kandil.

Ben inleyen hazan, o goncada gül

Hüzün yaprağımı kopartıyor can.

Karşı balkonlarda eğlence, cümbüş

Cadde ortasına yayılıp düşmüş.

Aslılar, Şirinler bahtıma küsmüş; 

Alın yazımızı karartıyor can.', 'Karşı balkonlarda söyleşip durur Ayı gökyüzünden ayartıyor can. Alıp hançerini bağrıma vurur İy’olmaz yâremi kanatıyor can. Karşı balkonlard...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karsi-balkonlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-mustafa-ceylan-hyjmq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül atı aşk dağına

Çıkar dedim, çıkmadı mı? 

Dostlar bir gün dudağına

Bakar dedim, bakmadı mı? 

Dağ omzuna alır güneş,

Yaylalarda tutsan güreş.

Su misali gökten ateş

Akar dedim, akmadı mı? 

Aşk doldursun kalbimizi,

Alsın gayri bizden bizi.

Bu sevda her ikimizi

Yakar dedim, yakmadı mı? 

Gönül atı dört naladır,

Ova gurbet, dağ sıladır.

Ayrılık başa belâdır

Yıkar dedim, yıkmadı mı? 

Ey Ceylan’ ım soru sorma! 

Deli tayı dağa vurma! 

Bir gün senden telli turna

Bıkar dedim, bıkmadı mı?', 'Gönül atı aşk dağına Çıkar dedim, çıkmadı mı?  Dostlar bir gün dudağına Bakar dedim, bakmadı mı?  Dağ omzuna alır güneş, Yaylalarda tutsan g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soru-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessüm', 'tebessum-mustafa-ceylan-t72qn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gamzede muhteşem gonca

Bir sevda çiçeği yüzde tebessüm.

Rahmet dalgasıdır ömür boyunca

Fıtratın dilidir özde tebessüm.

Ufuk çizgisine sarılan gençlik,

Sabır dağlarında yontulan çelik.

Gönül bahçesinde duran serinlik

Elmanın rengidir, yazda tebessüm.

Işık karanlığı nasıl boğarsa,

O güzel tabloda mutluluk varsa,

Hesabı, ölümü unutturmazsa

Hakk’ ın rızasıdır sizde tebessüm.

Sevda trenine alınan bilet,

On beşinde hayâl dolu bir gölet.

Yetmişlik ninede huzur, bereket

Gonca gonca güldür kızda tebessüm.

Yığınla çileyi silip süpüren,

Dışta huzur veren, içte köpüren.

Bayram sabahına alıp götüren

Muhabbet gülüdür bizde tebessüm.

Kahkaha nefsimin çılgın girdabı,

Tebessüm ruhumun sonsuz mehtabı.

Yunus çevirdikçe dertli dolabı

Çıkrık kolundaki izde tebessüm.

Rüzgârın dansıdır, koca deryada

Bir uzay dolmuşu olan dünyada.

Mevlâna’ ca dönüp duran Konya’ da

Ney’ de, kudümlerde, sazda tebessüm.', 'Her gamzede muhteşem gonca Bir sevda çiçeği yüzde tebessüm. Rahmet dalgasıdır ömür boyunca Fıtratın dilidir özde tebessüm. Ufuk çizgisine sa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tebessum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Var mı?', 'haberin-var-mi-mustafa-ceylan-um16r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yâr sunduğun şerbeti

İçtim, haberin var mı? 

Tırpan ile gurbeti

Biçtim, haberin var mı? 

Susamıştım sevgiye,

Sensin bana hediye,

Çileyi kaymak diye

Seçtim, haberin var mı? 

İki gözüm iki sel,

Yeter gayri durma gel! 

Seni bulmadan evvel

Hiçtim, haberin var mı? 

Buldum “Bizim Yunus” u 

İbadettir uykusu...

Zaman köprü, bende su

Geçtim, haberin var mı? 

Ceylan seni bulacak,

Bulup da kurtulacak...

Gönlümü köşe bucak

Açtım, haberin var mı?', 'Yâr sunduğun şerbeti İçtim, haberin var mı?  Tırpan ile gurbeti Biçtim, haberin var mı?  Susamıştım sevgiye, Sensin bana hediye, Çileyi kaym...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haberin-var-mi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus'' a Gidelim', 'yunus-a-gidelim-mustafa-ceylan-7nzo8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel ey vazoların süslü lâlesi! 

Gel ey gözlerimin top şelâlesi! 

Gel ey yücelerden gönül kalesi! 

Yunus’a gidelim, Yunus’a doğru! 

Ey karlı dağların koca bulutu! 

Dost bahçelerinin bal akan dut’ u...

Sevgi ülkesinin sonsuz hudutu

Yunus’a gidelim, Yunus’a doğru! 

Mekâna sığmayan “kimsesiz kimler”

Ben ağlarken bana gülen takvimler.

Ey zamanlar, ey seneler, iklimler! 

Yunus’ a gidelim, Yunus’a doğru! 

Dağların omzunda ışıktan çiçek,

Çocuk beşiğinden fışkıran gerçek.

Gel ey aynaları çıldırtan mercek! 

Yunus’ a gidelim, Yunus’a doğru! 

Ey dünya denilen uzay dolmuşu! 

Gurbet mektubunun efsane kuşu.

Dertli dolaplarda şakırdayan su,

Yunus’a gidelim, Yunus’a doğru!', 'Gel ey vazoların süslü lâlesi!  Gel ey gözlerimin top şelâlesi!  Gel ey yücelerden gönül kalesi!  Yunus’a gidelim, Yunus’a doğru!  Ey karlı ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yunus-a-gidelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçluları; Yönetenler', 'suclulari-yonetenler-ali-hamdi-eray-kiygk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ata sözü, söylemişler,

Balık baştan kokar diye.

Koktu,güzel memleketim,

Suçluları; yönetenler.

Devletimiz; borçlar ile,

Çaresizler; suçlar ile,

Bürokrasi; rüşvet ile,

Suçluları; yönetenler.

Politika; yalan ile,

İş hayatı talan ile,

Garibanlar; kalan ile,

Suçluları; yönetenler

Gençlerimiz, işsizlikle,

Hastalarsa; dişsizlikle,

Medya ise; yüzsüzlükle,

Suçluları; yönetenler.

Yönetenler; ilgisizdir.

İlgililer; bilğisizdir.

Bilgililer; sevgisizdir,

Suçluları; yönetenler.', 'Ata sözü, söylemişler, Balık baştan kokar diye. Koktu,güzel memleketim, Suçluları; yönetenler. Devletimiz; borçlar ile, Çaresizler; suçlar i...', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/suclulari-yonetenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-necmi-unsal-a1ama', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yollar  vardır,  götürür  visâle.

Yollar  zordur, götürür  fisâle.

Yollar  yoldur, götürür  necâta.

Yollar  kandır, götürür  memâta.

11 Mart 2004 Perşembe, Danimarka-Køge  14.30

2+2+3+3', 'Yollar  vardır,  götürür  visâle. Yollar  zordur, götürür  fisâle. Yollar  yoldur, götürür  necâta. Yollar  kandır, götürür  memâta. 11 Mart...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yollar-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Destan Atatürk', 'destan-ataturk-mustafa-ceylan-xqbju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kağnıyla çileyi avuçta tutup,

Türklük ateşini içine katıp,

Allah Allah diye destan yaratıp

	Yeniden dirilen vatan Atatürk,

	Tarihe sığmayan destan Atatürk.

Bismillâh! Ya Mevlâ’ m! Açılsın çağım

Yüksekten fırlayan Türk denen çığım,

İyi dinle, işit, hisset çocuğum! 

	Nabzını ruhunda tutan Atatürk,

	Tarihe sığmayan destan Atatürk.

Dağ başından dumanları süpüren,

Nice yüzyılları önceden gören; 

Her an içimizde yaşıyorsun sen! 

       Coşalım İzmir’den, Kars’tan Atatürk,

       Tarihe sığmayan destan Atatürk.

Kuruyan toprağa yağmursun yağan,

Güneşsin Samsun’ da ufuktan doğan,

Boğan, kör geceyi kabında boğan

         Yurt diye patlayan volkan Atatürk,

          Tarihe sığmayan destan Atatürk.

Bilimsin, tekniksin, vatan türkümsün

Sevgisin, barışsın bitmez ülkümsün.

Şöyle bir bakıver, yüzümüz gülsün! 

          Yurdu kucaklayan insan Atatürk,

          Tarihe sığmayan destan Atatürk.

Tutuşan yürekte bayrak alısın,

İnsan sevgisiyle öyle dolusun.

Dünyanın başında zeytin dalısın,

         Zerreden kürreye umman Atatürk,

         Tarihe sığmayan destan Atatürk.', 'Kağnıyla çileyi avuçta tutup, Türklük ateşini içine katıp, Allah Allah diye destan yaratıp 	Yeniden dirilen vatan Atatürk, 	Tarihe sığmayan ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/destan-ataturk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samsun'' dan Doğan Güneş', 'samsun-dan-dogan-gunes-mustafa-ceylan-nghsm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yurduma ışık saçtı

Samsun’ dan doğan güneş.

Göklere bayrak açtı

Samsun’ dan doğan güneş.

Yeşertti yaprağımı,

Güldürdü bayrağımı,

Kurtardı toprağımı

Samsun’ dan doğan güneş.

Yurttan düşmanı attı,

Ufkumu aydınlattı,

Devrimleri anlattı

Samsun’ dan doğan güneş.

Başladı ta en baştan,

Güller çıkardı taştan,

Yazdırdı şanlı destan

Samsun’ dan doğan güneş.

Dağıttı bulutları,

Ağarttı ufukları,

Işıttı hudutları

Samsun’ dan doğan güneş.

Düşmana hesap sordu,

Şahlandı ordu ordu,

Yeni bir meclis kurdu

Samsun’ dan doğan güneş.

Dağları dümdüz etti,

Geceyi gündüz etti,

Tarihe bir söz etti

Samsun’ dan doğan güneş.', 'Yurduma ışık saçtı Samsun’ dan doğan güneş. Göklere bayrak açtı Samsun’ dan doğan güneş. Yeşertti yaprağımı, Güldürdü bayrağımı, Kurtardı to...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/samsun-dan-dogan-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bakmadın', 'bana-bakmadin-mustafa-ceylan-gv2dm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ciğeri beş para etmez adama

Öptürdün de yavru, bana bakmadın.

Bütün gençliğini, umutlarını

Kaptırdın da yavru, bana bakmadın.

Yüzüne gülene eğilip baktın,

Aşık oldu sandın, gözyaşı döktün.

Deli tay gibiydin, bak nasıl çöktün? 

Yıkıldın da yavru, bana bakmadın.

Meydan okuyordun aya ve güne

Süslenip giderdin her bir düğüne.

Paslı bir çiviyle aşk kütüğüne

Çakıldın da yavru, bana bakmadın.

Gördüm, kar yağıyor dertli döşüne

Yıllar kurşun sıkar, garip başına.

Koşar deyip, topal atın peşine

Takıldın da yavru, bana bakmadın.

Arılar sen varken yapmazdı balı,

Cümle gençlik derdi: “Benim olmalı! ”

Sevgisiz ellerde limon misali

Sıkıldın da yavru, bana bakmadın.

       

Beste: Şenol YAĞAR', 'Ciğeri beş para etmez adama Öptürdün de yavru, bana bakmadın. Bütün gençliğini, umutlarını Kaptırdın da yavru, bana bakmadın. Yüzüne gülene ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bana-bakmadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-huseyin-cayikli-rcnt4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne zaman o türküyü dinlesem

aklıma senin yüzün 

ve hayata sarılmış bir çocuk gelir

şimdi sana sesleniyorum

neredesin ey güzel insan', 'ne zaman o türküyü dinlesem aklıma senin yüzün  ve hayata sarılmış bir çocuk gelir şimdi sana sesleniyorum neredesin ey güzel insan...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/insan-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayyıldız', 'ayyildiz-sule-aydemir-5k11w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '_____________________________________Ayyıldız ''a

sinirlenmedim bu gün

hiç ağlamadım

tırnaklarım 

deldi avuçlarımı 

gülümsedim

ağlamadım 

bu gün

kavak yellerime 

kurutturdum

göz yaşlarımı

bir yer maviye 

bir gök beyaza 

baktım

gerektiğinde 

ayva çiçeğini ağlattım

ağlamadım

öldüm yanarak

döküldüm otuz

bir yaprak 

serildim 

göz aldı küllerim

ben ağlamadım

çırılçıplak doğdu

ağladı dirilişim', '_____________________________________Ayyıldız ''a sinirlenmedim bu gün hiç ağlamadım tırnaklarım  deldi avuçlarımı  gülümsedim ağlamadım  bu ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayyildiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balpeteğim', 'balpetegim-mehmet-engin-38ux7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben senin gözlerini özlüyorum balpeteğim

rengini pırıltısını derinliğini özlüyorum

kirpikler arasında kaybolup var olan

bakışlarındaki manayı özlüyorum

ben senin gülyüzünü özlüyorüm balpeteğim

çocuksu masumiyetini saflığını özlüyorum

gülünce yanağındaki gamzeyi

dudağındaki tatlı tebessümü özlüyorum

ben senin gülüşünü özlüyorum balpeteğim

ahengini coşkuyu özlüyorum

bir başka güzel oluyorsun bir başka sevdalı

şen şakrak tavırlarını özlüyorum

ben senin ellerini özlüyorum balpeteğim

saçlarımı okşayan avuçlarındaki sıcaklığı

ellerime kenetlenen ellerini

yüzümde dolaşan parmaklarını özlüyorum

ben seni sende özlüyorum balpeteğim

seviyorum derken titreyen dudaklarını

öptüğümde kızaran yanaklarını özlüyorum

suskun, suskun konuşan bakışlarınla

hayatımdaki varlığını özlüyorum

ben seni sende özlüyorum balpeteğim

seni sende özlüyorum.', 'ben senin gözlerini özlüyorum balpeteğim rengini pırıltısını derinliğini özlüyorum kirpikler arasında kaybolup var olan bakışlarındaki manay...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Engin']::text[], 8.5, '{"poet":"Mehmet Engin","poet_slug":"mehmet-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/balpetegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfır', 'sifir-bahadir-yurteri-mqs95', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir hiçim hiç saydın mı...

Kaç sıfır ettiğimi? 

Yokluğunda tükenip,

Günbe gün bittiğimi? ! 

Yandığımı hiç bildin mi

Bir yağmur damlası ile

Aynı yanaktan aşağı

Süzülüp gittigimi? 

El gibi bakışlarda,

Bilindik şarkılarda,

Gökyüzünde havada,

Silinip gittiğimi...

Peşin sıra kuşlarla...

Bir gurbete, bir sılaya...

Yırtık kanatlarımla

Çırpınıp gittiğimi

Sensiz hiçim hiç saydın mı...

Kaç sıfır ettiğimi? !', 'Ben bir hiçim hiç saydın mı... Kaç sıfır ettiğimi?  Yokluğunda tükenip, Günbe gün bittiğimi? !  Yandığımı hiç bildin mi Bir yağmur damlası i...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Yurteri']::text[], 8.5, '{"poet":"Bahadır Yurteri","poet_slug":"bahadir-yurteri","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sifir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdâ Sepeti', 'sevd-sepeti-bahadir-yurteri-emotn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaralarım niye bunca ağır; 

Kaç yürek var karşı kefede? 

Beş para etmez mi anılar? ! 

Neyse, neyse...

Koy sepete.', 'Yaralarım niye bunca ağır;  Kaç yürek var karşı kefede?  Beş para etmez mi anılar? !  Neyse, neyse... Koy sepete....', ARRAY['Türk Edebiyatı','Şiir','Bahadır Yurteri']::text[], 8.5, '{"poet":"Bahadır Yurteri","poet_slug":"bahadir-yurteri","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevda-sepeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karagözlüm', 'karagozlum-mehmet-engin-l61kz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Veda ederken saramadım doyasıya

Başını göğsüme koyamadın be karagözlüm

Bakışlarında hüzün, yüreğimde acın kaldı

Bir buse bile veremedin be karagözlüm.

Sen gittin, istanbul sessiz, istanbul yasta

Yürüdüğün kaldırımlar seni arıyor, seni özlüyor

Sahilde martıların çığlıkları sensizliğe

Hüzünlü şarkılar senin için be karagözlüm.

Mehtap seninle veda etti istanbula

Geceler zifiri karanlıktan daha kara

Güneş kırgın bakıyor bulutlara

Sağnak yağmurlar senin için be karagözlüm.

Sen gittin ya neşem tadım yok benim

Her lokmada hasret, her yudumda sensizliği içiyorum

Yolun sonu demiştim başa döndürdün

Sevmeye paydos,yanlızlığa kucak açarken

Nefretimi tutkuya döndürdün be karagözlüm

Sana tapmak günah ise cehenneminde yanmaya hazırım

Seni sevmek suç ise uğruna ölmeye hazırım

Bana sabırla beklemeyi öğrettin

Bana özlemi hasreti sevdirdin

Beni benden alıp gittin de karagözlüm

Sensiz yaşamayı  yanlızlığı öğrettin.

den', 'Veda ederken saramadım doyasıya Başını göğsüme koyamadın be karagözlüm Bakışlarında hüzün, yüreğimde acın kaldı Bir buse bile veremedin be k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Engin']::text[], 8.5, '{"poet":"Mehmet Engin","poet_slug":"mehmet-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/karagozlum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlişki', 'i-liski-gokhan-oflazoglu-yup8u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlişki var mıdır gerçekten, korkularımız

acılarımız örtmüş. Sur dibinde açan

güller gibi yüreğimizi açarız ya da 

öyle zannederiz. Duvarlardan 

anlamamış gülücüklerle çevrili

kızgın yağ dökülür üstüne, 

biz ilişki kurduğumuzu sanırız.

Birbirimize dair fikirlerimiz örtmüş.

İlişki nafile bir çabadır ömrümüzde.

08/04/2004', 'İlişki var mıdır gerçekten, korkularımız acılarımız örtmüş. Sur dibinde açan güller gibi yüreğimizi açarız ya da  öyle zannederiz. Duvarlard...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iliski-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-ahmet-fahri-sezgin-rm21d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzakta açtı güller hep, görmeden

Zaman durdu, hayat durdu yıllarca

Ufuğun ardında ancak birleşebildi

Yer ve gök

Uzak bir zamanda kaldı gerçekler

Ve çocukça merakların ışığı

Kestim ümidimi, çıktım sessizce

Dünyadan', 'Uzakta açtı güller hep, görmeden Zaman durdu, hayat durdu yıllarca Ufuğun ardında ancak birleşebildi Yer ve gök Uzak bir zamanda kaldı gerçe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Fahri Sezgin']::text[], 8.5, '{"poet":"Ahmet Fahri Sezgin","poet_slug":"ahmet-fahri-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yolculuk-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sidoma', 'sidoma-nuri-sedat-o306g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben deli deli akan bir nehir

Sen ise fırtınalı bir salkım söğüt

Ben ulaşmak için sana

Ne engeller, ne barajlar aştım

Coştum, köpüklere boğuldum

Seni sardım, liflerinde dolaştım

Yeşilin en koyusu, lacivertin en derini oldum 

Dallarına gökkuşağını doladım

Sen ise sağlamlaştırdın kendini

Toprağın daha derinine kök saldın

Bulutları seyrettin, düşlere daldın

Rüzgara yapraklarını bıraktın

Hoşuna gidendi uymak rüzgara

Heyecanıydı belki de yakalayan seni

Sidoma, Sen ve Ben

Ben durgun akan bir nehir

Sen ise dingin bir salkım söğüt

Yağmurlar dindi, ben kurudum

Yıllar geçti, sen ise soldun

Ama tükenmedi umutlar hala', 'Ben deli deli akan bir nehir Sen ise fırtınalı bir salkım söğüt Ben ulaşmak için sana Ne engeller, ne barajlar aştım Coştum, köpüklere boğul...', ARRAY['Türk Edebiyatı','Şiir','Nuri Sedat']::text[], 8.5, '{"poet":"Nuri Sedat","poet_slug":"nuri-sedat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sidoma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi', 'yedi-mustafa-ceylan-or2ww', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saklanmış göklerin dipsiz ufkuna

Görüyorum ancak çözemiyorum.

Dolanmış, sarılmış gök kuşağına

Bir beyaz kâğıda çizemiyorum.

Ben doğmadan önce toprağa sinmiş

Arzın merkezine koşarak inmiş,

Bana da, sana da kabir bilinmiş

Nice âlet ile kazamıyorum.

Fatiha içinde gizlenmiş bir sır

Ömür takviminde gündür, haftadır.

Cümle âlemler de aynı saftadır

Onunla dizilmiş bozamıyorum.

Baktığım her yanda karşıma çıkar,

Bu aciz Ceylan’ ı yollara yıkar

Hem döner, hem yanar, hemi de akar

Basit mantığımdan süzemiyorum.', 'Saklanmış göklerin dipsiz ufkuna Görüyorum ancak çözemiyorum. Dolanmış, sarılmış gök kuşağına Bir beyaz kâğıda çizemiyorum. Ben doğmadan önc...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yedi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tefekkür', 'tefekkur-mustafa-ceylan-0dczr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çevir başın şu göklere bak gönül

Katman katman yedi göğü gör hele.

Aşk mumunu düşüncene yak gönül

Katman katman yedi göğü gör hele.

Yakın göğe ad vermişiz atmosfer

Bu atmosfer dünyamızı çok sever

Yedi gaz var, ozon deler, yer çeker

Katman katman yedi göğü gör hele.

İkinci kat: Yıldız, kevkeb isimli

Güneş ile, gezegenle resimli

Yörüngede dizi dizi takvimli

Katman katman yedi göğü gör hele.

Üçüncüsü, galaksinin katmanı

İlâhi aşk işareti sarmalı

Kalp gözüyle novalara girmeli

Katman katman yedi göğü gör hele.

Dördüncüsü, burçlar ile donanmış

Kendisini yaratana inanmış

İnsanların hallerine ağlamış

Katman katman yedi göğü gör hele.

Beşincisi, gözlem ufku  süsümüz

Süper küme, zikir yapan özümüz

Umudumuz, hayâlimiz, sözümüz

Katman katman yedi göğü gör hele.

Altıncısı, gözlem ufku ötesi

Mükemmeldir, bulunamaz hatası

Görülmeyen mülti-medya galaksi

Katman katman yedi göğü gör hele.

Yedincisi, çözülmemiş son uzay

Kitabımda tariflenmiş bir saray,

Sen bunları göremezsin vay ki vay! 

Katman katman yedi göğü gör hele.

Yedi göğe bir merdiven kurmalı

Her adımda melekleri saymalı

Gözü açıp nesin başın kırmalı

Katman katman yedi göğü gör hele.', 'Çevir başın şu göklere bak gönül Katman katman yedi göğü gör hele. Aşk mumunu düşüncene yak gönül Katman katman yedi göğü gör hele. Yakın gö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tefekkur-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tefekkür Yolu', 'tefekkur-yolu-mustafa-ceylan-ihj8g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçaktır, füzedir kuşun kanadı

Bal yapmak arının ince sanatı

Tefekkür yolunda ey gönül atı

                  Dörtnala şahlan da görelim seni

                  Sonsuz ovalara verelim seni.

Bir damla hakikat cihana değer

Bunca gördüklerim yalanmış meğer

Tefekkür yoluna düşersen eğer

                  Varıp terminale soralım seni

                  Aşk şehri yolunda yoralım seni.

Tohuma, dağlara yazılmış âyet

Böcekten, çiçekten etme şikâyet

Tefekkür yoluna gelirsen şayet

                  Kır çiçeği gibi derelim seni

                  Hakikat ehline verelim seni.

Düşmüş okyanuslar ilâhi aşka

Ufuklar bir başka, öteler başka

Tefekkür yoluna düşeydin keşke

                  Suya perde perde gerelim seni

                  Yağmur bulutuyla serelim seni.

Kendi benliğini aşarsan bir gün

Maddiyat kabından taşarsan bir gün

Tefekkür yoluna düşersen bir gün

                   Vurup dost taşına kıralım seni

                   Kutsi ilâçlarla saralım seni.

Zindana tıkarsan pörsümüş dili

Yakarsan gönlüne nurdan kandili

Tefekkür yolunun olursan gülü

                  Koklasın, koklasın maralım seni

                  Sır gibi saklasın Ceylan’ ım seni.', 'Uçaktır, füzedir kuşun kanadı Bal yapmak arının ince sanatı Tefekkür yolunda ey gönül atı                   Dörtnala şahlan da görelim seni ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tefekkur-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhasebe', 'muhasebe-mustafa-ceylan-k7h2s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya bir imtihan salonu gibi

Nefsimle savaşın alanı gibi

Cümle hesapları vermeden yarın

Patlasın gönlümün balonu gibi.

Yanlış hesaplara gitmesin elim

Günah zehirli bal, tatmasın dilim

Topl, çıkar, çarp, böl yarım sayfalar

Her sayfa sonunda görünür ölüm.

Topladım, çıkardım ölüm karşımda

Azrail’ de gezer durur çarşımda

Biter muhasebe, firakım biter

Hasretliğim dile gelir şarkımda.

Sancılar sancılar, bitmez sancılar

Her sancı ruhumu ezer, kamçılar

Söyle söyle Ceylan, bugün ne yaptın? 

Diye soru sorar bana hancılar...

Hesap hesap hesap; sonsuz hesaplar

Gönlümü, beynimi, ufkumu kaplar

Şimdi karanlık bir uçurumdayım

Bize yol gösterir kutsal kitaplar.

Yollar var, dağları dolanan yollar,

Yollar, yollara ulanan yollar

Çekiyor çekiyor beni kendine

Bir mıknatıs gibi gül olan yollar.

Ölmeden ölmek var, gülmeden gülmek

Gönüllerden damla damla dökülmek

Sevda dediğimiz koca cihana

Yanardağ misali aşkı püskürmek.

Bir cetvel, bir kantar, ya da terazi

Tartılır, tartılır bugünle mazi

Tarlaya tohumlar ektiysen eğer

Başaklara gebe bütün arazi...

Nefsim nefsim nefsim: Kokmuş nefesim

Ya hesap yanlıştır, ya yanlış sesim.

Direnme boşuna, ölüm mukadder

Toprak yatağımız, toprak nevresim.

Ey Ceylan bilesin ömür imtihan

Neye yarar senin olsa da cihan? 

Bir yola çıkmış da elde meşale

Gel diyor, gel diyor güzel nevcihan.', 'Dünya bir imtihan salonu gibi Nefsimle savaşın alanı gibi Cümle hesapları vermeden yarın Patlasın gönlümün balonu gibi. Yanlış hesaplara git...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/muhasebe-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Ağlar', 'kan-aglar-mustafa-ceylan-gylde', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bahçıvan bülbülü kovdu kovalı

Bağımda, bahçemde güller kan ağlar.

Ölü evine döndü gönül sarayım

Ah eder, vah eder; diller kan ağlar.

Büktü de boynunu inim inim inler saz

Hüzün dalgasına dönüşünce haz,

Sanki kış mevsimidir, dallarda ayaz

Bülbülsüz yapraklar, dallar kan ağlar.

Ne vardı apansız çekip gidecek? 

Bülbül yok işte, kim var ötecek? 

Bu acı yüzünden açmıyor çiçek,

Maviler, yeşiller, allar kan ağlar.

Gün gelir, umudun yere dökülür

Gün gelir, göğsünden dikiş sökülür

Gün gelir, senin de boynun bükülür

Ağıt düzer ağzın, diller kan ağlar.', 'Bahçıvan bülbülü kovdu kovalı Bağımda, bahçemde güller kan ağlar. Ölü evine döndü gönül sarayım Ah eder, vah eder; diller kan ağlar. Büktü d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kan-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Haklısın', 'sen-haklisin-mustafa-ceylan-sayoa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben istedim bırakıp da gitmeni

Haklısın, haklısın gelmemekte haklısın.

Pişman oldum, geriye dön desem de

Selâm bile vermemekte haklısın.

Kurtulurum derken, pençene düştüm

Düştüm de aşk-ı ateşinde yanarak piştim

Hasretinle inan öyle değiştim

Düşlerime girmemekte haklısın.

Bağırdım, çağırdım, defol git dedim

Bana ne, sokakta ister yat dedim,

Bir yıllık defteri tut kapat dedim

Açılan sayfayı görmemekte haklısın.

Şimdi pişmanım, heyhat çare bulamam

Kesilir nefesim, ölsem ölemem

Adın yüreğimde asla silemem

Hatırımı sormamakta haklısın.

Ceylan bazen deliriyor, bilmem ki neden

Duyar mısın, özür dilese senden

Dağ dağa kavuşur elbet yeniden

Sen beni sarmamakta haklısın.', 'Ben istedim bırakıp da gitmeni Haklısın, haklısın gelmemekte haklısın. Pişman oldum, geriye dön desem de Selâm bile vermemekte haklısın. Kur...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-haklisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek miydi, Neydi ki O?', 'melek-miydi-neydi-ki-o-mustafa-ceylan-bhp0v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Akbaba elinde durmaz güvercin...-

Beni benden alıp gitti

Acaip bir şeydi ki o! 

İnan ki canıma yetti

Melek miydi, neydi ki o? 

	Bakışıyla vurdu beni,

	Saat saat kurdu beni,

	Elleriyle sardı beni

	Melek miydi neydi ki o? 

Başına poşu bağlamış,

Belli ki yanmış, ağlamış.

Kolun boynuma dolamış

Melek miydi, neydi ki o? 

	Parmakları pamukçaydı,

	Zehir verse sanki çaydı,

	O güzel benim olsaydı

	Melek miydi, neydi ki o? 

Boyu fidan, vücudu hoş

Kokusundan oldum sarhoş

İki gözüm şimdi sel, yaş

Melek miydi, neydi ki o? 

Bir göründü, bir yok oldu

Kirpikleri ok ok oldu,-

Yüreğimde bayrak oldu

Melek miydi, neydi ki o? 

Usulca dedi adımı,

Duydu da aşk feryadımı,

Bilmem ki kimin kadını? 

Melek miydi, neydi ki o? 

Ceylan’ ını serdi yere

Göz değil sanki pencere

Olsaydı derdime çare

Melek miydi, neydi ki o?', '-Akbaba elinde durmaz güvercin...- Beni benden alıp gitti Acaip bir şeydi ki o!  İnan ki canıma yetti Melek miydi, neydi ki o?  	Bakışıyla v...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/melek-miydi-neydi-ki-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakikat', 'hakikat-mustafa-ceylan-7uhsg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gerçek yüzünü gösterdin bugün

Maske düştü, sır döküldü işte

Sakladın, sakladın bu güne dek,

Bir fıskede patladın işte...

Ortalık toz duman

Of aman, aman! ! ! 

Yuvasız kuş sanıyordum

Dalıma konsun istedim, yanılmışım

Perde kalktı, herşey

Gün gibi ortaya çıktı.

Tam bir yıl avuttun beni, tebrikler

Ama bütün bunlar, canımı sıktı

Haberin olsun, bitti zaman

Of aman, aman! ! ! 

Alnına vurulmuş yazın, doğruymuş

Söyleyen doğru, dosdoğru demiş

Bu ceylan mı? Bu ceylan nasıl aldanmış

Şimdi anlamış, naneyi yemiş? 

Çünkü oyun bitti, başımda duman

Of aman, aman! ! ! 

Şiir yazmıyorum onun için

Her şey tamam! ! !', 'Gerçek yüzünü gösterdin bugün Maske düştü, sır döküldü işte Sakladın, sakladın bu güne dek, Bir fıskede patladın işte... Ortalık toz duman O...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hakikat-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Haber Ver', 'bir-haber-ver-mustafa-ceylan-rvcbj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne adresin belli, ne de telefon? 

Elin varmaz, aramazsın bir tanem.

Gelen gider, zaman geçer, gelir son

Sen beni de soramazsın bir tanem.

Bir haber ver, neredeysen, nasılsan? 

Bir haber ver, suret değil asılsan! 

Santim santim, milim milim kesilsen

Şu gönlümü kıramazsın bir tanem.

Kaçıyorsun neden böyle uzağa? 

Düşmeyesin bir hileye, tuzağa? 

Tebessümü yapıştırıp dudağa

Şu yaremi saramazsın bir tanem.

Bir haber ver, telefon et, alo de! 

Deliriyom, çıldırıyom gitgide

Unutursan adımı da belki de

Rehberlerde göremezsin bir tanem.

Avcı mısın bu Ceylan’ ı vurursun? 

İnat edip cesedini sürürsün...

Sen de bir gün karşılığın bulursun

Yüreğime giremezsin bir tanem.', 'Ne adresin belli, ne de telefon?  Elin varmaz, aramazsın bir tanem. Gelen gider, zaman geçer, gelir son Sen beni de soramazsın bir tanem. Bi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-haber-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüm Sana', 'kustum-sana-mustafa-ceylan-1f7r2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sakın ola dönüp bakma yüzüme

Gül misali soldurdun ya sen beni.

Karıncaydım ayak bastın üstüme

Minnacıktım öldürdün ya sen beni.

Aşk dağından rüzgâr olup esmişim

Kes demişsin, irtibatı kesmişim; 

Dönme sakın, billâh sana küsmüşüm

Yâd ellere güldürdün ya sen beni.

Yalvarsan da, yakarsan da nafile

Bunca zaman gösterdiğin hep çile

Can evimde bulunmazken bir hile

Ham meyveydim oldurdun ya sen beni. 

Üç kuruşa satıverdin neyleyim? 

Bir romandır savurduğum hey, hey’im

Sana burdan bir gerçeği söyleyim

Boş çuvala doldurdun ya sen beni.

Gecekondun nasıl acep güzel mi? 

Sevdiceğin benim gibi özel mi? 

Bu ceylan! ın bundan böyle hep el’ mi? 

Yaprak yaprak yoldurdun ya sen beni.', 'Sakın ola dönüp bakma yüzüme Gül misali soldurdun ya sen beni. Karıncaydım ayak bastın üstüme Minnacıktım öldürdün ya sen beni. Aşk dağından...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kustum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerit Koptu', 'serit-koptu-mustafa-ceylan-jcjut', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne gelişe biz karar verdik

Ne gidişe...

Senden geldik, sana varıyoruz işte...

Şerit koptu kopacak

Başım dönüyor, titriyor titriyorum

Aslında yalın kılıç korkularım var,

Şah damarımdan yakınsın biliyorum

Eridim ya sevginde, sen bilirsin! 

Tabut saray, kabir bahçe

Şiir mi? 

Kâğıt kâğıt, bohça bohça...

Salkım söğüt saçlı bir güzele

Emânet ettim cümle mısralarımı,

Sahip çıkaydı keşke! ..

Ne gelişe biz karar verdik, ne gidişe

Senden geldik, çağırdın, geliyoruz işte...

Ağır geliyor göz kapaklarım

Yüzüm bile fazla yüzüme...

Oturmuşum bir de yazarım içimden geçenleri,

Kopmak üzre şerit, yaş elliye gelmeden

Kitaplarım yâdigâr kalsın torunlarıma

Dedelerinden...

Başım dönüyor, bu kahrolası başım

Bitti bunca derdim, bunca şarkım, 

Haber salın ahbapların hepsine

Şerit koptu, kopacak! 

Kokmasın naaşım! ..

Benden sonra belki yeter

Emekli maaşım...', 'Ne gelişe biz karar verdik Ne gidişe... Senden geldik, sana varıyoruz işte... Şerit koptu kopacak Başım dönüyor, titriyor titriyorum Aslında...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/serit-koptu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-yasar-okcu-b9frt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüm

Ruhumun kapıları açıldı; 

Hayallerim çürümüştü, sevgilerim ise gizlenmişti

Karanlığı özümsemiş yaşayan ölüydüler artık

Hüzün ve korku, hatta sevgilerim,

Unutulmuş,

Kaybolmuş...

Kışın dondurucu soğuğunda bırakılmış küçük bir çocuk gibi,

Donuk gözlerle ardımdan bakan anılarım,

Ölüme terkedilmiş...

Donuk gözlerle ardımdan bakan anılarım,

Alacakaranlığı yaşıyorlardı artık,

Tek çabaları ölmeye çalışmaktı.

Unutulmuştular,

Sonsuza akıyorlardı...

Savaştan çıkmış gibi darmadağındılar

Yaralıydılar,

Yaralanmış çocuklarımdılar,

Çaresizdim onlar gibi,

Kurtaramadım onları kendim gibi...

‘’Umut’’ soyutluğunu bile yitirmişken

Perdeleri aralamak niye.

Geride anlamsız bir yaşam kaldı sadece

Savaşlarda bırakılmış çocuk gözleri

Sıcaklığından habersiz bir beden

Ve duygularından sıyrılmış bir beyin...

Her şey soğuktu,

Donuyordum gitgide,

Paramparça hayallerim,

Sonsuza akıyorlardı umarsızca...

Bir kibrit alevinin sıcaklığı kalmıştı sadece..! 

Isıtsın isterdim yüreğimi

Sıcacık,

Yaşatsın isterdim,

Kurtarmak istediğim yanımı...

Sevgilinin yüreğinde yaşamak istedim

Yaşamı gözlerinde,

Sıcaklığı teninde...

Dağları, vadileri yürümek istedim

Gözyaşı gibi sıcacık,

Gökyüzü kadar sonsuz,

Okyanuslar kadar derin.

Saçların rüzgarın asiliğine direnirken

Teninin kokusunu hissetmek isterdim

Yaşamak gibi.

Kuralların gereksizliğine mi yetersizliğine mi yanmalı

Ya da doğallık denen yalanın varlığına mı? 

Anlatamamak galiba beyinleri silikleştirip yalnızlaştıran

Ve korkudur bizi doğal olandan uzaklaştıran.

Kabullenemeyiz korkmayı, uzaklaşırız sadece; 

Bizleri boğacak sandığımız mutluluklardan,

Bizim biz olmamızı sağlayan doğaldan...

Gideriz, uzaklaşırız sadece,

Güneşin yeniden doğacağını sandığımız başka diyarlara.

Başka bir yönden güneşin doğacak sanırız,

Bizim olacak sanırız, olmaz

Sanırız sadece

Çaresizce uğraşıp durmak işte yaptığımız şey.

Ama ölürüz yinede yaşadığımızı sanarak,

Körelip giderek,

Ardımızda ölüm bırakarak...

Yaşam anlamını çoktan öldürdü mü gerçekten...

Yokluk ile varlık aynılaştı belki de,

Ölüm doğallaştı aslında yalnızlık gibi.

Ama yine de; 

Ölmek için yaşamak ilginçtir be dostum,

Dünde kalanlar,

Geleceğe taşınamayanlar,

Tutsak edilmiş mutluluklar,

Ve diğerleri...

Dün denen şey; 

Unutmak istediğimiz yalnızlığımız,

Yalnızlık da F tipi bir ölüm...

Yaşanacak mı toprak rengi gözlerinde mutluluk,

Unutulacak mı buğday sarısı teninde ölüm,

Başka baharlara mı erteleyeceğiz güneşin doğuşunu,

Yitip gidecek miyiz yine yaşamla ölüm arasında.

Çaresi olmayan,Issızlığı yaşayan ölüler gibi...

Hep donuk gözlerle mi bakacağız aydınlanacak güneşe,

Yaşamın diğer renklerine dönüp siyah-beyaz yaşamak gibi...

Ama yinede ’’şiir tadında’’ yaşayacağım öldürdüğüm yaşamı…', 'Ölüm Ruhumun kapıları açıldı;  Hayallerim çürümüştü, sevgilerim ise gizlenmişti Karanlığı özümsemiş yaşayan ölüydüler artık Hüzün ve korku, ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Okçu']::text[], 8.5, '{"poet":"Yaşar Okçu","poet_slug":"yasar-okcu","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/olum-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Karpuzu', 'zaman-karpuzu-mustafa-ceylan-seq1y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu soğuk havalarda çatladı

Zaman karpuzu...

Göbeği kesildi mutlulukların

Kalmadı, kalmadı ey yüreğim

Yaşamanın tadı-tuzu...

Saatler, bozuk saatler kaldı ellerimde

Nasıl yakalar, nasıl söyle bana? 

Kör atlar, bulutlar ötesine

Uzanan sonsuzu? ..

Doğduk toprak damlı köy evinde

Tahta beşiklerde büyüdük ninnilerle

Okuduk, diploma için; çıktık basamak basamak

Acılar tezgâhında dokuduk, gönül kilimini

Gülmedi bahtımız

Evlendik çoluk çocuğa kavuştuk

Gölge misal takipçimiz oldu kör olası şansımız

Gün oldu karanlıkta bulamadık yolumuzu

Dost dedik, düşman çıktı karşımıza

Yuvarlandık, kader yokuşundan aşağı

Yuvarlandıkça

Çatladı ömür karpuzu...

Kızımız gelin oldu, iki torun verdi bize

''Batuhan'' yaman mı yaman

''Aslıhan'' güzel gözlü ceylan...

Everdik oğlanı, bir torun da ondan

“Dede” sözcüğünü duydum ya ''Çağlasu'' dan

Dünyalar benim oldu

Allah’ ı var, şikâyetim yok

Gelinden, damattan...

Geriye ''Pınar'' kaldı bizimle

Okul yolunda dilerim başarılı olur! 

Şimdi, üç otuz emekli maaşına talim ederim

Şimdi, göğe açık ellerim,

Koskoca bir kelim...

Geçim derdi, seçim derdi derken

Nice ihanetler gördüm, yaşadım, duydum

Daha nicelerini hissedecğim can çekirdeğimde

Şu an mısra kuyumcusuyum, yapayalnız

Gurbet ellerde...

Düştük, kalktık, hastalandık

Sürüldük ilden ile,

Yıktık köprüleri dilimizle

Her seferinde uyuduk, uyandık

Güneş ne ki aşk ateşinin yanında

Biz kutlu aşklarda yandık...

Dayandık! ... Dayandık! ...

İşte sözün özü cancağızım:

Kırık dökük birkaç şiir,

Kimsenin duymadığı şarkılar

Kalem, kâğıt, koltuk masa...

Bütün zerrelerin özünde tasa

Ah şu ayrılık olmasa! ...

Elli yıl sonra

Bunu düşünüyor, bunu yazıyorum

Diyorum ki:

Ah şu öfke çıkmasa kınından

Ne güzel geçinirdi kurtla kuzu...

Ölmeseydi, yaşasaydı muhabbet kuşum

Yaşasaydı baş ucumda; kafesinde...

Düşmeseydi, gurbet rüzgârıyla

Balkondaki koltuğum... 

Nasıl yakalardım nasıl, o muhteşem sonsuzu...

Özeti şu dostlar:

Elli dilim içinde zaman karpuzu...

	26.11.2001 / 12.01.2002', 'Bu soğuk havalarda çatladı Zaman karpuzu... Göbeği kesildi mutlulukların Kalmadı, kalmadı ey yüreğim Yaşamanın tadı-tuzu... Saatler, bozuk s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/zaman-karpuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özen', 'ozen-gokhan-oflazoglu-6215u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En çok birbirimize muhtacız,

en çok gadrimiz birbirimize.

Rastgele yaşıyoruz, özen yok

ilişkilerimizde; biraz dikkat

bu kadar zor mu...? biraz özen

açardı bütün kilitlerimizi.

Rastgeldik bu dünyaya, 

devam ediyoruz öyle.', 'En çok birbirimize muhtacız, en çok gadrimiz birbirimize. Rastgele yaşıyoruz, özen yok ilişkilerimizde; biraz dikkat bu kadar zor mu...? bir...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Kuşum Vardı benim', 'uc-kusum-vardi-benim-mustafa-ceylan-bh8xe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üç kuşum vardı benim, aynı yuvada

Besledim, yürüttüm, büyüttüm 

Uçmasını öğretemedim, nedense

Zira uçmadım, uçamadım; 

Hep süründüm...

Onlar da peşimden, aynen...

Üç kuşum vardı benim, aynı yuvada

İkisini el aldı, birisini yel

Yuva darmadağın şimdi

İki gözüm iki sel...', 'Üç kuşum vardı benim, aynı yuvada Besledim, yürüttüm, büyüttüm  Uçmasını öğretemedim, nedense Zira uçmadım, uçamadım;  Hep süründüm... Onlar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uc-kusum-vardi-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(GÜLCE-Buluşma) Ağlamam Diyordum', 'gulce-bulusma-aglamam-diyordum-mustafa-ceylan-tfvwl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlamam, asla ağlamam diyordum

“Git, haydi git! ” derken sana

Anladım, yanılmışım meğer

Şimdi için için ağlıyorum...

Deli yüreğimi ağzına kadar

Taşla doldurdum sanıyordum.

Saz teli kadar ince

Saz teli kadar gözü suluymuş

Ne bileyim? 

.....Bilmezdim mehtabın kolumdan tutup

.....Benimle sabaha çıkacağını.

.....Goncayı açmadan dalda unutup

.....Bülbülün türküler yakacağını...

...............Bilmezdim ateşten daha çok sıcak

...............Ateşin göğsümü yakacağını.

...............Sensiz saatlerin hep bıçak bıçak

...............Ruhuma hüzün bırakacağını...

.....Getirin resimler konuşsun bana

.....Getirin olmuşun olacağını.

.....Cihanı toz edip savuracağım

.....Getirin sımsıcak yâr kucağını...

Böyle yalnız kalmaya

Öksüz, yetim, boynu bükük kalmaya

Alışamadım bir türlü.

Gidişin, sana koşmakmış

Gidişin, yanıp yakılmakmış

Gidişin, hıçkırmakmış anladım

Oturdum çocuklar gibi

Ağladım, ağladım...', 'Ağlamam, asla ağlamam diyordum “Git, haydi git! ” derken sana Anladım, yanılmışım meğer Şimdi için için ağlıyorum... Deli yüreğimi ağzına ka...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gulce-bulusma-aglamam-diyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boncuklar', 'boncuklar-yasar-okcu-zzvwj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boncuklar

             Bilemezdim ipin çürümüşlüğünü,

             Diziyordum boncukları,tek, tek…

Kuralları olmalıydı, imamesiz olmamalıydı diyordum,

Tamam sanmıştım.

          

             Bilemezdim ipin çürümüşlüğünü,

             İp yırtılmış, dökülmüştü boncuklar, tek,tek…

Önce biri, sonra diğerleri döküldü,

Ben; 

İlk dökülenleri toplamaya çalışırken.

Birkaçı tutunmaya çalıştı dökülenlere inat.

Dökülenler kaybolup gittiler,

Başka iplere bile ait olamadan…

           

             Bilemezdim ipin çürümüşlüğünü,  

             İpe tutunanların bana yeterliliğini,

             Dostlukta kural koymanın gereksizliğini,

             Ve bilmeliydim; 

             Dostluğun sınırsızlığını,

             Kuralsızlığını…', 'Boncuklar              Bilemezdim ipin çürümüşlüğünü,              Diziyordum boncukları,tek, tek… Kuralları olmalıydı, imamesiz olmamalıydı...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Okçu']::text[], 8.5, '{"poet":"Yaşar Okçu","poet_slug":"yasar-okcu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/boncuklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün gibi', 'dun-gibi-ferit-teksoy-ahiah', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine sabah oldu sensiz geceden sonra

Gözlerim güneşin doğduğu yerde

Diğer sabahlardan farksız,umutsuz

Güneş yükselip batacak..tıpkı dün gibi

İnsanlar telaşla işlerine gidecek

Veda edecekler evlerine,sevdiklerine

Onlar kaybolurken karşı köşeden

Ben uyumuş olacağım..tıpkı dün gibi

Uyanıkken her anımda seni düşünmek

Yetmiyecek,rüyamda sen olacaksın

Akşam herkes dönerken evine,sevdiğine

Benim sabahım olacak..tıpkı dün gibi

Şehir eğlenirken gece boyunca

Yemeklerde,sohbetlerde,danslarda

Ben senin hayalinle konuşacağım

Tüm gece boyunca..tıpkı dün gibi', 'Yine sabah oldu sensiz geceden sonra Gözlerim güneşin doğduğu yerde Diğer sabahlardan farksız,umutsuz Güneş yükselip batacak..tıpkı dün gibi...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dun-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbette Unutamazsın!', 'elbette-unutamazsin-mustafa-ceylan-7em0e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutamazsın, gözlerimin rengini

Unutamazsın, hiç bitmeyen sevgimi

Unutamazsın çılgın buselerimi

Unutamazsın canım, unutamazsın.

Beni görürsün, baktığın her bir yerde

Beni sorarsın zifiri gecelerde,

Beni sararsın efsunlu seherlerde

Dayanamazsın canım, bırakamazsın.

Duyarsın tatlım, sesimin yankısını

Söylersin balım, aşkımın şarkısını

Ararsın gülüm, tenimin kokusunu

İnandım, gülü bile koklayamazsın.

Asla ağlatmam, ben seni üzemem ki

Yalan dünyada eğlenip gezemem ki

Nidem yazıdır, yeniden yazamam ki? 

Yazılmışım; el yerine koyamazsın.

Sevdim delice; Tanrı’ m buna şahitsin! 

Neden diyorsun:“Istırap burda bitsin? ”

Bilmiyor musun yalnız bana aitsin? 

Ben saklasam bile, sen saklayamazsın.

Unutma beni, unutma ellerimi

Unutmam seni, o kahve gözlerini

Bahar gülüşlüm koklasam her yerini

Elbet unutamam; unutamazsın.

Unutamazsın canım, unutamazsın...', 'Unutamazsın, gözlerimin rengini Unutamazsın, hiç bitmeyen sevgimi Unutamazsın çılgın buselerimi Unutamazsın canım, unutamazsın. Beni görürsü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/elbette-unutamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyva mınî', 'heyva-min-yasar-okcu-7csjw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Wek heyvêyi dı tarîyêde şevq dıdî

Ronahî dıdî dılêmın

Davîyêde ez gırtî mam lı benda te

Tıjî gırtî bu, vêga lı benda kîyî tu

Tı wek kevokê nejmalê azad buyî; 

Herî kîja welatî keça rojê? 

Ez, lêvyateme, were…', 'Wek heyvêyi dı tarîyêde şevq dıdî Ronahî dıdî dılêmın Davîyêde ez gırtî mam lı benda te Tıjî gırtî bu, vêga lı benda kîyî tu Tı wek kevokê n...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Okçu']::text[], 8.5, '{"poet":"Yaşar Okçu","poet_slug":"yasar-okcu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/heyva-mini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlu bir gün', 'yagmurlu-bir-gun-erdal-asik-mzbpn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen hiç yağmurla seviştin mi? 

Yollarda yapayalnız yürürken

Üstüne düşen her damla

İçini ürpertip titredin mi? 

Kara bulutlar üzerinde dolaşırken

İçine belirsiz bir kuşku çöktü mü

yollarda akıp giden sular gibi

Sen hiç okyanuslar kadar büyüyen 

Ummanlar kadar sevdin mi! ?', 'Sen hiç yağmurla seviştin mi?  Yollarda yapayalnız yürürken Üstüne düşen her damla İçini ürpertip titredin mi?  Kara bulutlar üzerinde dolaş...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yagmurlu-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü', 'dogum-gunu-yasar-okcu-5kfdp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yirmi beşinde doğdu şubatın,

Yirmi beşinde öldü şubatın.

Kardelen misali doğdu,

Laleler onu boğdu.

Tüm çiçekler kardeş olmadılar

Laleler onu kaybettiler, 

Kendisi de kayboldu…

Laleler ölüm fermanını okudu,

Şubatın yirmi beşinde,

O gün geldi herkes lale oldu.

‘Yirmi beş şubat’ da öldü,

O’da  öldü,

Herkes öldü,

Öldüğünü anladığında kardelenliğinden utandı…

Yirmi beşinde doğdu,

Yirmi beşinde öldü…

Artık hiçbir ay şubat değildi,

Ama o yalnızlığı yaşayan bir ölüydü.

Yalnızdı ama,

Umut tükenmemişti,

Yalnızdı, ama; 

Taşıyordu gizlemek istediği yaşam ateşini…

Aşk kadar özgür olmak istemişti,

Aşk kadar özgür olmak istemiştik.

En somut varlığa aşık olduk sonra,

Yalnızlaştık birbirimizden habersiz,

Öldük sonra ayrı kutuplarda…

Artık yirmi beş şubat,

Artık on yedi eylül,

Ve tüm doğum günleri,

Ölümün doğallaştığı günlerdi…', 'Yirmi beşinde doğdu şubatın, Yirmi beşinde öldü şubatın. Kardelen misali doğdu, Laleler onu boğdu. Tüm çiçekler kardeş olmadılar Laleler onu...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Okçu']::text[], 8.5, '{"poet":"Yaşar Okçu","poet_slug":"yasar-okcu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dogum-gunu-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmamış bir özet', 'yasanmamis-bir-ozet-serkan-madak-swb0p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen şimdi git benim bir randevum var

Sakın arkana bakma bu portre ikimize dar

Anlatsam bu sevda aklına zarar

Sessizce ölmeliyim Azrail''e sözüm var

Ne senda bir ahım ne sevgimde vahım var

Kral''lıklar devirdim alemde tek şahım var

Yıkıldı tüm benliğim elde tek imanım var

Fark görmüyorsan bende bu kahpelerden seç yar

Aşinasın teklife güzellik var fizik var

Ne gönülde bir hicret ne parmakta yüzük var

Yaradan şahit olsun dört cihanda ben kadar

seven var ise seni Kerbela''dır bana yar

İstersen dost kalalım çağdaşız Ya sen kadar! 

Anlamamışım seni eğlence olurmu ar

Hem ne çıkar ki bundan samimi tüm insanlar

Caddelerde mutluluk yürek yansa ne zarar

Zannetme ki bir andı unutmadım dün kadar

Sen Polyana''dan eşsiz kendine mutluluk kâr

Gayri anlatılmaz aşk Mecnunda da sönmüş hâr

Belki bir Ayzıd çıkar unuturum sen kadar', 'Sen şimdi git benim bir randevum var Sakın arkana bakma bu portre ikimize dar Anlatsam bu sevda aklına zarar Sessizce ölmeliyim Azrail''e söz...', ARRAY['Türk Edebiyatı','Şiir','Serkan Madak']::text[], 8.5, '{"poet":"Serkan Madak","poet_slug":"serkan-madak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasanmamis-bir-ozet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıraliçe''ye', 'kiralice-ye-gok-tengri-fqmfy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben proleteryayım

Sen de kıraliçe

Bunu ikimiz de biliyoruz

Ama benim bildiğim bir şey var ki 

Sen bilmiyorsun

Ben veda şarkılarıyla neşelenebilir

Ve boşver diyebilirim bir çok şeye

Ama sen bir bozulsa rahatın

Daralır, sıkılır, ağlarsın

Başında tacın..

8Aralık2003

21.15', 'Ben proleteryayım Sen de kıraliçe Bunu ikimiz de biliyoruz Ama benim bildiğim bir şey var ki  Sen bilmiyorsun Ben veda şarkılarıyla neşelene...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiralice-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir', 'kim-bilir-yusuf-ziyaeddin-sivaslioglu-cyg4f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kim bilir,

Ne çok isterdin,

Zamanı, geçsin diye.

Kim bilir,

Ne özlem duyardın,

Yaşanmamış bir sevgiye.

Kim bilir,

Ne çok isterdin,

Güneşi, doğsun diye.

Kim bilir,

Ne çok aşık olurdun,

Aşkından  habersiz yare.

Kim bilir,

Ne çok anardın,

Tekrar yaşamak için anıları.

Kim bilir,

Nasıl kurardın dünyayı,

Birlikte yaşamak için sevdayı,

Kim bilir.

(Samsun, 5 Nisan 2004)', 'Kim bilir, Ne çok isterdin, Zamanı, geçsin diye. Kim bilir, Ne özlem duyardın, Yaşanmamış bir sevgiye. Kim bilir, Ne çok isterdin, Güneşi, d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kim-bilir-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Bir Yürek mi Bırakacaksın Avuçlarına', 'yarali-bir-yurek-mi-birakacaksin-avuclarina-kamil-aydemir-m3tlm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yanıtmadı beni yüreğim

                                      yüreğimden gelen her şey kabulümdür

                                      anahtarı yaralı yüreğinde

                                      bu yürek şimdi senin köşkkündür

sevdamın uğruna çıktım dağlara

düşlerimin penceresinden baktım uzaklara

en uzak bile yakındı bana

gönlüme çıkan karanfilli sokakta

yeşil yaktım yalnız sana

nefesin nefesime değerken bile

sen uzaktın bana

uzaklık aşka açar yara

boş yere sevmedi bu soylu yürek seni

farklısın diğer güzellerden

kıyarsan bu sevdaya

paramparça edersin beni

batarım günün bir yerine

herkese dokunur acısı

ben düş suçlusu

güzel günlerin gönüllüsü

çok örseliyor hayat

yüreğinde sakla beni

her günün akşamında

yaralı bir yürek mi bırakacaksın avuçlarına

görüyorum ki

emanet gülücüğe bile muhtaçsın

     sevgiye açsın

nereye kadar yenileceksin korkularına

bir kezde iplerini ver yüreğinin eline

üzüm karası gözlerinde beyaz güller açsın

seni bekliyorum sevgide

soyun bana

çıplaklığını çizeyim dudaklarına

izimi sürüyor yalnızlığım

yüreğinde sakla beni

kırma bakışlarımı sokul yanıma

öpücük çiçekleri olayım dudaklarının kıvrımlarına

karakışta camlara konan güneş gibi çık yarına

hep kanar ayrılık yarası

ömür dediğin ne ki

bir türkünün ilk harfı ile son harfı arası

bonkerlik etmeyelim zamana

kumar oynanmaz hayatla

geldim düşlerindeki beyaz atla terkime atla

pembe bulutları yatak yaparım sana

soyun bana

demir atmam ben her limana', 'yanıtmadı beni yüreğim                                       yüreğimden gelen her şey kabulümdür                                       anaht...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/yarali-bir-yurek-mi-birakacaksin-avuclarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SENi ARIYORUM...!', 'seni-ariyorum-baki-son-hoov0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susuyordu...! 

................Fıskıyeden dökülen,

................Binlerce damla.

Susuyordu...! 

................Yalnızlığıma inat

................Bütün kuşlar.

................Binlerce dudaktan,

................Ne istiyordu gülümseme.? 

Susuyordu...! 

................Gözlerdeki sıcak sevgi.

Susuyordu...! 

................Tertemiz,bir kaç cümle.

................Mahcup bir rüzgar,

................Söylenecek ne varsa

................Dünyadan yana

Utanıyordu...

................Bilmem ki,dünya mı değişti

................Binlerce bekleyen göze

................Kapalı pencereler,

Susuyordu...! 

Bir adam dolaşıyordu

............................Günlerce

............................Yıllarca beklemeye...

Bir adam dolaşıyordu

............................Dünya ötesi

............................Bir sevgi bulmaya...

Susuyordu...! 

................Tüm sevgililer.

Susuyordu...! 

................Dünya ötesi sıcak sevgi.

................Islak bir rüzgar

................Söylenecek ne varsa

................Dünyadan yana

Utanıyordu...!', 'Susuyordu...!  ................Fıskıyeden dökülen, ................Binlerce damla. Susuyordu...!  ................Yalnızlığıma inat ...........', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/seni-ariyorum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Dediğin Bıçak Yarasıdır', 'siir-dedigin-bicak-yarasidir-melih-coskun-y8j78', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir dediğin bıçak yarasıdır 

Durup durup kanayan 

Her kanayışında mürekkep olup 

Binlerce dizeye savrulan,

Şiir dediğin,

Etine işlemeli insanın her dokunuşunda 

Garip bir heyecan uyandırmalı 

En boş, en sevgisiz yürekte bile 

En soğuk şehirlerde bile 

Sıcak tutmalı ateşini kavganın ve hayatın 

Ve umudunu 

Bir gün elbet geri dönüleceğinin... 

Şiir,

Acılarla yontulmuş beyaz bir mermer 

Her söz biraz daha belirginleştirir yüzünü 

Her imge biraz daha ölümsüzleştirir 

Saklı bir bıçak yarasıdır şairin yüreğinde 

Her akşam gizli gizli kanar...', 'Şiir dediğin bıçak yarasıdır  Durup durup kanayan  Her kanayışında mürekkep olup  Binlerce dizeye savrulan, Şiir dediğin, Etine işlemeli ins...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/siir-dedigin-bicak-yarasidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlik', 'i-lik-abdullah-atay-gyzka', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gidince; 

Donar kanım,iliğim.

Sen gelince; 

Çözülür düğmesinden

   İliğim...', 'Sen gidince;  Donar kanım,iliğim. Sen gelince;  Çözülür düğmesinden    İliğim......', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Veda', 'bir-veda-omer-serdar-gy917', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'durgun bir andır bu yürekte

nasıl başlandığı 

çoktan unutulmuş bir kilim

çözgüsü yıpranmış 

yorgun çatalağız 

nehrin döküldüğü yerde

yosunlu bir kayıkhane kokusu

hangi kıyı bilinmez

hangi denizin esiri

hangi suyun boğuntusu

hangi selin ezgisi

sonuç yüreğindir senin

geçerli sondan öte

uzadıkça önemini yitirse de yön

yürür bu yol

otopsi raporlarında haritaların

bir vedasın

kapat kapını 

duru ve derin kalsın

balıkçı koylarının suskun

sisli sabahlarında 

martılara yansıyan mavin

son uç yüreğindir senin 

dilersen kopar

hangi kast’ a dahilsem

yöntemince yak beni

hindistan ya da istanbul’ da

ne önemi var mesafemin

Ekleyen: Oya Burgu', 'durgun bir andır bu yürekte nasıl başlandığı  çoktan unutulmuş bir kilim çözgüsü yıpranmış  yorgun çatalağız  nehrin döküldüğü yerde yosunlu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Serdar']::text[], 8.5, '{"poet":"Ömer Serdar","poet_slug":"omer-serdar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-veda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Sevgilerle', 'anneme-sevgilerle-muharrem-guney-lshdt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bedeninden ve ruhundan parçalar kopmak da...

Belki biri bana bir diğeri başkasına.

Her kopan parça derin yaralar açar ruhunda.

Sen yaralarını sarmaya çalıştıkça 

Yenileri baş gösterir apansız.

Ama sen her bir yaradan sonra 

Güçlüsün daha da. 

Direnmek zorluklara,

Sıkılmadan yıkılmadan, 

Umut beslemek geleceğe. 

Umut yaymak çevrene, 

Seni sen yapan budur işte.

Seneler koşturmayla geçmişti.

Emeklilik ufuktaydı.

Çekiverdin kürekleri.

Son bir kuvvetle.

Geleceğe dair ümitle.

Beklenen seneler gelmişti. 

Türlü türlü sorunları da getirmişti.

Ah o beklenen seneler 

Hastalıklar,krizler,

Nasıl da senden götürdüler. 

Tamam mı seneler! 

Bu son mu seneler! 

Yetmedi mi seneler! 

Günler geçiverdi yine. 

Oluverdi tam bir sene. 

Bir anneler gününde 

Vefakar ve cefakar anneme

Nice mutlu günlere 

Ulaşmak dileğiyle 

Bu şiir olsun benden bir hediye.', 'Bedeninden ve ruhundan parçalar kopmak da... Belki biri bana bir diğeri başkasına. Her kopan parça derin yaralar açar ruhunda. Sen yaraların...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Güney']::text[], 8.5, '{"poet":"Muharrem Güney","poet_slug":"muharrem-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/anneme-sevgilerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımdasın', 'aklimdasin-ali-i-hsan-gurpinar-cmz7l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimin her sessiz atışında

Saatin her saniyeyi zorlayışında

Her akşam günbatımında

Aşk gibi aklımdasın

Yazdığım her notada

Seni anlatan yoksul şarkılarda

Sesini anımsatan her çığlıkta

Ölüm gibi aklımdasın

Gidişinin sessiz ağıtında

Sen diye açılan her kapıda

Bakıpta göremediğim her duvarda

Ayrılık gibi aklımdasın

Seni yitirdiğim eylül ayında

Açmadığın telefonlarımda

Kulağımın her çınlayışında

Sevdam gibi aklımdasın

Aklımdasın işte inadına

Aklıma sığmayan hayalinle

Aklımın ermediği yalnızlığımla

Aklımın alabildiği her alemde

Aklımdasın inadına aklımda', 'Yüreğimin her sessiz atışında Saatin her saniyeyi zorlayışında Her akşam günbatımında Aşk gibi aklımdasın Yazdığım her notada Seni anlatan y...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Gürpınar']::text[], 8.5, '{"poet":"Ali İhsan Gürpınar","poet_slug":"ali-i-hsan-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aklimdasin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu ilk kayan yıldızı bu mevsimin', 'bu-ilk-kayan-yildizi-bu-mevsimin-nevin-kalafatoglu-aehh3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birden bakakaldım  gecenin atlasına

koyu bir lacivertti

dolunayı birkaç gün geçmişti

baktım aslına

sevdalarım geldi aklıma

uzaklar

bir yıldızım vardı  seçmiştim 

aradı gözlerim

işte tam o anda 

bir yıldız kaydı

kuyruğunda izini bıraktı

mevsim yaza yakındı

kaçtı...

işte o özgürlüğüne düşkün

gökteki en özgün ışıktı

bu ilk kayan yıldızı bu mevsimin

mevsim bahardı

gönlüm hercai', 'Birden bakakaldım  gecenin atlasına koyu bir lacivertti dolunayı birkaç gün geçmişti baktım aslına sevdalarım geldi aklıma uzaklar bir yıldı...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-ilk-kayan-yildizi-bu-mevsimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öptüğüm Sancı', 'optugum-sanci-zafer-zengin-etnika-f6wqb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O cingene kızın gözlerinde

Gördüğüm hakikat neyse

Bana getir

Sun içime

Bakmazsam

Ölüm alsın umutlarımı...

Bakma

İçimize salıp gittiğin

O ayrılıkların saati değil

Bir kelime et

Dağla yaralarımı

Kanım akmaz

Dokunmaz yüreğine

Ölüm olsun umudum...

Ufka bakıp kopardığın

O gülümseme senindi

Bunu cocuklar bile sevdi

Yağmurda oyanayıp

Gözlerini bana getirdi

Afacan deyip/yanaktan öptüğün

Mavi gözlü

Küçük mustafa

Gizliden kondurdum

Gerdanına gül destesi

Öptüğüm sancı/Büyük bir kadındı...

Gitti mi! 

Bizi mavilikte unutan peri

Sormadan ahvalimizi

Esirgedimi gözlerini...

Adını kaçış koydum a gözüm

Bakışım sen/Yangınım akdeniz

Tüter tapınak duaları

Adına ayrılık/Adına savaslar

Bu yaz da gecmez

Başlar sancılar...

Mırıldadığın o şarkıyı ben yazdım

Yanına mavi kattım

İki kedi gibi sarıldık/Ayrılığa...

8 Nisan 2004  '' İçimin Kitabı ''', 'O cingene kızın gözlerinde Gördüğüm hakikat neyse Bana getir Sun içime Bakmazsam Ölüm alsın umutlarımı... Bakma İçimize salıp gittiğin O ayr...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/optugum-sanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-serkan-erberksoy-lufpi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günbatımının gizemli sonsuzlugunda, kaybolmak

Karanlık, güneş ışığı girmez çıkmaz sokaklarında İstanbul'' un

Anlamsızlığın, anlamlı olmaya başladığı zamanlarda,

Birtek, birtek sen anlamlısın aslında.

Aşkımın tükendiği anlarda

Birtek, birtek gözlerin aklımda.

Mutluluğun güftesini yazdım ben kağıtlara,

Askımı yudumladım tavşan kanı misali, 

Günün son vuslatında

Ama nafile bu yasamda

Yine, ay ısığı vurdu,

Dalgalarla karışmış kıyılara,

Yine ağlıyorum, sonsuzluğun kayboluşunda.', 'Günbatımının gizemli sonsuzlugunda, kaybolmak Karanlık, güneş ışığı girmez çıkmaz sokaklarında İstanbul'' un Anlamsızlığın, anlamlı olmaya ba...', ARRAY['Türk Edebiyatı','Şiir','Serkan Erberksoy']::text[], 8.5, '{"poet":"Serkan Erberksoy","poet_slug":"serkan-erberksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/arayis-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakırdı ellerim', 'bakirdi-ellerim-zafer-zengin-etnika-1ma4s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakırdı 

ellerim

Çekiç

sesleriyle

gülen

Düştüm

gözün

yaşına

Tav

oldu

sevdama

Sevdim...

Yazıma 

düşen 

gölgeyi

Beni

hep

gece

beklerdi

Gamzesi

gül 

bezeli

Sevimli mi! 

S E V İ M L İ...

9 Nisan 2004  '' İçimin Kitabı ''', 'Bakırdı  ellerim Çekiç sesleriyle gülen Düştüm gözün yaşına Tav oldu sevdama Sevdim... Yazıma  düşen  gölgeyi Beni hep gece beklerdi Gamzesi...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bakirdi-ellerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimin sayımı', 'resimin-sayimi-zafer-zengin-etnika-woha6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Resimin 

sayımı

- Sayılmıştır

Tebbessüm unutulmuş boyasında

- Rütuşla

Kabul etmiyor boyanın rengi

- Gülmek işlenmez tuale

Işığı azaltsak olmaz mı! 

- Renk kaçmasın tutukla

Çok genç ressam 

- Döv ama ağlatma

Ya şiirde  yazarsa

- Aşıktır,ağlatma

Olur..lambalar söner..umudu ve dostluğu ve hayali sakladıkları tüm odalar

Duvarlardan yükselen kahkahalarla şaşırırlar..Bunlar çocuklar

- Bırakın oynasınlar..Oynadıkça barış var..

Sırf para için göz yaşı döktürenlere lanet olsun..mezarlarına götürecekleri ne varsa..kirlensin..zehirlensin..yüzleri gülmesin..

9 Nisan 2004', 'Resimin  sayımı - Sayılmıştır Tebbessüm unutulmuş boyasında - Rütuşla Kabul etmiyor boyanın rengi - Gülmek işlenmez tuale Işığı azaltsak olm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/resimin-sayimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu mudur?', 'bu-mudur-serap-demirturk-cb6ec', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vazgeçmek kolay mı yıllarından,

Uzanıp kaldığım ellerinden.

Bir ömür nedir ki

Bilemedim...

Sana sevdiğimi diyemedim.

Gitmek bu kadar mı zormuş,

Yürek de böyle mi kanarmış,

Gurur böyle mi yaparmış? 

Bilemedim.

Al gençliğimi,

Git gidebilirsen.

Al özlemlerimi,

Sar sarabilirsen.

Umudum,hayalim

Ve kalan ömrüm

Nerde,kimle bitecek; 

Bilemedim.

Bir korku yok içimde

Kendime dair.

Korkum sana dairdir.

N''apar bensiz,

N''apar sevgisiz

Bilemedim.

Bu mudur aşk,

Bu mudur sevgi,

Bu mudur vefa; 

Söylesene gülüm,

Bilemedim.

Bu mudur?', 'Vazgeçmek kolay mı yıllarından, Uzanıp kaldığım ellerinden. Bir ömür nedir ki Bilemedim... Sana sevdiğimi diyemedim. Gitmek bu kadar mı zorm...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bu-mudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Tapınmak.', 'aska-tapinmak-ali-osman-yilmaz-63jf0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Okuduğum şiirlerde,

Tanıdığım şairlerde,

Seviyorum diyen herkes de,

Aşk için dua edenleri,

Sevdasına ağlarken,

Sevgilisine yalvarırken

Tapınırcasına yakaran,

Ama tanrıya değil,

Ne insanlar gördüm.

Bende öyleyim şimdi,

O’na kavuşmak için,

Ne dualar ettim,

Ne dilekler tuttum,

Hatta canımı bile adadım,

Bir tek an bile,

Tanrıyı düşünemedim.

Ne garip şey aşık olmak,

İnsanın kimyasını,

Ruhunu,benliğini,

Hatta düşün gücünü,

Bağlıyor,çözülmemesine.

Ne tanrısı kalıyor insanın,

Ne yakınları,dostları,

Atıyor kendini,

Kendisini kavuran,

Sevdasının ateşine.', 'Okuduğum şiirlerde, Tanıdığım şairlerde, Seviyorum diyen herkes de, Aşk için dua edenleri, Sevdasına ağlarken, Sevgilisine yalvarırken Tapın...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aska-tapinmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun.', 'sen-yoksun-ali-osman-yilmaz-d8oxf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günler geçmiyor,

Sen yoksun ya; 

Karabasanlar aynı,

Gökyüzü solgun,

Akşam olmada yine,

Geceler cehennem bana,

Nasıl olsa sabaha,

Ya da günün sonunda,

Yine sensizlik var.

Ve her yanda,

Sensizliği taşıyan renkler,

Hep bana kalmakta.

Akşamın alaca karanlığında,

Tüm şiddetiyle,

Koynumda patlayacak.

Yine yalnızlık.

Ve ben düşüneceğim,

Yalnızlığın derinliklerinde,

Yine sen geleceksin aklıma.

Ne olurdu yanımda olsan,

İstersen boğazıma düğümlen,

Uykularımı kaçır,

İştahımı kapat,yeter ki,

Yanımda ol.

Seni göreyim her gün,

Sabahları yüzümü yıkamak için,

Avuçlarıma doldurduğum suda,

Yüzünü göster bana.

Nasıl istersen öyle acı ver,

Ama,sensizliği yaşatma.', 'Günler geçmiyor, Sen yoksun ya;  Karabasanlar aynı, Gökyüzü solgun, Akşam olmada yine, Geceler cehennem bana, Nasıl olsa sabaha, Ya da günün...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-yoksun-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Olursun', 'pisman-olursun-halil-i-brahim-ozdemir-9nf9v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tohumunu sağlam at, gelip geçen o an’a

Dizginini bırakma ve sahip ol zamana

Elinde karasaban sürdüğün bu hayatta

Bin pişmanlık duyarsın, sızlarsın yana yana...', 'Tohumunu sağlam at, gelip geçen o an’a Dizginini bırakma ve sahip ol zamana Elinde karasaban sürdüğün bu hayatta Bin pişmanlık duyarsın, sız...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pisman-olursun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Seni Arar*', 'gozlerim-seni-arar-bayram-tunca-gfvlg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim albümlerde resmini arar 

Müjdelenenler arasında ismini arar 

Mahşer günü gözlerim cismini arar 

Sensiz cennete verseler neye yarar 

Gözlerim görmek, burnum koklamak 

Ellerim tutunmak/dudaklarım öpmek 

Dilim tatmak, dimağım da tatlanmak 

Gönlüm istiyor her an seninle olmak 

Göz gönlün elçisi esas gönlüm seni arar 

Sensiz her şey verir faydadan çok zarar 

Seninle olunca her yer olur gül gülistan 

Çünkü sensin gönlümdeki en âlâ sultan 

09.04.2004-09.04', 'Gözlerim albümlerde resmini arar  Müjdelenenler arasında ismini arar  Mahşer günü gözlerim cismini arar  Sensiz cennete verseler neye yarar ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerim-seni-arar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaret', 'cesaret-oguzkan-bolukbasi-qdm2d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En tepelerinden

Yuvarlandığım bir hayalin

Son durağıdır sana rastladığım yer

Geceleyin, yalnız ve soğukta kalmış

Bir adamdım saati sorduğumda çekinerek

Ve saatin durduğunda

Çok söz var söylenecek 

Der gibi baktığını gördüğümde

Zamanı durdurmak farz olmuştu

Şehrin perdelerini kapadık

Görünmeyelim konuşurken

Söz bölünmesin

Gün ışığıyla aniden

Ve yeniden başlamak gibi telaşlara kapılmayalım

Sadece dudaklarını seyrediyordum

Gözlerini dinliyordum

Dudaklarında gül

Gözlerinde bir hayat vardı

Yeni tanışmış bir halimiz de yoktu

Sakin

Çok eski günleri birlikte yaşamış gibiydik

İnsan hayatları bu kadar benzeşir mi

Aynı toprağın kokusunda

Ve aynı gök altında

Seni de seviyorum diyeceğim

Cesaretimi yokluyorum

Çalmışlar', 'En tepelerinden Yuvarlandığım bir hayalin Son durağıdır sana rastladığım yer Geceleyin, yalnız ve soğukta kalmış Bir adamdım saati sorduğumd...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cesaret-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinçten Kabarmış Düşüm', 'sevincten-kabarmis-dusum-sevcan-koyuncu-5ldgj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Yüreğime...)

Düşten kabarmış bir güne takıldı yüreğim 

Taşar demeden düştüm içine hayatın... 

  

Önce 

Yıldızların dahi kıskandığı 

O okşanası 

Işık seli saçların düşüyordu aklıma 

Geziniyordu ellerim umarsızca 

Tel tel doluyordun parmak aralarıma 

Ve dalıyordun uykunun koynuna 

                                       avuçlarım başında 

Hissetmiyordun sen... 

  

Gözlerin 

O öpülesi gözlerin 

Saklanmıştı kaşlarının gölgesine 

                                                ürkek 

Sızıyordu güneş içlerinden 

Ve uyandığında doğuyordu gün yüzüme 

Kapatmadan gözlerini üşümüyordum ben 

Bir kara ağıt süzülüveriyordu renginden 

Anımsıyordum yine dilsiz yalnızlığımı 

Vuruluyordum sonunda 

                             kurşunsuz 

Bilmiyordun sen... 

  

Ve gül yanakların 

O dokunulası 

Gamzenin kendine en çok yakıştırdığı 

Kaybolurum sanırdım çukurlarında 

Uzan(a) madan dudaklarım 

Hapsolduğun yalnızlığınla kaçıyordun 

Sığınıp dört duvarına 

Görünmez oluyordun hüznünden 

                                       kederinden 

Fark etmiyordun sen... 

  

Bilmiyorum diyordu dudakların 

Sana ağır gelen bir şeylerden bahsediyordun 

Bahşediyordun bana duygusuzluğunu 

Yapışkan yalnızlığından korkuyordun 

                                       korka korka yaşıyordun 

                                                          kaçmaya halsiz 

Oysa ağır olan ta kendisiydi hayatın 

Ve yalnızken yoruluyorduk biz 

Anlamıyordun sen... 

  

Ellerimi en çok seninkilere yakıştırıyordum 

Uzandıkça ben itiyordun sessizce 

Usul usul yumuyordun avuçlarını 

Sonra bir yerden söz ediyordun 

                                       yüreğinin götürdüğü 

Ne yolumun üzerinden geçiriyordun yolunu 

Ne de sonunda bana varıyordun 

Alışılmış yalnızlığına sarılıyordun yine 

                                                yine kimsesiz 

Oysa benimkini al demiştim sana 

Ben razıydım seninkiyle yaşamaya 

Duygusuzlanıyordun yine 

                             yine bir başına 

Kaçıyordun sen... 

  

Sonra 

Sesini karıştırıveriyordun günüme 

Hep beklenen zamanların 

                             beklenmedik bir anında 

Sen doluyordu soluduğum hava 

Soluk soluk içimde sen biriktiriyordum 

Nefessiz kalıyordum sonunda 

Yanıyordu gülmeye yakışır yüzüm hüzünçle 

Yüzyıllık yalnızlığıma sen ekleniyordun bir de 

Vaz geçiyordum her şeyden 

Habersizdin sen... 

  

Ve 

Nisan 1 günlerden 

Hepsi bir şakadan ibaretmiş yalnızca 

Yüreklerimiz değiş-tokuş 

                                  zaten... 

  

Sevinçten kabarmış bir güne sarıldı ellerim 

Taşır diyerek düştüm içine yaşamın(ın) ...', '(Yüreğime...) Düşten kabarmış bir güne takıldı yüreğim  Taşar demeden düştüm içine hayatın...     Önce  Yıldızların dahi kıskandığı  O okşan...', ARRAY['Türk Edebiyatı','Şiir','Sevcan Koyuncu']::text[], 8.5, '{"poet":"Sevcan Koyuncu","poet_slug":"sevcan-koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/sevincten-kabarmis-dusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zülüfte Gör Telde Gör', 'zulufte-gor-telde-gor-hafize-zuluflu-kmucg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç kere yemin ettim

İnatla durdum sözümde önce

Bir gün, beş gün, bir ay….

Dayanamadım hasretine

Bozdum yeminimi kaç kere

Aradım defalarca

Yabancılara sordum seni

Şairin dediği gibi 

Kelimeler kifayetsiz

Gözlerdeki ayna eksik

Ne desem boş şimdi

Bekleme daha fazla

Hatırla seni nasıl sevdiğimi

Boz sessizliğini

Bir selam yolla

Durma gel hadi

Gözlerimden anlamazsan 

Dokun saçlarıma 

Sen sevdayı

Zülüfte gör telde gör', 'Kaç kere yemin ettim İnatla durdum sözümde önce Bir gün, beş gün, bir ay…. Dayanamadım hasretine Bozdum yeminimi kaç kere Aradım defalarca Y...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zulufte-gor-telde-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorundasın', 'zorundasin-mehmet-ozkilinc-76ayh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç ağlama, sızlama boşuna

Böyle olmasını sen istemedin mi? 

Katlanmak zorundasın şimdi buna

Hayat devam ettiği sürece...

Olan oldu, biten bitti zaten

Dönülmez ki bir daha geriye...

Pişmanlık ve gözyaşı etmez ki fayda

Katlanmak zorundasın böyle yaşamaya...

  ...........

  ...........', 'Hiç ağlama, sızlama boşuna Böyle olmasını sen istemedin mi?  Katlanmak zorundasın şimdi buna Hayat devam ettiği sürece... Olan oldu, biten b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özkılınç']::text[], 8.5, '{"poet":"Mehmet Özkılınç","poet_slug":"mehmet-ozkilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zorundasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-hasan-arican-nhqj1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“Ya banimsin, ya toprağın”

Bu sözcüklerin anlamını iyi biliyor olmalısın.

Gerçekten, 

Gerçek sevgi istiyorsan geç kalmış değilsin 

Gel katıl sevmesini bilenlerin, bizlerin arasına

Öğren “öldüresiye sevgi”nin sevgi olmadığını, arkadaş.

Neden istersin hep sevgiliden bir şeyler almayı; 

Aksine,

Gerektiğinde verilmeli can, sevgili için

Ver verebildiğin kadar ne varsa yüreğinde 

Böylelikle,

Artacaktır sevgin, ona verdiğin değer ölçüsünde; 

Böyle sev,

Sev sevebildiğin kadar, arkadaş.

Hiç kimseye dokunmaz zararı gerçek sevginin; böyle bil

Olmasa bile sevgilinin mutluluğu seninle paylaşılan

Mademki sevdiğin insan mutlu

Olmalı onun mutluluğu sana teselli, arkadaş.

Sev, zararı dokunmayan delilikle; 

Deliliğin zararı yalnız sana dokunuyorsa bile, arkadaş

Zorlama ile ne sevdir kendini,

Ne sevmeye çalış başkasını arkadaş

Arkadaş,

Sevgin aşk mertebesinde olsa bile

Atmışsan sevginin uğruna gururunu ayaklar altına

Ne önemi varki onun sana olan sevgisinin

Ne mutlu sana, seviyorsa o da seni senin gibi arkadaş.', '“Ya banimsin, ya toprağın” Bu sözcüklerin anlamını iyi biliyor olmalısın. Gerçekten,  Gerçek sevgi istiyorsan geç kalmış değilsin  Gel katıl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Arıcan']::text[], 8.5, '{"poet":"Hasan Arıcan","poet_slug":"hasan-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/arkadas-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınım', 'yarinim-mehmet-ozkilinc-60ta2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yapayalnız kaldım tek başıma 

Ne arayanım var, ne de soranım

Nerden düştüm ben bu hayata

Acılar hep yoldaş olur yarınıma

Ben ne bahtı kara bir divaneyim 

Gecesi yok, gündüzü karanlık biçare

Suskun kalan yüreğim avare

Gözyaşım sel olmuş, taşırmış neçare

Hüznün nağmeleri boşalır dudağımda 

Sanki yarınım yokmuş, bu dünyada

İki damla gözyaşı süzülür yanağımda

Alır götürür beni, diyardan diyara

Felek kırbacını bir kere vurdu ya! 

Artık doğrulmaz belim, kırılır dizlerim

Yüzüm acıdan güler, bilinmez halim

Dayanılmaz bir yaşam alır bedenim

Haykırır yüreğim, adaletine dünyanın

Açılır ellerim, göğe doğru dualarım

Söylenir ardı sıra dizilmiş acılarım

Feryatlar koparır bağrı yanık yarınım

Bir umut ışığı görülmez terkedilmiş bahardan

Hüzün hep bana, karanlık çökmüş baharıma

Bırak, hiç kimse sormasın halimi

Teselli istemez kan ağlıyan yarına

Bu hayata tutunacak dalım da kalmadı

Hepsi birer birer kırıldı, yeşermediler bir daha 

Çığlıklar içinde şimdi, yüreğim inler

Hiç bir haber gelmez, doğacak yarından

Acılar üst üste birikirse böyle

Gözyaşın sel olup, her gün taşarsa,

Bil ki bir tek sözün kalmış dünyaya

Ne olur BU NEFES BİR SON BULSUN! ...', 'Yapayalnız kaldım tek başıma  Ne arayanım var, ne de soranım Nerden düştüm ben bu hayata Acılar hep yoldaş olur yarınıma Ben ne bahtı kara b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özkılınç']::text[], 8.5, '{"poet":"Mehmet Özkılınç","poet_slug":"mehmet-ozkilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yarinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bademler Çiçeklendi', 'bademler-ciceklendi-mustafa-onder-q3hpx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bademler çiçeklendi,

Patır patır tomurcuklar...

Seni bekliyor yüreğim,

Çıkıp geleceğini biliyorum

Bir yerlerdesin..

Baharını bekliyor ömrümün kalanı,

Seni istiyor,

Dinlemiyor ne düşü ne yalanı..

Bademler çiçeklendi,

Yüreğim gümbür gümbür

Sen bir yerlerdesin

Çıkıp gel hadi

Dol içime leylaklar,

Güller ve sümbüller gibi..

Dola kollarını belime

Bahçe sarmaşığı gibi...

Bademler çiçeklendi

Kırksekiz yıllık fotoğrafın

Kırbahçesinde açan menevşeler gibi..

Sev beni,

Çok sev..

Yılların acısını çıkartsın dokunuşların..

Dudakların bal çanağı, 

Gözlerin derya deniz...

Sev beni,

Çok sev...

Yüreğimi çıldırtsın öpüşlerin..

Bademler çiçeklendi,

İçimde ikinci bahar,

Yaşamak ne güzelmiş,

Seninle var olmak ne güzel! 

08.04.2004/Burdur', 'Bademler çiçeklendi, Patır patır tomurcuklar... Seni bekliyor yüreğim, Çıkıp geleceğini biliyorum Bir yerlerdesin.. Baharını bekliyor ömrümü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Önder']::text[], 8.5, '{"poet":"Mustafa Önder","poet_slug":"mustafa-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bademler-ciceklendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sildim Seni Defterimden', 'sildim-seni-defterimden-hifzi-ozbekmez-tn4bt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başkasını seveceğim

Sildim seni defterimden

Ağlamayıp güleceğim

Sildim seni defterimden

Ettiklerin artık yeter

Aşkınla ettin bin beter

Çileli ömrümde biter

Sildim seni defterimden

Çekemem artık nazını

İstemem bahar yazını

Bitirdim gönül sızımı

Sildim seni defterimden

Sen umurumda değilsin

Cümle alem bunu bilsin

Latifinde bahtı gülsün

Sildim seni defterimden', 'Başkasını seveceğim Sildim seni defterimden Ağlamayıp güleceğim Sildim seni defterimden Ettiklerin artık yeter Aşkınla ettin bin beter Çilel...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sildim-seni-defterimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrep ve yaya', 'akrep-ve-yaya-elif-sebnem-akal-xl60d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne yapsam

ne söylesem

neyi düşünsem de sen olmasa

sessizliğim

Sukunet sensizliğin diğer adı mı ne

kuru gürültü olsun o zaman

hayat dediğin

ki  akrep gibi sokmalı kendini

mesela işlek caddede karşıya geçerken

solumdan gelen ölüm olmalısın sen

hesaba katmadığım o bakış

eli bıçaklı katilim

ki gitsem

bir gitsem

pir gitsem 

iz kalmasa ölümümden

karşıya geçiyorum durmadan

gel vur bana

bir anlık saygı duruşu istemem', 'Ne yapsam ne söylesem neyi düşünsem de sen olmasa sessizliğim Sukunet sensizliğin diğer adı mı ne kuru gürültü olsun o zaman hayat dediğin k...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/akrep-ve-yaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilyor Musun', 'bilyor-musun-mehmet-ozkilinc-hl30u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana,

İki kelime yazmak istedim,

Ellerim titredi,

Yazamadım.

Telefon edip söyleyeyim dedim.

Telefonun kapalıydı. 

Sen,

Aradığında sana söylemek istedim

Dilim tutuldu,

Söyleyemedim.

Defalarca üst üste bunu denedim,

Anılar engel oldu. 

BİLİYOR MUSUN? 

Sen,

Benim vazgeçilmezim oldun,

Sana hiç sahip,

Olamadım.

Anlaşılan bu hayat böyle bitecek

Gözyaşı çaresiz...

Senden,

Bir tek şey istedim oysa

Anladığını sandım

Yanılmışım

Ve sana vurgun olan yüreğimi

Acımadan deldin geçtin

BİLİYOR MUSUN? 

Senden,

Kaç kere kaçmak istedim

Yüreğimi hançerleyip unutmak

Olmadı, başaramadım

Nerden bilebilirdim her yerin sen olduğunu

Kaçmak faydasız...

Neyse,

Artık hiç bir şeyin faydası yok

Kendi kendime 

Söyleniyorum işte

Geri dönüşü olmayan bu yarışta,

Kaybettik anlaşılan.

BİLİYOR MUSUN? 

BİLİYOR MUSUN? 

BİLİYOR MUSUN....?', 'Sana, İki kelime yazmak istedim, Ellerim titredi, Yazamadım. Telefon edip söyleyeyim dedim. Telefonun kapalıydı.  Sen, Aradığında sana söyle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özkılınç']::text[], 8.5, '{"poet":"Mehmet Özkılınç","poet_slug":"mehmet-ozkilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bilyor-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim', 'zalim-volkan-sen-5lx8w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nerede o kahraman

Nerde o aşık

Seni seviyorum diyen yar nerede? 

Hazin bir aşk hikayesiydi bizimkisi

Hani o mutlu son

Hani nerede? 

Hani beni seviyordun

Kalbinde bir tek ben vardım hani? 

Böyle mi bitmeliydi herşey

Gerçekler nerede hani? 

Sana son bir sözüm var zalim

Vur hançeri kalbime kana bulansın

Fazla derine inme

Çünkü orada sen varsın', 'Nerede o kahraman Nerde o aşık Seni seviyorum diyen yar nerede?  Hazin bir aşk hikayesiydi bizimkisi Hani o mutlu son Hani nerede?  Hani ben...', ARRAY['Türk Edebiyatı','Şiir','Volkan Şen']::text[], 8.5, '{"poet":"Volkan Şen","poet_slug":"volkan-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zalim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey gönül...', 'ey-gonul-yusuf-ziya-leblebici-p9pzj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Militanların gri parkalarının

içinde gül, dışında bir ısırgan otu

Bir gönül ki bu, devrimlere kale olmuş

gözyaşların doldurduğu bir kuytu...

Hangi mavzerin gül attığı

  hangi kalemin kurşun sıktığı,

    hangi gözyaşların çiçek aktığı görülmüş

      bu gönülden başka...

Bir gönül ki bu, dağlarında yediveren

    dikenlere karşı direnen,

Kora düşen ateşe biraz daha diyen

Bir gönül bu, topraklarında çiğ esen...

Ey gönül; 

Ey bir kurak, bir göl olan

yağmura avuç açıp, sıcakta kavrulan

sen değil misin rejimine darbeler,

   sevinçlerini zindanlara atan.

Sen, düşünce özgürlüğüne bir gardiyan,

    mantığına başbakan.

Sen, postalların astı

   sevdaların militanı...

Çatlamış dudaklarıma bir merhem

   bazen de yerine zehir koyan.

Derinliklerimdeki kurşun yaralarına

   bazen yaprak, bazen de tuz basan

      sen değil misin! ...', 'Militanların gri parkalarının içinde gül, dışında bir ısırgan otu Bir gönül ki bu, devrimlere kale olmuş gözyaşların doldurduğu bir kuytu......', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ey-gonul-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...', 'sen-yusuf-ziya-leblebici-pvdkg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boğazımdan geçen bir lokma ekmeğin

   Tuzu sen

      şekeri sen

          biberi sen...

Titrek ellerimdeki

  adına damar dediğin

hayat nehrinin

   canı sen

      kanı sen...

Bir rahmetse bulutlardan sağılan

Bir yağmursa toprağı çamurlaştıran

güllerin ilacı sen

   suyu sen

      gölü sen...

Dokunmasınlar yapraklarıma

razıyım dikenli düşmanıma

   fidanım sen

      toprağım sen...', 'Boğazımdan geçen bir lokma ekmeğin    Tuzu sen       şekeri sen           biberi sen... Titrek ellerimdeki   adına damar dediğin hayat nehri...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-358-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Korku', 'korku-tansel-yegen-rkven', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Kendimden bir o gittiğinde korktum....ah bir de hatırlarken hala....”

KORKU

önce tül perdenin arasından sızdı

sonbaharın son ışık hüzmeleri

soluk ve duvarda yüzleri unutulmuş

çerçeve içindekileri okşayarak geçti.

ürküyorum / uyanacak anılar içimde

istasyondan kalkan son tren çığlığında

yere düşen o ipek mendilden

-ki orada yitirmiştim sesimi

bir umut daha paslanacak

oksitlenmiş kolyenin gölgesine

oysa hüznü dolu dolu yaşayan

ne çok aşk emanet bırakılmıştı

sırtımdaki çeyiz sandığımın üzerine

-ki en eski ceviz ağacından hediye

ve ışığın korkusuna havalanacak

turkuvaz boyunlu üç güvercin

gövdemden...

30-01-2004, 15:26', '''Kendimden bir o gittiğinde korktum....ah bir de hatırlarken hala....” KORKU önce tül perdenin arasından sızdı sonbaharın son ışık hüzmeleri...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yegen']::text[], 8.5, '{"poet":"Tansel Yegen","poet_slug":"tansel-yegen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/korku-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdi Ne Ki', 'derdi-ne-ki-sadik-softa-6bfdb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendi kendisine küser,

Taş kesildi, buza keser,

Gönülde bir rüzgar eser,

Bu yüreğin derdi ne ki? ! 

Başıma bela, yaramaz,

Kendini arar bulamaz,

Göz çağlar kalbi sulamaz,

Bu yüreğin derdi ne ki? ! 

Umutlarla haşır neşir,

Kendi kendiyle güreşir,

Vuslata erse devleşir,

Bu yüreğin derdi ne ki? ! 

Acıları katar katar,

Sevda ile kalkar, yatar,

Her gün biraz daha batar,

Bu yüreğin derdi ne ki? ! 

Acıları bir bir yutar,

Kör bahtına dilek tutar,

Dert üstüne derdi artar,

Bu yüreğin derdi ne ki? ! 

Çankırı-08.04.2004', 'Kendi kendisine küser, Taş kesildi, buza keser, Gönülde bir rüzgar eser, Bu yüreğin derdi ne ki? !  Başıma bela, yaramaz, Kendini arar bulam...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/derdi-ne-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bakarım', 'oyle-bakarim-sadik-softa-m9ltt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Irmaklar uzayıp akar ya hani,

Ben de umutlara öyle bakarım.

Garip boyun büküp bakar ya hani,

Ben de sevdalara öyle bakarım.

Ahlara, ohlara bırakma hüner,

Kainatın yükü sırtıma biner,

Gözlerin gözüme gelir de tüner,

Ben de sevdalara öyle bakarım.

Seni bekleyen var delicesine,

Fırtınalı kalbin selicesine,

Bir garip gecenin gülücesine,

Ben de sevdalara öyle bakarım.

Mühürü vurunca gözlerin kalbe,

Tebessümle dolar yüzlerin kalbe,

Bir ferahlık verir sözlerin kalbe,

Ben de sevdalara öyle bakarım.

Irmaklar uzanıp akar ya hani,

Kalpleri ateşler yakar ya hani,

Garip boyun büküp bakar ya hani,

Ben de sevdalara öyle bakarım.

Çankırı-08.04.2004', 'Irmaklar uzayıp akar ya hani, Ben de umutlara öyle bakarım. Garip boyun büküp bakar ya hani, Ben de sevdalara öyle bakarım. Ahlara, ohlara b...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oyle-bakarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaz Ve Sen', 'bir-yaz-ve-sen-sirma-mersin-adzu2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beyaz bir bisikletin üzerinde; giden anılarım...

Günbatımdan karanlığa doğru yol alırken...

Ağustos böceklerinin sesleri ile, 

Sarmaşık güllerin arasındaki; 

Salıncakta sallanan benliğimi gördüğümde...

Canlanır hayallerim! 

O gün! 

Yüreğimde söylenmemiş; ünlü ünsüz harflerin arasına sıkmış 

birçok duygu, senin karşında konuşamamıştı...

Şimdi ise! 

Yıldızlar karanlığa göz kırpıyorken; mehtap denizle fısıldaşıyor...

Hayallerim umudu kucaklıyorken,gerçekler yüzümü okşuyor...

Sensizliğe takılıkalmış yüreğim, sonbaharı yaşıyor...

04.04.04', 'Beyaz bir bisikletin üzerinde; giden anılarım... Günbatımdan karanlığa doğru yol alırken... Ağustos böceklerinin sesleri ile,  Sarmaşık güll...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-yaz-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün (...)', 'huzun-feysah-can-tmmox', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biktim artik hayattan,

Biktim caresizce sevgiyi aramaktan,

Anlayişsiz insanlarla dolu şu dünyadan, 

Uykusuzlukla anlaşmiş gecelerden,

Ve hüznü aşka tercih eden yüregimden,

Niye anlaşılmaz olur bazen sözler,

Sevgiyle içtenlikle söylenseler bile? 

Niye sevginin degerini anlayamaz insanlar,

Dünyada ondan degerli baska birsey olmadigi halde? 

Niye hüzüle biter sonsuz denebilecek  aşklar? 

Sevmek niye zor gelir bazen insana,

Sevmeye ekmek gibi su gibi ihtiyaci varken bile?', 'Biktim artik hayattan, Biktim caresizce sevgiyi aramaktan, Anlayişsiz insanlarla dolu şu dünyadan,  Uykusuzlukla anlaşmiş gecelerden, Ve hüz...', ARRAY['Türk Edebiyatı','Şiir','Feysah Can']::text[], 8.5, '{"poet":"Feysah Can","poet_slug":"feysah-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzun-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşarken Öğrendim', 'yasarken-ogrendim-sirma-mersin-lijn6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakarken görmeyi,

Konuşurken düşünmeyi,

Dokunurken hissetmeyi, öğrendim...

Yaşarken öğrendiğim, öğrenirken; acıları yaşadım...

Defalarca bozduğum yeminler,

Adını unutamadığım sevinçler,

Sayfalar dolusu, anılar varken...

Ardıma bıraktığım izlerde; 

Herşeyin çözümü olacak...

6.4.04', 'Bakarken görmeyi, Konuşurken düşünmeyi, Dokunurken hissetmeyi, öğrendim... Yaşarken öğrendiğim, öğrenirken; acıları yaşadım... Defalarca boz...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasarken-ogrendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün (4)', 'huzun-4-feysah-can-h5vc7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen hiç sabahladinmi sevdigini düşünürken,

Hiç hüznü solukladinmi oksijen yerine,

İçin kan aglarken bile gülmek zorunda kaldinmi insanlara,

Birdaha sevmemek üzere ettigin yeminlerin

Hangisine sadik kalabildin,

Ve unutnaya and içtigin sevgiliyi unutabildinmi? 

Hiç başaramadin bunlari,

Çünkü yüreginde bu sevda vardi,

Nezaman atarsan bu sevdayi yüreginden 

İşte ozaman hüznü unutur yüregin,

Ama sende bilirsin ki 

Baharçiçegi ayrilmaz bu yürekten 

Yürek ayrilincaya dek bu bedenden', 'Sen hiç sabahladinmi sevdigini düşünürken, Hiç hüznü solukladinmi oksijen yerine, İçin kan aglarken bile gülmek zorunda kaldinmi insanlara, ...', ARRAY['Türk Edebiyatı','Şiir','Feysah Can']::text[], 8.5, '{"poet":"Feysah Can","poet_slug":"feysah-can","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/huzun-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmekse', 'sevmekse-feysah-can-clwtf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmekse en cömertçesini yapmadimmi? 

Koşulsuz kredi açmadimmi kalbimim en güvenilir bankasından,

Peki bu güvensizlik niye*

Niye hicranla bitti bu sevda? 

Hayat anlamini kaybetti seni kaybettigim anda,

Kaybettim özgüvenimi ve sevebilme yetenegimi

Hüzne aşina bir yürek taşiyorum, taşimaktan yoruldugum,

ama herşeye ragmen sevmek istiyorum,

sevmek istiyor yüregim seni,

ve seviyorum bahar çiçegim hala delicesine seni

mutluluklar senin olsun sevdigim,

ben yine hüzünleri alirim..', 'Sevmekse en cömertçesini yapmadimmi?  Koşulsuz kredi açmadimmi kalbimim en güvenilir bankasından, Peki bu güvensizlik niye* Niye hicranla bi...', ARRAY['Türk Edebiyatı','Şiir','Feysah Can']::text[], 8.5, '{"poet":"Feysah Can","poet_slug":"feysah-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmekse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak Kolay Değil', 'unutmak-kolay-degil-umut-koroglu-5urpw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unutmak kolay değil arkadaş

Beraber geçen o günleri

Sana ağlayan kalbimdeki yerini

Söküp atmak kolay değil arkadaş

Hani sahil kenarında oturmuştuk ya arkadaş

Fethiye’nin o eşsiz güzelliğinde

Mavilim’i söylemiştik akşam serinliğinde

O günleri unutmak kolay değil arkadaş

Masmavi uzanıyordu akdeniz arkadaş

Sırt sırta vermiştik ağustos sıcağında

Bir de fotoğraf çekinmistik

Hiç bitmesin diye bu rüya arkadaş

Kafaları çekmiştik ustayla arkadaş

Bugünler de gelir geçer diyordu

Belki de ayrılacağımızı biliyordu

Ayrılığı kabullenmek kolay değil arkadaş

Suskunluğun yaralar beni arkadaş

Ne bir haber, ne bir selam var senden

Nerde o gülüşün merhaba derken içten

Yakınken uzak olmak kolay değil arkadaş

Artık görüşemez olduk arkadaş

Hatrımızı soramaz olduk

Bunca paylaşılandan sonra

Şimdi ayrı gayrı mı olduk arkadaş

Beraber güldük beraber ağladık arkadaş

“Yar yanağından gayrı paylaşmak için herseyi” diyerek

Bir gün sonumuzun geleceğini bilerek

Yine de kenetlendik birbirimize arkadaş

Yiğit sevdimi tam severmiş arkadaş

Yarini kolay kolay bırakmazmış

Ona tapar, ona yanar, onun için yaşarmış

Sana layık olmak kolay değil arkadaş

Sevmek yürek istermiş arkadaş

Seven yardan başkasını görmezmiş

Yalvarmak yakarmak boşuna

Gönül ferman dinlemezmiş arkadaş

Köroğlu burkulur içim arkadaş

Bakma sen mutluluktan gözümden akan yaş

Istesem  de unutamam seni

Unutmak kolay değil arkadaş', 'Unutmak kolay değil arkadaş Beraber geçen o günleri Sana ağlayan kalbimdeki yerini Söküp atmak kolay değil arkadaş Hani sahil kenarında otur...', ARRAY['Türk Edebiyatı','Şiir','Umut Köroğlu']::text[], 8.5, '{"poet":"Umut Köroğlu","poet_slug":"umut-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/unutmak-kolay-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Damlada Binbir Bela', 'her-damlada-binbir-bela-necmi-unsal-2dvgs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağan yağmur  değil;  damla-damla  gözyaşım.

Yağmurlarda  bereket...

Her  damlada  bin bir  bela,  dertte  başım.

Ey keder  beni  terket! 

Beni  söyler  masallardaki  her  kör  kuyu; 

Kah  kendimi  bulurum  devlerde.

Bir  fırtına  eser  kuyuda,  kurumuş  acı  suyu.

Kah  yatarım  kapısız  bacasız  evlerde.

10  Şubat 2004 Salı,  Danimarka-Køge  22.03', 'Yağan yağmur  değil;  damla-damla  gözyaşım. Yağmurlarda  bereket... Her  damlada  bin bir  bela,  dertte  başım. Ey keder  beni  terket!  B...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/her-damlada-binbir-bela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyumsamalar', 'duyumsamalar-cigdem-bir-genc-98wj3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akıp gidiyor hayat...

Tüm gürültüler bir senfoni

Ve bizler akordu bozuk  enstrümanlar gibiyiz 

Ayrı notalardan aynı besteyi çalmaya uğraşan

Ortak paydamız yaşamak

Ve sevmek 

ve  tutunmak bir bedene....

yaşadık....

Anılar biriktirdik 

Kimini naftalinleyip sakladık

Kimini attık bir köşeye rutubetten sararttık

Unutmak istedik 

Unutmuş gibi yaptık

En sevdiklerimizi çerçeveleyip duvara astık...

yaşamak

tüm kafiyeleri hiçe sayıp 

kendi şiirimizi yazmak

ve duyumsamak

gürültülerin içindeki senfoniyi

akıp giderken önümüzden  koca bir hayat...', 'Akıp gidiyor hayat... Tüm gürültüler bir senfoni Ve bizler akordu bozuk  enstrümanlar gibiyiz  Ayrı notalardan aynı besteyi çalmaya uğraşan ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duyumsamalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meze', 'meze-aydin-ceran-0bge7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çalıntı kurmacaların ortasındayım, 

Bol limonlu sıkılmaların sonun da,  içine düşüyorum.

Akşam dan kalma sevda kırıkları; 

Sabaha çok var daha, soluksuz.

Kahvaltılar, acele yine, 

Elinden gelen meze.....

Ben sadece yollara bakarım,

Bakarım yollara, yolculuk eşikte

Ve

Bir akşamüstü, bir uğurlama şarkısından fazlasıdır.

Mezesiz, katıksız gibi aşk 

Yollara kalan.', 'Çalıntı kurmacaların ortasındayım,  Bol limonlu sıkılmaların sonun da,  içine düşüyorum. Akşam dan kalma sevda kırıkları;  Sabaha çok var da...', ARRAY['Türk Edebiyatı','Şiir','Aydın Ceran']::text[], 8.5, '{"poet":"Aydın Ceran","poet_slug":"aydin-ceran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/meze-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık kalp', 'kirik-kalp-sema-aka-c72ot', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşündüm dün gece

Seni özleyişlerimi, bekleyişlerimi

Birbirimize verdiğimiz sözleri

Heyecan içinde bana gelişini

Yaşanan o güzel günler nerede şimdi? 

Dolu dizgin yaşanan bitimsiz bir sevdaydı

Uğrumda ölümü bile göze alırdın hani

Bizi kimse ayıramazdı sözde 

Bir sözünle sonunu getirdin tüm hayallerin

Üzgünüm, seni yakıp yıktığım için

Suç kimde nerede o güzel günler? 

Üzgünüm, bütün bu olanlar için

Seni kırdığım umutlarını yıktığım için

Yerine getiremediğim bütün sözlerim için

Seni sonsuza dek bekleyemediğim için

Affedilmiyor kırıcı sözler,

Unutulmuyor yerine getirilmeyen boş vaatler

Kalbim kırıldı onarılmıyor ne yazık

Üzgünüm seni üzdüğüm için,

Seni, beni sevdiğin kadar sevemediğim için! 

09.04.2004', 'Seni düşündüm dün gece Seni özleyişlerimi, bekleyişlerimi Birbirimize verdiğimiz sözleri Heyecan içinde bana gelişini Yaşanan o güzel günler...', ARRAY['Türk Edebiyatı','Şiir','Sema Aka']::text[], 8.5, '{"poet":"Sema Aka","poet_slug":"sema-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kirik-kalp-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-aydin-ceran-7gl8h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yollar var gitmek için,

Yollar var ağlamaklı.....

Eninde sonunda biterken aşk,

Ben bir yolun ortasın da başlamamış hayallerin içindeyim.

Buralar uzak, 

Sahrada ki yalnız ağaç gibi

Süphan eteksiz; 

Kelimeler yalnız bir sis ,

Üzerime kalır, ıslak.

Aşkın anlatılmayacak hali, yollar kadar uzak.......', 'Yollar var gitmek için, Yollar var ağlamaklı..... Eninde sonunda biterken aşk, Ben bir yolun ortasın da başlamamış hayallerin içindeyim. Bur...', ARRAY['Türk Edebiyatı','Şiir','Aydın Ceran']::text[], 8.5, '{"poet":"Aydın Ceran","poet_slug":"aydin-ceran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yol-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
