            /embed/td', '/font/p font color=''#800000''htmlP align=center brDIV style=''BACKGROUND-COLOR: #333333''font face=arialfont size=4font color=pink img src=''htt...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/elveda-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Resim', 'eski-bir-resim-halil-i-brahim-ozdemir-9nzlp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kenar dantel kırığı, eskilerden bir resim,

Arkaya not düşülmüş, bu tanıdık bir isim,

Geçmişini kaybetmiş geleceği muamma,

Kış sıcağı tebessüm ve sadece bir cisim...', 'Kenar dantel kırığı, eskilerden bir resim, Arkaya not düşülmüş, bu tanıdık bir isim, Geçmişini kaybetmiş geleceği muamma, Kış sıcağı tebessü...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eski-bir-resim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştü', 'dustu-halil-i-brahim-ozdemir-bjghm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Halay çeker oynardık düğünlerde toylarda..

Aslan yelesi kollar, uçuşan kanat düştü.

Mermi hızıyla koşan, şimşekler gibi çakan,

Gün ışığı yarışan bedenden sür’at düştü…

Şaire ilham olan dağ bayır çalıp gitti,

Çağlamaz oldu artık, gönülden Fırat düştü…

Doludizgin koşardı o serhat boylarında

Gün geldi tökezledi sevdiğim kırat düştü.

Vermeye kıymadığım ömrümü alıp gitti..

Sermayeden an be an, dakika, saat düştü…

Her şeyiyle mükellef, hem hakimdi hem mahkum,

Dostun eline teslim, insandan salat düştü…', 'Halay çeker oynardık düğünlerde toylarda.. Aslan yelesi kollar, uçuşan kanat düştü. Mermi hızıyla koşan, şimşekler gibi çakan, Gün ışığı yar...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dustu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kılavuz', 'kilavuz-hakki-hakan-kaya-djpak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Siler mi bir mavi

teninden kokunu,

denizdesin ki! 

hangi boran

yıkar

dokunduğum yerleri,

hislerimle izlerim

daima kokundur kalan,

kokun

kalıcı bir kılavuzdur

bedenimi yakan...', 'Siler mi bir mavi teninden kokunu, denizdesin ki!  hangi boran yıkar dokunduğum yerleri, hislerimle izlerim daima kokundur kalan, kokun kalı...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kilavuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkla Dokunuşun', 'askla-dokunusun-cafer-tayyar-ozkan-4d760', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben değilim sadece insafsızca reddettiğin,

Koskoca ömre bedel sevdaya attığın kurşun,

Uğruna gözyaşı döküp umutla yer edişin,

Hafızamda duruyor hala ilk günkü duruşun.

Kalplerimize anlamsız günahları koymadık,

Boynumuza boş yere aşk yeminleri asmadık,

Yaşadığımız hiçbir anı macera saymadık,

Dudağımda eriyor hala son günkü öpüşün.

Dile gelmedi sözler, düğümlendi boğazımda,

Yalan bilmedi gözler, son nokta darağacında,

Belki akmadı yaşlar, korkulardan gümüşlüde,

Yanağımda geziyor hala aşkla dokunuşun.

23 Şubat 2004 Ankara', 'Ben değilim sadece insafsızca reddettiğin, Koskoca ömre bedel sevdaya attığın kurşun, Uğruna gözyaşı döküp umutla yer edişin, Hafızamda duru...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askla-dokunusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Güldüm', 'cok-guldum-recep-onal-rx4tz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adının önünde ünvan bulunan

Nice insanlar gördüm

Topsakal ve piposuna aldanıp

Entellektüel sandım

Kusuruma bakmayın densizlik edip

Güncel bir soru sordum

Çeyrek saat bekleyerek aldığım cevaba

Çok güldüm', 'Adının önünde ünvan bulunan Nice insanlar gördüm Topsakal ve piposuna aldanıp Entellektüel sandım Kusuruma bakmayın densizlik edip Güncel bi...', ARRAY['Türk Edebiyatı','Şiir','Recep Önal']::text[], 8.5, '{"poet":"Recep Önal","poet_slug":"recep-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cok-guldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne oldu', 'ne-oldu-kamil-boyraz-gr2za', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılık yok diye yeminler ettin

Ne çabuk usandın çekipde gittin

Sönmez bir alevdin küllenip bittin

Ne oldu sevgilim ne oldu sana

Şimdi mutlumusun gittin ellere

Kutsaldı aşkımız düştü dillere

bilinmez nazarmı değdi bizlere

Ne oldu nur tanem ne oldu sana

Bir çare eserini görmek istersen

Dönüpte arkana baka bilirsen

Tanrının aşkına bir kere gelsen

Ne oldu aşkına ne oladu sana

Tanrıdan sonra beni bilirdin

Haşa ondan başka beni severdin

istersem benimle öle bilirdin

Ne oldu sevgilim ne oldu sana', 'Ayrılık yok diye yeminler ettin Ne çabuk usandın çekipde gittin Sönmez bir alevdin küllenip bittin Ne oldu sevgilim ne oldu sana Şimdi mutlu...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-oldu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Yüreğime Söz Geçirebilsem', 'su-yuregime-soz-gecirebilsem-hafize-zuluflu-fthbs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce sözlerinle güldün yüzüme

Sonra uzak uzak durdun gözüme

Ne bahaneler ürettin işler çıkarttın

Lüzumsuz kaprisler yaptın

Sevgimi görmezden gelip yabana attın

Seni bedavaya satmak var ama

Şu yüreğime söz geçirebilsem

Ne tuzaklar kurdun nice denedin

Daha dün gibi hatırımda

Seni çok özledim dedin

Yüz kere tutamayacağın sözler verdin

Bu sevdadan dönmek var ama

Şu yüreğime söz geçirebilsem

Sanma ki dünyada yok benzerin

Niyetim olsa nicelerini kapıma dizerim

Ben sadece seni sevdim

Az değil tam üç sene emek verdim

Emeğimden vazgeçmek var ama

Şu yüreğime söz geçirebilsem

15 Nisan 2004', 'Önce sözlerinle güldün yüzüme Sonra uzak uzak durdun gözüme Ne bahaneler ürettin işler çıkarttın Lüzumsuz kaprisler yaptın Sevgimi görmezden...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/su-yuregime-soz-gecirebilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoğu Kere...!', 'cogu-kere-bayram-tunca-csbnc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah söyledim suç oldu/söylemedim suç oldu

Deveyi hendekten atlatmaktan da güç oldu

İnanmazsan bak saçtan önce sakal ak oldu

Evvel böyle değildi ne olduysa aşktan oldu

B. Tunca/14.04.2004-14.04-İst.', 'Ah söyledim suç oldu/söylemedim suç oldu Deveyi hendekten atlatmaktan da güç oldu İnanmazsan bak saçtan önce sakal ak oldu Evvel böyle değil...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cogu-kere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin varmı', 'haberin-varmi-pasa-ceten-1iams', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş tutunur ayın nazına

Senin zamandan haberin var mı

Kor dökülür ellerime

Senin zamandan haberin var mı

Düşmüşüm saçlarına uzar yollarım

Sabaha çıkacak kapım kalmadı

Yüreğim,aşkım,nefesim,çilem

Senin zamandan haberin var mı

Aşkın benliğimde şiir

Göz bebeklerimde bahar

Ey renklerin birleştiği rüya

Senin zamandan haberin var mı

Çırılçıplak şimdi göklerin

Doruğundayım bir kara sevdanın

Ey yolumu kesen güzel şaki

Senin zamandan haberin varmı', 'Güneş tutunur ayın nazına Senin zamandan haberin var mı Kor dökülür ellerime Senin zamandan haberin var mı Düşmüşüm saçlarına uzar yollarım ...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haberin-varmi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-pasa-ceten-2u2q2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kuş olur da uçarmış

Uzaktan uzağa

Müminlerin dualarında

Toprak,

Bağrını açar da ağlarmış

Bülbüller ağaç dallarında

Sonsuzluktan  sonsuzluğa

Göz yaşı dökermiş

İklimlerin en güzelinde 

Ortasında bir beyaz atlasın

Hoş,tatlı bir rüzgarla 

Yakından uzaklara

Yayılırmış gözyaşı

Gözyaşı,

Akşamın kızıllığı

Mavinin kirpiklerinde

Denizleri boyarmış

Halka halka dalgalar

Yan yana gidermiş 

Gözyaşında

Gözyaşı,

Bir kuş olur da uçarmış

Beşikten mezara

Ayrılık yok ölüm yok

Sevgilinin diyarında

Medeniyet kurarmış

''''Allah bir,Peygamber hak'''' diye', 'Bir kuş olur da uçarmış Uzaktan uzağa Müminlerin dualarında Toprak, Bağrını açar da ağlarmış Bülbüller ağaç dallarında Sonsuzluktan  sonsuzl...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gozyasi-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '23 Nisan', '23-nisan-ozan-ozel-cv3ze', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk Meclisin açıldığı günde 

Bayram olur bizde 

Gelin katılın siz de 

Kutlu olsun 23 Nisan 

Atatürk''ten bizlere 

En güzel armağandır 

Söyleriz hep birlikte 

Kutlu olsun 23 Nisan', 'İlk Meclisin açıldığı günde  Bayram olur bizde  Gelin katılın siz de  Kutlu olsun 23 Nisan  Atatürk''ten bizlere  En güzel armağandır  Söyler...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/23-nisan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirlendik', 'kirlendik-aysel-coban-8ec7f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'An gelince bir tarla ortasında doğan

Ot yığınlarının arasında büyüyen

Yenisini göremediğimiz eskilerle

Analarımızdı bizi sırtında taşıyan

Çalışırken sırtında bağlı tuttuklarıyla

İstedikleri tertemiz bir nesildi

Başaramadık temiz kalmayı

Doğduğumuz yerlerde kaldı masumluğumuz

Hep böyle kalacaktık, hep böyle temiz

Olmadı kirlendik.

Bıyıklarımız terlemeden elimizde tırpan

Dor bir atın sırtında gençliğimiz

Şafakta söken güneşin arkasında hayallerimiz

Babalarımızdı bizi asker ocağına hazırlayan

Her dönüşümüz, sevdalarımız için bir ümitti

Daha iyi bir yaşam için çekip gidilirdi gurbete

Kazanamadık bu savaşı

Doğduğumuz köylerde kaldı sevdalarımız

Hep sevecektik, hiç vazgeçmeyecektik.

Olmadı vazgeçirildik.

Bir göçtü içimizde beklentiler, bir yeni hayattı

Bu şehrin büyüsünde kaldı geleneklerimiz

İkili yaşadık bu şehri varoş sırtlarında

İdeallerimizdi bizi hayata bağlayan

Her direnişimiz, biraz daha yakınlaştırırdı çaresizliği

Kim olduğumuzu sorgularken,

Ne çocukluk, nede gençlik kaldı bedenimizde

Yenemedik bu haksızlığı

Doğduğumuz evlerde kaldı çocukluğumuz

Hep çocuk kalacaktık, hiç büyümeyecektik.

Olmadı zamanı durduramadık.', 'An gelince bir tarla ortasında doğan Ot yığınlarının arasında büyüyen Yenisini göremediğimiz eskilerle Analarımızdı bizi sırtında taşıyan Ça...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kirlendik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekbir olur', 'tekbir-olur-pasa-ceten-ljczk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani bir çocuk atına biner gider bir gün

Atının ayak sesleri döner tekbir olur

Göklerin kıyılarına vuran emelleri

Güneşle terler tekbir olur

Karanlıklar yerin altına serilir

Gölgeler bile bağlanır konur zindana

Işık damlar ateşten toprağa

Gecede yıldızlar çatlar tekbir olur

Dallar birleşir ulu kökte

Uzaklar yakın olur bu yürekte

Göğün altı üstü çepe çevre şenlik

Akıl dilde çoşar tekbiir olur

Battım bu sevdaya dizlerime kadar

Vicdan kanar göze al olur göz yaşı

Bir ocakki suları sulara köprü yapar

Rüzgar da tutar dallarda tekbir olur

Patlar o gün damarlarımda kanım

Gök tersine döner yerini bulur

Düşsede ayrılığa bu yolun yolcuları

Sessizlik içinde süzülür tekbir olur

Neslim susuz kalmaz artık

Toprakta döl sabahı bekler

Sevgi yıkar ayrılık bendini

İlahi bayrağın altında tekbir olur', 'Hani bir çocuk atına biner gider bir gün Atının ayak sesleri döner tekbir olur Göklerin kıyılarına vuran emelleri Güneşle terler tekbir olur...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tekbir-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçilmez sevdalardan', 'gecilmez-sevdalardan-pasa-ceten-kiyf6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden uzak olmak istiyorum

İki dudağın arası kadar

Aklıma düşerken bir görsen

Dalda yaprak gibi çırpınırım

Bil ki bir kapıldım erişilmeze

kulaklarımda hüzünün ağır faslı

Ey kalbimin dinmez ağrısı

Anladımki terkibi ateşmiş aşkın

Bildim saf derdimi susdum aleme

Kavruluyor bir çiçek can kafesimde

Denize ulaşmaz yağmurumun rengi

Çıkmaza sürüklenen sel gibiyim', 'Senden uzak olmak istiyorum İki dudağın arası kadar Aklıma düşerken bir görsen Dalda yaprak gibi çırpınırım Bil ki bir kapıldım erişilmeze k...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecilmez-sevdalardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Kedilerim Şiirli', 'benim-kedilerim-siirli-nal-n-yildiz-nul3y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerim kedi patileri

Sevincim kedi mırıltısı

Şiirlerimde besliyorum kedilerimi

Evde doktor yasakladı...

Bir şiirden ötekine atlıyorlar

Kiminin sesi 

Kiminin nefesi bulaşıyor yazdıklarıma

İçimde bir kedi

Sesimde bir kedi...

Dilim de kedi

Saçlarım sarman

Yalanıp taranmaktan

Zihnim de kedi

Kaç defa atıldım Araf''tan 

Kaç defa pusulasız döndüm? 

Gözlerim kedi gözleri,

Donup kalıyorum yol ortasında

Kaçamıyorum

Bir canım hayatı koklarken,

Bir canım köprüden atlarken gitti,

Ötekiler faili firâr kazalarda

Geride iki canım var şimdi

Beni ölene kadar yaşatacak...

Ellerim kedi patileri

Sevincim kedi mırıltısı

Şiirlerimde besliyorum kedilerimi

Evde doktor yasakladı...', 'Ellerim kedi patileri Sevincim kedi mırıltısı Şiirlerimde besliyorum kedilerimi Evde doktor yasakladı... Bir şiirden ötekine atlıyorlar Kimi...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/benim-kedilerim-siirli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız Ada', 'issiz-ada-tulay-sustam-ak0ck', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani derler ya; 

Issız bir adaya gitsen,

Yanında götüreceğin üç şey? 

Ben her seferinde...

“Kendimi, kendimi, kendimi” götürürdüm.

Üç şeye gerek yok

Ben her gidişimle her şeyimi beraber götürüyorum

Ailemi, seni, dostlarımı, kağıdı mı, kalemi mi

Keşke! ...

Senin gibi olabilsem

Gittiğim de hiçbir şeyi kendimle götürmesem

Sen; giderken kendini bende bırakıyorsun

Her şeyimi benden alıp öyle gidiyorsun

Ama bunu hiç mi hiç anlamıyorsun

Ben ise giderken geride hiçbir şeyimi bırakmıyorum

Ben nereye, sahip olduklarım oraya

Aslında ne güzel şey; 

Giderken her şeyi geride bırakmak

Tek başına yolculuğa çıkmak

Ve tek başına geri dönebilmek

Ama olmuyor ben bunu yapamıyorum

Sevgili! ...

Senden kurtulmanın yolu yok mu? 

Bu son yolculuğumda...

Heybemin içine bir tek seni koydum

Seni bir uçurumdan aşağıya atacağım

Nasıl bıraktım seni öyle boşluktan aşağıya

Hala inanamıyorum kendime

Ama...

Yine içim rahat etmedi

Senden önce yere ben indim

Yine kucak açtım sana...

Yine sensiz yapamadım...

Yine sensiz olamadım...

(İstanbul, 15.04.2004)', 'Hani derler ya;  Issız bir adaya gitsen, Yanında götüreceğin üç şey?  Ben her seferinde... “Kendimi, kendimi, kendimi” götürürdüm. Üç şeye g...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/issiz-ada-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş yağmurları', 'ates-yagmurlari-pasa-ceten-t6vei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin ulaşamadığı yeri çevirmem

Ben kara sevdayı dokuyanım

Ben karıncaların yolundan giden

İsterse gök eğilip başımı okşamasın

Zamandan soyulan rengime bakın

Toprağımdan kan ve ter fışkırıyor

Gönlüm dert açıyor dertler üstüne

Sabır kaplıyor tüm bedenimi

Sefere çıkıyorum,Kırmışım pusulamı

Acılarım ve ağrılarım ve elemlerim

Morfini vuruyor ateş yağmurlarım

Yatağım soğuk elimde ışığın anahtarı', 'Güneşin ulaşamadığı yeri çevirmem Ben kara sevdayı dokuyanım Ben karıncaların yolundan giden İsterse gök eğilip başımı okşamasın Zamandan so...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ates-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-pasa-ceten-hqkq0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her akşam can evime serilen kadın

Bilirmisin günahlarım senin elinde dokunur

Yaralarsın da hem yarasın yaramı

Talan edersin gençliğimi

Son mektubumuz bulutlardan olsun

Kalmıyor bu yürek o gözlere

Ruhumun dilinde kanat sesi var

Dudaklarıma gelmiş ölümü bekliyorum

Çiçeklere mi koysam seni ben

Duygularımdan bile naziksin

Bilirsin kaç kez yıkadım tevbelerle

Ört üstüme aşkın beyaz örtüsünü', 'Her akşam can evime serilen kadın Bilirmisin günahlarım senin elinde dokunur Yaralarsın da hem yarasın yaramı Talan edersin gençliğimi Son m...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kadin-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne arıyor', 'ne-ariyor-pasa-ceten-h1o0r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayın sevgisi gök yüzünü sarıyor

Yıldızlar göğün derinliğinde ne arıyor

Oturmuş tarıyor saçlarını sevgilim

Şaşkın tarak tellerin arasında ne arıyor

Dil peşinde gelmiş ile geleceğin

Bu sırrın içinde göz ne arıyor

Arzularım yalın kılıçtan keskin

Korkum kefenimde ne arıyor

Ve en son üstündeyin soylu bir atın

Bu hayal deryasında gerçek ne arıyor', 'Ayın sevgisi gök yüzünü sarıyor Yıldızlar göğün derinliğinde ne arıyor Oturmuş tarıyor saçlarını sevgilim Şaşkın tarak tellerin arasında ne ...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-ariyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara Yolculuk', 'bahara-yolculuk-sair-abdulkadirartiran-sqa5l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sokakların aşkını izliyorum bir kaldırımda 

Kederli geceyle el ele 

Yükselirken göğe bir güvercin kanadında 

Düşüyor sineme bir velvele 

Aklıma ay yüzlü nevhayalin gelir 

Artar sevgim 

Bu dert bir boşluğa itiverir 

Düşer bedenim 

Canım acır yüreğim yanar gördükçe seni 

Söyleyemem içimdekini 

Ah! Bir duyabilsem vuslatın sesini 

Düşünmem gerisini 

Bakışlarım duvarda gökkuşağını kovalar 

Gözyaşları ardından 

Aşkının füsunlu renkleri canlanır 

Kalbimin kuytularından 

Sevgiyi toprağa gömen bir fani 

Sesimdeki kendim 

Bir bahar sabahı filizlenecekti hani 

Hazan dolu sevgim 

Sen hayalimin ufkunda firdevsi renktin 

Her köşeden görülen 

Ruhuma gizliden sinen bir güzelliktin 

Her mısramda hissedilen 

Sonsuzluğa açılan bir vapurun çığlığında 

Bulduğumda seven gönlü 

Ötelerin hazzını duyarım senin aşkında 

Ey! Baharı tutan ay yüzlü', 'Sokakların aşkını izliyorum bir kaldırımda  Kederli geceyle el ele  Yükselirken göğe bir güvercin kanadında  Düşüyor sineme bir velvele  Akl...', ARRAY['Türk Edebiyatı','Şiir','Şair Abdulkadirartıran']::text[], 8.5, '{"poet":"Şair Abdulkadirartıran","poet_slug":"sair-abdulkadirartiran","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bahara-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat geldi kalbime dayandı', 'vuslat-geldi-kalbime-dayandi-pasa-ceten-453a2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vuslat geldi kalbime dayandı

Ve ben bir renk gibi şımardım

Tatlı telaşım kanat çırpıyor yüreğimde

Umut,dokunduğumbaharın ortasında

Sevgi ilinden uzaklara

Göklerin ıssızlığına sürüldüğüm günler hey

Gözleri güneş,saçları mevsimler

Arada bir eksen gibiyim artık

Şimdi başım kucağında...

Zamanı ikiye bölen ayna gibi

Elimde aşkın kılıcı.

Görmesi kolay anlatması ölüm', 'Vuslat geldi kalbime dayandı Ve ben bir renk gibi şımardım Tatlı telaşım kanat çırpıyor yüreğimde Umut,dokunduğumbaharın ortasında Sevgi ili...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vuslat-geldi-kalbime-dayandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saydam Boşluk', 'saydam-bosluk-can-arslan-evhsw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elimizden 

boşluk

d

  ü

    ş

      e

         r

saydam, beton yüzeylere

cam 

kı

-rık

-la

-rı

-nın

sesi batar

çıplak,saydam yüreklere', 'Elimizden  boşluk d   ü     ş       e          r saydam, beton yüzeylere cam  kı -rık -la -rı -nın sesi batar çıplak,saydam yüreklere...', ARRAY['Türk Edebiyatı','Şiir','Can Arslan']::text[], 8.5, '{"poet":"Can Arslan","poet_slug":"can-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saydam-bosluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sensizliğe Satmasın', 'beni-sensizlige-satmasin-necmi-unsal-a1e03', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bal  yaptı  arılar  petek  petek.

Yağmurlarla  ıslandı  kaç  nisan! 

Aklandı  saçlarım  tek  tek.

Yokluğuna  sanki  birer  nişan! 

Tutarım  zamanın  hoyrat  nabzını.

Dursun,  hiç  ama  hiç  atmasın! 

Mühürledim  köle  pazarlarının  kapısını.

Beni  sensizliğe  satmasın! 

24  Şubat 2004 Salı,  Danimarka-Køge  23.20', 'Bal  yaptı  arılar  petek  petek. Yağmurlarla  ıslandı  kaç  nisan!  Aklandı  saçlarım  tek  tek. Yokluğuna  sanki  birer  nişan!  Tutarım  ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beni-sensizlige-satmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beraat', 'beraat-reyhan-sur-r44jt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'diz dize otururken sevdayla umut

ve de göz göze

çıkagelir apansız ayrılık zulmü

usturası cebinde

lime lime umut

sevda kan kusar ateşler içinde

aşkolsun değebilene 

zulüm mü

müebbet demişler ya

beraat etmiş

demek iyi hali de varmış ayrılığın

uzatırmış kara saçlarını

sefasından 

ince uzun dar sokaklar gibi

sevdayla umutun da 

tırnakları uzarmış çektikleri cefadan

tırmalarlarmış ara sıra kendilerini

hala yaşadıklarını anlamak için...', 'diz dize otururken sevdayla umut ve de göz göze çıkagelir apansız ayrılık zulmü usturası cebinde lime lime umut sevda kan kusar ateşler için...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beraat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıntılarımdan', 'kirintilarimdan-reyhan-sur-qtloa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ayyaş 

gözleri biber kırmızı

ayyaşın oğlu

kan bürümüş gözünü

üstelik bana doğru

sözleri daracık sokak ana avrat

uzar gider uzun uzun belinde bıçak

durdurun durdurun

yakalanmışım

şimdi vurdu vuracak

***********

hava 

karardı kaldı

sanki üvey ana suratı 

hava burnundan soluyor...

daha yaz başında kış ortası gibi

havan kime

hadi hadii...

kus içindekileri de

rahatla...

************

soğan 

şair medet ummuş

aşk acısına zakkumdan aman

zıkkım çıkmış zakkum

aşk bazen bir baş soğan azizim

vuracaksın tepesine yumruğunla

acı sütü bir yana

cücüğü sana/ derman.....

**************

mortal 

bir kaptan daha düştü

hayat ağacı takviminden

yelkenler fora

yürek nekropol

yürek alabora...

*****************', 'ayyaş  gözleri biber kırmızı ayyaşın oğlu kan bürümüş gözünü üstelik bana doğru sözleri daracık sokak ana avrat uzar gider uzun uzun belinde...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kirintilarimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti..', 'bitti-alena-akin-ksrph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne çok bekledim seni

beklemek bile dayanamadı gitti

tek başıma kaldım

artık beklemiyorum

beklemek gitti

artık sevmiyorum

sevmek gitti

aşk gitti

gözyaşım bitti

bir ben kaldım

kalakaldım

bendende ben gitti

bitti...

gitti..

geriye tek sen kaldın...', 'ne çok bekledim seni beklemek bile dayanamadı gitti tek başıma kaldım artık beklemiyorum beklemek gitti artık sevmiyorum sevmek gitti aşk gi...', ARRAY['Türk Edebiyatı','Şiir','Alena Akın']::text[], 8.5, '{"poet":"Alena Akın","poet_slug":"alena-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bitti-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa dönüş..', 'yalnizliga-donus-alena-akin-9phb4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gene sana döndüm

yoksa sen hep burdamıydın? 

görmezden geldiğim senmiydin? 

gel ben vazgeçtim

gel yalnızlığım

elimde değilsin.', 'gene sana döndüm yoksa sen hep burdamıydın?  görmezden geldiğim senmiydin?  gel ben vazgeçtim gel yalnızlığım elimde değilsin....', ARRAY['Türk Edebiyatı','Şiir','Alena Akın']::text[], 8.5, '{"poet":"Alena Akın","poet_slug":"alena-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizliga-donus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğal', 'dogal-osman-i-slam-5p7ey', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'doğal olmalı insan 

daha doğal 

anlayışı sevisi 

teni dokusu 

nefesi kadar doğal 

bakışı kadar masum 

dili kadar kemiksiz 

yüreği kadar 

engin', 'doğal olmalı insan  daha doğal  anlayışı sevisi  teni dokusu  nefesi kadar doğal  bakışı kadar masum  dili kadar kemiksiz  yüreği kadar  eng...', ARRAY['Türk Edebiyatı','Şiir','Osman İslam']::text[], 8.5, '{"poet":"Osman İslam","poet_slug":"osman-i-slam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin yüzün', 'senin-yuzun-alena-akin-8skjs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüzünü tersine çevirip,

anlamaya çalıştım

tersi,tersimde kaldı

yüzünde,yüzemedim

ters,yüz ettim,yüzleştiremedim

yüzlerce kez denedim

senin yüzünü göremedim..', 'yüzünü tersine çevirip, anlamaya çalıştım tersi,tersimde kaldı yüzünde,yüzemedim ters,yüz ettim,yüzleştiremedim yüzlerce kez denedim senin y...', ARRAY['Türk Edebiyatı','Şiir','Alena Akın']::text[], 8.5, '{"poet":"Alena Akın","poet_slug":"alena-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/senin-yuzun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak', 'yaprak-osman-i-slam-uknal', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaprak olunca herşey 

sonu gelmiş gibi 

bırakıverir kendini 

ne duyar acıyı 

ne yağmuru 

ne soğuğu 

kurusa da artık 

parçalansa da 

ne bir kuşun 

ne bir devenin umurunda olur 

o sadece artık 

toprağın kucağındadır', 'yaprak olunca herşey  sonu gelmiş gibi  bırakıverir kendini  ne duyar acıyı  ne yağmuru  ne soğuğu  kurusa da artık  parçalansa da  ne bir k...', ARRAY['Türk Edebiyatı','Şiir','Osman İslam']::text[], 8.5, '{"poet":"Osman İslam","poet_slug":"osman-i-slam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaprak-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet olsun...', 'lanet-olsun-yusuf-ziya-leblebici-ih4qb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kar tipiye dönmüş, rüzgar ayaza

Kara sevda bana, bense karaya.

Binalar uykuya yatmış

         İstanbul suskun.

Lanet olsun,

Sen bugün de yoksun...

Yaşamın kıyısında olta atmışım sana

el, balığa takarken kancayı

ben, hasrete takmışım sevdayı.

Üstüne üstlük,

 balık da, hasret de bedava ya! 

Sen ateşler içindeyken

 titrer bedenim.

Üşürüm sana baktıkça

 sen esrarla yandıkca

  ben sana büzüşürüm.

Şiirlerim kurşun yediğinde

 sakat kalır kelimelerim.

Kalemim hasreti yazdıkça

 çığlık atar harflerim.

Lanet osun,

 sevdam hücrelerde

  ama, sen yanımda yoksun! 

Saçlarım senin yokluğunu taşıyamadı

gün gün ağardı

 gün gün karalardan ayrıldı.

Bana yüklediğin hasret

 belimi değil,

  yüreğimi kamburlaştırdı.

Bana verdiğin ayrılık

ateş mezralarında kor aldı

 ayaklarım yalınca yol aldı.

Yaşamın kıyısında olta atmışım

Deniz bir şarkı fısıldar kulağıma.

Martılar telli çalgıda

 sirenler kalın bir basta.

Acı bir güfte vurur şafaklarıma

rüzgar dolar damarlarıma.

Sen yoksun bu güftede

 bu denizde sen yoksun

  Lanet Olsun!', 'Kar tipiye dönmüş, rüzgar ayaza Kara sevda bana, bense karaya. Binalar uykuya yatmış          İstanbul suskun. Lanet olsun, Sen bugün de yok...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/lanet-olsun-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyhane', 'meyhane-yusuf-ziya-leblebici-032oy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir meyhane, oturduğun masada bir şişe

Dalgın ve demli bir kafa, düşüncense meze

Kadehdeki rakına su katmak da neyine

Akıttığın şu yaşlar var ya, yeter hepsine

Dertlice inleyen kemanın, dağlayan sesi

Hasretlik kokan sevda şarkısının güftesi

Okunan nakaratlar sanki O''nun nefesi

Beynindeki düşünce, bu masanın mezesi

Kadeh kaldırırsın karşındaki sandalyeye

Kimse yoktur ki, sen hayal kurarsın boş yere

Olsun be! Kendini bulduğun yer, bu meyhane

Gelenler hep gidicidir arama boş yere', 'Bir meyhane, oturduğun masada bir şişe Dalgın ve demli bir kafa, düşüncense meze Kadehdeki rakına su katmak da neyine Akıttığın şu yaşlar va...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/meyhane-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müstehcenim Bu Akşam', 'mustehcenim-bu-aksam-yusuf-ziya-leblebici-wkmxy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aykırıyım bu akşam,

 sana susadım.

Seninle sevişmek istiyorum 

bu içki masasında.

Elimi sürdüğüm her şey

sensin sultanım.

Gerdeğe giriyorum bu gece

bu alkol sınırında.

Bir yudum rakı,

bir yudum da sen

Hasretini meze yaptım geceme.

elimde sıktığım kadeh ellerin

kenarları dudakların..

Düğmelerini açıyorum 

şişenin kapağında.

Tutma ellerimi, sınır yok akşamımda.

Sen oturmuşken masama

sen oynaşırken karşımda

kadeh niyetine

seni alırım koynuma.

Müstehcenim bu akşam

Varsın olsun! 

Dağıt beni bu gece

dağıtalım şişeyi, masayı

dertler şurada dursun.

Haydi güzelim

uzat bana dudaklarını...', 'Aykırıyım bu akşam,  sana susadım. Seninle sevişmek istiyorum  bu içki masasında. Elimi sürdüğüm her şey sensin sultanım. Gerdeğe giriyorum ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mustehcenim-bu-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoktun...', 'sen-yoktun-yusuf-ziya-leblebici-baz40', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne köşe başlarında

köpeklerin hırladığında,

Ne de gölge adamların

çöpleri karıştırdığında

sen yoktun...

Günün, saçlarının karasına

 büründüğünde,

yıldızların birbirine

 sürtündüğünde

sen yoktun yine

 yoktun gecemde...

Kaşkolumla ayazdan 

 koruduğum kulaklarımda

Adımlarımı saydığım

 bu ısıssız sokaklarda

Aklıma gelen

 bin bir türlü şarkılarda

Sen yoktun yine

 Yoktun

  günümün bu hazanında...', 'Ne köşe başlarında köpeklerin hırladığında, Ne de gölge adamların çöpleri karıştırdığında sen yoktun... Günün, saçlarının karasına  büründüğ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-yoktun-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklerim', 'seni-beklerim-yusuf-ziya-leblebici-d9bsm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tesadüf ya, yıllardan sonra seni tekrardan gördüm

Geçen gün, geçen zaman seni ne çok değiştirmiş

Elin elini tutmuş bir de erkek çocuk gördüm

Demek ki son aşkın şirin bir meyvesini vermiş

Otuz metre ileriden aheslice yürüdünüz

Bir an dayanamayıp, koşup gelmek istedim

Lakin, siz ne benim karım, ne de çocuğumdunuz

Ve herşeyden habersiz yürüdünüz sakin sakin

Çocuğun da sana benziyor, senin kadar güzel

Saçları siyah, yanağı al...Burnu sen değilsin

Görmedim ama, belki de babasına çekmiş

Bırak şimdi babasın! ..Sen, hala çok güzelsin

Hani bizim de böyle çocuğumuz olacaktı

Hani kaşları saçları sana, burnu da bana

Hani gözü sana, eli bana benzeyecekti

Hani, elinden tutup gezdirecektik parkları

Böyle olmadı bir tanem, böyle olmamalıydı

Yine geldiğim gibi, geri gitmek zorundayım

Sen ellerin olmuşsun, benim umudum kalmadı

Gitmeliyim bir tanem, burada kalmamalıyım

Sen unut beni, unut aramızda geçenleri

Beni nasıl da seviyordun, öyle sev onları

Kocanı sev, çocuğunu sev, koy kenara beni

Ben unutmalıyım, unutmalıyım buraları

Yalnız! ..Belki bir gün, ölüm haberimi duyarsan

Mezarıma beklerim, unutma seni beklerim

Gül gibi yanaklarını toprağıma koyarsan

Mezarda bile onu gözyaşlarımla beslerim

Bu adam neyin oluyordu diye sorarlarsa

Sevdalımdı de, ben aşağıda seni dinlerim

O''nu bu kadar da çok mu seviyordun derlerse

Sevdamla öldürecek kadar demeni beklerim', 'Tesadüf ya, yıllardan sonra seni tekrardan gördüm Geçen gün, geçen zaman seni ne çok değiştirmiş Elin elini tutmuş bir de erkek çocuk gördüm...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/seni-beklerim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sende Sevdim', 'seni-sende-sevdim-yusuf-ziya-leblebici-4zxbf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben seni yarınlarımın dününde

şeker tutmayan balın özünde

savaşcıl arıların peteğinde sevdim.

Kadehdeki alkolün inadına

yanındaki saf suda,

Ben seni özümde

ben seni gönlümde sevdim..

Atların yelesinde

 başakların filizinde

 mısırın süpürgesinde

 saçlarını sevdim.

Damarımdaki kanda

 güllerin alında

 dudağını sevdim.

Barışın mavisinde

 denizin renginde

 gözlerini sevdim.

Ben seni yüreğimde

ben seni bende sevdim...', 'Ben seni yarınlarımın dününde şeker tutmayan balın özünde savaşcıl arıların peteğinde sevdim. Kadehdeki alkolün inadına yanındaki saf suda, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-sende-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi...', 'sevgi-yusuf-ziya-leblebici-m3xtt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir duygu olmalı dünyayı saran

Gül gibi, sevginin kokusunu yayan

Yağmur olup, göl oluşturmalı

insanlar sevgi içmeli

bir ceylan misali.

Çocuk gibi doğurulmalı sevgi

meme gibi emzirilmeli

dedelerin bastonu

bebelerin ninnisi

tüm evrenin güneşi olmalı.

Su kadar kutsal

nefes kadar yaşamsal

ölçümsüz olmalı.

Kağıt gibi

odun gibi yanmamalı...

Bir nefesse sevgi

derince çekmeli,

kaçırmamalı.

Sevgi yoksa eğer

hiç nefes almamalı.

Ya da; 

Son nefesi verdiğimizde

bizimle birlikte

toprağa sokulmamalı...', 'Bir duygu olmalı dünyayı saran Gül gibi, sevginin kokusunu yayan Yağmur olup, göl oluşturmalı insanlar sevgi içmeli bir ceylan misali. Çocuk...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgi-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otoban', 'otoban-yusuf-ziya-leblebici-2wtqr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendimi vurduğum bu bayırlarda

Vücudumu kaplamış yaralardan

damarlarım hesap sorar.

Hesap sorar önümdeki basamaklarda.

Bu günün dönüşü yoktur düne

hataları düzeltmeye.

Umutlarsa, 

              kimbilir? 

Her şey yarınlara gebe..

Neler gelir yelkovanlarla,

umut saniyenin sırtındadır

   bense, ardında tazı.

Yelkovan bazen kılıç gibi

   keser umutları

      beklediğim yarınları.

Akrebin kendi etrafında

     turladığı güzergahta

neler oldu neler o yolda

    ah bir dile gelseler.

Ne umutlar söndü

    ne insanlar yürüdü kolkola..

Bu zaman otobanında üç aktör

Yelkovan, saniye ve akrep

    çete kurmuş diktatör.

Rakamların her biri bir evren

Herbiri bir mazidir kalan dünden.

Bazen birinden birine

   aniden düşersin.

Bazen se, umut olur

   saniyenin sırtında gezersin...', 'Kendimi vurduğum bu bayırlarda Vücudumu kaplamış yaralardan damarlarım hesap sorar. Hesap sorar önümdeki basamaklarda. Bu günün dönüşü yoktu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/otoban-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ökkeş Emmi (Mektup I)', 'okkes-emmi-mektup-i-yusuf-ziya-leblebici-x9o3j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani bizim orda sivrisinekler vardı

Burada da vampir insanlar var.

Bizimkiler, bunlardan daha arlıydı

hiç değilse, gram gram çekerlerdi kanımızı

bunlarsa, kiloyla emiyorlar.

Hani davara kurt saldırırdı da

bir kaç koyunu alırdı ya

burda da binlerce koyunu alıyorlar

hem yiyor, hem de kanını içiyorlar...

Ne azık niyetine anamdan alıp

yüreğime koyduğum sevgim

ne de çocukluğumda öğrendiğim türkülerin

adı yok burda

çoğunun özüne gelmiyor

hoşuna gitmiyor bunlar

hoşuna gitmiyor çıkarcı zümrelerin...

Ne Veysel''in uzun ince bir yolu

ne de diğerlerini dinlemiyorlar

bizi büyüten türküleri...

Hani, harman sonu cebime koyduğum

üç beş kuruş var ya,

her kuruşuna kimbilir

kaç kez soluduğum o para

en büyük sevgiymiş burda, bilmezdim.

Paranın, insanlarda kan olduğunu 

burada öğrendim...

Ne insanlık kalmış, ne doğruluk

kimilerini hortumlar kapmış

kimileriyse

olmuş birer korkuluk...

Buraların mevsimleri bile bir hoş

kış mı güz mü çözemedim

yaz mı bahar mı bilemedim.

Kışın güneş gözlüğü takıp

salonlarda kararıyorlar

yazın sevgisizlikten üşüyorlar.

Hani elini sallasan

ellisi derlerdi ya

benimde çıktılar karşıma.

Elimi sallamadığım halde

heral, bol paralı sandılar beni de.

Kalbimimi, yoksa

başka bir şey mi istediler

çözemedim emme, yine de vermedim.

Veremezdim, bilirsin ben kalbimi

köyümdeki yavukluma vermiştim...

Evet Ökkeş Emmi,

daha kaç gün oldu

bu koca şehre geleli.

Şimdiden içimi sardı korku,

Kurtlar kaparmış bu şehrin acemisini.

Biz davardayken

sürüye kurt gelir miydi

gelir miydi görünce bizleri...

Bilmem ki Emmi,

bizim kurtlar biraz salaktı emme

bunların kurnazlığına göğüs gerebilir miyim

ya beni de katarlarsa sofralarına

ya beni de sokarlarsa aralarına

kendimi yedirmedim diyebilir miyim....

İşte böyle emmi, buralardaki sofralarda

ne anamın keşkeği, ne de yufka ekmeği var.

Milyonların yaşadığı, bu koca şehir İstanbul''da

kurtların sofrasında, sömürülen insanlar var.

Babamın yarısı Ökkeş Emmi,

ben buraya geldim geleli

ne yavuklumun mendilini

ne de anamın yüreğimdeki emanetini

kaybetmedim ben de beni.

Kaybetmedim,

Kurtlar sürse de izimi...', 'Hani bizim orda sivrisinekler vardı Burada da vampir insanlar var. Bizimkiler, bunlardan daha arlıydı hiç değilse, gram gram çekerlerdi kanı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/okkes-emmi-mektup-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ökkeş Emmi (Mektup II)', 'okkes-emmi-mektup-ii-yusuf-ziya-leblebici-f5c6g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köyler inmiş sokaklarına bir bir

Yerlisi kalmamış koca şehrin

Zapdetmişler her köşe başını

Bölüşmüşler taşını toprağını..

Taş para, toprak para, nefes para

O para da yoksullarda acı bir yara.

Hani bizim meydandaki pınar var ya

kesilmeden akar boğum boğum

kızlar helkelerle girerdi sıraya

o pınar var ya kurban olduğum

O suya hasretim Ökkeş Emmi.

Burda içtiğim suya para veriyorum

Yine de bulamıyorum o lezzeti...

Ne yoldan geçene bir selam

ne de sesleniş var

her konuştuğum kişide 

bir bekleyiş var.

İşçi elbisemle üstten bakıyorlar

memur gibi giyinirsem

bey diyorlar.

Sanki elbiselerin içinde 

para arıyorlar.

Aklıma hep bizim

süslü Naciye geliyor Emmi.

Demek ki o burada olsa

ona da astsolist deyip

yollarına yatacaklar...

Hani derler ya

oku da adam ol diye.

Burada binlerce genç okuyor

ama çoğu sürünüyor.

Meslek para getirmiyor Emmi

manavın duvarında mühendis diploması

sahtekarın duvarında teşekkür yazısı var.

Bize harf öğreten hocalar

pazarlarda limon satıyorlar...

Diyorsun ki şehirde kurt ne gezer? 

gezer Ökkeş Emmim gezer

İstanbul''daki kurtlar

ta burdan senin izini bile sürer.

Onların sofrasında

bir lokma olsan

dişlerinden kurtulamazsın

artık olsan sofradan atılan

başka kurtlardan kaçamazsın...

Buralar bir hoş, heveslenmeye gelmez

Hevesin kursağından aşağıya heç inmez.

Burda bebeler tezek bilmez, yulaf bilmez.

Hele bizim karakaçanın,

ırmakta yunan camızın

nasıl bir şey olduğunu bilemez.

Bir bilseler köyümün tadını

tertemiz havasını

unuturlarmı yer sofrasını? 

Bulgurun yanında soğana da

okkalıca vurdum mu yumruğu

onun cücüğünün tadını

camız yoğurdunun ayranını

iç babam iç, ye babam ye

Özledim be emmi sılamı..

Emme bu şehrin güzellikleri de var

Şairler yedi tepeli cennet derler.

Hele, denizinde yakamoz dedikleri

o parıltılar var ya.

Kıyısında aldım mı çayınan simidi

O sana göz kırpar sen de ona.

Merak etme emmi,

ne kadar kötü desem de

İyiliğini de yazacağım bu şehrin

sevmiyorum desem de...', 'Köyler inmiş sokaklarına bir bir Yerlisi kalmamış koca şehrin Zapdetmişler her köşe başını Bölüşmüşler taşını toprağını.. Taş para, toprak p...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/okkes-emmi-mektup-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sen yaptım...', 'seni-sen-yaptim-yusuf-ziya-leblebici-5rif9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey İstanbul; 

Şehir ettim ya seni.

İnkar etsen de,

sana çok şey öğrettim.

Yürürken koşmayı,

ağlarken gülmeyi.

İnsanların iki yüzünü gösterdim.

Taşları bir bir, üst üste dizdim,

Ev yaptım sana, seni şehir ettim...

Milyonlarca insan verdim ya

elbisesinin içinde olmasa da.

Köpekleri saldım sokaklarına

dört ayağı olmada da.

Kerhanana kadın, köşene dilenci

Köşklerine zengin, barakana yoksul

Toprağına ölü, viranene dilenci

sokaklardaki pezevengin

sermayesini vermedim mi? ..

Direnci kalmamış kurban,

kana susamış sülük istedin.

Kurbanını intiharla

sülüğünü vurgunlarla almadın mı

ne istersin daha? 

Ne kadar güzellik, o kadar çirkeflik

Ne kadar sadelik, o kadar çılgınlık

Bunlar değil miydi istediklerin...

Çorum''u, Sivas''ı, Erzincan''ı

kültürleri yığdım sana.

Birer köy yaptım sokaklarını

Toprak attım kıyılarına

Olta attım sularına...

Ey İstanbul; 

Boğaz''da rakımı yudumlarken

senin güzelliğinle övünen.

Pazarda hamallık ederken

soyuna, sopuna küfreden

ben değil miyim be İstanbul.

Seni sen yapan ben değil miyim! 

Sürünmedim mi yılanı kıskandırıcasına

Yüzmedim mi balıkların inadına.

Seni övdüm, sana küfrettim

Yine de seni taşımadım mı sırtımda.

Ey İstanbul; 

Ben sana bir uşak oldum

Sense bana

doymayan bir kanara...', 'Ey İstanbul;  Şehir ettim ya seni. İnkar etsen de, sana çok şey öğrettim. Yürürken koşmayı, ağlarken gülmeyi. İnsanların iki yüzünü gösterdi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/seni-sen-yaptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylemeden Nasıl Gittin', 'soylemeden-nasil-gittin-murat-demir-i01n0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arkadaşım iş ortağım sırdaşım

Karınağrım davadaşım yoldaşım

Delidolum tuzum aşım kırbaşım

Söylemeden nasıl gittin sen bensiz

Bilmez miydin yaşayamam ben sensiz! 

Sırma saçlım kalem kaşlım ak tenlim

Balık etlim pamuk ellim mor benlim

Dağım bağım balım yağım tan yellim

Buralardan nasıl gittin sen bensiz

Bilmez miydin yaşayamam ben sensiz! 

Kırlangıcım kelebeğim menekşem

Sevda köşem zevkim neşem dert şişem

Acım tatlım mutluluğum endişem

Habersizce nasıl gittin sen bensiz

Bilmez miydin yaşayamam ben sensiz!', 'Arkadaşım iş ortağım sırdaşım Karınağrım davadaşım yoldaşım Delidolum tuzum aşım kırbaşım Söylemeden nasıl gittin sen bensiz Bilmez miydin y...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/soylemeden-nasil-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizi yazıyorum', 'sizi-yaziyorum-yusuf-ziya-leblebici-c030l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önümde kağıdım, elimde kalemimle

Gecenizi paylaşıyorum sizinle

Sizlerden bir zümre, şehirden bir cadde

Sizleri yazıyorum dizelerimde.

Kiminizin ellerinden tutup koşuyor

Kiminizin dudaklarından öpüyor

Bazense kuytu yerlerde sürünüyor

Gökyüzünde rüzgar gibi esiyorum.

Duygulu şiirler yazıyorum size

Kimi zaman düzene isyan ediyor

Kimi zamansa sevdaya susuyorum

Sizleri akıtıyorum kalemimle

Hayatınızı paylaşıyorum sizinle

Kah tutsağım parmaklıklar içinde

Kah özgür bir kuşum gökyüzünde

Sizi yaşıyorum, siz bilmeseniz de.

Siz beni hiç göremezsiniz

Okursunuz ama seçemezsiniz

Kendimi gizlerim bu şiirlerime

Gizlerim hecelerin nirengisine.', 'Önümde kağıdım, elimde kalemimle Gecenizi paylaşıyorum sizinle Sizlerden bir zümre, şehirden bir cadde Sizleri yazıyorum dizelerimde. Kimini...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sizi-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ters geliyor anne...', 'ters-geliyor-anne-yusuf-ziya-leblebici-kue5b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık anneler gününde

çiçek vermeyeceğim sana.

Tıpkı rahmetli babama

yıllardır veremediğim gibi.

Mazlum çiçekleri dalından koparıp

canlarını çıkartmak ters geliyor bana...

Bir menekşeyi,

 bir karanfili düşün,

cıvıl cıvıl renkleri.

Nasıl kıyılır bıçak vurmak

yemyeşil bedeninden çalmak

bana ters geliyor anne...

Sana, canice koparttığım

bu çiçekleri versem,

bir kaç gün sonra

yaprakları dökülüp solacaklar.

Ama, bir buse koysam yanağına

gözlerinde açsa o çiçekler

sulasan onları kana kana.', 'Artık anneler gününde çiçek vermeyeceğim sana. Tıpkı rahmetli babama yıllardır veremediğim gibi. Mazlum çiçekleri dalından koparıp canlarını...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ters-geliyor-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü olur...', 'turku-olur-yusuf-ziya-leblebici-xwjlx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mermi seslerinden sağır olmuş kulaklarıma

Rüzgarın getirdiği bir türküydü bu.

Bir kısrak kımızının sarhoşluğunda

Sevdalı güllerin bülbülüydü bu.

Bağrımda bağdaş kuran bağlama

Şafaklarımda girerse halaya

Bu tellerin çağrısı

Kulaklarımda dizilir kolkola.

Gurbet elde sevdalıları yakan

Bir türküdür bu, destanlardan akan

Döşümde ağlayan, böğrümde sızlanan

Bir yavuklunun dilidir

kulaklarımda çınlayan...

Hasret,

Sıla ve sevda

girmişse kolkola

dağda bir eşkiya

yüreklerde derin yara.

Hele de, yollar yatmışsa uykuya

Kağnı sesi bile

türkü olur kulaklarıma...', 'Mermi seslerinden sağır olmuş kulaklarıma Rüzgarın getirdiği bir türküydü bu. Bir kısrak kımızının sarhoşluğunda Sevdalı güllerin bülbülüydü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/turku-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım', 'asigim-meral-yagcioglu-c3oaa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben aşığım arkadaş

Duy ve inan

Mutluluk rüzgarına kapılmış

Uçuyorum göklerde

Kanatlandım sanki

Yüreğim kıpır, kıpır

Raks ediyor martılarla 

Tarifsiz duygularım

Kırmızı gül goncası elinde

Uzandı girdi gönlüme

Beyaz karanfil koynumda

Düştüm amber kokulu deryaya

Sırılsıklam sarıldım aşka

Aşık olmak güzel

Hele birde paylaşmak

İşte o her şeyden güzel

Hazırım anlatmaya

Güzeli anlatmak zor

Harfler karışık hecelenmiyor

Kelimeler yok kayboldu 

Kırmızı uçurtmanın kanatlarında

Yükseliyorum şimdi arşa

Anlatamıyorum

Anlayabiliyorsan eğer

Gözlerimden bir nebze

Ben aşığım arkadaş

Elimden başkaca bir şey gelmez

İster anla ister anlama

Ben aşığım arkadaş.

		06/09/1996', 'Ben aşığım arkadaş Duy ve inan Mutluluk rüzgarına kapılmış Uçuyorum göklerde Kanatlandım sanki Yüreğim kıpır, kıpır Raks ediyor martılarla  ...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/asigim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim SE  SİZ lik', 'kim-se-si-z-lik-esref-guzel-so2r3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bir anka kuşuyum, 

Kaf dağının yok oluşuyum,

Bir kartalın süzülüşü... 

Şahinin keskin bakışıyım. 

Hep görünen yüzüyüm ayın, 

Suya değen ayaklarıyım bir kadının, 

Bir çocuğun sevinci... 

Tuvalindeki fırça darbeleriyim ressamın.', 'Ben bir anka kuşuyum,  Kaf dağının yok oluşuyum, Bir kartalın süzülüşü...  Şahinin keskin bakışıyım.  Hep görünen yüzüyüm ayın,  Suya değen ...', ARRAY['Türk Edebiyatı','Şiir','Eşref Güzel']::text[], 8.5, '{"poet":"Eşref Güzel","poet_slug":"esref-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kim-se-siz-lik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çam Ağacıyla Dertleşme', 'cam-agaciyla-dertlesme-nevzat-bayramoglu-hurdemi-li0es', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dertleştim bir ulu çam ağacıyla

Yaşlandım yetmişten gün aldım dedi

Toprağı gösterip güldü acıyla

Vefasız kullardan bunaldım dedi

Yıllarca kahrını çektim sizlerin

Gövdeme kazındı çile izlerim

Güneşten kaçsanız yine gizlerim

Sizleri koynuma ben aldım dedi

Dalımı kestiniz acı verdiniz

Hamaklar astınız sefa sürdünüz

İdam sehpaları gibi gördünüz

Sizin yüzünüzden can aldım dedi

Cahilin elinden her gün ölürken

Kamilin elinden fidan olurken

Toprağa faydamı hani bilirken

Seversiniz sandım yanıldım dedi

Bina yapmak için gezip baktınız

Durup düşünmeden kibrit çaktınız

Bir çok kardeşime kıyıp yaktınız

Bende onlar ile yanandım dedi

Sayenizde artık çıplak köklerim

Kozağım kalmamış gayrı teklerim

Kuruyan gövdemle sonum beklerim

Bazen de baltayla sınandım dedi 

Bak Hürdemi bir bir anlat bunları

Bu gidişle felakettir sonları

Yaratsınlar yeni çam ormanları

Yıllarca onlara canandım dedi

11 Nisan 2003 - Çubuk', 'Dertleştim bir ulu çam ağacıyla Yaşlandım yetmişten gün aldım dedi Toprağı gösterip güldü acıyla Vefasız kullardan bunaldım dedi Yıllarca ka...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cam-agaciyla-dertlesme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Dünyalar', 'karanlik-dunyalar-reyhan-sur-gqvxa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ter kokuyordu Yılmaz buram buram... Elleri çöl toprağı gibi yarıktı, ayakları çıplak... Eski giysileri içinde hala neşeliydi.. 

Haftasonu tatilini geçirmek için köyüne gidiyordu.Elinde erzak torbası, ıslık çala çala ilerliyordu arada bir ayağının üzerinde sekerek...Daha yenice inmişti köy minübüsünden... 

Yirmiiki yaşlarındaydı Yılmaz.Üniversite okuyordu bin bir emekle..Bu yıl son sınıfındaydı okuduğu okulun..Yaz tatillerinde ya tarla işlerinde çalışırdı başka köylerde, ya da okuduğu ilde çeşitli dükkanlarda iş bulurdu. 

Anasını kaybedeli beş yıl olmuştu, babasını ise bir yıl.Yedi yaşında bir erkek kardeşi ile Onaltı yaşında kız kardeşi vardı karanlık dünyasında mutlu.. Görmüyordu gözleri ama, o da seviyordu yaşamı ağabeysi gibi...Şimdi oturmuş küçük bir tepelikte Yılmaz''ı bekliyordu.İndi iki köy ayrımında İbrahim minibüsten. Koşarak tırmandı küçük tepelik yere köy girişindeki.. 

sarıldılar iki kardeş, öpüştüler doymamacasına.. Küçük İbrahim ablasını tepeliğe bırakıp az ilerdeki ağaçların arasından geçen dereye inmiş oynuyordu arkadaşlarıyla..Yılmaz koluna girdi kızkardeşi Nergis''in, tepelikten aşağıya inip eve doğru yürürken ünlediler '' az sonra geliriz biz de'' diye. 

Yılmaz erzak torbasından yiyecek ayırıp aldı yanına bir de iç çamaşırı aldı yedek..Özlemişti herşeyi. Evin odalarına bir göz gezdirdi, babasından kalma silahı da aldı yanına.Dere kenarına gittiler..Nergis''i oturtup ağaç altına suya atladı Yılmaz.Hem yorgunluğu, hem tozu toprağı gitsindi üstünden.. Çığlık çığlığa su savaşı da yaptılar İbrahim''in arkadaşlarıyla.. 

Dere üzerine tahta merdivenden yapılmış köprü görevi gören geçirtmeliğin üzerine çıkıp oturdu, güneşlendi biraz.. Sora da üzerini değiştirip hep birlikte azıklarını yediler... Dere kenarındaki elma ve kayısı ağaçlarından hırsızlık yaptılar, yediler... 

Güneş dağların ardında kaybolmaya yüz tutmuştu..Su bir başka akar olmuştu sanki..Suyu öpen ağaçlar, ağırlığıyla daha bir derinden tutunur olmuştu hüzünlenen suya... 

Beraber geçirdikleri üç gün çabuk geçti sevgi ve sevinçle..Yılmaz’ın kentte yapacağı işler vardı.Ağabeylerini uğurlayan iki kardeş yine yalnızdılar işte...Haftalar böylesine geçip gitti.. 

Sonbaharın hüznüyle birlikte eşsiz güzelliği de gelmişti. Doğa ayrı özellikler, ayrı güzelliklerle yeni günlere gebeydi. 

Yılmaz da işlerini bitirmiş biraz para tutmuş okul günlerini bekliyordu artık.. Bu son yılı da başarıyla bitirirse öğretmen olacaktı...Okul başlamadan son kez köyüne gidip kardeşlerine, yeni aldığı elbiselerini göstermek, onlarla birlikte geleceğe ilişkin planlarını paylaşmak istedi... Öğretmenliğinde yanına alacaktı kardeşlerini..Köy girişinde göğe yükselen duman gördü, bir karışıklık, bağırışıklıklar vardı amansız. Köyde genç yoktu pek, ya kentte okumaya gitmeşler ya çalışmaya...Bir iki genç koşup karşıladı Yılmaz’ı, evleri yanıyordu.. 

İbrahim dere suyundan üşütmüş hasta yatağındaydı kan ter içinde baygın bir halde.. Nergis evde piknik tüpünün gaz kaçığı yaptığını farkettiğinde alev perdeleri sarmış, yangın çıkmıştı... Can havliyle tüpü bulup fırlatmıştı tüpü ama perdenin alevi evi sarmıştı... 

Yılmaz koştu atıldı eve doğru. Her yer dumana boğulmuş yutuyordu haykırışları...İbrahim ayık ama bir köşeye sıkışmış sesi bile çıkmıyordu korkudan. Atıldı ağabeyinin kucağına.. Yılmaz çıkarıp kardeşini, attı bakan yaşlıların kucağına... Köydeki birkaç genç bir yandan su atıyor dumanlara bir yandan bağırışıyorlar, sese gelmesi için Nergis’in...Eve doğru hamle yaptı yaralı bir kaplan gibi, kardeşini çekip almalıydı... Boşunaydı gayreti, insanların yangına karşı verdiği savaşım gibi...İnsanları zor seçiyordu artık.. Beyni uğulduyor, başı dönüyor, sallanıyordu yerinde sadece...Ev çökmeye başladı ve Yılmaz da kendini kaybetti, kapıya yaklaştığında yığıldı kaldı...Rüzgar ıslıklar çalıyordu artık karırken hava.... 

Genç adam bütün gece baygın kaldı, köylünün yoğun çabalarına rağmen..Gün geceyi keserken yola çıktılar, Kente götürüp bir hastaneye yatırdılar iki kardeşi..Yanıkları vardı ikisinin de..Yılmaz uzun süre şoktan çıkamamış, uzun süreli tedavisi başlamıştı.. 

Hastane çıkışında, köylülerin yanında kalan İbrahim’le birlikte, birkaç köylünün yardımıyla, doğup büyüdüğü ve kendinde acı anılar bırakan Doğu ilinin köyünden yola çıktı Orta Anadolu’nun bir iline yerleşmek için.Köylülerden birinin yakını vardı orada... 

Yol boyunca bir hemşehrisi ile de tanışarak ahbap oldu. Bir ağabey kardeş gibiydiler artık..Aynı kente gidiyorlardı ve öğretmendi adam...Adı Şehmuz... 

Yılmaz’ın ağabeyi! Kendi evinin yakınında bir ev kiraladı iki kardeşe...O yıl okulu bitemedi Yılmaz’ın.Şehmuz Hoca’nın yardımıyla bir okulda üç ay kadar vekil öğretmenlik yaptı..Bu arada yatay geçişle okuduğu okulunu değiştirdi.. Ertesi yıl okul bitmiş artık öğretmen olmuştu..Geçirdiği acı günleri anımsamak büyük üzünç kaynağıydı... 

Yaz tatilinde kardeşini de alarak memleketine gitti.. Anasının, babasının, kızkardeşinin bulunduğu mezarlığı ve köylüleri ziyaret etti...Gömütlerin bağrına çiçekler dikti...Ayrılacağında bir de yazı bıraktı kardeşinin gömütü üzerine... isyan doluydu yüreği... 

Başını gökyüzüne kaldırarak ağlamaya başladı sessizce..Bulutlar da boşalıverdi... Aldı ıslanan kağıdı tekrar okudu... 

zaman akıyordu durmaksızın 

geceler hayal dünyamdı 

korkuyordum aslında karanlıktan 

kabuslar peşimi bırakmıyordu 

sevginin her türü yasaktı sanki 

sevdiklerim uçmuştu elimden 

kuş misali, tek tek 

terkedilecek biri miydim ki 

terkettiler beni 

yaşam mı beni istemiyordu artık 

yoksa ben mi yaşamı bilmem 

işte, biri daha kaçtı benden 

ruzgarın savurduğu yapraklar örneği 

savruldum, savruldular uzaklara 

çok uzaklara... 

ve, gömütün başında öylece kaldı bir süre, kardeşiyle birlikte...Sonra, hepsinin başucuna birer mum bıraktı yakarak..Yaz yağmuru da dinmişti zaten... 

Kalktı ayağa, ayrılmak için... Başı önde... gözleri yaşlı......', 'Ter kokuyordu Yılmaz buram buram... Elleri çöl toprağı gibi yarıktı, ayakları çıplak... Eski giysileri içinde hala neşeliydi..  Haftasonu ta...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/karanlik-dunyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana -1', 'sana-1-sirma-mersin-t6yfm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baharın tam ortasında! 

Gözlerini; denizden mi? gökyüzünden mi? çalmış,

Bilinmez ama...

Yüreğini sevgi ile doldurmuş,biri...

Bugün yeniden doğmuş! 

Müebbet yalnızlığını yaşarken; 

Hayatına eklemiş, bir sürü anıyı...

Dünyaya bi kez geliyoruz deyip; 

Mutlu kal''la imzasını atmış, zamana...

Bir dost merhabası ile,

Herkesin yüreğine yerleşmiş...

15.04.04', 'Baharın tam ortasında!  Gözlerini; denizden mi? gökyüzünden mi? çalmış, Bilinmez ama... Yüreğini sevgi ile doldurmuş,biri... Bugün yeniden d...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senmisin', 'senmisin-alena-akin-s6d3m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'senmisin karşımda duran? 

gözlerime bakan senmisin? 

neden böyle hüzünlü gülümsüyorsun? 

sende benim gibimisin? 

senmisin? 

senmisin yanlızlığım? 

sevdiklerimi hatırlatan

senmisin yanlızlığım? 

benimle yanlızlık oyunları oynayan?', 'senmisin karşımda duran?  gözlerime bakan senmisin?  neden böyle hüzünlü gülümsüyorsun?  sende benim gibimisin?  senmisin?  senmisin yanlızl...', ARRAY['Türk Edebiyatı','Şiir','Alena Akın']::text[], 8.5, '{"poet":"Alena Akın","poet_slug":"alena-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/senmisin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* KADEHiMDESiN...', 'kadehimdesin-baki-son-23xpt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni buldum,

Seni  kaybettim...

Bu gece,

Kadehimde.

Işığı yakamadı ellerim.

Yalnızlık gibi çöken,

Karanlığı seyrettim.

Aynalar,

Göstermedi

Gözlerimdeki yaşı...! 

Ve hiç kimse görmedi

Sensizliğimi...! 

Gölgelerin

Yere düşüşü kadar sessiz...

İçime döktüm dertlerimi.

Uzak...! 

Ve karanlık yıldızlara baktım,

Penceremden.

Soğuk bir sonbahar,

Fısıldadı rüzgar.

Buruk bir yalnızlık

Ürperdi ağaçlarda.

Uzak...! 

Çok uzaklarda

Bir yıldız kaydı...! 

Uzattım ellerimi...

Seni buldum

Ve 

Seni kaybettim

Kadehimde...!', 'Seni buldum, Seni  kaybettim... Bu gece, Kadehimde. Işığı yakamadı ellerim. Yalnızlık gibi çöken, Karanlığı seyrettim. Aynalar, Göstermedi G...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kadehimdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-alena-akin-pzder', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gittin..

kaç şiire böyle başladım bilmiyorum

gittin..

altı harf bir kelime

gittin..

bunca hüzün nasıl sığdırılır bir kelimeye 

gittin

tarifi ne bilmiyorum

gittin

işte böyle..

gittin...', 'gittin.. kaç şiire böyle başladım bilmiyorum gittin.. altı harf bir kelime gittin.. bunca hüzün nasıl sığdırılır bir kelimeye  gittin tarifi...', ARRAY['Türk Edebiyatı','Şiir','Alena Akın']::text[], 8.5, '{"poet":"Alena Akın","poet_slug":"alena-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gittin-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evim', 'evim-alena-akin-qtkds', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'iyiki bir evim var

babam sağolsun

iyiki verdi bu evi bana

baba, ben sana anlatamazdım

bu evin bildiklerini..', 'iyiki bir evim var babam sağolsun iyiki verdi bu evi bana baba, ben sana anlatamazdım bu evin bildiklerini.....', ARRAY['Türk Edebiyatı','Şiir','Alena Akın']::text[], 8.5, '{"poet":"Alena Akın","poet_slug":"alena-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/evim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-alena-akin-wz6ci', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yalnızım

yalnızım

yalnızım

yalnızım

yalnızım

yalnızım....

böyle şiir olurmu? 

başka türlü anlatılırmı?', 'yalnızım yalnızım yalnızım yalnızım yalnızım yalnızım.... böyle şiir olurmu?  başka türlü anlatılırmı?...', ARRAY['Türk Edebiyatı','Şiir','Alena Akın']::text[], 8.5, '{"poet":"Alena Akın","poet_slug":"alena-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizim-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-sirma-mersin-llkly', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bekleyişin sessizliği,

Sessiz çığlıklarımı haykırdıkca...

Gece! 

Karanlığın içine düşen, yalnızlığımdan kurtulamaz iken...

Nefesimin altında; 

Gizlenmiş cümlelerle, özlemini sessizliğe  bırakan...

Yüreğimin suskunluğu derinleşir! 

Karanlık dokunuşlarla; yokluklara ağladığımda, 

Dilimin ucundaki sessiz kelimeleri yazmak için...

Küllerimden doğmak istedim! 

Olmadı! Olmuyor...

Sessizliği, sensizliği  yüreğim yaşarken; kalem yazmıyor...

04.04.04', 'Bekleyişin sessizliği, Sessiz çığlıklarımı haykırdıkca... Gece!  Karanlığın içine düşen, yalnızlığımdan kurtulamaz iken... Nefesimin altında...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sessizlik-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vitamin Haplarımı Çiçeklerime Verdim / deneme', 'vitamin-haplarimi-ciceklerime-verdim-deneme-k-muran-esen-zoc52', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soluk benizli biriyim ben. Sabahleyin yüzümü yıkarken aynaya baktığımda, görüntümü hiç beğenmem: Solgun, sapsarı bir yüz... Sanki limon.... Üstüne üstlük kısa, seyrek kirpikler. Biri burda, diğeri ta bilmem nerde. Hani tarlaya tohum ekersiniz; bir müddet sonra seyrek seyrek çimlenir ya, işte onun gibi...

Kendimi çok sağlıklı hissetmemle beraber; soluk benzimden rahatsız olurum. Zaman zaman ufak tefek rahatsızlıklarımdan dolayı doktora gittiğimde, sorarım doktorlara bunun nedenini. Onlar da hemen tırnaklarıma, göz kapaklarımın altına bakarlar. Aradıklarını bulmuş olmalılar ki; sözlerimi hiç ciddiye almadılar, iki ay öncesine kadar. Kan sayımı yaptırmamı istemediler. Ben de bu soluk benizle yaşamımı sürdürüyorum.

Son gittiğim doktor, kan sayımı istedi. Yapılan tahlil sonunda, kanımın bir değer düşük olduğu ortaya çıktı. Doktor vitamin hapı verdi bana. ”Bunları kullanın, bir ay sonra yeniden bakalım kanınıza,” dedi.

Doktorun verdiği hapları kullandım. Hem de hiç aksatmadan. Soluk benzimin düzeleceğini bekledim boşuna. Sanki bir ayda elma yanaklı biri olacakmışım gibi.....Bir ay sonra yapılan kan sayımında, kanım bir değer daha düşük çıktı. Hap kullandığım halde, kanım biraz daha eksilmişti. Yeniden vitamin hapları verildi. 

Daha önce kullandıklarım bir işe yaramadı diye düşünerek, kullanmadım en son verilen hapları... ”Olur mu canım! ” falan demeyin. Kullanmadım işte......Unuttum gittim bir ara, soluk benzimi ve bundan duyduğum rahatsızlığı.

Bu arada, çiçekleri çok sevdiğimi söylemeliyim. Evimizin pencere önleri, bahçemiz rengârenk çiçeklerle dolu. Onlara gözüm gibi bakarım. Pireciklerle mücadele ederim. Zamanında sularım falan. Hatta çiçek vitamini bile veririm. Onlar da bir şımarırlar, görmelisiniz. Kol, bacak atarlar uzun uzun. Saksılarına sığamaz olurlar.

Geçenlerde çiçeklerimin, eski sağlıklı görüntülerini kaybettiklerini farkettim. Vitaminleri de kalmamıştı. Küçük kasabamızda çiçek vitamini yok. Zaten olsaydı, “Kel başa şimşir tarak” olurdu. Ben de kendi vitamin haplarımı verdim çiçeklerime. Bari bir işe yarasınlar diye.

Birkaç gün içinde aydınladı, canlandı yüzleri çiçeklerimin. Dirileştiler, sağlıklı bir görünüm kazandılar. Her birinin her dalında, çok sayıda çiçekler açtı.Vitamin haplarım işe yaramıştı kısacası.

Peki ya benim eksik kan durumu, soluk beniz falan ne mi oldu? Valla ben yine soluk benizle dolaşıyorum. Aynadaki görüntümden rahatsız olduğumda da, makyaj malzemeleri koşuyor imdadıma. Allıklar sağolsun! Hiç bir sağlık problemim olmadığı için(Düşük kanı saymazsanız.) , vitamin haplarımı çiçeklerime vermeye devam edeceğim. Çok iyi geliyor çünkü.

Sizin de çiçekleriniz varsa, tavsiye ederim.Vitamin haplarınızı çiçeklerinize verebilirsiniz. Bir deneyin.(Aman doktorlar duymasın.) 

Uyarı: Bu yazıyı okuyup da, vitamin haplarını çiçeklerine verenlerin yaşayacağı olası sağlık sorunlarından ben sorumlu değilim. Ne demiş atalarımız: “El ağzına bakan, sel ağzına yuva yapar. ” Ona göre. ”Demedi” demeyin.', 'Soluk benizli biriyim ben. Sabahleyin yüzümü yıkarken aynaya baktığımda, görüntümü hiç beğenmem: Solgun, sapsarı bir yüz... Sanki limon.... ...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vitamin-haplarimi-ciceklerime-verdim-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-erdal-asik-6n273', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşündüğüm bu kaçıncı gece

Geceler bir işkence sanki

Üzerime kabus gibi çöktü sensizliğin

Sahilde ışıklar yok artık

Yakamozlar kaybolmuş

Senin hayalini görmüyorum 

Denizin üstünde

Dalgalar bile uykuya dalmış

Konuşmuyorlar artık benimle

O tatlı esintiler kaybolmuş

Baykuş sesleri var sanki beynimin içinde

Kötü günlerin habercisi gibi

Sensizliğini haykırıyordu bana....', 'Seni düşündüğüm bu kaçıncı gece Geceler bir işkence sanki Üzerime kabus gibi çöktü sensizliğin Sahilde ışıklar yok artık Yakamozlar kaybolmu...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoksun-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tarafta konaklar', 'bir-tarafta-konaklar-sedat-tuvar-doijv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğim alın terinden yana 

Aklıma da hep sokmuşlar konakları

Bir yanda alınteri, bir yanda konaklar

Alınteri yakın, alınteri sıcak,... 

Ya konaklar?  Ya konaklar? 

Konaklar uzak, soğuk, sevimsiz.. 

Dedimya birkez, yine derim

Alınterinden yana olmuşum

Öğretti yaşam her ikisini de bana

Bir adım ötede alınteri, 

Bir adım ötede de konaklar..

Seçtiğim benim oluverir 

Bir tarafta konaklar, bir tarafta kavaklar. 

Yüreğim alınterinden yana, 

Yar seçmiş konakları 

İki arda bir derede 

Mutlu edebilirmiyim her ikiyanı..? 

Hem alınterini, hem de konakları..

Diyemiyorum ki yar’e de 

Ben neyleyim konakları

Ben baştan seçmişim kavakları

Yar seyreyler konakları 

Ben sayarım kavakları..

Bir ter bir kavak, her ter bir kavak...

Bin ter, bin kavak

Bin kavak yapmıyor bir konak.', 'Yüreğim alın terinden yana  Aklıma da hep sokmuşlar konakları Bir yanda alınteri, bir yanda konaklar Alınteri yakın, alınteri sıcak,...  Ya ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Tüvar']::text[], 8.5, '{"poet":"Sedat Tüvar","poet_slug":"sedat-tuvar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-tarafta-konaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye rağmen', 'herseye-ragmen-erdal-asik-q8go5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sizinde hayalleriniz var mı

Ümitsizlikleriniz hiç olmadı mı

Çaresiz günleriniz yok mu

Yaşarken ölümü hissettiniz mi

Ne kadar kendinizi seviyorsunuz

Sevginizi çevrenize gösteriyor musunuz

Yaşama ne kadar bağlanıyorsunuz

Gülerek neşeyle bakabiliyor musunuz

Yeter artık demeden

Bıkmadan tükenmeden

Bütün zorluklara rağmen

Her şeye rağmen şükredebiliyor musunuz', 'Sizinde hayalleriniz var mı Ümitsizlikleriniz hiç olmadı mı Çaresiz günleriniz yok mu Yaşarken ölümü hissettiniz mi Ne kadar kendinizi seviy...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/herseye-ragmen-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Ömür Hırsızı', 'omur-hirsizi-metin-eser-hcize', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hey gidi uyku hey, ne menem şeysin,

Ömrümün üçte birinin hırsızı sensin.', 'Hey gidi uyku hey, ne menem şeysin, Ömrümün üçte birinin hırsızı sensin....', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/omur-hirsizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Hasret', 'sensizlige-hasret-seref-yildirim-1gr2o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Poyraz rüzgarları şiddetinde ilkbahar yağmurları

Yüreğimin bilinmezliklerine akıyor 

Yılların ağırlığını kaldıramıyor zavallı yüreğim

Doğrulmaya çalışsam da kayıyorum hasretinle

Kaybetme korkusu sarıyor bedenimi

Kahroluyorum sessizliğin boşluğunda

Çaresiz boyun eğiyorum kırık bir dal gibi 

Aynalara bakıp görünmez oluyorum

Soruyorum kendime nereden geldi bu yılgınlık diye

Gerçeklerle yüz yüze gelmek istememem neden /

Vücuduma ölü toprağı serpilmiş 

İçkim ve sigaram  bataklıktan çıkarmaya yetmiyor kendimi 

Sen benden habersiz,duygularım karanlık kuyularda kaybolup gidiyor 

Göz yaşlarım kanlı damlalarını yüreğime akıtıyor

Yırtılıyor boğazım, nefesim uçuşuyor gökyüzüne

Sıcak düşlerimle  kar tanesi gibi eriyorum

Kor alevlerde kül olup okyanus derinliklerinde

Kaybolup gidiyorum sonsuza dek...

Sensizliğin hasretiyle....', 'Poyraz rüzgarları şiddetinde ilkbahar yağmurları Yüreğimin bilinmezliklerine akıyor  Yılların ağırlığını kaldıramıyor zavallı yüreğim Doğrul...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yıldırım']::text[], 8.5, '{"poet":"Şeref Yıldırım","poet_slug":"seref-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensizlige-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalaka', 'yalaka-ozan-ozel-q9wke', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yala deyince yalarsın

Ne olduğuna bakmaksızın

Her bir şeye dalarsın

Senin adın yalaka

Sağımda sen, solumda sen

Kampüste sen, yolda sen

Hi. yorulmasın çenen

Senin adın yalaka

Kim inanır sana bilmem? 

Çoktur bilirim seni seven

Bakırı altın eden

Senin adın yalaka

Biraz yüzün kızarsın

Alnından aksın terler

Ne yerler, ne içerler

Senin adın yalaka', 'Yala deyince yalarsın Ne olduğuna bakmaksızın Her bir şeye dalarsın Senin adın yalaka Sağımda sen, solumda sen Kampüste sen, yolda sen Hi. y...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalaka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiir', 'bu-siir-bekir-mutlu-gokcesu-vw22m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Son ışıkları tükenmekteydi günün

Akşam çoktan inmişti dağların ardına

Seni düşününce gecenin koynunda

Avuçlayıp güneşin son demlerini

Koşmak geliyordu içimden yanına

Nişan aldım gözlerimin menzilinde

Dağlar, birer zor siluetti uzaklarda

Dalga, dalga aşıp dorukları akıyordu

Yaklaşıyordu gece şehre emin adımlarla

Saracaktı beni de, az sonra teslim alacaktı

Yoktun işte, gece yine sensiz yaşanacaktı...

Sensiz dedim de

Simsiyah delişmen bir atın terkisinde

Koptu, koştu zaman inciden parıltılarıyla

Sensizliğe dokuz doğurduğum saatlerde

İki dağın arasından bir şiir doğdu senden

Güneş toplamış bir bulutun süzülüşünde

Heyecanımdan bakamadım bir süre

Sonra aldım ellerime, öyle güzeldi ki

Gözleri sen, dudakları sen, tıpatıp sendi

Bastım bağrıma, uyuttum dizlerimde

Seni yaşadım dizelerinde ve düşlerimde

Şiirden film oldum seninle başrollerde

Sensizlik dedim de bu sensizlikse...

Sonra aydınlandı sahne

Düş yorgunu bir gecenin

Merdivenlerinden inerken gülücüklerle

Ve sen gitgide çoğalırken içimde

İşte bu şiirin kalp atışları sesinde

Adamakıllı duyumsadım

Sana can atışımı yüreğimde...', 'Son ışıkları tükenmekteydi günün Akşam çoktan inmişti dağların ardına Seni düşününce gecenin koynunda Avuçlayıp güneşin son demlerini Koşmak...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bu-siir-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alçak', 'alcak-gokhan-karaduman-1soae', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Mutluluk rüzgarı savuramadan 

Ayrılık ateşi dağladı kalbimi 

Dudaklarına daha varamadan 

Gözyaşlarınla boğdun yüreğimi'' 

Ne vardı karşıma onunla çıkacak 

Ne vardı yatağıma onunla yatacak 

Şimdi yastığımda o mu uyuyacak 

Erosmu yoksa sen misin bu kadar ALÇAK 

İstediğin herşey ellerindeydi 

Yüreğim her an yüreğindeydi 

Suratım sayende yerlere değdi 

Hayatmı yoksa senmisin bu kadar ALÇAK 

Şimdi beden haritanı o çözecek 

Fiziğini kimyanı o formulleyecek 

Umarım gözlerin sevişirken sönecek 

Zamanmı yoksa senmisin ALÇAK 

Madem niyetin düşüp kalkmaktı 

Bende bilirdim yapacağımı 

Duymayacaksın bir daha ağladığımı 

Karar çıktı Sensin ALÇAKtan da ALÇAK 

'' Ne zaman sevdiğimi söylesem inanmıyorum derdin, Sen yine İnanma, Çünkü Değmezmişsin AŞKıma''', '''Mutluluk rüzgarı savuramadan  Ayrılık ateşi dağladı kalbimi  Dudaklarına daha varamadan  Gözyaşlarınla boğdun yüreğimi''  Ne vardı karşıma o...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/alcak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çürüdüm', 'curudum-ebru-kavak-hgqur', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben çürüdüm,ömrüm çürüdü,yürek çürüdü

Gönül daraldı ben daraldım

Öfkelendim hırslandım

Şafak ile ayıldım

Yürek ferman dinlemedi

Hep savruldum,vuruldum', 'Ben çürüdüm,ömrüm çürüdü,yürek çürüdü Gönül daraldı ben daraldım Öfkelendim hırslandım Şafak ile ayıldım Yürek ferman dinlemedi Hep savruldu...', ARRAY['Türk Edebiyatı','Şiir','Ebru Kavak']::text[], 8.5, '{"poet":"Ebru Kavak","poet_slug":"ebru-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/curudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Seviyorsun', 'beni-seviyorsun-gokhan-karaduman-k5ub6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başını koyamıyorsan rahatça yastığa 

Nereye baksan, 

Beni görüyorsan karşında. 

Yarım uykularında ben varsam. 

Elimi tutmak için çıldırıyorsan 

Ellerinde kitaplar 

Koşarca telefona koşuyorsan 

Sevişmeyi değil, 

Sevmeyi özlüyorsan. 

Hep ben varsam usunda 

Beni seviyorsun.!', 'Başını koyamıyorsan rahatça yastığa  Nereye baksan,  Beni görüyorsan karşında.  Yarım uykularında ben varsam.  Elimi tutmak için çıldırıyors...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beni-seviyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liselim', 'liselim-gokhan-karaduman-ojz17', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', ''' Ben aşkla yolumu çoktan ayırdım 

Yalnızlığı seçtim,buna alıştım. 

Gönül defterimi artık kapattım 

Açmayı deneme, Pişman olursun'' 

- Can Afacan- 

Bırak 

Tutma ellerimi Liselim 

Bırak 

Bakma gözlerime 

Sakın 

Söyleme sevdiğini Liselim 

Sakın 

Açma bana yüreğini 

Yazık olur Liselim 

Yakarsın gençliğini 

Yazık olur 

Üzersin Yüreğini 

Ben 

Acılara bürünmüşüm Liselim 

Ben 

Aşka çoktan küsmüşüm. 

Sen 

Bahar dalı gibisin Liselim 

Sen 

Üzülmeye gelmezsin. 

Daha 

Çok seveceksin 

Ve kimleri sevecek 

Kimlerce sevileceksin. 

Mutluluklar Liselim 

Bir daha görmeyeceksin beni 

Bir daha duymayacaksın sesimi. 

Güle güle Liselim 

Güle güle.. 

Güle güle. 

Gökhan Karaduman 

'' Sevgili sanatçı ağabeyim Can AFacan''a sevgilerimle'' 

www.gokhankaraduman.cjb.net', ''' Ben aşkla yolumu çoktan ayırdım  Yalnızlığı seçtim,buna alıştım.  Gönül defterimi artık kapattım  Açmayı deneme, Pişman olursun''  - Can Af...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/liselim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-gokhan-karaduman-keusw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün kalırsan 

anılarla başbaşa 

yalnız bir köşede 

Saçında aklarla. 

Hülyalara daldığında 

Beni, beni hatırla. 

'' Bir özele''', 'Bir gün kalırsan  anılarla başbaşa  yalnız bir köşede  Saçında aklarla.  Hülyalara daldığında  Beni, beni hatırla.  '' Bir özele''...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/beni-hatirla-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-gokhan-karaduman-ksvv0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir vapur daha yanaştı iskeleye 

Sen yoksun 

Şehir Güzelliğinden yoksun. 

Yoksun, 

Saçlarının kokusu esmiyor 

Yoksun 

Güzelliğin içimi titretmiyor. 

Aylardır sen yoksun 

Tenim teninden yoksun.', 'Bir vapur daha yanaştı iskeleye  Sen yoksun  Şehir Güzelliğinden yoksun.  Yoksun,  Saçlarının kokusu esmiyor  Yoksun  Güzelliğin içimi titre...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yoksun-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkıcı Kız', 'sarkici-kiz-gokhan-karaduman-66q9e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen mi varsın yine 

Bu gece sahnede 

Benden sana yok artık 

Ne bir alkış, ne ıslık. 

Yasaksın artık düşlerime. 

Yırttım attım resimleri 

Sen kokan şarkıları 

Yoksun artık yüreğimde 

Yoksun artık,şarkıcı kız. 

Sen mi varsın yine 

Bu gece sahnede 

Benden sana yok artık 

Ne bir alkış, ne ıslık. 

Al mikrofonu eline 

Son kez o şarkıyı söyle 

Bu gece son gecen 

Yüreğimin sahnesinde. 

İstersen pop star ol 

İstersen tek idol 

Artık bana yapamayacaksın rol. 

'' Kritik aşkımız yolun sonunda'' 

Buna da hay hay. 

Melekler de ölürmüş 

Alıştık buna 

Sende payına düşeni aldın 

Hadi yolun açık olsun 

Şarkıcı kız.', 'Sen mi varsın yine  Bu gece sahnede  Benden sana yok artık  Ne bir alkış, ne ıslık.  Yasaksın artık düşlerime.  Yırttım attım resimleri  Sen...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sarkici-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyankar Şiir', 'i-syankar-siir-gokhan-karaduman-9mkak', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşuna isyankar olmadım ben 

Boşuna İmparator olmadım acılara 

Dayanırım bunada 

Buna da çekerim eyvallah 

Basitlik sende nasılsa. 

'' Bir Özele''', 'Boşuna isyankar olmadım ben  Boşuna İmparator olmadım acılara  Dayanırım bunada  Buna da çekerim eyvallah  Basitlik sende nasılsa.  '' Bir Öz...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/isyankar-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanka', 'kanka-gokhan-karaduman-l466c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kadarmı yüreksizsin be Kanka 

Bir kerecik sırt çevirip anana 

Seviyorum diyemedin o kıza. 

Gördün mü bak sonunda kaçtı 

Şu kör olası Bakkalın çırağına.', 'Bu kadarmı yüreksizsin be Kanka  Bir kerecik sırt çevirip anana  Seviyorum diyemedin o kıza.  Gördün mü bak sonunda kaçtı  Şu kör olası Bakk...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kanka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Ama', 'neden-ama-ebru-kavak-m8pr3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden Ama

Hep sordum kendime

Neden ama diye

Bunu sorması gereken ben miydim acaba? 

Yoksa başkalarımıydı.

Ama nedense 

Ben hep kendime sordum

Hırpaladım kendimi

Düşündüm.....uğraştım

Ama nedense bir sonuca varamadım

Çünkü; 

Suç bende değildi

Zaten bir suçluda aramıyorduk ki

Sadece ve sadece doğruyu

Peki doğruyu bulmak bu kadar zormuydu? 

Neden herşey bu kadar tutarsız olmalımıydı acaba? 

Bir insan ne kadar dayanabilirdi? 

Veya dayanmalımıydı? 

Neden ama neden? 

Bütün bu olanlar.

Bu öfke bu hırs....

15/04/2004', 'Neden Ama Hep sordum kendime Neden ama diye Bunu sorması gereken ben miydim acaba?  Yoksa başkalarımıydı. Ama nedense  Ben hep kendime sordu...', ARRAY['Türk Edebiyatı','Şiir','Ebru Kavak']::text[], 8.5, '{"poet":"Ebru Kavak","poet_slug":"ebru-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neden-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İvme ve Haz', 'i-vme-ve-haz-aynur-uluc-wx7at', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerim sancır seni düşlerken

Dipsiz yolculuğun neresindeyim

Erguvan likörü tadında sosa bulandım

Direngen ürperti sardı tenimi

İçimde isyanlar alesta beklerken

Uzun uzadıya aşka dayandım

Dişinin erkeği olmuştum

Erkeğimin dişisi

Kaç içiçe resim gizliyor yaşam

Kaç sarmal çizimde boy verir insan

Anladım

Özlem biriktirdikçe 

Büyüyor içi

Öyleyse…

Seni beklemek güzel

Hazzı inceden işlemek

Güzel..

08-04-2004

08-02-2005', 'Ellerim sancır seni düşlerken Dipsiz yolculuğun neresindeyim Erguvan likörü tadında sosa bulandım Direngen ürperti sardı tenimi İçimde isyan...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ivme-ve-haz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çingen Kızı Sevda Şarkısı...', 'cingen-kizi-sevda-sarkisi-hurrem-yalcin-ik2jq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çingen kızı

Eteği can kırmızı

Ovanın yıldızı

Göbeği oynak

Gözleri işvek

Saçında gülü

Nazı edası

Maralımsı

Kaptırdı yüreği

Ovanın sarı oğlanına

Sarı oğlanın kara sevdası çingen kızında

Sarı oğlan yazdı

Dağa taşa sevdasını

Vurdu baba yadigarı kemanı yüreğine

Aldı yayı eline

Çaldı sevda şarkısı

Duydu çingen kızı

Sarı oğlanın sevda şarkısını

Taktı saçın gülünü

Savurdu eteğin püskülünü

Fırladı ovanın ortasına

Bahtı sarı oğlanın sevdalı yüreğinde

Gözleri gözlerinde

İkiside değildi kendinde

Sevda şarkıları yükseldi

İki ağız tek yürek 

Sımsıcacık güneşe.....

Bir anda gürledi gök yüzü

Ortalık kapkara

Bulut yağmur yükü

Güneş gök yüzü kaçkını

Toprak ölü toprağı

Çeri başının şimşekli bakışı

Nemli sesi sardı ovayı

Gözü çingen kızında

Çıldırmış sanki o anda

Kolay mı! çeri başı

Sayar mı karşı çıkışı

Varmı sevgiye sevgisi

Ya da sevdaya saygısı

Bilemedi çingen kızı

Yüreğinde ince sızı

Yıldızlar sanki göz yaşı

Umutsuzdu sevdası.....

Çeri başı insafsız

Sevdaya saygısız

Karakalbi infazda

Dayadı bıçağı çingen kızın boğazına

İnciyi mercanı dizdi alnına

Kattı tarlayı baba toprağına

Bağladı kısrakları ahırına

Yaktı kara kınayı avucuna

Hapsetti çingen kızı yatağına....

Sarı oğlan büründü yaslara

Vurdu yazgısız başı dağdan dağa

Dilindeki sevda şarkısı

Şimdilerde oldu yüreğinin kara sızısı

Baba yadigarı kemanı parçaladı

Sapladı yayı toprağa

Göğsünde fişek elinde tüfek

Oldu ovanın sarı delisi

Vurdu dağlara kendini

Ve

Çeri başı şimdilerde

Yeni bir içimsu peşinde

Ve

Çingen kızı mutsuz gözlerinde

sekizinciye hamile

Ve

Sarı oğlan hala sarı deli

Silaha dayalı sevda yazgılı yüreği....

Titrek parmağı iter soğuk tetiği....

O gün bu gündür

Dolanır ovanın rüzgarı 

Deli oğlan

Çigen kızı

Sevda Şarkısı...

.....

...

..

14.04.2004', 'Çingen kızı Eteği can kırmızı Ovanın yıldızı Göbeği oynak Gözleri işvek Saçında gülü Nazı edası Maralımsı Kaptırdı yüreği Ovanın sarı oğlanı...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/cingen-kizi-sevda-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satranç', 'satranc-hikmet-aslan-76vqh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şah hayali kurmak yasak,

Vezir olmak ise uzak,

At-fil olmak bana tuzak,

Piyon bile değilim ki…

Piyon tek adım düz gider,

O sadece çaprazı yer,

Bazen şahı yere serer,

Piyon bile değilim ki…

Ne şahlara şah çekmişim,

Ne baldıranlar içmişim,

Candan bile vazgeçmişim,

Piyon bile değilim ki…

Satrançtır hayat oyunu,

Mat olmak her şahın sonu,

İyi tanı bu piyonu,

Lan yoksa ben piyonmuyum…

14/04/2004  08:10

Güvenevler / Gaziantep', 'Şah hayali kurmak yasak, Vezir olmak ise uzak, At-fil olmak bana tuzak, Piyon bile değilim ki… Piyon tek adım düz gider, O sadece çaprazı ye...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/satranc-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Öldüren Dert', 'adam-olduren-dert-hikmet-aslan-a7no7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yasaklar içindeyim kalem tutuk elimde,

Kahkahayla gülüyor şeytanlar hayalimde,

Hale benzer bir hal yok mevcut olan halimde,

Gel de gör şu halimi, halim düşman güldürür.

Sigaramın dumanı resm çizerken yüzüme,

Acayip yaratıklar görünüyor gözüme,

Doruğum çırılçıplak kar düşüyor düzüme,

Gözlerimde bir deniz, gözlerimde göl durur.

Haydutlar dinlenirken kanunlar gölgesinde,

Cahiller hep baş olmuş bilgeler ülkesinde,

Mıntıka yapıyorum fikrimin bölgesinde,

Başımdaki fikirler çok başlarda kel durur.

Ruhumun hücreleri yapıyorken içtima,

Gerçekler görünmüyor ben de mi oldum âmâ,

Saadet dolu yaşam ben de isterdim ama,

Derdim fikir sancısı, adam bile öldürür.

26.06.1996

Iğdır', 'Yasaklar içindeyim kalem tutuk elimde, Kahkahayla gülüyor şeytanlar hayalimde, Hale benzer bir hal yok mevcut olan halimde, Gel de gör şu ha...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/adam-olduren-dert-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firari Sevgili', 'firari-sevgili-hikmet-aslan-xo6ue', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vücudum sürgüne biçilmiş kaftan,

Yüreğim sallanır darağacında,

Hüdhüd’ü çağırdım inmedi Kaf’tan.

Firari sevgili payıma düştü,

Esaret zinciri kalbe dolaştı,

Nasibim olmadı şu genel aftan.

Ağlamak talihim neyime gülmek,

Sanki kaderimdir kezlerce ölmek,

Boynuma gerdanlık sevgilim yaftan.

Yüreğimde ateş, gözlerimde yaş,

Kendimle savaşım bitmeyen savaş,

Kurtuluş kitabım inmedi raftan.

Yuvasız kuş gibi yuvadan uçtum,

Gurbeti gönlüme öz diyar seçtim,

Yalnızsan, yıl gibi geçmiyor haftan.

Kimler dost kim düşman seçemiyorum,

Ne serden ne yardan geçemiyorum,

Gel de sen ayıkla karşığı saftan.

06.04.2002

Gerence Körfezi / İzmir', 'Vücudum sürgüne biçilmiş kaftan, Yüreğim sallanır darağacında, Hüdhüd’ü çağırdım inmedi Kaf’tan. Firari sevgili payıma düştü, Esaret zinciri...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/firari-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlana', 'mevlana-hikmet-aslan-p5uuq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkına mevlanayım,

Sana fır dönüyorum.

Güneşte pervaneyim,

Zuhalde yanıyorum.

Dilde Mevlana sözü,

Nolursan ol yine gel.

Bahtımın gülen yüzü,

Gel gönül hanemde kal.

Değil Mevlana gibi,

İki elim göktedir.

Deli divane gibi,

Yüreğim dilektedir.

Gel derdime çare bul,

Ger gönlüme kol-kanat.

Sen sultan ben sana kul,

İstersen ateşe at.

Mevlanaca aşığım,

“Geeel! ” demekten usanmam.

Pilavda dik kaşığım,

İstemekten utanmam.

27.11.2001

Konya', 'Aşkına mevlanayım, Sana fır dönüyorum. Güneşte pervaneyim, Zuhalde yanıyorum. Dilde Mevlana sözü, Nolursan ol yine gel. Bahtımın gülen yüzü,...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mevlana-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir Adamı', 'sehir-adami-taha-nur-apsn5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Heykel duruşlu, donuk bakışlı, yüzü sanki buz sıcağı.

Ne selâmı var, ne sabahı; işte karşınızda şehir adamı.

Kalabalıklar içinde bulunsa da, ruhu yalnızlık odağı.

Kimi zavallı, kimi belalı; işte karşınızda şehir adamı.

			****				*****

Apartman ona hapishane misali, balkon hava alma yeri.

Gürültü, keşmekeş, koşturmaca, onun değişmez kaderi.

Köşe başındaki yapay şelale, bir nebze azaltsa da kederi.

Nerde rahatı, nerde felahı; işte karşınızda şehir adamı.

			****				*****

Kapalı kapılar arkasında yaşar, törenle çıkar sokağa.

Beton binalar arasına sıkışmıştır, özlem duyar toprağa.

Parktaki çimene dayanamaz, aldırmaz hiçbir yasağa.

Hani huzuru, hani refahı; işte karşınızda şehir adamı.

			****				*****

Çocuklar, sabah-akşam internet kafede, sanal oyunda.

Gençleri sorarsan, havai, aklı-fikri cep telefonunda.

Yaşlılara gelince, gece-gündüz hep televizyon başında.

Neye gülmeli, neye ağlamalı; işte karşınızda şehir adamı.

			****				*****

Dar pencereden bakar, sanki dünyanın merkezindedir.

Bir evi, bir de arabası varsa, değme, keyfi yerindedir.

Komşusu aç mı, tok mu, bihaber, umurunda değildir.

Ne ahı duyar, ne vahı; işte karşınızda şehir adamı.

			****				*****

Şehir adamını altın suyuna batırsan da, aslı bakırdır.

Derinlik, ufuk, fikir ne gezer, herşeyiyle tamtakırdır. 

Sözü uzatmağa gerek yok, bu çağa tam yakışandır.

Ne kızmalı, ne şaşmalı; işte karşınızda şehir adamı.', 'Heykel duruşlu, donuk bakışlı, yüzü sanki buz sıcağı. Ne selâmı var, ne sabahı; işte karşınızda şehir adamı. Kalabalıklar içinde bulunsa da,...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sehir-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Dili', 'sairin-dili-hikmet-aslan-t6g9b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kılıç kında güzeldir,

Şairin ağzında dil

Kılıç tutan bir eldir

Kılıç kında güzeldir.

Cenk yerinde cengaver,

Şairin ağzında dil,

Gözü pek atik nefer

Cenk yerinde cengaver.

Bazen hayat fısıldar,

Şirin ağzında dil,

Bazen çok zor kımıldar,

Bazen hayat fısıldar.

En tehlikeli bölge,

Şirin ağzında dil,

Rahatlatan bir gölge,

En tehlikeli bölge.

Kıvrak, mahir rakkase,

Şirin ağzında dil,

O oynamaz herkese,

Kıvrak mahir rakkase.

İlham kaynağı gökten,

Şirin ağzında dil,

Girer damardan, kökten,

İlham kaynağı gökten.

İnsanlığa bir anne,

Şirin ağzında dil,

Kafiyeler bahane,

İnsanlığa bir anne.

13.12.2002

Bornova / İzmir', 'Kılıç kında güzeldir, Şairin ağzında dil Kılıç tutan bir eldir Kılıç kında güzeldir. Cenk yerinde cengaver, Şairin ağzında dil, Gözü pek ati...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sairin-dili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsun Gözlüm', 'efsun-gozlum-hikmet-aslan-wc86n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerine tutsak ettin,

Gözlerime yasak ettin,

Saçlarımı apak ettin,

Azat eyle efsun gözlüm.

Gözlerinle davet ettin,

Gözlerimi hep ret ettin,

Gözlerine hasret ettin,

İnsaf eyle efsun gözlüm.

Bakışında bin türlü renk,

Saçlar, gözler, kaşlar hep denk,

Gülüşünde tek bir ahenk,

Güldür beni efsun gözlüm.

Bakışınla yandı gönlüm,

Ellerinde gönül gülüm,

Ya gelirsin, ya da ölüm! 

Ecel sensin efsun gözlüm.

Sen küçücük bir bebeksin,

Yeni uçan kelebeksin,

Şebnemi bol bir çiçeksin,

Koklat bana efsun gözlüm.

30.01.2001

Nergiz / Karşıyaka', 'Gözlerine tutsak ettin, Gözlerime yasak ettin, Saçlarımı apak ettin, Azat eyle efsun gözlüm. Gözlerinle davet ettin, Gözlerimi hep ret ettin...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/efsun-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapıyorsun', 'ne-yapiyorsun-hikmet-aslan-uo859', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum da

Şu an ne yapıyorsun

Mutfaktaysan…

Ya patlıcan oturtuyorsun,

Ya imam bayıltıyorsun,

Ya da karın yarıyorsun.

Bu mevsimde

Patlıcanlar ucuz olur biliyorsun.

Düşünüyorum da

Şu anda ne yapıyorsun

Ayaktaysan…

Ya bana geliyorsun,

Ya bana gel diyorsun,

Ya da hep bekliyorsun.

Bu mevsimde 

Heyecanlar tatlı olur biliyorsun.

Düşünüyorum da

Şu an ne yapıyorsun

Yataktaysan…

Ya kanıma giriyorsun,

Ya günahıma giriyorsun,

Ya da koynuma giriyorsun.

Bu mevsimde

Can-cananlar hızlı olur biliyorsun.

23.09.2001

Gerence Körfezi / İzmir', 'Düşünüyorum da Şu an ne yapıyorsun Mutfaktaysan… Ya patlıcan oturtuyorsun, Ya imam bayıltıyorsun, Ya da karın yarıyorsun. Bu mevsimde Patlıc...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ne-yapiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Portren', 'portren-hikmet-aslan-l8jwi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzun kirpiklerin 

O kahve gözler,

Bir bilsen bu yürek 

Nasıl da seni özler,

Ne yazar, ayrı tenler.

Birleşmiş bizim özler,

Özlenmedi sen kadar,

Ne özge ne de özler.

O simsiyah saçların,

Ve o beyaz ten,

Gayrı adandı sana

Hem bu can hem de bu ten,

Cilve naza ne gerek

Gönlüme girdin zaten,

Aşık ettin sen beni

Emin ol buna. Kasten.

12.11.2001      Karşıyaka / İzmir', 'Uzun kirpiklerin  O kahve gözler, Bir bilsen bu yürek  Nasıl da seni özler, Ne yazar, ayrı tenler. Birleşmiş bizim özler, Özlenmedi sen kada...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/portren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran Bulutları', 'hicran-bulutlari-hikmet-aslan-sv2vc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Yine hicran bulutlarını taç edilmişsin başına...”

demiş kardeşim..........

Öyle ya... sen olsaydın benim yerimde

Gözlerine kara, kara  bulutlar çökmez miydi

Yanarken gönlümde alev, alev bir ateş

Ve gözlerinde şimşekler çakmaz mıydı

Olsaydın şayet benim yerimde

Ve durumumda ve ahvalimde

Hangi yağmurlar yağardı acaba 

Ve hangi nehirler ıslatırdı yanaklarımı 

O dertli başımı hangi taşa vururdum

Yaslayacak bir diz bulamayınca

Ve ellerini yumruk yumruk edip

Hangi taştan duvarlara vururdum

Fırtınalar eserken meltem yerine 

Acaba hangi kasırgaları özlerdin

Uyku görmemiş mahmur gözlerinle 

Doğacak diye hangi duyguları gözlerdim

Ve bir akşam üstü güneş batarken

Gönlümde kaç keder tohumu filizlenirken

Gözünde bebeğin tuttuğu kadar

Yüreğin tutuşup cızzz ettiği zaman 

Bir fotoğraf  kağıdını kaç kez öperdim

Kaç kez basardım bağrıma resmini

Bebeğim, bebeğim benim deyip

‘Yine hicran bulutlarını taç etmişsin başına...’ 

demiş kardeşim..

Efkar basınca dumanlı başına

Bilmem kaç çakmak çakardın..

Sonu gelmez kaç sigara yakardın 

Acaba o külleri başına saçar mıydın 

Beklediğin yönden bir nefha eser diye

Gece de kaç kez pencereleri açardın

Ve yalnız başına bir kuytu köşede

Kaç saat bürünür mateme kaleme sarılırdın

Bilmem kağıtlar yeter miydi sana 

Karalamak ve parçalamak için

Şiirler tek tesellin olmaz mıydı

Taş yağmaz mıydı gökten üzerine

Özlediklerin geldiğinde gözlerinin önüne

Ve kan inmez miydi bir perde gibi

Boşluğu seyreden kara gözlerine 

Bilmem o zaman sevinç gözyaşları mı  dökerdin

Yoksa bir hançer mi saplanırdı yüreğime

Bin ah çıkmaz mıydı bir tek kelimenle

Hasret kokan nefesinle ağzından

Ona buna çatar mıydın çatmaz mıydın

Olsaydın şayet benim yerimde..

Ve durumumda ve ahvalimde...

Bir gün 

“Yine hicran bulutlarını taç edinmişsin başına.....” 

ben diyeceğim sana...', '“Yine hicran bulutlarını taç edilmişsin başına...” demiş kardeşim.......... Öyle ya... sen olsaydın benim yerimde Gözlerine kara, kara  bulu...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/hicran-bulutlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maalesef Sana Vuruldum', 'maalesef-sana-vuruldum-hikmet-aslan-vlzvs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kütüklüklere  kırık bir sevda

Şarjörlere hasret mermisi doldurdum

Bana öyle kopmaz bir kanca taktınki

Her gece  alemin nöbetlerinde durdum

Sensizliğin nöbeti üç beşi geçti

Bazen olta attım bazen oturdum

Mevziden mevzi dışını gözetliyorken

Düşmanı değil seni gözleye durdum

Düşman ateş etse bile bana doğru

Ben ateş etmeden düşmana seni sordum

Sen diye tüfeği alırken elime

Nöbetler boyunca hep konuşurdum

Mevzi ilerisindeki karartıları

Hep sana, hep sana, hep sana yordum

Gelip gecen devriyeye her nöbet 

Parola değil senin adını sordum

O kadar  kıymet arz edersin ki benden 

Seni miğfer diye baş üstünde durdurdum

Neden gelmiyorsun ki mevzim karşıma 

Yeter artık, yeter sensizlikten kudurdum

Sen geleceksin diye karşılama için 

Saatler boyunca esas duruşta durdum

Hasret kokan nefesini duyabilmek için 

Çınlayan kulaklarımı hazır olda durdurdum

Hani nerde kaldı gelmez oldu selamın

Gelsin artık dudakları selamlarda durdurma

Belki duyarsın diye adi adımlardayken 

Ayaklarımı çatlatırcasına yerlere vurdum

Ne diyeyim bakışların kurşun misali

En sonunda,sana,sana maalesef sana vuruldum', 'Kütüklüklere  kırık bir sevda Şarjörlere hasret mermisi doldurdum Bana öyle kopmaz bir kanca taktınki Her gece  alemin nöbetlerinde durdum S...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/maalesef-sana-vuruldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıkmışım', 'acikmisim-hikmet-aslan-cqkz0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acıkmışım bebeğim bana sofra kur,

Hasret ekmeğinin yarısını ver,

Derdini, gamını koy bir tabağa,

Gözlerinden akanı bardağa doldur.

Yiyeyim doyayım,

İçeyim kanayım,

Sen üzülme bebeğim,

Ben kahrolayım.

19.07.1995 Topçu Meydanı / Şanlıurfa', 'Acıkmışım bebeğim bana sofra kur, Hasret ekmeğinin yarısını ver, Derdini, gamını koy bir tabağa, Gözlerinden akanı bardağa doldur. Yiyeyim d...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aslan']::text[], 8.5, '{"poet":"Hikmet Aslan","poet_slug":"hikmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/acikmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
