INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş Gibiyim', 'sarhos-gibiyim-huseyin-avni-erdemir-puzc5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni kollarıma aldığım zaman,

Ateşi savrulmuş sarhoş gibiyim.

Hasretine düşüp yandığım zaman,

Gülleri kavrulmuş sarhoş gibiyim.

Bir tatlı gülüşün kul etti beni,

Geçtiğin yollara çul etti beni.

Aşk mektuplarına pul etti beni; 

Hasretle yoğrulmuş sarhoş gibiyim.

Hüseyin Avni der, şaştım bu işe,

Gönlümde kalmadı kahkaha,neşe.

Dizilse melekler saf saf  peş peşe

İdama çağrılmış sarhoş gibiyim.', 'Seni kollarıma aldığım zaman, Ateşi savrulmuş sarhoş gibiyim. Hasretine düşüp yandığım zaman, Gülleri kavrulmuş sarhoş gibiyim. Bir tatlı gü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avni Erdemir']::text[], 8.5, '{"poet":"Hüseyin Avni Erdemir","poet_slug":"huseyin-avni-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarhos-gibiyim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamsarlık', 'karamsarlik-hikmet-aslan-xx4sl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En kötü halde bile karamsarlık bulunmaz

