INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Zaman Sonra', 'i-ki-zaman-sonra-nazife-abayli-qtkiq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki zaman sonra,

Oturup demirden bir kuşun kanatlarına,

Uçacağım.

Baş ucuna konacağım.

Ellerim ellerin olacak sonra..

Gözlerim gözlerin....

Dinle..! ! ! 

Duy sevgilim..! ! ! 

Nasıl da atıyor heyecandan yüreciğim...! ! !', 'İki zaman sonra, Oturup demirden bir kuşun kanatlarına, Uçacağım. Baş ucuna konacağım. Ellerim ellerin olacak sonra.. Gözlerim gözlerin.... ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iki-zaman-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yıl daha', 'bir-yil-daha-zafer-zengin-etnika-y7v5h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Helvanı yedik

Tadı tadındı

