INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarkaçlı Saat', 'sarkacli-saat-cumhur-turan-i6ndx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sarkaçlı saat

bir bomba gibi konmuş içimize

kilik kılak

kılak kilik

atmayı sürdüren o sarkaçlı saate

inat mı inat

bilinmezliklerle örülü o haritaya

pusulasız dalmak

bir yerinde gizli

o muhteşem zamanı bulmak

çıkışı ve inişi benzersiz olan

ne dersin', 'sarkaçlı saat bir bomba gibi konmuş içimize kilik kılak kılak kilik atmayı sürdüren o sarkaçlı saate inat mı inat bilinmezliklerle örülü o h...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarkacli-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bun', 'bun-nazim-ercan-kkbnh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bun

Düşleri öldürüpte çıktığım yol bu

Gezgin bir karga inkarda aslını

Dağınık saçlı uykularımda karabasanlar

Bir nefes bir sigara daha dumanı cehennemin

Nöbetçi düşmanlıklar var uykularıma

Bir gözbebeği görüyorum hafif buğulu

Gözkapaklarımın altında.

Bu cehennem sıcağında bile 

Üşüyorum.

Üzerimizde bir erbain

Delikdeşik düşler

Bir kalleşliği sorgular gibi.

Yalnız, 

Bir kalem bir kağıt elinde şeytanın.

Kırkbir dedi tanrı

Ondokuz’a çeyrek kala.

Kırılan iki çömlek

Şovalyeleri mitosun

Ve ben 

Zeus’u hatırlıyorum da

Gerçek bir şovalyenin elinde tanrı’dır demişti kılıç.

						Nazım ERCAN

						Yaz 1996', 'Bun Düşleri öldürüpte çıktığım yol bu Gezgin bir karga inkarda aslını Dağınık saçlı uykularımda karabasanlar Bir nefes bir sigara daha duman...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmi beşinci saat', 'yirmi-besinci-saat-nazim-ercan-1o9ip', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sakat bir kısrakla çıktığım yol bu.

Bir düş tarlasından biçtiğim hayaller.

Kendini korumaktan aciz

Bi korkuluk yüreğim.

Ve

Düş görmeyi unutmuş ben.

Yaramaz bir kelebek konuyor avucuma,

Titrek bir güzellik! 

Bir flüt sesi uzaklarda

Son bir nefes, son bir gayret daha parmaklarımda

Tanrıyı gördüğüm bir ses.

Gökyüzünde ben

Ve 

Saat kaç? Yok artık.

Şimdi yirmi beşinci saat

				

				Nazım ERCAN

				Kış 1993', 'Sakat bir kısrakla çıktığım yol bu. Bir düş tarlasından biçtiğim hayaller. Kendini korumaktan aciz Bi korkuluk yüreğim. Ve Düş görmeyi unutm...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yirmi-besinci-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldi 23 Nisan', 'geldi-23-nisan-ozan-ozel-ys6c0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bayram düşünün ki

Cıvıl cıvıl, neşeli

Tüm dünyadan çocuklar

Bir bayram düşünün ki

Bir ulusun dirilişi

Atatürk''ten armağan

Bir bayram düşünün ki

Yürekler coşkulu, başlar dik

Adımlar barışa, geleceğe

Bir bayram düşünün ki

Seksenbirinci yılında

Geldi 23 Nisan', 'Bir bayram düşünün ki Cıvıl cıvıl, neşeli Tüm dünyadan çocuklar Bir bayram düşünün ki Bir ulusun dirilişi Atatürk''ten armağan Bir bayram düş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geldi-23-nisan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acemi Aktörün Yaslı Gözleri...', 'acemi-aktorun-yasli-gozleri-hurrem-yalcin-sefyz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acemiydi aktör

Bu ilk sahnesi

Replikler ezberdi

Roller canda kenetli

Seyirci kurttu

Sahne kurtlar sofrası...

Acemi olansa sadece kendi...

Işıklar söndü! 

Sahnede aldı yeri

Perde hâlâ kapalı

Heyecandı acemi aktörün kamçısı

Titriyordu sesi eli ve ayağı

Utanç heyecan ve korku mayasıydı yüreğinin

Perde açıldı 

Işıklar yandı

Alkışlar nerde kaldı! 

Hayat bitti

Oyun başladı

Bir anda buldu kendini

Orta yerinde sahnenin

Az önce aklındaydı sözleri

Ve dahi hareketleri

Ah bir de hatırlayabilseydi! 

Halbuki onca prova

Nereye gitmişti.....

Dekorlara baktı

Hepsi yerli yerinde

O halde dedi

Acemi aktör

İş başa düştü

Oyna bu rolü

Sırala sözleri

İçinden geldiği gibi....

Sahnenin bir o yanı

Bir bu yanı

Evi gibiydi sanki....

Hareketler ve sözler özü hayatı....

İLK PERDE böylece kapandı

Alkışlar oradaydı....

Beğenilmişti rolü

Ve 

Replikleri...

Ardından İKİNCİ PERDE geldi

Acemi aktör bu işi öğrendi....

Bir bir sıraladı sözleri

Ve dahi hareketleri....

ÜÇÜNCÜ PERDE bitti....

Acemi aktör gitti

Yerine geldi

Cin gibi biri

Öğrenmişti bu işi

Ve oyunu başarıyla nihayetledi....

İkiyüz kişi dörtyüz göz 

Eleştiri...

İkiyüz kişi dörtyüz el 

Alabildiğince ayakta alkış....

Ve perde de kapanış....

Alkışlar artınca ayakta

Perde önünde aktör

Gözleri yaştan ışıl

Verdi selamı 

Sahneden indi geri geri! 

O anladı artık

Acemilik bitmişti...

Bu işi kotarmıştı...

Kulise vardığında

Bitkindi bedeni 

Ama

Mutlulukla

Çarpıyordu yüreği.....

...

...

Mutluluğu yüreğinde kaldı....

Acı bir haberi vardı...

Anacığını Tanrı yanına aldı....

Hüzün cübbesiyle çöktü omuzları...

Keder tüneliyle yaslandı ışıldayan gözleri...

....

...

18.04.2004', 'Acemiydi aktör Bu ilk sahnesi Replikler ezberdi Roller canda kenetli Seyirci kurttu Sahne kurtlar sofrası... Acemi olansa sadece kendi... Iş...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/acemi-aktorun-yasli-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suyun sessiz çığlığı', 'suyun-sessiz-cigligi-erol-sen-yd861', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çamlar içinde bir park düşünün

Ortasından bir dere akıyor 

Başında ve sonunda fıskiyeler

Ve temiz hava

Yavaş yavaş yol alan suya bakarken

Tahta köprünün üstünden

Bir yandan fıskiyenin dinlendiren sesi

Diğer yandan suyun çığlıkları

Yavaş ama yaşayan suyun

Sessiz umuda akan görüntüsü

Bazen engellerini aşarak

Bazende çağlayan gibi önünde durulmaz

Yaşam pınarları hep gözyaşı

Bize hayat veren bazen hüzün

Ben istemedim ki derken bu hayatı

Kaderine mahkum bazen duru bazen çılgın

Yokluğu bir dertken yaşam da

Varlığı farklı duygulara yollanan

Her yaşam gibi o da yaşamın parçasıyken

Acı tatlı her yönüyle

Canları yaşama döndürürken

Belki severek belki özleyerek

Sensizlikle yaşam sona erecekse

Sen beni de al yanına…..

18.04.2004', 'Çamlar içinde bir park düşünün Ortasından bir dere akıyor  Başında ve sonunda fıskiyeler Ve temiz hava Yavaş yavaş yol alan suya bakarken Ta...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/suyun-sessiz-cigligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bitti Taslak', 'ask-bitti-taslak-halil-manap-i2umb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzü usulca 

……….naz eden gelin gibi 

…………………..karanlığa gömülüyor

Ve çıplak tenime düşen 

………………….çiy damlaları 

………………………….içime kan olup 

……………………………………..akıyor 

Sen yoksun 

……….maceralarımın 

.................................sessiz 

.......................................kahramanı 

Aşk bitti 

Gürültülü şehirler 

....................beynimi kemirdi 

........................................sonsuzluğa 

..........................................akan bir yıldız gibi 

Sessiz dingin bir hayattır ölüm 

Güneşin 

...göz kamaştıran 

........................ışıltıları 

................................saçlarımı 

................................okşamayacak 

Ve havayı içirtmeyeceğim 

……………………. yaşarken ölmüş bedenime

Çaresi yok 

………aşk bitti 

…………..sen yoksun diye 

……………………….şiirler yazıyorum 

……………………………………. Kendime

bunu bil ki sevgili 

......................senin yerine 

...................................toprağı 

.......................................sereceğim 

................................................tenime 

19.04.2004 

Adana', 'Gökyüzü usulca  ……….naz eden gelin gibi  …………………..karanlığa gömülüyor Ve çıplak tenime düşen  ………………….çiy damlaları  ………………………….içime kan ol...', ARRAY['Türk Edebiyatı','Şiir','Halil Manap']::text[], 8.5, '{"poet":"Halil Manap","poet_slug":"halil-manap","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ask-bitti-taslak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Günlerdeyim', 'bu-gunlerdeyim-ozan-ozel-o0alj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'derin düşüncelerdeyim

yaşanmış geçmişim

yaşanası geleceğim

yanımda çocuğum

yanımda eşim

uzaklarda annem

ve kardeşlerim

sahibi olduğum

beynim ve yüreğim

bir savaşta gibi

her an tetikteyim

yıkan ve yıkılan

seven ve sevilen

gülen ve güldüren

ağlayan ve ağlatan

bu günlerdeyim...', 'derin düşüncelerdeyim yaşanmış geçmişim yaşanası geleceğim yanımda çocuğum yanımda eşim uzaklarda annem ve kardeşlerim sahibi olduğum beynim...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-gunlerdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk', 'ey-ask-halil-manap-o97bh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey aşk 

...........teninin 

........derinliklerindeki 

..............................etinde 

....................................yanarak

Güneş 

.......sıcaklığında

.................çığlıkla tenin

................................hazdan 

....................................giysi oluyor 

...................................................tenime

Gökyüzü utangaç gözleriyle seyrediyor 

.......................................................aşkımızın 

....................................................................ritmik 

......................................................................iniltisini

Kaşları siyah gibi incecik iki çizgi gibi

...........................................sessiz gözleriyle 

.................................................gözlerken bizi ay

Deniz suskun

Dalgalar durgun

kainat aşkımıza vurgun

Yıldızlar akışarak doluyor içimize

Ey aşk

......şimdi 

..........ikimizde 

...............kilitlendik 

...................birbirimize

...........

19.04.2004

Adana', 'Ey aşk  ...........teninin  ........derinliklerindeki  ..............................etinde  ....................................yanarak Gün...', ARRAY['Türk Edebiyatı','Şiir','Halil Manap']::text[], 8.5, '{"poet":"Halil Manap","poet_slug":"halil-manap","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ey-ask-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaya Kırlangıcının Ağıdı', 'kaya-kirlangicinin-agidi-halil-manap-sd334', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Malezya falezlerinde yaşarım

Kaya kırlangıcıdır adım

Hiç bir canlıda yoktur tadım

yirmi gramlık etim var

Yemek yaparlar kendilerine

Diş kovuklarını doldurmam bile

Sunarlar beni prenses gibi

Zenginlerin sofra zevkine

Doyulmazki benim etimle

Koku sızdırmaz örtüler altında

bir kaç bin dolar ödemişler

Kokumu bile sindirirler içine

19.04.2004

Adana', 'Malezya falezlerinde yaşarım Kaya kırlangıcıdır adım Hiç bir canlıda yoktur tadım yirmi gramlık etim var Yemek yaparlar kendilerine Diş kovu...', ARRAY['Türk Edebiyatı','Şiir','Halil Manap']::text[], 8.5, '{"poet":"Halil Manap","poet_slug":"halil-manap","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaya-kirlangicinin-agidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Nesil', 'yeni-bir-nesil-ozer-sutcu-g2j49', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zulme boyun eymeyen

Kötü insanları sevmeyen

Yetimin hakkını yemeyen

Yeni bir nesil geliyor

Hak için savaş açan

Çevresine iyi huylar saçan

Bir gül gibi yurdumda açan

Yeni bir nesil geliyor

O ki fatihin torunu

Hak için çizmiştir yolunu

Kötünün kırmak için kolunu

Yeni bir nesil geliyor

Gücünü almıştır halktan

Kim döndürebilir onu bu yoldan

Adalet gelecek dörbir yandan

Yeni bir nesil geliyor

Hak için can verecek

Zulme göğüs gerecek

Batılı değil hakkı sevecek 

Yeni bir nesil geliyor

Hakkı ve hukuku bilen

Adalet için can veren

Önce dürüstlük diyen

Yeni bir nesil geliyor

Zalimlere kafa tutacak

Onların kötü oyunlarını bozacak

Tarihe damgasını vuracak 

Yeni bir nesil geliyor', 'Zulme boyun eymeyen Kötü insanları sevmeyen Yetimin hakkını yemeyen Yeni bir nesil geliyor Hak için savaş açan Çevresine iyi huylar saçan Bi...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yeni-bir-nesil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekler Güzeli', 'cicekler-guzeli-eyup-erdem-garzek-syx9y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen Çiğdem''in çiçek olduğunu biliyorsun.

Hiç Çiğdem gördün mü? 

Saf beyazlığında ne kadar güzeldir.

Sen Mine''nin çiçek olduğunu biliyorsun.

Hiç Mine gördün mü? 

Şirin,küçük,tatlı maviliğinde koybolur gidersin.

Sen kendine hiç baktın mı aynada? 

Ve bütün çiçeklerden güzel olduğunu söyledim mi sana! ..

 İstanbul(10.05.1998)', 'Sen Çiğdem''in çiçek olduğunu biliyorsun. Hiç Çiğdem gördün mü?  Saf beyazlığında ne kadar güzeldir. Sen Mine''nin çiçek olduğunu biliyorsun. ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Erdem Garzek']::text[], 8.5, '{"poet":"Eyüp Erdem Garzek","poet_slug":"eyup-erdem-garzek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cicekler-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-ozer-sutcu-xhu42', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir duyurabilsem sesimi

Ağladığımı bir görsen sevgilim

Şahit olsan neler çektiğime

Gelip teselli verebilsen sevgilim', 'Bir duyurabilsem sesimi Ağladığımı bir görsen sevgilim Şahit olsan neler çektiğime Gelip teselli verebilsen sevgilim...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgilim-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştım Sevgilim', 'alistim-sevgilim-ozer-sutcu-53a8b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sensiz  yaşamaya

Bağrıma taşlar basmaya

Acılarla yatıp kalkmaya

Artık alıştım sevgilim

Göz yaşlarımı şarap gibi içmeye

Her şeyi sineye çekmeye

Her seferinde kadere küsmeye

Artık alıştım sevgilim

Boş hayallerle avunmaya

Başımı taşlara vurmaya

Seni sensizde yaşamaya

Artık alıştım sevgilim', 'Seni sensiz  yaşamaya Bağrıma taşlar basmaya Acılarla yatıp kalkmaya Artık alıştım sevgilim Göz yaşlarımı şarap gibi içmeye Her şeyi sineye ...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alistim-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç', 'uc-hatice-ari-58g1u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklımdan bir sayı tuttum; 

Üç,

Neden? 

Sınırın sayısıdır üç; 

Falların,

Yolların,

Dileklerin,

Dalda duran

Ya da,

Masal bitiminde düşen 

Elmanın; 

Aman be yazar,

Ne düşünürsün bu kadar,

Harcama boşa

Ne kağıdı,

Ne kalemi,

Ne de vaktini; 

Üç günlük dünya,

Ne sana kalır, ne bana

Ne de üçüncü şahsa...', 'Aklımdan bir sayı tuttum;  Üç, Neden?  Sınırın sayısıdır üç;  Falların, Yolların, Dileklerin, Dalda duran Ya da, Masal bitiminde düşen  Elma...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uc-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Akkuş''um', 'guzel-akkus-um-ozer-sutcu-ermpz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel akkuşum ne oldu sana 

Neden böyle suskun duruyorsun

Bir gelin gibi bürünmüşsün beyaza

Susma söyle yoksa üşüyormusun

Üzme sen kendini baharda gelecek

Kırlarında yine çocuklar oynayacak

Bu soğuk günlerde elbet bitecek

İnsanlar yeşilinle hayat bulacak

Yaz gelince ağaçların yaprak açar

Sokakların insanlarla dolar

Yaylalarından akar buz gibi sular

Sabret kış bitiyor gelecek ilkbahar

      NOT:(Akkuş ordu ilinin şirin bir ilçesidir)', 'Güzel akkuşum ne oldu sana  Neden böyle suskun duruyorsun Bir gelin gibi bürünmüşsün beyaza Susma söyle yoksa üşüyormusun Üzme sen kendini b...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/guzel-akkus-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünceler..', 'dusunceler-eyup-erdem-garzek-lfq9m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Konuşmayı sevmediğimi bilirsin..

Yazdığım şiirlerdeki duyguları hissetmeni,

Hissettiğin duyguları da bakışlarımla yüreğine vermek istiyorum.

Anlamlı sözlkte bulunmayan sözler yüzünden kavga emek,

Güzel geçirdiğimiz her günün anısını,

Yaşadığımız kötü günlerle bozmak istemiyorum..

Sevmek istediğim güzel sensin.

Başka nasıl anlatayım! 

Yalnızca seni istiyorum..', 'Konuşmayı sevmediğimi bilirsin.. Yazdığım şiirlerdeki duyguları hissetmeni, Hissettiğin duyguları da bakışlarımla yüreğine vermek istiyorum....', ARRAY['Türk Edebiyatı','Şiir','Eyüp Erdem Garzek']::text[], 8.5, '{"poet":"Eyüp Erdem Garzek","poet_slug":"eyup-erdem-garzek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dusunceler-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Rengi', 'bahar-rengi-necmi-unsal-ipx5k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağaçlar yaprak yaprak hep  uyanır.

Alemler  bahar  rengine  boyanır.

Mevsimden  başka  mevsime  girilmiş.

Her  bahar  yeni  mahşerde  dirilmiş.

Gün  olur,  döner  silkinme bu yaza.

Bakmışsın hemen bürünmüş  beyaza! 

18 Mart 2004 Perşembe,  Danimarka-Køge 00.40

3+2+3+3', 'Ağaçlar yaprak yaprak hep  uyanır. Alemler  bahar  rengine  boyanır. Mevsimden  başka  mevsime  girilmiş. Her  bahar  yeni  mahşerde  dirilm...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahar-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-sedat-tuvar-nv2tv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalınayak yürürdüm karlarda

Yanımda sen vardın

Buz tutardı dışı

İçini ter basardı mintanımın

Alev alev yanardım

Yanımda sen vardın

Aynı şehrin yazında

Kanım donuyor, üşüyorum

Sebebi yokluğunmudur? 

Üşüyorum..

Fırtınalar kopardı kışlarında 

Ben ellerinden tutardım

Aynı şehrin baharında

Tutunacak dal bulamıyorum

Sebebi yokluğunmudur? 

Düşüyorum

Düşüyorum

Üşüyorum...', 'Yalınayak yürürdüm karlarda Yanımda sen vardın Buz tutardı dışı İçini ter basardı mintanımın Alev alev yanardım Yanımda sen vardın Aynı şehr...', ARRAY['Türk Edebiyatı','Şiir','Sedat Tüvar']::text[], 8.5, '{"poet":"Sedat Tüvar","poet_slug":"sedat-tuvar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/usuyorum-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli de Değil', 'gizli-de-degil-eyup-erdem-garzek-vgawd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Keşke:

Sana beni kahreden sorunları anlatabilsem.

Tüm içtenliğimle ince ruhuna.

Biliyorum anlayacaksın ama; 

Henüz cesaretimi toplayamadım.

Ve döksem gözyaşımı,

Gölgenin düştüğü yere.

Eminim acılarımın sonu olacak ama; 

Yediremiyorum gururuma.

Uzun uzun yordum aklımı.

Sonuncusuda olacak döktüğüm gözyaşı.

Bilmelisin bir şeyler söylemek istiyorum ama; 

Söyleyemiyorum karşında.

İnanmak içinde hiçbir nedenin olamaz,kötülük yok

Anlatamadığım en karanlık yanımda.

Artık bilmelisin garipliğimin özü ''sensin''

Anla beni Allah Aşkına! 

Son bir dize daha yazmak istiyorum.

Yüreğimi koyduğum şiirimde.

Hayat yaşamaksa ki benim için öyle,

Tek Dile(...)  ''im sensin.

Mutluyum sonunda herşeyi anlatabildiğim için.', 'Keşke: Sana beni kahreden sorunları anlatabilsem. Tüm içtenliğimle ince ruhuna. Biliyorum anlayacaksın ama;  Henüz cesaretimi toplayamadım. ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Erdem Garzek']::text[], 8.5, '{"poet":"Eyüp Erdem Garzek","poet_slug":"eyup-erdem-garzek","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gizli-de-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlık Parası', 'baslik-parasi-mustafa-kara-xlkwq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni bedava mı verdiler bana 

iki milyar para saydım  güzelim

enayiliği tuttu yüreğimin

en büyük kazığı babandan yedim

korsan bir aptaldım biraz budala

bu gönlüm lap diye kondu her dala

sonra birde baktım nüfus kağıdıma

hayli büyümüşüm fakat ne fayda

şehir kızlarınıon abisi oldum

tıraş olmamışken babası oldum

ben de anlamadım bunca yıl durdum

sonra nasıl olduysa bak seni buldum

bir bir geçti şu gönlümden trenler

kulağımı deldi uğultular siremler

geri hiç bakmadı çekip gidenler

bu elim duruma kolay düşmedim

aşk kuyusuna küçükken düştüm

şimdikinden fakir ve de yoksuldum

bilmiyordum sevdaların yolunu

yüreğimi acemice çok yordum

öğrendim tanıdım aşk laflarını

bire bir yaşadım aldatılmayı

ihanetlerin en acısını

kalleşce öğrendim en hocasından

seni yol ortasında bulmadım güzelim

doğum günü partisinde yaş pastaya düşmedi bu yüreğim

bende anlamadım nasıl kapıldım

iki milyar para saydım güzelim

neticede biraz babanda yamuk

birazda bendeki bu enayilik

bu başlık parası hep var oldukça

yangında çil bulmak bizde evlilik.', 'seni bedava mı verdiler bana  iki milyar para saydım  güzelim enayiliği tuttu yüreğimin en büyük kazığı babandan yedim korsan bir aptaldım b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kara']::text[], 8.5, '{"poet":"Mustafa Kara","poet_slug":"mustafa-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/baslik-parasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişir....', 'degisir-cemil-dagidir-dyyxg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Değişir tüm doğrular

                   yalanlarsın kendini

Tanığısındır ikiyüzlü doğruların

Ve gerçek daha birçok kez 

                   karışacaktır yalanlara

Hiçbiri olduğun bu kargaşada

Yakana yapışmıştır bütün ihtimaller

Yerçekimi asılıdır ayaklarında            

Ağırlığınca düşüverirsin

Kendi gölgenin üstüne

Kim olacağın gelir aklına

Kim gibi yaşayacağın

Sahte yaşamlar

                 sürülür kent sokaklarına

Şahsiyeti sakıncalı olur as''lolanların

Bir bir toplanırsın yürüdüğün yollardan

Oysa böyle değildi başlangıçlarımız

Oyuncaklara küsmeden önceydi

                                            insandık...', 'Değişir tüm doğrular                    yalanlarsın kendini Tanığısındır ikiyüzlü doğruların Ve gerçek daha birçok kez                     k...', ARRAY['Türk Edebiyatı','Şiir','Cemil Dağıdır']::text[], 8.5, '{"poet":"Cemil Dağıdır","poet_slug":"cemil-dagidir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/degisir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affetmek mümkünmü', 'affetmek-mumkunmu-ozer-sutcu-uyq8w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnanmamalıydım sahte sözlerine 

Aldanmamalıydım  sahte sözlerine

Gelipte kapansan bile dizlerine

Seni affetmek mümkünmü

Sende kalmamış şahsiyet ve gurur

Seninle insan yalnızca dert bulur

Senin gibisine ancak lanet okunur

Seni affetmek  mümkünmü

Gözünden akan yaşlarda yalanmış

Adilik senin fıtratında varmış

Güzelim senin kalbin kararmış

Seni affetmem mümkünmü', 'İnanmamalıydım sahte sözlerine  Aldanmamalıydım  sahte sözlerine Gelipte kapansan bile dizlerine Seni affetmek mümkünmü Sende kalmamış şahsi...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/affetmek-mumkunmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ozer-sutcu-r37xt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşey bitti artık 

Yollarımız ayrıldı

İkimizin kaderi

Ayrı,ayrı yazıldı.', 'Herşey bitti artık  Yollarımız ayrıldı İkimizin kaderi Ayrı,ayrı yazıldı....', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayrilik-157-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişken', 'sevisken-sirma-mersin-m0kem', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sevişmenin sonu, zamansız ayrılıktı...

Kimsesiz ruhuma yer bulamadan; 

Sensizliğin gölgesine düştüm...

Sevişkenliğimle; 

Sensiz ve sessiz sevdamızın ruhuna dokunmaktaydı, benliğim! 

Sevişken ruhumla kölen olmuş, kadınlığım...

Nefesin bedenimi ısıtırken,

Ateşli öpüşmelerinle soluğum kesilir...

Sahipsiz ruhların içinde; kaybolan ruhum, senin kollarında canlanırken...

Uyanamadığım hayallerin arasında; 

Sevişkenliğimizin kıpırtısı çoğalır...

15.4.04', 'Her sevişmenin sonu, zamansız ayrılıktı... Kimsesiz ruhuma yer bulamadan;  Sensizliğin gölgesine düştüm... Sevişkenliğimle;  Sensiz ve sessi...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevisken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Artık', 'git-artik-ozer-sutcu-d76ed', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Git artık beni üzdüğün yeter

Gidersen belki bu çile biter

Senin sevgin bana dert ve keder

Al herşeyinide git artık

Seninle yaşamak zulüm oldu

Kalbim sevgi yerine dert buldu

Bak bütün hayallerim mahvoldu

Al herşeyinide git artık

Bir zamanlar ölürdüm senin uğurunda

Sende vefasız çıktın sonunda

Artık  bir hiçsin gönül tahtında

Al herşeyinide git artık

Yaşamak nedir unuttum sayende 

İhanet var güzel gözlerinde

Seni deli gibi seviyor olsam bile 

Al herşeyinide git artık', 'Git artık beni üzdüğün yeter Gidersen belki bu çile biter Senin sevgin bana dert ve keder Al herşeyinide git artık Seninle yaşamak zulüm old...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/git-artik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-ozer-sutcu-7fcr6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çoğu zaman dertlerime ortak ettiğim

Sığınmak için  tek dost bildiğim

Gündüzlerden daha çok sevdiğim

Sabırla beklediğim geceler', 'Çoğu zaman dertlerime ortak ettiğim Sığınmak için  tek dost bildiğim Gündüzlerden daha çok sevdiğim Sabırla beklediğim geceler...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/geceler-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceset', 'ceset-sirma-mersin-4olki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acıların demlenmiş hali! 

Yüreğime batan hançerin ucunda ; 

İnce ince damlayan kan damlaları,

Düşüyordu hayallerime...

Bir ceset gibi; kokan ruhum,

Soğuk çarşafın üzerinde kalmış, bi lekeydi  sanki...

Ölü  sevdanın suskunluğu sarmışken, odamı...

Titreyen  bir adamın gözyaşları damlıyordu, yüzüme...

Sevdasız kalmasına mı? yoksa

Bensizliğe kalması mı? onu bu halle koydu; bilinmez...

Belki de! 

Kimsesiz kalan ruhuna ağlıyordu...

Kimbilir! ...

16.04.04', 'Acıların demlenmiş hali!  Yüreğime batan hançerin ucunda ;  İnce ince damlayan kan damlaları, Düşüyordu hayallerime... Bir ceset gibi; kokan...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ceset-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus Konuşma', 'sus-konusma-ozer-sutcu-1amv6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sus konuşma

Konuştukça batıyorsun

Suçu kendinde aramayıp

Hep bana çamur atıyorsun

Gülüşlerin bile sahte

İnan hep yanlış yapıyorsun

Benim içim kan ağlarken 

Sen gününü gün ediyorsun

Şöyle bir etrafına bak

Eğriyi,doğruyu gör artık

Gençliğin elden gitmeden

Doğru yola dön artık

Seninkisi yalanlarla dolu bir hayat

Sahte şeyler seni mutlu ediyor

Belki birgün gerçeği bulacaksın

Ama unutma gençlik elden gidiyor', 'Sus konuşma Konuştukça batıyorsun Suçu kendinde aramayıp Hep bana çamur atıyorsun Gülüşlerin bile sahte İnan hep yanlış yapıyorsun Benim içi...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sus-konusma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan Ediyorum', 'i-syan-ediyorum-ozer-sutcu-fyrfm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dürüst bir dost bulamadığım dünyaya

Uyandığımda hayra yoramadığım rüyaya

Çile li yaşadığım bütün hayata

Gülmeyen kadere isyan ediyorum

Mutlu  bsonla bitmeyen aşklara

Bir hiç uğuruna akan yaşlara

Boş yere başıma vurulan taşlara

Beni anlamayanlara isyan ediyorum

Birgün olsun gülmeyen yüzüme

Dostların bile sahte olan sözüne

Bu kaderin bugününe dününe

Artık herşeye isyan ediyorum

İnsanın insanı ezdiği bu yerde

Hiç yoktan başın girerse derde

Birde yerin yoksa gönüllerde

Sahte dostlara isyan ediyorum', 'Dürüst bir dost bulamadığım dünyaya Uyandığımda hayra yoramadığım rüyaya Çile li yaşadığım bütün hayata Gülmeyen kadere isyan ediyorum Mutlu...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/isyan-ediyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençliğim', 'gencligim-ozer-sutcu-u2fh5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün olsun yaşamadan

Onun tadına varmadan

Nedir diye tanımadan

Bitti gidiyor gençliğim

Boş yere onu harcadım

Bitmez diye kağale almadım

Nasıl geçti hiç anlamadım

Bitti gidiyor gençliğim

Sandım ki hep bende kalacak

bu yaş ilerleyip ömür dolmayacak

Sonunda anladım ihtiyarlıkta gelecek

Bitti gidiyor gençliğim', 'Birgün olsun yaşamadan Onun tadına varmadan Nedir diye tanımadan Bitti gidiyor gençliğim Boş yere onu harcadım Bitmez diye kağale almadım Na...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gencligim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbeler Olsun', 'tovbeler-olsun-ozer-sutcu-tzkfi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölürken ecelime çare bulsanda

Azrağilin önüne kaya gibi dursanda

Dünyanın en güzeli sen olsanda

Seni sevmeye artık tövbeler olsun

Olmadık yere kalbimi kırdın

Seninle dopdolu dünyamı yıktın

Düşman gibi bir kurşunda sen sıktın

Seni sevmeye artık tövbeler olsun

Köle oldum sana değer vermedin

Benim gibi sende beni sevmedin

Seni seven kalbimden ne istedin

Seni sevmeye artık tövbeler olsun

Kendini herşeyin üstünde gördün

Güzelliğinle her yerde öğündün

Sonunda saman alevi gibi söndün

Seni sevmeye artık tövbeler olsun', 'Ölürken ecelime çare bulsanda Azrağilin önüne kaya gibi dursanda Dünyanın en güzeli sen olsanda Seni sevmeye artık tövbeler olsun Olmadık ye...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tovbeler-olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinçaltı Şiirleri-2', 'bilincalti-siirleri-2-oguzkan-bolukbasi-jtj93', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimleri ısıracağım kudurursam

Sonra cezai ehliyetsiz serbest dolaşacağım

Bilinçaltımı ezince

Avrupa birliğine bireysel üye olacağım

Seni en kalabalık caddelerde öpeceğim', 'Kimleri ısıracağım kudurursam Sonra cezai ehliyetsiz serbest dolaşacağım Bilinçaltımı ezince Avrupa birliğine bireysel üye olacağım Seni en ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bilincalti-siirleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Deli Çocuk', 'hey-deli-cocuk-ozer-sutcu-qgndo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hey deli çocuk dimdik ayakta duracaksın

Galleşlere fırsat vermeden hep varolacaksın

Üç kuruş menfaat için el öpmeden

Şerefin ve haysiyyetinle yaşayacaksın

Yoluna it sürüleri çıkacak

Belkide hepsi sana saldıracak

Sakın ümitsizliğe kapılma dostum

Bu savaştan mertler galip çıkacak', 'Hey deli çocuk dimdik ayakta duracaksın Galleşlere fırsat vermeden hep varolacaksın Üç kuruş menfaat için el öpmeden Şerefin ve haysiyyetinl...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hey-deli-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metin 1', 'metin-1-eyup-erdem-garzek-llw7e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi; 

Güneş gibi,aşk gibi...

Gözlerinin içine dolsam damla damla.

Sonra sarsam bedenini kor gibi,yakar gibi...

Ruhun ruhmda ışık gibi,var yok gibi sokulsa.

Belki özlemeyi bırakırdım seni buralarda', 'Şimdi;  Güneş gibi,aşk gibi... Gözlerinin içine dolsam damla damla. Sonra sarsam bedenini kor gibi,yakar gibi... Ruhun ruhmda ışık gibi,var ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Erdem Garzek']::text[], 8.5, '{"poet":"Eyüp Erdem Garzek","poet_slug":"eyup-erdem-garzek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/metin-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Annem', 'canim-annem-mahmut-catak-suhfy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kanından kan verdin

Canından can

Dünyaya getirdin beni

Destek oldun yürüttün

Ellerinle besledin

Büyüttün beni

Nasıl sevmem ben seni 

Canım annem

Kanayan yaramı 

İlk sen sardın 

En kötü günüm de 

Hep sen vardın

Elime diken batsa 

Güle kızardın

Çok seviyorum seni

Canım annem

Zamanın gelince

Sende gideceksin

Cennette annene

Eşlik edeceksin

Yavrun senin yolun da

Bunu göreceksin

Hep seveceğim seni

Canım annem', 'Kanından kan verdin Canından can Dünyaya getirdin beni Destek oldun yürüttün Ellerinle besledin Büyüttün beni Nasıl sevmem ben seni  Canım a...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çatak']::text[], 8.5, '{"poet":"Mahmut Çatak","poet_slug":"mahmut-catak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/canim-annem-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükürler Olsun', 'sukurler-olsun-hifzi-ozbekmez-4sbjz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatım boyunca aradım seni

Sonunda buldum ya şükürler olsun

Sende seviyorsun bilirim beni

Gönlüne doldum ya şükürler olsun

Ellerim eline değdiği anda

Dedim ki mutluluk buymuş cihanda

Aşk ile titreyen gül yüzlü canda

Muradım aldım ya şükürler olsun

İki cihanda benim helalimsin sen

Sevda bayrağımda hilalimsin sen 

Damarımda kanım mecalimsin sen

Sevdiğim oldun ya şükürler olsun

Latifim sevdaya salan sen oldun

Aklımı başımdan alan sen oldun

Gönlüme sel gibi akıp ta doldun

Esirin oldum ya şükürler olsun', 'Hayatım boyunca aradım seni Sonunda buldum ya şükürler olsun Sende seviyorsun bilirim beni Gönlüne doldum ya şükürler olsun Ellerim eline de...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sukurler-olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerindeyim', 'gozlerindeyim-fatih-aydogdu-ydmbo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben, bozkırın sarısındayım

Kardelen çiçeğinin kokusunda

Bir ölünün uykusundayım.

Beni bir serçenin gözyaşları diriltir.

Bir bebeğin gamzesindeyim

Cırcır böceğinin nefesindeyim

Gökyüzünün rengiyim ben.

Bir şehit toprağa düştüğünde

Ben, şehadetin türküsündeyim.

Yusufun gömleğindeyim

Beni bir kurdun dişleri kanatır.

Kumdağında kar çiçeğiyim ben.

Ben Aslı''nın düğmesindeyim

Kerem''in ateşiyim

Beni bir azizin nefesi söndürür.

Ben, sahipsiz akşamların

Ürkek ceylanların

Denizde yürüyen martıların

Gözlerindeyim.

Ve birgün aklına düşürse gözlerim

Aynalarda gülen gözlerinin ta içine bak

Ben, gözlerindeyim...', 'Ben, bozkırın sarısındayım Kardelen çiçeğinin kokusunda Bir ölünün uykusundayım. Beni bir serçenin gözyaşları diriltir. Bir bebeğin gamzesin...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aydoğdu']::text[], 8.5, '{"poet":"Fatih Aydoğdu","poet_slug":"fatih-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gozlerindeyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-fatih-aydogdu-xphhf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneş, geceye karanlığa isyan

Deniz susamışlığa isyan

Yağmur kurumuşluğa isyan

Meşe, menekşe bozkıra isyan

Tebessüm gözyaşına isyan

Vuslat ayrılığa isyan

Güller, bülbüller baykuşa isyan

Özgürlük tutsaklığa isyan

Gök mavisi kan kızılına isyan

Düşler, hayaller acı gerçeğe isyan

Yaz kışa, bahar hazana isyan

Kartal kargalara isyan 

Kurt çakallara isyan

Doğan her bebek ölüme isyan

Ve zaman,

Zaman bastıramadığım tek isyan! ..', 'Güneş, geceye karanlığa isyan Deniz susamışlığa isyan Yağmur kurumuşluğa isyan Meşe, menekşe bozkıra isyan Tebessüm gözyaşına isyan Vuslat a...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aydoğdu']::text[], 8.5, '{"poet":"Fatih Aydoğdu","poet_slug":"fatih-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/isyan-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Konya Olsan', 'sen-konya-olsan-ahmet-aka-48h0o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gedavet olsan ikindi üstleri

bildik bilmecelerle 

tarasan saçlarımı

secdeye değen yanımı öpsen 

ya da sen konya olsan…

seğirtsen önümden bir atlı gibi 

ve yetişmek için düşsem ardına

yine çocuk olsam

yine bir çocuk…

ya da sen konya olsan

eski sokaklarda o kerpiç evler

gözümde olduğu gibi dursa yerinde 

duvara yaslanan ihtiyar çeşme

serinlik damıtsa servi söğütle

ya da sen konya olsan

köşe başlarında delikanlılar

süpürse sille kokan yolları

araboğlu makasından zafer’e

uzansa atlı tramvaylar, 

ya da sen konya olsan

perşembe günleri çocuklar için

şivlilik hazırlasa genç kızlar

akşam olmadan takkeli dağa

bir bulut olup ağsam

ya da sen konya olsan', 'gedavet olsan ikindi üstleri bildik bilmecelerle  tarasan saçlarımı secdeye değen yanımı öpsen  ya da sen konya olsan… seğirtsen önümden bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-konya-olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazmayacaktım; Ama...', 'yazmayacaktim-ama-eyup-erdem-garzek-8ka6l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kötü sözlerle üzüyorsun beni.

Biliyorsun seni nasıl sevdiğimi.

Yapacaksan düşündüklerini,

Vakit var daha deme! 

Olacaksa sonumuz ayrılık,

Hatırlayayım seni en güzel halinle.

Sonra ömür boyu saklarım hatıranı,

En özel,hep güzel bir çiçek gibi kalbimde.

Yazık ki hiçbir ümit  yok,

Senden öte sevdalarda.

Çıkar yolum yok,

Blinmeze giden diyarlarda...', 'Kötü sözlerle üzüyorsun beni. Biliyorsun seni nasıl sevdiğimi. Yapacaksan düşündüklerini, Vakit var daha deme!  Olacaksa sonumuz ayrılık, Ha...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Erdem Garzek']::text[], 8.5, '{"poet":"Eyüp Erdem Garzek","poet_slug":"eyup-erdem-garzek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yazmayacaktim-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bağı', 'gonul-bagi-mahmut-catak-1hqvl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tam herşey bitti derken

En çok sevdiğin

Terkedip giderken

Hayat devam ediyor aslında

Başka birini yeniden seversen

Zaman herşeyin ilacıdır

Severken ayrılmak 

Terkedilmek çok acıdır

Sen seversen sevilmek kolay

Karşılıksız seven baştacıdır.

Nerde mutluluğun

En son durağı

Ya hayallerde yeri 

Ya da kafdağı

Öyle bir düğüm olsaki

Hiç çözülmese

Birbirini sevenlerin 

Gönül bağı', 'Tam herşey bitti derken En çok sevdiğin Terkedip giderken Hayat devam ediyor aslında Başka birini yeniden seversen Zaman herşeyin ilacıdır S...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çatak']::text[], 8.5, '{"poet":"Mahmut Çatak","poet_slug":"mahmut-catak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gonul-bagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aradım', 'seni-aradim-fatih-aydogdu-q2zl9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni aradım,

Güneşin mehtaba her batışında..

Ay karanlığında, yıldız suskunluğunda

En ıssız yerde açan zambak yalnızlığında

Ve hırçın dalgaların bestelediği 

Umutsuzluk şarkılarında aradım seni.

Her gece,

Boğazıma düğümlenen sessiz çığlıkların

Pınarından boşalamayan

Göz yaşlarımın çaresizliğinde aradım seni.

Sonbaharda,

Ayağıma kapanan solgun yapraklar

Saçlarımı okşayan soğuk rüzgarlar

Hüzünlendirdi beni.

Ölüm geldi aklıma

Acaba ölmüş müydün

Ölüpte kalbimin en derin yerine

Gömülmüş müydün?', 'Seni aradım, Güneşin mehtaba her batışında.. Ay karanlığında, yıldız suskunluğunda En ıssız yerde açan zambak yalnızlığında Ve hırçın dalgal...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aydoğdu']::text[], 8.5, '{"poet":"Fatih Aydoğdu","poet_slug":"fatih-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-aradim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir Yıkılıyor', 'sehir-yikiliyor-ahmet-aka-s11ln', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'takkeli dağ içime düşüyor bu gece

yıldırımlara çarpıyorum kendimi

elimi ölümün şakağında yıkıyorum

şehir yıkılıyor

ben ayıkıyorum

şekerden, nergisten uzak

bir aşık acem türküleri çığırıyor 

dağınık saçları, kirli sakalı...

yalan gibi...

yaş / otuz üç

kuytu tebessümler dağıtıyor

adım gibi biliyorum

o/ysa bir benimle barışık

bir tek benimle...

iki de bir düşlerimi damıtıyor

şehrin bulutları avucumuzda

yılgın atlar kar tanesi bir ordu

geceyi kurdele yapan çocuk

sessiz sedasız

bir çığlık omzumuzda', 'takkeli dağ içime düşüyor bu gece yıldırımlara çarpıyorum kendimi elimi ölümün şakağında yıkıyorum şehir yıkılıyor ben ayıkıyorum şekerden, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sehir-yikiliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Kimsenin Sevmediği Gibi', 'hic-kimsenin-sevmedigi-gibi-banu-aka-lwo6l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç kimseyi sevmediğin gibi 

Sevmelisin beni 

Uzun bir yolculuktan dönen denizcinin 

Kıyıdaki deniz fenerini 

İlk gördüğü andaki heyecanla 

Tenim tenine değdiğinde ürpermelisin 

Sıcak bir akşam rüzgarı 

Seni çepeçevre kucaklarmış gibi 

Sana sevgiyle baktığımda

Tüm yüreğinle bana akmalısın

Bir damla gözyaşının kendine yol bulup 

Yanaktan dudağa usulca kayması gibi 

Herşeyin olmalıyım senin 

Öbür boyu gönüllü tutsağı yüreğinin 

Nefesin, gülüşün, gözyaşın olmalıyım 

Ve sana milyonlarca kez söylemeliyim 

Sevdiğimi 

Dudakların dudaklarımdayken', 'Hiç kimseyi sevmediğin gibi  Sevmelisin beni  Uzun bir yolculuktan dönen denizcinin  Kıyıdaki deniz fenerini  İlk gördüğü andaki heyecanla  ...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hic-kimsenin-sevmedigi-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğimde', 'gittigimde-banu-aka-verjr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana gözlerimi bırakacağım 

Beni özlediğinde 

Sevgiyle gülümseyecekler sana

Aşkımı anlatacaklar 

Hiç bitmeyen satırlarda 

Sana ellerimi bırakacağım

Sıcacık tutacaklar avuçlarını 

Yüzünde dolaşacak  parmaklarım

Kıvrım kıvrım

Sana dudaklarımı bırakacağım 

Dirseğinin iç tarafında izi kalacak 

Kokum kalacak yastığında 

Yanında bulacaksın beni 

Yüreğim senin için atacak 

Duyacaksın, yalnız senin için 

Giden ben değil, bedenim olacak

Anlayacaksın....', 'Sana gözlerimi bırakacağım  Beni özlediğinde  Sevgiyle gülümseyecekler sana Aşkımı anlatacaklar  Hiç bitmeyen satırlarda  Sana ellerimi bıra...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gittigimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Bir Sayfaydım..', 'bos-bir-sayfaydim-eyup-erdem-garzek-a4a6h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi yeni yazılan bir şiir oldum.

Geçmiş neleri hatırlatır,düşündürür kim bilir! 

Düne saplanmış unutulmamış özel anlar.

Kendine geldiğinde tokat olur; sonra yas,

Yürekten atılamaz,yürek olur özlenen.

Daha gencim alışmam lazım diyorum ya...

Tutamıyorum hislerimi çarpıyorum yalnızlığa.

Usulca yazıyorum beni ben yapan benden kaçar gibi.

Biliyorum bugün de hatırlanacak özleminle geçen dünler gibi.', 'Şimdi yeni yazılan bir şiir oldum. Geçmiş neleri hatırlatır,düşündürür kim bilir!  Düne saplanmış unutulmamış özel anlar. Kendine geldiğinde...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Erdem Garzek']::text[], 8.5, '{"poet":"Eyüp Erdem Garzek","poet_slug":"eyup-erdem-garzek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bos-bir-sayfaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamamak', 'unutamamak-banu-aka-ib5s4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutamıyorum dediğin yürek acısıdır

İçten içe kanar da durur

Her nefeste yeniden deşilir ya, kapatamazsın

Yaşlı gözlerin uzak denizleri arar hep 

Baktığın her denizde onun gözleri 

Gördüğün her gülümseyişte 

Sevgilinin dudak uçlarıdır yüreğine batan 

Elele gezdiğiniz o sakin sokaklarda

Sevgilinin ayak izleri kalmıştır diye 

Eğilip öpesin gelir de dayanamazsın 

Mektuplarını okursun sen de kalan 

Binlerce kez ölürsün de satır aralarında 

Bir an bile dinmez acısı yüreğinin 

Ve gün gelir anlarsın ki 

Nicedir ağladığın 

Onun gidişi değil; kendi çaresizliğindir.', 'Unutamıyorum dediğin yürek acısıdır İçten içe kanar da durur Her nefeste yeniden deşilir ya, kapatamazsın Yaşlı gözlerin uzak denizleri arar...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutamamak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İHL Marşı*', 'i-hl-marsi-ahmet-aka-r7et1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kılcal damarlarında kılıçtan keskin sızı; 

Bilirim, zaman bozuk! Asır, arın hırsızı.

Nasıl olurdu gençlik, rehberi olmasaydın? 

Dünya seninle güzel, dünya seninle aydın.

Senin sarığın beyaz, bir toz bile kondurma.

Bunun için farklısın, fakat yine de durma.

Nerden nereye geldin… Çok zor senin görevin! 

Yıllar önce zayıftın, şimdi can buldun sevin.

Yüreklerde şahlanan coşkun bir arzu gibi,

Sustururlardı belki sen olmasaydın beni.

Bir gelecek saklıydı sinende umut dolu; 

Gösterdin yıllar yılı bizlere doğru yolu.

Engellere engel ol  sarılarak Kuran’a

Yaşa, yaşat ve kurtar, emin yürü yarına 

İmam-Hatip Lisesi senin de dâvân, sesin! 

Güneşi küllendirir istesen tek nefesin.

Kendini zamanlara tutsak etmeyen gençlik! 

Düşürme sancağını; Cafer ol da burca dik…

Nasıl yıkabilir ki hainler bu inancı? 

Kesilmeli içinde kol gezip duran sancı.

İmam-Hatipli gencim! Alnın açık, yol açık.

Bir şey seni bekliyor, onun için yola çık.

Okuduğun bu okul, senin pusulan, rotan…

Adın değil, imanın inanmazı korkutan! 

Kalbimden kopardığım şu son sözü de dinle:

Küfrün yolunu kapat güçlü iman bendinle

Ki… böyle yapıyorsun, yardım ediyor Allah

Rabbinden başkasına el açmazsın İnşallah! 

* Bu şiir M.E.B. Din Öğretimi Genel Müdürlüğü''nce İHL''lerin 40. yıldönümü dolayısıyla açılan yarışmada Türkiye birinciliği ödülünü aldı. (1991)', 'Kılcal damarlarında kılıçtan keskin sızı;  Bilirim, zaman bozuk! Asır, arın hırsızı. Nasıl olurdu gençlik, rehberi olmasaydın?  Dünya seninl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ihl-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardaydın', 'uzaklardaydin-banu-aka-love6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doludizgin seni düşünüyorum

Gözlerin diyorum 

İçi gülen güzelim gözlerinin 

Denizlerin rengini kıskandıran 

Baktıkca sevdiğim gözlerin 

Dudakların diyorum

Tatlı kıvrımlarında aşkı gizlediğin 

Öptükçe öpmek istediğim dudakların

Ellerin diyorum

Hep sıcak, sevecen ellerin 

Parmak uçlarında nabız gibi atan

Dokundukca tenimi yakan ellerin 

Sevgilim diyordum

Delicesine sevdiğim 

Sonsuzca seveceğim benim 

Çok uzaklardaydın

Beni duymadın', 'Doludizgin seni düşünüyorum Gözlerin diyorum  İçi gülen güzelim gözlerinin  Denizlerin rengini kıskandıran  Baktıkca sevdiğim gözlerin  Duda...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uzaklardaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlık', 'yanlizlik-banu-aka-y73v2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgilerin paylaşılmadığı

Umutların darmadağın olduğu 

Küçücük bir adadır 

Yalnızlık

Utanmadan ağlarken 

Bir an susup gözlerini kapadığında

Görecek kimsenin olmadığı 

O boşluktur yanlızlık 

Şimdi sadece unutmaya çalışmak vaktidir

Yalnızlıksa artık

Katlanılması gereken upuzun bir gecedir 

Güneşi  doğmacak', 'Sevgilerin paylaşılmadığı Umutların darmadağın olduğu  Küçücük bir adadır  Yalnızlık Utanmadan ağlarken  Bir an susup gözlerini kapadığında ...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanlizlik-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlu Geceler', 'yagmurlu-geceler-fatih-aydogdu-14rdn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceleri sokağa yağmur yağar

Kaldırımlarda kırık aynalar var

Rüzgarın çığlığı sokağı kaplar

Üşür ruhları sökülmüş ağaçlar.

Geceleri sokağa yağmur yağar

Evsizler kuytu birer mesken arar

Titrer sokaklarda yanan lambalar

Tellerinde baykuşlar nara atar.

Yağmur yağar sokağa geceleri

Bilmem ne rüyalarda niceleri

Bense uykusuzum günlerden beri

Gezer dururum sokakta serseri.

Sabah olur hepten diner yağmur

Yağmurdan arda kalır ıslak, çamur

Babalar uyanır, gözleri mahmur

Avareliğim böylece son bulur..', 'Geceleri sokağa yağmur yağar Kaldırımlarda kırık aynalar var Rüzgarın çığlığı sokağı kaplar Üşür ruhları sökülmüş ağaçlar. Geceleri sokağa y...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aydoğdu']::text[], 8.5, '{"poet":"Fatih Aydoğdu","poet_slug":"fatih-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmurlu-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutuş', 'unutus-banu-aka-wzw5l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Usul usul esmekte rüzgar

Saçlarımı savuruyor 

Deniz kokuyor her taraf

Seni düşünüyorum 

Elimde içki kadehim 

Sarhoş olmalıyım bu gece 

Gözlerin dibi olmayan kuyulara benziyor

Denizi görebiliyorum 

Rüzgarı hissedebiliyorum 

Kadehime çarpan yağmur damlaları 

Geçmişten gülümsüyorsun 

Sarhoş olmalıyım bu gece 

Sadece seni unutabilmek için 

Dudaklarımda buruk bir şarap tadı 

Seni içiyorum

Bu gece –nihayet- sarhoşum

Nefesin olmuş rüzgar 

Ilık, şarap kokuyor 

Gece;  soğuk

Uzaklardan bir müzik sesi 

Melodisine alışkın olduğum

Gözyüzünde hiç yıldız yok

Kesik kesik yağmur

Ben seni içiyorum 

Dudaklarımda buruk bir şarap tadı 

Bu gece – nihayet- sarhoşum... 

-Ama unutmuş değil-', 'Usul usul esmekte rüzgar Saçlarımı savuruyor  Deniz kokuyor her taraf Seni düşünüyorum  Elimde içki kadehim  Sarhoş olmalıyım bu gece  Gözle...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/unutus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrim Şarkıları', 'devrim-sarkilari-ahmet-aka-t0x88', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'devrim şarkıları ezberletirdi babam

annemin gözleri şişerdi ağlamaktan 

akşamları ağabeyim, 

mermisi tükenmiş mavzerini  yağlardı 

ocak başında yarı uykulu yarı uyanık ederdik sabahı

hiç de yabancı gelmeyen postallar basardı kasabayı

değiştirirdi yolların coğrafyasını darağaçları

sarıklıların idam edildiği günlerde

Medine’ye hicret etmişti amcam

idam edilecekti yoksa

şairdi amcam

o da devrim şarkıları ezberletirdi çocuklarına

özgürlüğü zincire vurmuştu bir haydut

hürriyet alınmıştı insanların elinden

değiştirdiler ismini esaretin 

sonra mağaralara gizlendi ilim 

düğünler unutuldu

bayramsız büyüdü çocuklar 

nice delikanlının uçurdular başını

zindan mesken sayıldı

yarım kaldı babamın ezberlettiği şarkılar

yarım kaldı lâiklik

yarım kaldı ihtilâl', 'devrim şarkıları ezberletirdi babam annemin gözleri şişerdi ağlamaktan  akşamları ağabeyim,  mermisi tükenmiş mavzerini  yağlardı  ocak başı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/devrim-sarkilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma', 'sorma-banu-aka-rcj3a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutlarımı sakın sorma

Çok zaman önce kaybettim onları

Yiten sevgilimin ardından

Gözyaşlarımla aktı gitti

Çok zaman önce vazgeçtim

İnanmaktan masallara

Aşk sadece

Şiirlerde kaldı', 'Umutlarımı sakın sorma Çok zaman önce kaybettim onları Yiten sevgilimin ardından Gözyaşlarımla aktı gitti Çok zaman önce vazgeçtim İnanmakta...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sorma-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Matematiği', 'askin-matematigi-aysun-elagoz-oyhu3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki paralel çizgiydik

Hayat düzleminde

Hiç kesişmeyen...

Birliktelik çabalarımız

Bilinmeyen sayısını arttırmak gibiydi

Çok bilinmeyenli denklemlerin...

Hayaller, imkansızlıklara bölününce,

Elde kalan,

Ümit hanesine yazılmış kocaman bir hiç idi..

Bir de çaresizlik eklenmişti,

Tam sayılarına aşkın..

Çizgilerden biri,

Yeni başlangıçlara giderken

Diğeri

Yönlenmişti sonuna hayatın.

İki paralel çizgiydik

Hayat düzleminde

Kesişmesi

İhtimal dahilinde olmayan...', 'İki paralel çizgiydik Hayat düzleminde Hiç kesişmeyen... Birliktelik çabalarımız Bilinmeyen sayısını arttırmak gibiydi Çok bilinmeyenli denk...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/askin-matematigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Ummadığım Anda', 'en-ummadigim-anda-banu-aka-9uv2j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıkıp geliversen şimdi

En ummadığım anda

Tıpkı seni ilk sevişim gibi

Gülümseyen gözlerine bakıp

Bu aşk deyişim gibi

En beklemediğim anda

Sarıversen beni ateş alev

Hiç bırakmayacakmış gibi

Aynı aşk seni de tutuştursa

En ummadığın anda', 'Çıkıp geliversen şimdi En ummadığım anda Tıpkı seni ilk sevişim gibi Gülümseyen gözlerine bakıp Bu aşk deyişim gibi En beklemediğim anda Sar...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/en-ummadigim-anda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-banu-aka-jktzd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün

Dudaklarında kırık dökük bir gülümseme

Bana döneceksin

O yüzden 

Kal demeyeceğim sana

Adımı söyleyeceksin

Sıcak bir meltem gibi kulağıma

Aşkımın seni hiç bırakmayacağını

Anlayacaksın

Bir gün

Dudaklarında kırık dökük bir gülümseme

Bana döneceksin

Biliyorum…', 'Bir gün Dudaklarında kırık dökük bir gülümseme Bana döneceksin O yüzden  Kal demeyeceğim sana Adımı söyleyeceksin Sıcak bir meltem gibi kula...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gun-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay mı?', 'kolay-mi-banu-aka-yim9t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kolay mı sanırsın 

Acısını taşımayı istenmeyişin

Onsuz olamayacağını düşünürken 

Kapkaranlık bir yanlızlık ortasında bırakılmayı

En güzel yerinde kesilmesini hayallerinin

Kolay mı sanırsın

Yokluğunda ağladığını unutmayı

Özlemiyle boğulduğunda 

Onun gözlerinin gecesinde uyumak için çırpındığını

Kolay mı sanırsın 

Bile bile sevmediğini

Unutamamayı çaresiz

İçin darmadağınken gülümsemeyi 

Yüzünü görecek gücün yokken 

Delicesine onu istemeyi

Kolay mı sanırsın 

Sen

Unutulmayı', 'Kolay mı sanırsın  Acısını taşımayı istenmeyişin Onsuz olamayacağını düşünürken  Kapkaranlık bir yanlızlık ortasında bırakılmayı En güzel ye...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kolay-mi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmiyorsun', 'gelmiyorsun-banu-aka-4jwog', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökkuşağını bekliyorum

Yağmurların arkasından

Ama

Yine fırtına, yine soğuk

Islak, ıpıslak gözlerim

Yağmurla yarışmada

Seni bekliyorum

Yağmurların ardından

Gelmiyorsun.', 'Gökkuşağını bekliyorum Yağmurların arkasından Ama Yine fırtına, yine soğuk Islak, ıpıslak gözlerim Yağmurla yarışmada Seni bekliyorum Yağmur...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gelmiyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-banu-aka-2qul8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün güneş başka bir güzel

Isıtacak yeryüzünü

Bambaşka bir aydınlık 

Sarmalayacak

Herşey bir başka olacak

Denizlerde fener alayına çıkacak balıklar 

Yakamoz niyetine 

Görülmemiş bir mavide uçacak kuşlar

Ay başka türlü gülümseyecek 

Yıldızlara kurduğu salıncaktan 

Bir gün 

Herşey bambaşka uyanıp

Bambaşka dalacak uykuya 

Bekliyorum..', 'Bir gün güneş başka bir güzel Isıtacak yeryüzünü Bambaşka bir aydınlık  Sarmalayacak Herşey bir başka olacak Denizlerde fener alayına çıkaca...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bekliyorum-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Acısı', 'ask-acisi-eyup-erdem-garzek-0bowq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk acısı bu:

Ne su gibi akıp gidiyor.

Ne alev gibi yanıp sönüyor.

Sesimi titretiyor,

Ellerimi terletiyor,

Kalbimi kırıyor.

Tutkularım oluyor,sevinçlerim de.

Senle geçen saatlerde,

Sensizim...

En acısı da,ayrılık acısı galiba! 

(18.06.1998 / İstanbul)', 'Aşk acısı bu: Ne su gibi akıp gidiyor. Ne alev gibi yanıp sönüyor. Sesimi titretiyor, Ellerimi terletiyor, Kalbimi kırıyor. Tutkularım oluyo...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Erdem Garzek']::text[], 8.5, '{"poet":"Eyüp Erdem Garzek","poet_slug":"eyup-erdem-garzek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-acisi-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırış', 'haykiris-fatih-aydogdu-nlc9g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim duyar gecelerin şu çığlığını

Hangi bahar büyütür gül yaprağını

Ölesiye susayan çöl toprağını

Bilmem kaç yağmurun ıslatacağını.

Hangi ceylan yavrusu kaçar kaplandan

Kaç damla süzülür serçe yanağından

Umutla sararan buğday başağından

Habarsizim, kaç mazlumun doyduğundan.

Bir tek idamlığa kaç sehba kurulur

Bilmem bir sehbaya kaç tekme savrulur

Nice vaadler ve yeminler bozulur

Bilmem kaç yiğit yüreğinden vurulur.

Kim alır beni yalnızlığın elinden

Kim kurtarır beni bu çile selinden

Ne ister zaman, bunca yıldır benden

Ya Rab! Nedir çektiğim kader elinden.', 'Kim duyar gecelerin şu çığlığını Hangi bahar büyütür gül yaprağını Ölesiye susayan çöl toprağını Bilmem kaç yağmurun ıslatacağını. Hangi cey...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aydoğdu']::text[], 8.5, '{"poet":"Fatih Aydoğdu","poet_slug":"fatih-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haykiris-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-banu-aka-prcwr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokluğun camıma vuruyor

Yağmur damlaları telaşıyla

Oysa gök mavi, bulut beyaz

Sen yoksun ya burda, yanımda

Kollarım sarmıyor ya seni

Kokunu duymuyorum ya

Ne gök mavi ne bulut beyaz

Yokluğun

Sağanak sağanak 

Gözlerimde duruyor', 'Yokluğun camıma vuruyor Yağmur damlaları telaşıyla Oysa gök mavi, bulut beyaz Sen yoksun ya burda, yanımda Kollarım sarmıyor ya seni Kokunu ...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yoklugun-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatabilseydim', 'anlatabilseydim-banu-aka-58b7p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Keşke anlatabilseydim sana 

Başımı omzuna koyduğum 

Andaki mutluluğumu

Yüreğimde hissettiğim o doyumsuz huzuru

Sana her dokunuşumda 

Parmakuçlarımdan içime akan 

Sıcaklığının 

Beni nasıl tutuşturup yaktığını

Teninin kokusunu 

Her içime çekişimde 

Duydugum o betimsiz aşkı

Dudaklarından çıkan adımın

Sadece senden işitmek istediğim tınısının

Başımı nasıl döndürdüğünü 

Keşke anlatabilseydim sana 

Sensizliğin ne demek olduğunu

Seni özlemenin

O buruk ama güzel tadını

Ve benim için

Vazgeçilmez olduğunu….', 'Keşke anlatabilseydim sana  Başımı omzuna koyduğum  Andaki mutluluğumu Yüreğimde hissettiğim o doyumsuz huzuru Sana her dokunuşumda  Parmaku...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlatabilseydim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-banu-aka-42w2t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öylece gidiyorsun ya hani 

İzleri dururken daha parmaklarının tenimde 

Kokun her yanı sarmışken 

İnce bir burukluk bırakrak yüreğimde

Bizi çevreleyen herşeyden nefret ediyorum 

Söylemek istediklerimin 

Hiçbirini söyleyememişken sana 

Anlatamamışken ne denli sevildiğini

Doyamamışken güzelim gözlerine 

Öylece gidiyorsun ya hani 

Ölmekten beter oluyorum 

O geçici ayrılışı ellerimizin –isteksiz-

Ve biliyorken cevabını

Dudaklarının tadı silinmemiş dudaklarımda 

Asılı kalışı iki hecenin:

“Gitme”', 'Öylece gidiyorsun ya hani  İzleri dururken daha parmaklarının tenimde  Kokun her yanı sarmışken  İnce bir burukluk bırakrak yüreğimde Bizi ç...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gitme-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Sen', 'sadece-sen-banu-aka-rtyak', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bırak sevgilim

Kutsanmış aşkları başkaları yaşasın

Başkaları ulaşsın yedinci kubbeye

Ben seni istiyorum

Başında haleler olmasa da olur

Kanatlarını çoktan almış olsunlar

Ne çıkar

Ben seni istiyorum

Bırak sevgilim

Kusursuzu ararken başkaları kaybetsin zamanlarını 

Biz kendimizi keşfedelim önce 

Kendi kutsallığımızı

Kendi kusursuzumuzu kendimiz yaratalım

Sevgimizle.', 'Bırak sevgilim Kutsanmış aşkları başkaları yaşasın Başkaları ulaşsın yedinci kubbeye Ben seni istiyorum Başında haleler olmasa da olur Kanat...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sadece-sen-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşırma', 'sasirma-banu-aka-ukwd7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerine dalıp

En aydınlık geceyi getireceğim sana

Hayal bile edemediğin güzellikte 

Tadılmamış aşklar bırakacağım avuçlarına

Güneşte kızmış kumlar gibi

Gökyüzü nasılmış, ozaman anlayacaksın

Binlerce kuş havalanacak yüreğinden aynı anda

Şaşıracaksın

Korkularından, önyargılarından sıyrılsan 

Kurtarsan beynini o hummalı tutsaklıktan 

Gülümsesen geleceğimize kaşlarını çatmadan

Tadılmamış aşklar bırakacağım avuçlarına

Şaşırmayacaksın.', 'Gözlerine dalıp En aydınlık geceyi getireceğim sana Hayal bile edemediğin güzellikte  Tadılmamış aşklar bırakacağım avuçlarına Güneşte kızmı...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sasirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Nefesi', 'bahar-nefesi-banu-aka-car18', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne delice yağan yağmurlar 

Ne de bu apansız soğuk rüzgarın 

Sürüklediği gri bulutlar

Aldatamaz beni

Takvimler baharı gösteriyor 

Rüzgar yalanlasa da

Bahar geldi 

Tüm doğa uyanık 

Çiçek çiçek olmuş bembeyaz ağaç

Yeşil yeşil tütüyor bahar 

Gülümsüyorum

Yüreğim kıpır kıpır 

Kuşlar daha da mavi daha da özgür 

Baharın nefesi ile aşık olmak 

Bir başka türlü, dile gelmez 

Yine de

Bu güzelim bahar vakti 

Seni sevmemiş olmayı isterdim', 'Ne delice yağan yağmurlar  Ne de bu apansız soğuk rüzgarın  Sürüklediği gri bulutlar Aldatamaz beni Takvimler baharı gösteriyor  Rüzgar yala...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bahar-nefesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-banu-aka-bjd2p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen 

Uçsuz bucaksız mutluluksun

Kalbimi dolduran

Yaşama sevinci

Sen

Asla yitmeyecek umutlarımsın

Yediveren güller gibi

Sıcaksın

Hayallerimde

Sen 

Gözlerimde başlayan

Yağmursun 

Sağanak sağanak 

Sen

Sevdiğimsin

Ve hep böyle kalacak olan', 'Sen  Uçsuz bucaksız mutluluksun Kalbimi dolduran Yaşama sevinci Sen Asla yitmeyecek umutlarımsın Yediveren güller gibi Sıcaksın Hayallerimde...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-368-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-banu-aka-1r1jr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çiçekler nasıl açmış bir görsen 

Rengarenk bulutlar gibi 

Ürkek boyunları güneşe dönük

Selamlıyorlar herkesten önce sabahı 

Sultan küpeleri rüzgarla şarkı söylüyor 

Turuncu borazanlar eşlik ediyor onlara 

Gülümsüyor bembeyaz ortanca

Sevildikçe açıyor yediverenler 

Özlüyorum seni 

Özledikçe daha çok seviyorum seni 

Ipek çiçekleri kolkola zambaklarla 

Göz kırpıyor bana bir aslanağzı

Ve çekilirken güneş yavaşsa 

Susuyor o eşsiz melodi

Bir akşam sefası kaldırıyor başını 

Yaklaşan geceye 

Eflatun bir merhaba diyor

Ben seni hala özlüyorum 

Özledikçe daha çok seviyorum', 'Çiçekler nasıl açmış bir görsen  Rengarenk bulutlar gibi  Ürkek boyunları güneşe dönük Selamlıyorlar herkesten önce sabahı  Sultan küpeleri ...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ozluyorum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Sevmek', 'yeniden-sevmek-banu-aka-d53cj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çakırkeyifliğinde henüz sarhoşluğun

Uykuların en güzel mahmurluğunda

Kaçak yağmurlar altında sırılsıklam

Göz kırpan sarışın gün ışığında

En özgür, en pervasız

Bir kuşun bir kuşu sevdiği gibi

Seni –yeniden- sevmek

Ne güzel olurdu.', 'Çakırkeyifliğinde henüz sarhoşluğun Uykuların en güzel mahmurluğunda Kaçak yağmurlar altında sırılsıklam Göz kırpan sarışın gün ışığında En ...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yeniden-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Kaçma', 'artik-kacma-banu-aka-tc2jl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen durmadan kaç

El değmemiş ormanlara saklan

Adını duymadığım kuşlarla uç

Gökyüzünde kanat kanat

Bulutlarda uyu

Bilmediğim uzak memleketlere git

Tanımadık insanların arasına karış

Sen durmadan kaç

Denizlerin en derin yerlerine

Yengeçlerin yeşil gözlerine

İstridyenin koynuna saklan

Saklan papatyanın sarısına

Nergislerin kokusuna saklan

Güneş saklasın seni gündüzler boyu

Bir ömür sürsün 

Bu kovalamaca

Yorulursan eğer

Gel 

Yüreğime saklan

İstersen yine de bulmam seni

Bile bile nerede olduğunu

Ama 

Seni bir daha bırakmam', 'Sen durmadan kaç El değmemiş ormanlara saklan Adını duymadığım kuşlarla uç Gökyüzünde kanat kanat Bulutlarda uyu Bilmediğim uzak memleketler...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/artik-kacma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buldum', 'buldum-banu-aka-76rr7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşil kanatlı bir kuş varmış

Kimsenin bilmediği

Kimsenin göremediği

Kendi mavisinde uçan bir kuş

Nerelerde gecelediğini

Nasıl yaşadığını 

Hiç kimse bulamamış

Gökyüzü saklarmış onu 

Yeşil kanatlı kuş

Kendi mavisinde uçar dururmuş

Bulmalıyım ben onu 

İncitmeden kanatlarını

Avuçlarıma almalıyım 

Yüreğini

Ya da 

Öyle istemeli ki beni

Kendiliğinden gelivermeli 

Kollarıma

Kendi mavimizde uçalım diye

Hep aynı aşk ile', 'Yeşil kanatlı bir kuş varmış Kimsenin bilmediği Kimsenin göremediği Kendi mavisinde uçan bir kuş Nerelerde gecelediğini Nasıl yaşadığını  Hi...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/buldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Değil', 'benim-degil-banu-aka-lglwn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Avucumdaki bu ürkek kuş 

Peşinden delicesine uçtuğum kuş değil 

Yüreğimdeki akıl almaz sevgi 

Onun değil

Neden kondu avucuma ve uçmuyor 

Hem ürküyor hem kalıyor 

Kanatlarını kırmadan üfleyip

Uçurmalı

Hadi uç git kuş

Bu avuçlar sana ait değil

Bana da...', 'Avucumdaki bu ürkek kuş  Peşinden delicesine uçtuğum kuş değil  Yüreğimdeki akıl almaz sevgi  Onun değil Neden kondu avucuma ve uçmuyor  Hem...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/benim-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinden Gülümse', 'gozlerinden-gulumse-bekir-mutlu-gokcesu-v1m7q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ararken gülüşünü

Mevsimin birinde

Hatıraların sislerinde

Hüzne sararsa yolların

Ömrün bitiminde

Dudakların tükense de

Sen tükenme

Gözlerinden gülümse...

Aksi gibi ben de yoksam

Çok özlesen de

Sakın ağlama

Üzülme

Sana 

Şiirler yazacağım 

Tebessümler biriktireceğim

Seni beklediğim yerde...', 'Ararken gülüşünü Mevsimin birinde Hatıraların sislerinde Hüzne sararsa yolların Ömrün bitiminde Dudakların tükense de Sen tükenme Gözlerinde...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerinden-gulumse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevda ki Kimse Anlamaz...', 'bir-sevda-ki-kimse-anlamaz-cigdem-agbulak-fww5g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey çiçek

Kimse bilmez senin

Yerin göğün hakimi olduğunu

Görmezler

Her sabah sevdaya doğduğunu

Köklerin toprağa bağlı

Ama ben bilirim

Dünyayı herkesten iyi gördüğünü...

Günlerdir dilimde ismin 

Nereden bileceksin ki

Her sabah sana uyandığımı

Güneşi görmek için dirilen çiçekler gibi

Ve 

Yanımda olmasan da 

Soluduğum şehirde

Aldığım her nefesin bir köşesinde olduğunu...

Bu sabah bunları düşünerek uyandım. Önce derin derin seni çektim içime, sesini, kokunu, afranı, tafranı, bakışlarını doldurup cebime, pekte özenmeyerek üzerime (her zaman ki gibi)  kendimi bir otobüste buldum. Aslına bakarsan nereye gittiğimi bilmeden, yanıma azık diye bir seni alarak, galiba kaybolmak için yola çıktım.

Derin bir sevda bu kimse anlamaz

Ne aldıkları nefeste bilirler seni

Ne verdikleri can da

Bir ağacın dalları gibisin oysa

Ben rüzgarı beklerim

Kırılmadan dokunayım diye sana...

Bir vapurun dışında buldum kendimi. Ben bulup bulup kaybetmek için buradayım. Yolcular pek az, vapur tenha. Hava da bir şeylerin değiştiğine dair bir koku var, sen duymasan da. Biliyorum bugün daha bir sevdalıyım, kelimelerim hep aşka, noktalarım virgüllerim yani anlayacağın beni ben yapan yazdıklarım. Bugün her şey senin için var yürüdüğüm yollarda, gördüğüm yüzlerde, duyduğum seslerde. 

Tüm dünya sarıya boyanıyor

Kapattım gözlerimi

Deniz sarı

Gök sarı

Ne tuhaf uçan kuşlar

Esen rüzgar

Ellerim dillerim

Bir tek sen kırmızı

Nedenini bilmesen de 

Sen 

Her şeye benzemeyen...

Kapattım sarıya boyanmış gözlerimi. Vapur, dalgalı denizde kıyıya ulaştığında, bir iki yolcuyu sahile bıraktı. Henüz sabah, güneşsiz bir pazar sabahı. Rüzgarlı birde, boynum büküldü. Yalnızlık asıldı tırnaklarıma, söküldüğümü hissettim. Hızla koşan bir adam çarptı omzuma, sendeledim. 

Oysa

Ben sevdama gülümsedim

O yüzden

Yavaşladı adımlarım

O yüzden

Bu sabah

Bu uzun yürüyüşe tek başıma çıkışım...

Kabataş’a yürümeye yeltendi ayaklarım, sonra vazgeçtim. Yeni Caminin minarelerini görüp, köprüye doğruldu adımlarım. Eski köprü geldi aklıma, birazda çocukluğum. İnsanlar oltalarını alıp, umutlarını takıp kancalara salmışlar suya. Yavaş yürüyüşüm, hayatı kaçırmamak için ellerimden ve ben seninle yürüdüm. 

Bir kahkahanın acısı yayıldı yüzüme

Gözlerin “dur” dedi

Gülümseme

Seyret sadece...

Bende öyle yaptım, seyrettim sadece 

Bir olta çekildi sudan 

Ucunda küçücük bir istavrit 

Henüz yeni başlamıştı hayata

Tecrübesizliğine yenilip aldanmıştı

Ucunda yem olan oltaya

Ağladım sessizce

Yapışıp adamın ellerine 

“bırak, henüz çok küçük” diyemedim 

Çevirdim başımı, daldım usulca

Ellerim ısındı niye bilmem

Tenini hissettim birden

Sabah sabah bu köprü

Amma anıyı canlandırdı

Çok uzaklarda...

Bir güvercin kanat çırptı acıyla 

Tasası beni aldı

Hangi yoldan gitmeliyim 

Bir tarafım adı yok deniz

Bir tarafım batık bir gemi

Sancağına dolanan yosunlara daldım

Köprü bitti

Ben bittim

Küçük bir istavritin

Denize olan aşkı bitti...

(19.04.2004 / 14:57)', 'Ey çiçek Kimse bilmez senin Yerin göğün hakimi olduğunu Görmezler Her sabah sevdaya doğduğunu Köklerin toprağa bağlı Ama ben bilirim Dünyayı...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Ağbulak']::text[], 8.5, '{"poet":"Çiğdem Ağbulak","poet_slug":"cigdem-agbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/bir-sevda-ki-kimse-anlamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmek Zamanı', 'vazgecmek-zamani-nezaket-tezcan-fupzt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceden daha karanlık yüzler,

Ne yıldızlar yanar gözünde, ne de ay parlar yüzünde 

“Seni seviyorum”  lar  sakız gibi ağızlarda

Kalp dil bir değil, göz görmez tenden ötesini

El başı boş kurşun gibi, kuru sıkı her bedende

Dudak ayırt etmez al yanağı gül dudağı, bir yataklık “Seni Seviyorum” larda

Geceden daha karanlık kalmış yüzler,

Ne yıldızlar yanar gözünde, ne de ay parlar yüzünde 

Zaman Vazgeçmek zamanıdır; canından, cananından... 

Ardına kadar aç kapıları, buyursun içeri devrin büyütülmüş yalanları.', 'Geceden daha karanlık yüzler, Ne yıldızlar yanar gözünde, ne de ay parlar yüzünde  “Seni seviyorum”  lar  sakız gibi ağızlarda Kalp dil bir ...', ARRAY['Türk Edebiyatı','Şiir','Nezaket Tezcan']::text[], 8.5, '{"poet":"Nezaket Tezcan","poet_slug":"nezaket-tezcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vazgecmek-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baldız', 'baldiz-hifzi-ozbekmez-sbmtz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sormadın sen hiç hal hatır

Yazdın zehir gibi satır

Ispanağı kıtır kıtır

Yedirdin sen bize baldız

Dedik ki ıspanaklı börek

Dedin ki sen neme gerek

Cezamız ne bizde bilek

Söylemedin bize baldız

Kalemim var dosta yaza

Gelemem ben böyle naza

Tem yolunda bize kaza

Yaptırdın sen bize baldız

Latifi yapmışsa gafı

Diliyor özürü afı

Olur olmadık her lafı

Kondurdun sen bize baldız

02 Nisan Saat:13.00', 'Sormadın sen hiç hal hatır Yazdın zehir gibi satır Ispanağı kıtır kıtır Yedirdin sen bize baldız Dedik ki ıspanaklı börek Dedin ki sen neme ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baldiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menşei Yalnızlık', 'mensei-yalnizlik-mustafa-tanrikulu-71ohp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'menşei yalnızlıktır kederimin...

bir ilkbahar gecesinin serinlik kokan havası

eski günleri, eski aşkları, eskileri hatırlattıkça

şimdiki yalnızlığıma hayıflanıyorum 

ve yeni baştan

kal u beladan başlayarak her şeye 

yanıyorum...

kâtipler kamışlarını Habil''in kanına batırdılar

ve yazmaya başladılar aşıkların kaderini...

Mecnű n dediler karşısına Leylâ yazdılar

Ferhat diye bir lâle nakşettiler,

Şirin''in kanıyla boyadılar...

Sonra Kerem yazdılar, Mem yazdılar,Cem yazdılar

Aslı dediler sonra, sonra Zîn sonra vatan...

Mustafa diye kalemler oynadığı gün

İbrahim ateşteydi...

Kâtipler telaştaydı; 

Nur yazacakları yerde nar yazdılar,

Attığı adım aldığı nefes zarar yazdılar

Hayatında her gün dert var yazdılar

Belayı biçareye yar yazdılar

Nur yazacakları yerde nar yazdılar

menşei yalnızlıktır kederimin...

bir ilkbahar gecesinin serinlik kokan havası

eski günleri, eski aşkları, eskileri hatırlattıkça

şimdiki yalnızlığıma hayıflanıyorum 

ve yeni baştan

kal u beladan başlayarak her şeye 

yanıyorum...', 'menşei yalnızlıktır kederimin... bir ilkbahar gecesinin serinlik kokan havası eski günleri, eski aşkları, eskileri hatırlattıkça şimdiki yal...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mensei-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca İllez', 'koca-i-llez-nezaket-tezcan-m19uf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nisan''ın 19''u. 

Üşümüş  toprağa ılık yağmurun düştüğü gün,

Sen de düştün toprağa

En güzel haliyle geldi Azrail; Yağmur kadar temiz, nisan kadar neşeli

Çiçek açtı yüzün,  gün doğmamıştı daha. Ve Nisan''ın 19'' unda, düştün toprağa

Acılarını bilmeden, acımız oldun. Kaldırdık seni tozlu raflara en güzel halinle

Aldım sahipsiz kalan kasketini;  her zaman ki gibi takamadım başıma,

Yorgun, acılı bedeninin kokusu sinmiş, silinmesin senin izin 

Kızgın gülümseyen yüzünü göremedim, İlk kez bakmadın bana, bakamadın

Son uykuna daldın işte, gecemize iyilik dilemeden

Gecemizi gün eylemeden, nefesin tükendi, meyveye döndün

Seni de yıktı ya ölüm

Koca elli, koca yürekli Koca İllez, Kocamış İllez.', 'Nisan''ın 19''u.  Üşümüş  toprağa ılık yağmurun düştüğü gün, Sen de düştün toprağa En güzel haliyle geldi Azrail; Yağmur kadar temiz, nisan ka...', ARRAY['Türk Edebiyatı','Şiir','Nezaket Tezcan']::text[], 8.5, '{"poet":"Nezaket Tezcan","poet_slug":"nezaket-tezcan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/koca-illez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıla''ma', 'sila-ma-seda-atasoy-8cj4e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırlarım ilk selam deyişini dünyaya.

Gülücük saçan o minnacık dudaklarla.

Sarı saçların en buklelisi sana! 

Yeşil gözlerin en harelisi Sıla''ma.

Hatırlarım ilk anne deyişini bana.

Cana can katan o unutulmaz sesin hala kulağımda.

Bebeklerin en cilvelisi sana! 

Evlatların en güzeli Sıla''ma!', 'Hatırlarım ilk selam deyişini dünyaya. Gülücük saçan o minnacık dudaklarla. Sarı saçların en buklelisi sana!  Yeşil gözlerin en harelisi Sıl...', ARRAY['Türk Edebiyatı','Şiir','Seda Atasoy']::text[], 8.5, '{"poet":"Seda Atasoy","poet_slug":"seda-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sila-ma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lelo''ma', 'lelo-ma-seda-atasoy-iwicy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Lelom,balım bal kızım.

Baldan tatlı can özüm.

Sırma saçlım yosun gözlüm.

Neşem dertortağım övüncüm.

Lelom,canım can kızım.

Sırdaşım öğretmenim meleğim.

Hasretim özlemim bebeğim.

Tutkumsun sen bir tanecik Selen''im.', 'Lelom,balım bal kızım. Baldan tatlı can özüm. Sırma saçlım yosun gözlüm. Neşem dertortağım övüncüm. Lelom,canım can kızım. Sırdaşım öğretmen...', ARRAY['Türk Edebiyatı','Şiir','Seda Atasoy']::text[], 8.5, '{"poet":"Seda Atasoy","poet_slug":"seda-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lelo-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin.', 'bilirmisin-seda-atasoy-0d1rn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlık nedir bilirmisin.

Sen hiç yalnız kaldınmı? 

İçini ısıtan bir nefes nedir bilirmisin.

Sen hiç nefessiz kaldınmı? 

Sensizlik nedir bilirmisin.

Sen hiç  sensiz kaldınmı? 

Kaldınmı söylesene can kaldınmı...

Sen tüm bu acıları yaşadınmı?', 'Yalnızlık nedir bilirmisin. Sen hiç yalnız kaldınmı?  İçini ısıtan bir nefes nedir bilirmisin. Sen hiç nefessiz kaldınmı?  Sensizlik nedir b...', ARRAY['Türk Edebiyatı','Şiir','Seda Atasoy']::text[], 8.5, '{"poet":"Seda Atasoy","poet_slug":"seda-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilirmisin-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pan Flüt Çetesi', 'pan-flut-cetesi-osman-olmus-hgmkd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sokak kavgalarında hep dayak yedim ağbisizlikten

ekmek almaya bile gidemezdim çeteye girmesem

sustalıyı çekemezdim öyle şak diye şakaktan

faça atmayı bilmediğimden hep faka basardım

kimle dalaşsam: sonunda çalıyı dolaşan yine ben

 			             -çelimsizlikten: bana müsaade-

ah! bir kere çamura düşürülmeden dönebilsem eve

asla girmezdim çeteye; çember çevirmenin dışında

bir keyif olduğunu bilmezdim çocukluğun: hep kavga

içinde büyüdüğüm sokaktan başka: arka çıkan yoksa

				                   -ağbisizlikten: bana müsaade-

kardeşim orhan ve once upon a time in america

pan flütüyle başlayan o buhran: bir bilet lütfen

tren daha kalkmadan nasılsa geçmiş tutar elimden

ah! lunaparka gidemediğimiz yıllar: bir coca-cola

kapağından çıkan plastik topla: patlar ilk tokat

izi hâlâ yanağında.olsun üzülme, ben varım ya! 

			 -artık kimse dokunamaz sana-

bir sürü bilet alacağım hem de çarpışan otolara

			        güz bahçesi’91/ankara

			        Osman OLMUŞ', 'sokak kavgalarında hep dayak yedim ağbisizlikten ekmek almaya bile gidemezdim çeteye girmesem sustalıyı çekemezdim öyle şak diye şakaktan fa...', ARRAY['Türk Edebiyatı','Şiir','Osman Olmuş']::text[], 8.5, '{"poet":"Osman Olmuş","poet_slug":"osman-olmus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/pan-flut-cetesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehmetçiğim Ben', 'mehmetcigim-ben-ozer-sutcu-ydhdd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beşyüzelli gün yokum aranızda

Vatana olan borcumu ödemeye gidiyorum

Hiç düşünmeden ülkemin uğurunda

Gözümü kırpmadan ölmeye gidiyorum

Terör ve eşkiya korkutamaz beni

Yurdum uğurunda seve,seve ölürüm

Kurşunlar delikdeşik etsede bedenimi

Ben yinede onların üstüne yürürüm

Korkmam ölümden sonunda şehitlik var

Peygamberimin müjdesine koşarım

Şu fani dünyada ebedi ne var

Şehit olur ebedi mutlu yaşarım

Bilirim en büyük borç vatanı korumak

En büyük görev bunu bilirim

Gurur verir bana şehit olmak

Korkmadan düşmanın üstüne giderim

Korksun eşkiya benden mehmetçiğim ben

En zor şartlarda görevimi yaparım

Benim için vatan önce gelir herşeyden

Eşkiyalar dünyayı başınıza yıkarım

Bu vatanı sahipsizmi sandınız

Vatanı uğurunda ölecek milyonlarca yiğit var

Bizi tanımamakla büyük yalnış yaptınız

Bu dünyayı size dar ederiz dar....', 'Beşyüzelli gün yokum aranızda Vatana olan borcumu ödemeye gidiyorum Hiç düşünmeden ülkemin uğurunda Gözümü kırpmadan ölmeye gidiyorum Terör ...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mehmetcigim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme ana', 'uzulme-ana-ozer-sutcu-jm41q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün kör kurşun benide bulursa

Eğer ki canı bedenden ayırırsa

Allah diyerek bir asker yıkılırsa

Üzülme ana dua et bana

Şehit olmak şereftir bize 

Dua ette gelmeyeyim göze

Korkma düşman gelecektir dize

Üzülme ana duğa et bana

Kaderde şehitlikte varsa

Dünyadaki vaktim dolduysa 

Alnıma şehit olacak yazıldıysa

üzülme ana dua et bana

Herkese nasip olmaz şehitlik

Yıllarca vatan için can verdik

Gururluyum alnım ak başım dik

Üzülme ana dua et bana', 'Bir gün kör kurşun benide bulursa Eğer ki canı bedenden ayırırsa Allah diyerek bir asker yıkılırsa Üzülme ana dua et bana Şehit olmak şereft...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzulme-ana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluyum, Mutluyum, Mutluyum', 'mutluyum-mutluyum-mutluyum-halil-kesken-vq42s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimdeki yaşları kurutana kadar ağlatmaya kararlı gibisin...? 

Ama boşa gidecek bütün çabaların,

Çünkü ben artık ağlamayı bulutlara; 

Sevmeyi Mecnun’a, Ferhat’a, Kerem’e

Hasreti ayrı düşmüş karşılıklı sevenlere

Seni de umutsuz umutlara bıraktım.

Hiç arkama dönüp bakmıyorum günlerdir

Çünkü burada unutmuş gibi bıraktığın tüm eşyalarını yaktım.

Onlarla birlikte kalbimdeki aşkta kül oldu

Uzun sürdü güzelim, ama en sonunda unuttum

Gözlerinin ne renk olduğunu bile hatırlamıyorum artık

Sakın bunları sarhoşken yazdığımı düşünme

Ağzıma hiç içki sürmediğimi bilirsin

Zaten senden sonra değişmeyen tek şey bu

Asık suratımın yerini mükemmel gülücükler,

Ağlayan gözlerimin yerini ışıl ışıl bakışlar,

Kalbimdeki yerini ise bir başkası aldı

Kendime nasıl şaşırıyorum bilemezsin

Hayatımda ilk defa eski aşkımı aldatmış gibi hissetmiyorum

Başın sağolsun ve teşekkür ederim

Öldürdün eski Halil’i

Mutluyum, mutluyum, mutluyum', 'Gözlerimdeki yaşları kurutana kadar ağlatmaya kararlı gibisin...?  Ama boşa gidecek bütün çabaların, Çünkü ben artık ağlamayı bulutlara;  Se...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mutluyum-mutluyum-mutluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp', 'kayip-melek-midikoglu-bij36', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bize birgün yetmezmiş

Kur kurabilirsen

Yılı doldurduk yolda

Dur durabilirsen

Kara karaya düşermiş

Karardım durdum

Denize attım yelkenini

Gel gelebilirsen', 'Bize birgün yetmezmiş Kur kurabilirsen Yılı doldurduk yolda Dur durabilirsen Kara karaya düşermiş Karardım durdum Denize attım yelkenini Gel...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kayip-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yürek Öldü', 'bir-yurek-oldu-salih-ozalasan-bu47n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yürek öldü

Can vermeden Azrail’e

Bir beden çürüdü

Daha konmadan kabrine

Bir güneş battı

Daha ufukta parlamadan

Bir yıldız kaydı

Semada yerini almadan

Candı canandı 

Bu güne ermeden

Bir tatlı gülüşe kandı

Gülmek nedir bilmeden

Hani derler ya

“Mezara kondum daha ölmeden”

Bedenin yüreğe isyanı

Bir acı gülüş kaldı bu sevgiden

Y.Tarihi 19-04-04 Saat 17-50

Salih ÖZALAŞAN', 'Bir yürek öldü Can vermeden Azrail’e Bir beden çürüdü Daha konmadan kabrine Bir güneş battı Daha ufukta parlamadan Bir yıldız kaydı Semada y...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-yurek-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm', 'kordugum-bulent-ahmet-alp-ddpwe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutlarımdı ufuğa gidecek gemi...

Sevinçler dalgalardaki sessiz bir köpük,

Biliyorlar kendilerini bekleyeni...

Mutluluklar kalmadı,çünkü hepsi sönük...

Hayat bir ayna; ne cam olabildim ne sır...

Arada sıkıştım kaldım,çıkamıyorum.

Hep burada yaşamışım  bilmem kaç asır? 

Neleri yaptım,neleri yapamıyorum? 

Kaldır kafanı bak! İşte sana gökyüzü...

Sonra aynaya bak gördüğün bir gariban...

Yatağında ''yapamadım'' oldu son sözü...

Kim kurtaracak seni kim! Hangi kahraman? 

Hep üzerime gelir sessizce geceler...

Hiç sığınacak kimsem yok,sığınamam ben...

Sanıyorum bu yüzleşmediğim gerçekler...

Soğur birden vücut,yayılınca ensemden...

Çektiğim her nefesin vardır bir sebebi.

Anlamsızdım.Ruhum ayrılırken bedenden...', 'Umutlarımdı ufuğa gidecek gemi... Sevinçler dalgalardaki sessiz bir köpük, Biliyorlar kendilerini bekleyeni... Mutluluklar kalmadı,çünkü hep...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ahmet Alp']::text[], 8.5, '{"poet":"Bülent Ahmet Alp","poet_slug":"bulent-ahmet-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kordugum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldür Öyle Git', 'oldur-oyle-git-i-lyas-ozmen-xec1g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Demek ki gidiyorsun

Anlamsız bir vedayla

Sanma ki ben yaşarım

Kanayan bu yarayla

Çek üstünden elini 

Bırak yaram kanasın

Damarımda sen diyen

Bir damla kan kalmasın

Silinsin hatıralar 

Anılar anılmasın 

Sök kalbimi de götür

Senden eser kalmasın

Şiirlerim yas tutsun

Şarkılarım ağlasın

Resimleri yakalım

Seni hatırlatmasın

Kıralım saatleri

Takvimleri yırtalım

Unutalım geçmişi

Yaşamamış olalım

Git gidersen böyle git

Üzerime basarak

Arkanda eser diye 

Bir ceset bırakarak', 'Demek ki gidiyorsun Anlamsız bir vedayla Sanma ki ben yaşarım Kanayan bu yarayla Çek üstünden elini  Bırak yaram kanasın Damarımda sen diyen...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oldur-oyle-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgım Sana Dair', 'yanilgim-sana-dair-goktu-kara-d3akh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mırıldandım seni günlerce yağmurun altında

akşam yatıyorum,sabah kaçıyorum dilimde

tarlalar uçsuz bucaksız göğsünde

ne saçma şeyler bu yurt seslenişleri

Kıbrıs güvercinleri martılarla dans ederken

balıklar sularda ne gezer çıkarsınlar artık başlarını

uyansınlar sevgilim

uyansınlar senin için 

bazen düşünüyorum da en güzel şey seni yurdumla 

düşünmek

sen ve yurdum

güzelsin be', 'mırıldandım seni günlerce yağmurun altında akşam yatıyorum,sabah kaçıyorum dilimde tarlalar uçsuz bucaksız göğsünde ne saçma şeyler bu yurt ...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanilgim-sana-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antilop', 'antilop-yusuf-kemal-metin-0brzy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ağrıyor

beynimin senli doruklarında

son serseri kurşunla

       vurulan

doğurgan başım.

sessiz çığlığın 

yağarken

durağan vadilerime

umarsız sekiyorsun

kristal gözlerimin

utanç siperlerinde

            antilop

batıp etine dünyanın

gömülürken kendine evren

kutupta şaşkın palmiye

yitik iklimine

yön ararken

ağarıyor

 ve

ağlıyor

yalımı ak 

utangaç 

korkak kara güneş

kaçıyor 

evrenin kara deliklerine

   sen gene de 

yeşil kansız 

bulutlar vadisindesin 

            antilop

sığmıyor sonsuzluk sonsuzluğa

çırpınıyor zaman

zamanın nurlu bataklığında

ağaçlar

yaprak yaprak dökülürken

     yalnızlık toprağına

ürkekçe savrulurken sen

bir sen

            en önde 

çatlayan 

yediveren 

inadına yeşeren

dirimsel umutlar

bende

antilop

haydi

çılgınca sevişme vakti şimdi

dök sonsuzluklarıma

çöl bozan

          yıldız tozan

dök dökebildiğince

                     dirim tohumlarını

çığ değil 

çağ düşür gönlüme antilop.', 'ağrıyor beynimin senli doruklarında son serseri kurşunla        vurulan doğurgan başım. sessiz çığlığın  yağarken durağan vadilerime umarsız...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kemal Metin']::text[], 8.5, '{"poet":"Yusuf Kemal Metin","poet_slug":"yusuf-kemal-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/antilop-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek işi', 'sevmek-isi-engin-ozcan-eex5y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'inadına asılmaktı hayata seni sevmek işi,

yüreğimin aşı,

damarlarımdaki her damla kan,

ve alnımın teri,

ve ocakta dumanı tüten çayın tadı,

ve yorgunluğum,uykum,

ve inadına yenilmekti,

baskın yemiş bir ordu gibi. 

kuşatılmaktı seni sevmek.

yenilmekten korkmadan yürümek ölüme ve zamana karşı..

inadına yaşamaktı seni,

seni sevmek işi..

kalkanları kırılmış bir şövalye haykırışı...

aşkın gürzünü kalbine inmiş hissetmekti..

Engin ÖZCAN

18-04-2004

İstanbul', 'inadına asılmaktı hayata seni sevmek işi, yüreğimin aşı, damarlarımdaki her damla kan, ve alnımın teri, ve ocakta dumanı tüten çayın tadı, v...', ARRAY['Türk Edebiyatı','Şiir','Engin Özcan']::text[], 8.5, '{"poet":"Engin Özcan","poet_slug":"engin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevmek-isi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abidin Ağa', 'abidin-aga-eren-sahin-2mgbr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ava gider,avlanır gelir

Vurur kuşu,tilkiyi...

Elinde tüfeği varken,

Kim tutar Avcı Abidin''i

Ramazan''da tepelerde 

İftar topu patlatır; 

Kurt mu vurur,kuş mu vurur bilmem ama

Bu şiiri bir duyarsa 

Benim gözümü patlatır...', 'Ava gider,avlanır gelir Vurur kuşu,tilkiyi... Elinde tüfeği varken, Kim tutar Avcı Abidin''i Ramazan''da tepelerde  İftar topu patlatır;  Kurt...', ARRAY['Türk Edebiyatı','Şiir','Eren Şahin']::text[], 8.5, '{"poet":"Eren Şahin","poet_slug":"eren-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/abidin-aga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittiğinden Beri', 'sen-gittiginden-beri-ercan-uracin-qmuuc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen giitiğinden beri çıkmadım sokağa

koklamadım fesleğenleri

ve de en önemlisi sulamadım sevdiğim çiçeğim

yasemini 

sen giitiğinden beri isyan ettim yalnızlığıma

hep üşüdüm geceleri

sen diye giyindim yalnızlığı

ve uyudum geceleri

sen giitiğinden beri

unutmak istedim seni

ama nafile unutamadım

çünkü

fesleğenlerin kokusu hala burnumda

yalnızlığın hala yatağımda uzanmakta

yasemin çiçeğim balkonumda uzanmakta

ve de en önemlisi 

sense hala kalbimdesin', 'Sen giitiğinden beri çıkmadım sokağa koklamadım fesleğenleri ve de en önemlisi sulamadım sevdiğim çiçeğim yasemini  sen giitiğinden beri isy...', ARRAY['Türk Edebiyatı','Şiir','Ercan Uraçin']::text[], 8.5, '{"poet":"Ercan Uraçin","poet_slug":"ercan-uracin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gittiginden-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebruli', 'ebruli-sabahittin-kurtoglu-kz0ya', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kaneviçe işledim

gökyüzüne

ilmik ilmik

ebruli döktüm

ege`ye

hava

günlük güneşlik

uzat elini şipiros

uzat elini

uzo raki

dolma dolmaki

çalsın buzuki

oynayalım

çiftetelli sirtaki

hava

günlük güneşlik

gökyüzü

ilmik ilmik

kaneviçe

ege

her tarafı

ebruli

uzat elini

eleni

uzat elini', 'kaneviçe işledim gökyüzüne ilmik ilmik ebruli döktüm ege`ye hava günlük güneşlik uzat elini şipiros uzat elini uzo raki dolma dolmaki çalsın...', ARRAY['Türk Edebiyatı','Şiir','Sabahittin Kurtoglu']::text[], 8.5, '{"poet":"Sabahittin Kurtoglu","poet_slug":"sabahittin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ebruli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oynatmayalım Uğurcuğum / deneme', 'oynatmayalim-ugurcugum-deneme-k-muran-esen-w78o1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Futbola çok meraklıyım. Bir bayan olarak futbola olan bu – belki de aşırı - merakım bazılarını şaşırtır bile. Şaşırmaları, futbolun erkek oyunu olmasından kaynaklanıyor sanırım. Oysa ki ben,  bayan mankenlerin sunduğu mayo defilelerine erkeklerin daha fazla ilgi gösteriyor olmalarına hiç şaşırmam. Her neyse, ben konuya döneyim.

            Futbol maçlarını izlemeyi çok severim sizin anlayacağınız. Süper lig maçlarını izlerim. Avrupa liglerinin, televizyonda yakalayabildiğim tüm maçlarını izlerim.Tabii ki, milli maçları hiç ama hiç kaçırmam. Bunlarla da yetinmem, maçların yorumlarını da izlerim.

               Yorumları izlerken; maçları yorumlayanların, top koşturan futbolculardan daha fazla yorulduklarını(!)   düşünürüm. Maçtan önce, olasılıklar üzerinde konuşurlar. Maç sırasında konuşurlar. Maç sonrası da izledikleri futbol hakkında konuşurlar. Futbolcuları, teknik kadroyu, yöneticileri, hakemleri eleştirirler de eleştirirler. Ya da bazılarını göklere çıkarırlar.Bunları dinlerken şaşırırım bazen. Hani maçı izlemesem, neyse.Sanki benim izlediğim maç başka, onların yorumladığı maç başka bir maçmış gibi gelir. Bu kişilerin işi bu, eleştirmeleri doğal. Ama bazen, bazılarının çizmeyi çok aştıklarını düşünürüm. Nasıl mı? Bakın anlatayım:

           Bu yorumcular, maça ait görüntülerden yararlanırlar yorum yaparken. Bir takımın diğer takıma attığı golün ofsayt olup olmadığını anlamak için, defalarca görüntüyü izlerler. Ama golün ofsayt olup olmadığına bir türlü karar veremezler. ”Oynatalım Uğurcuğum! ” derler, görüntü tekrarlanır. Sonra bir daha bir daha. “Bir de  ofsayt kamerasından izleyelim,” derler.Bir kez daha izlerler.Üstelik genelde maçı stadyumda izlemişlerdir. Ancak izledikleri yerden, hakemin kararının doğru olup olmadığına karar verememişlerdir.Yorum yaparken, görüntüleri defalarca izledikleri halde ne  “ofsayt”  diyebilirler ne de  “ofsayt değil”.  Sonra   “Bir de ofsayt kamerasından izleyelim,''  derler.Ve kararlarını ancak öyle verebilirler.

            Mazaallah, geçerli sayılan gol eğer ofsaytsa, hakemi yerden yere vururlar. Saniyede karar vermek zorunda olan hakemin hata yapabileceğini düşünemezler, düşünmek istemezler. ”Biz, görüntüleri defalarca izledikten sonra ancak karar verebildik. Hakem ne yapsın! Hakemlerin, bizim gibi görüntüleri geriye alıp pozisyonu yeniden değerlendirme şansları yok. Onların bir Uğurları, İsmailleri yok,''  demezler.

           Elbette ki hakemlerin, yorumcular gibi, görüntüyü tekrar tekrar izlettirecek bir Uğurları yok, ofsayt kameraları yok. Sevgili yorumcular! ... Bırakın şu, yok  “Oynatalım Uğurcuğum”,  yok  “Başa dön.” yok  “Bir de kale arkasından izleyelim”, yok “ Ofsayt kamerasının görüntülerini izleyelim,''  lâflarını. Siz de, aynı hakemler gibi ilk izleyişte karar verin bakalım. Bir defa olsun;  “Oynatmayalım Uğurcuğum oynatmayalım. Ben ilk izleyişte, bakalım karar verebilecek  miyim, ofsayt var mı yok mu? ”  sorusunu sorun kendinize.

            Haydi bakalım! Uğurcuğunuz tekrar tekrar oynatmasın da, göreyim sizin kararınızı. Hiç hatasız maç yönetmek o kadar kolay mıymış, anlarsınız o zaman.Görüntüler önünüzde, ekranda size “sus” diyen de yok.,suçladığınız kişi orada yok.Yani tüm olanaklar elinizde ve akan sular hep sizden yana. Eeeeeee!  Ne demiş atalarımız: ”Ağa güçlü olunca, maraba (ya da “kul”)   suçlu olur.

            Oynatmayalım Uğurcuğum, oynatmayalım. Ki görelim yorumcuların yorumunu. Bakalım; “ Turp elle mi çıkıyormuş yoksa belle mi? ”', 'Futbola çok meraklıyım. Bir bayan olarak futbola olan bu – belki de aşırı - merakım bazılarını şaşırtır bile. Şaşırmaları, futbolun erkek oy...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oynatmayalim-ugurcugum-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amonyaklaştım', 'amonyaklastim-sabahittin-kurtoglu-hn6ag', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mantığımı dörde böldüm

yarısını denize attım

biriyle düşünürken

amonyaklaştım

ötekiyle yetinmek

zorunda kaldım

karekök

pi sayısı derken

formülleri karıştırdım

bir an matematikten

uzaklaştım

fizik jeolojı

antropolojı

astrolojı derken

atmosferin

dışına çıktım

yıldızları dolaştım

aklım karıştı

mantıksızlaştım', 'mantığımı dörde böldüm yarısını denize attım biriyle düşünürken amonyaklaştım ötekiyle yetinmek zorunda kaldım karekök pi sayısı derken form...', ARRAY['Türk Edebiyatı','Şiir','Sabahittin Kurtoglu']::text[], 8.5, '{"poet":"Sabahittin Kurtoglu","poet_slug":"sabahittin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/amonyaklastim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığır', 'cigir-ahmet-aksoy-i8cum', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yalnızlığın esrarında gizlenen mana

aşk para ve siyaset

herkes aşık olur

...ve yaşar çoğunluk paraya hasret

her şeyin ve seksinde siyaseti olur

yalnızlık akar içinde varlığın

kimse kimseyi çoğaltamaz kimsesizliğinde

ve yaşar insan çığırında menfaat.', 'yalnızlığın esrarında gizlenen mana aşk para ve siyaset herkes aşık olur ...ve yaşar çoğunluk paraya hasret her şeyin ve seksinde siyaseti o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cigir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarın Aşkı', 'ruzgarin-aski-sabahittin-kurtoglu-daw75', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o gün yorgun argın gelince

eve

atıverdim kendimi

döşeğin üzerine

tez dalmışım

düşümde bir rüzgar gördüm

toroslar`ın tepesinde

karadeniz`den geliyormuş

gidecekmiş akdeniz`e

sanki demli çay tortusu vardı

genzimde

sordum``bu acelen ne``

yetişmeliymiş güneyden gelen

sevgilisine

şimdi kavrulmuştur

çöl sıcaklarından

sarılmalıymış

kum bulutlu bedenine

serinletmeliymiş

ve de bir öpücük kondurmalıymış

terine

bayılmadan düşmeden denize

ağaçların yaprakları

bir o yana

bir bu yana düşercesine

güle güle diyorlardı

rüzgarın hasret dolu gidişine

ve

takılmıştı toroslar`ın

kekik kokuları peşine', 'o gün yorgun argın gelince eve atıverdim kendimi döşeğin üzerine tez dalmışım düşümde bir rüzgar gördüm toroslar`ın tepesinde karadeniz`den ...', ARRAY['Türk Edebiyatı','Şiir','Sabahittin Kurtoglu']::text[], 8.5, '{"poet":"Sabahittin Kurtoglu","poet_slug":"sabahittin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ruzgarin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-ozan-kiratli-zana6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önceleri sadece uykularda gördüğümü sanırdım...

Ama sonraları gerçeği anladım...

Meğer gerçeğin ta kendisiymiş ''Rüya''...', 'Önceleri sadece uykularda gördüğümü sanırdım... Ama sonraları gerçeği anladım... Meğer gerçeğin ta kendisiymiş ''Rüya''......', ARRAY['Türk Edebiyatı','Şiir','Ozan Kıratlı']::text[], 8.5, '{"poet":"Ozan Kıratlı","poet_slug":"ozan-kiratli","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ruya-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördügüm', 'kordugum-erol-dal-jx4yh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kim O? 

Böyle vakitsiz çalan kapımı; 

Alacaklı mı yoksa

İnsafsızca vuran durmadan…

Kim O? Böyle ısrarla çalan zilimi

Sevgili mi yoksa 

Hasretle tutuşan...

Kim O? 

Böyle saygısız, 

Böyle cür''etkâr

Kim acaba? 

Bence ölüm

Her gece gördüğüm

Çözülme vakti gelmiş

KÖRDÜĞÜM', 'Kim O?  Böyle vakitsiz çalan kapımı;  Alacaklı mı yoksa İnsafsızca vuran durmadan… Kim O? Böyle ısrarla çalan zilimi Sevgili mi yoksa  Hasre...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kordugum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karafaki', 'karafaki-ahmet-aksoy-3jgi7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'uzayan gecelerinde ömrün

gölge bir karabasandır

dikilir ardında gövde

sanki dişleri kan çanağıdır

ve tutturmuştur bir türkü dilinde

ellerim sıkar gırtlağını karafaki

..............dostum değil misin', 'uzayan gecelerinde ömrün gölge bir karabasandır dikilir ardında gövde sanki dişleri kan çanağıdır ve tutturmuştur bir türkü dilinde ellerim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/karafaki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyorsun', 'yuruyorsun-erol-dal-e3xtu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürüyorsun..

Bakan bir daha bakıyor

Ardından.

Bakanlar sana küfr ediyor….

Ben; 

Baş bakana….

1982/Mekan', 'Yürüyorsun.. Bakan bir daha bakıyor Ardından. Bakanlar sana küfr ediyor…. Ben;  Baş bakana…. 1982/Mekan...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuruyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yolcusuna...', 'ask-yolcusuna-i-brahim-ethem-bingul-kvr7u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey yolcu garip dostum

Benim yol arkadaşım

Taşıdığın yük senin

Sahibisin dertlerin

Yollar uzun bir çizgi

Sen hep yürüyeceksin

Senin yürümen için

Önce nefes al derin

Yürümek aşka doğru

Yürürken ne acı duy

Aşka aşkınla yürü

Ve ne de özle dünü

Yürümek yol açmaktır

Dağı tünel yapmaktır

Yürümek bir savaştır

Barış uğruna cenktir

Elbet yorulacaksın

Az dinlen nefes al

Sonra yine koyul yola

Bekleyenin var durma

Hedefe varacaksın

Güzel yürürsen yolda

Aşıksan aşk yolunda

Güleceksin sonunda...', 'Ey yolcu garip dostum Benim yol arkadaşım Taşıdığın yük senin Sahibisin dertlerin Yollar uzun bir çizgi Sen hep yürüyeceksin Senin yürümen i...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-yolcusuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*-* GÜZELLiĞiNDE...', 'guzelliginde-baki-son-p0fm8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamın...

En güzeline rastladım,

......................../ Sende..! 

Mutluluk büyüyordu

Bir bebek gülüyordu

......................../ Güzelliğinde...

Utanmak...

Bir kat daha yakıştı

......................../  Esmerliğine

Yanağında pembe renk

Bir başka gülüyordu

Bir gül büyüyordu

......................../ Güzelliğinde...

Mutluluğun...

Doruğuna eriştim sende

......................../ Sıcaklığında,

Canlılık büyüyordu,

Yaşamak yürüyordu

......................../ Sende..! 

Hayat ve yaşam gülüyordu

......................../ Güzelliğinde...', 'Yaşamın... En güzeline rastladım, ......................../ Sende..!  Mutluluk büyüyordu Bir bebek gülüyordu ......................../ Güzel...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guzelliginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-baykal-kaanalp-u4vd6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aslında yoktu hiç sebep

seni düşünmem için bu gece

yokluğun özlemimi artırmıyordu bile

ama eksiltmiyordu da

bazı anlarda iştahla sarılıyordum

kaleme

ama birtek çizik bile atmıyordu

deftere

defter aşık

belli etmemek için çok sıkıyordu kendini

kalemin umrunda bile değil bir çizik

eksik atmış,bir harf fazla yazmış

aslında yoktu hiç sebep

sana yazmam için bu gece

hasretin içimi yakmıyordu bile

ama yangınımı söndürmüyordu da

aslında sana yazmak için

nedene gerek de yok

kalem sana aşık

defter de onun şahidi

aslında aşkımı yazabilecek

kalem de yok

yazılabilecek deftere

zaten sahip değilim', 'aslında yoktu hiç sebep seni düşünmem için bu gece yokluğun özlemimi artırmıyordu bile ama eksiltmiyordu da bazı anlarda iştahla sarılıyordu...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-dusunmek-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazı Düşler Yorulabilir', 'bazi-dusler-yorulabilir-baykal-kaanalp-jwiei', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bazı zamanlar senin olabilir 

bazı zamanlar hiç 

bazı saatler kurulabilir 

bazı saatler hiç 

dişlisi bozuk dünya 

yaşayanlar hani rüya 

gerçekler acı olsa 

yaşatanlar öldü mü? ya 

sana kalsın aşkım 

bana bir faydası yok 

aşksız kalmış yaşamım 

çabası ve kavgası yok 

bazı düşler yorulabilir 

bazı düşler hiç 

bazı hayaller kurulabilir 

bazı hayaller hiç 

dişlisi bozuk dünya 

yaşayanlar hani rüya 

gerçekler acı olsa 

yaşatanlar öldü mü? ya 

sana kalsın aşkım 

bana bir faydası yok 

aşksız kalmış yaşamım 

çabası ve kavgası yok', 'bazı zamanlar senin olabilir  bazı zamanlar hiç  bazı saatler kurulabilir  bazı saatler hiç  dişlisi bozuk dünya  yaşayanlar hani rüya  gerç...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bazi-dusler-yorulabilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş', 'ates-genco-yilmaz-g2x21', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'küçükken ateş yakardım tepenin yamacında

çalı çırpı toplar,

içimi ısıtırdım

kaybolurdu bir anda korkularım

ve üstüme sinen is kokularıydı annemin korkuları', 'küçükken ateş yakardım tepenin yamacında çalı çırpı toplar, içimi ısıtırdım kaybolurdu bir anda korkularım ve üstüme sinen is kokularıydı an...', ARRAY['Türk Edebiyatı','Şiir','Genco Yilmaz']::text[], 8.5, '{"poet":"Genco Yilmaz","poet_slug":"genco-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ates-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimde?', 'kimde-akin-samiloglu-1rqqd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gözler uğruna gebermeli! 

Kanayan bu yürek yüreğine değirmen,

Kahrolası ruhum çok titiz,

Ruhuna kurban.

Sana gelmeyen ayaklar,

Seni sarmayan kollar,

Kanıma mezar.

Duygularım,

Umutlarımda çocuk.

Ya uzan çek,

Cehennemden gençliğimi,

Yada bir avuç kum ol,

Yağ saçlarıma.

Bulutlar yastık gözlerime,

Hayatım bir şerit rüyalarda,

Tekbir laf mezar taşımda,

şamiloğlu.....

Gururum ol,

Namusumla uzan yanıma.

Bebek ol doğ içime,

Sevgim sadece sana,

Ellerim ellerinde.

Umutlarım.... Kimde?', 'Bu gözler uğruna gebermeli!  Kanayan bu yürek yüreğine değirmen, Kahrolası ruhum çok titiz, Ruhuna kurban. Sana gelmeyen ayaklar, Seni sarma...', ARRAY['Türk Edebiyatı','Şiir','Akın Şamiloğlu']::text[], 8.5, '{"poet":"Akın Şamiloğlu","poet_slug":"akin-samiloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Gün', 'kirk-gun-sabahittin-kurtoglu-8ghb4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir günü

kırk gün gibi

yaşayamazsan

kırk günü

bir güne sığıdıramazsın

acılarınla barışık

yaşayamazsan

acılarını pay edip

dağıtamazsın

mutluluklarına

ortak çoktur

ama kaçıramazsın

ölüm sana geldiğinde

azraili gönderecek

bir dost bulamazsın', 'bir günü kırk gün gibi yaşayamazsan kırk günü bir güne sığıdıramazsın acılarınla barışık yaşayamazsan acılarını pay edip dağıtamazsın mutlul...', ARRAY['Türk Edebiyatı','Şiir','Sabahittin Kurtoglu']::text[], 8.5, '{"poet":"Sabahittin Kurtoglu","poet_slug":"sabahittin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kirk-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum Şarkısı', 'kum-sarkisi-mehmet-ersoy-p7ccl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolun düştüğünde

Akdeniz sahillerine,

Gözünü yakan o tuzlu denizden

Koru kendini.

Açılmak istersen sahil boyunca,

Bir sandala binip

Kayalıkların kenarında

Deniz kızının parmaklarıyla

Kumlara çizdiği şarkıyı dinle,

Deniz kızından, kum şarkısından;

Koru kendini.

Yoksa anılar tutup bir kenarından

Komşunun bahçesinden kiraz çalıp

Kulağına küpe yaptığın ana götürür.

Hatırlatır kırmızı kuyruklu uçurtmanın

Havalanacağı zamanı,

Rüzgarın kesildiğini

Ve rüzgarı annene şikayet ettiğini.

Sonra çocukluk kara sevdan,

O komşu karısının taşınırken bir başka mahalleye

Gece saklı saklı ağladığını

Ve intikam alırcasına

Oturduğu evin duvarına işemeni.

En son

Kaldır başını kayalıklara doğru,

Anılarından kurtarıp kendini;

Bakabilirsen o deniz kızının gözlerine,

Hissedersin akşamın geldiğini,

Kürek çekmekten ellerindeki nasırı

Ve kum şarkısını', 'Yolun düştüğünde Akdeniz sahillerine, Gözünü yakan o tuzlu denizden Koru kendini. Açılmak istersen sahil boyunca, Bir sandala binip Kayalıkl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ersoy']::text[], 8.5, '{"poet":"Mehmet Ersoy","poet_slug":"mehmet-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kum-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-mehmet-ersoy-ft6hl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gece çıkıp kaybolsam

Zamanı olmayan bir yere düşse yolum

Çünkü zamana uysam seni

Uymasam kendimi unutuyorum', 'Bir gece çıkıp kaybolsam Zamanı olmayan bir yere düşse yolum Çünkü zamana uysam seni Uymasam kendimi unutuyorum...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ersoy']::text[], 8.5, '{"poet":"Mehmet Ersoy","poet_slug":"mehmet-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mercanköşk Mavisi', 'mercankosk-mavisi-sabahittin-kurtoglu-ksq0o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ışıkların kırılması gibi bir

yanılma mıydı

sana olan tutkunluğum

yoksa

çatlak bir bardakta

şarap içmek gibi yarım kalan

tat mıydı

yutkunduğum

gerçek bu günse

veya buysa

yarını kim söyleyebilir

bana

sarhoşluğum

yoksa yoksa

mercanköşk mavisi miydi

vurulduğum

susma susma

suskunluğum', 'ışıkların kırılması gibi bir yanılma mıydı sana olan tutkunluğum yoksa çatlak bir bardakta şarap içmek gibi yarım kalan tat mıydı yutkunduğu...', ARRAY['Türk Edebiyatı','Şiir','Sabahittin Kurtoglu']::text[], 8.5, '{"poet":"Sabahittin Kurtoglu","poet_slug":"sabahittin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mercankosk-mavisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezsin', 'bilemezsin-seyfettin-kardas-2ch6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilemezsin her gece sensiz geçen saatleri...

Uyku yabancı kelimedir, geçmişten kalan.

Işık gözlerime batan diken, karanlık soğuk bir dost...

Sevişmelerimizi düşünürüm hayal meyal,

En sıcak anlarda, ayrılıklar takılır aklıma.

Özlemin büyür içimde, dağ olur.

İçim sıkılır, yüreğim daralır, ağlayamam.

Bir sigara yakarım yıldızlara karşı,

Sonra ardısıra bir sigara daha, bir sigara daha

Dumana boğarım sensiz kabusları.

Bizi düşünürüm elele, gözgöze,

Tek bir yürek, sonsuza dek birlikte...

Düşünmem bir sonraki yalnız geceyi,

Düşünmem bir sonraki sensiz geceyi.', 'Bilemezsin her gece sensiz geçen saatleri... Uyku yabancı kelimedir, geçmişten kalan. Işık gözlerime batan diken, karanlık soğuk bir dost......', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bilemezsin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi Ardına Al', 'geceyi-ardina-al-mehmet-ersoy-z5d0b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin geç saatlerinde

Şehrin parlak ışıkları

Düşüncelerini kemirmeye başladığında,

İçindeki o eski isyan

Gömülmeyi bekleyen bir tabut gibi,

İçini yumrukladığında

Kulak ver.

Gündüz yasaklı

Kömür kamyonlarının aşındırdığı

O koskoca bulvarın kavşağında

Kırmızı ışıkta geç karşıya.

Bağdaş kurup otur

Soğuk kaldırımın kenarına.

Sırıtan taksilerden yüzünü çevir,

İçindeki o karanlık kıpırtıyı dinle.

Sonra adını bilmediğin bir kalabalığın

Yorgun gölgeler gibi sürüklediği,

Tahta tekerlekli, gıcırtılı

Bir özgürlük arabası geçer yanından;

Lüks otelleri uykusundan eden

Ama seni almayan.

Sen yine de ardından koş.

Geceyi ardına al,

Karanlığı da.

O yolun sonunda

Işık var.', 'Gecenin geç saatlerinde Şehrin parlak ışıkları Düşüncelerini kemirmeye başladığında, İçindeki o eski isyan Gömülmeyi bekleyen bir tabut gibi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ersoy']::text[], 8.5, '{"poet":"Mehmet Ersoy","poet_slug":"mehmet-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ozgurluk-arabasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simit Vapurları', 'simit-vapurlari-seyfettin-kardas-csk0c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman Kadıköy''den çıksam vapurla,

Mendirek''te konaklayan

Martı sürülerine takılır bakışlarım...

Hep aynı şey gelir aklıma.

Biz mi onları seyrediyoruz,

Onlar mı bizi? ..

Apaçık olansa karşılıklı bakışlar...

Bizim için; 

Onlar umut, onlar rüya, onlar hayal

Ve onlar ilham...

Ya biz; 

Kadıköy Eminönü arası

Simit vapurları...', 'Ne zaman Kadıköy''den çıksam vapurla, Mendirek''te konaklayan Martı sürülerine takılır bakışlarım... Hep aynı şey gelir aklıma. Biz mi onları ...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/simit-vapurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-mehmet-ersoy-ikt91', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğan çocuklara

Dedelerinin adının

Bir hatıra diye bırakıldığı

Yıllarda doğmuşum.

Başlarını sokacak bir ev derdindeymiş

Babamla annem.

Öyle lüks villalar değil,

Bir ufak gecekondu.

“İstersen, hayallerin olur,” derdi

Babam.

Ya hayalleri küçüktü,

Ya da kader yüzüne gülümsedi.

Ufacık gecekondumuzda,

Gaz lambasının sarı ışığında

Bizi avutmazdı aslında;

Bizi ayakta tutardı

Babamın anlattığı hikâyeler.

Bir cuma sabahı

Bıraktı bizi.

Yüzünde yine o bildiğimiz gülümseme.

Şimdi biz de

Çocuklarımızı seviyoruz.

Sevgili babam,

Senin bizi sevdiğin gibi.

                                                2004', 'Doğan çocuklara Dedelerinin adının Bir hatıra diye bırakıldığı Yıllarda doğmuşum. Başlarını sokacak bir ev derdindeymiş Babamla annem. Öyle ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ersoy']::text[], 8.5, '{"poet":"Mehmet Ersoy","poet_slug":"mehmet-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/babam-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''un Gözleri Doldu....', 'i-stanbul-un-gozleri-doldu-hurrem-yalcin-sfruh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul’un gözleri doldu

Sen sır olup giderken

Kolumdaki saat bile 

Zamanı sonsuza vurdu

Yüreğimin üşümelerinden

İçimdeki garip telaş

Ayaklarımın dibinde cansız

Sanki ilkbaharda sararan

Hüzün yaprağı buydu

Aslında gelen ilkbahardı dediler

Giden senmişsin bilemediler

Sevdamın esrik sabahı

Telefonum bile çalmaz oldu

Susmak nedir bilmezken

İstanbul’un gözleri suskun

Sen ardına bile bakmadan giderken

Islak yaprakların yürekleri dolandı

Yollarına çaresizlikten

Hışırtısı sağır edecek sanki

Esef rüzgarlarının

Kolumdaki saat bile zamanı dondurdu

Vakit gebe kaldı duruşlara

Gelecek sonbaharlarda

Sen yokken buralarda

İstanbul''un gözleri soldu

19.04.2004', 'İstanbul’un gözleri doldu Sen sır olup giderken Kolumdaki saat bile  Zamanı sonsuza vurdu Yüreğimin üşümelerinden İçimdeki garip telaş Ayakl...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istanbul-un-gozleri-doldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-seyfettin-kardas-edqht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elbet birgün açılır kapalı kapılar,

Son bulur

Sensiz saatler, kifayetsiz kelimeler...

Ve sancılı bekleyişler.

Elbet birgün tükenir acılar,

Son bulur 

Küskün sevdalar, umutsuz düşünceler...

Ve çaresiz çırpınışlar.

Elbet birgün kavuşur yürekler,

Son bulur

Özlemler, ayrılıklar

Ve yalnız ölümler...', 'Elbet birgün açılır kapalı kapılar, Son bulur Sensiz saatler, kifayetsiz kelimeler... Ve sancılı bekleyişler. Elbet birgün tükenir acılar, S...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Fincan', 'kirik-fincan-mehmet-ersoy-xs0j5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tunalı’da bir çay bahçesi,

Genç bir kız oturur sessiz.

Bir yandan çay, bir yandan yol,

Ağır adım bir ihtiyar; vakur, yalnız.

Göz göze gelirler ansızın,

Kız bakar, adam gülümser.

Kuğulu Park’ın kuğuları gibi gülümser.

Masaya çağırır genç kız onu,

Bir çay daha söylenir, zaman bükülür.

Cebinden çıkarır eski bir resim,

Susarak uzatır, eli titrek.

“Bu,” der bıyık altından,

“Kırk yıl önceki ben,” demek.

Garson fincanı bırakır usulca,

İhtiyar bir yudumda içer.

Boğazı yanar, fincan düşer,

Daha yere varmadan paramparça olur.

Kız sorar şaşkın:

“Neden?”

Adam gülümser:

“Gençlik kırık bir fincan,” der hemen.

“Masayla yer arasındaki boşlukta

Ne kadar asılı kalırsan, o kadar iyi;

Çünkü yere varmak

Her zaman geri dönülmez bir eski.”

Kalkar, gider çay bahçesinden,

Geldiği gibi yalnız.

Genç kız garsona döner:

“Plastik bardakta olsun çayımız.”

                                       06.05.1989', 'Tunalı’da bir çay bahçesi, Genç bir kız oturur sessiz. Bir yandan çay, bir yandan yol, Ağır adım bir ihtiyar; vakur, yalnız. Göz göze gelirl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ersoy']::text[], 8.5, '{"poet":"Mehmet Ersoy","poet_slug":"mehmet-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kirik-fincan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkramiye', 'i-kramiye-seyfettin-kardas-e2n9r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu yılbaşı bana çıkacak büyük ikramiye! 

Bütün dostları toplayıp,

Boğaz''da en lüks restorantı kapatacağım.

Binbir çeşit meze donatacak masamızı.

Balıklar aynı gün tutulmuş olacak.

Şarabın en iyisi, rakının alası olacak.

Kemancı hiç gitmeycek başımızdan,

Biz ne istersek onu çalacak çalgıcılar.

Masada oynatacağız dansözleri.

Muhabbet Bağı''ndan girip,

Ada Sahilleri''nden çıkacağız.

Sonra sabah,

Sonra akşam,

Sonra gece,

Para bitene kadar yiyip içeceğiz.

Sonra zil zurna sarhoş,

Döneceğiz yoksul yaşantımıza.', 'Bu yılbaşı bana çıkacak büyük ikramiye!  Bütün dostları toplayıp, Boğaz''da en lüks restorantı kapatacağım. Binbir çeşit meze donatacak masam...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ikramiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keman Seslerinde Saklı Bir Vals Var Benden Uzakta', 'keman-seslerinde-sakli-bir-vals-var-benden-uzakta-sabahittin-kurtoglu-6c632', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüreğimin çöl coğrafyasında

saklı bir ben var kum fırtınalarında

öksüz bulutlar yetim rüzgarlar

küskün yağmurlar çöreklenmiş göz kapaklarıma

keman seslerinde saklı bir vals var benden uzakta

kendi notalarımın yüreğinin ortasında

kontrabasın ``fa``sına basınca bana yansıyan

hüznümü saklayamam oysa

bir ben var ben de olmayan

solgun solgun soluklandığımda

keman seslerinde saklı bir vals benden uzakta

gün yorulmuş düşe yatmış

ağustos böceklerinin sesleri

çınar ağacı altında dinlenen senfoni tadında

ritmik döngüm de bana melankolik besteler yaptıran

ay mıydı alnına yansıyan arttırılmış akorlarla

keman seslerinde saklı bir vals var benden uzakta

yoksa ben mi değiştim de

benden ben miydi zülfünün altında

seni sensiz yazdığım şiirlerin yorgunluğunda

her güneşsiz sabahlarda manolyalarla

uyanıp seni andığım anlarda

keman seslerinde saklı bir vals var benden uzakta', 'yüreğimin çöl coğrafyasında saklı bir ben var kum fırtınalarında öksüz bulutlar yetim rüzgarlar küskün yağmurlar çöreklenmiş göz kapaklarıma...', ARRAY['Türk Edebiyatı','Şiir','Sabahittin Kurtoglu']::text[], 8.5, '{"poet":"Sabahittin Kurtoglu","poet_slug":"sabahittin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/keman-seslerinde-sakli-bir-vals-var-benden-uzakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yeni Başlıyor', 'gece-yeni-basliyor-seyfettin-kardas-z16u9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bir gece değil bu

Seni sensiz yaşadığım şu anda

Minderde uzanmış

Yıldızlardan, geceden, dalgaların sesinden,

Şarabın tadından konuşuyoruz.

Hafif serin bir rüzgarda,

Sımsıkı sarılmış bedenin bedenime.

Mutluluktan içim acıyor

Ellerin yavaş yavaş çekiliyor ellerimden

Bedenin soğumaya başlıyor

Yıldızlar kararıp, dalgalar susuyor.

Dur gitme

Gece yeni başlıyor.', 'Öyle bir gece değil bu Seni sensiz yaşadığım şu anda Minderde uzanmış Yıldızlardan, geceden, dalgaların sesinden, Şarabın tadından konuşuyor...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gece-yeni-basliyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş', 'tas-seyfettin-kardas-ip0it', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nice taşlar gördüm.

Kimi cadde kaldırımında,

Paspas olmuş cümle aleme.

Kimi dağ başında,

Meydan okumuş geçen asırlara.

Kimi asfalt kenarında,

Yoldaş olmuş geçip gidene.

Kimi han duvarlarında,

Sırdaş olmuş konuklarına.

Kimi elde yahut bir boyunda,

Süslü bir sevgili olmuş insan vucuduna.

Bir de mezar taşları gördüm; 

Ben gibi çakılıp kalmış, baş ucuna.', 'Nice taşlar gördüm. Kimi cadde kaldırımında, Paspas olmuş cümle aleme. Kimi dağ başında, Meydan okumuş geçen asırlara. Kimi asfalt kenarında...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tas-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılsama', 'yanilsama-seyfettin-kardas-22adh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir varsın, bir yoksun...

Bir buluşma bir ayrılık...

Bir mutluluk bir hüzün...

Bir gülüş, bir ağlayış...

Bir yağmur, bir güneş...

Bir bahar, bir kış...

İşte hayat böyle,

Zaten karşıt olan doğum ve ölüm

Arasında yaşanan karşıtlar...', 'Bir varsın, bir yoksun... Bir buluşma bir ayrılık... Bir mutluluk bir hüzün... Bir gülüş, bir ağlayış... Bir yağmur, bir güneş... Bir bahar,...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yanilsama-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-seyfettin-kardas-c2kg7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağan yağmurlarla boşalır gözyaşlarım.

Sesim bir martının çığlığında yankılanır.

Özlemimi dile getirir,

Toprağa kavuşan her damla.

Yağmur dinip, martılar sustuğunda,

Kasvet çöker içime.

Susup beklerim yine,

Bir sonraki yağmuru.', 'Yağan yağmurlarla boşalır gözyaşlarım. Sesim bir martının çığlığında yankılanır. Özlemimi dile getirir, Toprağa kavuşan her damla. Yağmur di...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Gelin...', 'haydi-gelin-hasan-basri-kale-k3894', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bir/düşünüyorum

Durup durup/yeniden..

Hüzünle gidenleri/umutla gelenleri..

Hain diller bıçak olmuş 

Sinsice kesiyor 

tertemiz kalemleri.. 

Ardından pişkin sırıtışlar/iğrenç

suratlar geliyor gözümün önüne

Nasıl yazıyorlar baharları/sevgileri..

Bir elde ''imlâ kılavuzu''

Diğerinde ''deyimler sözlüğü''/bir ansiklopedi eksik

olmadığı için üçüncü elleri..

Hala bir umut var içimde/azıcık ta olsa

Gelin yer açalım dünyamızda onlara

Yerleştirelim çıkarmamacasına 

Kazıyalım inatla/kalemi güzel/gönlü güzelleri...', 'Bir bir/düşünüyorum Durup durup/yeniden.. Hüzünle gidenleri/umutla gelenleri.. Hain diller bıçak olmuş  Sinsice kesiyor  tertemiz kalemleri....', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haydi-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta ve Çırak', 'usta-ve-cirak-seyfettin-kardas-gk1es', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir usta çırak hikayesidir bu.

Şiir ustası ve çırağı...

Usta hergün bir şiir yazar,

Çırak okur ve feyiz alırdı.

Arada bir nacizane; 

''''iyi olmuş ustam yüreğine sağlık'''' derdi.

Çırak bir gün bir şiir yazdı,

Usta okudu ''''şairin çırağı olmaz ustam'''' dedi...', 'Bir usta çırak hikayesidir bu. Şiir ustası ve çırağı... Usta hergün bir şiir yazar, Çırak okur ve feyiz alırdı. Arada bir nacizane;  ''''iyi o...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/usta-ve-cirak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-ahmet-kasapoglu-tla5d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siyah saçlarınla al yanağını

Koklayıp koklayıp öpesim gelir.

Leb-i nâr üstüne buse-i aşkı 

Evirip çevirip gömesim gelir.

Yâr ü ağyar ile seni görünce

Koparıp saçını yolasım gelir.

O şehlâ gözlerin bir nigâhiyle

Kaybedip kendimi ölesim gelir.

Dalgalı saçına rüzgâr vurunca

Tarayıp zülfünü öresim gelir.

Bir Lâhza gözümden ırağ ulunca

Sevdiceğim, billâh göresim gelir.

Salına salına seyran ederken

Memnu meyvaların çalasım gelir.

O mâsum kalbinin sevda gölüne 

Soyunup soyunup dalasım gelir.

Şarâb-ı aşkınla sarhoş olunca 

Tutup ta belinden sarasım gelir.

Bir tavr-ı edâyla sohbet ederken

Âteşin leblerin sorasım gelir.

Kasapoğlu der ki: bitirdin beni

Yakıp ta kül ettin yitirdin beni,

Ak göğsün üstüne yatırdın beni

Bu hulya içinde kalasım gelir.

  (Diyarbakır- 1953)', 'Siyah saçlarınla al yanağını Koklayıp koklayıp öpesim gelir. Leb-i nâr üstüne buse-i aşkı  Evirip çevirip gömesim gelir. Yâr ü ağyar ile sen...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kasapoğlu']::text[], 8.5, '{"poet":"Ahmet Kasapoğlu","poet_slug":"ahmet-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ozlem-153-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk', 'sonsuzluk-hamit-kunt-gp3l0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk bir ırmak olsa

Dalsam çıkmasam

Suyundan doya doya

İçsem bıkmasam

Bilirim bu ırmaklar

Deryaya kavuşacak

Ayrılan bütün yollar

Bir yerde buluşacak

                20/04/2004

                 Üsküdar', 'Aşk bir ırmak olsa Dalsam çıkmasam Suyundan doya doya İçsem bıkmasam Bilirim bu ırmaklar Deryaya kavuşacak Ayrılan bütün yollar Bir yerde bu...', ARRAY['Türk Edebiyatı','Şiir','Hamit Kunt']::text[], 8.5, '{"poet":"Hamit Kunt","poet_slug":"hamit-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sonsuzluk-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum', 'dogum-abdullah-atay-m2m2j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Müjde dostlarım müjde! ..

Bu sabah içim içime sığmıyor yine.

Kuşlar gibi uçuyorum ben de...

Işıldıyan güneşin bakışında,

Çisildiyen yağmurun altında,

Çileli bülbülün şakıyışında; 

Kara sevdam,

Yar toprağım,

Toprak anam,

Cancağızım:

Mini  minicik

Şirin  şirincik,cik cik....

Nergis,şakayık,orkide

Ve lalecikler doğurdu...

Şimdi bu yavrucuklar

Dünyaya ‘merhaba’ deyip

Sımsıcak bir yaza hazırlanıyor:

Ben oyuncaklarıyım! ....', 'Müjde dostlarım müjde! .. Bu sabah içim içime sığmıyor yine. Kuşlar gibi uçuyorum ben de... Işıldıyan güneşin bakışında, Çisildiyen yağmurun...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dogum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalıntı Şiirler', 'calinti-siirler-seyfettin-kardas-b2adi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İtiraf etmeliyim sana; 

Bu şiirlerin hepsi çalıntı.

Gizlice,

Saçlarından,

Gözlerinden,

Kaşlarından,

Kirpiklerinden,

Dudaklarından,

Avuçlarından,

Parmaklarından

Ve yüreğinden,

Küçük küçük,

Parça parça,

Koparıp çaldım onları.

Kendime şiir yaptım.', 'İtiraf etmeliyim sana;  Bu şiirlerin hepsi çalıntı. Gizlice, Saçlarından, Gözlerinden, Kaşlarından, Kirpiklerinden, Dudaklarından, Avuçların...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/calinti-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-ahmet-kasapoglu-nkvq4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gönlümde şakıyan bir bahar bülbülüsün,

Yalnız seni severek geçti bir ömür böyle.

Kalbimde başlatarak ruhumda estirdiğin

Fırtınalar dinmeden gel de şarkılar söyle.

Çakışan bakışların, kenetlenen ellerin,

Bir ağaç gövdesine resmedilen kalplerin,

Papatya yaprağında aranan sevgilerin

Anısı silinmeden gel de şarkılar söyle.

      (Bergama -1975)', 'Sen gönlümde şakıyan bir bahar bülbülüsün, Yalnız seni severek geçti bir ömür böyle. Kalbimde başlatarak ruhumda estirdiğin Fırtınalar dinme...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kasapoğlu']::text[], 8.5, '{"poet":"Ahmet Kasapoğlu","poet_slug":"ahmet-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sarki-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk sökücüler', 'ask-sokuculer-gencay-coskun-sw5iu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Psikolojik dengesi bozuk 

Aşk sökücüler 

Yalandan kan kusarlar 

Kustukları kan 

Aslında 

Gerçek sevgiye 

Kinleridir

Psikolojik dengesi bozuk 

Aşk sökücüler 

Yalandan göz yaşı dökerler 

Döktükleri gözyaşı 

Kirliliği yüksek 

Sudur

Psikolojik dengesi bozuk 

Aşk sökücüler 

Aşkı söküp attıklarını 

Sanırlar

Aslında attıkları 

Kendi 

İnandırılmışlıklarıdır

Psikolojik dengesi bozuk 

Aşk sökücüler 

Aşkı daha tanımadan 

Ahkam keserler 

Psikolojik dengesi bozuk 

Aşk sökücülerin 

Bilmediği

Gerçek aşkların 

Asla 

Bir yürekten 

Sökülemeyeceğidir

Psikolojik dengesi bozuk 

Aşk sökücüler 

Bana göre 

Her zaman 

Yalandan geçici 

Zaferlere inanırlar 

Sarhoş olurlar

Gerçek sevginin 

Karşısında 

Daima etkisiz kalırlar', 'Psikolojik dengesi bozuk  Aşk sökücüler  Yalandan kan kusarlar  Kustukları kan  Aslında  Gerçek sevgiye  Kinleridir Psikolojik dengesi bozuk...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ask-sokuculer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus Söyleme...', 'sus-soyleme-i-brahim-ethem-bingul-sn1u1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbim yüzüyor içimde

Ahenkli aşk yelinde

Salınan yelkenli gibi

Aşkın renk dünyası

Yeni renkler sunuyor

Adı yok renklerin

Sonsuzun başlangıcında sen

Yüreğime yüreğınle yazdığın için

Her lisan kendince teşekkürde aşkımıza

Yani sana yani bana

Tüm sesler ve sözler hayran dünyamıza

Ses,seda ile değil yürekle sevdiğimiz için

Seviliyorsun

Ama sus sakın söyleme kendine bile', 'Kalbim yüzüyor içimde Ahenkli aşk yelinde Salınan yelkenli gibi Aşkın renk dünyası Yeni renkler sunuyor Adı yok renklerin Sonsuzun başlangıc...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sus-soyleme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostiş', 'akrostis-ahmet-kasapoglu-d04wr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aradım cemâlini hayal bahçelerinde

Hayat ufuklarımın en tatlı yerlerinde.

Tâ subha dek inledim ismini yâdederek

Ümit dolu bir aşkın daha ilk seherinde.

Râyihalarla dolu ruhunun sellerine

Kapılıp sürüklendim  o aşk beldelerine.

Ah! ..Bir lâhza takılsam saçının tellerine 

Nağmelerle bezenen bu bahar âleminde.

  (Aksaray - 1959)', 'Aradım cemâlini hayal bahçelerinde Hayat ufuklarımın en tatlı yerlerinde. Tâ subha dek inledim ismini yâdederek Ümit dolu bir aşkın daha ilk...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kasapoğlu']::text[], 8.5, '{"poet":"Ahmet Kasapoğlu","poet_slug":"ahmet-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/akrostis-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yontulabilirlik....', 'yontulabilirlik-hikmet-feridun-demir-b7437', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam sana Cin cocuk, 

Ne güzel, simdiden bu genc yasinda basinin ne kadar sert bir tastan olustugunun farkina varmissin. 

Karsindaki de ne sertmis ki, carptiginda onun sertligini his etmissin. 

Karsindaki senin öyle bu ilk 22 yila sigdirdigindan daha büyük bir birikime sahipmis ki, sana bunu his ettirmis. 

Yasam öyle bir törpü ki, nice kayalari birakalim,

 en sert taslardan olan Graniti bile yontuyor. 

Ya bu bicimsiz tastan birsey olmaz dedigim anda cok yanilgi icinde oldugumuzu görüyoruz. 

O sert taslardan yasam cok güzel heykeller yaratiyor..

Birer saheser cikiyor ortaya.. 

Sen, bir bu kadar yasamin daha sonunda senin sertliginden eser kalmadigini 

ve yasamin cok güzel bir sekillenmesi ile olgunlastigini göreceksin. 

Hemen küplere binme.: :))))    kürekleri aheste cek ki.. 

Yontu parklaklik versin kirmasin yüzeyi.. 

Nice taslar (ama yontulabilinenler ve yontulma sürecini kabul edenler) , eser olarak kaldilar.

Tabiat yontamadigi taslari, onlardan eser olmuyor diye bazanda yontarken kirilanlari cöpügüne atti.. 

Cin cocuk, 

sen gercekten gelecekte bu yontuda nasibini alacak ve iz birakacak bir tas özelligine sahipsin.. 

Bunu iyi degerlendirdiginin de farkindayim..

Acik ve gerrak bir bakis acin var..

Sen 20 sinden evvel kendini heykeltrasin eline teslim eden ender taslardan bir tanesisin... 

Ne yazik ki nicelerini gördüm. 

Tabiat onlari 70 de dahi yontma geregini duymamisti ve cöplügüne atti. 

Yasami gönlünce yap. 

Kendine kendin icin iyi bak.. 

Sevgilar ve saygilar.... 

Sevgili Mutlu Ayar in Kararliligim siirine yorum....', 'Selam sana Cin cocuk,  Ne güzel, simdiden bu genc yasinda basinin ne kadar sert bir tastan olustugunun farkina varmissin.  Karsindaki de ne ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yontulabilirlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-serap-demirturk-7an75', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana özlemin resmini yap. 

Bir yürek çiz, yangın yeri. 

Çığlık çığlık dört bir yana dağılmış duygular. 

Ellerini uzatmışlar seni arıyorlar. 

Hiç bir deniz yok ki bu alevi söndürsün. 

Sen gereksin.

Özlemin alevi içinde bir göz var, ağlıyor. 

Sen diye ağlıyor, 

Biz diye ağlıyor. 

Sessiz çığlıklar atıyor kimse duymasın diye.

Yoksun. 

Bir bakıyorum yanı başımdasın, 

Bir bakıyorum koca dağlar girmiş aramıza. 

Bu resmi sevmedim; yırt, at! 

Ben seni istiyorum. 

Güzel gözlerini, 

Sıcacık ellerini, 

Sevgi dolu yüreğini.

Yoksun. 

Sen hiç aşkın buram buram eridiğine tanık oldun mu? 

Bir resim var şu an karşımda...

Bir yürek var, buz dağlarının içinde yanıyor. 

Buzlar eriyor alevin hışmından ama 

Dönüp bakan yok. 

Ver ellerini desem, 

Okşasam o beyaz saçlarını. 

Sarsam sımsıcak sevgimle ama gittin.

Fırat''ın azgın suları aldı seni...! 

Sen, gözleri kör eden aşkını nerde yitirdin?', 'Bana özlemin resmini yap.  Bir yürek çiz, yangın yeri.  Çığlık çığlık dört bir yana dağılmış duygular.  Ellerini uzatmışlar seni arıyorlar. ...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gittin-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişinin sessiz çığlığı', 'gidisinin-sessiz-cigligi-ali-i-hsan-gurpinar-iuv23', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana uzaktan bakıyor kanlı gözlerim

Uykusuz gecelerimin tek şahidi onlar

Bir zamanlar güzelliğine bakardı

Şimdi sadece umutsuzluk ve kedere mahkum

Pamuğum,sevgilim,kadınım

Sahip olabiliceğim herşeyim

Eylül aşkım sevda çiçeğim

Handem delikanlı güzelim

Yitikliğinin ertesinde rüyalarına daldığım

Bir nefes sigarayı bölüştüğüm

can damarım,ahu bakışlım

Bakmaya kıyamadığım

Al dudaklım, bal tenlim

Bebeğim,sevda gülüm 

Yokluğum,erkekliğim

Umudum, çarem, sevgi yüreklim

Çok özledim

Ali İhsan Gürpınar

20 NİSAN 2004

01:10', 'Sana uzaktan bakıyor kanlı gözlerim Uykusuz gecelerimin tek şahidi onlar Bir zamanlar güzelliğine bakardı Şimdi sadece umutsuzluk ve kedere ...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Gürpınar']::text[], 8.5, '{"poet":"Ali İhsan Gürpınar","poet_slug":"ali-i-hsan-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidisinin-sessiz-cigligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çare', 'care-serap-demirturk-wexn7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adam,

Anlamsızca baktı gözlerine.

Tutmak istedi ellerini nedensizce,

Uzandı...

Bir el bu kadar mı soğuk olurdu? 

Bir göz böyle mi anlamlı bakardı? 

Gözyaşları aktı gözünden ona sormadan...

Seslendi, duyuramadı...

Bunca yılın sevgisiyle sarılmak istedi.

Kadının bedeni,

Yılların intikamını alırcasına,

Hayır dedi...

Dokunamadı.

Keşkeler sardı bedenini,

Kemirdi pişmanlıklar beynini,

Sardı sözler dilini de

Sustu.

Duyan yoktu,

Gören yoktu,

Yolcu,

Gideceği yere varmıştı,

Çare yoktu.', 'Adam, Anlamsızca baktı gözlerine. Tutmak istedi ellerini nedensizce, Uzandı... Bir el bu kadar mı soğuk olurdu?  Bir göz böyle mi anlamlı ba...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/care-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz', 'kimsesiz-zafer-zengin-etnika-1dign', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimsesiz

Gidiyorum! 

Gülümsemenin

Olduğu

Yere...

Borcum

Var! 

Unuttuğum

Seylere...

Gidiyorum! 

Kimsesizlere...

K e n d i n      g i b i      g e  l i v e r s  e n    s e s s i z l i ğ i  m  e! 

Ç ı t ı m    ç ı k m a  z

A   y     s   u   s   k   u   n .  .  . 

20 Nisan 2004  '' İçimin kitabı ''', 'Kimsesiz Gidiyorum!  Gülümsemenin Olduğu Yere... Borcum Var!  Unuttuğum Seylere... Gidiyorum!  Kimsesizlere... K e n d i n      g i b i     ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kimsesiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şekerpınarı', 'sekerpinari-sabahittin-kurtoglu-mfzaj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ölürsem 

buralarda

zemzem

damlatmayın

dudağıma

şekerpınarı´ndan

bir tas su

toroslar´dan

rüzgar getirin 

bana', 'ölürsem  buralarda zemzem damlatmayın dudağıma şekerpınarı´ndan bir tas su toroslar´dan rüzgar getirin  bana...', ARRAY['Türk Edebiyatı','Şiir','Sabahittin Kurtoglu']::text[], 8.5, '{"poet":"Sabahittin Kurtoglu","poet_slug":"sabahittin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sekerpinari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-meyus-cetin-zkmje', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluluk diye bir şey yok

Acılar var hayatta 

Seni aşağı çeker

Sonra bırakır seni

Normale dönersin ki

Sen buna yükseldim

Mutlu oldum dersin

Yok yükselmek diye bir şey

Dağların bulutların üzerine 

Batmak var yerin dibine 

Sen sadece gökyüzü sanırsın

Çıkınca yeryüzüne', 'Mutluluk diye bir şey yok Acılar var hayatta  Seni aşağı çeker Sonra bırakır seni Normale dönersin ki Sen buna yükseldim Mutlu oldum dersin ...', ARRAY['Türk Edebiyatı','Şiir','Meyus Çetin']::text[], 8.5, '{"poet":"Meyus Çetin","poet_slug":"meyus-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mutluluk-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Çok Zor', 'sensizlik-cok-zor-mehmet-bolus-fue3d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özleminle alevalev yanıyor yüreğim,

Nisan yağmurları bile söndüremiyor,

İçimde gitgide büyüyen bu yangını.

Seni deli gibi severken,

Hasretine katlanmak,

Sensizliğe alışmak çok zor.

Seni sensiz yaşamak,

Sadece rüyalarda görmek,

Öyle acı veriyor ki bana

Sevgiyi seninle doyasıya  yaşamak,

Senin yanında olmak varken! 

Seni Senden Uzakta Sevmek

Tarifi imkansız acılar veriyor.

SENSİZ OLAMIYORUM ÖZLEDİM SENİ...................', 'Özleminle alevalev yanıyor yüreğim, Nisan yağmurları bile söndüremiyor, İçimde gitgide büyüyen bu yangını. Seni deli gibi severken, Hasretin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bölüş']::text[], 8.5, '{"poet":"Mehmet Bölüş","poet_slug":"mehmet-bolus","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensizlik-cok-zor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Uyanmak', 'sensizlige-uyanmak-mehmet-bolus-y8lxh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece daha bitmek üzere,

Güneş ışıklarını güne vuracak birazdan.

Tıpkı dün olduğu gibi.

Ve ben yine senli rüyalardan,

Sensizliğe uyanmak 

Zorunda kalacağım.

Ne olur sanki! 

Güneş doğmasaydıda,

Geceler hiç bitmeseydi.

Seni senden uzakta ancak

Rüyalarımda görebiliyorken,

Güneşin doğmasıyla

Yeniden sensiz kalıyorum,

Ancak öyle teselli bulup,

Kendimi avutuyor,

Yokluğunu hissetmemeye çalışıyorum....', 'Bir gece daha bitmek üzere, Güneş ışıklarını güne vuracak birazdan. Tıpkı dün olduğu gibi. Ve ben yine senli rüyalardan, Sensizliğe uyanmak ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bölüş']::text[], 8.5, '{"poet":"Mehmet Bölüş","poet_slug":"mehmet-bolus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizlige-uyanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Geçen Geceler', 'sensiz-gecen-geceler-mehmet-bolus-12c2p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugünde sabah oldu,

Tıpkı dün ve

Ondan önceki günlerde olduğu gibi,

Yine güneşin,

Dünya''yı aydınlatan ışıklarını,

Ve yine bir sabahı daha 

Sensiz karşılıyorum.

Gözlerim ufka dalarken,

Sensiz geçen günlerime isyan ediyorum,

Haykırmak geliyor içimden,

Avazım çıktığı kadar bağırmak istiyorum,

Daha kaç geceyi daha

Sensiz uğurlayıp,

Sabahları sensiz karşılamak 

Zorundayım söylermisin bana? 

Dayanamıyorum artık hasretine

Gece bile gündüzüne kavuşurken,

Ben sensiz acı çekmeye 

Devam ediyorum...........', 'Bugünde sabah oldu, Tıpkı dün ve Ondan önceki günlerde olduğu gibi, Yine güneşin, Dünya''yı aydınlatan ışıklarını, Ve yine bir sabahı daha  S...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bölüş']::text[], 8.5, '{"poet":"Mehmet Bölüş","poet_slug":"mehmet-bolus","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensiz-gecen-geceler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehir ve ilaç', 'zehir-ve-ilac-halil-i-brahim-ozdemir-6px7s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tik tak iniltilerle gidip gelen sarkaçtır,

Karnı aç olana sor, şu anki saat kaçtır? 

Bedava yaşayanlar nerden bilsin yokluğu,

Fakire nefes zehir, varsa ekmek ilaçtır..', 'Tik tak iniltilerle gidip gelen sarkaçtır, Karnı aç olana sor, şu anki saat kaçtır?  Bedava yaşayanlar nerden bilsin yokluğu, Fakire nefes z...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zehir-ve-ilac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut bire kaç verir?', 'umut-bire-kac-verir-halil-i-brahim-ozdemir-bcdi8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umut ektim bahara, yağmur  için dua et, 

Toprak bereketlidir, bir ekene kaç verir

Duadadır dal yaprak esirgenmez merhamet

Toprağından köküne, karşı konmaz güç verir…

Yeşerdi bahçe çimen, o dilediyse şayet

Umutlar taşı deler, gökyüzüne uç verir

Bahar biter yaz olur, hasat gelir nihayet,

Başaklar dolu dolu, gelin duvak taç verir…

Bir gün sorarlar sana, umut bire kaç verir? 

Bir gün sorarlar bana umut bire kaç verir?', 'Umut ektim bahara, yağmur  için dua et,  Toprak bereketlidir, bir ekene kaç verir Duadadır dal yaprak esirgenmez merhamet Toprağından köküne...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umut-bire-kac-verir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-hazar-can-fkac7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretinmiş anladım beni her gün ağlatan

Tek tesellim mektuplar seni bana anlatan

Geçmezki bu günler sen yanımda olmadan

Ne olursun gel artık gül dalında solmadan..

Geçiyor günler bak,zaman hiç durmadan

Yaz geçti,kış geçti bahar hazan olmadan

Bülbül uçup başka dala konmadan

Ne olursun gel artık gül dalında solmadan..', 'Hasretinmiş anladım beni her gün ağlatan Tek tesellim mektuplar seni bana anlatan Geçmezki bu günler sen yanımda olmadan Ne olursun gel artı...', ARRAY['Türk Edebiyatı','Şiir','Hazar Can']::text[], 8.5, '{"poet":"Hazar Can","poet_slug":"hazar-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-artik-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gibi', 'bahar-gibi-hazar-can-r9xvj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnce ruhlum selvi boylum gül nakışlım

Adın dudağımda dualar gibi

Bir tanem güzel gözlüm can bakışlım

hayalin gözlerimde rüyalar gibi.

Sensin yıllardır beklediğim gonca gülüm

Sıcaklığın dört yanımı sarar gibi

Sensin dudağımda yarım kalan tebessüm

Her anın bir başka bahar gibi.

Ömür boyu hep seni aradım durdum

Pervane ışığı arar gibi 

Bir iman seli sanki  sana tutkum

İnanılmaz eski sevdalar gibi.

Her nefeste kanımdasın canımdasın

Aşkın kalbimde deryalar gibi

Düşlerimde her anımda rüyamdasın

Esen yeller içimdeki hazlar gibi.

Her zerremle seninim duy beni

İçimden geçen türküler aryalar gibi

Her şeyinle benimsin sev beni 

Aslılar,şirinler,leylalar gibi...', 'İnce ruhlum selvi boylum gül nakışlım Adın dudağımda dualar gibi Bir tanem güzel gözlüm can bakışlım hayalin gözlerimde rüyalar gibi. Sensin...', ARRAY['Türk Edebiyatı','Şiir','Hazar Can']::text[], 8.5, '{"poet":"Hazar Can","poet_slug":"hazar-can","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bahar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Ben', 'sensiz-ben-cihan-firat-ss8t6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben yalnızlar prensi yine sana sığınıyorum karanlığımda

Bazen rüzgarı izliyorum kokunu taşıyan

Bir kuru yaprak oluyorum rüzgara karşı koyamayan

Kağıttan gemiler yapıp dilek tutuyorum 

Her biri için ayrı bir hayal kuruyorum 

Deniz dalgalarıyla vurup  batırıyor beni

Avucumda yıkık hayallerim kalıyor karanlığımda

Yaktığım mumları da ben söndürüyorum

Yanıma gelirsin diye düşler görüyorum

Gözlerin vuruyor gözlerimin yamacına 

Bir ak vuruyor yanaklarımdan süzülen

Ellerin kayıyor ellerimden can kopuyor bedenimden

Doğan güneş batıyor gine karanlık çöküyor kadehime

Bir zehir akıyor içime gölgen düşüyor önüme

Bir kurşun giriyor bedenime 

Toprak yağıyor güneşin üzerine

Bulutlar bedenimi sarmış

Karanlık çöküyor üzerime', 'Ben yalnızlar prensi yine sana sığınıyorum karanlığımda Bazen rüzgarı izliyorum kokunu taşıyan Bir kuru yaprak oluyorum rüzgara karşı koyama...', ARRAY['Türk Edebiyatı','Şiir','Cihan Fırat']::text[], 8.5, '{"poet":"Cihan Fırat","poet_slug":"cihan-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sensiz-ben-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlilik Öğüttü*', 'evlilik-oguttu-bayram-tunca-252zo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Teknede aynı yöne kürek çekilirse, yol alınabilir

Aksi yöne kürek çekilirse, tekne her an batabilir

15.12.203-12.15', 'Teknede aynı yöne kürek çekilirse, yol alınabilir Aksi yöne kürek çekilirse, tekne her an batabilir 15.12.203-12.15...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/evlilik-oguttu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum günün kutlu olsun', 'dogum-gunun-kutlu-olsun-mahmut-catak-qawqm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün senin doğum günün

Sen daha uyanmadan bugüne

Yıldızlardan taç yapıp

Kayan yıldızla yollasam sana

Ay ışığı saçlarına taksa

Ve sessizce kaybolsa 

Güneşin ilk ışıkları ile

Odana girip aydınlatsam

Hiç el değmemiş

Tüm dünya çiçeklerini

Odana doldursam

Aşkın kokusunu hissetsen

Seni ne kadar çok sevdiğimi

Kulağına eğilip söylesem

Gözlerini ilk açtığında

Karşında beni, 

Sana hayran bakan gözlerimde

Kendini görsen

Yüreğimdeki aşkı hissetsen

Hiç hatırlamasan

Bensiz geçen doğum günlerini

İlk kutlayan ben olsam

Sevgiyle gelen doğum gününü

Bir öpücük kondursam yanağına 

Doğum günün kutlu olsun 

Canım,aşkım, sevgilim desem

Bu bir hayal biliyorum

Keşke böyle bir düş görsem.', 'Bugün senin doğum günün Sen daha uyanmadan bugüne Yıldızlardan taç yapıp Kayan yıldızla yollasam sana Ay ışığı saçlarına taksa Ve sessizce k...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çatak']::text[], 8.5, '{"poet":"Mahmut Çatak","poet_slug":"mahmut-catak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı ben buldum', 'aski-ben-buldum-mahmut-catak-81sw4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O hep beklenendi

Ama gelmeyen

Hep aranandı

Ama bulunamayan

Bulduğunu hissetsen de

Kimsenin göremediği

Ellerinde tutup

Kaybettiğini bilmediği

Herkesin dilinde

Kim kaybetti ki

Biz bulalım dediği

Aşkı kim kaybettiyse

Söyleyin aramasın

Aşkı ben buldum

Kimilerinin canını acıtan

Kimilerini ayakta tutan

Karşılığını bulamazsa

Bazen kan akıtan

Kıymet bilmeyence

Üç kuruşa satılan

Arayanı duyarsanız

Söyleyin aramasın

Aşkı kim kaybettiyse

Ben buldum

Ben hissettim

Ben gördüm

Ben aşık oldum', 'O hep beklenendi Ama gelmeyen Hep aranandı Ama bulunamayan Bulduğunu hissetsen de Kimsenin göremediği Ellerinde tutup Kaybettiğini bilmediği...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çatak']::text[], 8.5, '{"poet":"Mahmut Çatak","poet_slug":"mahmut-catak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aski-ben-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel o zaman', 'gel-o-zaman-mahmut-catak-ar3rs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni özlüyorum

Çok seviyorum

Seni istiyorum diyorsunya

Ne duruyorsun

Gel o zaman

Çiçekler seni

Rüzgarlar nefesini

Kuşlar sesini

Hatırlatıyor diyorsunya

Ne bekliyorsun

Gel o zaman

Sensiz mutsuzum

Yersiz yurtsuzum

Gelecekten umutsuzum

Diyorsunya her zaman

Neden gelmiyorsun

Gel o zaman

Yanımda olmak

Benimle yaşamak

Birlikte yaşlanmak

Birlikte ölmek istiyorsunya

Neden korkuyorsun 

Gel o zaman', 'Seni özlüyorum Çok seviyorum Seni istiyorum diyorsunya Ne duruyorsun Gel o zaman Çiçekler seni Rüzgarlar nefesini Kuşlar sesini Hatırlatıyor...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çatak']::text[], 8.5, '{"poet":"Mahmut Çatak","poet_slug":"mahmut-catak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gel-o-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Nehirdir Yaşamak', 'i-simsiz-nehirdir-yasamak-k-muran-esen-4jkh5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşmanlık

Günden güne

Büyüyor  yüreğimizde

Salkım saçak.

Kimden aldık

Bu kini? 

Sevgiyi

Nerede tükettik? 

Anlamak

Bu kadar mı zor

Küskün yürekleri? 

Ki,

Sevmek  uzak bize

El sıkmak yasak.

Aradıklarımız

Hep bilinmeyen yerlerde

İsmimiz

Kapısına kilit vurulmuş ağızlarda

Tutsak....

Herkes

Bir başkasının

Lokmasına göz dikmiş

Nereye baksak.

Uçurumların

Son noktasında 

Ve bir karanlıkta mekânlarımız

Uçsak /  kanat yok

Koşsak

Kötürüm bacaklarımız

Bir gün batımında 

Çakıldık yerimize

Doğmuyor şafak.

Nedensiz savaşlar içinde

Eriyip gidiyor umutlarımız

Yeşermiyor

Ektiğimiz tohum,

Yağmurlar

Yabancı göklerimize

Toprağımız kurak.

Amaçsız nefretler  karmaşasında

Kayboluyor kimliğimiz,

Baktığımız yüzler

Dönmüş   çağrılarımıza /arkasını

Nereden doğup

Nereye aktığı

Bilinmeyen

İsimsiz bir nehirdir

Bizim için yaşamak......', 'Düşmanlık Günden güne Büyüyor  yüreğimizde Salkım saçak. Kimden aldık Bu kini?  Sevgiyi Nerede tükettik?  Anlamak Bu kadar mı zor Küskün yür...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/isimsiz-nehirdir-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serveti Murattır', 'serveti-murattir-cafer-tayyar-ozkan-4g1w1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cennetin bağından almış rengini,

Işıl ışıl parlar yaşlı gözlerin.

Bensiz mi gidecek kara toprağa,

Bağrımı aşkınla saran bedenin...

Ruhunu sözünden içti muradım,

Cana can katacak vaktini gözler,

Sana da  kıyamam tatlı sevgilim,

Biter mi ısrarım denen nedenin...

Değeri parayla pulla biçilmez,

Gerçek sevda gibi kutsal hislerin.

İhanet olmazsa umut kesilmez,

Serveti murattır gerçek sevenin...

01 Ocak 2004 Ankara', 'Cennetin bağından almış rengini, Işıl ışıl parlar yaşlı gözlerin. Bensiz mi gidecek kara toprağa, Bağrımı aşkınla saran bedenin... Ruhunu sö...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/serveti-murattir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alacakaranlık', 'alacakaranlik-ali-gencay-gufhw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sıyrıl güneş bulutlardan

sıkıldım artık alacakaranlıklardan

ellerimi sıkan kelepçe ve prangalardan

siyaha aşığım ben

ya git yada gel

sıkıldım artık alacakaranlıklardan

bilirmisin sen siyaha çalan 

beni benden alan

bilirmisin sen şafak vakti 

nedir bende kalan

ya git ya gel

sıkıldım artık alacakaranlıklardan

aşkın rengi olmaz yalan

ya siyahtır yok olan

ya beyazdır var olan

siyahı severim ben

ya git ya gel

sıkıldım artık alacakaranlıklardan', 'sıyrıl güneş bulutlardan sıkıldım artık alacakaranlıklardan ellerimi sıkan kelepçe ve prangalardan siyaha aşığım ben ya git yada gel sıkıldı...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/alacakaranlik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadeh Doluyordu', 'bir-kadeh-doluyordu-cumhur-turan-k0k4f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'içimdeki piyanonun tuşlarına bastıkça

sesin

yaşanmamış zamanların kurgusunda

sabahladım

erimiş bir yorgunluk

her yanımda salkım saçak

bırakırken kendini

alttan alta bir ninni gibi geliyordu

piyanonun sesi

bir kadeh doluyordu

bilinmeyen zamanlarda içilmek için', 'içimdeki piyanonun tuşlarına bastıkça sesin yaşanmamış zamanların kurgusunda sabahladım erimiş bir yorgunluk her yanımda salkım saçak bırakı...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-kadeh-doluyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumlara Çizercesine', 'kumlara-cizercesine-cumhur-turan-8louf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nasılda yürüdü ayaklarımız

kumsalda

gözlerimizde ayaklarımız

ayaklarımızda gözlerimiz

ellerimizde yüreğimiz

yüreğimizde çırpıntımız

bir sevda türküsünü kumlara çizercesine', 'nasılda yürüdü ayaklarımız kumsalda gözlerimizde ayaklarımız ayaklarımızda gözlerimiz ellerimizde yüreğimiz yüreğimizde çırpıntımız bir sevd...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kumlara-cizercesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisiz Adam', 'sevgisiz-adam-erol-sen-d9lsw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Konuşmaktan çok şiirle anlatmak 

Kolay geliyor belkide

Günlük yaşamı paylaşmak

Bir o kadar sevgisiz

İnsan yaşamı kadar değersiz

Ve de sevgisiz hayatlar

Hırsın güne yansıması kadar gerçek

Bir o kadar da acımasız

Artık suçlamalar bitti

Sona erdi sevgi çiçekleri

Belki önceden sevgiye aç yürekler

İçinden gelecek filizleri de öldürmüş

Sevgisiz yürek sevmek

Onun için üzülmek kahrolmak

Değmez ki ağlamaya

Kendini düşünmek varken

Bırak o yürek yüreksizini

Yaşama bak sen sevensin

Kendine güller ile bir yol çiz

Rengarenk olsun yaşama….

20.04.2004', 'Konuşmaktan çok şiirle anlatmak  Kolay geliyor belkide Günlük yaşamı paylaşmak Bir o kadar sevgisiz İnsan yaşamı kadar değersiz Ve de sevgis...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevgisiz-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Kucak', 'kara-kucak-sule-aydemir-i1w7q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'giderken

korkmadım 

açık bıraktığın karanlıktan

daha uzun bir süre

korkmayacağım

saydam boşluk 

sarıp sarmalıyor bedenimi

seni ne zaman düşünsem birdenbire

sanırım sadece o biliyor kimliğimizi

seni ne zaman düşünsem

uçuşuyor binlerce ateş böceği

arkalarında kanat bırakmaya havalanan

ateş dudaklı kelebeklerim

dudaklarında takılıyor gözlerim

sırılsıklam ağlıyor avuçlarım

bir zelzeledir geliveriyor 

sahipsiz bedenime 

acısız

acımasız 

kızgın 

yalnızlığıyla 

kıraç

yangın bir yar 

yüreğim

üstünü örtüyor

kurşundan agır 

ince perde gibi

suskunluğu bir lav

eriyor 

pamuk şekeri aşklarım

gülümsüyor

yıkıntıyı bilmez tanrılarım

giderken

korkmadım 

açık bıraktığın karanlıktan

uzun bir süre daha

korkmayacağım', 'giderken korkmadım  açık bıraktığın karanlıktan daha uzun bir süre korkmayacağım saydam boşluk  sarıp sarmalıyor bedenimi seni ne zaman düşü...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kara-kucak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl', 'nasil-ozer-sutcu-btl60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana elveda bile diyemedim

Gözlerim doldu bakamadım sana

Konuşmak istedim bir kelime edemedim

Kısacık zamanda kıyamadım sana

Ayırdılar bizi bakmadılar göz yaşıma

Sormadılar bir derdin varmı

Senden uzaktayım şimdi tek başıma

Yalnız yaşamak bukadar kolaymı

Ağlasam duymazsın sesimi

Biliyorum feryadım ulaşmaz sana

Öksüz gibi hissediyorum kendimi

Nasıl dayanacağım ben bu ayrılığa

İçim kan ağlarken nasıl gülerim

İdam mahkümu gibi isyanlardayım

Sensiz sanki yaşayan ölü gibiyim

Söyle bu hasrete nasıl dayanacağım', 'Sana elveda bile diyemedim Gözlerim doldu bakamadım sana Konuşmak istedim bir kelime edemedim Kısacık zamanda kıyamadım sana Ayırdılar bizi ...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-mahmut-catak-ul7wp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana bakmak

Görmenin  gereği olmalı

Seninle gülmek en güzeli

Oysa yapılan tekrarlamak

Bir heceyi

Seninle hüzünü yaşamak

Ağlamak bile güzel

Oysa akan

Bir damla  göz yaşı

Bırak sensizliği

Günümün seninle geçmesi

Yetmiyor bana

Yoksan eğer yanımda

Hayalin tamamlıyor geceyi

Çok şey istemiyorum aslında

Seninle geçsin gecem

Seninle geçsin gündüzüm

Artık yoksan yanımda

Yanında bitsin ömrüm.', 'Sana bakmak Görmenin  gereği olmalı Seninle gülmek en güzeli Oysa yapılan tekrarlamak Bir heceyi Seninle hüzünü yaşamak Ağlamak bile güzel O...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çatak']::text[], 8.5, '{"poet":"Mahmut Çatak","poet_slug":"mahmut-catak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-370-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sunaya', 'sunaya-turkay-gurlek-pnueg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SUNA’YA

Manalı gözlerinle bakma gözümün içine,

Bir mazi yatıyor inan kalbimin derininde

Kadehimi dolduruyorum ben onun seliyle

Suna kurban olayım bağlama beni kendine

          23/01/1985.as.hastane ERZİNCAN.....

SUNAYA

Hem bacımsın,anamsın,yarimsin,

Sen sevgilerinde üstündesin,

Ne menekşe ne lale sümbül

Sen güllerin üstünde bir gülsün.

    23/01/1985.as.hastane ERZİNCAN.....

SUNAYA          ..................

Sana bir şey söylesem kızmazsın değil mi

Çok görme sakın gönüldür anla derdimi

Yirmi gündür alev alev yanan sevgimi,

Sunam söyle melek misin yoksa perimi

07/02/1985.as.hastane ERZİNCAN.....', 'SUNA’YA Manalı gözlerinle bakma gözümün içine, Bir mazi yatıyor inan kalbimin derininde Kadehimi dolduruyorum ben onun seliyle Suna kurban o...', ARRAY['Türk Edebiyatı','Şiir','Türkay Gürlek']::text[], 8.5, '{"poet":"Türkay Gürlek","poet_slug":"turkay-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sunaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-turkay-gurlek-lpo46', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir isteğim var cerrah senden,

Şu kalbimi sök yerinden,

Göz yaşlarınla ıslatma onu,

Kirletme benim yüreğimi,

Kalbimi sökerken sakın incitme,

Başka yere vur neşterini.

Kalbim naziktir,kırma,yaralama onu,

Sonra git mezarcıya, iki mezar açsın,

Sorarsa iki mezar niye diye,

Birine beni,diğerine yüreğimi gömsün,

Kalbimin mezarı,süslü olsun,

Üzerinde leylaklar,güller,orkideler

Benim mezarımsa,taştan kumdan olsun.', 'Bir isteğim var cerrah senden, Şu kalbimi sök yerinden, Göz yaşlarınla ıslatma onu, Kirletme benim yüreğimi, Kalbimi sökerken sakın incitme,...', ARRAY['Türk Edebiyatı','Şiir','Türkay Gürlek']::text[], 8.5, '{"poet":"Türkay Gürlek","poet_slug":"turkay-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/isyan-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşmak', 'paylasmak-mahmut-catak-lchdu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep düşündüm,görmek istedim

Hep hissettim yaşamak istedim

Hep aradım bulmak istedim

Ben insandım; 

Özüme layık olmak istedim

Ben insandım; 

İnsanca yaşamak istedim

Çok okudum,okurken yaşadım

Yaşadıklarımı taşımak istedim

Dostluğumu 

İnsanlığımı paylaşmak istedim', 'Hep düşündüm,görmek istedim Hep hissettim yaşamak istedim Hep aradım bulmak istedim Ben insandım;  Özüme layık olmak istedim Ben insandım;  ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çatak']::text[], 8.5, '{"poet":"Mahmut Çatak","poet_slug":"mahmut-catak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/paylasmak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-ozer-sutcu-yecu4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buraya geldin küfür yadin

Bazen doymadın aç gezdin

Herşeyi sineye çektin

Söyle çok üzüldünmü can

Biliyorum seni çok kırdılar

Olmadık yere sana kızdılar

Başkasının suçunu sana yıktılar

Söyle çok üzüldünmü can

Çoğu zaman kısıtladılar özgürlüğünü

Zehir ettiler bu gününü dününü

Bırakmadılar hep kapadılar önünü

Söyle çok üzüldünmü can

Sabrettin sabırla bekledin

Hasretine çileyide ekledin

Biliyorum bu şeyleri hiç sevmedin

Söyle çok üzüldünmü can', 'Buraya geldin küfür yadin Bazen doymadın aç gezdin Herşeyi sineye çektin Söyle çok üzüldünmü can Biliyorum seni çok kırdılar Olmadık yere sa...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/can-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enginlere uzanacak ellerim', 'enginlere-uzanacak-ellerim-erol-sen-8ko29', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşantımı seçerken önümdeki ayrıntılar

Belli belirsiz biraz karaltı

Yönlendirmelerle ite kaka

Hatıralar adına bir şeyler var aklımda

Hatıralar yaşanmışlıklar

Türlü insanları gözlemlemek gibi

Yaşamda da kimlik değişikliği

Güne başlamak kadar başka

Aklınmı yok be adam

Yıllar taşkın sular gibi

Akarken tüketilen yılgınlıklara

Sevinçlerle birlikte

Ölüm bir o kadar uzakken düşüncede

Belli belirsiz kader çizgisinde

Sende yitip giderken yaşamda

Enginlere uzanacak bedenin…..

20.04.2004', 'Yaşantımı seçerken önümdeki ayrıntılar Belli belirsiz biraz karaltı Yönlendirmelerle ite kaka Hatıralar adına bir şeyler var aklımda Hatıral...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/enginlere-uzanacak-ellerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nevşehir', 'nevsehir-turkay-gurlek-4eb5z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne baharın ne yazın ne kışın var.

Mevsimlerin hep karışmış NEVŞEHİR

Dinmiş ıp ılık rüzgar,kasırgan var,

Mevsimlerin hep karışmış NEVŞEHİR.

Menekşe lale sümbüllerin vardı,

Bahçelerinde renk renk açarlardı,

Soldurmuş salmışın bak dikenleri,

Koklanmaz olmuşsun şimdi NEVŞEHİR.

Seher vaktinde yollarına düşerdim,

Bir ucundan bir ucuna seyir ederdim,

Semtlerinde sevgilimle gezerdim,

O yok yollarından geçmem NEVŞEHİR.', 'Ne baharın ne yazın ne kışın var. Mevsimlerin hep karışmış NEVŞEHİR Dinmiş ıp ılık rüzgar,kasırgan var, Mevsimlerin hep karışmış NEVŞEHİR. M...', ARRAY['Türk Edebiyatı','Şiir','Türkay Gürlek']::text[], 8.5, '{"poet":"Türkay Gürlek","poet_slug":"turkay-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nevsehir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-mahmut-catak-dn2lg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açsa elindekini ver

