BGSOUND SRC='' http://alaeddin.cc.selcuk.edu.tr/mcan/midi/midiler/Zeki%20Muren%20-%20Gitme%20Sana%20Muhtacim.mid''

   

.', 'img src='' http://ozel.balca.net/resima/jpg/anne10011-1.jpg''                                       -1977- Yokluğun neymiş meğerse. Düşünsem b...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gel-anneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İşte', 'benim-i-ste-fatih-ciftci-u7zkd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün çıkıp ta geleceğim diyen, 

Yoluna güller sereceğim diyen,

Seni bir ömür seveceğim diyen,

O insan benim işte.! 

İlk görüşte beni tanıyamazsın; 

Kim olduğumu anlayamazsın,

Beklide anlasan bırakamazsın,

Aşkından deli olan benim işte.! 

Şaşıracaksın karşına çıktığım zaman,

Islak gözlerle baktığım zaman,

Dönmem demiştim bıraktığın zaman,

Sözünü tutamayan benim işte.

Bir anda senden uzaklaşan; 

Her an ölüme yaklaşan,

Geceleri ecelle kucaklaşan,

Hep yıkılan benim işte,

Hep ağlayan benim işte,

Aşkından kahrolan benim işte.!', 'Bir gün çıkıp ta geleceğim diyen,  Yoluna güller sereceğim diyen, Seni bir ömür seveceğim diyen, O insan benim işte.!  İlk görüşte beni tanı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çiftci']::text[], 8.5, '{"poet":"Fatih Çiftci","poet_slug":"fatih-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Sevmem Seni', 'artik-sevmem-seni-fatih-ciftci-gc4y8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne çok koştum peşinden,

Ne hayaller geçti içimden,

Soğuttun beni kendinden,

İnan artık sevmem seni.

Kararsa bütün dünyam,

Yarım kalsa yine rüyam,

Silinse bütün hatıram,

İnan artık sevmem seni.

Yansa içim buram buram,

Dökülse saçım tutam tutam,

Olamazsın bir sigaram,

İnan artık sevmem seni.

Artık beni sevsen de,

Her an beni istesen de,

Benim uğrumda ölsen de,

İnan artık sevmem seni.', 'Ne çok koştum peşinden, Ne hayaller geçti içimden, Soğuttun beni kendinden, İnan artık sevmem seni. Kararsa bütün dünyam, Yarım kalsa yine r...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çiftci']::text[], 8.5, '{"poet":"Fatih Çiftci","poet_slug":"fatih-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/artik-sevmem-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan Ediyor', 'i-syan-ediyor-fatih-ciftci-r6rwk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu insan isyan ediyor,

Gece gündüz hep ağlıyor,

Andıkça maziyi içi yanıyor,

Bilmem neden kahroluyor.

Hayatından çıkana mı? 

Dünyasını yıkana mı? 

Bir kenara atana mı? 

Bu insan isyan ediyor.

Gözleri hep ıslak bakıyor,

Hali yürekleri yakıyor,

Sanki canı bedenden çıkıyor,

Bu insan isyan ediyor.

Hayatından çıkana mı? 

Dünyasını yıkana mı? 

Tek başına koyana mı? 

Bu insan isyan ediyor? 

İsyan ediyorum duyun sesimi,

Duyun ki; anlayın derdimi,

Ölmeden vereceğim bu son nefesimi; 

Bana bırakın,

Bırakın peşimi.

İsyan ediyorum dağlara taşlara,

İsyan ediyorum ağaçlara kuşlara,

İsyan ediyorum gözümde bitmeyen yaşlara,

İsyan ediyorum isyan.! 

İsyan ediyorum bu hayata bu dünyaya

İsyan ediyorum bu sevgiyi yaşamaya

İsyan ediyorum gülmeden ağlamaya,

Ölmeden tek başıma kalmaya,

isyan ediyorum isyan..!', 'Bu insan isyan ediyor, Gece gündüz hep ağlıyor, Andıkça maziyi içi yanıyor, Bilmem neden kahroluyor. Hayatından çıkana mı?  Dünyasını yıkana...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çiftci']::text[], 8.5, '{"poet":"Fatih Çiftci","poet_slug":"fatih-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/isyan-ediyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Üzülme', 'sakin-uzulme-fatih-ciftci-6vxu4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin yüreğin artık mekanım,

Sensin benim tek hatıram tek anım,

Parçalansa bedenim sana akar kanım,

Unutmam seni sakın üzülme.

Acılar sarsa dört bir yanımı,

Ecel alsa benden canımı,

Mezar taşında görsen adımı,

Unutmam seni sakın üzülme.

Ben sana adamışım hayatımı,

Sen kal yanımda yıksınlar dünyamı,

Sensiz kalsam o güzel aşkımı,

Sevdamı da unutmam sakın üzülme.', 'Senin yüreğin artık mekanım, Sensin benim tek hatıram tek anım, Parçalansa bedenim sana akar kanım, Unutmam seni sakın üzülme. Acılar sarsa ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çiftci']::text[], 8.5, '{"poet":"Fatih Çiftci","poet_slug":"fatih-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sakin-uzulme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Seninle', 'gel-seninle-fatih-ciftci-0cmlu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdim desem inanmaz mısın? 

Bu sevdaya kanmaz mısın? 

Bir gün ölsem yanmaz mısın? 

Ayrılmayalım gel seninle.

Bensizken kimsesiz olmaz mısın? 

Hep tek başına kalmaz mısın? 

Gece gündüz ağlamaz mısın? 

Yıkılmayalım gel seninle.

Kapını çalsam açmaz mısın? 

Kolumu açsam sarılmaz mısın? 

Bırakıp gitsem darılmaz mısın? 

Aşkı bulalım gel seninle.

Uzatsam elimi tutmaz mısın? 

Bu dargınlığı unutmaz mısın? 

Gül sersem yoluna mutlu olmaz mısın? 

Sevgili olalım gel seninle,

Mutluluğa koşalım gel seninle.', 'Sevdim desem inanmaz mısın?  Bu sevdaya kanmaz mısın?  Bir gün ölsem yanmaz mısın?  Ayrılmayalım gel seninle. Bensizken kimsesiz olmaz mısın...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çiftci']::text[], 8.5, '{"poet":"Fatih Çiftci","poet_slug":"fatih-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-seninle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasan...', 'anlasan-i-brahim-ethem-bingul-gya5i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün şiirler sana

Bir aşkımı anlasan

Bütün sevda, aşk sana

Beni aşkı bir anlasan

Yaşlarım yağmur oldu

Aşkım aktı sel oldu

Sukut dilim lâl oldu

Beni aşkı bir anlasan

Yaşarken öldüm zaten

Sen yoksun yokum zaten

Kaderimde sen zaten

Beni aşkı bir anlasan..', 'Bütün şiirler sana Bir aşkımı anlasan Bütün sevda, aşk sana Beni aşkı bir anlasan Yaşlarım yağmur oldu Aşkım aktı sel oldu Sukut dilim lâl o...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlasan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma Beni', 'sorma-beni-fatih-ciftci-xlukd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüzgar olup uçtun aklımdan yel gibi,

Akıp gittin gönlümden sel gibi,

Unutacağım seni oldun artık el gibi,

Arana beni sorma ne haldeyim.

Sakınırdım seni bir gül gibi,

Özlerdim yaşayamadığım gün gibi,

Ayrılık günü aklımda daha dün gibi,

Bekleme beni sorma neredeyim.

Yazmıştım seni bir şarkı bir şiir gibi,

Bıraktın öylece yarım kalmış romangibi,

Bitirdin hayatımı durmuş zaman gibi,

Üzülme sakın ölüyorum kederdeyim.', 'Rüzgar olup uçtun aklımdan yel gibi, Akıp gittin gönlümden sel gibi, Unutacağım seni oldun artık el gibi, Arana beni sorma ne haldeyim. Sakı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çiftci']::text[], 8.5, '{"poet":"Fatih Çiftci","poet_slug":"fatih-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sorma-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Seni Anlatır', 'bana-seni-anlatir-fatih-ciftci-7w0qp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökte yıldızların pırıltısı,

Akan suyun şırıltısı,

O güzel kuşların cıvıltısı,

Bana seni anlatır.

Doğan güneşin sarısı,

Gece ayın ışıltısı,

Esen rüzgarın uğultusu,

Bana  seni anlatır.

Karanlık gecenin sessizliği,

Yıldızsız akşamın kimsesizliği,

Ölümü bekleyen hastanın ümitsizliği,

Bana seni anlatır.', 'Gökte yıldızların pırıltısı, Akan suyun şırıltısı, O güzel kuşların cıvıltısı, Bana seni anlatır. Doğan güneşin sarısı, Gece ayın ışıltısı, ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çiftci']::text[], 8.5, '{"poet":"Fatih Çiftci","poet_slug":"fatih-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bana-seni-anlatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Yüreğim...', 'sensiz-yuregim-i-brahim-ethem-bingul-x8wmi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana aşık oldum hemde delice

Dağıldı, virandı senli yüreğim

Beni anmışsın yar yine dün gece

Koptu, uçtu, gamlı senli yüreğim

Bensiz yaşam sana hani haramdı

Çöle dönen yürek senle yanardı

Nisan yağmurları bana mı kaldı

Hayat artık sensiz anla yüreğim

Suyu çekilmiş kör kuyuya döndüm

Çakar fener vardı aşkın görürdüm

Beni yakan sendin seninle söndüm

Yaşasam ne yazar sensiz yüreğim...', 'Sana aşık oldum hemde delice Dağıldı, virandı senli yüreğim Beni anmışsın yar yine dün gece Koptu, uçtu, gamlı senli yüreğim Bensiz yaşam sa...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinçaltı Şiirleri-10', 'bilincalti-siirleri-10-oguzkan-bolukbasi-jloqu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşadıklarımı

küçük odalarda sakladım

küçük odalarda

hayatımı aradım

özledim', 'yaşadıklarımı küçük odalarda sakladım küçük odalarda hayatımı aradım özledim...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bilincalti-siirleri-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlatma Emi..! !', 'aglatma-emi-nazife-abayli-wxkgo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Demirden bir kuşun,

Kanatlarına oturup,

Uçtum..

Pamuk tarlalarının,

Alp dağlarının,

On bin fit üstünde,

Uçtum...

Gittim..

Yabancı bir ülkede seni buldum..

Baş ucuna kondum..

Yastığına başımı koydum..

Gezdim,

Gördüm....

Seni sevdiğimden,

Bin kat daha fazla,

Sevdim....

Seni,

Kendim gibi bildim..

Ağlatma emi..! !', 'Demirden bir kuşun, Kanatlarına oturup, Uçtum.. Pamuk tarlalarının, Alp dağlarının, On bin fit üstünde, Uçtum... Gittim.. Yabancı bir ülkede...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aglatma-emi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avcı', 'avci-murat-i-lgun-2ltu8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siz  avcılara  bakmayın

onlar  anlata  dursun  öykülerini

bir  kuşa  sormak  lazım

bir  geyiğe

övündüğümüz  insanlık  nedir  diye.', 'Siz  avcılara  bakmayın onlar  anlata  dursun  öykülerini bir  kuşa  sormak  lazım bir  geyiğe övündüğümüz  insanlık  nedir  diye....', ARRAY['Türk Edebiyatı','Şiir','Murat İlgün']::text[], 8.5, '{"poet":"Murat İlgün","poet_slug":"murat-i-lgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/avci-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Değiştirmek Boynumun Borcu', 'adini-degistirmek-boynumun-borcu-derin-oger-y1203', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çekil önümden dünya

Bir toprak yolsun sokağımda

Ki yorgun bile sayılmazsın

Parfümünü tazeler durursun  çiçeklerinle yağmurlarınla 

Güneşin kurutur dudaklarımı

Yuvarlanır yuvarlarsın gözlerime yıdızlarını

Sanki namluna susturucu takılmış

Bir bir vurursun göğsümdeki canlı anılarımı

Kalbim bir işkence odası

Öyle çok öyle çok ki ki irili ufaklı masalları

Gelip örtsede üstünü karanlığın

Örtemez emeğimin terini alnımda pırıltıları

Seni zamansız yiyip bitirici

Bir kalem daha kırıp fırlattın yüzüme

Adını değiştirmek olsun boynumun borcu 

Oysa sitem yalnızca ne sanık var ortada ne davacı

Bilinmez nerede solar gülümün pembesi

Eski fotoğrafladan bakar gülümser gibi

Zaman da karışır bir derenin sesine

Say ki bir gözyaşı damlasıyız hep aynı yöne dizi dizi...', 'Çekil önümden dünya Bir toprak yolsun sokağımda Ki yorgun bile sayılmazsın Parfümünü tazeler durursun  çiçeklerinle yağmurlarınla  Güneşin k...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adini-degistirmek-boynumun-borcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iste O Asktir', 'iste-o-asktir-sehriban-gombel-89eg3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ebedi bir mutluluk sanar

kendimizi ne oldugunu bilmeden kaptiririz

rabbimizden tek dilegimiz odur

ebedi bir tutkudur

mahveder yikar bazende ceker gider

canimiz pahasina tutkun oluruz

ask mi azap mi bilinmez

ne kadar istesekte unutamayiz

dar gelir koskoca dünya

acilarla dolu dünya der

saskinlik ve caresizlikle bekleriz

acilardan ve acimasizliklardan korkmaz

keske sonu mutluluk olsa der

günlerden aylardan ve hatta yillardan bikmadan bekleriz

umutla bekleriz sevgili bir gün kapimizi calacak diye

ne varki yürekten sevenlerin kavusmasi zordur der

yinede bekleriz

iste o asktir', 'ebedi bir mutluluk sanar kendimizi ne oldugunu bilmeden kaptiririz rabbimizden tek dilegimiz odur ebedi bir tutkudur mahveder yikar bazende ...', ARRAY['Türk Edebiyatı','Şiir','Sehriban Gömbel']::text[], 8.5, '{"poet":"Sehriban Gömbel","poet_slug":"sehriban-gombel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/iste-o-asktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Önce', 'senden-once-aysun-elagoz-yc7iu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben

Yaşanmamış aşklara adanmış şiirler yazıp

Ardından bakmaya alışıktım.

Alışık değildim

Yüreğimde hissetmeye,

Acısıyla tutukusuyla sevdayı

Alışık değildi gözlerim gözlerine

Alışık değildi dudaklarım

Bir ismi yüzlerce kere tekrar etmeye...

Ben

Yaşanmamış aşklara

Adanmış şiirler biriktirmeyi bilirdim,

Senden önce..', 'Ben Yaşanmamış aşklara adanmış şiirler yazıp Ardından bakmaya alışıktım. Alışık değildim Yüreğimde hissetmeye, Acısıyla tutukusuyla sevdayı ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senden-once-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Ağlarım', 'karanlikta-aglarim-ayse-birgul-yilmaz-snyff', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herkesin bir öyküsü var

Herkesin hayatından bir roman çıkar

İlle de aşk ille de aşk

Harcıyoruz, harcanıyoruz

Ben bir garip kimseyim

Aldılar ne varsa neyim

Kalmadı ki hiçbir şeyim

Biçareyim..

Sormayın anlatamam hikayemi

Yaslı geçti yaslı geçti en güzel çağlarım

Sözlerim yürek kanatır

Saklıdır kırıklarım, hıçkırıklarım

Ben her zaman karanlıkta ağlarım', 'Herkesin bir öyküsü var Herkesin hayatından bir roman çıkar İlle de aşk ille de aşk Harcıyoruz, harcanıyoruz Ben bir garip kimseyim Aldılar ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karanlikta-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-ayse-birgul-yilmaz-srivn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah erkenden kalkarım

Güne gülerek başlarım

Perdelerimi açarım

Aydınlığı kucaklarım

Günaydın doğan güneş

Günaydın çiçeklerim

Günaydın güzel evim

Günaydın sevdiklerim

Görüyor, yürüyor, duyuyorum

Bir kuş kadar hafif ruhum

Allaha şükrederim

Her şeyde bir güzellik bulurum

Her şeyle mutlu olurum

Günaydın gece bekçisi

Günaydın fabrika işçisi

Günaydın günaydın herkese', 'Sabah erkenden kalkarım Güne gülerek başlarım Perdelerimi açarım Aydınlığı kucaklarım Günaydın doğan güneş Günaydın çiçeklerim Günaydın güze...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunaydin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göğüs Kafesi', 'gogus-kafesi-soner-evran-ngfmu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'özgürlüğü çalınmış

kuşlar gibi

tıkmışsın yüreğini

göğsündeki kafese

ne olur

arala kapısını

razıyım seni

içinde sevmeye

(03 12 2002)', 'özgürlüğü çalınmış kuşlar gibi tıkmışsın yüreğini göğsündeki kafese ne olur arala kapısını razıyım seni içinde sevmeye (03 12 2002)...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gogus-kafesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Hapsi', 'goz-hapsi-soner-evran-rhu20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geceleri esir düşer

özgürlüğün rengi

ve alabildiğine güzeldir

gözlerindeki mavi

ben senin

bakışını sevdim

sakın indirme

gözlerindeki kepengi

(10 12 2002)', 'geceleri esir düşer özgürlüğün rengi ve alabildiğine güzeldir gözlerindeki mavi ben senin bakışını sevdim sakın indirme gözlerindeki kepengi...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/goz-hapsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Bir Şaka Bütün Bunlar', 'kotu-bir-saka-butun-bunlar-bora-alagoz-prbz9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şaka şaka, kötü bir şaka bütün bunlar; 

Dağ, düzlüğe dönüşür mü hiç; 

Kaplan çakala, kartal kargaya; 

Olur mu hiç? ! ..

Olur; olur be kardeşim:

Değişir, dönüşür her şey; 

Meltemler çark eder, hortum olur; 

Nehirler döner kendine, girdap olur; 

Ova kalkar yürür

Yürekler buza keser

Kan donar

Sen kötüye yaslanırsın

Çıban olgunlaşır da patlamaz

Ben ölür, ölür dirilirim

Ok yayda kalır

Düşer zaman

Çığlık olur.

Olur…

Şimdi ben

Rahman ve şeytana ana avrat sövüp

Sigaramın dumanıyla boşluğa resimler çizeceğim

Elimi daldırarak gökyüzüne, bulutlarını karacağım

Bol, bol öksürüp

Bir tuvale, bir yaptığım resme tüküreceğim

Yonga, yonga dökülüp tükenene kadar.

Lanet olsun doğduğum güne

Işıdığını gördüğüm ilk aya

Çiçekler arasında tozutan yıldıza

Kör karaya

Oflayıp, puflayan domuz burnuna

Tüm karpuz çekirdeklerine

Ahırlara serpilli sap ve samana

Ve bilcümle müşkülata, lanet olsun...', 'Şaka şaka, kötü bir şaka bütün bunlar;  Dağ, düzlüğe dönüşür mü hiç;  Kaplan çakala, kartal kargaya;  Olur mu hiç? ! .. Olur; olur be kardeş...', ARRAY['Türk Edebiyatı','Şiir','Bora Alagöz']::text[], 8.5, '{"poet":"Bora Alagöz","poet_slug":"bora-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kotu-bir-saka-butun-bunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değerli Saatler', 'degerli-saatler-soner-evran-d4y1y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dakikliğimin hediyesi

bir öpücük için

kusursuzca

zımparaladım zamanı

çünkü 

kolumdaki saatin

paslıydı çarkları

(18 11 2002)', 'dakikliğimin hediyesi bir öpücük için kusursuzca zımparaladım zamanı çünkü  kolumdaki saatin paslıydı çarkları (18 11 2002)...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/degerli-saatler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâbus', 'k-bus-soner-evran-8za5i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'rahat uyumak

isteyişime rağmen

kuş tüyünden yastık

konmasın yatağıma

sonra babamın 

avladığı

kuşlar giriyor

rüyama

(10 11 2003)', 'rahat uyumak isteyişime rağmen kuş tüyünden yastık konmasın yatağıma sonra babamın  avladığı kuşlar giriyor rüyama (10 11 2003)...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kabus-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Git', 'cek-git-safure-yildirim-3p584', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Al koluna ceketini,paltonu

Çek git,

Kapat yavaşça kapıyı,

Şimdi biraz üzgün

Biraz da kırgınım, ama,

Sanma,

Dayanamam,kahrolurum 

Bitti diye, çelimsiz aşkın,

Bunları da aşarım,

Kalmaz yarın sabaha

Dayanılmaz ağrılarım.

çek git,

Senin olsun, bilmeden verdiklerim

Artık, dalgasız denizim,

Kalmadı med cezirim,

Bekleyemem gelsin diye

Ne geceyi, ne gündüzü,

Sensiz olan her güne

İster uyur ister uyanırım.

Çek git,

Bakma hiç arkana! 

Sen de kendine yeni bir yol ara

Sakın ha sakın, 

Beni kafana takma,

Geçenleri anı diye sakla! 

Boşaldı bak hayatın,

Senin şimdi tüm zamanın,

Çek git hayatımdan

Kapat yavaşca kapıyı! ..

25.04.04  İlkim', 'Al koluna ceketini,paltonu Çek git, Kapat yavaşça kapıyı, Şimdi biraz üzgün Biraz da kırgınım, ama, Sanma, Dayanamam,kahrolurum  Bitti diye,...', ARRAY['Türk Edebiyatı','Şiir','Safure Yıldırım']::text[], 8.5, '{"poet":"Safure Yıldırım","poet_slug":"safure-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cek-git-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Bahçe', 'sakli-bahce-aynur-uluc-elnae', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gizlendiğim dünyamda yeşeriyorum

Dal veriyorum ince ince

Tomurcuklar çıkıyor bedenimden

Korkarak açıyorum çiçeklerimi

Kokusunu saklıyor

Tadını örtüyorum

İçimde çoğaltıp renklerimi

Siyah beyazla paketliyorum

(04-03-2004)', 'Gizlendiğim dünyamda yeşeriyorum Dal veriyorum ince ince Tomurcuklar çıkıyor bedenimden Korkarak açıyorum çiçeklerimi Kokusunu saklıyor Tadı...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sakli-bahce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-erdal-sayil-bhy6x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüm düştü eline,

Tut eline şan olsun...! 

Sevildim diye sevine; 

Bu da ona zan olsun...! 

Kavuşsun dileğine...

Seven sever kalbiyle,

Bir olur sevdiğiyle,

Konuşursa övğüyle; 

Yüceldiği an olsun...! 

İhanet aşkı keser! ...

Kalmaz ilğiden eser! ...

Kavak yelleri eser! ..

Belki sonu kan olur...!', 'Gönlüm düştü eline, Tut eline şan olsun...!  Sevildim diye sevine;  Bu da ona zan olsun...!  Kavuşsun dileğine... Seven sever kalbiyle, Bir ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ihanet-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kürek Mahkûmu', 'kurek-mahk-mu-soner-evran-1i4hk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kolumun yorulması

kimin umurunda

geçerken hain dalgayı

denizdeki balık

kendi savaşında

damıtılır gibi

erkinliğin içime hayâli

sevdama ıslık tutturmuşum

unutarak esareti

mahkûmluğuma ağladım

uzayan ay ışığı sularında

kulağımda çınlayınca acıdım

kırbaç kanar sırtıma

çırptığım kürek dağıtır   

ışıl bir yakamoz kuşağını

ki demlenirken bir çiftin

dudağında dudağı

usulca yayılır enginlere

yüreğimden üreğen

kıskançlık sarmalı

(09 09 2003)', 'kolumun yorulması kimin umurunda geçerken hain dalgayı denizdeki balık kendi savaşında damıtılır gibi erkinliğin içime hayâli sevdama ıslık ...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kurek-mahkumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum Falı', 'kum-fali-soner-evran-m8jcb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'denize dahi

açılmasa balıkçılar

yıldırmaz asla beni

zincirinden

kopan rüzgarlar

mevsimini kapatsa da şimdi

bulunduğum sahil kasabası

bir ateş yakıp beklerim

göçebe yaşayan

falcı kadını

poyrazlar

dağıtmış olsa da

ayağının tozuyla kumları

kaderim değişmezmiş hiç

çünkü biliyormuş çingene

bir de yıldız falını

(11 11 2003)', 'denize dahi açılmasa balıkçılar yıldırmaz asla beni zincirinden kopan rüzgarlar mevsimini kapatsa da şimdi bulunduğum sahil kasabası bir ate...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kum-fali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-soner-evran-s2bww', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aslında

iki kişiliktir yatağım

ama hep soğuk kalır

bir yanı yastığımın

titrerken sessizliğin

orta yerinde

ısıtmayı beceremez

damsız yorganım

(28 11 2002)', 'aslında iki kişiliktir yatağım ama hep soğuk kalır bir yanı yastığımın titrerken sessizliğin orta yerinde ısıtmayı beceremez damsız yorganım...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizlik-157-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Aşkı', 'yaz-aski-soner-evran-qh047', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'köpüklü dalgaların ucunda

ayağımızı okşarken deniz

istiridye kabukları kumsalda

biz halâ sevişiğiz

sabah kapıyı çalmakta

martılar uçmuş sessiz

yosun kokusu tadında

biz halâ sevişiğiz

(23 12 2002)', 'köpüklü dalgaların ucunda ayağımızı okşarken deniz istiridye kabukları kumsalda biz halâ sevişiğiz sabah kapıyı çalmakta martılar uçmuş sess...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yaz-aski-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yumarken Gözlerimi', 'yumarken-gozlerimi-soner-evran-ryjpg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'saklambaç oyunlarında ki

ebeler gibi

aradım seni

sevdiğim için

oysa sen beni

arkadan vuran

hainler gibi

yalnızlığa sobeledin

(18 11 2002)', 'saklambaç oyunlarında ki ebeler gibi aradım seni sevdiğim için oysa sen beni arkadan vuran hainler gibi yalnızlığa sobeledin (18 11 2002)...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yumarken-gozlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çivi Yatağı', 'civi-yatagi-soner-evran-ghygm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben küçüktüm

ve ahşaptı

iskeleti pencerelerin

o zamanlar

sokağa bakmaya çekinip

pasından korkardım

cam çivilerinin

hatırlarımda

el bile sallayamamıştım

pencereden

sevdiğim komşu kızı

taşınıp gidince mahalleden

zaten hiç beceremedim

sevdiklerimle vedalaşmayı

ama çağırsaydı

beni peşinden

koşarak giderdim aşkımın

yatağı olsa da

çividen

(14 04 2004)', 'ben küçüktüm ve ahşaptı iskeleti pencerelerin o zamanlar sokağa bakmaya çekinip pasından korkardım cam çivilerinin hatırlarımda el bile sall...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/civi-yatagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Bir Sızı', 'yuregimde-bir-sizi-hikmet-karakus-6qvdc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özledim seni

  karlı dağların nazlı çiçeği

   kardelenim

    sevdiceğim...

Eriyen kar suları gibi

  ince mi ince bir sızı

  akıyor yüreğimden

  ayrılığın derin yatağına; 

  Sellere dönüşmek üzere..

Kim bilir; 

 daha kaç bahar 

   yontulacak yüreklerimiz? 

Kaç güneş batacak üstümüzden

     kaç güneş doğacak ümidimize? 

Haberin olsun; 

    dayanamıyorum artık

     zamanın acımasızlığına

      ve sana...

Kardelenim

    hasretliğim benim

    ya gel yada ben geleyim...

(Ank.2002)', 'Özledim seni   karlı dağların nazlı çiçeği    kardelenim     sevdiceğim... Eriyen kar suları gibi   ince mi ince bir sızı   akıyor yüreğimde...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yuregimde-bir-sizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle Beklerim...', 'senle-beklerim-i-brahim-ethem-bingul-j8ad3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi Allah vergisi ahh anlasan

Beni başka nazarlardan saklasan

En başından beni aşkla donatsan

Bu aşkı dünyada senle beklerim

Öyle sev ki aşık ol aşk dağlasın

Aşkımızı kalbin aşka bağlasın

Beni hapset aşka, ruhta saklansın

Bu aşkı cennette senle beklerim..', 'Sevgi Allah vergisi ahh anlasan Beni başka nazarlardan saklasan En başından beni aşkla donatsan Bu aşkı dünyada senle beklerim Öyle sev ki a...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senle-beklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toka', 'toka-soner-evran-1dum0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'senden

küçük bir hatıradır

sevişirken

aldığım saçından

pek

sevmesem de

saçımın

ayrılığa uzamasını

sürekli

saklarım kafamda

senden kalan tokayı

(17 10 2003)', 'senden küçük bir hatıradır sevişirken aldığım saçından pek sevmesem de saçımın ayrılığa uzamasını sürekli saklarım kafamda senden kalan toka...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/toka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamoz', 'yakamoz-soner-evran-9ibgj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüreğime süzülen

bir ay parçası oldun

gecenin

imtiyazlı zamanlarında

aksine hep

karanlıkken sevdim güneşi

yansıttığı için yakamozunu

tüm mahzunluğuma

(04 08 2003)', 'yüreğime süzülen bir ay parçası oldun gecenin imtiyazlı zamanlarında aksine hep karanlıkken sevdim güneşi yansıttığı için yakamozunu tüm mah...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yakamoz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tavşan Falı (akşamcı)', 'tavsan-fali-aksamci-soner-evran-1zm4x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalnızlıktan mı bilmem

kadehimi hep

yakamozla paylaşırdım ben

oysa

alışagelmiş olabilir

kağıt çekmeleri

eğitilmiş tavşanların

yine de

sığdıramıyorum aklıma

asılsız fallara inanıp

benden kaçmasına

akşamın

(12 10 2003)', 'yalnızlıktan mı bilmem kadehimi hep yakamozla paylaşırdım ben oysa alışagelmiş olabilir kağıt çekmeleri eğitilmiş tavşanların yine de sığdır...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tavsan-fali-aksamci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Akşamlar', 'boyle-aksamlar-abidin-guneyli-8o515', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok rahat oluyorum böyle akşamlar

Gök yüzünde ay

Karşımda sen gülüyorsun

İçimde İlk bahar çiçekleri

Parmağımın ucunda muhabbet kuşum

Kanat çırpıyoruz mutluluğa

Ancak böyle akşamlar unutuyorum

Yolsuzluk üçgenlerini

Delik cebimi

Ayaklarımın ıslaklığını

Dünyanın yükü sırtımda

Şair yüreğim dayanmaz

Böyle akşamlar olmasa

		(1 Aralık 1996)', 'Çok rahat oluyorum böyle akşamlar Gök yüzünde ay Karşımda sen gülüyorsun İçimde İlk bahar çiçekleri Parmağımın ucunda muhabbet kuşum Kanat ç...', ARRAY['Türk Edebiyatı','Şiir','Abidin Güneyli']::text[], 8.5, '{"poet":"Abidin Güneyli","poet_slug":"abidin-guneyli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/boyle-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antik Daktilo', 'antik-daktilo-soner-evran-whq9e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eskiye dair

paslanmış bir

daktilo görsem

yüreğim burkulur

tuhaflaşırım aniden

yıllara meydan okuyan

sihirli aşklar

gelir de irfana

kıskanır

sevi isterim

tutkuyla

her şiir

duygu selinde ıslanıp

yazılırken kurumuştur

şairlerin

küflü kitaplarında

ve usanmadan

yontarak yaşanmışları

sayısız sevişmiştir

parmaklar

susmak bilmeden ağlayan

yaşlı tuşlarla

(21 08 2003)', 'eskiye dair paslanmış bir daktilo görsem yüreğim burkulur tuhaflaşırım aniden yıllara meydan okuyan sihirli aşklar gelir de irfana kıskanır ...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/antik-daktilo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmış', 'yalanmis-hayrettin-turk-4bqqe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geldiğinde zamanın donma vakti

Gelip gitmeler, sevmeler yalanmış

Beşikten mezara bir köprü var ki

Hazanda solup, ölmeler yalanmış…

Ağır emaneti alıp koynuna

Kara kara düşünmeler yalanmış

Cellad vursa baltayı boynuna

O son nefeste gülmeler yalanmış…

Fırtına koparıp bir bardak suda

Ardından dalıp, yüzmeler yalanmış

Okuyup aşkı, bitirip sonunda

Mecnunca çölde gezmeler yalanmış…

Yalanmış o gün batımı hüzünler

Ardından sevdanın ağıt yalanmış

Yalanmış parçalanmış tüm bütünler

Şiirlerde kalem, kağıt yalanmış…', 'Geldiğinde zamanın donma vakti Gelip gitmeler, sevmeler yalanmış Beşikten mezara bir köprü var ki Hazanda solup, ölmeler yalanmış… Ağır eman...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalanmis-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayakizleri', 'ayakizleri-seda-atasoy-fgalg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fırtınalar kopuyor yüreğinde yine 

Acılar denizinde boğulmaktasın biliyorum.

Kumsalda gördüğün ayakizleri iki iken  bire indi dimi 

Yıldızlar dansetmeye başladı gökyüzünde ama bak...

Korkma sakın o ayakizleri izleri  benim..

Bıraktım sanma seni daima yanındayım.

Sırtını okşuyorum bak hissedebiliyormusun  asıl şimdi arkandayım.

Bil ki oğlum seni şuan kucağımda taşımaktayım.', 'Fırtınalar kopuyor yüreğinde yine  Acılar denizinde boğulmaktasın biliyorum. Kumsalda gördüğün ayakizleri iki iken  bire indi dimi  Yıldızla...', ARRAY['Türk Edebiyatı','Şiir','Seda Atasoy']::text[], 8.5, '{"poet":"Seda Atasoy","poet_slug":"seda-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayakizleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahta Ev', 'tahta-ev-derin-oger-lhwom', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tahta ev

Doğduğum yer

Tozlanmış büyük kapısı 

Yağmurlarla güvercinlerle lekelenmiş çatısı

Gri bir donukluğa bulanmış 

Hani dilleri olsa konuşacak camları

Eşiği çam alalı

Oyuklarında kuş yuvaları

Ah çocukluğumun kıymetli anıları

Adımlarım otlar misali dizildi taş sofaya

Ninemi bulamadım...................................................

Gözyaşlarım duruldu o yüz yıllık çam ağacının altında

Bir tahta ev

Al çiçekler arasında

Yeşiline sarılmış sarmaşıklarının

Koynunda uyumuşum yollarımı yıllarımı gözlemiş 

Kaşım gözüm yağmurlara ıslatmamış rüzğarlara üşütmemiş 

Sanki hazin gelmiş  bu bahar ak merdivenlerine

Hazanı yüzümü özlemiş.......................................................

Yüzüm.........................', 'Bir tahta ev Doğduğum yer Tozlanmış büyük kapısı  Yağmurlarla güvercinlerle lekelenmiş çatısı Gri bir donukluğa bulanmış  Hani dilleri olsa ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tahta-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşasın İlkbahar', 'yasasin-i-lkbahar-aysenur-yazici-xuqyh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ki,  yüzünden serçe yüreğime

bin hüzün sıkıştırdım yıllar boyu..

sen ki gözlerime kezzap atarken

tutmadım bile kolunu...

gün gelir devran döner

....bilirim zaten 

Çok söylediler...

Ama inanmadım,

Tüm enlem ve boylamların arasında sen vardın

unutursun dediler habire

...vesaire.. vesaire...

mevsimlerde şair de bulanır

aşk küfenir o temizler

kış gelir,sevdiğini gömer

yaz  gelir 

çıkarır cesedini sever! 

..sonbaharla anılar kabarır

..yaprakların altına saklanır şair

aşkını koynuna alır buz gibi

hikayeler anlatır aşka dair

kış geldimi beyazlanır heceleri

hasretle acıya tutsak olmak

işte bu mevsimde bulaşır

bir hastalık gibi..

ah o geceleri...

gök yarılsa da gitsem diye

az mı ayıklar şair kuru yıldızları,

deli bulutların altından

uyandırmadan sızıları...

Sen öldüğün yerde kal! 

ne rüyama gir, ne söylen arkamdan

ne de gitar çal...

dünyayı senin için yakmaya kalkan bu kadın

gübre almış, filiz veriyor hayatın gamından

güle güle sevgilim

Ölü aşkı deşmenin ne gereği var

Yaşasın ilkbahar

                    26.04.2004

                    Tarabya

                     (02:10)', 'Sen ki,  yüzünden serçe yüreğime bin hüzün sıkıştırdım yıllar boyu.. sen ki gözlerime kezzap atarken tutmadım bile kolunu... gün gelir devra...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yasasin-ilkbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayal Sadece', 'bir-hayal-sadece-serap-demirturk-u441f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni hayallerimin içine tutsak ettim,

Herhangi bir yerde ya da zamandayız artık seninle.

Başbaşa oluşumuzun bu ilk günü...

Gözlerim kamaşıyor gözlerinin ışığından...

Allahım bu ne büyük mutluluk! 

Canımsın diye haykırabilirim...

Seni özlemenin şarkısını yazmam artık,

Sesime sevgini katıp da söylerim sevdamı.

Otur yanıma, 

Bakalım birlikte batan güneşe,

Doğan aya.

Yıllardır hasretim sana sanki...

Ellerim, gözlerim, dudaklarım hasret.

Sana dair söylenen tüm sözlere düşmanım.

Seni bir tek ben terennüm etmeliyim.

Sen bu gece benim hayallerimin

En kutsal misafirisin.

Sana bakmaya bile doyamam,

Korkarım ki dokunursam yok olursun.

Kal, gitme! 

Ben razıyım seni sadece seyretmeye.

Gitme!', 'Seni hayallerimin içine tutsak ettim, Herhangi bir yerde ya da zamandayız artık seninle. Başbaşa oluşumuzun bu ilk günü... Gözlerim kamaşıyo...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-hayal-sadece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZYAŞl', 'gozyasl-baki-son-wz0hg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzel ne kaldı...? 

.....................Gözlerde / ki manadan derin

.....................Bu dünya içinde,

.....................Sevmeye değer...! 

Saçlarında,

.....................Akşam rüzgarı

.....................Bir kaç sarı yaprak,

Ellerinde,

.....................Kaybedilmiş sıcaklığım...

Yum artık gözlerini,

''''Bir bahçe ve bir kaç nergiz,

Avuç dolusu mutluluk saksılarda

Ve kadehte damla damla

Yudumlanan,

Sevinç,ümit...''''

.....................Gerçek / se

Bir bakış sonsuzluğa

Bir kaç müzik nağmesi

.....................Dudaklarından...

Hayat  umutsuz boş

.....................Sevdiceğim.

Gözler / se dopdolu

.....................Ağlamalarla...!', 'Güzel ne kaldı...?  .....................Gözlerde / ki manadan derin .....................Bu dünya içinde, .....................Sevmeye değe...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozyasl-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ISTANBUL, Benim…', 'istanbul-benim-mine-gul-ij79m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ISTANBUL, İstanbul’um ve ben. Sendeyim, seninleyim, seni seyrediyorum…  Karşımda Haliç ve binlerce rengarenk ışıklar, hayran olduğum yakamozlar. Saatlerce izlesem, bıkar mıyım sanırsın? Bıkabilmem mümkün mü? İçimde, yüreğimin bir köşesinde öyle bir yerin var ki, hiç birşey ve hiç kimse o yeri dolduramıyor. Sen yoksan, ben sensizsem... ne büyük bir boşluk ki bu, ateşler içinde benliğim kavruluyor.

Bir martı geçiyor önümden, ne güzel de süzülüyor göklerinde. Ben de o martılardan birisi olabilseydim, semâlarında gezinebilseydim, hiç ayrılır mıydım senden? Ben bir martı, sen ve deniz, baska birşey ister miydim hiç? 

Sana olan sevgim, sana olan özlemim, senin ulaşılamaz olmandan, ya da seni bulup bulup kaybetmekten belki de? Ya içimde yanan ateş ve beni saran alevler? Onlar ne biliyor musun? Onlar benim sende bıraktığım, sende unuttuğum öbür yanım, çocukluğum, hayallerim, ümitlerim. Bir unutulmuş ben var sende. Sana her gelişimde, her kavuştuğumda, aradığım bir ben var, özlediğim bir ben var....

Onu bulamasam da, seninleyken onu hissediyorum, ona ne kadar yakın olduğumu hissediyorum.  Kendime yaklaştıkça, içimdeki boşluğun kapandığını farkediyorum, içimde birşeylerin kıpırdadığını farkediyorum. Garip bir duygu sarıyor içimi. Sana kavuşunca, mutluyum diyebiliyorum ve ardından mutlulukla karışık bir hüzün kaplıyor içimi... Sana kavuşmak, seninle olmak ve senden ayrılacağımı bilmek, “Bir daha ki sefere...” demek... Yine ayrılık, yine özlem ve yine içimi kavuran hasretin. Ama sonra... 

sana kavuşma heyecanı, yürek çarpıntıları, içimin ürpertileri ve yine sana kavuşmak. Ne kadar da ‘Bir daha kavuşacak mıyım sana 

acaba? ’, desem de, ümidimi hiç yitirmiyorum. Benim ümidimi yitirmem, seni unutmak olur, sende bıraktığım beni unutmak olur, seni kaybetmek olur, kendimden vazgeçmek olur. Oysa ben biliyorum, sen benimsin, ben sendeyim. Bir gün bana beni vereceksin, beni bana kavuşturacaksın... Bunu da biliyorum.

Nice gönülleri bağrında saklamak, nice ümitleri içinde gizlemek, öyle güzel yakışıyor ki sana.  Bir beyefendi kibarlığıyla, bir hanımefendi edâsıyla duruyorsun hep karşımda. Beklesem mi, daha da mı beklesem, sana kavuşmak için, kendimi bulmak için? Yoksa sorular sorsam sana, birşeyler söyler misin, cevap verir misin...? 

Bir martının kanatlarına mı gizledin benim hayallerimi, benim özgürlüğümü? Yoksa yakamozların rengarenk pırıltılarında çocukluğum mu gizli? Ya denizin derinliklerinde, orada yüreğimin en gizli, en ışıksız köşelerini mi barındırıyorsun yoksa? Belki de bu yüzden yakamozları seyretmekten kendimi alamıyorum, her seferinde bu yüzden belki bir çocuk gibi gözlerimin içi parıldıyor. Martılarda gizliyse hayallerim, belki de bu yüzden onları seyrederken hayallere dalıyorum, özgürlüğümü arıyorum ve onlar gibi özgürce uçmak istiyorum. Denizi seyrederken, öyle derinlere dalıyorum ki, bazen denize atlayıp o dalgaların arasına karışmayı düşlüyorum, dalgalarda kaybolup, denizle buluşmak istiyorum.

Sence ben kendimi bulmak üzere miyim? Ya da, ne yapmam gerekiyor, beni bana vermen için? Daha çok sevgi mi istiyorsun, daha cok aşk mı? Daha çok özlem mi çekmem gerekiyor, daha çok hasret mi? Daha fazla acı mı duymam gerekiyor, sana kavuşmam için? Yoksa sana kavuşmam için ölmem mi lazım? Ölünce toprağına karışıp seninle bir olmam mı gerekiyor? Zaten ölünce hiç ayrılmayacağız, bunu biliyorum ben. Ama ben seni yaşarken yaşamak, ben seni bu beden ve bu canla hissetmek istiyorum.

Bunu benden esirgemiyeceksin, değil mi? Biliyorsun, bir yanım hep eksik, hep yarım. İçimdeki boşluk her geçen gün büyüyor, o boşlukta kaybolmaktan korkuyorum.

Oysa beni bana verdiğinde, ben seni bulduğumda, o boşluk yok olacak, diğer yarım, eksik yanımı tamamlayacak. O zaman bir bütün olacağız, birbirimize kenetleneceğiz, daha da çok seveceğiz, daha çok özleyeceğiz ve o zaman içimizi yakan özlem ateşi yok olacak ve yerini yalnızca aşk ateşine bırakacak ve işte o zaman, hiç ayrılmayacağız, ölene kadar ve öldükten sonra da hep birlikte olacağız.

Biliyorum, sana her kavuştuğumda, bana biraz daha benden bir parça veriyorsun. Haklısın, belki de tümüyle beni bana versen, kendimle karşılaşmayı kaldıramazdım ve belki de tanıyamazdım kendimi…

Bu sefer de bir hayal verdin bana, bir rüyâ sundun,...güzel bir rüyâ. Hiç aklımdan geçmeyen, tahmin dahi edemeyeceğim bir rüyâ. O rüyâda ben vardım, benim bir parçam gizliydi, varlığını dahi unuttuğum bir parçam. Bana, „Bu rüyâ senin, istersen, sen göreceksin, elini uzat ve al! “ dedin. Biliyor musun, hiç düşünmeden, istiyerek o rüyâya daldım, ne olup olmayacağını kestiremeden hatta. O rüyâyı görmem gerekiyordu, o rüyâ bana aitti, bunu hissettim. Herşeye hazırdım, acılara da, hayal kırıklıklarına da. Ama diğer bir yanı daha vardı... mutlu olacaktım, bir rüyâ da olsa, unutmuş olduğum mutluluktan tadacaktım. Uyanacağımı bildiğim halde ve bu mutluluğu sadece bu rüyâda hissedilebileceğimi bildiğim halde, bu rüyâyı görmeliydim. Bu benim için çok önemliydi, çünkü ben mutlu olmayı unutmuştum, çok uzaktı benim için mutluluk ve mutlu olma sanşım her geçen gün azalıyor gibiydi.

Evet, bir hayalim ve bir rüyâ. Uyanacağım, biliyordum. Ama o kadar güzel bir rüyâydı ki, içimi hiç acıtmıyordu, içimde duyduğum mutluluk, acıları geçici de olsa bastırabiliyordu. Bazi rüyâlar vardır ya hani, rüyâda hissettiklerin hisler günlerce içini ısıtır, uyanmışta olsan, onları hissedersin. Belki, bu rüyâdan uyandıktan sonra içimdeki bir takım acılar yok olacak, belki hissettiğim mutluluk sonraları da hep içimde olacaktı. Önceleri mutluluk kavramına inanmıyordum, mutlu olabileceğimi düşünmüyordum. Ama şimdi bu rüyâda mutluluğun varlığına inandım, hissedebiliyordum. Öyle müthiş, öyle unutulmuş, öyle yeni bir duyguydu ki bu...

Deniz kıyısında oturmak, sevdiğim, vazgeçemediğim deniz ve benim sahilim, dalgaların coşkusuyla ayaklarımın ıslanması, içimi saran denizin kokusu, süzülen martılarım ve benim için flütle çalınan bir parça, bir parça ve bir parça daha... Martılar dayanamayıp dinlemeye gelmişlerdi, yüzlerce martı, çığlıklarıyla içimdeki coşkuya eşlik ediyorlardı. Gözlerimi kapayıp denizin dalgalarının sesini, taa içime işleyen, yüreğimin gizli köşelerine kadar inen o flütün sesini, o notalari, o an beynime ve benliğime kazıyordum âdeta. O coşkuya dayanamadım, içim içime sığmıyordu ve gözlerime birikti içime sığdıramadıklarım. Gözlerim alevlendi, gözlerim dayanamadı bu ateşe, sonra yaşlar doldu gözlerime ve süzüldüler, elimde olmadan, mani olamıyordum buna... Ben ağlıyordum, ama bu sefer mutlu olduğum için ağlıyordum, böyle bir mutluluğu yaşadığım için ağlıyordum, mutlu olmayı başarabildiğim için ağlıyordum. Hatta sevinçten çocuklar gibi zıplamak ve çığlıklar atmak geliyordu içimden, haykırmak istiyordum mutluluğumu dünyaya, insanları kucaklamak ve onları ne kadar çok sevdiğimi söylemek istiyordum... ve uyandım.

Bu rüyâyı sende yaşadım, sen yaşattın, kendime bir parça daha yakınım artık, bir parça Istanbul’umu daha buldum şimdi. Kimbilir, belki seni tümüyle bulurum hiç ummadığım bir zamanda, hiç ummadığım bir mekânda. Kendimi bulurum o zaman, beni bulurum...

Ben Istanbul olurum ve sana “Istanbul senmişsin! ” derim, belki bir gün, belki bugün, belki yarın. Ama bir gün, bir yerde, mutlaka....

(Istanbul, Nisan, 2004)', 'ISTANBUL, İstanbul’um ve ben. Sendeyim, seninleyim, seni seyrediyorum…  Karşımda Haliç ve binlerce rengarenk ışıklar, hayran olduğum yakamoz...', ARRAY['Türk Edebiyatı','Şiir','Mine Gül']::text[], 8.5, '{"poet":"Mine Gül","poet_slug":"mine-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istanbul-benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BiTiK...! ! !', 'bitik-baki-son-hrb9b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '..........................................Sen...

....................................................................................Gözlerin

..........................................Ve hayalin

....................................................................................Saplanan

..........................................Bakışların...

....................................................................................Ne kastınız var..? 

..........................................Bir kalbim var / dı

....................................................................................Aldınız.! 

..........................................Beni,

....................................................................................Benden

..........................................Çaldınız.! 

....................................................................................Artık bırakın

..........................................Beni,

....................................................................................Bende/n

..........................................Ne istiyorsunuz..?', '..........................................Sen... ....................................................................................Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bitik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam ...!', 'bir-adam-musfik-saltik-fdfc9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıkarları için her şeyi yapardı, paraya tanrı gibi tapardı

Her devrin adamıydı, yükseldi, paralandı, tanındı

Yüzüne güldüklerinin arkasından kuyularını kazdı

Daha otuz beşine, gelmeden o artık önemli bir adamdı.

Artık onun da etrafında yağcıları, şakşakçıları vardı

Mutluluktan uçuyor, açılmaz denen kapıları açıyordu

Etrafa su gibi para saçıyordu, zaman akıp geçiyordu

Yıllar geçti yaşlandı,  yavaş yavaş etrafındakiler azaldı

Sonra döndü geriye bir baktı, her şeyi elde etmişti ama

Bir yerde bir hata  vardı , düşündü, sorguladı, yargıladı

Sonunda  karara vardı, o  hiç kimsenin sevmediği bir adamdı

O hep  insanları, insanlar hep onu kullanmıştı, şimdi elinde 

Onursuz, şerefsiz,  içi bomboş bir ömür  kalmıştı.

Çok parası, çok malı vardı ama tek bir dostu yoktu

Bir başına yapayalnız koskoca bir evin içinde ölümü bekliyordu

Acıma duygusundan yoksun, sevgisiz kalbi artık tekliyordu.

Bir gün kalbi durdu , ne gariptir o gün yalnızlığı son buldu

Yanına yaklaşmayan,   ona bulaşmayan bir sürü insan koşuştu

Cenaze törenine geldi, onu öven sözler söylendi, haklar helâl edildi.

Tabutu omuzlar üzerinde taşınarak mezarlığa kadar gidildi.

Mezarına herkes, kürek kürek toprak attı, çelenklerle üzerini kapattı

Yanık sesli hafızlar dualar okudu, mezarına sular döküldü

Akşam yemekler yapıldı helvalar kavruldu, dualar okundu

Herkes büyük bir coşkuyla bu işleri yapıyordu, neden mi? 

Nedeni çok basit, millet bir mikroptan daha kurtuluyordu.

                                                                         15 / 04 / 2004', 'Çıkarları için her şeyi yapardı, paraya tanrı gibi tapardı Her devrin adamıydı, yükseldi, paralandı, tanındı Yüzüne güldüklerinin arkasından...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-adam-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birliğim', 'birligim-i-hsan-uncuoglu-ouvzt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birliğim

Dirliğim

Kaç zaman önceleri

Ayaklanmış yürüyor

Şerefli göz tac''ımdır 

Milletimin gözbebeği

Yücelerde O dalgalanır

Bayrak okunur Fermandır, 

***

Kalbimin her gözünde dolu toprak 

Nerden baksam gördüğüm Anavatan

Yüksek dağları aşar esince rüzgar

Aşkım göklere uzanır bak kollarımda 

Vatanda Milletin özlemi tek İstiklal 

İnan ki kalbte ona taşınan duygu kutsal,

***

Aradığım körfeze yolumu hiç şaşırmam 

Yalın yürüyen değişmez benim o İnsan 

Sonsuza dek başımın üstünde dalgalan 

ufkumun gurub rengi engin al denizim

Bayramlarıma sevincim ruhum herşeyim

Ay-yıldız''lı bayrağım altında doğdum

Varlığımı anlatan yalnız sana dönerim,', 'Birliğim Dirliğim Kaç zaman önceleri Ayaklanmış yürüyor Şerefli göz tac''ımdır  Milletimin gözbebeği Yücelerde O dalgalanır Bayrak okunur Fer...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/birligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-halil-i-brahim-ozdemir-dqzya', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Huşuyla yöneldiğin ulu divanda yüzün,

Analık özünde var, yanar kalbinde közün,

Allah, merhametinden merhamet bağışlamış,

Sözün ulu divanda, evladındadır gözün…', 'Huşuyla yöneldiğin ulu divanda yüzün, Analık özünde var, yanar kalbinde közün, Allah, merhametinden merhamet bağışlamış, Sözün ulu divanda, ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ana-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehirden Uzak', 'sehirden-uzak-orhan-tuncay-ysl8d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağların kokusu benliğimde

Nefes alıyorum derin derin

Yaşıyorum ben gönlümce

Kırlar, ovalar, çiçekler benim.

Kah tren düdüğü sessizliği bozuyor

Kah bir kuzu yavrusu koşuyor

Gökyüzü masmavi, gülüyor

Kalmıyor benim gamım kederim.

Çoban kavalları inliyor uzakta

Sürüler su içiyor ırmakta

Köpekler neşe dolu bu sabah ta

Tatlı tatlı gülümsüyor çoban Selim.

Güneş ışıkları parlarkan derede

Kıyıda söğütler eğilmiş yere

Buzağılar gömülmüş çimene

Söyleyin burada hüzünlü kim? 

Meltem rüzgarı mı şapkamı uçuran? 

Yeşil doğa mı beni çağıran? 

Ne arayan var beni ne soran

Gönlümce rahatım, burada sevdiklerim.', 'Dağların kokusu benliğimde Nefes alıyorum derin derin Yaşıyorum ben gönlümce Kırlar, ovalar, çiçekler benim. Kah tren düdüğü sessizliği bozu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sehirden-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz', 'umutsuz-orhan-tuncay-ueol6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Perdeler çekildi birden

Işık silindi gözlerimden

Uçurumlar parıldadaı arada

Yok oldu mutluluk daha bilemeden.

Sarardı ufuklar sararadı

Karardı gözlerim karardı

Bir ufacık sevincim vardı

O da eridi, o da koptu benden.

Yıkıldı birden umut dünyam

Yalnızlığı sarıp sarmaladı gam

Kalmadı sığınacak tek bir dam

Aktı göz yaşlarım dinmeden.

Dünya bana zindan, yaşam acı

Tüm faniler birer zindancı

Dikenlerle dolu her gül ağacı

Boş ruhumla, sahiden ben miyim ben?', 'Perdeler çekildi birden Işık silindi gözlerimden Uçurumlar parıldadaı arada Yok oldu mutluluk daha bilemeden. Sarardı ufuklar sararadı Karar...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umutsuz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert', 'dert-bedihi-kazim-nasuhbeyoglu-85tqw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Rahmetli Eşime-

Oya oya, emek emek nakışım,

Ak umudum, dal yeşilim, dikişim,

Bu ayrılık yıkılışım, çöküşüm.

	

                Çöken bilir, çöken bilir bir, diyem,

	Çok götürmez, derdin beni yer diyem.

Oya oya ak yazmaya dizildim.

Destan oldum, dilden dile yazıldım.

Arılandım,durulandım, süzüldüm.

	

                Bundan öte sır  içinde sır diyem,

	Bu noktada durulmaz ki, dur diyem.

Oya oya aşk okuttum dallara,

Mevsim mevsim kanat gerdim yellere,

Gözlerimi kilit yaptım yollara.

	

                Yollar ıssız, dilim ermez,” kar” diyem,

                Sensiz kime nazlı diyem, “yar” diyem.? 

Oya oya oydu beni derdin oy! 

Gül yerine gül dikeni verdin oy! 

Ak alnıma kara leke sürdün oy! 

	Sür efendim, sür sultanım, sür diyem.

                Çok götürmez, bu dert beni yer diyem.', '-Rahmetli Eşime- Oya oya, emek emek nakışım, Ak umudum, dal yeşilim, dikişim, Bu ayrılık yıkılışım, çöküşüm. 	                 Çöken bilir, ...', ARRAY['Türk Edebiyatı','Şiir','Bedihi Kazım Nasuhbeyoğlu']::text[], 8.5, '{"poet":"Bedihi Kazım Nasuhbeyoğlu","poet_slug":"bedihi-kazim-nasuhbeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dert-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yaprağı ''5'' Son', 'huzun-yapragi-5-son-halit-demir-7xhma', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün olur bedenim, makbere düşer

Sorguya, suale, gelmiş melekler

Bir yanımda nekir, bir yanda münker

Dile emir olmaz, hüzün yaprağı

Dünyada hiç sonu, yoktur emelin 

Hasat’ı cennettir, güzel amelin,

Huzuru-mevlâda, bomboşsa elin

Ele hisâb olmaz, hüzün yaprağı', 'Gün olur bedenim, makbere düşer Sorguya, suale, gelmiş melekler Bir yanımda nekir, bir yanda münker Dile emir olmaz, hüzün yaprağı Dünyada h...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/huzun-yapragi-5-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumru', 'kumru-cihan-firat-lixcg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne olurdu bir kum tanesi olsam

Bir kıyının güneş sıcaklığında

Denizin dalga,dalga serinliğinde

Masanın üstünde duran kum satinde

Bir tane olsaydım ne olurdu

Her akşam bana dokunup beni izlesen

tırnağında oje olsam

Parmağında tektaşlı yüzük 

Her duyduğunu duysam küpe olsam kulana

Ne olurdu kalbinde bir ben olsam 

Kumdan bir dağ  rüzgarla danseder

Yağmuru emer ateşi söndürüp kalbine hükmetsem

Ne olurdu bir kum tanesi olsam..', 'Ne olurdu bir kum tanesi olsam Bir kıyının güneş sıcaklığında Denizin dalga,dalga serinliğinde Masanın üstünde duran kum satinde Bir tane ol...', ARRAY['Türk Edebiyatı','Şiir','Cihan Fırat']::text[], 8.5, '{"poet":"Cihan Fırat","poet_slug":"cihan-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kumru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kızı', 'deniz-kizi-cihan-firat-uda9d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz tanımaz beni benim kadar

Koça dalgalarda bir kayık 

Ben içki nedir bilmem

Sarhoşluğum hasretinden

Namım yayılmış yedi tepe bilir

Sana yanıktır sesim sen duyma

O zaman dilim sürter söyleyemem

Bırak yakamozlar yığılsın üstüme

Yıldızlar senin olsun deniz gözlüm

taç yapayım İpek tenli saçlarına

canım senin olsun ben sensiz

denizi neyleyim bırak ömrümü

deniz dolsun ciğerlerim yudum, yudum', 'Deniz tanımaz beni benim kadar Koça dalgalarda bir kayık  Ben içki nedir bilmem Sarhoşluğum hasretinden Namım yayılmış yedi tepe bilir Sana ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Fırat']::text[], 8.5, '{"poet":"Cihan Fırat","poet_slug":"cihan-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deniz-kizi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadığın', 'yasadigin-cafer-tayyar-ozkan-1b50r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda ülkesinin kullarıyız,

Çektiğimiz her nefes boğar,

Ölümden beter acılara girip,

Muhabbet çeşmesi başında,

Vuslat şerbeti umarken,

Acılardan yudum yudum içer, sabrederiz.

Bir yudum sevgi arzularken,

Aşk kapısından eli boş döner,

Yaralı kalbimize taş basıp ölsek de,

Ser verip, sır vermeden geçip gideriz....

Kalbe sevda koymak marifet değil,

Yıllarca acıdan kıvranmak da değil,

Marifet; uğruna ne yapabildiğin,

Ne ektiysen, onu biçtiğin,

Ne sunduysan, ne kadarını içtiğin,

Ne verdiysen, onu aldığın,

Ne sevdiysen, ne kadarını yaşadığın...

12 Mart 2004 Ankara', 'Sevda ülkesinin kullarıyız, Çektiğimiz her nefes boğar, Ölümden beter acılara girip, Muhabbet çeşmesi başında, Vuslat şerbeti umarken, Acıla...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasadigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimler*', 'mevsimler-bayram-tunca-gqxz2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Farklı mizaçlı dört kardeş gibi

Olur muydu bu tat tek olsaydı

Ayrı ayrı her mevsimin özelliği

Dokusu/kokusu ve soğu/sıcağı 

Âlemin raksıyla olur mevsimler

Mevsimlerde oluşur güzellikler

Farklıdır her mevsim dört unsur

Etkiler her insanı bu dört unsur

Bahar çocukluk/gençlik yıllarımızı 

Yazlar olgun ve verimli yıllarımızı

Kış mevsimi çile/kahırlı yıllarımızı

Sonbahar anımsatır ihtiyarlığımızı

Mevsimler yaz/kış ilk ve son bahar

Geldi mi yaz duygular dağları ağar

Geldi mi kış mahlukatı telaş sarar

Baharda tohum taşı/toprağı yarar

Onda gördüm aşkın tüm motiflerini

İşittim onda aşkın ahenkli müziğini

Yaşadım onda aşkın bütün tonlarını

Belki, yaşamışsındır sen de aynısını

İlkbaharda gözledim yeniden dirilmeyi

Yaz mevsiminden aldım hasret dersimi

Kış mevsiminden öğrendim kahrı çileyi

Güzün yaşadım her türlü ayrılık acısını

Mevsimler ister kış, isterse bahar olsun

Yeter ki bahar gözlü yar yanımda olsun

Onunla beraberken her şey gül gülistan

Ama o yokken, yeryüzü sanki kabristan

19.04.2004-19.04', 'Farklı mizaçlı dört kardeş gibi Olur muydu bu tat tek olsaydı Ayrı ayrı her mevsimin özelliği Dokusu/kokusu ve soğu/sıcağı  Âlemin raksıyla ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mevsimler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Yaşam*', 'yasam-kubilay-enginol-zeskp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözünü açıp kapadın bak

Ogeçen bir saniyeydi

Ölüm döşeğinde birisi için

Hazineler ederdi

Kıymetini bil,ona göre yaşa

Mutlu olmasını bil daima

Düştüğün zaman ölüm kucağına

Kainatı bağışlasan dönemezsin

Sev insanları,kucak aç dostluğa

Çünkü hepsi bu dünyada

Hiç bir şeyin manası kalmayacak

Ulaştığın zaman kainata', 'Gözünü açıp kapadın bak Ogeçen bir saniyeydi Ölüm döşeğinde birisi için Hazineler ederdi Kıymetini bil,ona göre yaşa Mutlu olmasını bil daim...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasam-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliş', 'bilis-ayse-tural-nxse4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün doğrular yatay-dikey

Öğretiler yapay

Doğru hangisi

Hangisi yanlış

Dünyayı parmağında 

Oynatan büyücü

Neden 

Bebekler ağlar doğarken? 

Ve neden selviler

Her zaman birilerini bekler? ....', 'Bütün doğrular yatay-dikey Öğretiler yapay Doğru hangisi Hangisi yanlış Dünyayı parmağında  Oynatan büyücü Neden  Bebekler ağlar doğarken?  ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin Konuşsun', 'yuregin-konussun-ayse-tural-39qiy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deniz dibinde

Kırmızı balıklar

Dudaklarında

Vurgun yemiş gönlüm

Alıp götürdüler

Sarayına sultanın....

Gökyüzü

Güneşi harmanlıyor

Durmuş zamanlarda....

Dudakların sulusepkeni

Yüzümü kamçılıyor.

Dur 

Sen konuşma

Yüreğin konuşsun....', 'Deniz dibinde Kırmızı balıklar Dudaklarında Vurgun yemiş gönlüm Alıp götürdüler Sarayına sultanın.... Gökyüzü Güneşi harmanlıyor Durmuş zama...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yuregin-konussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Diye Varsın', 'ne-diye-varsin-murat-demir-havem', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne açlığın ne tokluğun

Ne azlığın ne çokluğun

Belli değil varın yoğun

	Ne diye varsın, sen nasıl yarsın? 

	Hiçlikten başka neye yararsın? 

Ne sevmekten anlıyorsun

Ne sevene can diyorsun

Sıkıştınmı gidiyorsun

	Sen nasıl yarsın, ne diye varsın? 

	Kaçmaktan başka neye yararsın? 

Ne karanlık ne ışıksın

Ne dağınık ne de şıksın

Ağlatmaya alışıksın

	Sen nasıl yarsın, ne diye varsın? 

	Üzmekten başka neye yararsın? 

Ne derdime derman oldun

Ne sevindin ne kahroldun

Yüreğime vurdun durdun

	Sen nasıl yarsın, ne diye varsın? 

	Vurmaktan başka neye yararsın? 

Ne beyazsın ne karasın

Ne beynimde fırtınasın

Yapan değil hep kıransın

	Ne diye varsın, sen nasıl yarsın? 

	Kırmaktan başka neye yararsın?', 'Ne açlığın ne tokluğun Ne azlığın ne çokluğun Belli değil varın yoğun 	Ne diye varsın, sen nasıl yarsın?  	Hiçlikten başka neye yararsın?  N...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ne-diye-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turan', 'turan-halit-demir-h8i1t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül sandığından, anılar çıkar

Anıda hem hüzün, hem de sevgi var

Sandığa kitlersin, bilmez ki anahtar 

Açarsan bu  dert tazeler TURAN

Gece uykun kaçar uyuyamazsın

Üst üste koyarsın tutturamazsın

Yorgana, yatağa sarılamazsın

Acmazsan bu dert kavurur TURAN

Üst üste yakarsın bir kaç sigara

Dalmışsa gözlerin tek bir noktaya

İçine baktığın o sandık var ya! 

Yaşanması hayata tutturur TURAN

Bu şiir sevgili kardeşim Filiz TURAN''a ithaf edilmiştir...', 'Gönül sandığından, anılar çıkar Anıda hem hüzün, hem de sevgi var Sandığa kitlersin, bilmez ki anahtar  Açarsan bu  dert tazeler TURAN Gece ...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/turan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy06) Gönüller Gurbet, Gurbetler Vatan Şimdi.-Mensuriye-', 'zy06-gonuller-gurbet-gurbetler-vatan-simdi-mensuriye-zulfikar-yapar-kaleli-ys82s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah rüzgârı yeşil yaygılar sererdi, 

Zümrüt yeşili. 

Bahar bulutları süt nine olurdu, yer beşiğinde.

Bitki çocuklarını emzirirdi. 

Ağaçlar, yeşil yapraktan elbise giyer, 

Mini mini dalların başlarına 

Çiçekten taç koyarlardı. 

Arılar çiçek çiçek koşmaya başlar, 

Çok yorulurlardı.

Bal yaparlardı, insanlar için.

Ağaçlar meyveye dururdu, insanlar için. 

Toprak ana bitkileri uyutup, 

Uyutup büyütürdü, insanlar için. 

Rüzgar ninni söylerdi insanlar için.

İnsanlar yoktu artık. 

İnsanlar gurbete gitmişlerdi.

Kimisi; 

Rahmandan mekânlarını cennet olmasını dilediğim,

Dönülmez gurbete. 

Belki ana vatanları orasıydı. 

Bizden çok uzaklardaydılar ya, gurbetti. 

Sonsuz rahmet, mağfiret ve gufran dileklerimi 

Gönderdiğim gurbet... 

Kimisi Almanya’yı, 

Kimisi  sevgilinin: “Yarim İstanbul’u mesken mi tuttun. 

Gördün güzelleri beni unuttun” dediği İstanbul’u. 

Yurdun dört bir yanı gurbet olmuştu, 

Gariplerin gurbeti. 

Gurbetin gitmediği, 

Kolunu uzatmadığı yer yoktu. 

Ey! Gönülleri gurbet,

Gurbeti vatan olanlar.

Gırcova çekirgeler yuvası değil artık! 

Çalılı sekide keklikler gagalamıyor.

Taşın başındaki  kuşburnu erkekçe bir isyanda. 

Kör gözenin ağlamaktan gözyaşları kurumuş. 

Hocanın pınarına su içmek için; 

Ne koyunlar, ne sığırlar, ne de serçeler gelmiyor. 

Tarlalar çorak, yamaçlar kuru. 

Gonogol’da çobanların sesleri yankılanmıyor.

Sandıktaşı’nın üstünde cüz oynayan da yok. 

Ve en garibi, en çok koyanı 

Kahrolası kızıl taştan guguk kuşunun

“Guguk,guguk” sesi kesileli seneler oldu. 

İnsanlarla birlikte gurbete çıktılar demek ki. 

“Gukku ben kaç yaşındayım” soracak 

Çocuklar da yok köyde. 

Artık kalan üç beş ihtiyar.

İnsanların eli dertli, dili dertli, 

Gönülleri:

Gönülleri çoktan sevdikleriyle birlikte 

Gurbete çıkmış.

”Eğlen bir haber ver, acele gitme, 

Zamanın bu kadar dar mı postacı. 

Yok deyip de beni perişan etme, 

Sevdiğimden haber var mı postacı” 

Diye haber soran sevgili de yok,

Postacı da yok. 

Artık mektuplar kara trene verilmiyor.

“Gurbet o kadar acı ki, ne varsa içimde. 

Hepsi bana yabancı, hepsi başka biçimde” 

Diyen şair ne kadar da haklıymış meğer. 

Bu yerin vefası yoktur,

Aşı da, suyu da muhannettir.

Eski tatlar hasrete dayanamadılar, yollara düştüler. 

“Şura senin bura benim” 

Derken her biri bir baharda kaldılar. 

Artık sabah ezanları eskisinden çok

Dokunuyor insana. 

Geçmişe yolculuk yapmak için 

Gözleri yummaya gerek yok. 

Gözler zaten  gurbet.', 'Sabah rüzgârı yeşil yaygılar sererdi,  Zümrüt yeşili.  Bahar bulutları süt nine olurdu, yer beşiğinde. Bitki çocuklarını emzirirdi.  Ağaçlar...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/zy06-gonuller-gurbet-gurbetler-vatan-simdi-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DenizSiz Kent', 'denizsiz-kent-sule-aydemir-g0wnv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kokun

denizden gelirdi 

arkasından gözlerin

gelirdi ki

bir o kadar derin

titremelerim 

dalgalarından mıydı

hiç bilmezdim

güneş doğardı seni seyrederdim

batardı  seni seyrederdim

kulaklarım sesini dinlerdi

nemini çekerdi bedenim

tenimden içeri girerdin

gitmedim

denizsiz bir kente 

gidemedim

_________gidemedim', 'kokun denizden gelirdi  arkasından gözlerin gelirdi ki bir o kadar derin titremelerim  dalgalarından mıydı hiç bilmezdim güneş doğardı seni ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/denizsiz-kent-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Yıldız Kayarak Geliyorum', 'yildiz-yildiz-kayarak-geliyorum-nevin-kurular-3df6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapatma gözlerini aç, ben geliyorum

Mor bulutlara sarmışım hayalleri

Tozu dumana katarak,

Dörtnala koşan atlılar gibi

Doludizgin özlemimle geliyorum.

Kokla rüzgarı ışık gözlüm

Efil efil hisset beni

Onca yolları aşacak

Onca dağları yalayıp okşayacak

Meltemlerle geliyorum.

Sen gönderdin güneşi gecelerime 

Biliyorum.

Ben üfledim yıldızları düşlerine

Seni uykularda sanarak

Yumma gözlerini aç yaprak gözlüm

Yıldızlarla

Yıldız gibi kayarak geliyorum.

Açık dursun avuçların

Kollarını  aç

Sıkı sıkı tut yüreğimi

Şimşeklerim çakacak

Gökler delik deşik hasretimden

Yağmur gibi

Sağanak sağanak  geliyorum.

Şafaklar  feryat

Gurublar yangın yeri,

Gecelerde deli mavi adını anarak

Seni düşledim seni

Aç kollarını aç

Biraz şaşkın biraz utangaç

Alev alev kor dudakla geliyorum.

Ağustos böceğinden,

Kumru muhabbetinden

Sesler getiriyorum.

Nisan çiçeklerinden renkler,

Aç kulaklarını aç

Heceler derliyorum

Besteleri nihavent

Besteleri rast

Duy beni; 

Şarkı şarkı, 

Şiir şiir,

Türkü türkü  geliyorum.

Acıları,

Çakıl taşı zamanlara bırakıyorum.

Seni bende,

beni sende sanarak 

Sarhoş gibi umarsızca

Berduş gibi pervasızca

Irmak ırmak  çağlayarak, 

Coşuyorum.

Aç yüreğini aç

Taşıyorum.', 'Kapatma gözlerini aç, ben geliyorum Mor bulutlara sarmışım hayalleri Tozu dumana katarak, Dörtnala koşan atlılar gibi Doludizgin özlemimle g...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/yildiz-yildiz-kayarak-geliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-esen-zafer-ddkdk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönül hasret oduyla yanıp dururken

Feryadımız figanımız arşı bulurken

Puşt zulalarında harap olurken

Dost diye haykırdıklarımız nerelerdeydi

Bir ömür ki genç yaşta derbeder olmuş

Bir ışığa pervane sabreder olmuş

El yanmış, göz yanmış, canda ten yanmış

Grubda kaybolurken dost neredeydi

Dünya dergah idiyse biz kapıda kul

Özümüz göklerde savruldu pul pul

Zalim elinde soldu da yediveren gül

Felekler gezgini dost neredeydi

Arayıp dururken hep köşe bucak

Biz bize yandı içte her saçak

Muhabbet sunarken biz kucak kucak

Terk etme diyen dost neredeydi

Çağrına koştuk her  nerde isek

Kaybolup gittin neye döndüysek

İsyan edip gidişine isyan olduysak

Gel dediğimiz dost neredeydi

Gün be gün sabırla yeniden doğduk

Sen bir ömürken biz bir an olduk

Sığmadık bir yere aradık durduk

Biz kaybolurken dost neredeydi

Kaç canda bir sinmek bir dönmek gerek

Kaç yüzyıl yeniden yazılmak gerek

Kılıklar hep aynı oyuncalar hep felek

Eski esvab olmuşken dost neredeydi

Soyulduk soyunduk bir öze daldık

Kurban edildikte pek şaşıp kaldık

Talihin sebebin sırrını sorduk

Yoktur derlerken dost neredeydi', 'Gönül hasret oduyla yanıp dururken Feryadımız figanımız arşı bulurken Puşt zulalarında harap olurken Dost diye haykırdıklarımız nerelerdeydi...', ARRAY['Türk Edebiyatı','Şiir','Esen Zafer']::text[], 8.5, '{"poet":"Esen Zafer","poet_slug":"esen-zafer","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sitem-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün bayram', 'bugun-bayram-esen-zafer-ev6uq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün bayram

Farz etki sessiz dualarının üstüne gelmişim

Bir derde deva gibi

Bugün bayram

Farz etki ertelenmiş umutlara ışık olmuşum

Karışmış birbirimize bir parça benler

Farz etki bir yürek çırpıntısında bölüşmüşüz özlemleri

Bir sofrada doymuş

Bir aykırılıkta küsmüşüz

Küsmeyen yüreklerimize inat

Bu gün bayram farz etki

El alemdir oyunlardır yenik düştüğümüz

Farz etki özde kaybolmaz bütünlüğümüz

Bugün bayram

Bugün ne kadar kin varsa seni saran

Hiçbir el sıkışta hiçbir sözde

Kıpırdatmayacak olandır içindeki tek teli bile

Umutlarım sevinçlerim gözyaşlarım

Bu günü tüm iyi dileklerimden gayrı yaşatan

O en berbat iç çekişlerime inat

Seninle kaybettiklerim kurbanın

Seninle kazandıklarım hediyem olsun 

Bugün bayram bayram 

Bayramın kutlu olsun', 'Bugün bayram Farz etki sessiz dualarının üstüne gelmişim Bir derde deva gibi Bugün bayram Farz etki ertelenmiş umutlara ışık olmuşum Karışmı...', ARRAY['Türk Edebiyatı','Şiir','Esen Zafer']::text[], 8.5, '{"poet":"Esen Zafer","poet_slug":"esen-zafer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bugun-bayram-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-esen-zafer-gcq27', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hangi göze dalarsan dal

Sevda yoksa derya yoktur

Hangi gönle dolarsan dol

Sırrı çoksa aşkı yoktur

Gülistanda gül çok amma

Gül kokusu gülde yoktur

Bir öz bir öze düşünce

Kıvılcımlar birleşince

Her dokuda ince ince

Arasanda yarin yoktur', 'Hangi göze dalarsan dal Sevda yoksa derya yoktur Hangi gönle dolarsan dol Sırrı çoksa aşkı yoktur Gülistanda gül çok amma Gül kokusu gülde y...', ARRAY['Türk Edebiyatı','Şiir','Esen Zafer']::text[], 8.5, '{"poet":"Esen Zafer","poet_slug":"esen-zafer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/arayis-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'F.f.', 'f-f-sule-aydemir-bbt56', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kalk gidelim diyor zaman

karıncalar iniyor bacaklarına 

biliyorsun

gülümseme yerleşiyor dudaklarına

kaç basamak çıkıp geldin bu ana

düşünüyorsun

insanin boş vakti olur mu diyorsun

gülüyorsun

kırıştırdığın yaşam kıskanıyor seni

zaman bakakalıyor arkandan

her yıla bir yaşam sıkıştırdın

34 yılı devirdin 

yürüyüp gidiyorsun', 'kalk gidelim diyor zaman karıncalar iniyor bacaklarına  biliyorsun gülümseme yerleşiyor dudaklarına kaç basamak çıkıp geldin bu ana düşünüyo...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/f-f-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umarsız yar', 'umarsiz-yar-esen-zafer-pa1nr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yar beklermiş yorgun

Yar beklermiş heyecanlı

Yar umarsız 

umarsız yar

Kim bilir kaçıncı uzayıp gidişi yolların

Kaç umudun durağında mola verdi zaman

Hangi istasyonda uğurladı iki damla yaş

Hangisinde aradı mendil sallayanını

Uykulu uykusuz buğusunda gözlerin

Hangi anılar tazelendi inceden

Hangi arzular sarıverdi sımsıcak

Yollar uzun menzil uzak 

yollar sarsıp uykudan soracak

Bu son dediğin kaçıncı aşk

Hoş geldinler kucaklayıp kucaklayacak

Yar gelirmiş yorgun

Yar gelirmiş heyecanlı

Hey gidi yar

Umarsız yar', 'Yar beklermiş yorgun Yar beklermiş heyecanlı Yar umarsız  umarsız yar Kim bilir kaçıncı uzayıp gidişi yolların Kaç umudun durağında mola ver...', ARRAY['Türk Edebiyatı','Şiir','Esen Zafer']::text[], 8.5, '{"poet":"Esen Zafer","poet_slug":"esen-zafer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/umarsiz-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben sana', 'ben-sana-esen-zafer-5fsy6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben o gözlerinde çakan ışıltılara 

Sesinde çağlayan çağrıya vurulmuştum

Ayrıntıları kaçırmayan dikkatine

Kendimde görüp bilemediğin

Özelliklerimin sende dillenişine

Ben çocuk merakına vurulmuştum

Dürüst ve heyecanlı

Gece gündüz bilmeyen özlemine

Bir anda her şeyi unutan ve unutturan cesaretine

Bitmez tükenmez bilmelerine vurulmuştum

En keskin yargılarımı kırdığın 

sessiz kabullenişlerine

Farklılığın olabilirliliğine

Sende gördüklerime

Ben sana vurulmuştum', 'Ben o gözlerinde çakan ışıltılara  Sesinde çağlayan çağrıya vurulmuştum Ayrıntıları kaçırmayan dikkatine Kendimde görüp bilemediğin Özellikl...', ARRAY['Türk Edebiyatı','Şiir','Esen Zafer']::text[], 8.5, '{"poet":"Esen Zafer","poet_slug":"esen-zafer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekerlekli Sandalye', 'tekerlekli-sandalye-kenan-soyalp-ypk4l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kaza yaptığı bisikletinin 

tekerleklerini taktırdı sandalyesine 

o tekerlekler gibi, 

zincirsiz bağlanmıştı sandalyeye 

artık elleriyle çeviriyordu onları 

gözlerindeki uçurumdan aşağı 

acıyla açan nasırlı güller vardı avuçlarında 

o güllerle dokunuyordu 

uçurumun eteklerindeki bacaklarına 

gene ordaydı tek başına, 

bahçedeki kömürlükte 

aynası oluyordu 

tekerliksiz kalan bisikleti 

kömürlüğün pis camına 

düşen ilk yağmur damlası 

camda izlediği yolla 

iz bıraktı yanağında 

gözlerini dikti 

hissetmediği bacaklarına 

ayağında eskimeyen 

ayakkabıları 

hep aklına geliyordu 

yaramaz çocukluğundan kalan 

oturma cezaları', 'kaza yaptığı bisikletinin  tekerleklerini taktırdı sandalyesine  o tekerlekler gibi,  zincirsiz bağlanmıştı sandalyeye  artık elleriyle çevi...', ARRAY['Türk Edebiyatı','Şiir','Kenan Soyalp']::text[], 8.5, '{"poet":"Kenan Soyalp","poet_slug":"kenan-soyalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tekerlekli-sandalye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle güle', 'gule-gule-esen-zafer-idsm1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umutlarla besledik seni

Hasretle suladık

Uykusuz gecelerle büyüttük çılgınlar gibi

Mutlandık

Neler vermedik ki sana gönüllü

Düşlerimizi 

O yaşlı dünyayı değiştirecek olan

Kavgamızı doğrudan haktan yana

Elimizi emeğimizi

Yarım kalan arzularımızı

Heyecanlarımızı 

hüznümüzü

Anılarımızı kırık dökük

Sırlarımızı verdik çekinmeden

Doymadın aşk

Gidiverdin bir gün ardına baka baka

Oysa alacak bir şeyin kalmadı geride

Bir hüznü var geçen güzel günlerin

Birde acı yorgunluğu kırılıp dökülenlerin

Güle güle aşk güle güle

Sen bir çocuk gibisin

Kızmıyorum sana

Büyüdün artık', 'Umutlarla besledik seni Hasretle suladık Uykusuz gecelerle büyüttük çılgınlar gibi Mutlandık Neler vermedik ki sana gönüllü Düşlerimizi  O y...', ARRAY['Türk Edebiyatı','Şiir','Esen Zafer']::text[], 8.5, '{"poet":"Esen Zafer","poet_slug":"esen-zafer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gule-gule-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum', 'seni-seviyorum-esen-zafer-289gw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mehtap dalgın 

Uzunca bir süre göstermedi yüzünü

Gece bozuk ayaza çalıyor

Sonra ateş basıyor birden

Kalem efkarlı

Şair susukun

Hiçbir söz hiçbir anlatım

Yetmiyor be canım

Derdimi anlatmaya

Seni seviyorum işte şükürler olsun

Seni seviyorum kahrolsun', 'Mehtap dalgın  Uzunca bir süre göstermedi yüzünü Gece bozuk ayaza çalıyor Sonra ateş basıyor birden Kalem efkarlı Şair susukun Hiçbir söz hi...', ARRAY['Türk Edebiyatı','Şiir','Esen Zafer']::text[], 8.5, '{"poet":"Esen Zafer","poet_slug":"esen-zafer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-seviyorum-180-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrık Düşünceler', 'ayrik-dusunceler-hakki-hakan-kaya-687sv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'git,

...

düşüyorsa eğer düşünceler

çatal ağızlı çukuruna

kayboluyorsa aydınlığın

karanlığın gölgesinde

ve hazmetmiyorsa yüreğin

aşkın soğuk yüzünü

yetmiyorsa ayaz bir gecede

sabaha varmak elele

...

git

...

bilki ellerin hep soğuk kalacak...', 'git, ... düşüyorsa eğer düşünceler çatal ağızlı çukuruna kayboluyorsa aydınlığın karanlığın gölgesinde ve hazmetmiyorsa yüreğin aşkın soğuk ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrik-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandıramazsın', 'kandiramazsin-esen-zafer-uplnv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dargınım işte artık kelimelere

Sorma neden diye sorma sus

Sus ki suskunluğun doysun

O çok anlatırmış gibi hallerinle

Bitiremezsin bitmek bilmeyecek sorularımı

Biliyor musun

Kaç monologla doyuramadığım melankolimi

Hani o masalını dinlemeden uyuyamayan

Çocuğun hayranlığıyla 

dinlediğim yaşam öykülerinle

Kandıramazsın bitmek bilmeyecek meraklarımı

Yeni değil küskünlüğüm

Senle değil sensiz değil

Kendimi bildim bileli

Ruhumun her zerresinden bir sürü kelimeyi

Bulup sevgiye verdim

Benim gibi sevsin diye beni

Hani ya her şeyi anlatan kelimelerdi

Dargınım işte

Kaç gündüzü bir ben bir ruhum ayrı yaşadı

Kaç geceden alcaklıyım biliyormusun

Kaç damla kurban ettim gözümün ferinden

Dört bir yanıma sessiz haykırışlarıma çarşafım şahittir

Bu bir günlük beş günlük değil

Bu bin yıllar kadar uzun

Şu kısacık ömrümde

Beni sonsuzlardan alıp sonsuzlara vuran

O doyumsuz arzularımın 

kahrolasıca masumiyetine

Yetersiz kalan kelimelere

Anlatamadığım anlatamayacağım

Anlatılmayan her şeye

Dargınım isyandayım 

Tamam mı!', 'Dargınım işte artık kelimelere Sorma neden diye sorma sus Sus ki suskunluğun doysun O çok anlatırmış gibi hallerinle Bitiremezsin bitmek bil...', ARRAY['Türk Edebiyatı','Şiir','Esen Zafer']::text[], 8.5, '{"poet":"Esen Zafer","poet_slug":"esen-zafer","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kandiramazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve... Fonda!', 've-fonda-i-brahim-ugur-toprak-6re3q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gül daha soldu, ömrümün bahçesinde

Üç beş damla kan, hayat defterinde

Sararan yapraklar dolaşıyor yerlerde

Mazileri saklı geçen meçhul günlerde

Güneş bir kez daha battı

Ve ufuk yine alacalı

Gökyüzü siyah bulutlarla kapalı

Yer bulmak istiyor ay kendine

Yansımak istiyor yeniden denize

Denizler, alabildiğine engin

Tıpkı, gözlerin kadar kadar derin

Al! Yüreğim artık oldu senin

Ve bir yıldız kaydı demin

Gönlümün derinliklerinden

Akan bir kaç damla yaş gözlerimden

Bir parça alıp götürdü benden

Kumsala vuran her dalga

Hatırlatır seni bana

Sanki, seni sayıklarlar

Sanki, senin için çağlarlar

Seninle çoşan yüreğim

Yine seninle ağlar

Güneş doğmasa,

Ne olur? sabah olmasa

Sen yoksun ki yanımda

Vuran her dalga

Adını yazıyor kumsala

Ve ekliyor:

''Bu gönül sevdalı sana''

Bilmiyorum ne yapmalı? 

Ne yapmalı da, tekrar seninle olmalı? 

Bir gemi kalkar yüreğimin derinliğinden

Toplar herkesi yolu sevgiden geçen

Çok özledim oranın mehtaplı akşamlarını

Zaten, bir tek yüreğim kaldı oralı

Özledim seninle geçen güzel günleri

Özledim herşeyini, özledim seni

Hani, olursun ya! 

Bazı an sevinçli, bazı hüzünlü

İşte, yine öyle bir gündü

Oturdum kumsala

Ve meydan okurcasına anılara

Seni yazıyorum kumlara

Beni yazıyorum sayfalara

İçimi kapladı, tarifsiz bir duygu

Acaba, özlem bu muydu? 

Hasret miydi bu? 

Bilmiyorum! 

Ama, bildiğim bir tek şey var benim

Seni seviyorum sevgilim

Biliyor musun sevdiğim? 

Hep sen düşüyorsun aklıma

Dalgalar vurduğunda kumsala

Ve bir müzik çalıyor fonda:

''YÜRÜMEK KARDA ZORDUR

GELİRSEN BAK AŞK BUDUR! ..''

30.09.98/Çarşamba

20:00/Tekirdağ', 'Bir gül daha soldu, ömrümün bahçesinde Üç beş damla kan, hayat defterinde Sararan yapraklar dolaşıyor yerlerde Mazileri saklı geçen meçhul g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/ve-fonda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Ne Denli Özledim Bir Bilsen...', 'ne-denli-ozledim-bir-bilsen-abir-zaki-o118p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay ışığı beni kendine çekerken 

Akıntının hafif sesini dinleyip 

Ve nefes alışını hayal ederken 

Bana bakıp gülümseyen yıldızlar gördüm 

Geceleri uykulardayken 

Birden, 

Rüzgar fısıldadı 

Adını yankıladı melekler cennetten 

Sabırlı ol 

Uzun çilene katlan diyerekten 

Fakat hiç biri, 

Ruhunun derinliklerinde kaybolmuş 

Azat edilmeyi bekleyen 

Benim seni ne denli özlediğimi bilemezdi 

Ben hala, 

Sarılmanla duygularımın ateşli hayaliyle 

Dokunuşunun sıcaklığını hissediyorum 

Ben hala, 

Aşkının tutsağı olma hayaliyle 

Tutkunun yoğunluğunda kavruluyorum 

Ben hala, 

Öpüşlerinin verdiği sarhoşlukla 

Dudaklarımdaki mutluluk hayaliyle 

Dilinin dokunuşunun tatlılığında duyduğum 

Tada can atıyorum 

Ben hala, 

Akan göz yaşlarının 

Adımı sayıklamasını 

Beni istediğini 

Ve ruhumu tutuşturduğunu biliyorum 

Ve ben hala 

Gümüş alevli ayın 

Gözlerinden arta kalan aşkının 

Gölgesini özlüyorum...

Çeviren: Mehmet Bardakçı

24 Nisan, 2004', 'Ay ışığı beni kendine çekerken  Akıntının hafif sesini dinleyip  Ve nefes alışını hayal ederken  Bana bakıp gülümseyen yıldızlar gördüm  Gec...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ne-denli-ozledim-bir-bilsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiler ölmez', 'sevgiler-olmez-i-lkgul-celebioglu-v1iwr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırakında dalında solsun çiçekler

onlarda mukadder ölüm suyunu içecekler

ölümsüzlüğün bir kapısı olmalıdır ki bu,

çiçeğe ecel gelirken,o''na olan sevgiye gelmemektedir.

o,geceyi gündüze çeviren perde,

o çaredir,çare bulunamayan derde.

sırrı ilahi bir esintisi olmalıdır ki bu,

fani dünyada sevgi,feza gibi sonsuz

yaşamak ne ifade ederdi,bilmem ki o''nsuz....

Not:Teşekkürler Ahmet ÇİÇEK', 'Bırakında dalında solsun çiçekler onlarda mukadder ölüm suyunu içecekler ölümsüzlüğün bir kapısı olmalıdır ki bu, çiçeğe ecel gelirken,o''na ...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgiler-olmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Akşamüstü', 'dun-aksamustu-i-brahim-ugur-toprak-no6e0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir mezar kazdım dün akşamüstü

Seni andıran, sana ait olan ne varsa gömdüm

Seninle beraber

Bir mezar kazdım dün akşamüstü

Düşlerimi, hayallerimi gömdüm seninle

Şarkıları, şiirleri gömdüm kendimle

Bir mezar kazdım dün akşamüstü

Dünleri, anıları gömdüm

Seninle beraber

Bir mezar kazdım dün akşamüstü

Tasayı, gözyaşını gömdüm seninle

Sevgimi, aşkımı gömdüm kendimle

Dün akşamüstü bir mezar kazdım

Üstelik yağmur da yağıyordu

Üstelik büsbütün de ıslanmıştım

26.05.99/Çarşamba

21:04/Tekirdağ', 'Bir mezar kazdım dün akşamüstü Seni andıran, sana ait olan ne varsa gömdüm Seninle beraber Bir mezar kazdım dün akşamüstü Düşlerimi, hayalle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dun-aksamustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaklı Sevgilim', 'yasakli-sevgilim-ayse-tural-7ly9h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen 

Düşlerimdesin

Ben de 

Senin düşlerinde

Biliyorum.

Ellerini tutamam

Sıcacık...

Aşkımı söyleyemem

Çağlayanlar misali...

Kucağında olamam 

Sarmaş dolaş

Uzanamam dudaklarına

Kor gibi,alev gibi.

Ama

Dilediğimce 

Bakabilirim gözlerine...

İstediğimi düşünebilirim 

Özgürce...

Her şey

Beyinde başlar dememişler boşuna....

Yasaklı sevgilim benim....', 'Sen  Düşlerimdesin Ben de  Senin düşlerinde Biliyorum. Ellerini tutamam Sıcacık... Aşkımı söyleyemem Çağlayanlar misali... Kucağında olamam ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasakli-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Bırakacağım', 'sana-birakacagim-ayse-tural-jl47b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün 

Çekip giderken

Ellerimi sana bırakacağım

Umutlarınla asıl diye....

Soğuk kış rüzgarları

Ruhunu titretirken

İliklerine işlemiş yağmurlarla

Saçlarındaki kar taneleri

Ölmesin diye

Gözlerimi sana bırakacağım....

Ardımdan sen

Ayrılık mumları yakarken

''Elveda'' deyip

Yüreğimi sana bırakacağım...

Günlerden bir gün,

Apansız

Demirlemek için limanına

''Seni seviyorum'' larımı 

Sana bırakacağım....', 'Bir gün  Çekip giderken Ellerimi sana bırakacağım Umutlarınla asıl diye.... Soğuk kış rüzgarları Ruhunu titretirken İliklerine işlemiş yağmu...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sana-birakacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kız', 'kucuk-kiz-ayse-tural-tcagw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ellerinden tuttuğun küçük kız

ürkek

ağlamaklı

yalnızlığını bir yük gibi taşıdı.

yalnızlığında sen....

sevgisi

eskimiş  zamanlarda tutsak...

şimdi

aynalarda küçük kız

özlemleri de kendiyle yürüdü.

gözlerinde hep

gözlerinin menevişi yüklü

küçük kız artık büyüdü....', 'ellerinden tuttuğun küçük kız ürkek ağlamaklı yalnızlığını bir yük gibi taşıdı. yalnızlığında sen.... sevgisi eskimiş  zamanlarda tutsak... ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kucuk-kiz-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir dua, birkaç mısra.', 'bir-dua-birkac-misra-burak-cicek-gkffu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgi hırsızıyım ama

Ne haki bir tesadüf ki bu

Yine kendimden çalıyorum suni teneffüs oksijenimi.

Susadım...

Susmadım aslında erteledim veya kimilerine göre de ertelendim.

Ben dümeni kırık bir Mercedes’im.

Ki Mercedes dediysem öyle eski model bi’şey.

Bir tek şey daha söyleyeyim... 

“Bir şarkısın sen” diye başlamayan.

“Elveda” diye bitmeyen.

“MERHABA”

Güler yüzle bir -merhaba demeyeli

Buradan Bağdat’a yol oldu.

Kim bilir bu laf hangi tarihi dönemde ilk kez kapak oldu? 

“ELVEDA” diye bitiyor maalesef yine.

Ritüel böyle, Amerika’yı yeniden keşif gereksiz, Amerikyum (AM)  tartışılır.

Neyse şey...

Çünkü aslında asla kabul etmezdim.

Bahtsız bir veda, şartsız elveda.

Güle güle gidiyorum, Allah’a emanetim

Bir dua ve birkaç mısra.', 'Sevgi hırsızıyım ama Ne haki bir tesadüf ki bu Yine kendimden çalıyorum suni teneffüs oksijenimi. Susadım... Susmadım aslında erteledim veya...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-dua-birkac-misra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Takvim Hazır Rafta', 'yeni-takvim-hazir-rafta-necmi-unsal-rt7ze', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kazançlar,  yitikler...

Dimdikler,  bitikler...

Yenen,  yenilen

Kazanan,  kaybeden

Zafer  sarhoşu  yenen.

Keder  tablosu  yenilen.

Bir  nokta  hayatın  özeti.

O  nokta  ruha  çözelti.

Nedir  bu  afra  tafra? 

Herkes  ayrı  bir  safta.

Ömürler  boyunlarda

Geçici  bir  yafta.

Aya  yaklaşır  günler

Hafta  hafta.

Zamanda  bozuk  frenler.

Yıl  mı  dedim  erenler? 

Eskisi  gidiyor,

Yeni  takvim

Hazır  rafta...

1 Nisan 2004 Perşembe, Danimarka-Køge 22.20', 'Kazançlar,  yitikler... Dimdikler,  bitikler... Yenen,  yenilen Kazanan,  kaybeden Zafer  sarhoşu  yenen. Keder  tablosu  yenilen. Bir  nokt...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeni-takvim-hazir-rafta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeri Bilinmeyen Sevgili', 'yeri-bilinmeyen-sevgili-hasan-arican-3igqz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlüm sevdiğini tam bulmuş iken

Güneşim doğarken hava karardı

Tam mutluluğa sahip olmuş iken

Her şey alt üst oldu benzim sarardı

Menzil bilmem nerde  ben burda kaldım

Tek bir gün görmedim gamlarla doldum

Çok umut besledim havamı aldım

Sevip sevilmeden dünyam karardı

Yanan yüreğimi söndürenim yok

Kötü talihimi döndürenim yok

Yarden tek bir haber bildirenim yok

Gönlüm sevdiğini her dem sorardı

SAHİPLİ’ye onun sözü fermandır

Hastayım, sevgisi bana dermandır

Anlamazsa benim halim dumandır

Ondan başka her şey bana zarardır.

22.4.2004', 'Gönlüm sevdiğini tam bulmuş iken Güneşim doğarken hava karardı Tam mutluluğa sahip olmuş iken Her şey alt üst oldu benzim sarardı Menzil bil...', ARRAY['Türk Edebiyatı','Şiir','Hasan Arıcan']::text[], 8.5, '{"poet":"Hasan Arıcan","poet_slug":"hasan-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeri-bilinmeyen-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Tanıdım', 'kendimi-tanidim-ayse-tural-qabl5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni tanıdım

Seninle....

Güneş ıslağıydı kaldırımlar

Gözlerin

Buğulu aşklar vadediyordu

Tıpkı sesin gibi...

Seni tanıdım 

Seninle...

Küçük zaman kırıntılarıydı

Paylaştığımız.

Hepsini

Yoğunlaştırdım

Zenginleştirdim

Ta yüreğimde...

Ben de yüceldim

Duygularım da...

Seni tanıdım 

Seninle...

Küçük sevinçler yakaladı beni

Yeni baştan yaşadım 

Geceyle gündüzü

Mevsimler sende içiçeydiler

Tıpkı duygularım gibi

Hangisi yaz

Hangisi güz

Belli değil...

Seni tanıdım 

Seninle...

Bir uçurtmanın 

Rengarenk kuyruğundaydı

Umutlar...

Gökyüzünün rengini içerken

Sarhoştum...

Seni tanıdım

Seninle...

Yaşanmamış dünleri

Yarınlara ekledim.

Delice düşlerimle

Afacan sevgini tanıdım.

Dişlerim kamaştı tadından.

Aslında ben

Seninle

KENDİMİ tanıdım....', 'Seni tanıdım Seninle.... Güneş ıslağıydı kaldırımlar Gözlerin Buğulu aşklar vadediyordu Tıpkı sesin gibi... Seni tanıdım  Seninle... Küçük z...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kendimi-tanidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saplanır Kirpiklerin İçime İçime', 'saplanir-kirpiklerin-i-cime-i-cime-muammer-celik-qz5xl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Harcanmamış bir fer var o gözlerinde bilirim

el değmemiş sığ bakirelik akıyor bakışlarından

yüzyirmidörtbin erkek eli değmiş olsada...

Yanmamış ateşlere gebe yüreğin bilirim

tetiklenmeye hazır bekliyor göğüs uçların...

Ne duruyorsun 

„vur beni gözlerimden diyor“

 yüzündeki gamze çukurların

yüzyirmidörtbin erkeği alnından 

vurmuş olsa da kirpiklerin, bilirim...

BirDeli

26.04.2004', 'Harcanmamış bir fer var o gözlerinde bilirim el değmemiş sığ bakirelik akıyor bakışlarından yüzyirmidörtbin erkek eli değmiş olsada... Yanma...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saplanir-kirpiklerin-icime-icime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ayse-tural-7z120', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin

Ayrılık türkülerine durmuş

İçin sızım sızım...

Aşkın buruk tadı

Damaklarında...

Bir öylesin,bir böyle

Bilinmezlerde...

Yüreğin telaşlı,çarpıntılı

Yol ayırımında bir kelebek,

Yaşamın penceresinde

Gitmekle kalmak arası....', 'Gözlerin Ayrılık türkülerine durmuş İçin sızım sızım... Aşkın buruk tadı Damaklarında... Bir öylesin,bir böyle Bilinmezlerde... Yüreğin tela...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayrilik-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştığımız Bir Şeydi Yaşamak', 'alistigimiz-bir-seydi-yasamak-ayse-tural-15l43', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Su suydu işte

Kana kana içtikçe

Pek ardı sorulmazdı....

Ekmek de ekmekti işte

Karın doyurdukça

Gerisi aranmazdı....

Para yetmeyince 

Çekilirdi sıkıntısı geçimin

Yine de

Alıştığımız bir şeydi yaşamak....

Kız-oğlan evlenmeliydi

Düğün-dernekle

İşler büyütülmeli

Bitmeyen bir emekle

Paralar paralara eklenmeliydi....

Derken 

Hay-huyla geçiverdi zaman.

Kayıp gidince 

Avucumuzdaki sevgiler

Ellerde güç

Ayaklarda derman kalmayınca.

Dostlar da

Birer birer

Dönülmez ufuklara gidince...

Yalnızlık

Kor gibi yaktı yüreğimizi

ÖLÜM

Aklımıza düştü.

Oysa 

Alıştığımız bir şeydi yaşamak....', 'Su suydu işte Kana kana içtikçe Pek ardı sorulmazdı.... Ekmek de ekmekti işte Karın doyurdukça Gerisi aranmazdı.... Para yetmeyince  Çekilir...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/alistigimiz-bir-seydi-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandırma', 'kandirma-ayse-tural-dumci', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerin

Başka ellerin sabırsızlığındaysa

Gözlerin

Başka bkışların çağrılısıysa

Yüreğin

Ritmini değiştirmiş

Başka tempoları vuruyorsa

Sen bir başkaysan

Bu aşk bitmiş demektir

Kendini kandırma....', 'Ellerin Başka ellerin sabırsızlığındaysa Gözlerin Başka bkışların çağrılısıysa Yüreğin Ritmini değiştirmiş Başka tempoları vuruyorsa Sen bir...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kandirma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Esmerim*', 'esmerim-kubilay-enginol-5363e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Esmerim

Sana ne diyeyim

Ciğerim seni görünce yanıyıor

Ben şimdi neyleyim

Gözlerin bakıyor buğulu

Yüzün zaten gizem dolu

Ay parçası haltetmiş kaşların

Çevrelemiş güzelliğini,siyah saçların

Sana kitaplarca şiir yazsam doyamam

Resmine bakmaya kıyamam

Sana bir diyebilsem,sevgilim

Aşığım ben sana,esmerim', 'Esmerim Sana ne diyeyim Ciğerim seni görünce yanıyıor Ben şimdi neyleyim Gözlerin bakıyor buğulu Yüzün zaten gizem dolu Ay parçası haltetmiş...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/esmerim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiracı', 'kiraci-ayse-tural-t3iao', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin dünyanda ben

Kendimi kiracı gibi hissediyorum.

Kontratım belli değil

Ya erken bozulursa

''Çık git'' deyip

Kapı önüne koyarsan beni....

İyisi mi ben

Kendi gönlümle 

Çıkıp gideyim...', 'Senin dünyanda ben Kendimi kiracı gibi hissediyorum. Kontratım belli değil Ya erken bozulursa ''Çık git'' deyip Kapı önüne koyarsan beni.... İ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kiraci-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Dünmüdür', 'dun-dunmudur-ozan-eldeniz-pyd9u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Taşıma 

         suyla dönüyor 

                  değirmenler 

Lafla yürüyor 

Peynir yüklü gemiler 

Yılan zaten dokunmaz 

Yaşları 

         bulur binler 

Damlar 

         oluşmaz 

Yerinde 

            göller … 

Ata! 

    ya  uymuyoruz 

                     sözüne 

ya dönüp söylenmeli 

              yeniden günümüze …', 'Taşıma           suyla dönüyor                    değirmenler  Lafla yürüyor  Peynir yüklü gemiler  Yılan zaten dokunmaz  Yaşları           ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Eldeniz']::text[], 8.5, '{"poet":"Ozan Eldeniz","poet_slug":"ozan-eldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dun-dunmudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişe vesika olsun', 'gecmise-vesika-olsun-burak-cicek-vbidu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şendiler,

Şemdinlililer,

Şeyden önce...

Ne vakur bir gençlik.

Savaş kan.

Kana kan bir kan davasını güden puştlar.

Ve puştlara köle olmuş masum kuşlar.

Yani bizim çocuklar...

Kaç mısra yazıldı kim bilir bu davaya,

Akan kanlardaki akyuvar sayısı kadar kelime döküldü istatistiki olarak.

Hep boş masal sandık

''Hepimiz kardeşiz'' repliklerini.

Oysa replik değilde söyleyenler boşmuş, söyleyenler baron.

Vurulan uçan balon.

Kan kırmızıymış.

Anımsamıştık, hafızalarımıza kazıdık.

Artık unutamayacağız. Toplu bir psikiyatri seansına külliyen ihtiyaç gerçeği! 

Bir avuç toprak ''Vatan Toprağı''

İki varil petrol.

Ne ucuz yasıyoruz...

Bir yanda gecekondulu ''metro city''

Diğer yanda çocuklar yalınayak.

Geçmişe vesika olsun. Bir şeyler unutulamaz üzeri boyanarak!', 'Şendiler, Şemdinlililer, Şeyden önce... Ne vakur bir gençlik. Savaş kan. Kana kan bir kan davasını güden puştlar. Ve puştlara köle olmuş mas...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gecmise-vesika-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-sirma-mersin-di77a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni unutmak adına...

Terketmek istiyorum, bu şehri! 

Yüreğimi kanatan acıları,

Sana ait hayalleri,

Adını sevgi sandığım; yalancı mutluluğumuzu,

Terketmek istiyorum, bu şehri...

Adım adım dolaştığımız sokaklarında bile; 

Sana ait geçmiş günler, canlanıyor! 

Şimdi! 

Bu son otobüsle veda ediyorum,

Dahası terkediyorum...

Seni ve bu şehri.

Bir dönmemek üzere! 

25.04.04', 'Seni unutmak adına... Terketmek istiyorum, bu şehri!  Yüreğimi kanatan acıları, Sana ait hayalleri, Adını sevgi sandığım; yalancı mutluluğum...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-sehir-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Senden, Nede Sana', 'ne-senden-nede-sana-sirma-mersin-nhpd0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne senden uzaklaştım,

Nede sana yaklaştım....

Hep bir mesafede durdum.

Aramıza giren mesafeler, uzak! 

Bizi birbirimize yakınlaştıran konuşmalar kadar, yakındım...

Sen bir adım geldin, bana.

Bense on adım geldim, sana.

Ben seven, sen sevilen oldun, hep.

Adı konmamış bi ilişkinin; tadını yaşıyoruz...

Kısa mutlulukların arasına sıkıştırdığımız özlemler olsada; 

Hüzne teslim ettiğimiz hayallerle, yalnızlığa bıraktık, ruhumuzu...

Ansızın gelişin, birden bire gidişin; 

İçine düşürdüğümüz bi zamanda, yeniden buluşacağız...

Biz! Seninle bir yerde...

25.04.04', 'Ne senden uzaklaştım, Nede sana yaklaştım.... Hep bir mesafede durdum. Aramıza giren mesafeler, uzak!  Bizi birbirimize yakınlaştıran konuşm...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-senden-nede-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Sadık-', 'sadik-halit-demir-txfsx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sadık’ın gönlünde güller açınca

Dost elin bağına sevgi sununca

Böyle bir şiire imza atınca

Alnından öpüp te kutlamak gerek

Sadık yüreğine ateşler atar

Gülistan içinde tomurcuk arar

Yüreği sevgiyle ışıklar saçar

Yüreğini öpüp te kutlamak gerek

Sadık sinesinde, sine gizlermiş

Âşiyân-ı harâb, bi-tâp gezermiş

Sesinde sır gizler, figân edermiş

Sesini dinleyip kutlamak gerek

Bu şiirim değerli dost,üstât  Sadık SOFTA’ya ithaf olunur', 'Sadık’ın gönlünde güller açınca Dost elin bağına sevgi sununca Böyle bir şiire imza atınca Alnından öpüp te kutlamak gerek Sadık yüreğine at...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye tutunamayan bir yıldızdan', 'geceye-tutunamayan-bir-yildizdan-semih-tanriver-reuj1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceye tutunamayan bir yıldızdan 

Neler umardın 

Kim bilir? 

Şaşkın bakışlarımda 

Çocuk umutların...

Bir de beni çekiştirmen yok mu

Sen de tut bir dilek diye

Bak bir yıldız kayıyor

Ve ilk kez bir dilek tutuyorum.

O eksikse 

Ben çok fazlayım diyorum

Ya kimse duymuyor

ya da anlatamıyorum', 'Geceye tutunamayan bir yıldızdan  Neler umardın  Kim bilir?  Şaşkın bakışlarımda  Çocuk umutların... Bir de beni çekiştirmen yok mu Sen de t...', ARRAY['Türk Edebiyatı','Şiir','Semih Tanrıver']::text[], 8.5, '{"poet":"Semih Tanrıver","poet_slug":"semih-tanriver","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geceye-tutunamayan-bir-yildizdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ak Sakallı Adam(1)', 'ak-sakalli-adam-1-halil-manap-ikpg6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'büyük dedem söylerdi 

..............................ceketini 

..................................satmadan 

...............................................önce 

ak sakalıyla oynarken düşlemişti

kapital''in 

.........aklanmayan 

.........................düzenini 

........................doğa''nın diyalektiğinde de 

mırıldanırdı 

........keçe beyazı 

.........sakalını okşarken 	

...............................usulca

kutsal aile”nin 

.................temeli atılmış mıydı 

............................................acaba 

hegel ''in ters masasında 

..................................bacakları 

.............................................havada, 

eytişimin 

…….özündeki tözü 

……………..özümseyerek 

feurbach ''in kaba kabuklarını kırarken 

.......................................baş döndüren devinim 

sonsuzlukta çıldırmıştı 

...................kainattan daha çok 

...........................gittikçe genişleyerek 	

..................................................içime doluyordu 

zamanla 

……….sakallını 

……………..okşamayı da unutmuştu 

ürpererek düşledi 

………………ana rahminde 

………………………..yaşamıştı evrimi

Darvin”in türlerini incelerken 

……………………….ayrı tutmadan

………………………………..eşitlemişti cinsleri

İnsanlık yeniden türemişti

…..

En büyük cevher 

……………..insanlığın 

……………………yapılmalıydı 

………………………………….devrimi

Ak sakallı adamın 

………………felsefesi 

……………………….aşk 

……………………….aşkın felsefesi yaşam 

…………………………………..sana bin selam 

………………………………………….ak sakallı adam

Bak hala deviniyor yaşam 

…………………..sen olmadan da

………………………….güne dönüyor akşam

bu yüzden 

………….en büyük davam 

………………………insan olmaktır 

………………………………….sevgili ustam

karanfil kokulu sevgiliyi 

……………koynumda saklıyorum 

………………….her an öperek eytişimin gibi 

………………………………………..deviniyorum

evrimleşip değiştim

……………emekle yoğrulup 

…………………………devrimleşmeye 

…………………………………..bir öpücük kadar 

………………………..……………………..yakınlaştım 

………………………………………………………USTA 

düşlerimde 

……….ak sakalını okşuyorum 

……………..insanlığın tarihini okşar gibi 

……………………………..ve okşadıkça 

…………………………………kısa pantolonlu 68 kuşağı gibi 

………………………………………………………..coşuyorum

26.04.2004 

Kuşadası', 'büyük dedem söylerdi  ..............................ceketini  ..................................satmadan  .....................................', ARRAY['Türk Edebiyatı','Şiir','Halil Manap']::text[], 8.5, '{"poet":"Halil Manap","poet_slug":"halil-manap","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/ak-sakalli-adam-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta', 'nokta-koksal-akar-xrhpn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vardığım en son ölüm,varlığındaki nokta...

Vardığım son noktanın başlangıcı bu nokta.

24/04/2004 - İzmir', 'Vardığım en son ölüm,varlığındaki nokta... Vardığım son noktanın başlangıcı bu nokta. 24/04/2004 - İzmir...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/nokta-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALAN DüNYA', 'yalan-dunya-baki-son-jatd1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlgilendirmiyorsun beni...

Ağaçlar varmış,

Kuşlar varmış...

Bana ne.! 

Mutlu...

İnsanlar varmış,

Güya...

Kimi kandırıyorsun.? 

Hey gidi,

Yalan dünya..!', 'İlgilendirmiyorsun beni... Ağaçlar varmış, Kuşlar varmış... Bana ne.!  Mutlu... İnsanlar varmış, Güya... Kimi kandırıyorsun.?  Hey gidi, Yal...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalan-dunya-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UsANÇ', 'usanc-baki-son-k3yyn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen...

Gönlümü kemiren hayalet.! 

Bırak peşimi artık

Rüyalarımı bırak,

Ellerimi bırak,

Gölgemden çık..!', 'Sen... Gönlümü kemiren hayalet.!  Bırak peşimi artık Rüyalarımı bırak, Ellerimi bırak, Gölgemden çık..!...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/usanc-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala sen misin?', 'hala-sen-misin-nazim-ercan-vhwz1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'HALA SEN MİSİN? 

Bir çift mahzun gözbebeğiydin sen

Belki, belki birazda deli fişek bir yürek

Ve

Sendeydim ben, sensiz ve sessiz

Hıçkırıklarını yorumlamaktı zevk olan

Gülücüklerini bazen de

Ve

Sevdiğim bir şarkıyı söylemekti seni sevmek

Bakardın

Yalnızca bakardın bana

Hissederdim

Konduramazdım

Sevmeli miydin beni? 

Yani

Bendim işte bir basit ben

Hatırla

O akşam öptüm ilk seni

Titreyen bir bedendim artık,

Bir gezegen belki de titrek dönüp duran yörüngende

Ve sen

Hey sen

Sev beni

Yine sev

Sev

Hep sev

Sonbahar 2001', 'HALA SEN MİSİN?  Bir çift mahzun gözbebeğiydin sen Belki, belki birazda deli fişek bir yürek Ve Sendeydim ben, sensiz ve sessiz Hıçkırıkları...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hala-sen-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-fatih-buyukdag-of7hy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sende aradım,

Yoktun.....

Sen bendesin,

Ruhumda ve kalbimde....

Çık git desem nafile,

Bütün umutsuzluklarımla

Beni sende bıraktın....', 'Seni sende aradım, Yoktun..... Sen bendesin, Ruhumda ve kalbimde.... Çık git desem nafile, Bütün umutsuzluklarımla Beni sende bıraktın.......', ARRAY['Türk Edebiyatı','Şiir','Fatih Büyükdağ']::text[], 8.5, '{"poet":"Fatih Büyükdağ","poet_slug":"fatih-buyukdag","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-ve-ben-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir adam', 'bir-adam-nazim-ercan-chzaz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Belli; incinmiş bir yürekti adam…

Bir sahilindeki bir bankında ağlıyordu oturmuş Yeditepelinin. 

Bir çift insan gördü yalnız onu. 

Ağlıyordu. 

Korktu genç, 

olanı biteni soramadı derdinin ne olduğunu, 

alacağı cevaptan duymak istemediklerini duymaktan korktu. 

Korkmalı mıydı yoksa; 

yoksa oda mı ağlamalıydı.¿

Hayır; 

Yapmadı sormadı yürüdü yalnızca genç olanlar, 

hiç konuşmadan sessiz 

dalgalara eşlik ederek yürüdüler yalnız. 

Ağlıyordu adam. 

Yürüdüler, 

adam ağladı 

onlar yürüdü adam hep ağladı,

dalgalarsa hep tebessümdeydi yüreklere, 

yürüdüler adam genede ağladı. 

Yoktu döndüklerindeyse adam,

başka bir bankta başka bir çift insanın yanında.

AĞLIYORDU. 

									İlkbahar 2002', 'Belli; incinmiş bir yürekti adam… Bir sahilindeki bir bankında ağlıyordu oturmuş Yeditepelinin.  Bir çift insan gördü yalnız onu.  Ağlıyordu...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-adam-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yengecin karabasanı', 'yengecin-karabasani-nazim-ercan-xa0ml', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yutkundum

Yoksundum çünkü uykularımdan

Ve; 

Tanrıların kovaladığıydım

Bir rüzgar geçidini izliyordum

Gölgelerin oynaştığı yıldırım’ı

Sabahlara dek gölgelerle konuşup, 

gece kuşlarını gözetlediğim geceleri hatırlıyorum.

Kara bir yıldızdı kalbim iskeletimin içinde

Savaşçı bir prens, şatosunda gözlerimin.

Yosunlar ekerdim denizlere

Yumurta çalan bir tilkiydim bir zaman ejderha yuvalarından

Oyuk gözlerimin içinde gördüğüm bir düştü yaşam

Sırılsıklam ıslanmış bir yağmur sonrası.

						

Kış 1996', 'Yutkundum Yoksundum çünkü uykularımdan Ve;  Tanrıların kovaladığıydım Bir rüzgar geçidini izliyordum Gölgelerin oynaştığı yıldırım’ı Sabahla...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yengecin-karabasani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşunladılar Rüyalarımı', 'kursunladilar-ruyalarimi-nazim-ercan-zm8w5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurşunladılar rüyalarımı

Güneşindoğumuna yakın

Kırmızı gözlü cüce

Kopuk bir baş gibi yuvarlandı önüme

Tamtamların sesini duyuyorum 

Sisten pelerin giymiş gecede

Yıldızlar savaş dansı yapıyor

Güneş doğum sancısında

Halley saplandı sol gözüme

Sıkmaya başladı gök kuşağı gırtlağımı,

Sanki birer kurt olmuş her yıldız

Saldırıyor büyük ayı

Kurşunladılar rüyalarımı

Güneşindoğumuna yakın

Cehennemi giyinmiş bir çöl de 

Akbabaların yörüngesi benim şimdi.

Sonbahar 1993', 'Kurşunladılar rüyalarımı Güneşindoğumuna yakın Kırmızı gözlü cüce Kopuk bir baş gibi yuvarlandı önüme Tamtamların sesini duyuyorum  Sisten p...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kursunladilar-ruyalarimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-nazim-ercan-e5402', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay vadisinden aşağı sallanan yıldızlar! ...

Şu alaca sabahta yalnızlığımı

Bir körük misali üfleyip duran benliğim.

Kimbilir kaçıncı sabahtır bu

Dudaklarımda bir ıslıkla karşıladığım.

Kimbilir kaçıncı sesleniş uykulu gözlerle

Uzaklardan da öteye ta belirsizliğe.

Çok uzun zamanlardan beri 

Yazmayı düşündüğüm bir mektuptu bu.

Evet bebeğim diye başlayıp

Yalnızlık armonileriyle devam eden

Ve

Seni seviyorum diye biten

Seni seviyorum

Kış 1996', 'Ay vadisinden aşağı sallanan yıldızlar! ... Şu alaca sabahta yalnızlığımı Bir körük misali üfleyip duran benliğim. Kimbilir kaçıncı sabahtır...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-seviyorum-181-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-nazim-ercan-pxxps', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşlerimin şemsiyesine sığınıyorum

Sensizlik yağmurlarından

Bir alaca gök, 

Yapraksız fakat yemyeşil bir ağaç yalnızlığım.

Motor sesleriyle irkiliyorum düşlerimden

Birdaha geç yatmayacağım

Rüyamda göremiyorum seni.

Yazmayı unutan bir kalemim artık,

Konuşmayı unutan bir dil,

Yanıp sönen ışıklar etrafında 

Dönüp duran bir pervaneyim.

Dün gece uçmayı öğrendim

Ta buradan kalkıp yatağına geldim

Sabaha dek uykunda seni seyrettim.

Kış 1996', 'Düşlerimin şemsiyesine sığınıyorum Sensizlik yağmurlarından Bir alaca gök,  Yapraksız fakat yemyeşil bir ağaç yalnızlığım. Motor sesleriyle ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dus-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlardı Dostlarım', 'yildizlardi-dostlarim-taner-dondurmaci-ob0ip', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.

Dostlarım vardı bir zamanlar

Dost bildiklerimde vardı etrafımda

Yıldızlar kadar çok

Sanki ben bir gezegen

Etrafımda onlar

Her ne kadar bulutlansa da hava

Aradan bir iki tanesi mutlaka gözükürdü

Sevinir, avunurdum o bir iki tane ile

Ama şimdi çöktü kara bulutlar

Gör görebilirsen dost yıldızları

Nerede o eski gökyüzü nerede

Nerede o hangi yıldıza baksam,

Hangisi ile konuşsam dediklerim nerede

Sanırım şimdi sözleşmiş gibi hepside

Yıldızlık yapıyorlar başka bir gezegende', '. Dostlarım vardı bir zamanlar Dost bildiklerimde vardı etrafımda Yıldızlar kadar çok Sanki ben bir gezegen Etrafımda onlar Her ne kadar bul...', ARRAY['Türk Edebiyatı','Şiir','Taner Dondurmacı']::text[], 8.5, '{"poet":"Taner Dondurmacı","poet_slug":"taner-dondurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yildizlardi-dostlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalma Hali Uykularına Gözlerimin', 'dalma-hali-uykularina-gozlerimin-bekir-mutlu-gokcesu-kp6xz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I

Dalma hali şiir gözlerine gözlerimin

Şu sessizliğe üç beş ses kalan lahzada

İtiraflarımın tüm gizlerimi soyma hali

Uzandığım dizlerinden geniş zamana

Haykırışlarımın seni seviyorum hali... 

İç çekme hali saçlarımda gezinişine ellerinin

Masalım, misalim, sana uçma hali düşlerimin

Şiirsi fısıltılarının okşayışlarında kalma

Tebessümün dudaklarımda yayılma hali

Sana aşkımın her hali bu hallerim...

Direnişi gözlerimin ve dilimin dolaşma hali

Sayıklanma zamanı sana koşan sözcüklerimin

Sende kaybolmaya müptela hallerimin

Dalma hali uykularına gözlerimin...

...

II

Sese iki üç sessizlik kala 

Uyandığımda kokunla, yoktun...

Bir buse bırakmışsın avucuma

Ve mahzunluğuma...

Kurmuşsun saatleri kim bilir? 

Kaç yitik zamanlar sonrasına

Donup kalma hali bu düşlerimin

Ve dudağımdaki gülüşlerin

Dayanılmaz yokluğunda kaybolma

Dalma hali uykularına gözlerimin...', 'I Dalma hali şiir gözlerine gözlerimin Şu sessizliğe üç beş ses kalan lahzada İtiraflarımın tüm gizlerimi soyma hali Uzandığım dizlerinden g...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dalma-hali-uykularina-gozlerimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katli Vacip Usumun', 'katli-vacip-usumun-nazim-ercan-l370o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşliyor gergefi hüznün

Puslu bir sabahın karşısında,

Kaçıncı sezinleyişimdir o’nu.

Çarmıha geriyorlar kulaklarımı ve 

Gözlerimi ayrı ayrı.

Bir film izliyorum,

Biraz müzik daha sonra.

Köpürmüş bir dalga vuruyor ruhuma.

Gölgemi izliyorum,

Takibindeyim ruhumun.

Usumda planlarla yürüyor,

Henüz yazılmamış bir tarihi okuyorum.

Ölümüme sebep kelimeler bunlar.

Yinede! 

Söylüyorum.

Katli vaciptir usumun! .

Çarmıha geriyorlar, kaçıyor gölgem.

Bir medyum okuyor sonumu gözlerimden.

Ve bu 

Deli kısrak yüreğim benim.

Gölgesinde bir yolun ilerliyorum.

Yeni bir yürek arıyorum kendime,

Ve

Üşüyorum.

Kış 1996', 'İşliyor gergefi hüznün Puslu bir sabahın karşısında, Kaçıncı sezinleyişimdir o’nu. Çarmıha geriyorlar kulaklarımı ve  Gözlerimi ayrı ayrı. B...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/katli-vacip-usumun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı', 'kirmizi-murat-tali-1qmr5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir gül açsa 

çamura bulanmış duvarımın kenarında 

rengi kırmızı olsa 

tüm o

pastel renk tezatlığının 

içinde 

adını sevgi 

koysam

koparmaya kıyar mısın?', 'bir gül açsa  çamura bulanmış duvarımın kenarında  rengi kırmızı olsa  tüm o pastel renk tezatlığının  içinde  adını sevgi  koysam koparmaya...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kirmizi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*düşe Düştüm', 'duse-dustum-yildiz-yildiz-h1m7i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşümün uçuşan buseleri,

Kondu mu saçlarına dün gece,

Uykumun sevecen dokunuşlarında

Dolandı mı telleri hayalimin parmaklarına? 

Utangaç edalı bir göz yaşından filizlenip,

Çiçeğe durmuştu elma ağacı.

Seher rüzgarında çekingen baharın,

Kızıl  yanakları alev alev, bir yüz müydü,

Mahçup bir tevekkülle, pervasız...

Avuçlara bırakılan.

Yoksa bir yürekmiydi 

Ele avuca sığmayıp 

Kuş kanadında çırpınan...? 

Mekansız bir kırlangıç kanadına saklamıştım

Ondan mı uçup gitmiş habersizce zaman

Yıl mı olmuş, bu ağır uyku kirpiklerime asılalı,

Yıl mı olmuş, mavi kalem gözlerime kan kızılı sürmeler çekeli? 

En koyu gölgeleri mi düşmüş lacivertin

Okyanus üstüne,

Son anda çıkıp da en dibinden nefes nefese

Tan ağarırken açıldım eflatun çalkantılı denizlere,

Zümrüt yeşili kristal bir damla yaştan süzülüp

Elma çiçeğinin pembesinden 

...................................................................Düşe düştüm

Mavi uyandım bu sabah

24/04/2004', 'Düşümün uçuşan buseleri, Kondu mu saçlarına dün gece, Uykumun sevecen dokunuşlarında Dolandı mı telleri hayalimin parmaklarına?  Utangaç eda...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/duse-dustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Ne Çıkar (Sevgili Eşim''e) -1', 'ne-cikar-sevgili-esim-e-1-halit-demir-l21sf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sevgiyim, deli gönlüm divane

Gönül evim, sensiz olur virane

Otağ kurdun,  yüreğimin içine

Gönül koymuş, sevmiş olsam ne çıkar

Gözüm ağlar, yaş düşse da nafile

Gönül bahtım, sensiz döner sefile

Köz olmuşken, küle dönen kalbime

Bu ateşi, yakmış olsan ne çıkar', 'Ben sevgiyim, deli gönlüm divane Gönül evim, sensiz olur virane Otağ kurdun,  yüreğimin içine Gönül koymuş, sevmiş olsam ne çıkar Gözüm ağla...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-cikar-sevgili-esim-e-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derece', 'derece-cihan-paca-7mjgv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'doktor acele gelip

hastanın koltuk altına

bırakmıştı dereceyi

kızgın bakışlar arasında

olsada...olsundu

mutluydu derece

bir güzelin sıcacık koynunda

geçirmişti ya  bütün geceyi', 'doktor acele gelip hastanın koltuk altına bırakmıştı dereceyi kızgın bakışlar arasında olsada...olsundu mutluydu derece bir güzelin sıcacık ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Paça']::text[], 8.5, '{"poet":"Cihan Paça","poet_slug":"cihan-paca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/derece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağma', 'yagma-gokhan-oflazoglu-qnqf3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarılır beynimin damarları; ben çıkarım.

Sen günlük didişmenle uğraş, hırsında boğul.

Bütün gün çalışkan, işlek sokakları arşınlarım.

Kasvetli, gri bulutlar çöker ışıklı İstanbula, 

dönerim evime. Bütün macera burda ve şimdi.

Işık sızmayan, el değmemiş ormanlarda ürkek

gezinirim, iner deniz kıyısına pupa yelken ufukları

tararım, yılmadan, çevik. Deniz de neymiş gel gör

beynimdeki enginleri, kıyıları; şekil şekil hayvanlar

gezinir, irkilirim. Issız bir ada sahilinde bulurlar, 

yüzüstü yerde; bir başka dil telaffuz ettiğim, anlatamam

yabanlara, düşman gibi bakarlar. Söylesemde boşuna,

bilemezler, bunlar yağmadan kalanlar.

26/04/2004', 'Yarılır beynimin damarları; ben çıkarım. Sen günlük didişmenle uğraş, hırsında boğul. Bütün gün çalışkan, işlek sokakları arşınlarım. Kasvet...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yagma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soba', 'soba-cihan-paca-ffvhp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eski sobamızın hatırasıydı

akşamın ilerleyen vakitlerine kadar

aile fertleriyle beraber olmak....

günümüzün en güzel icadı deyip

her odaya bir soba* kurunca

kader oldu akşamları yalnız kalmak

soba*=kalorifer', 'eski sobamızın hatırasıydı akşamın ilerleyen vakitlerine kadar aile fertleriyle beraber olmak.... günümüzün en güzel icadı deyip her odaya b...', ARRAY['Türk Edebiyatı','Şiir','Cihan Paça']::text[], 8.5, '{"poet":"Cihan Paça","poet_slug":"cihan-paca","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/soba-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanını Emen Kedi', 'kanini-emen-kedi-salih-elyesa-1lx41', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Süzer dev aynasında bir serçe endamını

Akla hayale gelmez ivedi bir söz ister

İpleri başkasında bir gölge oyununun

Rolünü iyi kesen riyakârı kul Mister

Adı var kendisi yok bir cengâver zamanın

Önünde tüy parçası ağızdan çıkan sözler

Kırık aynanın aksi çöker yılansı kalbe

Artık ses vermez olur usta elinde sazlar

Heyhat göz gördü gönül seyreyledi cihanı

Fanustan köyün dışı hercai menekşeler

Koşumdan kurtulan at gönlünce gezer kırda

Akla ziyan korkular beyinleri eşeler

Kalp en kırılgan bir gül ey Emir-i sadıka

Yaşmaklı gelinlerin umudu çalınmasın

Ve ey uçsuz ovada at koşturan süvari

Kara bulut nazarlar üstüne salınmasın

Nice bin zelzele ki sarstı yüreğimizi

Yürekler naçar kaldı akıbet hayır değil

Kör testere kanları fazlasıyla akıttı

Kanını emen kedi akla uy öze eğil', 'Süzer dev aynasında bir serçe endamını Akla hayale gelmez ivedi bir söz ister İpleri başkasında bir gölge oyununun Rolünü iyi kesen riyakârı...', ARRAY['Türk Edebiyatı','Şiir','Salih Elyesa']::text[], 8.5, '{"poet":"Salih Elyesa","poet_slug":"salih-elyesa","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kanini-emen-kedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Geleceğim', 'yalniz-gelecegim-cihan-paca-upwlo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tenimin rengine benzediğinden düşlerim

bilemezdin senin için ne düşündüğümü

ama sadece ben bilirdim,her gece

ruhumla bedenimin seni bölüştüğünü

çoğu kez başka muhitlerde yakalardım

sorardım ordaki insanlara bilmezdiler

ben nasıl bilebilirdim ruhumla bedenimin

nerede nasıl kaç kez seni görüştüğünü

ama bir keresinde işittim

başbaşa verdiğimiz bir nisan akşamı

seni daha yakından gördükleri için

kızarıp bozarıp uzun süre gülüştüklerini

söz veriyorum sana,artık

yanımda ne ruhum olacak ne de bedenim

bundan sonra sana gelirken hep

..........................................yalnız geleceğim', 'tenimin rengine benzediğinden düşlerim bilemezdin senin için ne düşündüğümü ama sadece ben bilirdim,her gece ruhumla bedenimin seni bölüştüğ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Paça']::text[], 8.5, '{"poet":"Cihan Paça","poet_slug":"cihan-paca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalniz-gelecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaretim Yok', 'cesaretim-yok-gulten-topay-uo8tp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden çıktın karşıma

Böyle ansız,böyle zamansız

Gücüm yok birtanem,güçsüzüm

Seni sevmeye değil

Sevmeye cesaret etmeye

Oysa isterdim

Seni dolu dolu

Seni uçsuz bucaksız sevmeyi

Ne dersen de haklısın 

Diyecek sözüm yok

Ne yazık ki birtanem

Seni uçsuz bucaksız sevmeye cesaretim yok', 'Neden çıktın karşıma Böyle ansız,böyle zamansız Gücüm yok birtanem,güçsüzüm Seni sevmeye değil Sevmeye cesaret etmeye Oysa isterdim Seni dol...', ARRAY['Türk Edebiyatı','Şiir','Gülten Topay']::text[], 8.5, '{"poet":"Gülten Topay","poet_slug":"gulten-topay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cesaretim-yok-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Öğrettin', 'sevmeyi-ogrettin-metin-usengec-jimpr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana sevmeyi öğrettin

Sen sevmeyi bilemedin sevgilim

Ben ayrılığa alışamadım

Sen ayrılmayı bilemedin sevgilim

Bir hiç uğruna olsa da yakarışım

Silerim hayatımı yıllarımı

Ben ki bunca yanılmışım sende

Ne unuturum seni,ne affederim kendimi

Herşey olacağına varsın,herkes hakkını alsın

Varsa mutluluktan payım,istemem kalsın.. 

25-Nisan-2004  02:30

Bir Gün Beni Ararsan Uzaklarda Arama,Dünde Bugünde Yarında Yüreğin Kadar Yakınım Sana..', 'Bana sevmeyi öğrettin Sen sevmeyi bilemedin sevgilim Ben ayrılığa alışamadım Sen ayrılmayı bilemedin sevgilim Bir hiç uğruna olsa da yakarış...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmeyi-ogrettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığa Dair', 'ayriliga-dair-metin-usengec-nqk44', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağır gelen ayrılıktan öte

Terkedilmişliğin verdiği kırgınlık

Dağları taşları sevdim bilemedim

Yaşadığımız güzellikleri de senide silemedim

Yıllar geçer mazi olur

Bin ah etsek bulamayız gideni

Kaçarız gerçeklerden izi kalır

Pişman olur dönemeyiz

Geçen günleri geri getiremeyiz

Gerçekten sevenler çekip gidemez

Arkasına bakmadan terk edenler sevemez..

25-Nisan-2004  02:30

Bir Gün Benden Ayrılırsan Bende Seninle Gelebilir miyim..', 'Ağır gelen ayrılıktan öte Terkedilmişliğin verdiği kırgınlık Dağları taşları sevdim bilemedim Yaşadığımız güzellikleri de senide silemedim Y...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayriliga-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlamalı', 'hatirlamali-gulten-topay-wwlk4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neyi yazmalı? 

Neleri saklamalı anılarda? 

Yaşanan güzellikleri

Geçmişi unutmamalı

Bir yağmur damlası

Bir yaprak kıpırtısı gibi

Bir rüzgar sesi getirmeli

Seni hatırlamalı

Nasıl yapmalı

Nereye saklamalı anıları

Yığmalı

Yürekte taşımalı

Unutmamalı', 'Neyi yazmalı?  Neleri saklamalı anılarda?  Yaşanan güzellikleri Geçmişi unutmamalı Bir yağmur damlası Bir yaprak kıpırtısı gibi Bir rüzgar s...', ARRAY['Türk Edebiyatı','Şiir','Gülten Topay']::text[], 8.5, '{"poet":"Gülten Topay","poet_slug":"gulten-topay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hatirlamali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlaka', 'mutlaka-gulten-topay-0yb2l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bambaşka duygular

Bambaşka istemler

İnsanın kafasındaki

Yaşama geçmesi mümkün olmayan

Çelişkiler

Fırtınalar,kasırgalar,sarsıntılar

Hep kafamızdakiler

Gerçekler ise hep kavgalar

Anılarda mı yaşamak? 

Gerçekle mi kucaklaşmak? 

Bilinmez

Ama birgün mutlaka netleşmek

Mutlaka', 'Bambaşka duygular Bambaşka istemler İnsanın kafasındaki Yaşama geçmesi mümkün olmayan Çelişkiler Fırtınalar,kasırgalar,sarsıntılar Hep kafam...', ARRAY['Türk Edebiyatı','Şiir','Gülten Topay']::text[], 8.5, '{"poet":"Gülten Topay","poet_slug":"gulten-topay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutlaka-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçımız Kaldı', 'kacimiz-kaldi-gulten-topay-ue863', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaçımız kaldı? 

Kaçımız dimdik ayakta? 

Sorgular,yaşama dair sorgulamalar yaşadık

Karanlıklar doldu içimize

Gün ışığı girmeyecek karanlıklar

Sevgi dolu yüreklerimizle karşı koyduk

Hüzne

Doldurduk gün ışığını içimize

İşte duru,işte berrak bir gün doğuyor ufuktan

Ama biz,biz miyiz? 

Bakan uzaklardan', 'Kaçımız kaldı?  Kaçımız dimdik ayakta?  Sorgular,yaşama dair sorgulamalar yaşadık Karanlıklar doldu içimize Gün ışığı girmeyecek karanlıklar...', ARRAY['Türk Edebiyatı','Şiir','Gülten Topay']::text[], 8.5, '{"poet":"Gülten Topay","poet_slug":"gulten-topay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kacimiz-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Bozuldu', 'gece-bozuldu-gulten-topay-ni8in', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece bozuldu

Gecenin masumiyeti bitti

Telaşlandı,kıpır kıpır oldu

Ne kadar sorumlu,ne kadar değil bilinmez.

Hani erken doğum olurya

Onun sızlatan ızdırabı

Gece ölüm yağdırdı üstümüze.', 'Gece bozuldu Gecenin masumiyeti bitti Telaşlandı,kıpır kıpır oldu Ne kadar sorumlu,ne kadar değil bilinmez. Hani erken doğum olurya Onun sız...', ARRAY['Türk Edebiyatı','Şiir','Gülten Topay']::text[], 8.5, '{"poet":"Gülten Topay","poet_slug":"gulten-topay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gece-bozuldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-demet-kaytan-yb2fu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde yangınlar gözümde yaşlar

Sustum konuşmadım geçti aylar yıllar

Gözlerinde kaybolmak için

Bekledim her gece sabahlara kadar

Seni benden çalmaya kimin gücü yeter

Sensiz canım inan bedenime dar

Beni benden almaya kimin ne hakkı var

Yüreğimde adını söküpte kim atar

Ne ağlayacak kadar günahım var

Ne gülmeyi bekleyecek kadar zamanın var

Ne kimsenin baharında gözüm var 

Damarlarında gezmeye ahtım var', 'İçimde yangınlar gözümde yaşlar Sustum konuşmadım geçti aylar yıllar Gözlerinde kaybolmak için Bekledim her gece sabahlara kadar Seni benden...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sustum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**son Dilek', 'son-dilek-tansel-yegen-m7di8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gittiğin gün

sıcak dokunuşun izleri

kaldı bedenimde

çoban yıldızına saklanmış gülüşlerin

hangi kara boşlukta yiterdi

hele / o son ve umarsız bakışların

oysa ne çok istemiştim

indirmeyi yıldızları tek tek sana

ve kadehindeki yansımalarıı

görmeyi gözlerinde

biriktirdiğin suskunlukların vardı

dudağından süzülen nefeslerini

nasıl bana bıraktığını bilemezsin

/her nerede isen şimdi 

seni kimler sever 

gittiğin yerlerde

o lacivert akşamlarda

...hangi kadınlar

alır seni kollarına

anason kokusuna sinmiş 

o son sözlerin

yudumlarken söylemediğin

ki hep anlatmaya çalışırdın

/bu bizim sonumuz...

açamadığım

kapılar vardı gözlerinde

birtakım pırıltılar geçerdi ya bazen

dudak kıvrımlarında kalmış öpüşlerim

/hediyemdir onlar sana

olur ya dönersen bir gün

hediyem bakidir

gel al biriktirdiğim öpüşlerimi

ve gideceksen durma yine

-hiç unutma

öpüşlerim hala senindir...

 07-08-2003, 18:06', 'gittiğin gün sıcak dokunuşun izleri kaldı bedenimde çoban yıldızına saklanmış gülüşlerin hangi kara boşlukta yiterdi hele / o son ve umarsız...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yegen']::text[], 8.5, '{"poet":"Tansel Yegen","poet_slug":"tansel-yegen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/son-dilek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrının Canı Sıkıldı', 'tanrinin-cani-sikildi-ahmet-can-demir-qtg2d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tanrının canı sıkıldı,insanlığı yarattı; 

İnsanlığın canı sıklıdı aşkı yarattı...

Aşkın canı sıkıldı ayrılığı yarattı; 

Ayrılığın canı sıkıldı beni yarattı yani intiharı...

Benim canım sıkıldı,

Seni sewdim,

seni....

Senin canın sıkıldı ayrılığa sığındın.

Ben bunun için tanrıya yakardım,

Ölesiye haykırdım..

Zaten canı sıkkın oln tanrı çok kızmış olacak ki; 

Bana ömür boyu sensizlik cezası verdi..bir ömür boyu..', 'Tanrının canı sıkıldı,insanlığı yarattı;  İnsanlığın canı sıklıdı aşkı yarattı... Aşkın canı sıkıldı ayrılığı yarattı;  Ayrılığın canı sıkıl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Demir']::text[], 8.5, '{"poet":"Ahmet Can Demir","poet_slug":"ahmet-can-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tanrinin-cani-sikildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teselli', 'teselli-halil-kesken-5cae2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir köşeye oturmuş,

İçin için ağlarken gördüm seni

Neyapacağımı bilemedim bir an

Sebebini anlayamadım

Teselli etmek istedim; 

Başaramadım

Derdine ortak olmak istedim,

Yaklaşamadım

Biliyordum,

Dostluklar bu günler içindi

Fakat sana yardımcı olamadım

Çaresizlik bulut gibi çöktü üstüme

Ellerimi yüreğimde bağladım,

Ben de bir köşeye oturup

Ağladım

Ağladım...', 'Bir köşeye oturmuş, İçin için ağlarken gördüm seni Neyapacağımı bilemedim bir an Sebebini anlayamadım Teselli etmek istedim;  Başaramadım De...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/teselli-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaktidir', 'vaktidir-ruyi-derya-8wtqo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gitmesini bilmelisin vaktin geldiğinde.

Haydarpaşa’dan kalkan son trene ilk binen sen olmalısın.

Vedalaşmalısın yıllarla.

Tren düdüğü ıslığını çaldığında,

Derin bir nefes almalısın yollardan.

Cama dayadığında başını,

Karanlık olsa da seni gözleyen dışarıdan,

Umudunu taşımalı tren, raylar boyunca uzaklara.

Güneş doğduğunda uzatmalısın başını camdan.

Bahar yelleri esmeli yanaklarında.

Saçlarında kar taneleri.

Yalnız, kışın yağmaz karlar.

Yalnızların başlarında beyaz beyaz kırağılar.

Bazı sabahlar çiğ düşer şakaklarına.

Ağlar yalnızlar.

Kırmızı bir gelincik gibidir yüreğin.

Ürkek,kırılgan,kırmızı ve narin.

Siyah siyah bakma bana öyle! 

Yeşersin avuçların! 

Bak uzatıyorum ellerimi! 

Bu kez bitmemecesine! 

Okulun zili ilk kez çaldığında yanımdaydın.

Unutma! 

Hayat teneffüse çıkana dek,

Ben hep yanındayım.

Islak kirpiklerin de güzeldir şimdi senin.

Ağlamak akıtır içimizdeki zehiri.

Gelmez mi sanırsın içimizdeki seheri? 

Küçük bir alemdir insan.

Binbir çeşit yaratık,

Binbir çeşit varlık ve yokluk barınır bedenimizde.

Binbir hissi yüklenir omuzlarımız sessizce.

Nesli tükenmez mi sanırsın kalbini ezen kırk ayakların? 

Gül bahçesine dönmez mi şu kurak toprak? 

Hatırla! 

Dikensiz yetişmez güller...

Gelmesini bilmelisin vakti geldiğinde.

Özlem hangi acıya deva olur? 

Saatine bakarsan görürsün, VAKTİDİR.

Gel! Ne olur? 

Hangi akbaba vazgeçer yavrusundan? 

Hangi serçe akbabaya emanet edilir? 

Hangi mektup kanatlanıp selamımı götürür? 

Hangi adreste bulurum seni? 

Cennetin o güzel ırmağının adı nedir? 

KEVSER KEVSER akıp dönsene geri! ..', 'Gitmesini bilmelisin vaktin geldiğinde. Haydarpaşa’dan kalkan son trene ilk binen sen olmalısın. Vedalaşmalısın yıllarla. Tren düdüğü ıslığı...', ARRAY['Türk Edebiyatı','Şiir','Ruyi Derya']::text[], 8.5, '{"poet":"Ruyi Derya","poet_slug":"ruyi-derya","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/vaktidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarışına', 'sarisina-ahmet-can-demir-fco7j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resmini çizmeye kalktım dün

Bir çocuk edasıyla,

Tüm boyalarımı aldım yanıma..

Her rengi denedim sewdiim,tüm renkleri

Çizemedim..

Hiç bir renk yansıtmadı seni,yansıtamadı..

Renkler birbirine girdi

Her rengi denedim sevdiğim,tüm renkleri! 

Bir tanesi gözlerin edemedi..

Saçların sarı değilmiş oysaki

Öyle sanmışım sadece

Gülüşün gördüğüm değilmiş aslında

Tanrısal bi tınıymış..

Anlıycağın sevdiğim

Yine sadece fotoğraflarınla gülüp

Fotoğraflarınla ağlıyacağım

Ve ben seni çizemezken

Sen sevdamı sildin ya..

Ben ona yanacağım! ! !', 'Resmini çizmeye kalktım dün Bir çocuk edasıyla, Tüm boyalarımı aldım yanıma.. Her rengi denedim sewdiim,tüm renkleri Çizemedim.. Hiç bir ren...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Demir']::text[], 8.5, '{"poet":"Ahmet Can Demir","poet_slug":"ahmet-can-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sarisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Sizin Olsun / deneme', 'i-stanbul-sizin-olsun-deneme-k-muran-esen-ref4e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim gibi küçük bir kasabada mı yaşıyorsunuz? Zaman zaman çevrenizden sıkılıyor musunuz? Kasabanızın olanaksızlıklarından yakınıyor musunuz? Veya ne bileyim daha büyük şehirde yaşamak, büyük şehrin olanaklarından yararlanmak istiyor musunuz? Bu sorulara verdiğiniz cevap “evet” ise, size şöyle bir İstanbul’a gitmenizi öneririm. Şöyle bir gitmek yetmez. Birkaç gün kalacaksınız, büyük şehrin yoğun kalabalığında ve trafiğinde, önemli işlerinizi halletmek için koşturacaksınız.....İşte o zaman yaşadığınız küçük kasabanın güzelliğini anlayacak, küçük yerlerde yaşamanın rahatlığını farkedeceksiniz. Çünkü insanlar, bazı şeylerden uzak kalınca ancak onların güzelliğini anlayabiliyor.

Geçenlerde üç-dört günlüğüne İstanbul’ a gitmiştim. Şarkılara, türkülere, şiirlere konu olan İstanbul’a. Orhan Veliler’in, Yahya Kemaller’in şiirlerinde anlattığı İstanbul’a. Hani diyordu ya Orhan Veli; “İstanbul’u dinliyorum gözlerim kapalı.” diye..... Sağ olsaydı eminim İstanbul’u dinlemek istemezdi şimdi. İstanbul’un güzelliği o şiirlerde ve şarkılarda kalmış. Onun güzelliklerini görebilmek, sezebilmek öyle zor ki. Peki ya sıkıntıları ve zorlukları? İşte bunları her yerde ve her zaman hissedebiliyorsunuz.

Bir defa, büyük şehir yutuyor sizi. Uzayda bir nokta gibi hissediyorsunuz kendinizi. Kim olduğunuzun, ne olduğunuzun ne siz farkındasınız, ne de başkaları farkında. Kasabanızda, karşılaştığınız herkesle selâmlaşmanın ve ayaküstü sohbet etmenin eksikliğini hissediyorsunuz. Aynı apartmanda oturan insanlar birbirini tanımıyor, selâmlaşmıyor. “Yere baksan yer ırak; göğe baksan gök ırak,” misali. Yüzlerce insanla karşılaşıyorsunuz, hepsi yabancı. Ne “merhaba” d iyen var; ne de gülümseyerek hafif başını eğen bir Allah’ın kulu...... Selâm vermek bu kadar mı zor? ..........İnsanlar birbirinden öyle uzak ki. Hepsi iç içe, ama aralarında dağlar var gibi. Duygusal olarak, birbirlerine yaklaşamıyorlar. Kalabalıkta yalnızlığı yaşıyorlar. Siz de o kalabalıkta kendinizi yalnız hissediyorsunuz. İnsanlık ilişkileri kopmuş çoktan. “Ölüyorum” deseniz, bir bardak su veren çıkmaz. Sanki dilini bilmediğiniz yabancı bir ülkede gibisiniz.

Hele hele mağazaların veya çeşitli iş yerlerinin isimlerinin genelde yabancı kelimeler olduğunu görünce, şaşkınlığınız iyice artıyor. Benim gibi yabancı diliniz de yoksa, vay halinize! ... Kalabalıktan ürküyor, gürültüden, hele hele yoğun trafiğinden bunalıyorsunuz. Yaşadığı küçük kasabada istediği yerde, karşıdan karşıya geçmeye alışmış biri olarak şaşırıp kalıyorsunuz. Trafik işaretlerinin, görevlilerin sizi yönlendirmesini garipsiyorsunuz. Kalabalık yaya kaldırımında size omuz vurup geçenlere bakakalıyorsunuz.

Galleria’da bir kahve molası vermek için oturup, çantanızı oturduğunuz sandalyenin arkasına taktığınızda; duyarlı bir güvenlik görevlisi gelip uyarıyor sizi: “ Bayan! Çantanızı elinize alın.”...... Renkli ışıklara kendini kaptırıp annesinden uzaklaşan küçük bir çocuğu izliyor aynı memur. Ve anneyi uyarıyor nazikçe: “Hanımefendi! Çocuğunuzla ilgilenin lütfen.”.....Allah Allah! Sanki savaş alanı veya bir âfet bölgesindeyiz. Demek ki her an tetikte, her an size gelebilecek bir tehlikeyi bertaraf edecek bir pozisyonda olmanız gerekiyor. Bu durumda, İstanbul’un güzelliklerini yaşamak imkânsız hale geliyor. Ürktüm. ” Ben meğer ne kadar rahatmışım kasabamda,” dedim. 

Garajlara gidiyorsunuz, kalabalık sizi ezecek gibi. Kasabada büyümenin ve yaşamanın rahatlığına alışmış biri olarak gene şaşırıyorsunuz. Otobüs muavinleri gelip valizinize yapışıyorlar. “Abla nereye gidiyorsun? ” diye soran sorana. Kimi “Bursa’ya mı? ” kimi “Ankara’ya mı? ” kimi “İzmir’e mi? ” diye valizinize saldırıyor. Valiziniz kapanın elinde kalıyor. Sinirlendim. “Yok kardeşim.” dedim. “Sizin dediğiniz hiçbir yere gitmiyorum. İzin verirseniz Bolu’ ya gideceğim.” İnanın öyle sinirlendim ki; İzmir veya Bursa’ya gidecek bile olsam, olara inat gitmeyeceğim. (Karadenizli Temel gibi.) .....Kalabalıkta karşılaştığımız erkeklerin bir bayana nezaketen yol vermesine alışık olduğumdan, aynı nezaketi orada da bekledim. Nerde! .....Yol vermek şöyle dursun, ittirip, dirsekleyip geçiyorlar sizi. Kendinizi aptallaşmış hissediyorsunuz.

Bindiğiniz taksi şöförleri kurt gibi. Sizi aldatmanın yollarını arıyorlar. Gideceğiniz yeri söylediğinizde, “Nereden gidelim? ” diye soruyorlar. Sizin yabancı olup olmadığınızı, kandırılmaya müsait olup olmadığınızı anlamak için yapıyorlar bunu. Siz de boş bulunup “Kardeşim ben yabancıyım, bilmiyorum.” derseniz, yandınız. Artık en uzak, en dolaşım yollardan götürür, dolaştırır dururlar sizi. Böylece yabancılığınızı fırsat bilip, ceplerine fazla parayı indirirler.

İşte ben birkaç günlük İstanbul seyahatimde bunları yaşadım. İstanbul’un güzelliklerini göremedim, sezemedim. Sıkıntılarını ise dolu dolu yaşadım. Kasabamdaki rahat, mütevazi yaşantımı özledim. Çok sevdiğim kasabamı daha fazla sevmeye başladım. 

Kasabama döndüğümde, hemen bir komşum seslendi pencereden:

”Kâmuran Hanım! Nerelerdeydiniz kaç gündür? Yokluğunuz hemen belli oldu.”

Ertesi gün gittiğim bakkal gülümseyerek: 

“Rahatsız mıydınız yoksa? Son günlerde uğramadınız hiç,” dedi.

Aynı gün başka bir komşum, kim olduğumu hatırlattı: 

”Hocanım! Kaç akşamdır ışığınız yanmıyordu.Nerdeydiniz? ''

Yokluğumun farkedilmesi gururumu okşadı. Kasabamın, trafik yoğunluğu olmayan tek caddesinin tadını çıkardım doyasıya. İstediğim yerde karşıdan karşıya geçtim.Yaya kaldırımda, itilip kakılmadan yürüdüm. Yolda karşılaştığım herkesi, sevinçle ve sevgiyle selâmladım. Birçoğuyla ayaküstü sohbet ettim.

Eğer içinizde küçük şehirlerde yaşamaktan sıkılanlar, büyük şehirde yaşamaya özenenler varsa, işte İstanbul orada. Buyursunlar, gitsinler. Gitsinler ki, küçük şehirlerin sıcaklığını, güzelliğini, rahatlığını anlasınlar. Benim hiçbir yere gitmeye niyetim yok. Varsın İstanbul onların olsun, ama kasabam benim. Çünkü burayı çok seviyorum.........Bana müsaade...Kapı çalınıyor.Galiba bir komşum kahve içmeye geldi.

1993 / Mudurnu', 'Benim gibi küçük bir kasabada mı yaşıyorsunuz? Zaman zaman çevrenizden sıkılıyor musunuz? Kasabanızın olanaksızlıklarından yakınıyor musunuz...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istanbul-sizin-olsun-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekçidirler.', 'gercekcidirler-gokhan-oflazoglu-wuwex', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadınlar gerçekçidirler, sevdayla, masalla işleri yoktur.

Salak Ferhat dağları deler, Şirin''in böyle bir derdi yoktur.

Şairler abartır, kadınlar güler, sen dizeler yaz hayaller kur.

Onlar ayağı sağlam basana gider; kısacası ''güzelliğin kaç

para eder'' dese de şair, kızımız güzel olmasa aşk bile 

olmaz ya, olsa da kaç para eder.

26/04/2004', 'Kadınlar gerçekçidirler, sevdayla, masalla işleri yoktur. Salak Ferhat dağları deler, Şirin''in böyle bir derdi yoktur. Şairler abartır, kadı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gercekcidirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Ağrı''yor', 'yuregim-agri-yor-ferit-ayva-98th4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Feribottayım,

mavi patiskalarda,

İstanbul''la yaşlanıyorum.

Ruhumu yağmurlara kurban etmişim...

Sesini duyuyorum düşen her damlanın.

Islak adımlar atarken karanlık sokaklarda,

yokluğunda kaldırım çiçekleriyle büyüyorum.

Ay kızıla dönüyor sen yokken,

kan boşalıyor bulutlar yanaklarımdan,

yanıyorum.

Varlığından bihaber seni arıyorum.

Belki sen,Buyer''desin elindeki elmayı bana kavuşmak için 

atacaksın...

Belki sen,Ergene''sin fabrika atıklarını kusuyorsun,

kirlenmişsin...

Belki sen,Nemrut''tasın güneşi küçümsüyorsun...

Belki sen,Van''dasın gölün derinliklerinde,

görmüyorsun,duymuyorsun sesimi,

inanmıyor kimse sana...

Ararat''tayım,Karakilise''den batık kalpler denizine bakıyorum,

görünmüyorsun.

Yüreğim Ağrı''yor...

Hicri zamanlardan kalan hicranımı hatırlatıyor yokluğun.

Ağlamsıyor gözlerim,

yüreğim Ağrı''yor...', 'Feribottayım, mavi patiskalarda, İstanbul''la yaşlanıyorum. Ruhumu yağmurlara kurban etmişim... Sesini duyuyorum düşen her damlanın. Islak ad...', ARRAY['Türk Edebiyatı','Şiir','Ferit Ayva']::text[], 8.5, '{"poet":"Ferit Ayva","poet_slug":"ferit-ayva","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yuregim-agri-yor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Petrol Karası', 'petrol-karasi-hasan-sakman-fxh24', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'karışır kan kırmızısı petrol karasına,

okyanus aşırı bir ülkede,

daha fazla binsinler diye 

insanlar arabasına.', 'karışır kan kırmızısı petrol karasına, okyanus aşırı bir ülkede, daha fazla binsinler diye  insanlar arabasına....', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/petrol-karasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Yağmuru', 'mevsim-yagmuru-huseyin-cayikli-uvcv3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mevsim rüzgarlarında kaybettiğim kadındın sen.istasyon kenarlarında  raylara takılırdı gözüm.giden geleni gelen gideni aratır düşüncesine kapılmış istasyondum.sensiz yaşamak zordu.ıslak sokaklarında yürüyordum gözlerime mil çekilmiş gibi,görmüyordum kalabalığı.yalnızdım içimi burkan bu acı sen olamazdın,biliyordum.yorgundum bu şehirde kalmış eski kadınlar birer birer gitmiş oysa eski dostlarla da muhabbet kalmamış ^neydi o eski günler^ demek için geç kalmış oysa mevsim bahardı yağmurlar yağdı sokaklarda ayaklarımın izi var ve ben biraz daha yalnızım.sen başka bir yerdesin,yani benden uzakta...istesem ellerine dokunamam tenini öpemem ve ben acizim bu yalnızlıkla...istesemde bu yalnızlığı terkedemem 

edemeyeceğim galiba...herşey bi yerde kaldı ben bir yere takıldım ve ne yazıkki hala gülemiyorum', 'mevsim rüzgarlarında kaybettiğim kadındın sen.istasyon kenarlarında  raylara takılırdı gözüm.giden geleni gelen gideni aratır düşüncesine ka...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/mevsim-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-adem-tetik-otqh0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hadi çek git ardına bile bakmadan

Sen alışık değilmisin sanki

Böyle yıkıverip gitmeye herşeyi

Ne duruyorsun hadi gidiversene 

Varsa seven  seni  benim gibi

Korkma ben yıkılmam artık 

Düşüremezsin öyle eskisi gibi

Üzülmem kahretmem bırakıp gitsende beni

Nasılsa yemiştim unuttunmu..? 

Daha önce senden bu darbeyi

Hani yılar çok değiştirmişti ne oldu ikimizi

Değişen sadece bizim fiziklerimizmiydi.....? 

Sen yine aynı sen ben yıkılmışım şimdi

Maziye kömülmüş umutlarda

Çok sevmiştim  oysa seni', 'Hadi çek git ardına bile bakmadan Sen alışık değilmisin sanki Böyle yıkıverip gitmeye herşeyi Ne duruyorsun hadi gidiversene  Varsa seven  s...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-378-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarıma', 'dostlarima-alper-er-wv18r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutsuzluğuma bakmayın dostlar… 

Onlar kalbimde ki hayal kırıklıklarından 

Yaşam acı geliyor sizsiz.. 

Hatırlatıyor bir şekilde 

Meyhaneci şerefsiz.. 

İçerken gündüz gece, çekerken kafamızı 

Bir an perde iniyor, gözlerime aniden 

Sizsiz olmuyor dostlar 

Bu hayat çekilmiyor.. 

Kime sitem etsem bilemem 

Bu ömür geldi ama 

Bu şekil hiç geçmiyor… 

Ağlasam gözümdeki yaş belli 

Haykırsam sesim size ulaşmıyor.. 

Kalbim ne yapacağından habersiz 

çaresizlik aklımdan hiç gitmiyor.. 

Güler yüzlü olun dostlar… 

Zaten yeterince asıklık var suratımda.. 

Bir de siz vurmayın 

Kalbimi iyice karatmayın 

İhanet etmeyin dostlar… 

En çok bu vurur beni 

Diğerleri palavra, yaşarsan ihaneti… 

Ölüm herkesin başında 

Olurda öncelik bendeyse 

Mezarıma gelip de 

Sızlanmayın dostlar 

Ağıt yakmayın.. 

Bir günlük olsa da beni 

O zaman anlayın… 

Gözyaşlarınızı boşa harcamayın dostlar 

Her şeyin bir zamanı var 

Ölümün ki apansız… 

Vaktim geldiği zaman 

Döneceğim yer belli 

Gideceğim yol belli 

Bir gün orda buluşacağız.. 

Koymasın size bu uzun ayrılık 

Aslında bu yalnızlık değil 

Sonsuz yanlılık…', 'Umutsuzluğuma bakmayın dostlar…  Onlar kalbimde ki hayal kırıklıklarından  Yaşam acı geliyor sizsiz..  Hatırlatıyor bir şekilde  Meyhaneci ş...', ARRAY['Türk Edebiyatı','Şiir','Alper Er']::text[], 8.5, '{"poet":"Alper Er","poet_slug":"alper-er","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/dostlarima-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-taha-aygun-kanca-6391r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğimde yanıyor Erzurum ateşi,

Viraneler oluyor yalnızlığın kardeşi.

Dostlardan uzaktayım garip bir yolcu gibi,

Geziyorum devamlı duyanlar diyor deli.

Kaderimde varmış İstanbul’da bulunmak,

Cennet mahallesinde top oynayıp koşarak.

Diyorum ki; biz neden bölük bölük olmuşuz,

Aydınlığı bırakıp karanlığa koşmuşuz.

Eyvah eyvah diyerek nedamet duyuyorum,

Geçen eski günlere yeniler ekliyorum.

Dostlar dostundan uzak bulunduğum günlerce,

Çekiyorum her zaman hemen her gün işkence.

Gurbetteki acıyı anlayanlar  belki çok,

Kalbimdeki sızıyı dindirecek dostlar yok.

Kafamdaki her fikir bana sinyal veriyor,

Sert iklimin çocuğu fırsat bulup gel diyor.', 'Yüreğimde yanıyor Erzurum ateşi, Viraneler oluyor yalnızlığın kardeşi. Dostlardan uzaktayım garip bir yolcu gibi, Geziyorum devamlı duyanlar...', ARRAY['Türk Edebiyatı','Şiir','Taha Aygün Kanca']::text[], 8.5, '{"poet":"Taha Aygün Kanca","poet_slug":"taha-aygun-kanca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurbet-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetten Erzurum''a', 'gurbetten-erzurum-a-taha-aygun-kanca-qw0uv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şanına yakışı eksi yirmibeş,

Bazen de oluyor otuz, otuzbeş

Karın kalınlığı yetmiş, yetmişbeş

Yinede seni özlerim seni Erzurum.

Geçte olsa bahar elbet geliyor

Hafif serinlikle gelip geçiyor

Yaz mevsimi seni çok sevdiriyor

Özlemin içimde yanar Erzurum

Temmuz, ağustosta bir hoş olursun

İsterim toprağım seninle olsun

Sevdiklerim sende mutluluk bulsun

Vade bitiminde çağır Erzurum

Nemli hava ile arkadaş oldum

Diyar-ı sahilde yanıp kavruldum

Sıcağı, soğuğu arayıp durdum

Bütün bunlar sende vardır Erzurum

Taha Aygün der ki; güzel yaylalar 

Sert iklimde bir hoş olur havalar

Size deniz bize canım yaylalar

Baba mekanımsın çağır Erzurum', 'Şanına yakışı eksi yirmibeş, Bazen de oluyor otuz, otuzbeş Karın kalınlığı yetmiş, yetmişbeş Yinede seni özlerim seni Erzurum. Geçte olsa ba...', ARRAY['Türk Edebiyatı','Şiir','Taha Aygün Kanca']::text[], 8.5, '{"poet":"Taha Aygün Kanca","poet_slug":"taha-aygun-kanca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gurbetten-erzurum-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Erzurum', 'canim-erzurum-taha-aygun-kanca-huuzo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şanına yakışır eksi yirmibeş

Bazende oluyor otuzotuzbeş

Karın kalınlığı Yetmiş,yetmişbeş

Yinede özlerim seni Erzurum

Geçte olsa bahar elbet geliyor

Hafif serinlikle gelip geçiyor

Yaz mevsimi seni çok sevdiriyor

Özlemin içimde yanar Erzurum

Temmuz, ağustosta bir hoş olursun

İsterim toprağım seninle olsun

Sevdiklerim sende mutluluk bulsun

Vade bitiminde çağır Erzurum

Nemli hava ile arkadaş oldum

Diyar-ı sahilde yanıp kavruldum

Sıcağı, soğuğu arayıp durdum

Bütün bunlar sende vardır Erzurum

Taha Aygün der ki; güzel yaylalar 

Sert iklimde bir hoş olur havalar

Size deniz bize canım yaylalar

Baba mekanımsın çağır Erzurum', 'Şanına yakışır eksi yirmibeş Bazende oluyor otuzotuzbeş Karın kalınlığı Yetmiş,yetmişbeş Yinede özlerim seni Erzurum Geçte olsa bahar elbet ...', ARRAY['Türk Edebiyatı','Şiir','Taha Aygün Kanca']::text[], 8.5, '{"poet":"Taha Aygün Kanca","poet_slug":"taha-aygun-kanca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canim-erzurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zil', 'zil-cihan-paca-i1tbi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne kadar çok sevinmiştim

baban,kuş gibi şakıyan zili 

kapıya taktırınca

çünkü dokunduğumda hep

sen çıkıyordun karşıma

ne zamanki

kapının tokmağına maruz kaldım

kanaat getirdim o akşam

mahalleden taşındığınıza', 'ne kadar çok sevinmiştim baban,kuş gibi şakıyan zili  kapıya taktırınca çünkü dokunduğumda hep sen çıkıyordun karşıma ne zamanki kapının tok...', ARRAY['Türk Edebiyatı','Şiir','Cihan Paça']::text[], 8.5, '{"poet":"Cihan Paça","poet_slug":"cihan-paca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-cem-ozdemir-4amrl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte yine gece..

İşte yalnızım yine..! 

Kapımda sensizliğim,

Ruhumda cinnetlerimle..! 

Sensizliğim..

Bir su bardağı dolusu buruk şarap tadında..! 

Ne zevk veriyor..

Ne sarhoş ediyor.

Cinnetlerim ise..

Bir kızılca kıyamet renginde..! 

Patladı patlayacak..

Çiçeği burnunda bir isyanı müjdelercesine..!', 'İşte yine gece.. İşte yalnızım yine..!  Kapımda sensizliğim, Ruhumda cinnetlerimle..!  Sensizliğim.. Bir su bardağı dolusu buruk şarap tadın...', ARRAY['Türk Edebiyatı','Şiir','Cem Özdemir']::text[], 8.5, '{"poet":"Cem Özdemir","poet_slug":"cem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizligim-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gidince..', 'sen-gidince-ferit-teksoy-pzvxn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gidince o güzelim yuvamız

Ruhunu kaybeden duvarlar oldu

Issız..ışıksız,hücre idi adeta

Gitmişti güzelliği..sıcaklığı bitmişti

Başka bir mekanda gibiydim sanki

Bu masa..biraz önce yanyana oturarak

Kahvaltı ettiğimiz masa değildi sanki

Bitmişti özelliği..güzelliği gitmişti

Fincan soğuk,içindeki çayı içirmiş,

Şamdan boynu bükük,mumu bitirmiş

Ayna üzgün,bakanını yitirmiş,

Parfüm kokun bile gitmişti..

Bal kasesi dolapta üşümüştü

Ahududu,şokella sana küsmüştü

Saçına taktığın toka düşmüştü

Bitmişti sensiz,güzel herşey bitmişti

Bumuydu? ..seni ilk öptüğüm kanepe

Şurda mı? .. oynamıştık tavla oyunumuzu

El ele bu balkondan mı? ..bakmıştık adalara

Hayal olmuştu hepsi..güzellikler bitmişti

Dağınık odamızda düşündüm,uzun uzun..

Bir saatlik yokluğun bunları yaşatırsa

Düşünmek istemedim,çektim kapıyı,üzgün

Ne işim vardı burda? ..çok sevdiğim gitmişti', 'Sen gidince o güzelim yuvamız Ruhunu kaybeden duvarlar oldu Issız..ışıksız,hücre idi adeta Gitmişti güzelliği..sıcaklığı bitmişti Başka bir ...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-gidince-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme-RPT', 'anneme-rpt-erol-dal-ilrug', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum bu kaçıncı ayrı geçen günüm,

Senden uzak, sevdiklerimden ayrı.

Bilmiyorum kaç gün oldu? 

Uzanıp da dizlerine,

Nasihat ederken başımı okşamayışın.

Kaç gün oldu kim bilir! 

Sofraya oturup da, yiyemediğimiz beraber

Sevginle yoğurduğun yemekleri.

En önemlisi kaç asır oldu…

Senin gününde olmayışım ANNEM.

Bu gün ANNELER GÜNÜ.

Sevdiğim tek varlığın en mutlu günü.

Sabah kalkıp da öpmek için elini,

Vermek için sana tün kalbimle sevgimi,

Şu an neleri feda etmezdim ki.

Yapabildiğim tek şey,

Hayaline sarılmak.

Gönderebileceğim tek hediye,

Senin için canımı bile vereceğimi,

Ve uğruna dünyayı sana sunacağımı bilmendir.

Geçmişimle yaşadığım şu günlerde,

Geleceğimin seninle birlikte,

Sonsuza kadar sürmesi dileğiyle…

ANNELER GÜNÜNÜ KUTLAR ELLERİNDEN ÖPERİM.

ED/83', 'Bilmiyorum bu kaçıncı ayrı geçen günüm, Senden uzak, sevdiklerimden ayrı. Bilmiyorum kaç gün oldu?  Uzanıp da dizlerine, Nasihat ederken baş...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anneme-rpt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Vesikalı Kız', 'sari-vesikali-kiz-erol-dal-u1kzr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sarı vesikalı kız.

Beni, hatırladın mı? 

Hani bir gün seninle

Loş havalı bir dünyada tanışmıştık da; 

Sana viski ısmarlamıştım

Kalan son mangırlara.

Hani, hani

Sakız çiğniyordun da; 

Boğazına kaçmıştı

Öperken seni.

Sarhoş ağzında

Biri bin paraydı küfrün; 

Kalbin var mıydı

O zaman.

Yoksa ben miydim kalpsiz olan.

Sevgisiz,

Hayâsızca saldıran,

Buharlı tren gibi

Git gel Konya altı saat

Sahip olan

Sarı vesikalı kız.

Hatırlamadın mı? Beni

Hani aynı gece 

Sızmış kalmıştın da

Kollarımda uyutmuştum seni.

Ne güzelde göğüslerin vardı

Çocuk olup onlarla top oynamak isterdim.

Sarı vesikalı kız.

Tanımadın mı? Beni

Hani sütun gibi bacakların arasında

Bir ben vardı.

Okşadıkça

Gıdıklandığını söylüyordun.

Sarı vesikalı kız.

Sen ne güzel gıdıklanıyordun.

Sabah olup ta uyandığımda

Seni bulamadım.

Paramda yoktu ki

Cüzdanımı soysaydın.

Sarı vesikalı kız.

Sen paramı da almadan gittin

Borçlu kaldım sana…

Beklide 

Sen borçlusun hala

En iyi

Gıdıkladığım için seni.

Öyleyse 

Kim kime borçluysa

Ödeşelim haydi…

Çeyizinden son hatıra 

Dantel işlemeli yatağında 

Ne zaman yattıysam

Yetmiş iki buçuk milletin kokusu

Üzerime sindi.

Sinsice

Oysa

Türkü, Kürdü, Tatarı, Gürcüsü

Fark etmez sana 

Zaten

Hepsi bir delikte buluşmakta

Peki

Bu savaş da ne

Garibim Anadolu’da

Sarı vesikalı kız

Ben yerinde olsam

Yatağa soyunana kadar 

Soyunurdum

Politikaya da

Sarı vesika yerine

Kırmızı plakam olurdu.

Hem o zaman

Çeyizinden kalan son hatıra

Dantel işlemeli yatağın yerine

Yaylı koltuklu 

Son model arabanda

Bitirirdin işini

Sarı vesikalı kız

Sahi, 

Sen nede güzel politikacı olurdun.

Dimdik göğüslerine 

Dayanamazdı,

Enflasyon ve de deve- lüasyon.

Sarı vesikalı kız.

Sen milletin umudu bile olurdun be…! 

Umutsuz kalan yıllarında hemde; 

Ağzı sulu, Abaza, 

Vekilleri bizlerin,

Otururken 

Başkanlık masasında

Habire kalem düşürürlerdi yere

Çocuklar gibi gizlice.

Sarı vesikalı kız

Hala hatırlamadın değil mi? 

Hâlbuki! 

Unutamadım seni

Dantel işleme yatağında

Yetmiş iki buçuk milletin arasında

Benini gıdıkladığım

O, 

Müthiş geceyi

Sarı vesikalı kız.

Sen hala umutlarında mısın? 

Gökyüzünde çalan zilin

Sahibi ben-im

Kapıyı 

Neden hala

Açmaktasın

ED/Mekan', 'Sarı vesikalı kız. Beni, hatırladın mı?  Hani bir gün seninle Loş havalı bir dünyada tanışmıştık da;  Sana viski ısmarlamıştım Kalan son man...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":108,"source_url":"https://www.antoloji.com/sari-vesikali-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜNYASlZ ADAM...! ! !', 'dunyaslz-adam-baki-son-ls9yk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Davullar..............

..............Çalınır

Plaklar..............

..............Çalınır

Dünya..............

..............Çalınır.

Dünya...! ..............

..............Çalınır mı.? 

Dünyamı.............. 

..............Çaldılar

Uyuma...! ..............', 'Davullar.............. ..............Çalınır Plaklar.............. ..............Çalınır Dünya.............. ..............Çalınır. Dünya......', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dunyaslz-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Şekeri', 'umut-sekeri-tolga-ayla-6vyi5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir amca bana şeker vermişti

Arnavut kaldırımlarında umutsuz bekleyişlerimde

Asfalt yoldan çıkmanı beklediğimi hatırlıyorum

Beni güldüren tek kişi o amca olmuştu

Hemen senin evinin yanında oturuyor

Kısa beyaz sakallı bastonlu

Seninle her buluşmamızda penceresinden bakardı sokağa

Yine baktı..

Dün gece yağmur vardı

Kaç zaman oldu beklemişim kapında

Fark etmedim yanıma yaklaştığını

‘’üzülme’’ dedi.

İlk okulun önünde çocuklara sattığı şekerlerden getirmiş bana

Aldım...

Ceketimin iç cebine koydum ıslanmasın diye

Dolabımda durur hala...

Günler geçiyor zaman akıyor

O amcayı ne zaman görsem işe giderken

Bana bir şeker uzatıyor

Almıyorum,

Anlıyor...

Gülümsüyor...

Bende gülümsüyorum ona

Yüzümün çiçek açtığı tek an o oluyor...

Akşam dönüşümde okuldan çıkan çocukların elinde 

Kırmızı kalpli şekerler sokak aralarında

Yenilip tükenen umutları hatırlatıyor bana

Hele senin sokağından geçerken adımlarım susuyor...

Artık şekerci amcanın penceresini de yokluyorum göz ucuyla,

Belki senin perdelerin çekili karşılar bu gece beni

Ama biliyorum...

O’nun penceresi açık olacak soğuğa rağmen,

İçerde çıplak ampulle aydınlanan o oda,

Senin kapalı pencerenin anılarından daha sıcak.

Belki bir yerlerde umut olmalı diye düşünüyorum,

Sonra vazgeçiyorum.

Vazgeçiyorum sensiz bir umuttan.

Yinede gülümseyecek o amca yarın yine o okul kapısında 

O gülümseme umutlarımı yeşertiyor...

Daha güçlü basıyorum toprağa,

İnadına...

Ben belki beklemiyorum senin kapılarında artık ama

O şeker bekliyor

Her gelmediğin dakikakalarda 

Daha bir soğuyor daha bir sertleşiyor dolapta

Tıpkı suratım gibi

Ama gece pencerendeyim...', 'Bir amca bana şeker vermişti Arnavut kaldırımlarında umutsuz bekleyişlerimde Asfalt yoldan çıkmanı beklediğimi hatırlıyorum Beni güldüren te...', ARRAY['Türk Edebiyatı','Şiir','Tolga Ayla']::text[], 8.5, '{"poet":"Tolga Ayla","poet_slug":"tolga-ayla","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/umut-sekeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıklar Birazdan Karartılacak', 'isiklar-birazdan-karartilacak-ahmet-capa-3mnpx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Işıklar birazdan karartılacak,

Birazdan içimdeki duygulardan habersiz,

milyonlarca insan dalacak uykuya.

Ya sen, tüm bu koşuşturmaların bittiği bu saatlerde,

yüzün kimlere güler, kimlere hoş geldin der 

acımasız elvedalara alışık dudakların.

Ben mi beni boş ver,

Bardağımda tüten çay buğularına karışan biriyim işte,

Siyah beyaz anılar arasında savrularak; 

Hep dağınık olan ders kitapları şurada dururdu,

Yemeği şuraya kurardık,

Saatimiz hep sabahın yedisine kurulu olurdu,

Hani çoğu kez gülerdik

sırtımızı sıvası dökülmüş duvarlara yaslayarak.

Pencerenin önündeki yer yatağında uyurdun,

Ve ben usulca okşardım uykunun en tatlı yerinde saçlarını,

Gecenin bir vakti sigaramız biterdi,

Radyonun kırmızı ışığında

bizim bilmediğimiz bir şarkı çalıyor olmalı diyen biriyim işte.

Unutulmaz bir veda sahnesiydi gidişin.

Birazdan gidecektin buralardan,

Seninle beraber tüm hatıralar 

sedef kakmalı bir sandıkta tutuklu kalacaktı.

Senin olmadığın bir yerde 

seni yaşama mahkûmiyeti düşecekti bana.

Ve tüm hatıralar bir gardiyan gibi dikili duracaktı başımda.

Sessizce ağlayarak geçip gitti mevsimler

parmaklarımızın arasından bir su gibi kayarak. 

Çoğu kez kurban ettik değeri bilinmeyen sevdaları,

Ve zaman geri dönüşü olmayan bir yolda

homurdanarak geçip gitti yanımızdan.

Ve ne kaldı bize. Yalnızlıklar…

Bazen her şeyin bittiğine inandığım o kahrolası çöküş anları,

Bazende bir nefes olup içime dolduğu andır yalnızlıklar…

Dedim ya unutulmaz bir veda sahnesiydi gidişin.

Durup dururken uzaklaştık birbirimizden,

Adresi yitirilmiş bir mektup gibi iade oldu bu aşk.

Küçük bir dalganın kıyıya gelip kumsalda ölmesi gibi,

Söylenmemiş sözcükler doluşurken içime.

Birer birer belirip gürültüsüzce kayıp gitti yüzün.

Gece sessizce çökerken bu şehrin turuncu çatılarına

Esneyen sokaklara yine yalnızlıklar doldu.

Arzın dansı gibi dağılan saçların ise şimdi başka rüzgarların yolcusu.

Ey göklere yerini sorduğum sevgili,

Adresini bildiğim sessizliğin tüm sokaklarında yoksun artık,

Bir zamanlar adımı yorganın ucuna yazmışken,

Ve zamanı durdurmak adına 

saatlerimizi tam onikide durdurmuşken,

şimdi terk edilişin acısını bir nakış gibi kalbime işleyipte gittin.

Yorma artık usulca kapansın gözlerin,

Bir rüyayı yaşamak yerine

sen yalancı rüyalara bırak kendini,

Işıklar birazdan karartılacak,

Birazdan içimdeki duygulardan habersiz,

milyonlarca insan dalacak uykuya.

Sende onlardan biri ol 

tüm yaşadıklarımız ile onlardan farklı olarak.

(Haziran 1999 Hudut Karakolu.Akçakale/Ş.Urfa)', 'Işıklar birazdan karartılacak, Birazdan içimdeki duygulardan habersiz, milyonlarca insan dalacak uykuya. Ya sen, tüm bu koşuşturmaların bitt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/isiklar-birazdan-karartilacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dua', 'son-dua-omer-albayrak-es1rr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zerre kadar hilâf yoktur sözümde,

Ayrılık kor gibi yanar özümde.

Küllüğü burnuma tüter Yurdumun,

Çöplüğü gülistan oldu gözümde.

Gücendimi? Küstümola? Yâr bana! 

Gün geçtikçe bu ayrılık kor bana.

Emmisiz, dayısız, ilsiz, obasız; 

Yaşaması zor geliyor zor bana...

Nerde annem, babam, bacım, kardeşim? 

Onlarla süslenir hayâlim, düşüm.

Ne mektup var ne selâm var ne haber,

Yoksa mahşere mi kaldı görüşüm? 

Bir bayram sabahı çıktım Yurdumdan,

Otuz bayram geçti görmedim el-an.

“Iflâh olmaz” diyor bakan yüzüme,

Tek ümidim sende kaldı YARADAN! ..

Çan sesi beynimde yaralar açar,

“Türken raus” diyen yanımdan kaçar.

Yurdumda, yuvamda köle et beni,

Şu gurbet illerde etme hükümdar! ..

Arttıkça artıyor gönlümün gamı,

Sargı tutmaz oldu artık yaramı.

Son nefesi Vatanımda vereyim,

Ya Rabbi! Kabul et bu son duamı! ..

Kavuştur sılama ecel gelmeden,

Bir sabah ezan duyum ölmeden.

Bu kadar saadet yeter ÖMER’e,

Isterse desinler “Gitti gülmeden”! ..', 'Zerre kadar hilâf yoktur sözümde, Ayrılık kor gibi yanar özümde. Küllüğü burnuma tüter Yurdumun, Çöplüğü gülistan oldu gözümde. Gücendimi? K...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/son-dua-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşadası Kuşlarına Veda....', 'kusadasi-kuslarina-veda-hurrem-yalcin-yzsw7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kuşadası kusları

uçar güneşe karşı

kuşadası kuşları

yükselir sema boyu

kuşadası kuşları

öter sevdalı

kuşadası kuşları

hasrete kanat çırpışları

ve

kuşadası kuşları

vakit doldu

göründü eve dönüş yolları

düşsün kanatlarınız

öncü kuşlar misali

istanbulumun yollarına

ve

kusadası kuşları

bu

vedam olsun

sevdanızın kanatlarına! ...

ben eve dönüş yollarında...

kanat çırpışlarınız memleketinizin semalarında! ....

25.04.2004

Kuşadası/Terminal', 'kuşadası kusları uçar güneşe karşı kuşadası kuşları yükselir sema boyu kuşadası kuşları öter sevdalı kuşadası kuşları hasrete kanat çırpışla...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kusadasi-kuslarina-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köhne Gemi', 'kohne-gemi-omer-albayrak-d2jx6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Radyoaktif sızar bu köhne gemi,

Berlirsiz rotası bozuk dümeni,

Ya! Rab’bi sen koru, benlikten-beni.

Denmeden “Garibin hali pür melâl”,

Beni-benden koru, beni-benden al! ..

Beni hedefliyor bütün silahlar,

Canevime neşter vurdu cerrahlar,

Şükürsüz, zikirsiz koydu eyvahlar,

Ister göğe çıkar, ister yere çal,

Beni-bana koyma, beni-benden al! ..

Goncası hazana kalmış bülbülüm,

Bağrında kıvılcım saklayan külüm,

Yeterki eyleme hayatı zulüm,

Ben-bende kaldıkça halim izmihlâl,

Beni-benden kurtar, beni-benden al! ..

Çare, çaresizi yemiş bitirmiş.

Devası, şifası dediki-demiş.

Bu yara kankıren olmadan yetiş! 

Ömür güneşinde başladı zeval,

Beni, sensiz koyma, beni-benden al! ..

Tefekkür denilen ruhun gıdası,

Erenlerin lokmasının mayası.

Ömer denen bu meczubun duası,

Kağıtsız, kalemsiz, pulsuz arzuhal,

Beni, sensiz koyma, beni benden al! ..', 'Radyoaktif sızar bu köhne gemi, Berlirsiz rotası bozuk dümeni, Ya! Rab’bi sen koru, benlikten-beni. Denmeden “Garibin hali pür melâl”, Beni-...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kohne-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-cem-alaca-jflbn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat bir ışığa benzer

Ona baktığın zaman gözünü alır,göremezsin gerisini

Ancak içinde olduğun zamanda anlarsın

Yaşananların değerini

En ufak bir umuda yelken açarsın

Esen rüzgarlara aldırmadan

Umutlarını gizlememelisin

Bir o kadar duygularınıda

Sen olduğun için yaşamalısın

Sana aldırmayanı takmamalısın

Sahip olduklarını hep korumalısın

Kaybetme korkusunu unutmalısın

İşte o zaman görünür ışığın arkası

Hayalindeki yolun açılır kapısı

Takip edincede bu yolu 

Hayatın tadı dolu dolu', 'Hayat bir ışığa benzer Ona baktığın zaman gözünü alır,göremezsin gerisini Ancak içinde olduğun zamanda anlarsın Yaşananların değerini En ufa...', ARRAY['Türk Edebiyatı','Şiir','Cem Alaca']::text[], 8.5, '{"poet":"Cem Alaca","poet_slug":"cem-alaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayata-dair-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etabsız Koşu', 'etabsiz-kosu-omer-albayrak-joxjx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Meczub-u aşk” derler buna,

Virüsü işlermiş kana.

Tiryaki eder hicrâna,

Mecnun’dan beterim bugün.

Can yandı, cânân aşkına

Sevdikçe döndüm şaşkına.

Zehir içerim meşkine,

Bal diye yutarım bugün.

Çilesi deniz vurgunu,

Gözyaşım yıkar argını,

Hâlâ çevirmez çarkını,

Çâresiz hederim bugün.

Kavle sadık, ahde vefa; 

Sevgiliye bu can feda.

Hamı, has edermiş cefa,

Yanmadan pişerim bugün.

Iliğime işler huşu,

Ayılmaz cemâl sarhoşu,

Ömer’e etabsız koşu,

Koştukça koşarım bugün...', '“Meczub-u aşk” derler buna, Virüsü işlermiş kana. Tiryaki eder hicrâna, Mecnun’dan beterim bugün. Can yandı, cânân aşkına Sevdikçe döndüm şa...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/etabsiz-kosu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak Emeller', 'tutsak-emeller-omer-albayrak-46gac', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tutsak emellerim bir dolunaya,

Gözlerim takılıp kalmış uzaya.

Çakılmış çıkmıyor soylu umutlar,

Paslı çivilerle, çürük tahtaya.

Ferhad’ın, Şirini gözümde sıla,

Böylesi nasibbi? Bilmem her kula.

Deli gönül fethi mübin sevdalı,

Sarılmış yakamdan aşkı mübtelâ.

Gülmekle çözülmez gönlümün buzu,

Basmışlar kanayan yarama tuzu..

Nice Kays’ı, Mecnun etmiş bu sevda,

Içtikçe yanarmış aşkın susuzu.

Çığa sevdalanır gönlümdeki kar,

Kıskanır halimi görse kutuplar.

Haykırsam duyarmı? Acep yâr, beni

Seni seviyorum, sende gözüm var! 

Küle döndüm hâlâ yanmak isterim,

Hâlimi tarife yetmez bir terim.

Esrarında yâr gizliyse ölümün,

Çarmıha gerseler seven Ömer’im...', 'Tutsak emellerim bir dolunaya, Gözlerim takılıp kalmış uzaya. Çakılmış çıkmıyor soylu umutlar, Paslı çivilerle, çürük tahtaya. Ferhad’ın, Şi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tutsak-emeller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir akşamüstü olsun...!', 'bir-aksamustu-olsun-hasan-basri-kale-zmot1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gidişin bir akşamüstü olmalı 

uzaklaştığını görmemeliyim 

ışık kalmamalı ardında

sessizlik.. 

ılık bir rüzgar eşlik etmeli vedana 

kıpırdatmayan yaprakları... 

sadece 

yağmur çiselemeli yavaşca 

sağnak gözlerimde

kimsenin görmediği.. 

adına 

ayrılık denmeli. 

sonsuza 

sadece aşk kalmalı 

ne sen 

ne de ben...!', 'gidişin bir akşamüstü olmalı  uzaklaştığını görmemeliyim  ışık kalmamalı ardında sessizlik..  ılık bir rüzgar eşlik etmeli vedana  kıpırdatm...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-aksamustu-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş', 'ates-suleyman-guney-3ctl7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ATEŞ

Her şey, 

her şey ama, sana dair

Kibritsiz ve benzinsiz

sözcükler alev alabilir.

Ve göz minelerinde

donar ateş

ateş ölebilir.', 'ATEŞ Her şey,  her şey ama, sana dair Kibritsiz ve benzinsiz sözcükler alev alabilir. Ve göz minelerinde donar ateş ateş ölebilir....', ARRAY['Türk Edebiyatı','Şiir','Süleyman Güney']::text[], 8.5, '{"poet":"Süleyman Güney","poet_slug":"suleyman-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ates-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-suleyman-guney-29bjn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YAĞMUR

Yine yağmur yağıyor

ne zaman düşünsem seni

bulutsuz havada mavi

uçar gelir bulutlar

dolar hemen gözleri.

Yine yağmur yağıyor

dallara, yapraklara

yollara yağıyor.

Ne zaman olsam seninle

düşün ki; güneşli havada

yağar hafiften.

Bu yağmur senin için

bu yağmur da benim,

ısıtırım ellerimi

içinde ellerinin.', 'YAĞMUR Yine yağmur yağıyor ne zaman düşünsem seni bulutsuz havada mavi uçar gelir bulutlar dolar hemen gözleri. Yine yağmur yağıyor dallara,...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Güney']::text[], 8.5, '{"poet":"Süleyman Güney","poet_slug":"suleyman-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekir', 'tekir-baykal-kaanalp-tst24', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'üç gündür

peşinde koştuğum

fareyle

dost olabilirdim aslında

bu sabah

tekirin mamasını vermeyi

unutmamış olsaydım', 'üç gündür peşinde koştuğum fareyle dost olabilirdim aslında bu sabah tekirin mamasını vermeyi unutmamış olsaydım...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tekir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak İzleriyle', 'ayak-i-zleriyle-suleyman-guney-yljlo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AYAK

İZLERİYLE

Bir kaya parçası

koptu içimden

bir damla gözyaşı

ıslattı

ayak izleriyle şiiri.', 'AYAK İZLERİYLE Bir kaya parçası koptu içimden bir damla gözyaşı ıslattı ayak izleriyle şiiri....', ARRAY['Türk Edebiyatı','Şiir','Süleyman Güney']::text[], 8.5, '{"poet":"Süleyman Güney","poet_slug":"suleyman-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayak-izleriyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Türkümü', 'dinle-turkumu-sabit-i-nce-izqaj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Su başında keklik ol,

Dinle türkümü dinle.

Dosta esen deli yel,

Dinle türkümü dinle.

Dağ başında boran ol

Yarenlere yaren ol,

Uzun, incecik bir yol,

Dinle türkümü dinle.

Sevgimi söylüyorum,

gönüller eğliyorum,

Yürekler dağlıyorum,

Dinle türkümü dinle.

Yakıp kavuruyorum,

Küller savuruyorum,

Gönül doyuruyorum,

Dinle türkümü dinle.

Kurşun gibi deliyor,

Dost elinden geliyor,

Sevenleri biliyor,

Dinle türkümü dinle.

Hem yazım hem de kışım,

hem ekmeğim hem aşım,

Mezar başında taşım,

Dinle türkümü dinle.

İnce ince yakarım,

Arş''alaya çıkarım,

Saltanatlar yıkarım,

Dinle türkümü dinle.', 'Su başında keklik ol, Dinle türkümü dinle. Dosta esen deli yel, Dinle türkümü dinle. Dağ başında boran ol Yarenlere yaren ol, Uzun, incecik ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dinle-turkumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymak', 'duymak-baykal-kaanalp-01cto', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yazmak gereğini

kalemim duyuyor

ben duymuyorum

konuşmak gereğini

dilim duyuyor

ben duymuyorum

duymak gereğini

kulağım duymuyor

ben de duymuyorum', 'yazmak gereğini kalemim duyuyor ben duymuyorum konuşmak gereğini dilim duyuyor ben duymuyorum duymak gereğini kulağım duymuyor ben de duymuy...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/duymak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuz Geceler', 'uykusuz-geceler-ozan-ozel-2k6pv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yine bir gece vakti

uyku tutmuyor gözlerimi

binbir düşünce zihnimde

kaç koyun saydıysam nafile

olmuyor, uyuyamıyorum

Saat bir, iki, üç,....

bir ara tam uykuya dalacakken

bir fikir şeytanı giriveriyor 

yeniden bir al, ver başlıyor  zihnimde

kaç bininci kez bilmem

off be,

bıktım artık uykusuz gecelerden', 'yine bir gece vakti uyku tutmuyor gözlerimi binbir düşünce zihnimde kaç koyun saydıysam nafile olmuyor, uyuyamıyorum Saat bir, iki, üç,.... ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uykusuz-geceler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehit', 'sehit-mehmet-ersoy-7ckor', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kara bulut nedir, anne?

Güneşimi örtüyor…

Yoksa gün

Henüz uyanmadı mı?

Canım oğlum,

Korkma.

Işık bazen

Bulutların sabrında gizlenir.

Sen yeter ki

Başını eğme.

Anne,

Bu kalabalık neden suskun?

Arkadaşlarımın gözleri titrek,

Babamın bakışı

Bir yere değil,

Bir zamana dalmış gibi…

Canım oğlum,

Yolcu etmek ağırdır.

Hele ki

Canından bir parçayı,

Yıllarca kalbinde sakladığını

Sessizce uğurlamak…

Anne,

Bulutların üstündeyim şimdi.

Güneşi avuçlarımda tutuyorum.

Hani yakardı güneş,

Böyle öğretmişlerdi bize…

Ama dokunuşu serin.

Canım oğlum,

Çünkü artık

Güneş sana incitmeden bakar.

Bak etrafına;

Yalnız değilsin.

Senden önce yürüyenler var

Aynı ışığa değmiş:

Karayılan,

Şahin Bey,

Kubilay…

Anne,

Kurşun yaramdan sızan

Bu aydınlık ne böyle?

Dört yanım

Gün gibi…

Canım oğlum,

Vakit tamam.

Gitmelisin yeni mekânına.

Kurşun yaran,

O kapıya açılan bir pencere.

Babandan, benden

Selam söyle

O son peygambere…

                                           Nisan 2004', 'Bu kara bulut nedir, anne? Güneşimi örtüyor… Yoksa gün Henüz uyanmadı mı? Canım oğlum, Korkma. Işık bazen Bulutların sabrında gizlenir. Sen ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ersoy']::text[], 8.5, '{"poet":"Mehmet Ersoy","poet_slug":"mehmet-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/sehit-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var oldukça.', 'var-oldukca-hatice-aydin-147gl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir  böcek, bir çiçek,

Bir çocuk, bir kadın,

Bir adam, bir ana,

Bir baba, bir yuva.

İnsan var oldukça

Sevecek,sevilecek

Doğuma yaşam.

Ölüme son denecek.', 'Bir  böcek, bir çiçek, Bir çocuk, bir kadın, Bir adam, bir ana, Bir baba, bir yuva. İnsan var oldukça Sevecek,sevilecek Doğuma yaşam. Ölüme ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/var-oldukca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğim', 'gidecegim-hatice-aydin-9vc0a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gideceğim bu diyardan.

Ardıma bakmadan

Kim olduğumu,

kim olduğunu hatırlamadan.

Gideceğim  seni anmadan.

Yalnızlığıma yelken açıp

Okyanusların beni götürdüğü

Yalnızlığın sürüklediği

İçimin yanıp kül olduğu

Geçmişi bırakıp

Terkedilmişliği,aldatılmışlığı

Unutturacak diyarlara

Gideceğim.', 'Gideceğim bu diyardan. Ardıma bakmadan Kim olduğumu, kim olduğunu hatırlamadan. Gideceğim  seni anmadan. Yalnızlığıma yelken açıp Okyanuslar...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gidecegim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemen Söyle', 'hemen-soyle-mehmet-ersoy-bjkto', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hadi söyle sevdiğini,

İlk kar yağmadan,

Yollara, ağaçlara,

Omuzlarına, saçlarına.

Hadi söyle sevdiğini,

Büyük acıları tatmadan,

Seni yanında bulmak ister belki,

Babası veya annesi ölmeden.

Hadi söyle sevdiğini,

Ekonomik darboğazlarda,

İşinden atılmadan,

İflas etmeden.

Hadi söyle sevdiğini,

Protesto ve eylemler yüzünden,

Sınıfta kalmadan,

Gözaltında kaybolmadan.

Hadi söyle sevdiğini,

Piyango çekilmeden önce,

Henüz vakit varken söyle,

Komşu ülke işgal edilmeden,

En önemlisi, o evlenmeden.

Hadi söyle sevdiğini,

Henüz gün batmadan,

Yıldızlar çıkmadan,

Hala vakit varken,

Hadi söyle sevdiğini.', 'Hadi söyle sevdiğini, İlk kar yağmadan, Yollara, ağaçlara, Omuzlarına, saçlarına. Hadi söyle sevdiğini, Büyük acıları tatmadan, Seni yanında...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ersoy']::text[], 8.5, '{"poet":"Mehmet Ersoy","poet_slug":"mehmet-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hemen-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilerin en ulusu en yücesi', 'sevgilerin-en-ulusu-en-yucesi-hatice-aydin-dcm2l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgilerin en ulusu en yücesi



Hangisidir diye sorarsanız



Evlet sevgisi der tüm anneler



Ne ana,ne baba,nede koca



Canı cananı can verdiği



Dokuz ay taşıyıp içinde büyüttüğü



Başında sabahladığı



Gözünden bile sakındığı evlat



Acısıyla acı çektiği



Mutluluğu ile mutlu olduğu



Gün gün büyüdüğünü seyrettiği



Bana ihtiyacı olur mu diye



Sabırla beklediği evlat



Söylemesi kolay bir kelime



Çocuk sevgisi başka demek



Ya birde ana olana sorsan



Ne söze ne dile gerek



Kalbinin atışı gözündeki feri



Her şeyi anlatmaya yeter



Ne söze ne dile gerek



Annenin gözlerine bak



Başka söze ne gerek', 'Sevgilerin en ulusu en yücesi Hangisidir diye sorarsanız Evlet sevgisi der tüm anneler Ne ana,ne baba,nede koca Canı cananı can verdiği Doku...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgilerin-en-ulusu-en-yucesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel.', 'gazel-hatice-aydin-vc5lm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fırtınalar kopar içimde

Kimse bilemez bunu

Dışı roman havası

İçi gazel

İnsanım işte böyle

Bu dünyaya böyle gerek

Söylemem derdimi 

Hiç kimseye

Gülmesin

Alay etmesin

Acımasın diye

Atarım içime

Dışı roman havası

İçi gazel', 'Fırtınalar kopar içimde Kimse bilemez bunu Dışı roman havası İçi gazel İnsanım işte böyle Bu dünyaya böyle gerek Söylemem derdimi  Hiç kimse...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gazel-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-hatice-aydin-g8pg2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlamak istiyorum

Bilir misiniz  ağlamayı? 

Keşke bende bilseydim.

Akan göz yaşının tadını

Kimi dertten, kimi kederden

Yahu ben niye 

Hiçbir şeyden

Ağlamayı bilmiyorum.', 'Ağlamak istiyorum Bilir misiniz  ağlamayı?  Keşke bende bilseydim. Akan göz yaşının tadını Kimi dertten, kimi kederden Yahu ben niye  Hiçbir...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aglamak-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni bir gün.', 'yeni-bir-gun-hatice-aydin-rjg6i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine güneş doğuyor

Dağların ötesinden

Kızıl alevler saçıyor

Mavi renkli gök yüzüne

Vuruyor ışıltısı denizlere

Denizler sessiz denizler durgun

Balıkçı sandalları geçiyor

Sabahın ilk ışıklarıyla

Yakamozlar kaybolmuş

Ortalık kızıl alev

Yeni bir gün başlıyor

Uyanıyor toprak ana

Kuşlar gün ışımasıyla

Coşup cıvıldıyor

Yine güneş doğuyor

Yeni bir gün yeni yaşamlar

Birde gidenler var bu günde

Hepimizin gideceği yere gidenler

Arkasında gözü yaşlı

Cefakar kadınlar analar

Evlatlar oğullar babalar

Bırakıp gidenler

Dünya bildiğini okuyor

Yeni bir gün yeni bir umut

Yada yeni bir acı başlıyor

Yeni bir gün daha başlıyor.', 'Yine güneş doğuyor Dağların ötesinden Kızıl alevler saçıyor Mavi renkli gök yüzüne Vuruyor ışıltısı denizlere Denizler sessiz denizler durgu...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yeni-bir-gun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Karanlığın Egemenliği', 'karanligin-egemenligi-vahdet-nafiz-aksu-uy72q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kadim aşinalığı var ruhumun 

Atmosfere egemen karanlıklarla

Buna rağmen  gözlerine meftunum 

Buna rağmen sulh içindeyim ışıklarla

Seher yeşil gözlerinin hatırı için 

Koşup geldi yine milyarıncı kez 

Sevgili sarıldı boynumuza yine 

Zifiri karanlık rengi kuşkularla 

Faniliği dayatıp durur zaman ısrarla 

Tüm yollar mahkumdur aynı kavşağa 

Ölümcül şakalar yapıyor yolcularla 

Gece vakti kervanbaşı kalkmış ayağa 

Kâbuslar dans ediyor ağır uykularla 

Güneşin milyonlarca ışık yılı ötesinden 

Bakıp durmaktayken mavi okyanuslara 

Karşılaşıverdik  çimen yeşili gözlerinle 

O an işte o an anladım ki ey sevgili 

Gözlerinden geçmektedir, gözlerinden...

Zifiri  karanlıklara yenilmemenin  yolu', 'Bir kadim aşinalığı var ruhumun  Atmosfere egemen karanlıklarla Buna rağmen  gözlerine meftunum  Buna rağmen sulh içindeyim ışıklarla Seher ...', ARRAY['Türk Edebiyatı','Şiir','Vahdet Nafiz Aksu']::text[], 8.5, '{"poet":"Vahdet Nafiz Aksu","poet_slug":"vahdet-nafiz-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/karanligin-egemenligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigaram.', 'sigaram-hatice-aydin-2ng44', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık odamı aydınlatan

Minicik bir mum

Denizden esen simbad

Tülleri nasılda uçuşturuyor

Elimdeki sigara dumanı

Bir yol çizmiş kendine

Bazen düz bazen zikzak

Çizerek gidiyor

Ya ben o yolu

Hiç bulamadım

Bir sigara dumanı 

Bile olamadım.', 'Karanlık odamı aydınlatan Minicik bir mum Denizden esen simbad Tülleri nasılda uçuşturuyor Elimdeki sigara dumanı Bir yol çizmiş kendine Baz...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sigaram-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedikodu', 'dedikodu-erdal-sayil-dqi3y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinde korku var,

Okudum ayan oldu...

İnkar etme,doğru,var; 

Sözün bir beyan oldu...

Korkutacak ne yaptım? 

Yanlış yola mı saptım? 

Havadan nem mi kaptım? 

Anladım duyan oldu...

Duyulsa da ne yazar? 

Üstüne düşen bezer,

Köşede kedi azar; 

Sana fit koyan oldu...

Kanma yarim ellere,

Hasetlik,  güzellere,

Dayanma her dallara; 

Bakarsın kıran olur...', 'Gözlerinde korku var, Okudum ayan oldu... İnkar etme,doğru,var;  Sözün bir beyan oldu... Korkutacak ne yaptım?  Yanlış yola mı saptım?  Hava...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dedikodu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maske.', 'maske-hatice-aydin-s5iuu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün maskemi çıkardım

Bu gün ben ben gibi oldum.

Ben ben olunca kimse kalmadı

Ne dost ne arkadaş

Ne de canıma yoldaş

Doğru söyleyen 

Üzülünce Göz yaşı döken

Sevinince çocukça gülen

Özgürce yaşayan

Çirkini güzeli ayıran ben

Ben hiç ben olmamıştım ki

Tanımıyordum artık beni

Taktım yeniden maskemi

Ben bile sevmedim

Maskesiz beni', 'Bu gün maskemi çıkardım Bu gün ben ben gibi oldum. Ben ben olunca kimse kalmadı Ne dost ne arkadaş Ne de canıma yoldaş Doğru söyleyen  Üzülü...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/maske-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan olmak.', 'i-nsan-olmak-hatice-aydin-jvv1m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özgürlük  hayat demek

Yaşam demek ama

Ben yaşamıyorum ki

Sevgi dünya için gerek

Ama ben sevmiyorum ki

Sadakat her şey demek

Saadet demek mutluluk demek

Ama ben sadık değilim ki

Dostluk her şey demek

Candan,sırdaş olan 

Ama ben dost olamıyorum ki

Tüm bu meziyetler insanlık demek

Ama ben insan olamıyorum ki

Neden? neden de ne demek

Aldınız  elimden hepsini

Bende hepsi vardı bunların

Bende insandım

Özgürlük dediniz özgürlük vermediniz

Sevgi dediniz ne verdiniz ne aldınız. 

Sadakat dediniz hep ama hep

Aldattınız

Dostluk  her şey dediniz

Ama hep arkamdan vurdunuz

Bunlarsız mutlu olurum belki dedim

Şimdi hepsini yok ettim

Ben insan değilim ki.', 'Özgürlük  hayat demek Yaşam demek ama Ben yaşamıyorum ki Sevgi dünya için gerek Ama ben sevmiyorum ki Sadakat her şey demek Saadet demek mut...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/insan-olmak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim.', 'i-sterdim-hatice-aydin-d1nsj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığında aydınlatan

Güneş gibi yüzünü görmek isterdim

Bahçeden ılık bir rüzgarla esen

Leylak kokuları yerine senin kokun

Senin teninin kokusu koksun isterdim

Sabahın üçünde kaçan uykularımda

Seninle sohbet etmek

Seninle sigaramı tüttürmek

O sıcak ellerinle yanaklarımı

Okşamanı isterdim

Bak bu günde sensiz ve sessiz

Tıpkı bundan sonraki günler

Bundan önceki günler gibi

Acımasız çaresiz  sevmek işte

Bütün suç bu kelimenin

Ne zormuş sevmek yok yok

Sevmek değil asıl olan mesele

Sevdiğinle olmamak

Bu gün sadece hayallerimde

Yarın ise karatoprağın içinde

O buz gibi havasında belki

Belki kimbilir yanında olurum

İşte o gün sıcaklığına kavuşur

Kimsenin dur gitme demesine

Aldırmam', 'Gecenin karanlığında aydınlatan Güneş gibi yüzünü görmek isterdim Bahçeden ılık bir rüzgarla esen Leylak kokuları yerine senin kokun Senin t...', ARRAY['Türk Edebiyatı','Şiir','Hatice Aydın']::text[], 8.5, '{"poet":"Hatice Aydın","poet_slug":"hatice-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/isterdim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıçak', 'bicak-gokhan-oflazoglu-uz4jt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkımın hırçın gölgesi düşer yere,

titrek, savunmasız, yitik özlemi nerde.

Tüller aralanır, soluk bir ışık sızar,

çırpınan yüreğim, herşey buraya kadar.

Dağlar, çiçekler uzak bir ülkedir artık.

Boşuna çabalama, kaçırdın fırsatları,

yazık değil mi bu ömre, başka avuntular bul.

Ne yapsan yerini tutmayacak, kaybettiğin

aşkların sırtında hain bıçak.

27/04/2004', 'Aşkımın hırçın gölgesi düşer yere, titrek, savunmasız, yitik özlemi nerde. Tüller aralanır, soluk bir ışık sızar, çırpınan yüreğim, herşey b...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bicak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Outlook Denen Meret / deneme', 'outlook-denen-meret-deneme-k-muran-esen-dpu1t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her insanın zayıf veya eksik yanları mutlaka vardır. Dolayısıyla benim de var tabi. Özellikle teknolojik bilgi ve beceri gerektiren konularda çok kötüyüm. Örneğin; bilgisayarı şöyle adam gibi kullanmak, nette – adını bilemediğim – birşeyler yapmak benim için çok zor, hatta olanaksız. Kısacası ben, teknoloji özürlüyüm. 

Bakmayın bilgisayar kullandığıma; işte öylesine ve sınama – yanılma yöntemiyle birşeyler yapıyorum. Yapmak istediğimi; aklıma gelen bir sürü yöntemi kullanarak, onlarca seçenek deneyerek yapmaya çalışıyorum, sonunda oluyor. Oluyor da en son hangi seçeneği kullanarak başardığımı bir türlü bilemiyorum. Körün şeytana taş attığı gibi denk geliyor işte. “ Aaaa! ” diyorum; “ Oldu! .... Nasıl yaptım ben bunu? ”...... En son neye, nereye tıkladığımı hatırlamıyorum bile. Birisi “ Hadi bir daha yap,” dese, hayatta yapamam.Yani bir insan bir konuda ancak bu kadar yeteneksiz olur. “ Yuh! “ derler adama.... 

Zaten, beceriksizliğim ve aklıma gelen yere tıklamalarım yüzünden bilgisayarım birkaç kez kilitlendi. Eşim attı bilgisayarı arabaya, Ankara’ya götürdü; hastaneye hasta götürür gibi. Orada adını bilmediğim birşeyler yapıyorlar bilgisayarıma, düzeliyor. “ Kullanım hatası,” diyorlarmış...Eşime; “ Yok canım! Halt etmişler. Uyduruyorlar, ” diyorum ama, içimden “ Nasıl da biliyorlar! ” diye şaşırıyorum. 

 Teknoloji özürlü olmam nedeniyle bakın neler oldu: izedebiyattan bir arkadaşım bana e-mailler gönderiyor sürekli.  Açmak ne mümkün! Özellikle sesli olanları....Dosyayı açmaya çalıştığımda ekranda “ Veri yetersiz ”, “ Veri eksik “ ya da “ Hata oluştu,” falan yazıyor. Allah Allah! Bu eksik veya yetersiz veri ne acaba? Ya da ne gibi bir hata oluştu? Hata benden mi kaynaklandı? İşin içinden çık bakalım çıkabilirsen! Ayıp olmasın diye, arkadaşıma bir şey söylemiyorum. O zavallı da aklına geldikçe bana e-mail gönderiyor. Sanıyor ki ben şakır şakır açıyorum gönderdiklerini. 

Sonunda dayanamadım, arkadaşıma e-mail çektim.  “ Senin yolladığın müzikli e-mailleri açamıyorum,” dedim. Hay keşke demez olaydım. Başıma ne işler açtım..“ Bülbülün çektiği, kendi dili belâsıymış.” Tutsana dilini be kadın! .....Arkadaşım da bana; “ Sana Outlook kuralım,” dedi. Outlook belâsı, işte o zaman musallat oldu bana.

 Benim Outlook’um olmadığı için e-maildeki ilişik dosyaları açamıyormuşum galiba......Acaba Outlook dedikleri ne? ...Aslında ekranımda böyle bir şey görmüştüm galiba. Arkadaşımın sözünü ettiği o olmasın! Kaç yıldır bilgisayar kullanıyorum(güya)   tıkır mıkır, Outlook’tan haberim yok. Keşke hiç haberim olmasaydı. 

Ayrıca arkadaşım; “ Bizim bir grubumuz var, o gruba seni de alalım. Bizden gelenleri okursun, sen de bize gönderirsin. Biz seni üye yaparız, ” falan dedi. İyi de neyi, nasıl göndereceğim? Yok ki gönderecek bir şeylerim. ” Olsa, dükkân seni,.” derler ya, onun gibi. Esirgeyen namert olsun......” N’olur gir grubumuza, biz sana yardım ederiz,” diyor. Onun bunun yardımıyla nasıl olacak bu iş? “ Bakkal fıstığıyla yar sevilmez,” demişler. 

Zavallı arkadaşım işi gücü bıraktı, benimle uğraşıyor. Ve Amerikan yardımı gibi akmaya başladı yardımlar. Arkadaşım ve onun bir arkadaşı gün boyu bana talimatlar, bilgiler yollayıp durdular..... İşte şunu şöyle yap, bunu böyle yap,” diye. Outlook kuracağız ya! .........Ya sabır! İyice bocaladım. Az buçuk bildiklerimi de tamamen unuttum telâşımdan ve bilgisizliğimin verdiği mahcubiyetimden. Yardım etmek için bana yazdıklarından bir şey anlıyorsam arap olayım! Bir sürü yabancı kelime. O dediğiniz şeyin Türkçe adı yok mu? İnsan sorar bir kez, “ Kardeşim yabancı dilin var mı? “ diye. 

Yanlış anlamadıysam, dediklerinden çıkarabildiklerim sadece şunlar, yani galiba: “ Öncelikle İnternet Explorer 6 ve onunla beraber gelen Outlook Express 6 kullanmalısın...” Var mı ki kullanayım! “ Benzin vardı da biz mi içtik? ” misali. Kulakları çınlasın Sayın Demirel’in...Acaba o dedikleri şeylerden benim bilgisayarımda var da ben mi kullanmayı bilmiyorum; yoksa onları ben mi bilgisayarıma kuracağım? Bu Outlook 6 dedikleri nedir, nasıl bir şeydir? Ne işe yarar? Neden 1, 3, 5 değil de; illâ ki 6? Öfffff! Dertsiz başımı derde sokacaklar durup durup dururken, hatta soktular bile. Keşke “ e-mailleri açamıyorum,” falan demeseydim. Boşboğazlığımın cezasını çekiyorum. Hani; “ Boşboğazı cehenneme atmışlar, - Odunlar yaş. – demiş,” derler ya, aynı onun gibi. Ayıkla bakalım pirincin taşını. Ben kim, Outlook Express kurmak kim; onu kullanacak kim!  Bana mı kalmış outlook kurmak! Kızdım kendime; “ Kaz değilsin, ördek değilsin; paçana kadar suda ne gezersin! ” dedim. 

Talimatları okudukça ter basıyor. Ben nasıl başaracağım bu Outlook’u? Adı batasıca! Radyoda istasyon bulamayan ben, tv kumandasını bile doğru dürüst kullanamayan ben; İnternet Explorer 6, o yetmezmiş gibi Outlook Express 6 kuracağım bir de. “Ayranı yok içmeye.....” misali.Sanki onları kurmak çok kolay! ...Benim Outlook’um kaç numara acaba? (Varsa tabi.)   Kimbilir benimki 3, 4, 5 falan da o nedenle işe yaramıyor. İyi de 6 sını nerden bulacağım, nasıl kuracağım? Ekmek değil ki gidip bakkaldan alayım; yemek tarifi değil ki bir komşuma sorayım....Destan gibi yazmışlar neler yapmam gerektiğini. Meğer ne zormuş o dediklerini kurmak. Onbeş bilinmeyenli denklem gibi.....” Şuraya gir, şunu seç, bunu tıkla, webde işlem yap vs.” 

Daha bitmedi: Antivirüs programın var mı? “ demezler mi bir de! ... Yok daha neler! “ Buyrun, buradan yakın, “ diye homurdanıyorum. Mutlaka olmalıymış ondan. Valla ne bileyim var mı, yok mu. Kardeşim aylar önce, virüsle ilgili bir şeyler yapmıştı bilgisayarıma. O zamandan beri, kardeşimin o yaptığı şey ikide bir geliyor bilgisayarımın ekranına, dokuma tezgâhı gibi tıkırdayıp duruyor. İşte o zaman ben, bana gelen virüsleri yiyor o program sanıyorum. Virüslere karşı verdiğim savaşı kazanıyorum diye kıs kıs gülüyorum bir taraftan. Acaba bana sordukları “ antivirüs programı ” bu m’ola? 

Ha! Bir şey daha: Spam yapmaktan söz etmişler. Acaba bu iyi bir şey mi, kötü bir şey mi? Kulağa hiç hoş gelmiyor da, şüphelendim. Hani aforoz etmek gibi sanki. Spam olmadığını bildirmezsem, bilmem şunlar şunlar olurmuş...Şimdiye kadar spam mpam yapmadım, kimseye bir şey bildirmedim; hiçbir şey de olmadı. Yalnız arada bir bilgisayarım kilitleniyor demiştim ya, o spam yüzünden olmasın. Spamdan kurtarmak ne, nasıl bir şey acaba? Spamın ne olduğunu bilmiyorum ki ondan kurtulmanın yolunu bileyim. Sizin anlayacağınız, görünmeyen bir düşmanla karşı karşıya gelmiş gibiyim. Allah sonumu hayır eyleye. 

Bir de “ Takıldığın yer olursa, bize sor.” demezler mi! ...Takılmak ne demek! Ben mi takılacağım? Takılacağımı hiç zannetmiyorum. Çünkü takılmak için, bir şeyler yapmak, işe başlamak lâzım. Siz, altı aylık bir bebeğin yürürken takılıp düştüğünü gördünüz mü hiç? Takılıp düşmesi için, bebeğin önce yürümeyi öğrenmesi gerekir. İşte o nedenle ben de hiç takılmayacağım. Bana anlatılanlardan hiçbir şey anlamadığım, o Outlook 6 dedikleri mereti kurmaya cesaret bile edemeyeceğim için, hiç takılmak gibi bir problemim olmayacak......İyi de o zaman bayanlara ayıp olacak. Zar zor kursam mı acaba Outlook’u? Ama nasıl? ...Yani utanmasam, “ İmdaaaaat! ” diye bağıracağım. 

Sevgili okurlar! “ Ben bir teknoloji özürlüyüm,” demekte haklıymışım, değil mi? Valla hiç abartmadım. Yazdıklarımın hepsi gerçek. Hatta eksiği var, fazlası yok. Çok ayıplarsınız diye ayrıntılara girmedim. 

Sevgili okurlar! Sizde Outlook var mı? Bu nasıl bir şey? Sizinki kaç numara? 4’ ü, 5’ i, 6’ sı da ne demek oluyor? En büyüğü kaç numara? Yoksa 7’si de var mı bunun? Kurmuşken 8’ ini mi kursam acaba? Hani olmuşken, en iyisinden olsun. Nerden alınır, nasıl kurulur bu meret? Kafayı yemek üzereyim.........

Sordum diye anlatmaya kalkışmayın sakın, çünkü an – la – ta – maz – sı – nız. Daha doğrusu siz anlatırsınız da ben anlayamam. Dedim ya, ben teknoloji özürlüyüm. Ayrıca, hiç kimsenin bana Outlook’ tan, Explorer’ den söz etmesini istemiyorum. Sabrım taştı, o kelimeyi duymaya bile tahammülüm yok, yoksa her an elimden bir kaza çıkabilir....İllâ ki söz etmek istiyorsanız; outlook moutlook demeyin bana, “ O dediğin şey.....” deyin yeter, ben hemen anlarım. Teknoloji özürlüsü olabilirim ama, Allah’a şükür anlayışım kıt değil....

Bir tavsiye: Siz siz olun, benim gibi teknoloji özürlülerden uzak durun.', 'Her insanın zayıf veya eksik yanları mutlaka vardır. Dolayısıyla benim de var tabi. Özellikle teknolojik bilgi ve beceri gerektiren konulard...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/outlook-denen-meret-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanımı ısırma', 'kanimi-isirma-zafer-zengin-etnika-wcr1t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kanımı ısırma izmir

Denizine dokunduğumda

Ilıktı sesin/Yamandı  kulağıma

Çöpün bile eski sevda

Elimi soktum koynuna

Kokun kaldı ucunda

Kanımı ısırma izmir

Eski aşk

Eski yara

Bağırma izmir/Korkutma

Işığınla sarmışsın körfezimi

Yakamozun yalan

Ayın sahtekar

Aşkım kokunda/Deniz

Ayrılık bıraktın bana unutma

İzmir kanımı ısırma

Gelmem yanına bir daha

Yapışma yakama

E l / v e d a  d o k u n m a s a m d a

'' Çok eskiden yitirdiğim o gül''e''

26 Nisan 2004 '' İçimin kitabı ''', 'Kanımı ısırma izmir Denizine dokunduğumda Ilıktı sesin/Yamandı  kulağıma Çöpün bile eski sevda Elimi soktum koynuna Kokun kaldı ucunda Kanım...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kanimi-isirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunma Sana', 'dokunma-sana-zafer-zengin-etnika-84eoy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mecazi

anlamlar 

yüklüyorum 

g ö z l e r i m e...

Batıyor 

y e l k e n l e r i m

Uyku

tutmuyor

d e r i n l i k

Mavi 

bu

sancı

d a l g a s ı z 

Yüzme 

bilmez 

a c ı 

Ne

y a p a c a k s ı n

Ellerim

d i n ç 

D o k u n m a /s a n a...

26 Nisan 2004 '' İçimin kitabı ''', 'Mecazi anlamlar  yüklüyorum  g ö z l e r i m e... Batıyor  y e l k e n l e r i m Uyku tutmuyor d e r i n l i k Mavi  bu sancı d a l g a s ı ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dokunma-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '19 Mayıs', '19-mayis-ozan-ozel-7pxvn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yol aldın hırçın Karadeniz''de

Umuda ve geleceğe doğru

İnandı sana Türk milleti

Ve uyandı derin uykusundan

İşte bak! geliyor ardından

Başlattığın bir savaştı

Esaretten özgürlüğe, 

Karanlıktan aydınlığa ve...

Bir sözün yetti, 

inançla doldu yürekler

adımlar uygun adım

yürüyüş başladı Samsun''dan

19 mayıslar kutlanıyor, kutlanacak

Atam, bu yürüyüş hiç durmayacak', 'Yol aldın hırçın Karadeniz''de Umuda ve geleceğe doğru İnandı sana Türk milleti Ve uyandı derin uykusundan İşte bak! geliyor ardından Başlatt...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/19-mayis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgem...!', 'golgem-musfik-saltik-xh761', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş vurmustu sırtımdan önüme gölgem düştü.

Bedenim miydi güneşin gücüne karşı koyan? 

Yoksa o bedeni dimdik tutan ruhum mu? 

Yürüdüm gölgem yürüdü, koştum gölgem koştu

O bedenimden hep öndeydi, sırrı çözdüm sonunda

Gölgeme gücünü veren şerefli, onurlu  ruhumdu.

Benim  gibi bir adamın gölgesi de ancak böyle olurdu.

Ama, ama böyle  bir gölge nasıl olurda yerde dururdu 

Ona da çözüm buldum koştum bir duvarın önünde durdum

Gölgem layık olduğu yeri  buldu benim gibi dimdik ayakta durdu.

Ama o da ne! güneş batmaya başladı gölgem soldu yok oluyordu.

Hemen bir çözüm bulmalıydım tabi ki çok sürmedi çözümü buldum.

Ben çözümlerin adamıydım koştum Topkapı sarayının duvarı dibine

Geçtim bilmem kaç vat gücündeki aydınlatma projektörlerinin önüne

Yerleşti gölgem bütün haşmetiyle tarihi duvarın üzerinde hak ettiği yere

Gözlerim doldu bu ne büyük gururdu gölgem  tarihin bir parçası olmuştu

Sonra yine onlar geldiler, etrafımı sarıverdiler direndim dinlemediler 

O kahrolası beyaz gömleği yine giydirdiler, arabaya tıkıp götürdüler.

Adamlara da kızamıyorum  bıktılar, onlar yakalıyor ben kaçıyorum.

Ne yapayım, hastanedeki odama güneş girmiyor, gölgemle buluşamıyorum

Kimseye  dinletemiyorum herkes birini sever ben gölgemi seviyorum

Gölgemde ben kendimi görüyorum, deli diyorlar gülüp geçi yorum.

Akıllılar birbirini sevsin bana ne ben gölgemdeki beni seviyorum

Yıllardır herkesten kazık yedim artık sadece gölgeme güveniyorum.

Gölgem saf, gölgem dürüst, gölgem sevgi dolu, gölgem dost canlısı.

Gölgem hak ettiği yerde olmalı, gece gündüz dimdik ayakta durmalı 

Kimseyi kırmadı, kimseyi kandırmadı, kimseye kalleşlik yapmadı

Bu dört duvarın arasından kurtulmak  benimde gölgemin de hakkı.

Yalnız ben değil bu hastanedeki bütün gölgeler dışarıda ve özgür olmalı, 

Buradaki  sevgi dolu, dürüst gölgelerin, buraya düşmesine sebep olan 

Ahlâksız, kalleş, içten pazarlıklı  gölgelere o beyaz gömlek giydirilip

Bizim gölgelerimizin yerine bu hastaneye o gölgeler kapatılmalı.

                                                                                  

                                                                                                Nisan 2004', 'Güneş vurmustu sırtımdan önüme gölgem düştü. Bedenim miydi güneşin gücüne karşı koyan?  Yoksa o bedeni dimdik tutan ruhum mu?  Yürüdüm gölge...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/golgem-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞiRiN MEYHANE', 'sirin-meyhane-baki-son-bu0q1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neler hatırlatmaz

Bir kaç kadeh insana...

Dünyayı unutur da,

Kendi içyüzüne dalarsın.

Boşalan kadehler gider,

Dolular gelir...

Derdini anlatırsın dumanlara,

Paketler 

Tükenir.! 

Kimi,

Yok olur 

Hatıralarda

Kimi,güler

Kimi,ağlar

Rahatlar..! 

Üzgün girer,

Şen çıkarsın.! 

Sonra döner,

Hey gidi,

Şirin meyhane der

Gidersin...

Gerçeklerinle...! 

Unuttuğun dünyaya.', 'Neler hatırlatmaz Bir kaç kadeh insana... Dünyayı unutur da, Kendi içyüzüne dalarsın. Boşalan kadehler gider, Dolular gelir... Derdini anlat...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sirin-meyhane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-ahmet-unal-5p2xh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Öğretmenden öğrencisine...”

Sevgili öğrencilerim:

“Eşini, işini seversen mutlu olursun” dediler

Eşimi de, işimi de seviyorum

Üstelik,

Eşim de öğretmen, 

Biliyor musunuz? 

“Öğretmenlik, Peygamber mesleğiymiş” 

Öyle belledim...

Verdiler elime hamuru,

Verdiler elime çamuru,

“Ekmek, çömlek yap hadi” dediler

Fırıncı değilim, çömlekçi de değilim, lâkin

İkisini de yürek fırınında pişirdim ilkin

Akıl süzgecinden geçirdim,

Ve yoğurdum bir iyice gönül teknemde

Güneşle, ışıkla, aşkla

Sonra, cümle insanlığı doyurdum

                          

Bir öğretmenim sevgili öğrencilerim, can çiçeklerim

Fırında ekmek yapar gibi

Çamurdan çömlek yapar gibi 

Sabırla, ilmek ilmek - nakış nakış

İnsanla insan olmayı işledim...

Büyüttüm sevgiyi, nakşettim galiba yüreğinize

Gök kubbeden çil çil yıldızlar indirdim size...

Kıraç toprakları verdiler

“Bahçıvanlık yap” dediler sarp yamaçlarında Anadolu’mun

Gonca gonca gül oldum kıraç topraklarında

Orman oldum sarp yamaçlarında

Yağmurları indirdim bulutlardan...

Can çiçeklerim benim! 

Ekmek olalım, doysun açlar 

Faydamız dokunsun, cümle âleme

Testi olalım çamurdan

Ve buz gibi su içsinler kana kana...

Ne güzel olur değil mi? 

Ayrık otları yeşermesin aramızda

Bir olalım, birlik olalım

Dirlik, düzenlik, güzellik için...

Atatürk’ü  yaşayalım Atatürk’çe...

Biliyor musunuz canlarım, 

Cananlarım biliyor musunuz? 

Atatürk’de öğretmendi

Hem de ''Baş öğretmen'', biliyorsunuz...

Ben bir öğretmenim... 

Hem öğretmenliği, hem de Atatürk’ü seviyorum

Niye sevdiğimi anlatabildim mi? 

Anlayabildiniz mi sevgili öğrencilerim? 

İnsanı sevmeyi öğretiyorum Yunus’ca

E-D-B ‘ i  öğretiyorum Hacı Bektaş Veli gibi

Canıma can katıyorum Mevlâna’ca...

Ülkem, ulusum ve bayrağım için

Gözüm görmüyor sizlerden başkasını...

Anadolu’ mun yanık yüzlü insanıyla

Yaşıyorum sizde, en büyük aşkımı

Ve sizinle beraber söylüyorum

Asırları delip geçen şarkımı...

Ben öğretmenliği insan için

İnsanca yaşamak için

''Güneşe bağdaş kurup oturmak'' için seçtim,

Hadi uzatın ellerinizi! 

Hadi canımın çiçekleri! ...

Yüreğimin içinde bekliyorum! 

Sizi, hepinizi 

Canımdan, canımdan çok seviyorum...

Yüreğime sığdırdım ruhla bedenlerinizi

Tertemiz okyanus berraklığında

Sizi yaşıyorum sizinle...

Damlalardan su birikintileri

Su birikintilerinden çaylar, dereler, ırmaklar

Aydınlığa yükselsin, yükselsin

Kanat kanat kalem tutan parmaklar...

Ey geleceğimizin damlaları! ...

Savrulmayın, savrulmayın sakın ola 

Gelip geçen rüzgârda...

Bulanmasın suyumuz, kararmasın havamız

Yağmura doysun bağımızla ovamız

Yürüyün, yürüyün geriye bakmadan asla

Aydınlık geleceklere! ...

''Bir türkü söyleyelim hep birlikte

Barıştan, erdemden yana''

Göğe ve yere...

Dedim ya sizlere 

Dedim ya eşim de öğretmen, ben de öğretmen...

Aynı yolda, aynı heyecanla, aynı aşkla

Sizleri bekliyorum ben...

Sizleri bekliyorum ben...', '-Öğretmenden öğrencisine...” Sevgili öğrencilerim: “Eşini, işini seversen mutlu olursun” dediler Eşimi de, işimi de seviyorum Üstelik, Eşim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal']::text[], 8.5, '{"poet":"Ahmet Ünal","poet_slug":"ahmet-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/ogretmenim-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Arayan Adam', 'kendini-arayan-adam-ahmet-unal-ljsfz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-I-

Caddelerde bir taksi

Takside bir adam,

Kaldırımlarda binlerce ayak sesi

Adamın içinde curcuna

Adamın içinde fırtına,

Gök yanar, yer yanar...

Şehir benzer fırına; 

Adam, milyonlar içinde yalnız,

Hayır! Hayır! 

Adam, içindeki adamla kavgalı...

Kıskacında zamanın, yakalanmış apansız...

Adamın saçı - sakalı un beyazı

Ne kadar bağırsa da; duyulmuyor avazı...

Adam, ince bir hüznün kelebeği,

Adam, içindeki adamın bebeği...

Elleri radyonun düğmesinde

İstasyon istasyon gezinse de boş,

Kaset çalsa da aynı, çalmasa da...

Adamın içi ağzına kadar dolu,

Adamın dışı bomboş...

Caddelerde bir taksi,

Taksi de bir adam.

Adam arayış içinde

Bir bulsa, bir yakalasa

Farketmezdi, nereden olursa olsun

Ha Çin’ den, ha Yemen'' den...

Kopup giderdi peşinden...

“Aç pervaneyi dostum, rüzgârın gelsin! 

Aç müziği sonunda dek, efkârın bitsin! 

Ve aç yüreğini  zaman silinsin” diyen bir sesle titredi adam,

Tepesinde yanan, mum titremesi sanki

Kaset döner, başı döner takside

Aradığını bulamaz adam,

Çünkü, her şey kendinde...

-II-

Çekmiştir taksiyi evinin önüne

Evinin mutfağında, musluk başında; 

Musluktan su yerine “tıs” sesi

Adamın çıkmıyor ki nefesi...

Arayış bu ya, telâşı ondan

Balkona çıkarken kapının gıcırtısı

Bozuyor gecenin sessiz boyutlarını,

Bakıyor adam, karanlıkların kapladığı göklere

Yıldızların şarkısını duyamıyor,

Balkonda bile huzur bulamıyor...

Tutuyor ay’ı ikiye yarıyor

Bir parçası parmak uçlarında,

Öteki parçasını evinin önünde duran taksisinin

Tam üstüne fırlatıyor...

-III-

Merdivenlerin basamakları sıfır,

Adımlarında mesafeler eriyor,

Adamın yürek yangını var

Gecenin tam orta yerinde

Öylesine hızlı ve çabuk ki

Adam takside,

Taksi, yol kovalıyor...

Yol boyu ağaçlarının sesi:

“Sen sendeki sana bak! Sana bakkk! ! ! ...

Sen

Kendini orada bırak! ! ! ” demekte,

Adamsa, esnemekte...

Ardından, bir gök gürültüsü

Ardından, siren ve ambulans çığlığı

Başına toplanmış doktorlar

Adamın içinden çıkan, adama bakar...', '-I- Caddelerde bir taksi Takside bir adam, Kaldırımlarda binlerce ayak sesi Adamın içinde curcuna Adamın içinde fırtına, Gök yanar, yer yana...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal']::text[], 8.5, '{"poet":"Ahmet Ünal","poet_slug":"ahmet-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/kendini-arayan-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Oyunu', 'hayat-oyunu-ahmet-unal-wmeux', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir oyun sandım hayatı,

Hem de yıllar boyu...

Kandım, küçücük gülümsemelere

Çocuklar gibi...

Bir gün, ateşe elim değdiğinde

Aklım başıma geldi...

On beş - yirmi beş arası

Çin Seddince ayırımlarda,

Sıkı dostlukar

Ve ölümüne düşmanlıklarda,

Ölesiye sevdalarda

Gidip geldik, gidip geldik...

Yirmi beş – otuz beş arası

Kayboluyor kesin çizgiler...

İhanet ediyor dostlar,

Hançer yiyorum sırtımdan

Ve hançeri çıkaran sırtımdan

Düşman sandıklarım...

“Dostun gülü yaralar beni” demiş ozan

Ne kadar doğru demiş; 

Bu çağda insan, severse

Bizim gibi severmiş...

Ezbere bildiğim yirmi dokuz harf

Sanki karmakarışık...

Baktım, zaman kanatlanmış,

Yaşım, ayakkabı numarammış...

Mumlar, pasta masrafını geçmiş

Doğum günümde,

Gerçeğin, katı gerçeğin keşfini yapıyorum

Bildiğimde, gördüğümde...

Sonuç mu? Sonuç şu birader:

İyi insan, kötü insan yok dünyada

Varsa iyilik-kötülük var

İkisi bir birinin kan kardeşi

Ve de panzehiriymiş, anladım...

Geçiyor peşpeşine seneler

Olgunlaştım sanıyorum...

Nefret şehvete dönüşüyor,

Tevazuyla gurur,

Haysiyetsizlikle onur kardeş olmuş

Hayret bir şey! 

Gayri görebiliyorum

Zamanın tozlu aynasında

İsyankârla sahtekârı,

Günahkârla tövbekârı....

İyilik arıyorum Diyojen misali

Elimde fenerim...

Kundakdaki bezime benziyor kefenim...

Bir de bakmışım dost,

Kırkı kırklamışız meğer,

Demircinin elinde hem örs,

Hem de çekicim...

Yılların yığını ile dopdolu içim...

Kötülüğün karşısında birader

İyilik benim... İyilik benim...', 'Bir oyun sandım hayatı, Hem de yıllar boyu... Kandım, küçücük gülümsemelere Çocuklar gibi... Bir gün, ateşe elim değdiğinde Aklım başıma gel...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal']::text[], 8.5, '{"poet":"Ahmet Ünal","poet_slug":"ahmet-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/hayat-oyunu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Faili Meşhur Cinayetler', 'faili-meshur-cinayetler-mehmet-kizilay-2t8hg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iki vatan içinde

kurşunlanan gölgemdir,

vurulan ben gibi.

bu benim ülkemdir

ülkem(!) ..gibi.

gözyaşlarım esir

gölgem ağlar

su ıslak değil

yüreğime yürür

kanın gölgesi

ummansız

delicesine,hoyratça.

sevda ve delişmenliği

vuslata erdiren toprak

toprak soylu değilse eğer

TORPAĞ kadar

ya eğil,

ya da..

onurunla çekil.

                                            

                                                                      Mehmet KIZILAY

                                                                 03.04.1998/İSTANBUL', 'iki vatan içinde kurşunlanan gölgemdir, vurulan ben gibi. bu benim ülkemdir ülkem(!) ..gibi. gözyaşlarım esir gölgem ağlar su ıslak değil yü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/faili-meshur-cinayetler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '......Kaybetmemek Uğruna', 'kaybetmemek-ugruna-mehmet-kizilay-isvjp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bakınca,

yüreğimden

birşeyler kopar

                      sanıyorum.

kaybetmemek

uğruna,

o şahesere

                     bakmıyorum.

                                                                      Mehmet KIZILAY

                                                                         02.02.1997 NİĞDE', 'bakınca, yüreğimden birşeyler kopar                       sanıyorum. kaybetmemek uğruna, o şahesere                      bakmıyorum.        ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kaybetmemek-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben sana bir ceza verebilseydim', 'ben-sana-bir-ceza-verebilseydim-ayten-ozlem-yesilcali-vmnco', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sana gülüm bir ceza verebilseydim..

Seni de benim seni sevdiğim gibi; 

Sevmeye mahkum ederdim..

Ama na file kırılsın beli sevğinin.

Sana ceza degil; Seni sevmeye bile mahkum edemiyorum.

Bunun ne demek olduğunu biliyormusun.

Uykusuz gecelerimin azabı sen sin.

Bilmem bunu hissede bilyormusun gülüm.

Ben sensiz bu felegin kahrını; 

Ben sensiz bu dünyanın zulmünü çekiyorum.

Sen nerdesin; Sen kiminlesin bebegim.

Ben bunu bile bilemiyorum.

Bunun seven için ne kadar acı oldugunu sen bilebiliyormusun.

Bilemezsin be gülüm.

Çünkü.sen sevmenin ne olduğunu bilmiyorsun..

Ben sana bir ceza verebilseydim.

Seni ömür boyu sevmemeye vede sevilmemeye 

Mahkum ederdim..', 'Ben sana gülüm bir ceza verebilseydim.. Seni de benim seni sevdiğim gibi;  Sevmeye mahkum ederdim.. Ama na file kırılsın beli sevğinin. Sana...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-sana-bir-ceza-verebilseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Diyorum', 'hani-diyorum-vedat-koparan-kw7d3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani diyorum 

Bir öpsem 

Bin yılların hasretiyle 

Yediveren gülleri açacak 

Hani diyorum 

Bir gelsen 

Gün sızdırmayan duvar çatlağından 

Güneş doğacak.. 

Hani diyorum hani 

Bunca vurduğun yetmez mi 

Hani diyorum 

Bu seraplara kapılmışken 

Sahrada gül bitmez mi 

Hani diyorum 

Göz yaşlarını sele versem 

Yürek pınarımda çağlasan 

Acıların gitmez mi 

Vedat K.16.04.2004(00:19)', 'Hani diyorum  Bir öpsem  Bin yılların hasretiyle  Yediveren gülleri açacak  Hani diyorum  Bir gelsen  Gün sızdırmayan duvar çatlağından  Gün...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hani-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '? Sevgiliye', 'sevgiliye-derin-oger-b7fec', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dil savurur

Bulutu düz duman

Yağmuru gürültüsünü yavaşlatır

Gözde sel revan

Sözcük tüy düşer

Ey sevgili dudaklarından

Kalbi çizmeye yeter

Kalpte gül revan

Uykuda rüyalar bağırır

Ne mümkün duyman

Aklıma bekleyişler birikir

Tende ruh revan...........', 'Dil savurur Bulutu düz duman Yağmuru gürültüsünü yavaşlatır Gözde sel revan Sözcük tüy düşer Ey sevgili dudaklarından Kalbi çizmeye yeter Ka...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiliye-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaza', 'kaza-halil-i-brahim-ozdemir-kgpzy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şişenin dibine vurmuştuk, gönlümüz şendi,

Ruya hızındaydık, araba ‘dolar’dı ‘yen’di,

Söylesene memur bey, böyle kaza gördün mü? 

Bu uçak bu karayoluna nereden indi?', 'Şişenin dibine vurmuştuk, gönlümüz şendi, Ruya hızındaydık, araba ‘dolar’dı ‘yen’di, Söylesene memur bey, böyle kaza gördün mü?  Bu uçak bu ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kaza-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüllerde', 'gonullerde-orhan-tuncay-lld3y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tatlı hoş bir burukluk

Anılarla birlikte gelen

Taht kuran gönüllerde

Kalbe derinden yerleşen

Geçmişten düşler gözlerde

Hayaller türlü çeşit

Sanki insanı eriten

İçine alıp düşündüren

Dolu dolu düşler

Düşünceler sıra sıra

Bir ırmak gibi coşup akan

Ve yeniden canlanan

Yaşlarla dolu gözlerde

Hem acı, hem tatlı günler

Sevilenler sevilmeyenler

Sarıp sarmalayan eskiler

Gönüllerde, gönüllerde', 'Tatlı hoş bir burukluk Anılarla birlikte gelen Taht kuran gönüllerde Kalbe derinden yerleşen Geçmişten düşler gözlerde Hayaller türlü çeşit ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonullerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Oldu', 'aksam-oldu-bedihi-kazim-nasuhbeyoglu-0cadk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk yuvaya beyazlara bürünerek gelenim,

Son yuvaya beyazlara sarılarak dönenim,

Beyaz tutkunu beyazım, dualarımda yaşattığım.

Akşam oldu hüzün çöktü ovaya,

Akşam oldu kuşlar döndü yuvaya,

Akşam oldu eller kalktı duaya,

Akşam oldu boynu bükük bir benim,

Bulut bulut yağmur yüklü gözlerim.

Yoruldun mu topraklara serildin? 

Kırıldın mı kime, neye darıldın? 

Gelin misin beyazlara sarıldın? 

Bu yol ıssız, gideni çok, dönen yok.

Kime derim anam gitti, anam yok.

Yem taşıyıp uçurttuğun yavrular,

Çığlık çığlık boş yuvaya döndüler.

Ana dedi ağladı, ana dedi yandılar.

Sen anasın yüreğini aç da gel.

Akşam oldu kanat, kanat uç da gel.

Akşam olur kuşlar döner yurduna,

Akşam olur hüzün çöker gönlüme,

Alem bilmez bu gönlümün derdi ne! 

Döner döner köyden yana bakarım.

Dilim varmaz söylemeye korkarım.

Gün bitimi boş yuvadan göçerim

Gün bitimi mor dağları aşarım,

Tek kanatlı düşe kalka uçarım,

Şu görünen avcıların köyü mü? 

Çözdükçe dolaşır derdin düğümü.

Yedi denklem yedi çözüm bulunsa,

Yedi yoldan yedi köye varılsa,

Yedi yerden yedi hançer vurulsa,

Yeter demem, eyvah demem, ah demem.

Kararlıyım, benden beni  söylemem.

Yazan yazmış, okuyamam yazımı,

Onda gizli dertlerimin çözümü,

Yüreğime kilitledim közümü,

Ağlamasam yangın durur diner mi? 

Su serpmesem gök alevler söner mi?', 'İlk yuvaya beyazlara bürünerek gelenim, Son yuvaya beyazlara sarılarak dönenim, Beyaz tutkunu beyazım, dualarımda yaşattığım. Akşam oldu hüz...', ARRAY['Türk Edebiyatı','Şiir','Bedihi Kazım Nasuhbeyoğlu']::text[], 8.5, '{"poet":"Bedihi Kazım Nasuhbeyoğlu","poet_slug":"bedihi-kazim-nasuhbeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/aksam-oldu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar İçin de', 'onlar-i-cin-de-orhan-tuncay-qjghn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yavaş yavaş örer ağını kader

Bu düzen böyle gelmiş böyle gider

Solar yaşam dolu çiçekler

Gün gelir hepsi için teker teker.

Işıklar donuklaşır, kararır her yer

Son perde zamanı gelince iner

Padişah, dilenci, general, er

Olurlar bilinmezde beraber.

Hep yarım kalır beklemeler

Ümitler daha da azalır her sefer

Böylece zamana karışır keder

Bilinir ki yanmayacak o fener.

Ve dünya durmadan döner

Kimileri sevinçle, umutla bekler

Onlar için de geçer gündüzler

Onlar için de örer ağını kader.', 'Yavaş yavaş örer ağını kader Bu düzen böyle gelmiş böyle gider Solar yaşam dolu çiçekler Gün gelir hepsi için teker teker. Işıklar donuklaşı...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/onlar-icin-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Kalbim', 'cocuk-kalbim-i-brahim-dikmen-2-bag4w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen,ilk aşkımdın,yüreğimdeki fırtınam,

Unutamadığım,erkeğimdin benim.

Küçüğüm,gonca gülüm derdin bana,

Nerdesin,canımın yongası,şimdi nerdesin.

Kalbimde fırtınalar kopuyor,yoksun diye,

Ağlıyor çocuk kalbim,ağlıyor sensizliğe.

Dayanamıyorum sevdiceğim,alışamıyorum yokluğuna,

Ağlıyor çocuk kalbim,ağlıyor sensizliğe.

Sen,ilk aşkımdın,yüreğimde esen kasırga,

Unutamadığımsın,kalbimin tek sahibi.

Minik kuşum,yosun gözlüm derdin bana,

Sevdiceğim,ilk aşkım,söyle şimdi nerdesin.

Kalbimde fırtınalar kopuyor,yoksun diye,

Ağlıyor çocuk kalbim,ağlıyor sensizliğe.

Dayanamıyorum sevdiceğim,alışamıyorum yokluğuna,

Ağlıyor çocuk kalbim,ağlıyor sensizliğe.', 'Sen,ilk aşkımdın,yüreğimdeki fırtınam, Unutamadığım,erkeğimdin benim. Küçüğüm,gonca gülüm derdin bana, Nerdesin,canımın yongası,şimdi nerdes...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cocuk-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararım Seni*', 'ararim-seni-bayram-tunca-lwtfd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ararım mazi albümünde resmini 

Ararım cennetlikler içinde ismini 

Ararım mahşer gününde cismini 

Cennet-i âlâda dahi ararım seni 

Öyle bir özümlemişim ki sevgini 

Her bir hücremde duyarım acını 

Muhtacım segine son nefes gibi

Ancak sen dindirebirsin sancımı

26.04.2004-16.04-İst.', 'Ararım mazi albümünde resmini  Ararım cennetlikler içinde ismini  Ararım mahşer gününde cismini  Cennet-i âlâda dahi ararım seni  Öyle bir ö...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ararim-seni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktan Utanma', 'asktan-utanma-melek-midikoglu-mljok', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin sesin 

Kulağımda çınlar durur

Ne olursun 

Bu duyduğum ses 

Senin olsun! 

Yok  yok  yok 

Arama dediler

Onu bulamazsın

Kendini yorma dediler

Seni duydum ya

Sesin kulağımda

Duysun tüm dünya

A-r-a-y-a-c-a-ğ-ı-m

Gülümsedin de; 

Uçtu kelebeğim...

Yol yakınken

Daha da geleceğim!', 'Senin sesin  Kulağımda çınlar durur Ne olursun  Bu duyduğum ses  Senin olsun!  Yok  yok  yok  Arama dediler Onu bulamazsın Kendini yorma ded...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/asktan-utanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün Senin İçin', 'bu-gun-senin-i-cin-hafize-zuluflu-jpowi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sayfalarca kitap okudu

Bıkmadı, usanmadı

Sokak çocukları için bir toplantıya katıldı

Özürlüler için rapor hazırladı

Heveslendi bahara çiçek açtı ağaçlarda

Caddelerde lüzumsuz hız yaptı

Hemzemin geçitte bir kazaya karıştı

Yağmur oldu yağdı rüyalarına

Rüzgar oldu dağıttı umutlarını

Bu gün kendine ihanet etti

Seni beklemedi….

Gel hadi! 

Güneş batıdan doğsun, ters yüz olsun dünya

Ayin yapsın, tapınsın tüm sevenlerin

Dağlarının yamaçlarında

27 Nisan 2004', 'Sayfalarca kitap okudu Bıkmadı, usanmadı Sokak çocukları için bir toplantıya katıldı Özürlüler için rapor hazırladı Heveslendi bahara çiçek ...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-gun-senin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimdeki Çocuk', 'yuregimdeki-cocuk-muhsin-bukucu-05fd6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir çocuk yaşıyor hala...

İnadına hem de, geçen senelerin

Göbek bağı benliğimdedir

İzin vermedim koparmasına kimsenin

Zaman zaman; 

Ardı sıra

Taş ocakları  devrildiğinde bile

Yüreğimin her bir köşesine

İsyan edecek olsam da; 

Vefasızlıklara

Yıkılışlara

Engeller beni hep, minicik elleriyle

Sevgisidir ona, o gücü veren

Beklentisiz sevgisidir boynumu büken



Gözlerimde bir çocuk yaşıyor hala...

İnadına hem de, geçen senelerin

Göbek bağı benliğimdedir

İzin vermedim koparmasına kimsenin

Zaman zaman...

Fark etsem de yüzlerdeki maskeleri

İsyan edecek olsam da; 

İçi boş sözlere

Sahte gülüşlere

Engeller beni hep, gülümsemesiyle

Sevecenliktir ona, o gücü veren

Beklentisiz gülümsemesidir boynumu büken



Şen kahkahalar sizin olsun! 

Bana yeter, çocuksu gülümsemeler

Gökkuşağıyla dolu dünya sizin olsun! 

Bana yeter, kir bulaşmamış minicik eller!', 'Yüreğimde bir çocuk yaşıyor hala... İnadına hem de, geçen senelerin Göbek bağı benliğimdedir İzin vermedim koparmasına kimsenin Zaman zaman;...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yuregimdeki-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Olan', 'zor-olan-muhsin-bukucu-x5dz3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çalışırken seni saklamaya,

Haberim yok, hissetmedim hiç! .

Dağlar devrilmiş  omuzlarıma.

Layık olabilmek için dostluk duygusuna,

Haberim yok, hissetmedim hiç! .

Yüreğimde denizler doğmuş, akan göz yaşlarımla



Bir kumsala benzetirsek, yürüdüğüm hayat yolunu

Sahile vuran taşları ise dostluklara

Toplayıp ta avuçlarımda

Denize atmaya kıyamadığım

Birkaç güzel taştan birisisin! 

Seni, altın harflerle kazıdım yüreğime

Unutmamak için, bir an bile olsa! 

Bakışlarını nakşettim göz bebeklerime

Kıyamadım hiç, kapatmadım gözlerimi

Bir an için olur da unutur belki

Endişelendim vefasızlık gösterir diye...

Alıştım uykusuzluğa

Sancısı tutmuş bebeği dinledim durdum uzaklardaki

Bekçi düdükleri yokladı hep kulaklarımı

Ayyaşların bir köşe başında horultusunu

Sokak kedilerinin derin uykusunu

Dinledim hep, kırpmadan gözlerimi



Lakin...

Zormuş hasretin

Zormuş yokluğun

Alışamadım....

Alışamadım be gülüm! 

Yalnız gecelerden

Acıtan, inciten hecelerden

Susuzluktan

Ekmeksizlikten

Zormuş be gülüm! .

Zormuş hasretin

Zormuş yokluğun



Çalışırken seni saklamaya,

Haberim yok, hissetmedim hiç! .

Dağlar devrilmiş  omuzlarıma

Layık olabilmek için dostluk duygusuna

Haberim yok, hissetmedim hiç! .

Yüreğimde denizler doğmuş akan göz yaşlarımla.



Elbet bir gün düşeceğim aklına

Bir acılı bakış kaplayacak gözlerini

Dost özlemi saracak yüreğini

Ve... o zaman anlayacaksın

Yüreğin için de  kolay olmadığını...', 'Çalışırken seni saklamaya, Haberim yok, hissetmedim hiç! . Dağlar devrilmiş  omuzlarıma. Layık olabilmek için dostluk duygusuna, Haberim yok...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/zor-olan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Dilimi', 'zaman-dilimi-muhsin-bukucu-uhsc3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Takvimler bölündü ikiye,

Birisi senden önce,

Birisi senden sonra...

Gençlik bölündü ikiye.

Birisi senden önce,

Birisi senden sonra...



Sen çıkana dek karşıma,

Kışı, salkım saçaklarıyla,

Yazı, gelincikleri, papatyalarıyla,

Severdim önce.

Yüksünmezdim hiçbir derde,

Çaresizlik nedir bilmezdim.

Ümitsizlik nedir bilmezdim.

Hiç ellerim titremezdi...

Hiç sesim titremezdi...

Ağlamazdım hiç eskiden.

Sızlamazdı bağrım

Sen çıkana dek karşıma.



Bir gün sen çıktın karşıma...

Söktün aldın benden

Ümidi,sevgiyi,muhabbeti.

Gözlerimdeki hayat ışıltısını,

İçimdeki heyecanı,

Ayaklarımdaki dermanı,

Söktün aldın benden.



Sen bir şeytansın! .

İnsan olamazsın! .

Bir zerre kadar da olsa bile,

Duygusu olur insanların.

Ağlayamasa bile,

Gözleri dolar insanların.

Karşında; 

Bir dağ devrildi de,

Titremedi hiç dudakların.

Hayat yolum bölündü sayende

Birisi senden önce,

Birisi senden sonra....', 'Takvimler bölündü ikiye, Birisi senden önce, Birisi senden sonra... Gençlik bölündü ikiye. Birisi senden önce, Birisi senden sonra... Sen çı...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/zaman-dilimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan bir dünyada', 'yalan-bir-dunyada-gulsum-tanriverdi-qd4oo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tüm çığlıklar boşuna; 

Herşeye rağmen güneş yine doğdu işte.

İşte dünya bu kadar yalan! 

Geçmişe karışabiliyor herşey bir anda

Unutulabiliyor herşey; 

Ölüm bile! 

Geçmiş, hatırlamada bir avuç rüya

Gelecek ise binbir meçhul

Kim karşı koyabilirki zamana

Herkes bu zamana kul.

Ben değil miydim bir zamanlar

Kırlarla kucaklaşan,

Şimdi bu taştan odalarda kuruyan

Bu gözler değil mi

Bir ağlayan, bir gülen

Gel de inan; 

Ne yalandır şu tabiat

Bir yılda dört kılığa bürünen.

Kim kanmadı ki bu yalanlara.

Kim soğukta üşümeyen, sıcakta ısınmayan.

Kim aldanmadı bu dünyaya

Üzerinde yaşayıp da..

(İst. 12.Mayıs.1992)', 'Tüm çığlıklar boşuna;  Herşeye rağmen güneş yine doğdu işte. İşte dünya bu kadar yalan!  Geçmişe karışabiliyor herşey bir anda Unutulabiliyo...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Tanrıverdi']::text[], 8.5, '{"poet":"Gülsüm Tanrıverdi","poet_slug":"gulsum-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yalan-bir-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum Gelini', 'erzurum-gelini-fahrettin-koseoglu-tazu9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Erzurum dedikleri dümdüz bir ova.

Karlar beyaz kuş olmuş, dağları yuva

Anam, adın dilimde sessiz bir dua.

İncinirsin, elinden tutamıyorum.

Bu odalar bir tek senin mi kaderin? 

Yüreğine dert olmuş bütün kederin.

Ne kadardı bu yaran, ne kadar derin? 

Paramparça oluyor, bakamıyorum.

Kolların çürümüş, iğneler tutmuyor.

Uykun var, doktorlar seni uyutmuyor.

İlaçlar ateşini hiç soğutmuyor.

O halini, aklımdan atamıyorum.

Yanağımda yaradır son öpücüğün

Yatağında, yanında bak küçücüğün

Sana mı kuruldu bu tören bu düğün

Gidiyorsun, yoluna duramıyorum.

Dağlar sarmış Erzurum’un her yanını

Gelin ettik seni salını salını.

Erzurum da anam bıraktın canını.

Görme anam halimi, kanamıyorum.', 'Erzurum dedikleri dümdüz bir ova. Karlar beyaz kuş olmuş, dağları yuva Anam, adın dilimde sessiz bir dua. İncinirsin, elinden tutamıyorum. B...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Köseoğlu']::text[], 8.5, '{"poet":"Fahrettin Köseoğlu","poet_slug":"fahrettin-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/erzurum-gelini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinçaltı Şiirleri-11', 'bilincalti-siirleri-11-oguzkan-bolukbasi-g7a50', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni küçük odalarımda saklıyorum

aslında özgür olmalıydın

ya da ben yanmalıydım

yaşamayı seçtim

senin olduğun havayı koklamayı

kendimi kandırıyorum', 'seni küçük odalarımda saklıyorum aslında özgür olmalıydın ya da ben yanmalıydım yaşamayı seçtim senin olduğun havayı koklamayı kendimi kandı...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilincalti-siirleri-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Veda', 'son-veda-ahmet-turan-altunsu-rry7q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'serzeniş/

artık aynalara bakmayacağım,

...anlaşmayacağım resimdeki gözlerinle! ..

inat bu ya; alabildiğine yaşlanacağım! 

altı üstü bir ‘’son nefes’’ değil mi? ..

vereceğim işte! 

ilk kez, konuşmayacağım seninle,

...son kez,  y a z m ı ş  olacağım! 

hikâye/

sende şen kahkahalar, bende cinnet ve kahır,

....ben sende öldüm melek yüzlüm! ..

önümde Nâzım’ dan: Zühre ile Tahir…

Orhan Veli’ nin dediği gibi

....‘’…bir elinde cımbız, bir elinde ayna…’’

....ben yokum ya, çek çek(!)   oyna! ..

oysa Tahir çok şanslı Zühre’ den yana,

.....bütün kabahat benim; 

........onlar masalda kahraman,

.............benimse hayatım roman! 

hamiş/

hoşcakal çingenem, kendinle övün! 

sen ey çeribaşı: mutlu ol,sevin! 

                                      26.04.2004', 'serzeniş/ artık aynalara bakmayacağım, ...anlaşmayacağım resimdeki gözlerinle! .. inat bu ya; alabildiğine yaşlanacağım!  altı üstü bir ‘’so...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/son-veda-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ahmet-turan-altunsu-f6vqk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılıktı korktuğum,

İşte başıma geldi; 

Boğazım düğüm düğüm! ..

Her şey nasıl güzeldi? 

Lâkin uzaklardaydın…

Resmindi son gördüğüm! ..

                       26.04.2004', 'Ayrılıktı korktuğum, İşte başıma geldi;  Boğazım düğüm düğüm! .. Her şey nasıl güzeldi?  Lâkin uzaklardaydın… Resmindi son gördüğüm! ..     ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayrilik-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşmeye Görsün', 'dusmeye-gorsun-cafer-tayyar-ozkan-9ta4d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda yeli eser durur başımda,

Artık deli derler orta yaşımda,

İnat seli değil, dileğim murat.

Sen de kaçar oldun, yoksun karşımda. 

Gönüllere ateş düşmeye görsün,

Bedenler kavrulur seni beklerken.

Bir nefesin kadar sana muhtacım,

Sevincin ilacım, sevgin mabedim,

Aşk zehri aksa da kalbim bağlıdır,

Kalbimin sahibi, sevdan baş tacım. 

Karagözlü yarin gelmeye görsün,

Arzular depreşir seni yaşarken...

17 Şubat 2004 Istanbul Sarayburnu', 'Sevda yeli eser durur başımda, Artık deli derler orta yaşımda, İnat seli değil, dileğim murat. Sen de kaçar oldun, yoksun karşımda.  Gönülle...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dusmeye-gorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Yaşa', 'oylesine-yasa-ali-osman-yilmaz-rokzi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatını,

Anılarını,acılarını,

Düşünerek değil,

Yeni anılar yaratmak için yaşa.

Gönlünü ferah tut,

Ama,sakın aşık olma,

Yoksa,yanarsın sende ben gibi,

Yalnızca anılarını,

Ve acılarını yaşarsın,

Hemde bir başına,

Yapayalnız ve özlemler içinde.

Deniz kıyısında,martılarla söyleşir,

Sevda kuşunun kanadına,

Sevdanı yükleyip yollarsın O''na.

Sen beni dinle dostum,

Boş ver her şeye,

Artık hayatını yaşa.

Anılarını ve acılarını,

Düşleyerek değil,

Yeni anılar yaratmak için,

Boş ver anasını satayım,

Boş ver gitsin be,

Öylesine yaşa.', 'Hayatını, Anılarını,acılarını, Düşünerek değil, Yeni anılar yaratmak için yaşa. Gönlünü ferah tut, Ama,sakın aşık olma, Yoksa,yanarsın sende...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oylesine-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Varmı Senin?', 'haberin-varmi-senin-ali-osman-yilmaz-p1drt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç gün,kaç gece,

Beklemiştim seni,

Bir ömür boyu beklemek,

Meçhulden gelecek sevgiliyi,

Haberin var mı senin? 

Kaç gece koynumda,

Hasretine sarılıp uyumuştum,

Kaç gece seninle,

Deliler gibi sevişmiştik,

Haberin var mı senin? 

Sana kavuşmak için,

Her sabah yola çıkardım,

Nerede olduğunu bilmeden,

Tam sana kavuşmayı unutacakken,

Aklıma geceler gelir ve ben,

Hemen geri dönerdim.

Hiç olmazsa yatağımda,

Sen olmasan da hayalin,

Sana olan hasretim vardı,

Birde geleceğini düşlemek,

Bir sabah vakti,

Kapıyı çalacağın o anı beklemek? 

Bu ümitlerim olmasaydı,

Şimdi yaşıyor olurmuydum? 

Haberin var mı senin?', 'Kaç gün,kaç gece, Beklemiştim seni, Bir ömür boyu beklemek, Meçhulden gelecek sevgiliyi, Haberin var mı senin?  Kaç gece koynumda, Hasretine...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/haberin-varmi-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yerde Sen Varsın', 'her-yerde-sen-varsin-ali-osman-yilmaz-tqoud', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nereye baksam,

Seni görüyorum.

Her yerde,her şeyde,

Sen varsın.

Geceleri bana göz kırpan,

Yıldızlara bakıyorum,

Seni görüyorum.

Güneş doğuyor sabah,

Sanki sen ışıldıyorsun,

Sevda bahçelerinde dolanıyorum,

Tüm çiçekler,sana benziyor,

Ve en güzeli de,sen kokuyorlar.

Akşam olunca gökteki ay,

Seni hatırlatıyor yine.

Yatağıma yatıyorum,

Rüyalarımda hep sen varsın.

Soruyorum kendime? 

Her yerde,her şeyde,

Sen varsan sevgilim,

Ben neden yalnızım? 

Sensizliği ve yalnızlığı,

Seninle ama sensiz,

Neden yaşıyorum?', 'Nereye baksam, Seni görüyorum. Her yerde,her şeyde, Sen varsın. Geceleri bana göz kırpan, Yıldızlara bakıyorum, Seni görüyorum. Güneş doğuyo...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/her-yerde-sen-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir', 'nedir-oguzkan-bolukbasi-v9urn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni boydan boya yüzeceğim

bir hayat boyu

okyanussun

senin renklerinin altından geçeceğim

gök kuşağısın

sana dokunurken

uyanacağım

rüyasın

ama nedendir

aklımda

yaşadığım her şeyde

sen varsın

sen var mısın

varsan

ufuksun

yok musun

yoksan

benimsin', 'seni boydan boya yüzeceğim bir hayat boyu okyanussun senin renklerinin altından geçeceğim gök kuşağısın sana dokunurken uyanacağım rüyasın a...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nedir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Şehri', 'dusler-sehri-bekir-mutlu-gokcesu-qxrd2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beynim 

Bastırmaya çalışırken

İçten içe ateşler 

Bir isyanı yüreğim

Gözlerim gözlerini ister

Dudaklarım dudaklarını

Zor tutarım ayaklarımı

Dilim haykırmak ister adını 

Dokunmayı sorar ellerim

Bilmiyorum dedikçe

Artar baskı, çoğalır saldırı

Ayaklanır tüm hücrelerim

Şaşar aklım, fikrim

Bu bir kaos, başkaldırı

Yürünür sevdamın başkentine

Karadır gözleri, kuşatırlar şehri

Daralttıkça daraltırlar çemberi

Nefes nefese sürdürürler takibi

Ya sen illaki

Ya da bulacaklar faili

Fakat gel gör ki

Yoktur bu diyarın ne sahibi

Ne de tek bir sakini

Sadece aklım seçer

Güneşin yedi rengindeki

Ve o yedi rengin

Her türlü olabilirliğindeki

Işık hünerlerini

Ama ifade edemez aklım

İzahı yok ki

Çaresiz terk ederler

Düşler şehrini...', 'Beynim  Bastırmaya çalışırken İçten içe ateşler  Bir isyanı yüreğim Gözlerim gözlerini ister Dudaklarım dudaklarını Zor tutarım ayaklarımı D...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dusler-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyen Sol Ayağım / itiraf', 'usuyen-sol-ayagim-itiraf-k-muran-esen-3ggyf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutfakta çalışırken setin önünde durduğum yer genelde aynıdır. Aynı noktada dikilmek için bir çaba sarfetmiyorum ama, nasıl oluyorsa hep aynı noktada duruyorum. Bulaşık yıkarken, salata yaparken, bulaşık makinesini doldururken ve boşaltırken hep aynı yere basıyor ayaklarım. Bir tencere sarma mı yapacağım, yine ayaktayım ve aşağı- yukarı aynı yerdeyim. Alışkanlık işte..... 

Salonda oturduğum yer de hep aynıdır. Kimseye vermem yerimi. Eğer gelen misafirlerden biri yerime oturursa; bütün misafirperver görüntümü takınır, nazik bir ifadeyle, “ Orada  rahat edemezsiniz, şöyle buyrun lütfen! ” diyerek kaldırırım yerimden, başka yere oturturum... Söylemesi biraz ayıp oldu belki ama, gerçek bu.

İşte mutfakta genelde hep aynı yerde durarak iş yaparken, şu soğuk günlerde ayağım üşüyor. Ayaklarım değil, a – ya - ğım üşüyor. Her ne hikmetse sol ayağım üşüyor sadece. Mutfakta kalorifer peteği yok. Mutfağın salona açılan kapısından gelen sıcaklık, mutfağı yeteri kadar ısıtmıyor çok soğuklarda. Sol ayağım sızlıyor üşümekten. Allah Allah! Bir türlü çözemiyorum nedenini. Neden sağ ayağım üşümüyor da sol ayağım üşüyor? 

Aslında kabahat bende. Yaklaşık yirmi gün kadar önce, mutfaktaki kaplama halıyı kaldırttım, mutfak tabanını muşambaya benzer bir döşeme maddesiyle kapladık, temizliği kolay olsun diye. Şöyle ahşap görünümünde bir şey de, adını bilmiyorum. Parke gibi duruyor. Halıyı temiz tutmak, temizlemek çok zor oluyordu. O nedenle yaptık bu değişikliği. İşte o günden beri sol ayağım ısınmıyor, üşüyor. Üşüyor ne kelime, donuyor donuyor. İyi de sağ ayağım neden üşümüyor?  Kafayı yi’ce’m nerdeyse.

Kendi kendime sebep bulmaya çalışıyorum. ” Demek bende romatizma var, ayağım o nedenle ısınmıyor bir türlü ve ağrıyor, ” diyorum.  İyi de sağ bacağımda niye romatizma yok? O bacak da benim. Birden aklıma, tv’de bir doktordan duyduğum şu cümle geliyor: “Bayanlar mutfakta dikilirken ya da ütü yaparken, farkında olmadan, vücut ağırlıklarını  genellikle sol ayaklarına verirler.”......Hııımmm! Demek ki ben de  ağırlığımı sürekli sol ayağıma veriyorum, dolayısıyla sol ayağımı çok yoruyorum. Ve o nedenle zaten yorgun olan ayağım üşüyor...Nasıl da biliyorlar herşeyi şu doktorlar! 

Fakat yapacak fazla bir şeyim yok bu konuda.Yalnız,  tv’de duyduğumun tersine, aklıma geldikçe ağırlığımı sağ ayağıma vermeye çalışıyorum, olmuyor; bu kez de yorulup gidiyorum. Bir şey doğrayacaksam, nasıl doğrayacağımı şaşırıyorum o zaman. Dikkatim ayaklarıma gidiyor çünkü. Öyle sol ayağım üşüye üşüye, sanki mecburmuşum gibi hep aynı noktada çalışarak, zamanımın çoğunu mutfakta geçiriyorum.Yalnızca üşüse iyi, sonra da ağrımaya başlıyor sol ayağım. Bir yandan  “Keşke halıyı kaldırtmasaydım,” diye söyleniyorum kendime;  bir yandan da ”Sağ ayağımın altında da halı yok,  o niye üşümüyor? ” sorusuna yanıt bulmaya çalışıyorum.

Galiba sol ayağımda bir problem var. Galiba değil, kesin var. Yoksa durup dururken neden üşüsün ve ağrısın? Ne olabilir ne olabilir? ..... Damar tıkanıklığı olabilir örneğin. Aman Allah korusun! .... Kan rahat hareket edemediği için, ayağıma yeterli kan gelmiyor, beslenemiyor ve o nedenle üşüyor olabilir. (Aslında kulaktan dolmaların dışında bir tıp bilgim yok da, öylesine fikir yürütüyorum işte.)   Bir de yıllar önce düşmüştüm de bu  ayağım onbeş gün alçıda kalmıştı. Taaa o zamandan  bir eser kalmış olmasın? Zaten düşmelerin, çarpmaların etkileri yıllar sonra ortaya çıkarmış. Derken kalbim aklıma geliyor. Kalbimiz sol tarafta ya; üşüyen ve ağrıyan bacağım da sol, sakın kalple ilgili bir problem olmasın! Bunu en kuvvetli ve en tehlikeli olasılık olarak görüyorum. Zaten  kalbim arada bir,  ökseye takılmış kuş gibi çırpınıp, sonra eski  temposuna dönüyor. “Ritim bozukluğu” demişti doktor. ” Kahveyi daha az içmeliyim.” Diye düşünüyorum. Günde sekiz- dokuz fincandan dört fincana indirdim, daha aza indiremem ki! Kahvesiz yapamam.....” Kahve içmezsen ölmezsin kızım, ama, kalpten pat diye gidersin,” diyorum kendime. “Zaten yaşın elli olmak üzere.”

Dün,  salata yapıyordum yine aynı noktada dikilerek. Alışkanlık işte. Tam o dikildiğim noktadaki ve  setin altındaki dolabın kapağını açtım bir şey almak için. Bir  de ne göreyim! Baktım, tam o parke görünümündeki döşemenin bitip de dolabın başladığı yerde bir delik var. Tabandaki ahşap zeminde yani. Allah Allah! Nasıl görmedim bunu şimdiye kadar! Ve oradan buz gibi soğuk geliyor. Tam sol ayağımı bastığım yer işte orası.....Şimdiye kadar, halı kapatıyordu demekki o deliği. Yeni döşeme dolabın altına kadar serilmediği için delik açıkta kalmış, oradan  buz gibi hava üfürüyor. Ve zavallı sol ayağım işte bu delikten gelen soğuk hava nedeniyle üşüyormuş düşecek gibi. Ağrıması da cabası.

 Yirmi gündür bu deliği nasıl farketmedim, nasıl görmedim diye şaşırdım kaldım. Ve kızdım kendime...Zavallı sol ayağımın neden üşüdüğünü, ağrıdığını böylece çözdüm. Çözmedim de daha doğrusu, tesadüfen buldum. Oh çok şükür! Demek ki sol ayağımda bir problem yok, damar tıkanıklığı yok, romatizma yok. Böylece, kahveyi daha da azaltmama gerek kalmayacak. Nasıl sevindim anlatamam.........''Allah fakir kulunu sevindirmek isterse; eşeğini kaybeder üç gün sonra buldururmuş,'' derler ya, bana da öyle yaptı işte...Teşekkürler Allahım! Seni çok seviyorum.

(Şimdi; “ Nasıl görmezsin o deliği? Kör müsün? ” diyeceksiniz. Haklısınız. Valla o deliği görünce ben de aynı soruyu sordum kendime. En kısa zamanda göz doktoruna gitmeyi düşünüyorum.)', 'Mutfakta çalışırken setin önünde durduğum yer genelde aynıdır. Aynı noktada dikilmek için bir çaba sarfetmiyorum ama, nasıl oluyorsa hep ayn...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/usuyen-sol-ayagim-itiraf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalanmayı bilmiyoruz...', 'sevdalanmayi-bilmiyoruz-yusuf-ziya-leblebici-84dch', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangimizin gözlerinden yaş akmadı

hangimiz aşık olmadık, 

   aşkı tanımasak da

Kimimiz Ferhat, kimimiz Şirin sandık kendimizi.

Heyhat; 

karşımızda görünce koca dağları

zorluklara çevirmedik mi sırtımızı! 

Biz mi aşık olamadık,

aşk mı bizi bulamadı,

yoksa dört harfe sıkıştık da

ellerimizin arasına mı aldık başımızı...

Sevda uğruna yıkılan dağlar

Yaşanan güzel aşklar dünlermiş meğer

ya da sevmeyi, sevilmeyi bilenler

mazidelermiş mi diyelim...

Gözbebeklerimiz parladığında

yüreklerimiz zıpladığında

hep gerçekler mi vardı karşımızda

yalanlar yok muydu yanıbaşımızda.

Platonik aşklar

anlamını daha çözemeden

girdiğimiz karasevdalar,

kalbimizi delen sahte oklar

ne kazandırdı oyalamadan başka.

Sevecek kadın için Aslı''mı gelmeliydi

Kerem''mi olmalıydık sevdayı yaşamak için.

sevmeyi bilmiyoruz 

sevilebilmek

elele verip yürekleri paylaşabilmek

ve Kerem ile Aslı

  ve Ferhat ile Şirin

    ve Yusuf ile Züleyha olabilmek için

kaç Türk filmi izlemek

kaç roman okumamız gerekiyordu.

Sevdanın anlamını bilmeden

arabesklerin ritminde,

ellerimizde şişelerle gidiyoruz 

modaya ayak uydurmak uğruna.

Damarlarımızdaki kana sevda diyemediğimiz

dudaklarımızdan dökülen kelimelerin

anlamlarını bilemediğimiz,

nefes almamızın değerini çözemediğimiz

bir hayal aleminde yaşıyoruz.

Bu hayallerin adına da

bilmeden sevda diyoruz.

Kaçımız sabahlara dek 

bağdaş kurup şiirler yazdı yüreğine

kaçımız bir parçasının tapusunu

sevdasına bağışladı! 

Heyhat; 

Dağa taşa, 

 tencereye tavaya,

  mankene futbolcuya

aşık olmayı biliyoruz da

sevdayı hakedene

sevdalanmayı bilmiyoruz.', 'Hangimizin gözlerinden yaş akmadı hangimiz aşık olmadık,     aşkı tanımasak da Kimimiz Ferhat, kimimiz Şirin sandık kendimizi. Heyhat;  karş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sevdalanmayi-bilmiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açık Turuncu', 'acik-turuncu-erol-ka-dw5gc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kizin gözleri kitabi mukaddesle boyanmis

Orada tek bir isik parlamayacak

Seytan oluncaya dek yanmis

Lisanin eteklerindeki eller

Kimin fikriydi bu

Iste babil de yikildi

Bahçene girdim ve kabrine

Portakallar sakladim

Bilmem ben kendi üstüme oyuncu

Oyun sert, tas sert, sehir sert

Iyi polis yok oldu hep sükut

Kus yuvalarini kusat gölgeleri kurut

Bana ayakkaplarini göster

Tipki filmlerdeki gibi

Siyah olman benim fikrimdi', 'Kizin gözleri kitabi mukaddesle boyanmis Orada tek bir isik parlamayacak Seytan oluncaya dek yanmis Lisanin eteklerindeki eller Kimin fikriy...', ARRAY['Türk Edebiyatı','Şiir','Erol Ka']::text[], 8.5, '{"poet":"Erol Ka","poet_slug":"erol-ka","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/acik-turuncu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakanıza Bir Gül Takın', 'yakaniza-bir-gul-takin-necmi-unsal-2p6vb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bayat  sözler                  

Baygın  gözler                

Aynı  yüzler                   

Aynı  sözler                    

Yarışanlar                       

Karışanlar                       

Her  şeye                        

İnceden  inceye              

Tartışanlar                      

Sataşanlar                        

Can  yakanlar

Kafayı  takanlar

Taş  atanlar

Çelme  atanlar

Caka satanlar

Tafra  satanlar

Çalım  satanlar

Kafa  atanlar

Kurşun  atanlar

Aşık  atanlar

Fişek  atanlar

Kinle  bakışanlar

Atışanlar

Küsenler

Süsenler

Bunları  bırakın

Sevmeye  bakın

Şapkanıza,

Yakanıza

Artık  bir  gül  takın

Keyfinize  bakın! 

18 Mart 2004 Perşembe,  Danimarka-Koge 19.41', 'Bayat  sözler                   Baygın  gözler                 Aynı  yüzler                    Aynı  sözler                     Yarışanlar  ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yakaniza-bir-gul-takin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '! ! ! ! ! -Hüzün Yaprağı-! ! ! ! ! ! !', 'huzun-yapragi-halit-demir-ifgdz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlkbahar olunca, dalda yeşilsin

Sen ki bu  bahçede, yeni değilsin

Öyle bir bak ki, ruhum  gerilsin

Gözlerde yaş durmaz, hüzün yaprağı

O Dalda yapraklar, durur mu sandın

Düşer de toprakta, kalır mı sandın

Acılar gün gelir,bitermi sandın

Gönüller kin tutmaz, hüzün yaprağı

Hep seni fısıldar, dışarda rüzgar

Ömür mevsimimden, düşen yapraklar

Bunun ne mekanı, nede zamanı var

Ömüre sur durmaz, hüzün yaprağı

Sevgine muhtaçtım, kısacık yolda 

Çalıştım didindim, hayat yolunda

Çatlayan ellerim, nasır tutsa da

Tenimde ter durmaz, hüzün yaprağı

Su olup akarım, kurak çöllerde

Bir Anız fidanı, dağın böğründe

Sevgine muhtacım, gurbet elinde

Ele duçar olmaz, hüzün yaprağı

Sonbahara döndü, gönül defterim

Sayfalarında bil ki, seni gizlerim

Hep adını yazıp, resmin çizerim

Sayfa yazı sunmaz, hüzün yaprağı

Kalemim kırılmış, mürekkep bitmiş

Azrail bu canı, almaya gelmiş

Diz toprağa dayanmış,  fer’i kesilmiş

Nefes sona gelmiş, kadim kesilmiş

Yürekler set çekmez, hüzün yaprağı.

Kısık iniltinin, kulakta sesi

Yaprağın duyulan, en son nefesi

Çağırdı bilmem ki, beni neresi

Mekanlar sır bilmez, hüzün yaprağı

Gün olur bedenim, makbere düşer

Sorguya, suale, gelmiş melekler

Bir yanımda nekir, bir yanda münker

Dile emir olmaz, hüzün yaprağı

Dünyada hiç sonu, yoktur emelin 

Hasat’ı cennettir, güzel amelin,

Huzuru-mevlâda, bomboşsa elin

Ele hisâb olmaz, hüzün yaprağı

Halit Demir- 14.04.2004', 'İlkbahar olunca, dalda yeşilsin Sen ki bu  bahçede, yeni değilsin Öyle bir bak ki, ruhum  gerilsin Gözlerde yaş durmaz, hüzün yaprağı O Dald...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/huzun-yapragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çıkar (Sevgili Eşim''e) ''2''', 'ne-cikar-sevgili-esim-e-2-halit-demir-5tv23', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saray kurdum, yüreğimde eyledim

Taht kurup ta, orda sultan eyledim

Sevgi sunup, kervanımı eyledim

Hancı olup, döşek kursan ne çıkar

	

Bu bedenim, sevgin ile beslenir

Gönlüm sensiz, hasretinle hislenir

Sevgi dilim, hep sinene seslenir

Bana gurbet, sunmuş olsan ne çıkar.', 'Saray kurdum, yüreğimde eyledim Taht kurup ta, orda sultan eyledim Sevgi sunup, kervanımı eyledim Hancı olup, döşek kursan ne çıkar 	 Bu bed...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-cikar-sevgili-esim-e-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayyaş', 'ayyas-sirma-mersin-s6zkp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir duvarın dibinde...

Bi ayyaşın naraları ile, yırtılan gece; sokağı saran sessizliği dağıtıyordu... 

Gecenin ayazında; kendini ısıtmak için, şiseye sarılıyordu.

Dibine vurmuş   yalnızlığın gölgesinde iken; 

Yudumlarında bile,sevdiğini düşünüyordu.

Bir ara:

Bir daha sevmeyeceğine dair; kendi kendine sözler veriyordu.

Yüzü kirli, nefesi alkol kokuyordu...

Sevgisine karşılık bulmadığı için; 

Bi ayyaş olduğunu söylüyordu, gelen geçene...

Birazdan o köşede; sızıp kalacaktı, öylece.

25.04.04', 'Bir duvarın dibinde... Bi ayyaşın naraları ile, yırtılan gece; sokağı saran sessizliği dağıtıyordu...  Gecenin ayazında; kendini ısıtmak içi...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayyas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Doluyum Bugün', 'huzun-doluyum-bugun-halit-demir-xafed', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzün doluyum bugün... 

Yine hüzünle doldu bu gecem

Ard arda yaktığım sigaralar

İzmaritlerle dolu kül tablalarım

Hüzün doluyum bugün...

Ne yapsam, ne etsem bilemiyorum

Silemiyorum bir türlü seni

Ve bende kalan son cismini

Atamıyorum ki seni …

Bende kalan, o en son  benliğini….

Isırdığım lokmalar, boğazımda kenetleniyor

Senin ismini söyleyemiyorum artık

Elime aldığım kalemler,ismini yazmıyor 

Sana seslenmek istiyorum, ama nefesim çıkmıyor

Senden uzakta olmaktan

Her an seni hülyalarımda yaşatmaktan

Seni rüyalarımda görmekten

Seni düşünmekten...

Tükendim artık ben

Ve ben sensiz her gün 

Yeni bir hüzünle doluyorum

……. BİRTANEM...', 'Hüzün doluyum bugün...  Yine hüzünle doldu bu gecem Ard arda yaktığım sigaralar İzmaritlerle dolu kül tablalarım Hüzün doluyum bugün... Ne y...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/huzun-doluyum-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskunluk', 'suskunluk-sirma-mersin-72v3y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suskunluğum senin gidişinle başladı; sesim çıkmıyordu...

Düşüncelerimde dünden kalan anılarım vardı, sadece.

Gönül matemini yaşarken, ruhum.

Bedenimi saran sancılar; 

Sol yanımı da senle götürdüler.

Yüreksiz bi benliğin yaşaması; bitkiselle dönmüş bir sevdaydı.

Soğuk odanın ürkütücü sessizliği ile; 

Geçmek bilmeyen günler, yaşanıyordu.

Tüm suskunluğumun anlamını; yalnızca, ben biliyordum.

Yorgun düşmüş umut bile; beni, sensizliğin pençesinden kurtaramıyordu.

Yaşayan bi ölü benliği; ancak mucize ile kurtulacağına inanıyordu, herkes.

Evet! Sevginle yüreğimin içine girdiğinde; yaşam yeniden başlayacak...

Sevdiğim! 

Hiçbir zaman ben seçmedim, sensizliği...

26.04.04', 'Suskunluğum senin gidişinle başladı; sesim çıkmıyordu... Düşüncelerimde dünden kalan anılarım vardı, sadece. Gönül matemini yaşarken, ruhum....', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/suskunluk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narkoz Öncesi', 'narkoz-oncesi-celal-sahin-8tsba', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üzerinde umut güneşinin yansıdığı

Mavi sularının dibine çekiliyorum.

Sular koyulaşıyor,mavi laciverde

Lacivert siyaha dönüşmede,

Koyu karanlıkta yapayalnızım....

Çıplak yüreğimin titremesi

Azrail’in soğuk nefesinden.

Film şeridi gözlerimde yaşamım,

Dertlerimi benimsedim

Hayatın armağanı kabul ettim

Korkum çaresizliğimden.

Karanlık odamın dört duvarından

Yüreğimi kalaylamış sırlarım

Dudaklarımda pas tadında

Zamanın anlamını yitirdiği yerde.

Yazdığım mektubun gideceği adresi biliyorum

Mektubumu bekleyen var mı? bilmeden...

‘Dönmesem de gam çekme,üzülme! 

Sevda pınarına girene yağmur ne ola ki? ’

                                                                 24/01/2004', 'Üzerinde umut güneşinin yansıdığı Mavi sularının dibine çekiliyorum. Sular koyulaşıyor,mavi laciverde Lacivert siyaha dönüşmede, Koyu karanl...', ARRAY['Türk Edebiyatı','Şiir','Celal Şahin']::text[], 8.5, '{"poet":"Celal Şahin","poet_slug":"celal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/narkoz-oncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-nella-siyar-1xxvu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittiler akşam olmadan.

Ortalık kararmadan

Yalnız kaldım.

Bitmez sazların özlemi

Daha sonra geceler uzar,

Hazırlık sonbahar

Bak gene buradayım

Yalnız,tek başıma', 'Gittiler akşam olmadan. Ortalık kararmadan Yalnız kaldım. Bitmez sazların özlemi Daha sonra geceler uzar, Hazırlık sonbahar Bak gene buraday...', ARRAY['Türk Edebiyatı','Şiir','Nella Şiyar']::text[], 8.5, '{"poet":"Nella Şiyar","poet_slug":"nella-siyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlem-155-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Peşinde', 'sevda-pesinde-kenan-carboga-dqfaz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Herkes özünü arar)

Sevda deryasına dalmayan aşık

Sevdayı küllenmiş ocakta arar

Hak’tan bul emrini almayan aşık

Harabeye dönmüş bucakta arar

Kimisi sır diye bir yalan düşte

Kimisi heykelde, putlarda, taşta

Kimisi kutupta bitmeyen kışta

Kimi cehennemde sıcakta arar

Kimisi dudakta, kimisi elde 

Kimisi belikte, kimisi telde

Kimisi kıvrılan bir ince belde

Kimisi kalçada, bacakta arar

Kimisi şehvetin az ötesinde

Kimisi cilvenin naz ötesinde

Kimisi fasıl’ın saz ötesinde

Kimisi her gece kucakta arar

Kimisi benimle Hakkın yolunda

Kimisi çingenin çıkmaz falında

Kimisi Mevla’nın Leyla kulunda

Kimisi çiçekte, böcekte arar

                           07.04.2003 (BOLU)', '(Herkes özünü arar) Sevda deryasına dalmayan aşık Sevdayı küllenmiş ocakta arar Hak’tan bul emrini almayan aşık Harabeye dönmüş bucakta arar...', ARRAY['Türk Edebiyatı','Şiir','Kenan Çarboğa']::text[], 8.5, '{"poet":"Kenan Çarboğa","poet_slug":"kenan-carboga","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevda-pesinde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutamamalıyım', 'seni-unutamamaliyim-osman-i-slam-h4bni', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni unutmak isterken 

seninle geçen zamanı 

beni yaşatan zamanı 

zamanı yaşatan saati 

unuttum hep 

bir sen doldurdun 

zaman saydığım herşeyi 

alıp veremediğim nefesimi

buz gibi yatağımı

boş gibi düşlerimi

sonsuz ve dipsiz kuyularımı

seni unutmak isterken

kendimi de 

kimliğimi de

yaşadığımı da unutmak istediğimi

anladım

çok zaman geçmeden

seni unutamamalıyım

seni yaşatmalıyım değil

seni yaşamalıyım

girdiğim kafede

mini şark motifli dürümcüde

Belgradın yeşilinde

Sarıyerin denizinde

Üsküdarın parkında

Başiktaşın iskelesinde

Donmuş ellerini ısıttığım elimde

üşüdüğünde yaslandığın omzumda

sokulduğunda uyuduğun koynumda

seni yaşatmalıyım değil

seni yaşamalıyım

doyasıya... 

sonsuz gibi, dipsiz gibi...', 'seni unutmak isterken  seninle geçen zamanı  beni yaşatan zamanı  zamanı yaşatan saati  unuttum hep  bir sen doldurdun  zaman saydığım herşe...', ARRAY['Türk Edebiyatı','Şiir','Osman İslam']::text[], 8.5, '{"poet":"Osman İslam","poet_slug":"osman-i-slam","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seni-unutamamaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadersizim Ben', 'kadersizim-ben-hifzi-ozbekmez-0lfd5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlüm isyandadır kadere kırgın

Hayatı boyunca feleğe dargın

Sevda denizinde yemişim vurgun

Sevda yorgunuyum kadersizim ben

Dinmedi gözümde bir türlü yaşlar

Başımdan eksilmez bin türlü işler

Dertlerim bitmeden yenisi başlar

Ömür yorgunuyum kadersizim ben

Bin dilek diledim olmadı biri

Aşkın demek bitti çabuk sihiri

Mezara soktular hem diri diri

Gönül yorgunuyum kadersizim ben

Sevdası gönlümde daima sızı

Hayatta unuttum baharı yazı

Yürekte yanıyor hasretin közü

Hasret  yorgunuyum kadersizim ben', 'Gönlüm isyandadır kadere kırgın Hayatı boyunca feleğe dargın Sevda denizinde yemişim vurgun Sevda yorgunuyum kadersizim ben Dinmedi gözümde ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kadersizim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetten Anneme 2', 'gurbetten-anneme-2-taha-aygun-kanca-6s7l8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gittin gideli çile çekerim,

Acımı kimseler anlamaz anne

Yaşayan bir ölü ben oldum derim,

Şevkatine muhtaç olmuşum anne.



Daha önce seni pek bilemedim,

Dağlara bakarak ağlarken anne.

Çok kez anlamakta zorluk çekerdim,

Ana acısını bilirdin anne.



Babadan öksüz dünyaya geldin,

İki abi ve sen öyleydi anne.

Sadece bir anne tanıyıverdin,

Yetim gelip yetim bıraktın anne.



Zahirde ölen sen, batında benim,

Anlayanlar bilmem var mıdır anne.

Gözyaşım kurumaz ağlar gezerim,

Hatıralarınla yaşarım anne.



Fani alem bana gurbet olmuştur,

Senin gidişinle anladım anne.

Gurbete alışmak çok zor olmuştur,

Takdiri ilahi bilirim anne.



Tesellim oluyor rüyada görmek,

İsterim her gece göreyim anne

Sarılıp öperek özlem gidermek

“ Ben ölmedim Aygün “ deyiver anne', 'Sen gittin gideli çile çekerim, Acımı kimseler anlamaz anne Yaşayan bir ölü ben oldum derim, Şevkatine muhtaç olmuşum anne. Daha önce seni p...', ARRAY['Türk Edebiyatı','Şiir','Taha Aygün Kanca']::text[], 8.5, '{"poet":"Taha Aygün Kanca","poet_slug":"taha-aygun-kanca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gurbetten-anneme-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamane Çocuğu ve Orhan Veli (Eğlencelik)', 'zamane-cocugu-ve-orhan-veli-eglencelik-umit-kilislioglu-ozger-6xptf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstanbul''un orta yeri Alabama

Yine online olduğumu duyurmayın babama

Faturalar kabarıkmış bana ne? 

Sanalım! Edâlım! Boynuna vebâlim.

Chat Bağımlısı

(27.Nisan.2004)', 'İstanbul''un orta yeri Alabama Yine online olduğumu duyurmayın babama Faturalar kabarıkmış bana ne?  Sanalım! Edâlım! Boynuna vebâlim. Chat B...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zamane-cocugu-ve-orhan-veli-eglencelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünün', 'gorunun-oguzkan-bolukbasi-zaba1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'fena halde 

dökülüyorum ellerine

su gibi

kaynağı belirsiz

temiz

kendimi yapıyorum yeniden

kırık

dökük

terkedilmiş bir evden çıkıyorum

gökyüzü mavi

yeryüzü deniz

ben doğuyorken

siz neredesiniz

bir aşkın sabahındayız

hepimiz

biz

siz onlar

ve yüzlerce hasretin resmi

duvarımda asılı

o

gülen gözlerle beni bekleyen

hanginiz

görününüz', 'fena halde  dökülüyorum ellerine su gibi kaynağı belirsiz temiz kendimi yapıyorum yeniden kırık dökük terkedilmiş bir evden çıkıyorum gökyüz...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gorunun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir rum ezgisi geliyorken radyodan, bir martı uçar adadan kanatlarında mavi umut', 'bir-rum-ezgisi-geliyorken-radyodan-bir-marti-ucar-adadan-kanatlarinda-mavi-umut-mustafa-sen-s4wk6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokluğunu  ada öğretti

Yokluğunda ada öğretti hiç bir denizin

gözlerin kadar 

derin olmadığını

Rakıya kanmak istiyor 

dudaklarımda dudakların 

hiç bir limanda demir almaksızın 

tam yol ileri

Sınırları aşıp

karşı kıyıda 

barbanın meyhanesinde

gülmek istiyorum 

gözlerinde

sıcacık

ellerim sensiz 

neredesin...

kutsal şehirlerin bakire gözlü dilberi

özlemimsin yıldızlara   karşı 

ve ben ada askeri.

(sadece yeşil)', 'Yokluğunu  ada öğretti Yokluğunda ada öğretti hiç bir denizin gözlerin kadar  derin olmadığını Rakıya kanmak istiyor  dudaklarımda dudakları...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen']::text[], 8.5, '{"poet":"Mustafa Şen","poet_slug":"mustafa-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-rum-ezgisi-geliyorken-radyodan-bir-marti-ucar-adadan-kanatlarinda-mavi-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır(p) ıntılarım 1', 'kir-p-intilarim-1-reyhan-sur-2qyqo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'püskürük

tüm kozalaklarını toplayıp

doldurdum kerestesinin sandığına

püskürük ormanlar oluştu

kangren

ellerimi vermiştim.. kesip attı kollarını (kolumu alamadım)

istemem yüreğimi geri

yüreği kangren...

rehber

sana bir yol çizemem

yakışan yolda yürür herkes

yürüdüğün yol tehlikeli.. dikenli...

med

deniz öyle yükseldi ki

tut elimi

ay...

günce

her çiçeğe bir sevgi

her sevgiye bin çiçek

yürekte milyonlarca yıldız tomurcuğu..

akıntı

volkanların cürümünden

vurulan mermiler kan revan

akıyor nehirlerden tıklım tıklım yokluğun...

şüphe

mayası bozuk ayna

zayıf! gösteriyor seni

ışık yansıtmıyorsun bana...

gelgeç

dondu ayazmalarım.. ekvatorum değişti

kent sürgün açık göçe

sağır boşlukta sallanıyorum...

istem

söküp atsam sudan geçen ışıkların

gün doğumu tellerini

sofrasına otursam güneşin...', 'püskürük tüm kozalaklarını toplayıp doldurdum kerestesinin sandığına püskürük ormanlar oluştu kangren ellerimi vermiştim.. kesip attı kollar...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kir-p-intilarim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır(p) ıntılarım 2', 'kir-p-intilarim-2-reyhan-sur-j3e21', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dingin

durup durup kamaşıyor

yorgun anılarımız

yaralarımız kanıyor ısrarla

*

seçme

bir şairin şiirleri gibiyiz

dağınık.. her yerde

.. ve öylesine içiçeyiz gönüllerde

*

görüş

o mahzun bakışlar

neler anlatır derinlerinde

anlayabilir misiniz...

*

tor

tüm sevinçlerim

cam kürede tutuklu.. tor bir çocuk

yuvarlanır.. sürgit misketlerime

*

biçim

burkulup koparılan dilin yerine

bilge bir yılan otursa

neler söylerdi suskun ağızda

*

köpük

siyanürlü çakıl taşlarıyla

parçaladım zamanı.. kıymık kıymık

karamsar köpürüyorsun kahvemde

*

yara

ıslak bir ekmek gözlerim

ufalanıp düşüyor ağzımın kuyusuna

iki büklüm.. hı(n) çkırarak kesiyor sözü tuz

yalıyor dil yaralarımı...

*

şarap

yıkık duvarlardan taşan

taş tas ezilmiş üzüm

püskürüyor hıçkırıkla

*

ezinç

köse şubatta kestiydi sakalını

martta soğuttu külünü temmuz

örsü çekip dövündü güz

*



yitik

düşüp kör bir uçuruma

unutulmuş engin insan

kuş gibi çırpınıyor bende...

*

kaçak

nefesliyorum dağların çam kokularını

sen, mağaralara gömüyorsun kendini

kaçak.. yaşıyorsun en derin ağrılarını...

*

ayakta kalmak

onca batıp yakan

diken var ki yüreklerde

yeminliyiz yine de.. sonsuza dek çiçek açmaya

*

dava

ağıtların öfkelerin aymazların tortusunu

söküp atsam kanırtarak..

karanlığın yalnızlığın küf kokulu yontusunu...

*

can bulut

ne çok ağladın öyle

hadi sil gözlerini de

sürün gel.. mavi farını', 'dingin durup durup kamaşıyor yorgun anılarımız yaralarımız kanıyor ısrarla * seçme bir şairin şiirleri gibiyiz dağınık.. her yerde .. ve öyl...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/kir-p-intilarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Destanı', 'canakkale-destani-bekir-gedikoglu-jv268', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çanakkale de altı gün görevli kaldım ve şairler toplantısı için İzmir’e giderken güzergah üzerinde ki zafer anıtlarını görünce; bu şiiri kaleme aldım.

Gelibolu adasında / Allahın Aslanları

Yazacaklar burada / Çanakkale destanı

Kalemler insan ise / mürekkebi Türk kanı

Komutana söz verdim/ savaş başladığında

Gece gündüz demeyip/ vuracağım düşmana

Ekmek diye mermiyi/ veriyorlar ağzıma

Cennete gideceğim/ sakın ağlama Ana

Başıma yağan ateş/ yüreğimdekinden az

Yedi düvel gelse de/ beni boğazlayamaz

Top-tüfeğe güvenen/ iman hesabı yapmaz

Çanakkale’ye gelenler/ bir daha ayrılamaz! 

Top tüfek kullanmadan/ saldırdık biz düşmana

Siperleri çevirdik/ biz hallaç pamuğuna

Gafil düşman şaşırdı/ Türk’ün kahramanlığına

Tarihe bakmayanlar/ tokat yer suratına

Gökten yağmurlar gibi/ yağıyordu bombalar

Bu vatanın uğruna/ ölüyordu Aslanlar

Bayrağımın rengine/ boyanıyor topraklar

Ben ölsem de siperde/  bu kan düşmanı boğar

Ana kuzusu diye/ boğazıma daldılar! 

Birkaç günün içinde/ bizi avlayacaklar

Biz Aslan yavrusuyuz/ bunu geç anladılar

Anadolu  Analar/ hep Aslan doğruyorlar

Cengaverlik, cesaret/ kanında var her Türk’ün

Vatan-Bayrak-Özgürlük/ değişmeyecek bir bütün

Çanakkale’ye gelen/ şu ucubelere bakın

Hak hakkın yanındadır/ bu Milleti tanıyın! 

Çanakkale, 27 Nisan 2004', 'Çanakkale de altı gün görevli kaldım ve şairler toplantısı için İzmir’e giderken güzergah üzerinde ki zafer anıtlarını görünce; bu şiiri kal...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/canakkale-destani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar/ımız', 'yar-imiz-reyhan-sur-2pmtj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bana yarsın..

ben yoksam

sen de yoksun benim için

ama kendin için varsın

sen yoksan

ben de yokum senin için

ama kendim için varım

bir yanımız hep yarım can tanem

ve ben sana hep yar/ım...', 'bana yarsın.. ben yoksam sen de yoksun benim için ama kendin için varsın sen yoksan ben de yokum senin için ama kendim için varım bir yanımı...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yar-imiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımıza Veda', 'askimiza-veda-halil-kesken-3tx9b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şehirde son günümdü

Yine o sahile gittim

Gözümde yaş, kalbim buruk

Anılara veda ettim

Sık sık bakıp ufka doğru

Seni aradı gözlerim

Sular yine deli dolu

Dalgalara veda ettim

Geç kaldığın bazı günler

Onlarla sohbet ederdim

Beni yine dinlediler

Martılara veda ettim

Kumdan izleri silerek

Hayata sitemler ettim

Kahrolarak, üzülerek

Aşkımıza veda ettim...', 'Bu şehirde son günümdü Yine o sahile gittim Gözümde yaş, kalbim buruk Anılara veda ettim Sık sık bakıp ufka doğru Seni aradı gözlerim Sular ...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askimiza-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar Yarına Kaldı', 'umutlar-yarina-kaldi-gulten-topay-oi2no', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boş sokaklarında yürüdüm İstanbulun

Bir yandan pranga sesleri gelmekte

Bir yandan

Belli belirsiz sevda türküleri

Umutlara,sevdalara vurdular zincirleri

Toplu sevdaları olacaktı 

Toplu utançları oldu yüzyıllık

Oysa sevda türküleri olacaktı yurdumun

Çığlık yerine sevgi türküleri duyacaktı insanlar

Eller havada kaldı

Kanlar yerde

Yürüyüp geçtiler üzerinden

Umutlar yarına kaldı.', 'Boş sokaklarında yürüdüm İstanbulun Bir yandan pranga sesleri gelmekte Bir yandan Belli belirsiz sevda türküleri Umutlara,sevdalara vurdular...', ARRAY['Türk Edebiyatı','Şiir','Gülten Topay']::text[], 8.5, '{"poet":"Gülten Topay","poet_slug":"gulten-topay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umutlar-yarina-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan yıllar', 'kaybolan-yillar-seda-atasoy-m1lr2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaybolmuş güzellikleri anımsıyorum  yine 

Geçmişe gidiyorum birden.

Hatıralara daldıkça içimdeki dayanılmaz özlem

Buruk bir acıya dönüşüyor 

Gözlerim doluyor inanın canım yanıyor...

Evler geliyor gözlerimin önüne 

Bacaları buram buram sevgi tüten evler

Sıcacık sobaların yanında mışıl mışıl uyuyan o tekirkediler.

Kestane kokuları tütüyor burnuma aniden

Mısır patlatmak istiyorum...

Gözlerim sehpalardaki sararmış kolalı dantelleri arıyor birden

Bilseniz o günleri nasıl da özlüyorum.

Gazlambalarıyla aydınlanan baba ocaklarını düşlüyorum

Nasıl da ışıl ışıl oluverirdi kitap yaprakları hatırlıyorum.

Çatılardan şıp şıp damlayan yağmurla dolsa da odalar

Yine de saksı saksı çiçeklerle donanırdı o balkonlar..

Ve mazide kalan o yıllar,ah o güzelim yıllar....

Sütçümüz Dursun efendi geliyor aklıma sonra

Elinde güğümü,

Bakraç bakraç süt dağıtıyor bebelere...

Mutluluk vardı diyorum

Emek vardı  insanlık vardı o günlerde,biliyorum.

İsyan etmek geliyor içimden bu kayboluşlara

Bağırmak geliyor içimden tüm insanlara.

Uyanın diyorum ey insanlar uyanın...

Elde avuçta ne varsa gidiyor.

Uyanın diyorum, ey insanlar uyanın...

İnsanlığımız hergeçengün biraz daha bitiyor.

Çoçukluğumuz seriliyor birden gözlerimin önüne

Eskiden çoçuklar bile birbaşkaydı diyorum.

Camlar kırılırdı hergün

Minik eşkiyaların fırlattığı toplarla 

Komşumuz Münire teyze koşardı balkona

Avaz avaz bağırırdı ''kim kırdı bunu yine'' diye birden.

Canhıraç kaçan veletlerin peşinden

Kızgınlığı sevgi dolu bir tebessüme dönüşüverirdi aniden.

Masallar dinlerdi uyumadan önce bebeler

O tertemiz minik beyinlerde

Hep pamukprenses ve yedicüceler...

Dualar ezberletirdi  analar başucumuzda.

Ne güzelmiş diyorum o yıllar,ah o yıllar...

İsyan etmek geliyor içimden bu kayboluşlara

Bağırmak geliyor içimden tüm çoçuklara.

Uyanın diyorum,ey çoçuklar uyanın.

Bu güzellikler artık bitiyor...

Uyanın diyorum,ey çoçuklar uyanın.

Çoçukluğumuz yokolup elimizden gidiyor...

,', 'Kaybolmuş güzellikleri anımsıyorum  yine  Geçmişe gidiyorum birden. Hatıralara daldıkça içimdeki dayanılmaz özlem Buruk bir acıya dönüşüyor ...', ARRAY['Türk Edebiyatı','Şiir','Seda Atasoy']::text[], 8.5, '{"poet":"Seda Atasoy","poet_slug":"seda-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kaybolan-yillar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pavyon Kızı', 'pavyon-kizi-halil-kesken-xc5uh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Barın kapısında az mı dolaştım

Bana kızdığının geldi haberi

Yaklaşmak istedim, hep uzaklaştım

Bir adım ileri, birbuçuk geri

Hiç dayanamazdım gelen taşlara

Mahvederdi pavyon kızı oluşun

İçkinin yanında tüm sarhoşlara

Kahrederdi beni meze oluşun

İstersen bir değil bin formül dene

Bizdeki bu derde bulunmaz çare

Başka erkeklerle çıkıp gitmene

Nasıl dayanırım göz göre göre', 'Barın kapısında az mı dolaştım Bana kızdığının geldi haberi Yaklaşmak istedim, hep uzaklaştım Bir adım ileri, birbuçuk geri Hiç dayanamazdım...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pavyon-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evreka', 'evreka-yaren-gurler-ig1mu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gençtin daha,

Belki de çocuk.

Kumrallığının kokusunu yayıyordun

Cennet elması niyetine.

O an aklıma düştü kokun..

Evreka! Evreka! 

İstemsiz ama mutlu heceledim ilk kez adını.

Gencim ben de, daha çocuk işte. 

Ne bileyim elmayı yiyenin cennetten kovulduğunu.', 'Gençtin daha, Belki de çocuk. Kumrallığının kokusunu yayıyordun Cennet elması niyetine. O an aklıma düştü kokun.. Evreka! Evreka!  İstemsiz ...', ARRAY['Türk Edebiyatı','Şiir','Yaren Gürler']::text[], 8.5, '{"poet":"Yaren Gürler","poet_slug":"yaren-gurler","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/evreka-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak', 'cikmaz-sokak-yaren-gurler-mlrno', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Yanındayken-

Buradan her yer uzak,

Ne sana gidilebilir ne bana.', '-Yanındayken- Buradan her yer uzak, Ne sana gidilebilir ne bana....', ARRAY['Türk Edebiyatı','Şiir','Yaren Gürler']::text[], 8.5, '{"poet":"Yaren Gürler","poet_slug":"yaren-gurler","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/cikmaz-sokak-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tez ölüm', 'tez-olum-cetin-isik-dur4w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu şehirde satılıktır

aşkları tadilata

kapalıdır bu mevsim

nesi varsa adı düş olan

ah tez ölüm

tez den ölüm

hainliklerde mümmesil

kaçmalarda

yitirmede

ölüme benzer tüm dostlar

zindandır artık sokaklar

sormayın,sorgulamayın öyleyse

alkole tanışıklığımızı

ah tez ölüm 

tezden ölüm

intihar silinmeyecek bir yazgıdır artık', 'bu şehirde satılıktır aşkları tadilata kapalıdır bu mevsim nesi varsa adı düş olan ah tez ölüm tez den ölüm hainliklerde mümmesil kaçmalarda...', ARRAY['Türk Edebiyatı','Şiir','Çetin Işık']::text[], 8.5, '{"poet":"Çetin Işık","poet_slug":"cetin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tez-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
