INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekerlekli Sandalye', 'tekerlekli-sandalye-umut-beker-aygoz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sağlam bacaklarında

                                    gördüm

                                                mutluluğu

ve hissettim

                    üzerine 

                               oturduğum

tekerlekli

               sandalyenin

                                   soğukluğunu', 'Sağlam bacaklarında                                     gördüm                                                 mutluluğu ve hissettim       ...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tekerlekli-sandalye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordum', 'sordum-umut-beker-dac9s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamı sordum tokuşa

      Bir ihtimalle çıkmaktır dedi beni

Sevdayı sordum yağmura

       Geri dönmemek üzere

                  karışmaktır dedi sulara

Hasreti sordum yalnızlığa

        Kovasız kuyunnun dibindeki

                   sudur dedi bana

Ölümü sordum sonsuzluğa

         dediki karışmaktır boşluğuma

Aşkı sordum aşığa

          vermedi bi cevap bana

Şimdi soruyorum sana

           aşk nedir usta?', 'Yaşamı sordum tokuşa       Bir ihtimalle çıkmaktır dedi beni Sevdayı sordum yağmura        Geri dönmemek üzere                   karışmaktır...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sordum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döne Döne', 'done-done-gencay-coskun-9fgu9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaçamak 

Bir yaprak

Düşmüştü 

Korkusundan 

Titremişti

Mevsim

Düşen 

Düşmüştü 

Elden ne gelirdi

Diye 

Ömürleri 

Bir çırpıda 

Harcamıştı 

Alıngan 

Duygular

Bir aşağı

Bir yukarı

Bayağı değil 

Pestil kıvamında 

Yorulmuştu

Haberci

Bir uzun mesajı 

Vardı 

Dengesiz 

İnsanlar kümesinin 

Çoğu ya okumadan 

Mesajı sildi 

Yada okuduklarını 

Anlamadı 

Bir harmandı 

Dünya 

Döne döne 

Bitmedi 

Kirlenmeler', 'Kaçamak  Bir yaprak Düşmüştü  Korkusundan  Titremişti Mevsim Düşen  Düşmüştü  Elden ne gelirdi Diye  Ömürleri  Bir çırpıda  Harcamıştı  Alın...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/done-done-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok uzun yıllar', 'cok-uzun-yillar-umut-beker-8y2d7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok uzun yıllar bekledim

                  ne olduğumu

         ve ne istediğimi bilmeden

Çok sonra

           yorgun bir sonbahar sabahı

                   yorgun düştüm zamana

Ve bir daha çıkamadım

        sonu olmayan tek kişilik yolculuklara

         Ve biliyor musun 

                    bekliyorum hala

                             aynı boşlukta

         Belki gelirsin sonsuzluğuma

                   ve bilmeni isterim

                        kimse yok

                                   yolculuğumda

          Ölümün

                   sessizliği

                            dışında...', 'Çok uzun yıllar bekledim                   ne olduğumu          ve ne istediğimi bilmeden Çok sonra            yorgun bir sonbahar sabahı   ...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cok-uzun-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar Kediler ve Ben', 'martilar-kediler-ve-ben-zafer-zengin-etnika-6iafb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz kırptım 

Dükkan kapattım

Harçlık ettim zamanı

Harcadım acımadan

Bir film ki; 

Seyredilmeden yanan

i ş t e  b u ; 

A ş k t ı r 

Anlatılmayan 

S ı ğ m a y a n

Yorulmayan

D a ğ ı l m a y  a n

A c ı k t ı m..gözlerin nerde...

İşte böyle; 

Aklı sıra

D e n i z  o n u n  o l  a c a k

Yemezler! 

M a r t ı l a r

K e d i l e r 

v e  b e n i m d i r 

Bakış çalarız gözlerinizden/Sizin ısraf ettiğiniz

Siz yüzerken

Biz geceyi bekleriz

S ı c a k  u y k u   a l ı r ı z

Memesi süt hatunlardan

G i z l i  s e v e r i z

Krallar bile bilmezken  aşkı

Ş i i r y a z a r d ı k s a b a h a  k a r ş ı

Çöp toplardık

Tapınak kurardık

Kalem eğilirdi elimizde

T a v ı n d a  d ö v e r d i k   h a s r e t i

Yelken takardık aklımıza

Seferlerimiz kimlikli aşklara

Eserdi hırpani rüzgarlar

O n l a r   k i  y ü z ü m ü z de ç a  t l a k l a r

Nasır bildik ayrılığı

Y a l ı n   a y a k   d ü ş t ü k   h a y a t a

G i d e r i z

Gitmesini biliriz

İ s t e d i ğ i m i z  i ç i n  s e v e r i z

Y ı k a n d ı k..Ar ı n d ı k..K i r i m i z   p a s ı m ı z   t e r   b i z i m...

29 Nisan 2004  '' içimin kitabı ''', 'Göz kırptım  Dükkan kapattım Harçlık ettim zamanı Harcadım acımadan Bir film ki;  Seyredilmeden yanan i ş t e  b u ;  A ş k t ı r  Anlatılma...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/martilar-kediler-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Olacaksın', 'pisman-olacaksin-umut-beker-pavod', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra 

     okuduğum bir kitabın

  son sayfalarından çıkan bir resim

                     olarak kalacaksın

Pişman olacaksın.

    Her zaman olduğu gibi

        belki birilerinin kalbini yakacaksın

Ve o kitabın son sayfalarındaki

           yanlız  aşık olacaksın

Ama bir farkın olacak ondan

     o sonunda mutlu,

           sense daima yalnız kalacaksın

Ve yaşamın boyunca bir anı olmanın

                         acısını duyacaksın.', 'Yıllar sonra       okuduğum bir kitabın   son sayfalarından çıkan bir resim                      olarak kalacaksın Pişman olacaksın.     Her...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/pisman-olacaksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefretisin bakışların', 'nefretisin-bakislarin-umut-beker-5onka', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nefretisin bakışların

        Amacısın sevdaların

Hikayesisin kırışıklıkların

        Rüzgarısın sonbaharın

İlk kıvılcımısın yangınların

        Mevsimisin yağmurların

Zamansız gelişisin eylülün

        Soluk alışısın ölümün

Ve sonu bitmeyen 

              bir şiirsin

Çünkü sen

         düşsel bir

                    hikayesin

                               sevgilim...', 'Nefretisin bakışların         Amacısın sevdaların Hikayesisin kırışıklıkların         Rüzgarısın sonbaharın İlk kıvılcımısın yangınların    ...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nefretisin-bakislarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-baykal-kaanalp-ej2we', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen içtiğim ilk sigarasın benim 

ciğerlerime çektiğim ilk duman 

içinde yok olduğum ilk sis bulutu 

sen ilk göz ağrım 

kaybolduğum ilk ara sokaksın 

sen bilmediğim bir denizde 

yolumu gösteren ilk fenersin 

sen varamadığım ilk nokta 

ulaşmak istediğim son duraksın 

sen bana çarpan ilk araç 

ilk ceza kesensin gönlüme 

sen benim ilk aşkım 

son bekçisi sevgimin 

sen ilk sahibimsin 

sen bir tanemsin 

sen benim kalan yarımsın 

sen diktiğim ilk fidansın yüreğime 

sen herşeyimsin ilkler içinde', 'sen içtiğim ilk sigarasın benim  ciğerlerime çektiğim ilk duman  içinde yok olduğum ilk sis bulutu  sen ilk göz ağrım  kaybolduğum ilk ara s...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-381-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkbahar kadar güzeldin', 'i-lkbahar-kadar-guzeldin-umut-beker-6kbj4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlkbahar kadar güzeldin

Sonbahar dökülen yapraklar gibi

                    Savruluverdin

  Ne bir matematik problemiydin

  Ne de bir şiir kitabı

       Sen dört mevsimin tek gerçeğiydin

                      yaşamdaki

                              dengeydin

        Sen hayatımdaki en güzel şeydin

      Bir rüzgarla savruluverdin

         Ve bir ilkbahar günü

                   girdiğin hayatıma

        Sonbaharda veda etmeyi

                                       seçtin

              Hoşçakal 

                           Sevgilim...', 'İlkbahar kadar güzeldin Sonbahar dökülen yapraklar gibi                     Savruluverdin   Ne bir matematik problemiydin   Ne de bir şiir k...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilkbahar-kadar-guzeldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen sevdin de...', 'sen-sevdin-de-baykal-kaanalp-76659', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir ben miyim sana her şeyini kaybettiren

sen sevdin de ben sana boş mu? verdim

bir ben miyim sana yalnızlığı seçtiren

sen sevdin de ben sana boş mu? verdim

kapıldıysan boş hayallere

bunda benim suçum,günahım ne? 

takıldıysan bir vefasızın peşine

bunda benim rolüm ahım ne? 

bir ben miyim sana her şeyini kaybettiren

sen sevdin de ben sana boş mu? verdim

bir ben miyim sana yalnızlığı seçtiren

sen sevdin de ben sana boş mu? verdim

kanıyorsan her söylenen yalana

arıyorsan hoş bir bahane

yanıyorsan ardında kalana

bunda benim rolüm ahım ne? 

bir ben miyim sana her şeyini kaybettiren

sen sevdin de ben sana boş mu? verdim

bir ben miyim sana yalnızlığı seçtiren

sen sevdin de ben sana boş mu? verdim', 'bir ben miyim sana her şeyini kaybettiren sen sevdin de ben sana boş mu? verdim bir ben miyim sana yalnızlığı seçtiren sen sevdin de ben san...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-sevdin-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu şiir', 'bu-siir-umut-beker-6lvpy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şiir 

             senin için

  Ve sen

           yalnızca bir

                            düşüncesin

      Ama olur ya belki

                               bir gün

                      eyleme geçersin...', 'Bu şiir               senin için   Ve sen            yalnızca bir                             düşüncesin       Ama olur ya belki            ...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-siir-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilin Kemiği', 'dilin-kemigi-baykal-kaanalp-oawds', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne çektiysem dilimden

Çektim dedi adam

Kadının kulağına

Eğilerek,usulca

Ağlamaklıydı üstelik

“çok kötü bir

kabahat işlediğini

her haliyle belli ediyordu”

kadın bir peçete uzattı

adam peçeteyi aldı

gözlerini hafiften kuruladı

sonra yine

ne çektiysem dilimden

çektim dedi adam

yanlış attım adımlarımı

kulağımı tersten tuttum

önemli değildi ama

nasıl olsa unutuldum

nasıl olsa unutuldum

ben istemedim ama

ne çektiysem bu

kopasıca dilimden

çektim dedi adam

her şeye maydanoz olan

her oltaya tutulan

bir sazan mı? ne', 'Ne çektiysem dilimden Çektim dedi adam Kadının kulağına Eğilerek,usulca Ağlamaklıydı üstelik “çok kötü bir kabahat işlediğini her haliyle be...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dilin-kemigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne düşünürse', 'ne-dusunurse-umut-beker-8j5ki', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne düşünürse

             14 katlı

                   bir binanın

              tepesindeki adam

        İşte budur yaşam.', 'Ne düşünürse              14 katlı                    bir binanın               tepesindeki adam         İşte budur yaşam....', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ne-dusunurse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gecenin Sesi', 'gecenin-sesi-guclu-sonmez-rt2hy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sus, dinle

Bak gece sesleniyor yine

Dur, kapat gözlerini

Dal derinlere, rahatla

Kimse hesap soramaz bana burda

Bozamaz keyfimi

Dokunamaz bana

Kimse engel olmaz rüyalarıma

Bulamaz hazinemi

Çıkamaz yoluma

(İstanbul, Temmuz 1999)', 'Sus, dinle Bak gece sesleniyor yine Dur, kapat gözlerini Dal derinlere, rahatla Kimse hesap soramaz bana burda Bozamaz keyfimi Dokunamaz ban...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gecenin-sesi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte budur yaşam', 'i-ste-budur-yasam-umut-beker-vsnss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne düşünürse

             14 katlı

                   bir binanın

              tepesindeki adam

        İşte budur yaşam.', 'Ne düşünürse              14 katlı                    bir binanın               tepesindeki adam         İşte budur yaşam....', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/iste-budur-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Don Kişot', 'don-kisot-gokhan-pamukcu-hm1jg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Don Kişot olup savaşırken 

senin için yel değirmenleriyle,

sen değil miydin ki rüzgar olup

yardım eden bütün yel değirmenlerine?', 'Don Kişot olup savaşırken  senin için yel değirmenleriyle, sen değil miydin ki rüzgar olup yardım eden bütün yel değirmenlerine?...', ARRAY['Türk Edebiyatı','Şiir','Gokhan Pamukcu']::text[], 8.5, '{"poet":"Gokhan Pamukcu","poet_slug":"gokhan-pamukcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/don-kisot-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni baktığımda göremedim', 'seni-baktigimda-goremedim-umut-beker-w7whc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni

     baktığımda göremediğim

geri getiremediğim

           koluma benzetiyorum artık

Acısını duyup

        özlemini çektiğim

ve yeniden

           benim olmayacağını bildiğim

    Bedenimi yarım bırakan

                  Koluma...', 'Seni      baktığımda göremediğim geri getiremediğim            koluma benzetiyorum artık Acısını duyup         özlemini çektiğim ve yeniden ...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-baktigimda-goremedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balkon', 'balkon-umut-beker-n7bf1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aynı bakışla

Aynı duruşla

Ve hep mavi bir hırkayla

Aynı balkonda

Geçermi bir ömür

Bir yaşam

Neden sessizdi haykırışları

İsyankardı bakışların

Mavi hırkasıyla tek başına

Bir ömrü eskitti

Çok mu zor günlerdi

Geçirdikleri

Yoksa hikayesinin sonumuydu

Düşündükleri

Hiçbir zaman bulamadım bu soruların cevabını 

Ve bir gün batımı farkettim

İhtiyarın artık o balkonda olmadığını

Ve ömrümün ortalarında 

Bir balkonda olduğumu', 'Aynı bakışla Aynı duruşla Ve hep mavi bir hırkayla Aynı balkonda Geçermi bir ömür Bir yaşam Neden sessizdi haykırışları İsyankardı bakışları...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/balkon-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Gemi', 'yalniz-gemi-cem-ozdemir-32cu6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnız bir gemi..! 

Dolaşır şiir denizlerinde..

o liman senin..

bu liman benim..! 

Taşır sözcükleri.. tümceleri.. mısraları..! 

Birbiri ardına ekler durur.

Her liman bir gönül..

bitimsiz duygularsa tonlarca yük..! 

Acı.. hasret.. sevgi.. özlem...

yığılmış istiflerde birbiri üstüne..! 

Her liman bir gönül ki:

alev-alev yangınların, bitmek bilmez..

kızılca kıyameti öfkesinde..! 

Ve..

Her liman bir sığınak sanki..! 

Nasıl oluyorsa..

fırtına sonrası sakinliğin

o eşsiz dinginliğinde..!', 'Yalnız bir gemi..!  Dolaşır şiir denizlerinde.. o liman senin.. bu liman benim..!  Taşır sözcükleri.. tümceleri.. mısraları..!  Birbiri ardı...', ARRAY['Türk Edebiyatı','Şiir','Cem Özdemir']::text[], 8.5, '{"poet":"Cem Özdemir","poet_slug":"cem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalniz-gemi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk seni sevmekti', 'ask-seni-sevmekti-umut-beker-przn2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk seni sevmekti

Ela hareli gözlerinde

gezinmekti

Sevmek

sana aşık olmaktı

Gözlerinin

haresine dalmaktı...', 'Aşk seni sevmekti Ela hareli gözlerinde gezinmekti Sevmek sana aşık olmaktı Gözlerinin haresine dalmaktı......', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-seni-sevmekti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-umut-beker-727wi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kıçı delik 

   Dünya! 

 Hiç bir 

         borcum

 yok

               sana!', 'Kıçı delik     Dünya!   Hiç bir           borcum  yok                sana!...', ARRAY['Türk Edebiyatı','Şiir','Umut Beker']::text[], 8.5, '{"poet":"Umut Beker","poet_slug":"umut-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dunya-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sevdiğimi İnkar Ederim', 'sevdigimi-i-nkar-ederim-guclu-sonmez-7v3qr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerindi kalbimi çalan

Sözlerin beni bağlayan

Bir gülüşün bile aşk kokar

Bir yudum sevdan sarhoş yapar

Ellerindi bana dokunan

Dudakların çağıran

Gözlerin derinlere dalar

Gönlüm her an onlardan kaçar

Gün doğar, umut doğar

Sen dostumsun nasıl söylerim

Akşam olur efkar basar

Sevdiğimi inkar ederim

(Pittsburgh, 1995)', 'Gözlerindi kalbimi çalan Sözlerin beni bağlayan Bir gülüşün bile aşk kokar Bir yudum sevdan sarhoş yapar Ellerindi bana dokunan Dudakların ç...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdigimi-inkar-ederim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özür Dilerim', 'ozur-dilerim-uzman-madalyon-7kdt6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adını kalbime aşk diye yazmışım

Zamanla unutur birgün silerim

Güzel bir rüyayı gerçek sanmıştım

Seni sevdiğim için özür dilerim

Aşkıma karşılık beklemek suçmuş

Dünyada vefasız yar çokmuş

Senin beni sevmeye niyetin yokmuş

Seni sevdiğim için özür dilerim...', 'Adını kalbime aşk diye yazmışım Zamanla unutur birgün silerim Güzel bir rüyayı gerçek sanmıştım Seni sevdiğim için özür dilerim Aşkıma karşı...', ARRAY['Türk Edebiyatı','Şiir','Uzman Madalyon']::text[], 8.5, '{"poet":"Uzman Madalyon","poet_slug":"uzman-madalyon","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozur-dilerim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kolay Değil', 'kolay-degil-guclu-sonmez-lttck', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl bilebilirdim ki

Aşkımızın biteceğini

Yıllardır süren bu sevgimizin

Göz açıp kapayana kadar 

Eriyip gideceğini

Kırık bir kalp ile dolaşmak inan ki kolay değil

Yüreğinin yandığını hissederken

Yeniden aşık olmak

Hiç olmazsa unutsam diyerek geleceğe bakmak

İnan ki kolay değil sensiz olmak

Şimdi mutsuz olmam gerek ama umutluyum

Çöldeki bir çiçeğin suyu olan hasretiyle

Minik bir kuşun annesini beklemesinin heyecanıyla

Bütün yeni aşklara kalbimi açıyorum

Çünkü hala yaşıyorum...

(Alanya, Haziran 1991)', 'Nasıl bilebilirdim ki Aşkımızın biteceğini Yıllardır süren bu sevgimizin Göz açıp kapayana kadar  Eriyip gideceğini Kırık bir kalp ile dolaş...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kolay-degil-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Güzeldir', 'yasam-guzeldir-cem-ozdemir-zx40n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'An gelir..! 

Küçük bir çocuğun gülücüklerinde..

sevinç çığlıklarında güzeldir yaşam..! 

Ve.. ellerini mutlulukla çırparak..

alkışlar tutuşunda..! 

An gelir..! 

Özgür bir kuşun anî ürperişlerinde..

kanat çırpışlarında güzeldir yaşam..! 

Ve.. bin bir umutla, heyecanla yükselişinde..

sonsuz göklere..! 

An gelir..! 

Taze bir mevsim çiçeğinin renklerinde..

kokusunda güzeldir yaşam..! 

Ve.. kucak açışında cömertçe..

arılara.. kelebeklere..! 

An gelir..! 

Bir yağmur damlasının duruluğunda..

serinliğinde güzeldir yaşam..! 

Ve.. karşılık beklemeden milyonlarcasının bir arada..

yeniden can verişinde doğaya..! 

Ve.. an gelir..! 

Uğrunda can verilesi o sevgilinin..

dudaklarında.. buselerinde güzeldir yaşam..! 

Hissedişte o zevklerin en erişilmezini..

ölçüsüz ve sınırsızcasına..!', 'An gelir..!  Küçük bir çocuğun gülücüklerinde.. sevinç çığlıklarında güzeldir yaşam..!  Ve.. ellerini mutlulukla çırparak.. alkışlar tutuşun...', ARRAY['Türk Edebiyatı','Şiir','Cem Özdemir']::text[], 8.5, '{"poet":"Cem Özdemir","poet_slug":"cem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yasam-guzeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'New Dimension', 'new-dimension-guclu-sonmez-yzzfv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I want to rule the world 

make the wickedness cease

from the temple of faith 

erase every disease

thunders will spread 

the surface will tremble

aching hearts will be awake 

they will assemble

new colors will be formed by the forgotten dreamer

the puzzles will be solved by the runaway thinker

will you be by my side if emergency occurs

don’t fear the lightning, it will help our cause

I want to change the world 

make the hazy myth real

be herald of the order 

from the triumphal hill 

oceans will struggle 

deserts will burn badness

patched souls will recover 

in the oasis

new colors will be formed by the forgotten dreamer

the puzzles will be solved by the runaway thinker

will you be reticent if espionage arises

pursue the signs and we shall be victors

(İstanbul, Aralık 1999)', 'I want to rule the world  make the wickedness cease from the temple of faith  erase every disease thunders will spread  the surface will tre...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/new-dimension-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağı', 'gokkusagi-cem-ozdemir-2lhrv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağan her yağmurun ardından..

Yedi umutla açar gökkuşağı..! 

En güzelini Kırmızı''ların..

güllerden alır..! 

Aşk çiçeklerinin en soylusundan..! 

Pembe''nin en zevklisini seçer..

aşka susamış hoppa bir genç kızın..

ince.. narin dudağından..! 

Mavi''lerin en can alıcısını..

derinlerinden tutup çıkarır..

dipsiz.. bitimsiz okyanusların..! 

En bir Yeşil''ini, var olan tüm yeşillerin..

yapraklarından alır çamların, köknarların..

sonsuz zirvelerindeki yüce dağların..! 

Hüzün rengi Sarı''yı..

yüreğinden koparır hazan mevsiminin..

adeta canını alırcasına..! 

Portakal bahçelerinden toplar Turuncu''nun..

en olgununu..

en güzel kokulusunu..! 

Ve.. en asilini Turkuaz''ın..

''Yeşil Türbe'' çinilerinde bulur..

nice tarihlere kucak açmış ''Yeşil Bursa''nın..! 

Yağan her yağmurun ardından..

Yedi umutla açar gökkuşağı..! 

Yedi güzel umut..! Yedi güzel renk..!', 'Yağan her yağmurun ardından.. Yedi umutla açar gökkuşağı..!  En güzelini Kırmızı''ların.. güllerden alır..!  Aşk çiçeklerinin en soylusundan....', ARRAY['Türk Edebiyatı','Şiir','Cem Özdemir']::text[], 8.5, '{"poet":"Cem Özdemir","poet_slug":"cem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gokkusagi-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Güzeli', 'esmer-guzeli-cem-ozdemir-o27q7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Size, bir merhaba bile diyemedim ya..

işte ona yanıyorum, esmer güzeli..! 

Oysa, bunu o kadar çok isterdim ki..! 

Hatırlar mısınız bilmem? ! 

Mart''ın 28''iydi.. günlerden Çarşamba..! 

Tam öğle üzeriydi vakit..! 

Semt Nalbantoğlu.. mekan Mini Cafe..! 

Oturduğunuz masanın tam karşısıydı yerim.

Sözüm ona, eski bir dostla sohbet için gelmiştim güya..! 

Ama bir gördüm ki sizi..

bir kapıldım ki, güzelliğinize..! 

Daha ilk bakıştan.. ilk saniyeden..

esir aldınız benliğimi benden..! 

Bense, size bir merhaba bile diyemedim ya..

işte ona yanıyorum, esmer güzeli..! 

Gözleriniz sevgi doluydu...

Bakışlarınızsa sımsıcak..! 

Ne kadar da içten gülümsüyordunuz..

yan masada, balonuyla oynayan küçük kıza..! 

İnanın, neler vermezdim..

onun yerinde olmak

ve arada yanınızdan geçerken,

sevgiyle yanağına dokunduğunuzda..

teninizi hissetmek için..! 

Oysa.. ben size bir merhaba bile diyemedim ya..

işte ona yanıyorum, esmer güzeli..! 

Arada.. göz göze geldiysek de..

sadece bir kaç kez..

ve bir kaç saniyeliğine..! 

Nereden bileceksiniz..

ve nasıl anlayacaksınız ki,

sizi ilk görüşte yüreğimden vurulduğuma.? ! 

Ama ben çok iyi biliyorum ki..

size vuruldum, Esmer Güzeli..! 

Oysa, bir merhaba bile diyemedim ya..

işte ona yanıyorum..!', 'Size, bir merhaba bile diyemedim ya.. işte ona yanıyorum, esmer güzeli..!  Oysa, bunu o kadar çok isterdim ki..!  Hatırlar mısınız bilmem? !...', ARRAY['Türk Edebiyatı','Şiir','Cem Özdemir']::text[], 8.5, '{"poet":"Cem Özdemir","poet_slug":"cem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/esmer-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl', 'akil-hasan-bayindir-yln51', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akıl uzaklara gitti yok

Bende sabır bitti yok

Hanemde baykuş öttü yok

Bu kalp mi? bir etti yok.', 'Akıl uzaklara gitti yok Bende sabır bitti yok Hanemde baykuş öttü yok Bu kalp mi? bir etti yok....', ARRAY['Türk Edebiyatı','Şiir','Hasan Bayındır']::text[], 8.5, '{"poet":"Hasan Bayındır","poet_slug":"hasan-bayindir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/akil-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-hasan-bayindir-vklr5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O gözlerindeki masumluk yok mu,

Beni benden alan o,

O zerafet, o endam

Beni benden çalan o.

Kırık bir kalp,

Bana senden kalan o.', 'O gözlerindeki masumluk yok mu, Beni benden alan o, O zerafet, o endam Beni benden çalan o. Kırık bir kalp, Bana senden kalan o....', ARRAY['Türk Edebiyatı','Şiir','Hasan Bayındır']::text[], 8.5, '{"poet":"Hasan Bayındır","poet_slug":"hasan-bayindir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozlerin-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allahım', 'allahim-hasan-bayindir-o1p86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ondan bende kalan

Sevgi koyma Alahım.

Unuttur o zalimi,

Beni yorma Allahım.

Ona yaptıklarımdan,

Soru sorma Allahım.', 'Ondan bende kalan Sevgi koyma Alahım. Unuttur o zalimi, Beni yorma Allahım. Ona yaptıklarımdan, Soru sorma Allahım....', ARRAY['Türk Edebiyatı','Şiir','Hasan Bayındır']::text[], 8.5, '{"poet":"Hasan Bayındır","poet_slug":"hasan-bayindir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/allahim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harç Bitti', 'harc-bitti-zafer-genc-hhv5c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu yokuş son olsun,

Düzlükler uzansın artık önümde...

Başımı kaldırabileyim, bakınca ufku göreyim.

Bitsin bu engelli koşu, bu yarış sona ersin.

Çalın artık son zili, verin karnemi gideyim.

Varsın tümü zayıf olsun ama, artık sınav olmasın...

Dünyayı durdurmayın niyetim yok inmeye,

Ama müsait yerde indirin,

Durmam bu çılgınlar otobüsünde...

Özgürlüğe çeyrek var; bu açtığım son kapı,

Işıl ışıl rengarenk, bu karanlık son olsun.', 'Bu yokuş son olsun, Düzlükler uzansın artık önümde... Başımı kaldırabileyim, bakınca ufku göreyim. Bitsin bu engelli koşu, bu yarış sona ers...', ARRAY['Türk Edebiyatı','Şiir','Zafer Genç']::text[], 8.5, '{"poet":"Zafer Genç","poet_slug":"zafer-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/harc-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen 2', 'sen-2-hasan-bayindir-0sizv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bir katilsin,

Sevgiyi öldüren.

Sen bir faasitsin,

Kalbi kalbe kırdıran.

Sen bir günahsın,

Durmadan işlediğim,

Sen bir ahsın,

Günüme başladığım.

Sen bir kaçaksın, 

Hep benden kaçan

Sen bir kucaksın,

Benden başkasına açan.

Sen bir hayalsin 

Günlerce kurduğum,

Sen bir yelsin 

Aylarca savurduğum.

Sen bir sonsuzluksun,

Asla bulamayacağım.

Sen bir susuzluksun,

Kalbimi sulamayacağım.', 'Sen bir katilsin, Sevgiyi öldüren. Sen bir faasitsin, Kalbi kalbe kırdıran. Sen bir günahsın, Durmadan işlediğim, Sen bir ahsın, Günüme başl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Bayındır']::text[], 8.5, '{"poet":"Hasan Bayındır","poet_slug":"hasan-bayindir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-2-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişkili Aşk', 'celiskili-ask-ayse-yakut-3uijq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimde sevgi coşup taşıyor

Ama kararsızlıklar,çelişkilerde yaşıyor

Neden,nasıl,niçinler hepsi birarada

Aslında bu soruları çözmek 

Mantığın görevi

Ama sevgi mantığı yok ediyor

Çünkü en büyük güç...sevgi', 'Yüreğimde sevgi coşup taşıyor Ama kararsızlıklar,çelişkilerde yaşıyor Neden,nasıl,niçinler hepsi birarada Aslında bu soruları çözmek  Mantığ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yakut']::text[], 8.5, '{"poet":"Ayşe Yakut","poet_slug":"ayse-yakut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/celiskili-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Emek İster', 'sevgi-emek-i-ster-ayse-yakut-ile8l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Coşkun çağlayanlar gibidir sevgi

Akar gider gönüllere

Ama kurak yüreklerde 

beslenip yeşeremezse

Kurur biter,çöle döner

Yeşertmesini bilen yüreklerde

Coşar,taşar,rengarenk çiçeklenir

Yediveren gülleri gibi

Açar sevgi', 'Coşkun çağlayanlar gibidir sevgi Akar gider gönüllere Ama kurak yüreklerde  beslenip yeşeremezse Kurur biter,çöle döner Yeşertmesini bilen y...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yakut']::text[], 8.5, '{"poet":"Ayşe Yakut","poet_slug":"ayse-yakut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgi-emek-ister-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-ayse-yakut-gr4bk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden sürmez sevgiler,bir ömür boyu

Tutkulu,coşkulu ve heyecan dolu

Neden biter mutluluklar birden

Tam yakaladım derken

Oysa yaşamın kaynağı değil mi bunlar

Sevgi,aşk,mutluluk

Yürekten,göülden,içten verilse

Tadına doyulmaz o zaman hayatın', 'Neden sürmez sevgiler,bir ömür boyu Tutkulu,coşkulu ve heyecan dolu Neden biter mutluluklar birden Tam yakaladım derken Oysa yaşamın kaynağı...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yakut']::text[], 8.5, '{"poet":"Ayşe Yakut","poet_slug":"ayse-yakut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neden-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-ayse-yakut-kq9w4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat bazen kırçiçekleri kadar sade

Bazen coşkun akan çağlayanlar gibisin.

Durgun bir deniz gibi sakin bazen

Bazen esen sert rüzgarlar kadar acımasızsın

Ama yinede hayat...VAZGEÇİLEMEZSİN...', 'Hayat bazen kırçiçekleri kadar sade Bazen coşkun akan çağlayanlar gibisin. Durgun bir deniz gibi sakin bazen Bazen esen sert rüzgarlar kadar...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yakut']::text[], 8.5, '{"poet":"Ayşe Yakut","poet_slug":"ayse-yakut","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayat-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-nesat-turan-iamx0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uçmak istiyorum 

bir öğlen vakti gökyüzün de 

güneşe doğru 

onca gün 

sabırla beklemişim 

yemişim doya doya 

bir gün uçmak istiyorum 

uçmak istiyorum 

yemyeşil çayır boyu 

çiçek ten çiçeğe 

özler alıp, delicesine 

bir gün uçmak istiyorum 

uçmak istiyorum 

onca gün pupa olmuş yatmışım 

deli mavi hayaller kurmuşum 

bir gün de olsa uçmak istiyorum 

uçmak istiyorum 

o gün dağlardan ovalara 

seslenerek sevgimi 

haykırmak istiyorum 

bir gün de olsa uçmak 

hayali bile çok güzel 

aşka banarak bir gün 

uçmak istiyorum 

aman tanrım bir gün mü 

ne olur tanrım 

bir gün olsa uçmak istiyorum', 'uçmak istiyorum  bir öğlen vakti gökyüzün de  güneşe doğru  onca gün  sabırla beklemişim  yemişim doya doya  bir gün uçmak istiyorum  uçmak ...', ARRAY['Türk Edebiyatı','Şiir','Neşat Turan']::text[], 8.5, '{"poet":"Neşat Turan","poet_slug":"nesat-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kelebek-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-ayse-yakut-4b1r1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dondurucu soğukların onu üşüteceğini bilerek

Ayaz gecelerin acımasızlığına direnerek

Kar suyundan alır cansuyunu

Umutla özlemle

Başkaldırır sevgiyle kardelen

Tıpkı yüreğim gibi', 'Dondurucu soğukların onu üşüteceğini bilerek Ayaz gecelerin acımasızlığına direnerek Kar suyundan alır cansuyunu Umutla özlemle Başkaldırır ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yakut']::text[], 8.5, '{"poet":"Ayşe Yakut","poet_slug":"ayse-yakut","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kardelen-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Anladım...', 'yeni-anladim-i-brahim-ethem-bingul-q2vdl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aman ne o endam! Güzellik enfes 

Gözler üzüm kara, solukluk nefes 

Güzel ötesiydi, değildi heves 

Ne kadar kalpsizsin yeni anladım 

Senin gibisini sevebilirdim 

Uğruna aşktan da ölebilirdim 

Yıkıldım nereden bilebilirdim 

Ne kadar ruhsuzsun yeni anladım 

Aşkı anlattım da aşkı görmedin 

Ruhsuzsun dedim de ruhu bilmedin 

Aşk kalpsizde olmaz sen ne zannettin 

Yontulmuş taşmışsın yeni anladım...', 'Aman ne o endam! Güzellik enfes  Gözler üzüm kara, solukluk nefes  Güzel ötesiydi, değildi heves  Ne kadar kalpsizsin yeni anladım  Senin gi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeni-anladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusatma', 'kusatma-hatice-gunes-1wany', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Iki nefes arasinda duraklamadan depresecek  dilin,

dizecek isyankar sozcukleri.

Donen dunya degil,aci dertli basindir

kapansada melanet kapilar bir bir umudun uzerine

yakaracaksin bin umut diye...

Besgen vakitlerde yosun tutacak o tas kalbin

sinirsiz doyumsuz sevisler esir alsada ruhunu

yok olmaktan kurtulamayacaksin.

Yaman celiskiler kusattiginda cepecevre yalnizligini

bir adim otesi yada sonrasi

hep muamma kalacak

yasamina dair tum bildiklerin ve ben! ..', 'Iki nefes arasinda duraklamadan depresecek  dilin, dizecek isyankar sozcukleri. Donen dunya degil,aci dertli basindir kapansada melanet kapi...', ARRAY['Türk Edebiyatı','Şiir','Hatice Gunes']::text[], 8.5, '{"poet":"Hatice Gunes","poet_slug":"hatice-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kusatma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değiş-Tokuş', 'degis-tokus-mahya-sultan-tosun-jpbxo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzgünüm, bir süre için

Geri almak zorundayım 

Kalbimi senden

İncinmesin diye.

Sakın üzülme

Seni düşünmeye devam edecek

Her ne olursa olsun.

Merak etme

Kimselere vermem

Sen hayata

Hayatıma dönene kadar.

İlelebet senin O...', 'Üzgünüm, bir süre için Geri almak zorundayım  Kalbimi senden İncinmesin diye. Sakın üzülme Seni düşünmeye devam edecek Her ne olursa olsun. ...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/degis-tokus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başı Hislerimin Ayaklarında Aşkın**', 'basi-hislerimin-ayaklarinda-askin-mehmet-kizilay-0iksv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''en hassas sarrafların

Ayarını çözmekten aciz kaldığı

Aşk

Aciz kaldı hislerimi anlatmaya''

birşeyler demeliyim

tek kelimelik olsa da 

birşeyler.kabaran hislerden

sıkışan kalbim

duracak yoksa.

giden güne yaslanan

bugünde de demezsem

yarının 

yere değecek sırtı...

yağmurun gölgesi

düşmeli artık

bu çirkin portreye

bana ne strüktürel dokudan.

bağıra bağıra

yüreğime yazdığım

sözcükler gömük.

koca koca yapraklar

bir bir..yaladı beynimi

bitti SÖZLÜK.

ne yapsam

değil bir sözcük

harf dahi giremiyor

duygu girdabıma

hasbelkader girenler se

kurtuluş çareleri arıyor..

yalnızlığıma yaslanırken

sessizce bir ses

şaşkınlıkla yardıma geldi.

düşen başımı kaldırdım; 

bir kolu eksik,

rastgele düğmelenmiş

lahutiliğini düşürmüş

perişan gömleğiyle; 

ayak tabanlarını 

asfaltlarda yırttırmış

tanıdık bir yüz.

tanıyordum bir yerden

meşhur biriydi.

herkesin dilindeydi.

''aklı 

şeytanın odalığı yapanlar''la

alışverişte idi.

neyse dedim

söyledim:

beni..

karda çamur edasıyla dinledi.

başı düştü eğildi.

gücümde değil dedi.

hala birşeylerin tortusu kalmıştı.

doğruyu söyledi.

gücünde değildi.

ağır ağır çekildi.

başı..

hislerimin 

ayaklarına değdi.

künyesine baktım

ismi ''AŞK'' yazıyordu..

                                   Mehmet KIZILAY /Karanfil şiirler', '''en hassas sarrafların Ayarını çözmekten aciz kaldığı Aşk Aciz kaldı hislerimi anlatmaya'' birşeyler demeliyim tek kelimelik olsa da  birşeyl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/basi-hislerimin-ayaklarinda-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay Değil', 'kolay-degil-mahya-sultan-tosun-hswxe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuk denecek yaşta

Aşkla tanışmış,

Acısıyla tatlısıyla

Kavgalarıyla sevişmeleriyle

Aşkı yaşamış,

Hayat tecrübesi ve

Zenginleşen kültürü ile

Kendini,

Dünyayı tanımış,

Yılların tükenmesine rağmen

Aşka veda etmiş birinin

Sevgilisi olmak,

Dünyanın en zor görevi! ..', 'Çocuk denecek yaşta Aşkla tanışmış, Acısıyla tatlısıyla Kavgalarıyla sevişmeleriyle Aşkı yaşamış, Hayat tecrübesi ve Zenginleşen kültürü ile...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kolay-degil-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhun Ölümü', 'ruhun-olumu-mahya-sultan-tosun-epb4x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana olan duygularımı

Baskılamam

Ertelemem

Mümkün değildi,

Öldürmek zorunda kaldım 

Bu yüzden.

Bir öpücüğün ile

Tekrar dirilir,

Kalbimin derinliklerinden.', 'Sana olan duygularımı Baskılamam Ertelemem Mümkün değildi, Öldürmek zorunda kaldım  Bu yüzden. Bir öpücüğün ile Tekrar dirilir, Kalbimin der...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruhun-olumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Kez', 'i-lk-kez-mahya-sultan-tosun-t6wqw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk kez

Bu gidişinle

Boşlukta hissettim kendimi,

Uzattığım yerde değildi elin.

Varlığım anlamsızdı,

Yokluğunda.

Amacım sendin artık

Manidar olmak için hayatta.', 'İlk kez Bu gidişinle Boşlukta hissettim kendimi, Uzattığım yerde değildi elin. Varlığım anlamsızdı, Yokluğunda. Amacım sendin artık Manidar ...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ilk-kez-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-mahya-sultan-tosun-e27rw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmeyenler için söylüyorum:

Benim yalnızlığım,

Sensizliğimdir.', 'Bilmeyenler için söylüyorum: Benim yalnızlığım, Sensizliğimdir....', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gercek-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
