INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durma Yeni Aşklar Devir', 'durma-yeni-asklar-devir-ayse-birgul-yilmaz-tgnyk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırık kalbimi hicranlar vuruyor

Derin hüsranlarla kaplı düşlerim

Gönül bu yine de rahat durmuyor

Kendi çıkmazına saplı yüreğim

Açık denizleri hayal ediyor

Hadi durma yeni aşklara koş

Çevir çevir eski tozlu sayfaları da çevir

Durma yeni aşklar devir, devir bu devir

Sevda yolunda bitmez seyir

Pişmanlık duyma yaşadıklarından

Giden gider elden ne gelir

Ardına bakma yeni aşklar devir', 'Kırık kalbimi hicranlar vuruyor Derin hüsranlarla kaplı düşlerim Gönül bu yine de rahat durmuyor Kendi çıkmazına saplı yüreğim Açık denizler...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/durma-yeni-asklar-devir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alma', 'alma-erol-dal-8ptbn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alma verdiğini

Güzel kadın..

Yıkılmışlığım arasında 

Arama ateş

Sorma,

Geçmişin aldıklarını aynalardan.

Sorma, bedeninde dar gelen bedeni.

Sorma, güzel kadın

Kapaklarında göz damlalarının çizgilerini.

Yılların, verdiğini anımsa,

Ki, 

Anılarımda kalsın öylece.

ED/Mekan/04', 'Alma verdiğini Güzel kadın.. Yıkılmışlığım arasında  Arama ateş Sorma, Geçmişin aldıklarını aynalardan. Sorma, bedeninde dar gelen bedeni. S...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/alma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
