INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken..', 'giderken-ferit-teksoy-eqa0y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durgun nehir,sisli vadi

Sizde mi ayrıldınız sevdiğinizden? 

Şu girdiğim tünel,sarı yapraklı orman

Söylermisiniz lütfen! ..nedir? 

Birinizi karartan diğerini sarartan? 

Yan masada oturan,

Top sakallı,kır saçlı adam

İç..afiyet olsun da,

Bu kadar medet umma o içtiğin rakıdan

Şimdi yanından geçtiğim sarı pancurlu ev

Pekii..senin derdin ne? 

Öylesine sıkı sıkı pancurlar kapattıran

Ah..deprem konutları

Sizi tanıyorum ben..

Nasıl da belli yaşadığınız acı

Duvarınızda gördüğüm gri renkli boyadan

Sen! ..

Minik kuş,ninesine Sapanca gölünü soran

Henüz yaşın ya on birdir,ya on iki.

Dilerim ömrünce bakma,bütün bu olanlara

Ne benim baktığım yönden,ne baktığım açıdan

Ya sen! .

Beni götüren Tren

Acelen ne be dostum? 

Çok mu mutlusun şimdi sevgili ayırmaktan? 

Akşamın kasvetini yükledin gözlerime

Adalar üstündeki yağmur bulutlarıyla

Ayırdın sevgiliden,çıkardın aydınlıktan', 'Durgun nehir,sisli vadi Sizde mi ayrıldınız sevdiğinizden?  Şu girdiğim tünel,sarı yapraklı orman Söylermisiniz lütfen! ..nedir?  Birinizi k...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/giderken-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şansım yok ki', 'sansim-yok-ki-zafer-zengin-etnika-w0w7t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şansım yok ki; 

Ben gidince

Deniz çekilir sessizliğine

Beklesem hasret

Beklesem fırtına

Balık kokusu sarar ellerimi

Yıkasam kan

Yıkasam duman

Takalar kaçar iskeleden

Şanssızım işte

Takılamam taka peşine

Yüzme bilmez/k o r k u l a r ı m

Kaçsam koku

Kaçsam ses

Mavi gelir sevda

Takmış yelkeni başına

Nazlı gelin havasında

Vurgun gelir yanıma/g ü l e m e m

Gidersem iyot

Gidersem tuz

Saklanan son balık

Tütsülenen bakışlar

Masada rakılar şaraplar

İçer gözlerim/ y a k a m o z 

Otursam rüzgar

Otursam beyaz

Açılır uzaklara /s ı ğ ı n t ı l a r

Tekne içinde yabancı sesler

Gözler

E l l e r...

Ayrılık kokar taka sesleri/ r a s t g e l e...

3 Mayıs 2004 '' İçimin kitabı ''', 'Şansım yok ki;  Ben gidince Deniz çekilir sessizliğine Beklesem hasret Beklesem fırtına Balık kokusu sarar ellerimi Yıkasam kan Yıkasam duma...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sansim-yok-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '439''uncu Sokak', '439-uncu-sokak-cem-ozdemir-e0ome', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün durup dururken..

anımsayıverdim o şehrin loş akşamlarını..! 

Lacivert rengi gecenin..

önce griye.. sonra siyaha dönüştüğü

sokaklarını..! 

Bir labirent gibiydi sokaklar..

kâh çıkmaz.. kâh dolambaçlı..! 

Ama gece hepsinde aynıydı.

Sessiz.. soluksuz.. ıpıssız..! 

Bir sokak vardı..

diğerleri arasında kaybolmuş..! 

Adeta çaresiz.. adeta bitkin.. adeta yapayalnız..! 

Köhne bir kaç ev.. yıkılmış bir iki duvardı..

bütün giyimi..! 

Ve paslanmış, çürümüş bir tek tabelaydı..

tek kimliği.. 439''uncu sokağın..! 

Gecesi, tüm sokaklardan daha bir ıssız..

sesi, hepsinden daha bir cılızdı..! 

Adeta kaybolmuş.. adeta bir hiç.. terkedilmiş..! 

Neden bilmem..? ! 

Sonsuz bir mutluluk..

tarifsiz bir huzur duyardım bu sokakta..! 

Gerçi, gecelerinden ürperirdim.

dağıtmak için karanlığı..

kibritler yakardım, birbiri peşi-sıra..! 

Yok etmek için ürpertimi..

bir melodi mırıldanırdım, usul-usul..! 

Ve.. nihayet..

sanki kâinatı dolaşıp, tekrar geri dönmüşcesine..

yankılanıverirdi aynı melodi, yıkık duvarlarda..! 

Öylesine derinden.. öylesine hafif..! 

Yalnızlığım mıydı, söyleyen..? ! 

Yoksa rüzgar mıydı, bilinmez..? ! 

Hiç bir zaman cevap vermedi.. 439''uncu sokak..! 

Oysa..

devleşen yalnızlığımı, kimbilir kaç kez hapsetmiştim..

o köhne duvarlar arasına..? ! 

Kimbilir kaç kez haykırmıştım..

ulurcasına..

o simsiyah, bomboş geceye:

''yeter artık, sabah olsun..! '' diye..! 

Ama bir kez olsun bile duymadı.. 439''uncu sokak..! 

...

Ve.. şimdi..! 

Yıllar sonra bir gün, durup dururken..

anımsayıverdim, o şehrin loş akşamlarını..! 

Lacivert rengi gecenin..

önce griye.. sonra siyaha dönüştüğü sokaklarını..! 

Hayalimde resmi geçit yaparken, tüm paslı tabelalar..

yıkılmış bir duvar altında..

adeta kaybolmuş.. adeta yokolmuş.. unutulmuş..

maziye gömülmüştü.. 439''uncu sokak..!', 'Bir gün durup dururken.. anımsayıverdim o şehrin loş akşamlarını..!  Lacivert rengi gecenin.. önce griye.. sonra siyaha dönüştüğü sokakların...', ARRAY['Türk Edebiyatı','Şiir','Cem Özdemir']::text[], 8.5, '{"poet":"Cem Özdemir","poet_slug":"cem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/439-uncu-sokak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkülerimiz / deneme', 'turkulerimiz-deneme-k-muran-esen-w4nty', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Türkülerimizi düşündüm. Yurdumuzun çeşitli yörelerinden izler taşıyan; içinde sevgileri, acıları, sitemleri,özlemleri, umutları barından türküleri. Bugün başka tür müziklere neredeyse yenik düşmek üzere olan öz müziğimizi.

Ben bu güzel türkülerle büyüdüm. Televizyonun olmadığı çocukluğumda, radyo ile tanıdım ve sevdim türkülerimizi. Türküyü söyleyen kişinin sadece sesi yetiyordu. Çocukluğumda, çanta gibi sapı olan kılıfının içinde koruduğumuz bir radyomuz vardı. Annemin elinden hiç düşmezdi. Kucaktaki çocuk gibi, annemle beraber gezer dururdu evin içinde. Annemin evin hangi odasında işi varsa, o odadan duyulurdu radyonun sesi. 

Türkülerimizi işte ben o radyoyla tanıdım. Türkülerimizi o radyoyla sevdim. Onlara o radyoyla bağlandım. Nezahat Bayram’ın, Aliye Akkılıç’ ın, Niyazi Yılmaz’ın, Ahmet Sezgin’in, Muzaffer Akgün’ün, Neriman Altındağ’ın ve daha birçok Türk Halk Müziğini icra eden o zamanın sanatçılarının sesleri hâlâ kulaklarımda.

Nesrin Sipahi, Behiye Aksoy, Necdet Tokatlıoğlu gibi Türk Sanat Müziği söyleyen sanatçıları da bu radyoyla tanıdım. Yıllardır bu sanatçılarımızı dinlemediğim halde; şimdi onlardan birinin sesini duysam hemen tanırım. “İşte bu falanca,” Diyebilirim. Öylesine yer etmiştir, iz bırakmıştır bende. 

Bugün artık pek dinleyemediğimiz türkülerimizin her biri bizden bir parçadır aslında. Sözleri anlamlı ve uyumludur. Şimdiki liste başı şarkılar gibi, sözleri saçma ve anlamsız değildir. Her birinin bir öyküsü vardır. Toplumsal veya ferdi yaşanan olayların sonucunda, halkımız tarafından yaratılmışlardır. Çalındıkları ve söylendikleri yerlerin seslerini,hislerini alarak, günümüze kadar gelmeyi başarmışlardır. Kimisinde acılarınızı bulursunuz, kimisinde umutlarınızı, kimisinde sevinçlerinizi. Ağıtlarında ağlamak, oyun havalarında oynamak istersiniz.  “Yarim İstanbul’u Mesken mi Tuttun? “ türküsünü dinlerken; ekmek parası için evinden ayrılıp İstanbul’a giden, yedi yıldır köyüne dönmeyen eşine sitem eden bir köy kadınının acısını içinizde duyarsınız.  “Şeker Oğlan”  ı  “Hüdayda” yı dinlerken, içinizin kıpır kıpır ettiğini hissedersiniz.  “Hem Okudum Hemi de Yazdım” ı dinlerken, yavrusunu kaybeden bir annenin yürek yangınını eminim siz de yüreğinizin derinliklerinde duyarsınız. Kısaca, her yönüyle bizi sarar türkülerimiz.

Bizim öz müziğimiz olan türkülere haksızlık ediliyor. Onlara gereken önem verilmiyor. Gerektiği gibi ve gerektiği kadar çalınıp söylenmiyor. 

Çocuklarımıza, gençlerimize türkülerimizi tanıtamıyoruz, sevdiremiyoruz. Ben öğrencilerimin türkülerimizi pek bilmediklerine ama; benim kulaklarımı tırmalayan, adına  “müzik”  bile diyemeyeceğim günümüzün moda parçalarının hemen hepsini bildiklerine tanık oldum. Türkü mırıldanan bir çocuğa pek rastlamadım. Hepsinin dilinde; adını bir türlü koyamadığım, saçma sapan sözleri içeren parçalar. Bunların bazılarını daha ben hiç dinlemediğim halde, liste başı olduklarını duyunca şaşırıyorum. Kendimi dünya ile ilişiğini kesmiş biri gibi hissediyorum. Çağımızın gerisinde kalmış biri olmanın endişesini yaşıyorum. Çok değil, iki gün televizyon izlemezsem, günümüzün meşhur sanatçılarından(!)  ve onların liste başı olmuş parçalarından habersiz oluyorum. Kendimi başka dünyadan gelmiş ve bu dünyanın yabancısı gibi görüyorum. 

Parça besteleniyor, iki gün sonra liste başı oluyor. Şarkıyı okuyan kişi de âdeta ilâhlaştırılıyor. Söyleyeni meşhur edip çıkıyor. O kişinin saç kesimi, giysisi, hatta sarfettiği kelimeler, gençler için bir sembol oluyor. Şarkının klibi televizyon haberlerine konu olabiliyor. Klibin çekimleri yurt dışında yapılıyor çoğunun. Cennet yurdumuzda, o güzelim şarkının(!)  konusuna uygun bir mekân bulunamıyor. Klipte şarkıyı okuyan kişiye eşlik edecek birisine milyarlar veriliyor. Ancak, bu kişilerin arkasında amaçlarını bir türlü anlayamadığım birileri var. Sanki sihirli bir el değmişçesine, şarkı ve şarkıyı okuyan, Türkiye’de “bir numara” oluveriyor. Bu parçalar nasıl seviliyor, nasıl ilgi görüyor? Ne çabuk meşhur oluyor? Bir türlü çözemiyorum. Onlardaki güzelliği sezemiyorum. 

İşte bu parçalara yenik düşmek üzere türkülerimiz. Türkülerimizi neredeyse arka plana iten, çocukların ve gençlerin dilinden düşürmedikleri parçalara bir göz atalım isterseniz. Onlarda, gözümden kaçan bir fevkaladelik var da, ben mi sezemiyorum? Önce sözlerinden başlayalım:  “Kıl oldum abi”,  “Ortada kuyu var, yandan geç”, “Amme velakin, cümbür cematin”, “Aganigi naganini”, “Ankara Devlet Su İşleri / Bırak yavrum bu işleri” gibi.

Bunlar hemen şimdi aklıma geliverenler. Bu sözlerde sizce bir fevkaladelik var mı Allahaşkına? Efendim deniliyor ki; çocuklarımız ve gençlerimiz bu müzikleri seviyorlar, dinliyorlar. Onların deyimiyle  “ çok tutuyorlar”  İşte sanatçılar(!)  da o nedenle bu tür müzik yapıyorlarmış. Ve insanları eğlendirmek istiyorlarmış. Oysa, bunların yaptığı eğlendirmek değil, saçmalamak...

Çocuk sabah gözünü açtığında televizyonda bu müzikleri dinliyorsa; düğünde, davette,parkta, çay bahçesinde bu müzikleri duyuyorsa, yani bu müziklerle büyüyorsa, bu müzikleri sevmesi, tutması (onların deyimi bu)  çok normal. Dinleye dinleye alışıyorlar, sevmeye başlıyorlar.

Bu bana, çok eski yıllara ait bir öyküyü hatırlattı: Zamanın birinde bir gelin kaynana varmış. Her gelin kaynana gibi onlar da zaman zaman tartışırlarmış. İşte böyle bir günde gelin kaynanasına; “Bu eve gelin geldiğimde kokudan, pislikten girilmiyordu. Şimdi evde koku moku kalmadı. Her taraf mis gibi oldu.” demiş. Gülmüş kaynanası.”Ah kızım ah! ” demiş.  “O koku hâlâ var bu evde. Ama, senin burnun alıştığı için kokuyu duymuyorsun.”

İşte çocuklarımız, gençlerimiz bu müzikleri devamlı dinledikleri için, bunlarla yatıp kalktıkları için, bu müziklerdeki basitliği, taklitçiliği sezemiyorlar. Onlara güzel geliyor. Dinleye dinleye alışıyorlar ve sevmeye başlıyorlar. Üstelik böylece çocukların ve gençlerin değer yargıları da değişiyor. Onları kolay şeyleri, değersiz şeyleri, kolay yoldan elde edilen şeyleri sevmeye yöneltiyoruz. Sanatsal hiçbir değeri olmayan ve birkaç günde televizyonun etkisiyle Türkiye’nin gündemine oturan şarkıları yapanlar, çocuklarımıza kötü örnek oluyorlar. Böylece çocuklarımız müzik eğitimi almadan müzik yapmaya, televizyondaki abileri ve ablaları gibi kolay yoldan meşhur olmaya özeniyorlar. Bir işin eğitimini almak, onlar için hiçbir değer ifade etmiyor.

Bu müziklerle büyüyen, bunları besteleyenlere ve yorumlayanlara “Sanatçı” gözüyle bakan çocuklarımız, büyüdüklerinde, nasıl parçalar bestelerler dersiniz? Mesela şöyle bir parça olabilir. Aynı bugünki şarkıların sözleri gibi:

Kediler der miyav miyav

Annem pişirmiş pilav

Gel koçum bir kaşık al.

Hap dedik, hop dedik

Pilavı yedik, bitirdik.

Alsana cicim alsana

Lay lay lom.

Güldüğünüzü duyar gibi oluyorum. Eğer gülüyorsanız haksızlık ediyorsunuz demektir. Çünkü günümüzün hit (!)  parçalarından ne farkı var bu şarkı sözlerinin? Sözler, en az onlar kadar anlamlı, onlar kadar uyumlu. Hatta onlardan bir gömlek daha üstün. Biz çocuklarımıza buna benzer müzikler dinletirsek, onların da böyle sözleri şarkı yapmaları çok normaldir. Ne demiş atalarımız: “Ağaca çıkan keçinin, dala bakan oğlağı olur.”

Peki ya eski türkülerimiz ve şarkılarımız? Onları besteleyenler, onlara söz yazanlar? ....O eski sanatçılara, onların yarattığı eserlere haksızlık edilmiyor mu? Türkülere, şarkılara verilen emeği bir çırpıda silip atmış olmuyor muyuz, bu günki müzikleri yapmakla? Çocuklarımıza ve geçlerimize bu saçmalıkları sunmakla, eski sanatçıları arka plana atmış olmuyor muyuz? Sanatı ve sanatçılığı basite indirgemiyor muyuz? 

Eser yaratmak,öyle kolay değil. Bir yerlerden çalınmış melodilere, uydurma sözler yazarak milyonların karşısına çıkmak, o milyonları hafife almaktır. Yahya Kemal Beyatlı; yazdığı bir şiiri tam iki sene bekletmiş yayımlamak için. Bunun sebebi de, şiirdeki sadece bir dizenin sözleri, istediği gibi olmadığı için. Sanatçıdaki şu titizliği anlayın lütfen.

Bir de o güzelim türküleri değiştirerek, otantikliğini bozarak söyleyenlere ne demeli? Neymiş efendim, yeni bir yorum getiriyorlarmış. İnsanları eğlendirmek istiyorlarmış. Bir türkünün aslı nasılsa, öyle söylenmeli. Yeni şeyler üretemeyenler, sanatı sadece şöhret ve para için yapanlar, daha doğrusu sanat icra ettiklerini zannedenler, türkülerimizi de bozuyorlar. Çok sevdiğimiz o güzelim türküleri, ne olduğu belli olmayan bir ses kalabalığına dönüştürüyorlar. Bu kişilere “ dur” diyecek birilerinin olmaması üzüyor insanı.

Kültür Bakanlığının, bu konuda yapacak bir şeyleri mutlaka olmalı. Ne “Hüdayda” nın, ne “Osman Abim Evde mi” türküsünün, ne de başka türkülerimizin bozulmasına gönlüm razı olmuyor. Bu türkülerin yeni yorumlara ihtiyacı yok. Hele hele o anlamsız kliplere hiç ihtiyacı yok. Bu türkülerimizi bozanlar, türkülerimize artık dokunmasınlar. Kendilerinin yapabilecekleri müzikleri yapsınlar. O güzel şarkı ve türkülerimizin gerçek sahiplerinin kemikleri daha fazla sızlamasın.

“Müzik evrenseldir.” diyerek, yabancı müziklere Türkçe söz yazarak bunları çocuklarımıza ve gençlerimize sevdirmeye çalışanlar!  “Yeni yorum getiriyoruz,“ kolaycılığına sığınarak şarkılarımızı ve türkülerimizi bozanlar! Argo, anlamsız, saçma sapan sözlerle şarkı yapanlar! .....Sözüm sizedir: Şarkılarımıza, türkülerimize lütfen dokunmayın. Onların güzelliğini, özelliğini bozmayın. Çocuklarımıza ve gençlerimize  “müzik “ diye, yaptığınız saçmalıkları sunmayın Belki o zaman bize daha az zararınız dokunur. Böylece, eskinin o güzelim şarkıları ve türküleri sizden kurtulmuş olur.', 'Türkülerimizi düşündüm. Yurdumuzun çeşitli yörelerinden izler taşıyan; içinde sevgileri, acıları, sitemleri,özlemleri, umutları barından tür...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/turkulerimiz-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül..Diken', 'gul-diken-fatih-ozkonyali-9qqnu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ya gülüver yüzüme, güller gülüşünle solsun,

Ya gülü ver kalbime, ya diken hançer olsun', 'Ya gülüver yüzüme, güller gülüşünle solsun, Ya gülü ver kalbime, ya diken hançer olsun...', ARRAY['Türk Edebiyatı','Şiir','Fatih Özkonyalı']::text[], 8.5, '{"poet":"Fatih Özkonyalı","poet_slug":"fatih-ozkonyali","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/gul-diken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Kokunda Rüzgar Esti', 'gul-kokunda-ruzgar-esti-sadik-softa-f8oe6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben esaret çemberine girdim seni göreli.

Kayboldu gönül huzurum, seni sevdim seveli.

Çok duygular kurban ettim, bu yel senden eseli; 

Gül kokunda rüzgar esti, getirdi seni bana; 

Ben bana sığmıyorum ya, artık sığmam cihana.

Erişilmez bir deryada, sevgimin zirvesisin.

Kollarımda dermanım yok, sen gönül gölgesisin.

Yakamozlar şavkın sarmış, bir derya busesisin; 

Gül kokunda fırtınalar, sürükler seni bana; 

Ben bana sığmıyorum ya, artık sığmam cihana.

Nice mavi türkülerle, umuda uzanmışım.

Dert yasiri oldum artık, umut ile yanmışım.

Bir gelincik taşındayım, bir katrecik kanmışım; 

Gül kokunda kokun gelir, sürükler seni bana; 

Ben bana sığmıyorum ya, artık sığmam cihana.

Erisem de taş misali, gam ne, yükünü çeksem? 

İpini çeker misin, bu boynum dara çeksem? 

Yadi veren çiçeğinde, gönlüne sevda eksem; 

Gül kokunda gülücükler, sürükler seni bana; 

Ben bana sığmıyorum ya, artık sığmam cihana.

Cümle hayatın yükünü, taşırım gram gram.

Tüm gönlümle olmuşum, senin sevdan ile ram.

Temsil eder bu gönülü, ispatı gerçek sevdam; 

Gül kokunda sevda yeli, sürükler seni bana; 

Ben bana sığmıyorum ya, artık sığmam cihana.

Kapanır bak o zaman, ayrılıktan yaramız.

Kurumuş dudaklarım, çatlamış yol sevdamız.

Gözlerime fer ol artık, kapansın bu davamız; 

Gül kokunda sevda kokar, sürükler seni bana; 

Ben bana sığmıyorum ya, artık sığmam cihana.

Çankırı-25.04.2004', 'Ben esaret çemberine girdim seni göreli. Kayboldu gönül huzurum, seni sevdim seveli. Çok duygular kurban ettim, bu yel senden eseli;  Gül ko...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gul-kokunda-ruzgar-esti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örümcek Gözlerim', 'orumcek-gozlerim-umut-yalim-4gg9d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum demeyecem

Ama seviyorum Verda

Belki kaçtır lüzumsuz seviyorum

Ömür ilanımı veriyor gasteler

Ne kadar yaşayacağmı biliyorum ama

Kaçtır lüzumsuz yaşıyorum.

Tercihimdi gözlerimi ölü taşımak

Ama gözlerim örümcek gözleri

Güzelliğni yüzüne ince ördüğüm

Bakarken sanki fena rahatsızsın

Basılan bir parti gibi sıkıntılı

Ağzında virgül bir sigara

Dumanında uzun idamlandığım

Ağır tamamlansa da infaz

Ölmeye devam ediyorum.

Bana atma jilet gözlerini

Seviyorum demeyecem Verda

Seni böyle sevmedim çünkü

Seviyorum demedim seni üzgünüm

Üzgün olmaktan belki yorgunum

Ama sen de besbelli demeyecen

Deseydin zaten sevemezdim seni.

Yüreğimde yüreğni emziriyorum

Yalnızlığından kan alıyorum durmadan

Bana Anna Frank gibi bakma Verda

Artık örümcek gözlerimden tanı beni

Gözlerimi yüzüne bıçak bıçak ördüğüm

Yüreğindeki kırık kemikleri sardığım

Beni artık seni sevmemden tanı ne olur

Seni seviyorum demeyecem 

Ama seviyorum Verda.', 'Seni seviyorum demeyecem Ama seviyorum Verda Belki kaçtır lüzumsuz seviyorum Ömür ilanımı veriyor gasteler Ne kadar yaşayacağmı biliyorum am...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/orumcek-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerinden Öptüm Başımda', 'ellerinden-optum-basimda-derin-oger-5s1q6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'söz dar gök uykuda

derin bir gökyüzü altında

yıldızlar bir bir kayıyor gözlerimin  içinden

oysa bir yürekti yıldızları salkımlayıp yüreğime yakıştıran 

ki cennetin ötesinden baktımm baktım

yıldızlar yüreğin kadar aydınlık ve sıcak değildi

tutamadığım ellerini öpesim geldi

sen elimin üstüsün......

istemem yıldızları

ak dağlara düşsün pırıltıları

sevemedim gümüş kanatlı aldatan ışıklarını

oysa sendin körükleyen sendin yakan soğuk ayın yüzündeki ateşi

hem bilmem yeter bana bir meleğin beni sevdiğini

baktım baktım saf ve temiz bir huzura doğru

ki göğüm şimdi baştannn başa

sen başımın üstüsün......

konuşmadan anlaşılmak ve anlamak.', 'söz dar gök uykuda derin bir gökyüzü altında yıldızlar bir bir kayıyor gözlerimin  içinden oysa bir yürekti yıldızları salkımlayıp yüreğime ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ellerinden-optum-basimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalardan Yüzümü Alıpta Gittin.', 'aynalardan-yuzumu-alipta-gittin-ahmet-capa-ueyvj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve gittin...

Dünyanın bütün ağaçlarını kalem yapıp yazmışken seni,

Beynimin her hücresinden adını alıpta gittin,

Bu aşkın seri numarasını silerek sayfalardan,

Anonim bir sevda gibi tozlu raflara bırakıpta gittin.

Ne yazacak güç kalmıştı kalemde,

Ne söyleyecek söz kalmıştı dilimde,

Bırakmışken arzumu avuçlarına,

Ağzımdan dilleri alıpta gittin.

Bir toplu iğne başı kadar yerim yokken bu dünyada,

Kendimi çoğaltır gibi aynalara baktım sonra,

Gözlerinin attığı imzaları ararken göz kenarlarımda,

Aynalardan yüzümü alıpta gittin.

Hangi bardağa dokunmuştun en son,

Ve hangi tarakla taramıştın saçlarını,

En son yürüdüğümüz sokak hangisiydi,

Ya en son yemek yediğimiz tabak,

Ve sen bütün sonları bana bırakıpta gittin.

Beyhude verilen bir nefes gibi,

Saatlerden yelkovanları alıpta gittin,

Ölmek üzere olan bir serçenin gözyaşları gibi,

Ömür yelkenimden rüzgârları alıpta gittin.

Her zil sesinde kapılara koşmak gibi,

Her köşe başında sanki sen çıkacaksın karşıma,

Açılmayan kapıların ardındaki boşlukta,

Bir vapur düdüğü gibi ıslığını bırakıpta gittin.

Çiçekler suya hasret,

ki onlar her yağmur yağanda buluşurlar,

Bilmemki ben yanlış yağmurlardamı bekledim,

Ve estin bir tayfun gibi bütün rıhtımlarda,

İskeleden omzunu alıpta gittin.

Hayaller sürürken ayaklarını uykularımda,

Umutlar gibi bu sevdayı topal bırakıpta gittin,

Ellerinin şarjöründen veda mermisini,

Saçlarının teli gibi göğsüme bırakıpta gittin.

(Mayıs 2004 İST.)', 'Ve gittin... Dünyanın bütün ağaçlarını kalem yapıp yazmışken seni, Beynimin her hücresinden adını alıpta gittin, Bu aşkın seri numarasını si...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/aynalardan-yuzumu-alipta-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denize Yürüdü Kadın..', 'denize-yurudu-kadin-musfik-saltik-t6yxa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kumsalda kimse yoktu 

Denizden sert bir rüzgâr esiyordu

Narin yüzünü bıçak gibi kesiyordu

Saçları havalanmış  dalgalanıyordu

Geriye doğru uzanan eteği sanki onu çekiyordu

Bedenine çarpan rüzgâra direniyor

Bronz bir heykel gibi  dimdik duruyordu

İki yana açılmış kollarıyla

Sanki hayata meydan okuyordu

Gözleri ufka kilitlenmişti

 Bir cesaret abidesi gibiydi

Hiç kımıldamıyordu

Sonra başını öne eydi

Elleriyle saçlarını topladı

Çıplak ayaklarıyla yavaş adımlar attı

Ayakları suya ulaştı 

Önce parmakları ıslandı 

Sonra devam etti yürümeye

Su dizlerini aştı 

Islanan etekleri ağırlaştı

Bacaklarına yapıştı

Hiç duraksamadan yürüyordu

Soğuk su bedenini donduruyordu

O halâ dimdik yürüyordu ufka doğru

Su boynunu aştı sanki denizle kaynaştı

Sonra gözden kayboldu

Suyun yüzünde birkaç köpük belirdi

Onlarda bir süre sonra dağıldı 

Sonra su da duruldu 

O sonsuz yolculuğuna 

Sonsuz ufka doğru yürüyerek

Denizden gidiyordu

Ne bir ses çıkartmıştı

Ne bir çığlık atmıştı

Ne geride bir ceset bırakmıştı 

Ondan son kalan ıslak kumdaki

Birkaç ayak iziydi

O izleri de sildi deniz

Küçücük bir dalgayla

Deniz saygı duymuştu

Bu cesaret abidesi kadına

İntihar  etmemişti O

Deniz basmıştı onu bağrına 

Güneş o gün daha hızlı alçaldı

Ufuktan denize daldı

Üşümesin diye bedeni 

O mağrur kadını sardı

Sonra hava karardı

Deniz karardı

Kadın da

Güneş de

Deniz de

Derin bir uykuya daldı

Yıldızlar çok uzaktan göz kırpıyorlardı

O gece ay da bir başka gülüyordu

Gururlu insanlar

Ölürken de gururlu ölüyordu

İnsanlar  duymasa da

Doğa onlara saygı duyuyordu.

                 Mayıs 2004', 'Kumsalda kimse yoktu  Denizden sert bir rüzgâr esiyordu Narin yüzünü bıçak gibi kesiyordu Saçları havalanmış  dalgalanıyordu Geriye doğru uz...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/denize-yurudu-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biten baharım', 'biten-baharim-gulden-karabudak-4swdz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk yaz gibi.. 

susuzuluğunda kurumuş dudaklarım 

bir adım ötesi bahar 

bir adım kadar uzaksın bana 

çiçekliğimde yeşeren dal kadar masum 

içimdeki huzur kadar benimsin 

ilk yaz gibi... 

sıcağında üşümüş damarlarım 

her dünde bir sen 

her sen bir bahar aslında 

ardımda kalan her bahar 

ilk yazı ağlatır ya bana 

düşen gözyaşım kadar 

benimsin şimdi... 

ilk yaz gibi...', 'İlk yaz gibi..  susuzuluğunda kurumuş dudaklarım  bir adım ötesi bahar  bir adım kadar uzaksın bana  çiçekliğimde yeşeren dal kadar masum  i...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biten-baharim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bâki''dir Gönül (Nazire)', 'b-ki-dir-gonul-nazire-mehmet-fatin-baki-pyg9s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zulme kâdir düşmanından aşkı vâkîdir gönül

Eylemek yok derdin izhâr. Sırrı hâkîdir gönül.

Nem birikmiş gözlerinden damlayan yaş gösterir

Her zaman  gam yüklü bir gurbette âkîdir gönül

Hem sevenden hem güzelden duyduğum hasret dolu

Yıl geçer, bir gün gelir, yârdan da şâkîdir gönül.

Mâha benzer vechinin her günde bir kez geldiği

Meclisin koynunda yatmış nazlı sâkîdir gönül.

Bâkî der ki, durmadan kalbim yanarken kor gibi, 

‘Ben ölürsem âlemî ma’nâda bâkîdir gönül.’  (1) 

(1)  Nef’î nin  gazelinden

İzhâr = gösterme, meydana çıkarma

Vâkî = koruyan     Hâkî = saklayan

Âkî = isyan eden    Şâkî = şikayetçi

Vech = yüz      Sâkî = mey sunan

Âlem-i mâ’nâda = rüya aleminde   Bâkî = kalan 

Fâilâtün     fâilâtün     fâilâtün     fâilün   

/  .   /   /    /  .   /   /    /  .   /   /    /  .   /   



Nef’i nin  Gazeli

Hem kadeh hem bâde hem bir şûh sâkîdir gönül.

Ehl-i aşkın hâsılı sahip-mezâkıdır gönül.

Bir nefes dîdâr için bin cân fedâ etsem n’ola

Nice demlerdir esir-i iştiyâkıdır gönül.

Dildedir mihrin ko hâk olsun yolunda cân u ten

Ben ölürsem âlem-i ma’nâda bâkîdir gönül.

Zerredir ammâ ki tâb-ı afitâb-ı aşk ile

Rûzigârın şemse-i tâk u revâkıdır gönül.

Etse  Nef’i  n’ola ger gönlüyle dâ’im bezm-i hâs  

Hem kadeh hem bâde hem bir şûh sâkîdir gönül.

Nef’i    (1635)', 'Zulme kâdir düşmanından aşkı vâkîdir gönül Eylemek yok derdin izhâr. Sırrı hâkîdir gönül. Nem birikmiş gözlerinden damlayan yaş gösterir Her...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/baki-dir-gonul-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah Eylediler', 'gunah-eylediler-mehmet-fatin-baki-s1hc2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rabbı sevdim bana âşık dediler

Bilerek gıybete âh eylediler

Adın andım, bana mâşuk dediler

Muzil onlar ki günâh eylediler.

Koyu bir mezhebe mensub dediler

Sunulan rahmete vâh eylediler

Öte yandan bana meczub dediler

Muzil onlar ki günâh eylediler.

Gıybet = çekiştirme, yerme

Muzil = zillete düşürenler

Mensub = tâbi, ilgili

Meczub = Tanrı sevgisine tutulmuş divâne 

Feilâtün     feilâtün    feilün

.  .   /   /   .  .   /   /   .  .   /', 'Rabbı sevdim bana âşık dediler Bilerek gıybete âh eylediler Adın andım, bana mâşuk dediler Muzil onlar ki günâh eylediler. Koyu bir mezhebe ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gunah-eylediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte böyle Bir Günün Akşamında', 'i-ste-boyle-bir-gunun-aksaminda-cem-ozdemir-sw849', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün, hep seninleydim birtanem..! 

Hayalinle birlikte yaşadım..

birbiri peşi-sıra geçen saatleri..! 

Sabah uyandım, bir de baktım ki; 

O da nesi..? ! Yanımda sen varsın..! 

Sere serpe.. öylece uzanmış yanıbaşımda..

ve dudaklarında hınzır bir gülümseme:

''Ne o..? ! Niye şaştın..? ! ''.. der gibilerden..! 

E, aşkolsun be birtanem..! 

Hani.. hayal de olsan..

ya da farzedeyim ki, gerçek..! 

İnsan bir haber verir değil mi..

hiç olmazsa geldiğini..? ! 

Ben ki, seni böylesine özlemişken..! 

Ben ki, sana böylesine susamışken..! 

Dindirir mi sanıyorsun..

öğlenlere kadar sanal sevişmeler..

tastamam yedi koskoca yılın hasretini..? ! 

Tutabilir mi sanıyorsun..

sımsıkı sarıldığım şu kuştüyü yastıklar..

o sımsıcak teninin yerini..? ! 

Ve.. anlayabilir mi sanıyorsun..

acaba ki hayalin..

ruhumu.. bedenimi.. ve beni..? ! 

Yok be, birtanem..! Nerdee..? ! 

Hani, dedim ya..! 

Hayal de olsan..

ya da farzedeyim ki, gerçek..! 

İşte böyle bir günün akşamında..

dertliyim şimdi..! 

Ne diyorum, biliyor musun ceylan gözlüm..? ! 

Bak.. saatler öğleni çoktan geçti.

Hava da hiç fena değil, serin..! 

Gel, bu nisan şaşkınlığında seninle..

çocuklar gibi coşalım, alabildiğine..! 

El ele tutuşup yine, yedi yıl öncesi gibi..

hani iki yanında bodur çam ormanları yükselen

o dağ yolunda gezintiye çıkalım..! 

Çiçekler toplayıp şarkılar söyleyelim..! 

Tamam.. sana söz..

ağaçlar arasında saklambaç da oynarız..

boylu boyunca yuvarlanırız da, çimenlerde..! 

Sonra da.. hani otepenin yamacındaki..

küçük ''kendin pişir, kendin ye'' meyhanesinde..

mangalda köfte pişiririz.. tam bir buçuk kilo..! 

Rakı da söyledik mi yanına..! 

Bir de çoban salata..! 

Allah be..! Değme gitsin, keyfimize..! 

Senden bahsederiz bolca..! 

Biraz da benden, istersen..! 

Sen hiç değişmemişsin be ceylan gözlüm..! 

Ama yıllar benden çok şey götürdü gördüğün gibi..! 

Gülüşün hep aynı.. hiç değişmemiş..! 

Sol yanağındaki o hınzır gamze de, yine aynı yerinde..! 

Çatık hilal kaşlarınsa yine aynı çaresizlikten muzdarip,

bir türlü silememiş o hınzır gülüşü..

ince, pembe dudaklarından..! 

Bense, ceylan gözlüm..

işte gördüğün gibi..! 

Kâh, yıllara meydan okumaktan..

kâh, boşverip herşeye.. teslim olmaktan..

sensiz geçen tastamam yedi koskoca yılda

yanmaktan.. yıkılmaktan.. hasret çekmekten..

ve tam bir buçuk kilo köfteyle,

bir büyük şişe rakıyı..

iştahla halletmiş olmanın hazımsızlığında..

karşımdaki hayaline

''Şerefe..! '' deyip kadeh kaldırıyorum..! 

Hani, dedim ya..! 

Hayal de olsan..

ya da farzedeyim ki, gerçek..! 

İşte böyle bir günün akşamında..

sarhoşum şimdi..! 

Evet, birtanem.. ceylan gözlüm..

canım.. herşeyim benim..! 

Vakit geceyarısını çoktan geçmiş..

saatler alabildiğince almış gitmiş başını..! 

Ve ben çok iyi biliyorum ki; 

şimdi yanıma sokulacaksın usulca..

tekir bir kedi kurnazlığında..! 

Önce yanağıma bir buse konduracaksın.

Ardından da başını omuzuma yaslayacak

ve diyeceksin ki: ''üzgünüm..! ''

''Gitmem gerek..! Vakit tamam..! ''

''Her şey için sağol ve kendine iyi bak..! ''

Ve.. ben yine başbaşa kalacağım

o lanet olası yalnızlığımla..! 

İsyanlar yağdıracağım, birbiri peşi sıra..

yollara.. yıllara.. hasretlere..! Her şeye..! 

Kovalar dolusu ağlayacağım, haberin olsun..! 

Göz pınarlarım yılmayacak, dolup boşalmaktan..! 

Dudaklarım, bir an bile bıkmayacak..

adını haykırmaktan, evimin boş duvarlarına..! 

Sonra ise..

yine sensizlikle dolu yeni bir yedi yılın..

ilk günü başlayacak, kasvetli gecenin ardından..! 

Ve ben..

7 X 365 gün daha yaşayacağım yürek zindanlarımda..! 

Bir kez daha olsun, tutmak için elini..! 

Bir kez daha olsun, içmek için tenini..! 

Bir kez daha olsun, görmek için seni..! 

Yani.. hayalini..! 

Ya da farzedeyim ki, gerçeğini..! 

Hani.. dedim ya..! 

İşte böyle bir günün akşamında..

yorgunum şimdi..!', 'Bugün, hep seninleydim birtanem..!  Hayalinle birlikte yaşadım.. birbiri peşi-sıra geçen saatleri..!  Sabah uyandım, bir de baktım ki;  O da...', ARRAY['Türk Edebiyatı','Şiir','Cem Özdemir']::text[], 8.5, '{"poet":"Cem Özdemir","poet_slug":"cem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":106,"source_url":"https://www.antoloji.com/iste-boyle-bir-gunun-aksaminda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldı Bize', 'kaldi-bize-mehmet-fatin-baki-lyg9q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'May içtimsede mey-hoş değilim

Gönül hüsn-i füsûn aldı yine.

Fürâkınlada hiç hoş değilim

Visâl bizden uzak kaldı yine.

Mefâkî sana hasretle yanar

Felek sille vurur sînemize

Bu müzmin yara durmaz da kanar

Visâl bizden uzak kaldı bize.

Hüsn-i füsûn = büyü ve sihir güzelliği

Fürâk = ayrılık    Visâl = kavuşma

Müzmin = eskimiş

Mefâîlü    mefâîlü    feül

.   /   /  .  .   /   /  .  .   /', 'May içtimsede mey-hoş değilim Gönül hüsn-i füsûn aldı yine. Fürâkınlada hiç hoş değilim Visâl bizden uzak kaldı yine. Mefâkî sana hasretle y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kaldi-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmdad', 'i-mdad-mehmet-fatin-baki-4w2qv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yâr elinden çâk olup şerhâda kaldım.

Gâh duman gâh külle bir nefhâda kaldım.

Bir yığın ben kimsesiz bir mâl-ı  metrûk

Doğduğum köyden baid tenhâda kaldım.

Çâk = yarık, yırtık      Şerhâ = parça parça

Nefhâ = yel, hava,  koku     

Mâl-ı metrûk = sahipsiz, terkrdilmiş mal

Baid = uzak                Tenhâ = boş yer

Fâilâtün     fâilâtün     fâilâtün

/  .   /   /    /  .   /   /    /  .   /   /', 'Yâr elinden çâk olup şerhâda kaldım. Gâh duman gâh külle bir nefhâda kaldım. Bir yığın ben kimsesiz bir mâl-ı  metrûk Doğduğum köyden baid t...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/imdad-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm', 'gordum-mehmet-fatin-baki-sxv7e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalınız kaldığımız hücrede dünyâ gördüm.

Odadan çıktığın an devranı tenhâ gördüm.

Kamerin  sunduğu  aydınlığın  etrâfında 

Senin ay yüzlü güzel vechi hüveydâ gördüm.

Sana kalbimdeki mülkten yer ayarken, medfen

Sığacak yirmi bir arşın karelik câ gördüm.

Gözünün damlası dün kaldı benim mendilde

Güneşin doğduğu an koskoca deryâ gördüm.

Kaderin verdiği üç çeyrek asırdan fazla

‘Hâb-ı gaflette geçen ömrümü rüyâ gördüm.’ (1) 

Senelerden  beri  gurbette kalıp  yaşlanmış, 

Kendi derdiyle  yanan, Mehmedi şeydâ gördüm.

(1)  Zatî’nin gazelinden

Tenhâ = boş       Câ = yer

Hüveydâ = açık, meydanda

Hâb-ı gaflet = gaflet uykusu

Şeydâ = şaşkın, divânne

Feilâtün   feilâtün   feilâtün   Fe’ün 

. .   /   /  . .   /   /  . .   /   /    /   /

Gazel

Gözüm açtım bu seher bir ulu sahrâ gördüm.

Anda bir dâne-i hardal gibi dünyâ gördüm.

Def’edüp sinesini hâle-i pür sûzunu ney 

Raksa girmiş nice bin âşık-ı şeydâ gördüm.

Nice bin zevrâk-ı ser geşte ana müstağrak.

Cûş edüb mevce vurur bir ulu deryâ gördüm.

Ne güzel vakıadır bu iki açub can gözünü

Hâb-ı gaflette geçen ömrümü rüyâ gördüm. 

Zatiya hiç zeval vermez ana zerre kadar

Dide-i can ile bir şems-i hüveydâ gördüm.

ZATİ       (1477-1546)', 'Yalınız kaldığımız hücrede dünyâ gördüm. Odadan çıktığın an devranı tenhâ gördüm. Kamerin  sunduğu  aydınlığın  etrâfında  Senin ay yüzlü gü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gordum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir', 'kim-bilir-mehmet-fatin-baki-o57ue', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bağçemizden gitti bülbül neyleyim ben gülşeni

Son bahardan sonra kıştır, zikreder bülbül Seni

Beklenen bir gün, diğer dünyâya gittim farzedin

Kimliğim dünyâda kalmış kim bilir Sensiz beni.

Bağçe = hayat

Bülbül = rûh

Gülşen = vücut

Sen = Hâlik, yaratan

Ben = kul

Fâilâtün     fâilâtün     fâilâtün     fâilün 

/  .   /   /    /  .   /   /    /  .   /   /    /  .   /', 'Bağçemizden gitti bülbül neyleyim ben gülşeni Son bahardan sonra kıştır, zikreder bülbül Seni Beklenen bir gün, diğer dünyâya gittim farzedi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kim-bilir-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak, Toprak ve Park', 'yaprak-toprak-ve-park-mehmet-fatin-baki-9tvtw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Et  lûtf,  İlâhî  bir  aşka

Nefs kandıran sahte çarktır.

İnsan, gönülden de başka,

Yaprakla toprak ve parktır.

Mü’min biziz Hakka döndük

Nurduk, karanlıkta  söndük

Ahlâkla  örf  ağlatan  yük

Yaprakla toprak ve parktır.

Dünyâda sevmek yalan mey

Ukbâda rûhtan çalan ney

Defterde Bâkî kalan şey

Yaprakla toprak ve parktır.

Yaprak = doğum

Toprak = ölüm

Park = yaşama

Mü’min = Tanrı birliğine inanan 

Fa’lün   feûlün   feûlün

  /    /    .    /   /   .    /   /', 'Et  lûtf,  İlâhî  bir  aşka Nefs kandıran sahte çarktır. İnsan, gönülden de başka, Yaprakla toprak ve parktır. Mü’min biziz Hakka döndük Nur...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yaprak-toprak-ve-park-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ney Değil', 'ney-degil-mehmet-fatin-baki-an0t0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılık bir şey değil

Öldürür fürkat beni.

Her kamış boş ney değil

Durmaz üfler bûseni.

Gördüğün saz bir kamış

Gölde yelsiz kalmamış

Nağmesiz dert çalmamış

Durmaz üfler bûseni.

Hasretin sonsuz dibi

Bir garip Mehmet gibi

Yok ney’in bir sâhibi

Durmaz üfler bûseni.

Fâilâtün   fâilün

/ .   /   /   / .   /', 'Ayrılık bir şey değil Öldürür fürkat beni. Her kamış boş ney değil Durmaz üfler bûseni. Gördüğün saz bir kamış Gölde yelsiz kalmamış Nağmesi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ney-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talihin Böylesi', 'talihin-boylesi-fuad-mete-aymana-ut71p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birini sevdim sevdiği başka,

Mukadderat.Söylenecek söz yok fazla.

Konuk olacak gönül bulsun canan da,

Bizim hanemiz yine boş kalsın, 

Canım sağolsun, canan da.', 'Birini sevdim sevdiği başka, Mukadderat.Söylenecek söz yok fazla. Konuk olacak gönül bulsun canan da, Bizim hanemiz yine boş kalsın,  Canım ...', ARRAY['Türk Edebiyatı','Şiir','Fuad Mete Aymana']::text[], 8.5, '{"poet":"Fuad Mete Aymana","poet_slug":"fuad-mete-aymana","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/talihin-boylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaca ya', 'karaca-ya-fuad-mete-aymana-m0z8q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kapısını çaldım gönlünün 

Araladın usulca beni gördün.

Rüyalarıma kadar herseyimde sen

Ancak sana ait kalbime girsen

Bıraksam kollarına kendimi

Ayaklarının dibinde can verebilsem...', 'Kapısını çaldım gönlünün  Araladın usulca beni gördün. Rüyalarıma kadar herseyimde sen Ancak sana ait kalbime girsen Bıraksam kollarına kend...', ARRAY['Türk Edebiyatı','Şiir','Fuad Mete Aymana']::text[], 8.5, '{"poet":"Fuad Mete Aymana","poet_slug":"fuad-mete-aymana","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/karaca-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe', 'serce-musfik-saltik-h51cl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adam her şeyden bıkmıştı

Ona göre bu dünyanın cılkı çıkmıştı

İnsanlar riyakardı, her şey sanaldı

Artık ne soruların ne cevapların önemi vardı

Sevgide, aşkta koca bir yalandı

Ne gelecek için bir planı ne de umudu vardı

Böyle yaşamaktan ölmek revaydı

Evinin yakınında bir tepe vardı

Tepenin sonunda bir uçurum 

Uçurumun dibi  kayalıklar ve deniz 

Korkusu yoktu ölümden 

Gider oradan kendini atardı

Kararını verdi 

Koşar adım uçuruma yöneldi

Tam kenara gelmişti ki

Bir çalının dibinde 

Bir serçe yavrusu gördü

Tüylerini kabartmış korkuyla titriyordu

O çok korumasızdı ve yaşamak istiyordu

Minik gözleriyle adamdan yardım istiyordu

Adam ölmek istiyordu

Serçe yavrusu yaşamak 

Onu orada bırakıp atlasa uçurumdan

Yavru serçe bir kediye yem olacak

Düşündü adam  insanlara hep yardım etmişti

Hiçbir karşılık beklememişti

Şimdi bir serçe yardım isterken

O kendini düşünemezdi

Geberip gideceğim diye 

Serçeyi görmezden gelemezdi

Yavaşça  serçeyi  avucuna  aldı

Boynundan atkısını çıkarttı,  serçeyi sardı

Yıllardır insanların yıktığı adamı

Bir Serçe  ayağa kaldırdı

Bir yavru serçenin  bakışı

Bir adamın canını  kurtardı.

                                Mayıs 2004', 'Adam her şeyden bıkmıştı Ona göre bu dünyanın cılkı çıkmıştı İnsanlar riyakardı, her şey sanaldı Artık ne soruların ne cevapların önemi vard...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/serce-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdilerde', 'simdilerde-fuad-mete-aymana-7eodk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Konuşmaya başladığımda iki yaşımda 

Evdekiler de bir sevinç, bir neşe

Oysa ondan sonra ki tek çabam

Yeniden susmayı öğrenebilmek...', 'Konuşmaya başladığımda iki yaşımda  Evdekiler de bir sevinç, bir neşe Oysa ondan sonra ki tek çabam Yeniden susmayı öğrenebilmek......', ARRAY['Türk Edebiyatı','Şiir','Fuad Mete Aymana']::text[], 8.5, '{"poet":"Fuad Mete Aymana","poet_slug":"fuad-mete-aymana","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/simdilerde-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortada Sıçan', 'ortada-sican-fuad-mete-aymana-6x458', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğimi söylemeseydim eğer,

Ortada sıçanın ebedi ebesiydim.

Seninle karşılasam bir güzel seher,

Belki de her yolun avaresiydim.', 'Seni sevdiğimi söylemeseydim eğer, Ortada sıçanın ebedi ebesiydim. Seninle karşılasam bir güzel seher, Belki de her yolun avaresiydim....', ARRAY['Türk Edebiyatı','Şiir','Fuad Mete Aymana']::text[], 8.5, '{"poet":"Fuad Mete Aymana","poet_slug":"fuad-mete-aymana","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ortada-sican-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Boncuk', 'mavi-boncuk-haluk-ozdemir-gocp1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakıyorumda çok zenginsin

Mavi boncuk bol sende

Ver bakalım herkese

Otur şimdi etrafı gözle

Tutmayacağını bilerek

Verdiğin sözle

Kimler ne hale geldi izle

Şiirdeki kişi hayal ürünü olup gerçek

hayattaki benzeşmeler tamamen tesadüftür', 'Bakıyorumda çok zenginsin Mavi boncuk bol sende Ver bakalım herkese Otur şimdi etrafı gözle Tutmayacağını bilerek Verdiğin sözle Kimler ne h...', ARRAY['Türk Edebiyatı','Şiir','Haluk Özdemir']::text[], 8.5, '{"poet":"Haluk Özdemir","poet_slug":"haluk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mavi-boncuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylemem usta', 'soylemem-usta-zafer-zengin-etnika-nu3lp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'S ö y l e m e m

