INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakla samanı', 'sakla-samani-baykal-kaanalp-mghrs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'saklamalımıyım bilmiyorum

yiyemiyeceğim samanı

geçmelimiyim üzerinden

korkularımı yenemediğim köprünün

ya sevda bulaşırsa

