INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-huseyin-sigirtmac-4jw3x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldızlarda mekan arayan beyin,

Uçarken yerdeki hayvanı düşün.

Misafir bu beden toprak son evin.

Uzun değil ömür zamanı düşün.

Gülerken aklında kalsın ağlayan.

Darda kalmaz özü hakka bağlayan.

Çölde susuz kalmaz gönlü çağlayan.

Leyla aşkı ile Mecnun’u düşün.

Baharın içinde kışı unutma.

Gülerken gözdeki yaşı unutma.

Sığırtmaç kederli başı unutma.

Her canlıdan önce insanı düşün.', 'Yıldızlarda mekan arayan beyin, Uçarken yerdeki hayvanı düşün. Misafir bu beden toprak son evin. Uzun değil ömür zamanı düşün. Gülerken aklı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dusun-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-tolga-yildiz-a5lpd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unut bebeğim

Henüz yaşayamadığın hüznü

Ulaşamadığın denizi

Tutamadığın eli

Şimdi tut bebeğim

Sen rahat uyu bebeğim.', 'Unut bebeğim Henüz yaşayamadığın hüznü Ulaşamadığın denizi Tutamadığın eli Şimdi tut bebeğim Sen rahat uyu bebeğim....', ARRAY['Türk Edebiyatı','Şiir','Tolga Yıldız']::text[], 8.5, '{"poet":"Tolga Yıldız","poet_slug":"tolga-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bebegim-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdim Senden Değil', 'derdim-senden-degil-tolga-yildiz-60mah', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni bu gece anlama

Ama! 

Derdim senden değil bilesin

Zor geliyor bu düzen

Bu omzumda dönen çark

Her yanı kasvet bu duvarlar

İçime işliyor hüznün hünerli ellerinden

Derdim senden değil bilesin 

Bu koku beni delirtiyor!', 'Beni bu gece anlama Ama!  Derdim senden değil bilesin Zor geliyor bu düzen Bu omzumda dönen çark Her yanı kasvet bu duvarlar İçime işliyor h...', ARRAY['Türk Edebiyatı','Şiir','Tolga Yıldız']::text[], 8.5, '{"poet":"Tolga Yıldız","poet_slug":"tolga-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/derdim-senden-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Öyle Doluyum ki', 'sana-oyle-doluyum-ki-tolga-yildiz-pzztc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana öyle doluyum ki

