INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dere', 'dere-necmi-unsal-qtsqg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir  dere  kenarındayım.

Hep  kendimin  yanındayım.

Şırıl  şırıl  akıyor  dere.

Kendini  yere  sere  sere.

Kenarında  yemyeşil  otlar.

Üstünde  mavimsi  bulutlar.

Onda  denize  kavuşma  arzusu.

Ben  hâla  anasının  kuzusu.

Bölük  pörçük  umutlar.

İsyanı  hedef  komutlar.

Çobanın  ağzında  türkü  yanık.

Bülbüller  de buna  tanık.

Dinleyicisi  sadık  bir  köpek.

Yada  toprağı  tepen  köstebek.

Otların  arasında  bir  çiçek.

Yaprağa  tırmanan  böcek.

Dibek  tokmakla  dövülür.

Diğerleri  bakmakla  övünür.

Ben  güzelliklerin  seyircisi.

Tokmağı  vuranın  hık  deyicisi.

Biliyorum  dere  denize  gidecek.

Var  mı  benim  bir  yerim  sinecek? 

22 Mart 2004 Pazartesi, Danimarka-Køge  18.45', 'Bir  dere  kenarındayım. Hep  kendimin  yanındayım. Şırıl  şırıl  akıyor  dere. Kendini  yere  sere  sere. Kenarında  yemyeşil  otlar. Üstün...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dere-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Babacığım', 'gitme-babacigim-galip-sinecikli-3aced', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şuan hastanede yatan babam için.

Babacığım gitme,

bizi terketme,

Annemi, kardeşlerimi, beni,

torunlarını bırakma babacığım,

sensizlik çok koyar bize,

bizi bırakma babacığım,

bir doktorun ağzından,

iki dudağının arasından,

dökülecek sözlere mahkumuz şimdi,

odanın kapısında bekliyoruz hepimiz,

gitme babacığım,

gözlerimizdeki yaşların hatırına gitme,

kalbimizdeki sevgileri hisset,

sevenlerin için gitme babacığım,

bizi hüzünlere bırakma,

kelimeler düğümleniyor boğazımıza,

hıçkırıklar diziliyor sıra sıra,

sen bizi hiç üzmedin,

hiç ağlatmadın babacığım,

bu defa üzecekmisin,

ağlatacakmısın yoksa? 

üzme bizi babacığım, ağlatma,

''hak vaki olunca'' diyorsun,

sen neden bizi terkediyorsun,

''sıra bende'' diyorsun,

ecele teslim olma babacığım,

sen hiç teslim olmadın,

şimdi teslim mi olacaksın,

bizi öksüzmü bırakacaksın,

teslim olma babacığım,

gitme, bizi terketme,

sensizlik bize göre değil babacığım,

yalvarırım gitme, 

ben bu yükü nasıl kaldırırım,

nasıl metin olurum,

annemi, kardeşlerimi nasıl teselli ederim,

''sen güçlüsün'' diyorsun,

benim gücüm senin gidişinle tükenir babacığım,

daha hazır değilim babacığım,

bu yükü taşıyamam,

sakın gitme babacığım,

bizi terketme,

kloroform kokan koridorlarda bizi terketme,

bir damla göz yaşında,

sen varsın babacığım, 

seni kaybetmemek için ağlayamıyorum,

ağlatma beni babacığım,

seni kaybetmek istemiyorum,

ne olur babacığım gitme,

bizi böyle terketme,

sensizliğe hiç hazır değilim....

12.05.2004', 'Şuan hastanede yatan babam için. Babacığım gitme, bizi terketme, Annemi, kardeşlerimi, beni, torunlarını bırakma babacığım, sensizlik çok ko...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/gitme-babacigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Bir Örgü', 'hayat-bir-orgu-k-muran-esen-xr092', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elimde iki şiş,

Ve  kocaman  yün yumağı / dolaşık...

Örüyorum hayatı.

Önce  yüz: Geldin işte

Sonra ters: Gittin

Bir ters, bir yüz:

Bir dargınız / bir barışık.

Derken

Bitti  yumak

Kazak bitmeden...

Örecek yeni bir yumak

Yok ne yazık!', 'Elimde iki şiş, Ve  kocaman  yün yumağı / dolaşık... Örüyorum hayatı. Önce  yüz: Geldin işte Sonra ters: Gittin Bir ters, bir yüz: Bir dargı...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-bir-orgu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman tanı bana', 'zaman-tani-bana-ceylan-yarar-t9fyw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman tanı bana yarınlara

Benim sana tanıdığım gibi

Unutmamı bekleme bir anda

Kolay olmuyor silmek

Yaşananları geçmişi 

Bir anda bitirmek

Zaman tanı bana yarınlara

Açılmış yaraları sarmaya

Belki görmüyorsun ama

Ruhumda kanayan yaranın

Izlerini taşıyorum ben hala

Henüz kabuk bağlamadı daha

Zaman tanı bana yarınlara

Başta sadakat göster

Sevgi yüreğimizi besler

Sabırla ör güven ağını

Okşa bebek gibi uykumda

Merhem olsun yarama

Zaman tanı bana yarınlara....

                                    07.ocak.2004', 'Zaman tanı bana yarınlara Benim sana tanıdığım gibi Unutmamı bekleme bir anda Kolay olmuyor silmek Yaşananları geçmişi  Bir anda bitirmek Za...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaman-tani-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerimin İhaneti....', 'hayallerimin-i-haneti-hikmet-feridun-demir-tt9p7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlüm ateşlerde yanarken...

Hayallerimin ihanetini gördüm...

Sevdam kaldı benimle...

Nereye gidebirdi ki sevdam...

Yeri olan gönlüm olmadan...

Dost diye el uzattım,

Açtım gönlümü…

Şöyle bir baktı..

Gülümser gibi yaptı…

O da bulamadı, 

bende kendini….

Sırtını döndü…

Kendine hain, 

biteceği yere doğru..

kendine ihanette…

çekti gitti… 

02.03.2002 

Köln-Almanya', 'Gönlüm ateşlerde yanarken... Hayallerimin ihanetini gördüm... Sevdam kaldı benimle... Nereye gidebirdi ki sevdam... Yeri olan gönlüm olmadan...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayallerimin-ihaneti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçtu Gitti Geceye', 'uctu-gitti-geceye-zeki-ergin-pgcjs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir akşam üstü

uçtu gitti geceye

nereye 

nereye

yolboyu 

bir türkü söyledi geceye

sustu akan sular

sustu ağlayan yavru

_istanbul 1975

_sevgiliye isyan yt:haz04', 'bir akşam üstü uçtu gitti geceye nereye  nereye yolboyu  bir türkü söyledi geceye sustu akan sular sustu ağlayan yavru _istanbul 1975 _sevgi...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uctu-gitti-geceye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimizdeki çocuk', 'i-cimizdeki-cocuk-ahmet-turan-altunsu-bza9n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen, mahallemdeki haylaz çocuk; 

uslanmayacak mısın hâlâ? ..

gözlerin, mahallenin dilberi Gülbeyaz’ ın saçlarında,

Nuray öğretmenin bacaklarında,

zengin Mevlût  amcanın para dolu avuçlarında,

ceberut muhtar Cabbar’ ın kükremelerinde,

fettan komşu Perihan teyzenin dolgun  memelerinde! ..

uslanmayacak mısın hâlâ

sen, mahallemdeki haylaz,

yere göğe sığmaz,

yerinde durmaz çocuk? 

ah o çocukluk günlerimiz…

zaman su gibi akıp giderken,

değişen sadece bedenlerimiz.

değişmeyen; içimizdeki çocuk ve genlerimiz,

bir de, sessiz sedasız bırakıp gidenlerimiz! ..

ama hâlâ o muzip çocuktur

arada bir göz kırpan, o yaramaz…

ve yaşam; her adımda iz bırakan bir yolculuktur:

kıpır kıpır, dur durak tanımaz! ..

                                    11.05.2004 - Ankara -', 'sen, mahallemdeki haylaz çocuk;  uslanmayacak mısın hâlâ? .. gözlerin, mahallenin dilberi Gülbeyaz’ ın saçlarında, Nuray öğretmenin bacaklar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/icimizdeki-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kelebek gönül*', 'kelebek-gonul-kubilay-enginol-rz79v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benden sana yar olmaz

Boşuna uğraşma,bu kalp uslanmaz

Uçar gider,çiçek görünce

Kıpır,kıpır yerinde duramaz

Gözyaşları faydasız,gem vuramaz gönlüme

Layık olmalıydın,benim sevgime

Olayları bırak artık kaderine

Başka birisini bul,sevgine

Benden sana yar olmaz

Taştan yürek,yumuşamaz

Seni sevse bile söyleyemez

Pişman olur,yinede uslanmaz', 'Benden sana yar olmaz Boşuna uğraşma,bu kalp uslanmaz Uçar gider,çiçek görünce Kıpır,kıpır yerinde duramaz Gözyaşları faydasız,gem vuramaz g...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kelebek-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köhnemiş Dünyam', 'kohnemis-dunyam-mahmut-dogan-p2odh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba....

Gizli Ve sinsice Gelen Sessizlik

Kanayan Yaralarıma Tuz Basmaya 

Küflenmiş Anılarımı Hatırlatmaya 

Batmak Üzere Olan Gemiyi 

Kurtarmaya mı Geldin...

  Hadi Geldin Diyelim 

Ya Kararan Umutlarımı Paslanmış Hayallerimi

Tükenmiş Özlemlerimi 

Uykusuz Gecelerimi

Nasıl Nasıl Kurtaracaksın.

Peki Ya Terkedilmişliğimi

Beynimi Kemiren Düşüncelerimi

Taşlaşmış Yüreğimi 

Dahası Çürümüş Bedenimi

Hangi vefasıza Hangi Vicdansıza

Peşkeş Cekeceksin

 Beni Bu Hallere Sokan 

Bir Zalimden Başkasını Görmeyen Gözlerimi 

Kalem Tutmayan Ellerimi 

İleri Geri Gidemeyen Ayaklarımı 

Aklaşmış Dağınık Saçlarımı

Hangi Merhametsize, Hangi Kalpsize 

Ve Hangi Beni Görmeze Göstereceksin

 Talan Edilmiş Mutluluğumu

Kararmış Olan Bahtımı

Bir Türlü Dönemeyen Şansımı 

En Acısı, En Kötüsü

Unutamadığım Safa Aşkımı 

Hangi Sevgiliye Hangi Yüzsüze 

Ne Diye Anlatacaksın..

  Söylesene Bana 

Söyle Ne Zaman Olacak 

Nasıl Neyle Yaspacaksın

Kimlere Söyliyeceksin Bunları 

  Ne O Ağlıyormusun. Kaçıyormusun Yoksa

Yazık Bende Seni Dost Bilirdim 

Madem Beni Dinlemiyecektin 

Madem Sende Dayanamıyacaktın 

Madem Sen Dermanım Değildin 

Hangi Yüzle Hangi Vaatle 

Çaldın Yıllardır Açılmayan Kapımı

   Şimdi Çık Git 

Ve Öyle bir Git Kİ

Bir Daha Geriye Dönme Sakın 

Beni Bu Karanlık Köhnemiş 

Yapayalnız Dünyamda Bırak

Çek Git Çek Git..', 'Merhaba.... Gizli Ve sinsice Gelen Sessizlik Kanayan Yaralarıma Tuz Basmaya  Küflenmiş Anılarımı Hatırlatmaya  Batmak Üzere Olan Gemiyi  Kur...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Doğan']::text[], 8.5, '{"poet":"Mahmut Doğan","poet_slug":"mahmut-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kohnemis-dunyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm, kendimi anlamakla geçti!', 'omrum-kendimi-anlamakla-gecti-mutlu-ayar-2y22a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayatım bana sürekli 

anlaşılmazlıkları getirdi

bendeki bu akıl hep

anlaşılamayanları sevdi! 

anlaşıldım mı bilmem, 

anladığımı sevmedim

bütün ömrüm böylece

kendimi anlamakla geçti…

13:05', 'hayatım bana sürekli  anlaşılmazlıkları getirdi bendeki bu akıl hep anlaşılamayanları sevdi!  anlaşıldım mı bilmem,  anladığımı sevmedim büt...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/omrum-kendimi-anlamakla-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama nereye', 'ama-nereye-huseyin-cayikli-a4c3x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hadi kalk gidelim...yola koyulalım istersen sen sadece cekitini al...ben bavulama bir kaç anıyı ve sevdaları toparlayacağım..hadi kalk gidelim şimdi durmayalım buralarda...unutmadan masamda ki fotoğrafıda al yoldayken bir çerçeve alalım...yalnız saatleri unutmayalım beraber geçireceğimiz zamanlarda bir dost şefkatiyle sarılmak...hadi kalk gidelim artık biraz ağlayarak bu sınırları geçelim istersen moskova istersen paris herhangi başkent yada unutmak istersen başka bir şehir hadi kalk gidelim yüreğimizi alalım çok ama çok uzaklara bir adı kalmalı geriye unutulmuşlığun acısıyla hadi kalk gidelim...en çok sevdiğin filmide al yanına filde geçen sözü aşk hiçbir zaman pişmalık duymamaktır diyelim.hadi geç oldu kalk gidelim...hadi canım ruhum gidelim...ama nereye...', 'hadi kalk gidelim...yola koyulalım istersen sen sadece cekitini al...ben bavulama bir kaç anıyı ve sevdaları toparlayacağım..hadi kalk gidel...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ama-nereye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaküstü Yalanlar', 'ayakustu-yalanlar-sirma-mersin-vvrd9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayaküstü yalanlar oynardım, hayatla...

Çoğu zaman; 

Hayallerimde  oynardı, bizimle.

Masum ve saf düşüncelerimin seslenişi ile; 

Değişik değişik  kimlikleri giyinirdi, benliğim.

55''de çapkın bi adam, 18''de saf aşık, 35''den sonra yaşlandığını

hisseden bi kadın...  vdleri....

Her defasında...

Kendimden birşeyler  koyarak oynadım.

Zamanı hatırladıkca; 

Yalnızlığımın dizboyunu aşmıştı.

Nedensizliğe takılı hallerden, kurtulamamışken...

Çaresizlik hep boynumu bükmüştü.

Yarım kalmış mutluluğumun gölgesinde büyümemiş, bi sevginin gözyaşları 

ile paylaştım, hayatımı.

Ayaküstü yalanlarla oynardım, belkide kendimi.

Sahipsiz ruhumun zincirsiz esiriydi, kader...

10.05.04', 'Ayaküstü yalanlar oynardım, hayatla... Çoğu zaman;  Hayallerimde  oynardı, bizimle. Masum ve saf düşüncelerimin seslenişi ile;  Değişik deği...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayakustu-yalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Grev Türküsü', 'grev-turkusu-zeki-ergin-brif9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'indi şalterler

sustu makineler

şimdi vurulur davullara

söylenir türküler

umuttur ocaklarda pişen

bir yalımdır yüreklere düşen

şimdi onlardır

karanlığı yırtıp 

aydınlığa koşanlar

_istanbul 79

_sevgiliye isyan yt:haz04', 'indi şalterler sustu makineler şimdi vurulur davullara söylenir türküler umuttur ocaklarda pişen bir yalımdır yüreklere düşen şimdi onlardır...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/grev-turkusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeminler (Cséjthe''de güneş)', 'yeminler-cs-jthe-de-gunes-akin-akca-in52g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kan ter içinde kanayan yeminler

Öncesinde verilir gerçek sözler:

  (Like a goth - Welsh from Cardiff,

  Wins in a battle & beats Hitler.)  

''Hiç gelmeyecek-son''a yakın

Bir kendinden çeker-loko''motif:

 	(Hücum mangaları:

	Bir sürü ağır kamil manda

	Ve bu mandalar eder bir kaç fil; 

	Harmanlanır bu ürün, serpiştirilir

	Kendine: Serpiştirilir ''mangalar'':

	Ulaşılan bir tek mamut

	Öyleyse, toplandı..

	Bir tekinde 

bu antik-familyasının,

Bireysel güçler:

	Bu ortaya çıkan hücum mangası:

	Niceliğin kütle içindeki değer

	Kaybından

                Gerçeğe dönen bir şapka-çıkartılası.)

Hücum mangası, tedirgin sessizliğe; 

Yeminlerin kanamasından sonra:

Bir batmayan-çıkan’ı

İçindeki sessizliğe odaklanmıştı; 

(Dark Death Tower of Cséjthe Fortress for Báthory Erzsébet,

  Washed young g.s in blood, she!)  

	(Suddenly, for this energetic twillight,

	I''m outa sight)  

	Fakat, fakat! Uğursuzun denizinde …

                Dolunay yaratısı doğaçlamalar vardı,

                Engin çarpan fısılltısında dalgaların kayalıklara -

                Kararlılığında yükselişlerin, bir anlık! 

                Sonsuzluk var, Cséjthe''de ölüm süresizliği:

                ''Kütlesince şekillenmiş'' bir kara deliğin çevresi; 

                Okyanusun ortasında,

                Yampiri yengecinde deniz tabanının,

	Yemyeşilin uzantısı dallar kıpırdadı! 

-

açıklama:

Erzsébet Báthory: Karpatların karanlık kontesi

Dark Death Tower of Cséjthe: ''Cséjthe'' şatosunun ''karanlık ölüm kulesi''

Washed young g.s in blood: Bu lafla Erzsébet Báthory''nin kızları kan''da yıkadığını kastettim.1500''lü yıllarda yaşamış gerçek bir şahıs bu ve vampir olarak anılır

dizeler yer yer içeri giriyor

---

3. (son elden geçirilen)  versiyon

Kan ter içinde kanayan yeminler 

Öncesinde verilir gerçek sözler: 

(Like a got - Welsh from Cardiff? Or maybe, * & Hopdediks

  Wins in a battle & beats Hitler.)

''Hiç gelmeyecek-son''a yakın 

‘Bir kendinden çeker-loko''motif’: 

(Hücum mangaları: 

Bir sürü ağır kamil manda 

Ve bu mandalar eder bir kaç fil; 

Harmanlanır bu ürün, serpiştirilir 

Kendine: Serpiştirilir ''mangalar'': 

Ulaşılan bir tek mamut 

Öyleyse, toplandı.. 

Bir tekinde 

bu antik-familyasının, 

Bireysel güçler: 

Bu ortaya çıkan hücum mangası: 

Niceliğin kütle içindeki değer 

                Kaybından 

Gerçeğe dönen bir şapka-çıkartılası.)

Hücum mangası, tedirgin sessizliğe; 

Yeminlerin kanamasından sonra: 

Bir batmayan-çıkan’ı 

İçindeki sessizliğe odaklanmıştı; 

(Dark Death Tower of Cséjthe Fortress for Báthory Erzsébet, 

& Washed young g.s in blood, şşssh e! (!))

(Suddenly, for this energetic twillight, 

I''m outa sight)

Fakat, fakat! Uğursuzun denizinde … 

Dolunay yaratısı doğaçlamalar vardı, 

Engin çarpan fısılltısında dalgaların kayalıklara - 

Kararlılığında yükselişlerin, bir anlık! 

Sonsuzluk var, 

Cséjthe''de ölüm süresizliği: 

''Kütlesince şekillenmiş'' bir kara deliğin çevresi; 

Okyanusun ortasında, 

Yampiri yengeci’nde deniz tabanının, 

Yemyeşilin uzantısı dallar kıpırdadı!', 'Kan ter içinde kanayan yeminler Öncesinde verilir gerçek sözler:   (Like a goth - Welsh from Cardiff,   Wins in a battle & beats Hitler.)   ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/yeminler-csejthe-de-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süreç saf', 'surec-saf-akin-akca-mr6w4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün ışığında sabahların,cama vuran; 

Arttıran şiddetinde yağmurun, don''un; 

Sayısız gümbürtü fısıltıdan seven, 

Gaip varır durur, kişilikli yüzlere. 

Tekleşen fazlar, kesifleşen: 

Yün eğiren, tencere karıştıran; 

Kendini oya layan: Saftır hububat, 

Ekonomiden; hele nadas''larda oyalanan? 

    (‘Oyalanma’ *

    Ama; 

Çünkü Güç toplar böylece,

                        Kendini bilirse eğer) 

Yağmura minnet duyan bir kör cehalet; 

Varlık: Farkında olan, ey sefalet! 

Kervansaraylar, geçişken süreçler: 

Deme öyleyse; ''gelecek,gelecek! ''

-

*isim hali: gene de söyleyeyim.

3. kıta dizeler yer yer girintili çıkıntılı', 'Gün ışığında sabahların,cama vuran;  Arttıran şiddetinde yağmurun, don''un;  Sayısız gümbürtü fısıltıdan seven,  Gaip varır durur, kişilikli ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/surec-saf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuyudaki göl ve ''özüt-kız çocuğu''', 'kuyudaki-gol-ve-ozut-kiz-cocugu-akin-akca-4l4hz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kız çocuğu sarkıtılan içine,

Büyük çanaklar:Aman da! ...

Deli gömleği giydirseler,besbelli! 

Bir gün olmadı,Vakit...

Bu çanakların sonuncusundan geçeli! 

Bildiğimiz kan:Şırınga ediyorlar bu kıza:

Nitro gliserin dolaşıyor

Onun damarlarında; 

Hemen bu kız çocuğunun; 

Eski bir kuyu,yanı başında:

Bu kuyuyu daha denememişlerdi,

Çağırdılar nezaket eşliğinde

Karşı çıkmadı – faltaşı gibi - kız,

''Soğuk-tepeden bakmalar'' ile 

Sarkıttılar tek celse,bir kovada,

Şaşkınca kız bakıyordu yukarıya! 

Hava soğuktu,üç gün,72 saat

Kaldı orada,ayazdı hava; 

Bekledi,sarardı - karanlıkta; 

3. günün sonunda,yukarı çıkardıklarında,

Arındırma süreci sona ermiş! 

Kanı temizlenmişti elbet artık,işte orda! 

Ne bildiğimiz kan,ne nitro-gliserin; 

Kanı donmuştu,akmıyordu artık! 

Aldılar,ellerde taşıdılar

...Suçluluk duygusuyla karışık,

Ayaklarından bir ağaca astılar,

Nispeten cılız bir daldı,

Ordan sallandırdılar

Onun aksın diye kanı,

Ama akmadı,ip de tutmadı.

(Gözlerinde kalmıştı kuyunun yüzgeci,

Göller üstünde üçüncü gece uyandırılmıştı) 

Yine aynı gölde uykuya dalmamış mıydı?)

Yere düştüğünde gözleri açıldı! 

Bazı vücutlar gördü koşan tepelerden eteklere,

‘Kuyunun,gözlerine sinen-suları’ndan akis’ :

Panik ile sabitkar,darağacıyla koşanlar 

--

Özüt: Anıt,dikit,sarkıt gibi özellikler gösteren öz bir oluşum anlamında kullandım', 'Kız çocuğu sarkıtılan içine, Büyük çanaklar:Aman da! ... Deli gömleği giydirseler,besbelli!  Bir gün olmadı,Vakit... Bu çanakların sonuncusu...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kuyudaki-gol-ve-ozut-kiz-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efkarlı Kervanlar', 'efkarli-kervanlar-nalan-kazazoglu-jvvsu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağıradım geçiyor yüreğimdeki çöllerden,

Uzun uzun efkar yüklü kervanlar

Benim de develerin de gönlü kırık...

Kum denizine son ışık yavaşça dalıyor,

Sayfalar dolusu kum rüzgarla savruluyor

Bitmek üzere yolculuk...', 'Ağıradım geçiyor yüreğimdeki çöllerden, Uzun uzun efkar yüklü kervanlar Benim de develerin de gönlü kırık... Kum denizine son ışık yavaşça d...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/efkarli-kervanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Göklerde', 'yuregim-goklerde-nevin-kurular-3fxrp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günü gelip öldüğümde,

Yüreğimi gömmesinler bedenimle

O''nu kuşlara bıraksınlar

Kuşlar yüreğimi gagalasınlar

Sonra,

uçsunlar ki göklere

Bulut bulut dolaşsınlar......

Ne güzel işte

Yüreğim göklerde.', 'Günü gelip öldüğümde, Yüreğimi gömmesinler bedenimle O''nu kuşlara bıraksınlar Kuşlar yüreğimi gagalasınlar Sonra, uçsunlar ki göklere Bulut ...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yuregim-goklerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Benim Can Yıldızım', 'gel-benim-can-yildizim-reyhan-sur-lbri9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yıldızlı gecelerini özledim gözlerinin

dudaklarındaki bahar çiçeklerini

efil efil esişini nefesinin

sarılışıp sıkıca biz koktuğumuz günleri

bak güneş sönmüş

ay da yok

kör karanlıkta ışır mı gözüm

devinsin artık yürek

çözülsün us

de kımıldan sevdiğim

yansın temmuz

sultası geçti artık suskularımızın

söktüm tel örgülerini pencere pervazının

dar geliyor çerçeve ca(n) m çiçeklerime

gel benim biriciğim

gel benim can yıldızım

yine sevdiğini söyle', 'yıldızlı gecelerini özledim gözlerinin dudaklarındaki bahar çiçeklerini efil efil esişini nefesinin sarılışıp sıkıca biz koktuğumuz günleri ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-benim-can-yildizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KuŞ DiLi BiLiRmiSiN?', 'kus-dili-bilirmisin-mine-ozdemirtas-6zpl2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangi Dil de konuşsam anlavsın ki? 

Kavşı davda biv tıvtıv avaçlavı yıyov kıtıv kıtıv

Devdim dünyadan büyük...Oku beni satıv satıv

............................................................................(Hamili kart yakınımdır) 

Dilim dönmüyov işte

Başka biv şekilde

Devdimi söylemeye

Ölümlevdeyim hev gece

hasvetinle bin kevve

Yanan biv kov halinde

Gitmek düvtüsü içimde.

ama gidemiyovum

gidemiyovum işte

Hiç biv yeve

Sen vuhumda..sen tenimde

Sen hev biv yevimde.

kanıyovsun çıbanlav halinde.

Doktovlar çave olamadı devdime.

Ama ben biliyovum ki

İlacım sende.

Yüzümü güldüvüvevecek

Dudaklavından dökülecek

O sihivli biv tek kelime.

haydi biv tanem... söyle

Yaşamamı istıyovsan evev

gecikmeden

''seni seviyovum'' de.

(ah serçe...ah.....ne kadar yakınımda ve ne kadar uzağımdasın./ hamili  kuş yakınımdır.... tanırmısın?) 

12/05/2004.... kartal', 'Hangi Dil de konuşsam anlavsın ki?  Kavşı davda biv tıvtıv avaçlavı yıyov kıtıv kıtıv Devdim dünyadan büyük...Oku beni satıv satıv ............', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kus-dili-bilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dersin', 'ne-dersin-huseyin-sigirtmac-im3fb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakıp gözümdeki yaşa ağlama.

Ya içime akan yaşa ne dersin? 

Efkarla yanarsın kızla oğluma.

Yuvası dağılan kuşa ne dersin? 

Kimlere mekandır fani bu dünya.

Ne yiğitler geldi geçti hani ya? 

Dünya gözü ile gördün beni ya.

Saltanatı sönen başa ne dersin? 

Düşünüp ışığa ışık tutanlar.

Arıya kahredip zehir yutanlar.

İnsanlığa kafa tutan Sultanlar.

Dolu yaşadı ya boşa ne dersin? 

Bazen efkar olur bayramla düğün.

Geçmiş tecrübedir gün varsa bu gün.

Sığırtmaç dönmeyi hedef gördüğün.

Azrail’e kucak köşe ne dersin?', 'Bakıp gözümdeki yaşa ağlama. Ya içime akan yaşa ne dersin?  Efkarla yanarsın kızla oğluma. Yuvası dağılan kuşa ne dersin?  Kimlere mekandır ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-dersin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapayım', 'ne-yapayim-hifzi-ozbekmez-5wnvk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstemem köşkü sarayı

Ne beyazı ne karayı

Gönlümdeki bu yarayı

Sen olmazsan ne yapayım

Arıda petek balını

Yeni açmış gül dalını

Benim perişan halimi

Sen olmazsan ne yapayım

Gözlerimdeki yaşımı

Sana feda bu başımı

Deli gönülle işimi

Sen olmazsan ne yapayım

Damarımda akan kansın

Sen gönlümde tek canansın

İster bütün dünya yansın

Sen olmazsan ne yapayım

İstemem güneşi ayı

Ne amıca nede dayı

Verseler bana dünyayı

Sen olmazsan ne yapayım

Bu gönlümün tek sevdiği

Kalmaz ki sensiz dirliği

Ozanlığı şairliği

Sen olmazsan ne yapayım

Latif sakınır gözünden

Çıkarmaz ki hiç sözünden

Ayırmaz iki kızından

Sen olmazsan ne yapayım', 'İstemem köşkü sarayı Ne beyazı ne karayı Gönlümdeki bu yarayı Sen olmazsan ne yapayım Arıda petek balını Yeni açmış gül dalını Benim perişan...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ne-yapayim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esinti', 'esinti-mehmet-fatih-kose-y0a2n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şükürler, keşkeler yağdı durmadı,

Bazen mesut oldum, bazen de pişman.

Başka birisine gerek kalmadı,

Ben bana olmuşum en büyük düşman...............', 'Şükürler, keşkeler yağdı durmadı, Bazen mesut oldum, bazen de pişman. Başka birisine gerek kalmadı, Ben bana olmuşum en büyük düşman...........', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Köse']::text[], 8.5, '{"poet":"Mehmet Fatih Köse","poet_slug":"mehmet-fatih-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/esinti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulaklarım Nasıl Delindi / anı', 'kulaklarim-nasil-delindi-ani-k-muran-esen-3i869', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Henüz sekiz -dokuz yaşımdaydım. Köyümüze gelen çerçiciden iki tane bilezik, bir çift de küpe almıştım bir gün. Ama kulaklarım delik değildi. Oysa ben, küpeleri takmaya can atıyordum. O halde, kulaklarımın delinmesi gerekiyordu. Bunun da çaresi vardı. Köyümüzde bir Fatma Ninemiz vardı. Onun bilmediği yoktu. Bilge bir kadındı. Herhangi bir sıkıntısı olan, hemen Fatma Nine’ye koşardı. Turşunun nasıl kurulacağı, asma yapraklarının nasıl salamura yapılacağı ve bu işin püf noktaları hep Fatma Nine’ye sorulurdu. Hastalanan hayvanlara ne içirilmesi gerektiğini bile bilirdi. Gençlere o akıl verir, yanlış yapanlara o nasihat ederdi. Nazara gelenleri okur, haylazlık edenlerin uslanması için dualar ederdi.

İşte bu Fatma Nine kulak da deliyordu. Biz çocuklara yaklaşımı da çok iyiydi. Bazı ihtiyarlar gibi çocukları kovalamıyor, bizi azarlamıyordu. O nedenle Fatma Nine’yi çok seviyordum. Hem bir gün bana paçalı don(pijama)   bile dikmişti. 

Ben de ona gittim, kulaklarımı deldirmek için. Bütün cesaretimi toplayıp, kurbanlık koyun gibi dizlerine yatıverdim.Aslında çok korkaktım.Ama güzel olmak için her şeye razıydım. Bir an önce küpelerimi takmak istiyordum. Küpelerle çok güzel bir kız olacağımı biliyordum(!) .Fatma Nine kulak mememi tuzla ovdu uzun süre. Önce gıdıklandım, sonra hissetmez oldum. Ovdu ovdu, ucunda iplik takılı olan iğneyi kulak mememe aniden batırıverdi. Ve ipliği kulak mememden geçirdi.

Kulağımdaki acının diğer ucunu ayak parmaklarımda hissettim birden, ürperdim. Saniyede aynı acı,vücudumun en uç noktasına ulaşıvermişti. Canım yanmıştı, ama hiç belli etmedim. İpliğin iki ucunu birleştirip düğümledi Fatma Nine. İşte kulağımın biri delinmişti. Çaresiz ikincisi de delinecekti. Tek küpeyle gezemeyeceğime göre, sabretmeliydim. Canımın yanmasına razı olmalıydım. Zaten ben sabırlı bir çocuktum. Annem benim için, “Benim kızım Ramazan ayında doğduğu için sabırlı,” derdi. Ben de annemi hiç yalancı çıkarmazdım.

Aynı yöntemle ikinci kulağımı da deldirdim. Köyde çocukların kulakları hep böyle deliniyordu. Bildiğim, gördüğüm veya duyduğum başka bir yöntem yoktu. Çok canım yandı ama hiç ağlamadım. Kendimi tuttum.

Birkaç gün acıdı kulaklarım; gece kulaklarımın üstüne yatamadım. Güzel olmak için, bu kadar acıya katlanırdım, katlandım da. ”Antidot” diye bir melhem bulunurdu evimizde. Yaramız,beremiz eksik olmazdı hiç. Hele erkek kardeşimin. İşte bu Antidot bizim kurtarıcımızdı. Annem o melhemden sürdü kulaklarıma. 

Kulaklarım iyileşince, çerçiciden aldığım küpeleri taktım. Bana çok yakışmıştı(!) .Çok güzel bir kız olmuştum(!) . Gidip gidip, aynaya bakıyordum. İyi ki kulaklarımı deldirmiştim. Babam bana bir müddet sonra altın küpe aldı. Bir de altın bilezik alsaydı tamam olacaktı. Çünkü çerçiciden aldığım bileziklerin altını zamanla silinmiş, geriye gümüşü kalmıştı(!) . Altın sarısı bileziklerim, teneke gibi olmuştu.

Ah o çerçici bir daha gelse! 

........................................................................................................................

O çerçicileri, altından gümüşe dönen bileziklerimi, bana çok yakışan küpelerimi ve en önemlisi, çocukluğumu o kadar özledim ki!', 'Henüz sekiz -dokuz yaşımdaydım. Köyümüze gelen çerçiciden iki tane bilezik, bir çift de küpe almıştım bir gün. Ama kulaklarım delik değildi....', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kulaklarim-nasil-delindi-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Hatırına...', 'kalbimin-hatirina-i-brahim-ethem-bingul-fsxfx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Böyle dememeliydi,

Böyle etmemeliydi,

Beklemiyordum ondan

Böyle gitmemeliydi...

Günler sonra göründü

Kalbim sende süründü

Yabani bir gül müydü? 

Böyle gülmemeliydi....

Kalbimi terk eyledi

Gülüşü kahreyledi

Oh olsun! Der gibiydi

Artık dönmemeliydi...

Aklım isyan halinde

Savaşın eşiğinde

Güçlü silah elinde

O zalim çekmeliydi...

İçimdeki sahibim,

O viran olan kalbim

Bir ana kalbi gibi

Dedi: Affa talibim...

Düşüncem mağlup kalbe

Yenildi bu sefer de

Üstünlük affedende

Hiddetim sönmeliydi...

Bir anda aklım döndü

Kızgın ateşim söndü

Onun hatası dündü

Af yüzü görmeliydi...

Kalbimin hatırına,

Ben nelere katlandım

Kalbimin hatırına

Gel,seni bağışladım...

Gel artık barışalım

Aşk ile sarılalım

Bir sarmaşık olalım

Kalbimin hatırına...', 'Böyle dememeliydi, Böyle etmemeliydi, Beklemiyordum ondan Böyle gitmemeliydi... Günler sonra göründü Kalbim sende süründü Yabani bir gül müy...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kalbimin-hatirina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefine', 'serefine-nesrin-ozyayci-zgzbi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şişe kırmızı şarap 

Yarım paket sigara

Yaşadıklarıma

Yaşadıklarına

Yaşanacaklara

Yaşanmışlara

Yaşanması gerekenlere

Ve yaşama

Gece bitinceye değin

Tüm yaşamların şerefine...

Gaziantep

2002', 'Bir şişe kırmızı şarap  Yarım paket sigara Yaşadıklarıma Yaşadıklarına Yaşanacaklara Yaşanmışlara Yaşanması gerekenlere Ve yaşama Gece bitin...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/serefine-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet Mutlu Olduğun Yerdedir!', 'cennet-mutlu-oldugun-yerdedir-ali-aydin-brmzt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş senin gözlerinden doğacak yarın,

Yüzme bilmediğin okyanuslarda,

Deniz kestanelerine basacaksın,

Yüreğini kanatacak her haykırışında.

Ah aşkım bedenine sevdamızı işleyeceğim dudağımla,

Biliyorum ki zaman kısır kalacak.

Gözlerime baktığında mevsimler birbirine karışacak,

Nilüferler açacak kış ortasında bedeninde.

Sana her dokunuşumda yeni bir şey keşfedeceksin, hayata dair.

Ve, üzerindeki prangaları parçalayıp, 

ADA’mıza koşacaksın çırılçıplak! 

Doğan güneş görecek gizli gizli seviştiğimizi,

Okyanusun köpükleri yorganımız olacak.

Kızgın mızrağım kalbine saplanınca içindeki fırtına dinecek,

Sonsuz huzuru bulacaksın kollarımda...

27.04.2004', 'Güneş senin gözlerinden doğacak yarın, Yüzme bilmediğin okyanuslarda, Deniz kestanelerine basacaksın, Yüreğini kanatacak her haykırışında. A...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydın']::text[], 8.5, '{"poet":"Ali Aydın","poet_slug":"ali-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cennet-mutlu-oldugun-yerdedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzle,!', 'i-zle-akin-akca-68b6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar Excalibur’u tutsak da? 

.. Bu kaya, o var ya! 

Excalibur, onu n''apalım,n''apalım? 

Uzanan’ın uçurum mesafesinde azalma mı var? 

Hem kendini arttıran, 

özüt-arıtkan-okyanus’a? 

Sanki bir şey istemiyor? 

Sanki bir şey onun içini kemiriyor? 

Sanki bir uçurum yok! .. 

Sanki bir yer de yok? ? 

Sanki bu kayalıklar kaya değil, fazla granit.. 

Sanki bu kayalıklar, sen! ! ! 

Cibinlik, rüzgarda uçuşturduğun; 

o, uçurum kenarında! aman, uçma! 

Bıçak sırtı-oynaşçısı, oynak-sürücü’s ü! 

Senin ipekten giysin ve dokusu onun senin tenin! 

Sanki uçurumdan düşen de o, 

uçurumu devam ettiren de. 

Kafam atıyor! 

Şelale nerde düşer? 

ya da topraktan ebemkuşağına yağmur boşanır 

Ay Dede’yi oralarda göründüğünde, 

bunu.. 

gökyüzünde, i z l e! 

- 

açıklama: 

Excalibur: Kral Arthur efsanesinde, Arthur''un efsanevi kılıcı.(Excalibur bir kayada saplıdır ve onu kimse çıkaramamıştır.Arthur çıkarır.)', 'Ne kadar Excalibur’u tutsak da?  .. Bu kaya, o var ya!  Excalibur, onu n''apalım,n''apalım?  Uzanan’ın uçurum mesafesinde azalma mı var?  Hem ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/izle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BeNiMLe EvLeNiRmiSiN ?', 'benimle-evlenirmisin-mine-ozdemirtas-qrwf4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolun yokuş

''Soluk soluğa kalmak'' deyimini bilir misin? 

............................................................................ (Ya ev de Yoksan? ...) 

Nerdesin? 

Dilimde kocaman bir soru ve

elimde

boynu bükük bir tutam menekşe

düştüm ocağına.

Epeyce bir zamandır

kapındayım işte.

uzun uzun çaldım zili

yetmedi... defalarca seslendim sana

öyle ki... kesildi nefesim.

Neden açmıyorsun kapıyı? 

Neden geri dönüyor sesim.? 

Kedi neden bahçede? 

Ve neden perdelerin kapalı senin? 

aklıma gelen başıma gelmesin

Yoksa.....

Yoksa evde değil misin? 

Hay allah...

aksilik işte

hevesim gursağımda......

sorum cevapsız mı kalacak? 

Hayır

buna onayım yok..........

Ben şimdi burada sormuş olayım.

sen cevabı eve döndüğünde verirsin.

''Eğer sence de uygunsa

Bir ara...

Benimle evlenir misin? ''

(ah serçe ah.....uzansam tutacağım sanki  / korkarsın biliyorum.. laf mı şimdi benim ki? ....) 

12/05/2004  kartal', 'Yolun yokuş ''Soluk soluğa kalmak'' deyimini bilir misin?  ............................................................................ (Ya ev...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/benimle-evlenirmisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimi', 'sevgimi-nesrin-ozyayci-89zlp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçime yazdım, derin bir mahzene gömdüm

Yıllansın diye, sevgimi.

Yalnızlığıma yazdım kavgam olsun diye,

Yüreğime işledim nakış nakış

Göklere yazdım bulut bulut,

Şafaktaki ilk ışığa yazdım seni,

Sonsuzluğa adadım adını

Yaşama adadım sevgini,

Yazdım her noktaya, her değere.

Bundan doyamıyorum, acılara,

Hüzünlere, umutsuzluklara,

Yıldızlarla yazdım gökyüzüne adını,

Dolunaya okuttum en karanlık gecelerde...

Gaziantep

2001', 'İçime yazdım, derin bir mahzene gömdüm Yıllansın diye, sevgimi. Yalnızlığıma yazdım kavgam olsun diye, Yüreğime işledim nakış nakış Göklere ...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz Gece', 'kimsesiz-gece-nesrin-ozyayci-52kol', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tren istasyonunda üşümüş bir kadın

Saat sabahın üçü,

Dağılmış, yalınayak duygular

Çaresiz uğurlamalar arasında,

Elveda diyordu elleri.

Tek başına, yalnız, yapayalnız

Ağlamaklı, hüzün doluydu bakışları

Karanlık örtüyordu gözyaşlarını

Geçmişten kanayan yaralarıyla

Yaşadığı belliydi, nefesinden,

Yapayalnız, sahipsiz bir istasyonda

Üşüyordu, bu ağustos sıcağında.

Gaziantep

2000', 'Tren istasyonunda üşümüş bir kadın Saat sabahın üçü, Dağılmış, yalınayak duygular Çaresiz uğurlamalar arasında, Elveda diyordu elleri. Tek b...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kimsesiz-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-zeki-ergin-cmpgb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hani nefretin sevgiye 

dönüştüğünü muştulayacaktı

ilk doğan güneşle

ilk öten horoz

hani zamanın bir noktasında duracaktı saatler

ve sevenler için kalkacaktı

şarap dolu kadehler

ve de ağlamayacaktı artık 

ve de ölmeyecekti bebekler

umut neden güneşe giden yolda yorgun

kara düşüncelere neden tutsak ak günler

yarına bel bağlayamıyorum

yarınlardan korkuyorum

nedendir söylenmez özgür türküler

özgür çağrışımlar neden suskun

_köz yt:73

_Çorlu Ekspres sayı:374410oca75

_dağlara ver sırtını yt: haz09', 'hani nefretin sevgiye  dönüştüğünü muştulayacaktı ilk doğan güneşle ilk öten horoz hani zamanın bir noktasında duracaktı saatler ve sevenler...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/neden-827-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sûr gün eş''im', 's-r-gun-es-im-sair-ahrazi-k0q3h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakmayın güneşin güleç yüzüne,

Zülfüne ak düşen yıllara benzer.

Biçare yaslanmış ufkun dizine,

Teselli arayan kullara benzer.

***', 'Bakmayın güneşin güleç yüzüne, Zülfüne ak düşen yıllara benzer. Biçare yaslanmış ufkun dizine, Teselli arayan kullara benzer. ***...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sur-gun-es-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Denemesi-1', 'mutluluk-denemesi-1-atila-gunal-6g5aq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluk kuşu konmuş pencereme

Rengarenk ama yaralı

Sesi en güzel bestelerden da güzel

Yalnızlığın atmacasından kaçıyor besbelli

Tam camı açmıştım ki

Düştü kuşum...

Hışımla gelen atmaca

Girdi camdan içeri...

Konmuş karşıma

Dehşet ve zevkle benimle artık...', 'Mutluluk kuşu konmuş pencereme Rengarenk ama yaralı Sesi en güzel bestelerden da güzel Yalnızlığın atmacasından kaçıyor besbelli Tam camı aç...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mutluluk-denemesi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Denemesi-2', 'mutluluk-denemesi-2-atila-gunal-xusu7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutluluk serçesi

Konmuştu pencereme

Ne kadar da nazik

Ne kadar da kırılganmış meğer

Aldım elime zevkle

Benimle kalsın istemiştim hep oysa

Okşarken hazla

Haz mı çok geldi

Mutluluk mu bana

Anlayamadım...

Avuçlarımda cansız kalıverdi...', 'Mutluluk serçesi Konmuştu pencereme Ne kadar da nazik Ne kadar da kırılganmış meğer Aldım elime zevkle Benimle kalsın istemiştim hep oysa Ok...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mutluluk-denemesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramızda Cam Perde', 'aramizda-cam-perde-semra-dereli-6v7uy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ARAMIZDA CAM PERDE

Dünü unut

Yarına geç mi kaldım? 

Tüm saatler sustu,

Sevda kalelerim düştü

Tutsağınım! 

Korkak bir güvercin kanatlandı geçmişe

Seni yalansız, yasaksız sevdim...

Bırak kırayım; aramızda cam perde! 

Sana geç kalmış bir aşkım...', 'ARAMIZDA CAM PERDE Dünü unut Yarına geç mi kaldım?  Tüm saatler sustu, Sevda kalelerim düştü Tutsağınım!  Korkak bir güvercin kanatlandı geç...', ARRAY['Türk Edebiyatı','Şiir','Semra Dereli']::text[], 8.5, '{"poet":"Semra Dereli","poet_slug":"semra-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aramizda-cam-perde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmeyen', 'bilinmeyen-semra-dereli-cd2ko', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİLİNMEYEN

Bir güvercin uçurdum

Sabah güneşinde

Kılıç yarası açmış

Nil yeşili gözlerine.

Bir bilseydin...

Tomurcuklar düşer miydi

Dallarına? 

Bir renk verir miydin

Gökkuşağından

Umutlarıma? 

Bir bilseydim...', 'BİLİNMEYEN Bir güvercin uçurdum Sabah güneşinde Kılıç yarası açmış Nil yeşili gözlerine. Bir bilseydin... Tomurcuklar düşer miydi Dallarına?...', ARRAY['Türk Edebiyatı','Şiir','Semra Dereli']::text[], 8.5, '{"poet":"Semra Dereli","poet_slug":"semra-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilinmeyen-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Uzak', 'senden-uzak-semra-dereli-hn0v9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SENDEN UZAK

Gecenin gizi içimde

Damarlarımdaki kan

Çekiliyor.

Senden uzakta hüzünlüyüm.

Gülüşü, bakışın,

Alnına düşen saçların

Gözlerimde bir perde

Hiç açılmıyor...

Senden uzakta sevgisizim.

Bu gecede sabahı buluyorum.

Nefes almak dahi zor

Teninin kokusu biraz uzaklaşsa...

Nankörlük oluyor kendime

Senden uzakta demek

Mesafeler daima var

Yeter ki, uzanan yollar olsun.

Senden uzakta, her an seninleyim.', 'SENDEN UZAK Gecenin gizi içimde Damarlarımdaki kan Çekiliyor. Senden uzakta hüzünlüyüm. Gülüşü, bakışın, Alnına düşen saçların Gözlerimde bi...', ARRAY['Türk Edebiyatı','Şiir','Semra Dereli']::text[], 8.5, '{"poet":"Semra Dereli","poet_slug":"semra-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/senden-uzak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuzguni Siyahlar', 'kuzguni-siyahlar-semra-dereli-8ggb8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KUZGUNİ SİYAHLAR

Ayrılık vaktini uçurdu sabahın

İlk ışıkları penceremden içeri.

Ellerimle yolcu etmek olmasa! 

Gözlerimde ağlamaksı bakışlar

Yüreğimdeki sessiz duygulanışlarla

Söyleşmekte veda ederken...

Gidişin hayırlı olsun, dönüşün tez

Böyle garip bakarım kapı

Ardından, olsun! 

Bilirsin ne zaman sensiz kalsam

Parça parça olur yüreğimin tenhaları

Kuzguni siyahlara bürünür umutlarım.

Sabah güneşi içimi ısıtıyor

Uyuyamadım ardından,

Tedirgin bekleyişler ellerimde.

Yaprak yaprak olmuş zaman

Sonbahar gölgesinde düşüyor

Yaşlı bir çınarın eteklerine.

Yaşamak istiyorum nefesinde

Yaprak dökümü bitmiyor!', 'KUZGUNİ SİYAHLAR Ayrılık vaktini uçurdu sabahın İlk ışıkları penceremden içeri. Ellerimle yolcu etmek olmasa!  Gözlerimde ağlamaksı bakışlar...', ARRAY['Türk Edebiyatı','Şiir','Semra Dereli']::text[], 8.5, '{"poet":"Semra Dereli","poet_slug":"semra-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kuzguni-siyahlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Üzerine', 'sensizlik-uzerine-semra-dereli-fsjcv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SENSİZLİK ÜZERİNE

Bu gece mum kokusu var

Sensizlikte.

Sensizlik, eriyen aşkımı

Özümsüyor.

Hiçbir zaman anlayamadı

Sensizlik

Onunlayken bile nasıl

Seni sevebildiğimi.

Oturup sensizlikle

Seni çekiştirdik.

Haklıydım şimdiki kadar

Sen, sensizlikten

Daha güzeldin.

Bilemedin,

Seni

Sensizlikle aldatırken bile

Nasıl mutsuz olduğumu.', 'SENSİZLİK ÜZERİNE Bu gece mum kokusu var Sensizlikte. Sensizlik, eriyen aşkımı Özümsüyor. Hiçbir zaman anlayamadı Sensizlik Onunlayken bile ...', ARRAY['Türk Edebiyatı','Şiir','Semra Dereli']::text[], 8.5, '{"poet":"Semra Dereli","poet_slug":"semra-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sensizlik-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Güler Misin Ağlar Mısın.?', 'guler-misin-aglar-misin-hasan-basri-kale-jeg13', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ağlayanı birine

koydum 

güleni diğerine

kefenin..

gülene 

ağlayan kadar

dara koymak gerekti

dengesi bozulmasın 

diye terazinin..

terazi hep dengede.', 'ağlayanı birine koydum  güleni diğerine kefenin.. gülene  ağlayan kadar dara koymak gerekti dengesi bozulmasın  diye terazinin.. terazi hep ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guler-misin-aglar-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim', 'seni-sevdim-sair-muhsin26-nnigj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevdim be güzelim

Ne yapayım sevdim işte

Acılarını,kızgınlıklarını,nefretini

Sevdim be güzelim ne yapayım işte

Çıkmazlar içine girdiğimde

Nefreti sürekli söylediğinde

Yaşamı birlikte götürdüğümüzde

Sevdim be güzelim ne yapayım işte

Kızgınlığım serseri kurşun misali saplandığında

Tam yüreğimi parçaladığında

Evde bekleyipte ağladığımda

Sevdim be güzelim ne yapayım işte

Sen küçücük bir kuşsun inan kanadın kırık

Bense azrailim hep ölüme alışık

İşimi yapamıyorum inan senin yüzünden

Sevdim be güzelim söyle ne yapayım ben

Ağlamak sızlamakla geçmezki zaman

Ağaran saçları suçlar bak hazan

Sen versin ya hatatta benimle her an

Sevdim be güzelim söyle ne yapayım ben

Alevin kırmızısı gibi sevdim yürekten

Közlenmiş odun gibi yok olup gitsem

Yanarak eriyip tükenip gitsem

Sevdim be güzelim söyle ne yapayım ben

Yaşamlar sunulmuş istemesekte

Çarpışmış hayatlar tam içimizde

Meyvesi olmuş bak günümüze 

Sevdim be güzelim söyle ne yapayım ben', 'Seni sevdim be güzelim Ne yapayım sevdim işte Acılarını,kızgınlıklarını,nefretini Sevdim be güzelim ne yapayım işte Çıkmazlar içine girdiğim...', ARRAY['Türk Edebiyatı','Şiir','Şair Muhsin26']::text[], 8.5, '{"poet":"Şair Muhsin26","poet_slug":"sair-muhsin26","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seni-sevdim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galiba sen....', 'galiba-sen-yolcu-toprak-k6ymy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu gece yine yanlızım,başkalarıyla olduğunu bilerek

caddeler ıslanmış yağmurdan,

ağlıyorum,canımdan koparken,buz gibi titrerken 

bir sigara ve yanındaki,en büyük keyfin....

benim içim dışım ağlarken 

yürüyorum şimdi sizin sokakta,sesin geliyor kulağıma 

sen beni görmüyorsun belkide 

benim gözüm kan çanağıyken,nasıl seviyorum bilmiyorum

şarkılar kulağımda,sessizce çalıyor

onlar bile kıyamıyor bana,senin bana kıydığın gibi

sabah olunca yüzüme gülümsüyorsun 

akşamları masum gibi sanki,çekip gidiyorsun 

umursamıyorsun anlaşılan, hayatı yaşamak istiyorsun 

ama ben seni her görüşümde,fena oluyorum 

akşam olunca ona gideceksin diye,

ya sen gideceksin buradan 

                                               (ki ben sana yinede kıyamam) 

yada ben gideceğim            (ki görünen o) 

beni sevecek birini bulana kadar unutamam seni 

yazamıyorum artık ellerim titriyor,tükeniyorum

bu gece de uyku yok anlaşılan,

şimdi seni düşünmeye gidiyorum,sen muhabbet içindeyken 

bir sigara daha yak benim için,

her nefeste biraz daha öldüğümü hissederim yattığım yerden 

yastığım gözyaşlarımla  ıslanır,

uykun gelince yat,sabah erken kalkacaksın 

benim ben seni düşünmeye gidiyorum

sabah ezanına daha çok var', 'bu gece yine yanlızım,başkalarıyla olduğunu bilerek caddeler ıslanmış yağmurdan, ağlıyorum,canımdan koparken,buz gibi titrerken  bir sigara ...', ARRAY['Türk Edebiyatı','Şiir','Yolcu Toprak']::text[], 8.5, '{"poet":"Yolcu Toprak","poet_slug":"yolcu-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/galiba-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Özlem...', 'ozlem-erdal-asik-nexxn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlayınça göz yaşımı silecek bir el

Başımı yaslayacak bir omuz arıyorum

Derdimi dinleyecek bir kulak

Teselli verecek bir dudak arıyorum

Düşsem de kalksam da bırakmayacak

Neşemde derdimde yanımda olacak

____________Sevgilim seni arıyorum...

07.1990', 'Ağlayınça göz yaşımı silecek bir el Başımı yaslayacak bir omuz arıyorum Derdimi dinleyecek bir kulak Teselli verecek bir dudak arıyorum Düşs...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlem-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-sefer-i-nce-itlel', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Serseriydi.

Martıya benzer kuşlar isterdi.

Dalıp dalıp enginlere...

Kuş oğlu insan,

Kıvır kıvır deniz saçlarının arasında,

Martıya benzer kuş olabilseydi,

Akdeniz’den dalıp bir çırpıda,

Okyanuslardan çıkarken,

Dünya ile defalarca kucaklaşmak 

                            İsterdi.', 'Serseriydi. Martıya benzer kuşlar isterdi. Dalıp dalıp enginlere... Kuş oğlu insan, Kıvır kıvır deniz saçlarının arasında, Martıya benzer ku...', ARRAY['Türk Edebiyatı','Şiir','Sefer İnce']::text[], 8.5, '{"poet":"Sefer İnce","poet_slug":"sefer-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dilek-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'No name (evlilik dr.)', 'no-name-evlilik-dr-akin-akca-sdhfw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görünmez-çap''ına şenlik 

Tutulan bir 

''İki bacak-pergel'', 

Yakalanır 

Güneş tutulmasında. 

(Şafak için

Ve gün batımı; 

Tutulması için, Ay’ın) 

Gördüklerini ''gördüm'' 

Sananlar vardır, 

Onlar için ''yok yoktur'', 

Ama dünyaya güneş kararırken 

Var olan ''hiç yoktur''. 

* 

Yaz ağaçları pusuda: 

Gölgeler, rüzgar:hışır hışır otlarda; 

Plajdan dönen bir gece bekçisi: 

''Tünemiş-baykuş-ayyaşı''... 

Oturdu banka, otobüs bekler: 

Sözde, veraseti vasiyetsizin; 

Düşün bakalım! 

Öl’geler katman katman; 

Farkındalık, kamikazelerde. 

----------

2. versiyon (son) 

Görünmez-çap''ına şenlik Tutulan 

bir ''İki bacak-pergel'': 

Yakalanır,

Güneş tutulmasında. 

(Şafak için

Ve gün batımı; 

Tutulması için, Ay’ın) 

Gördükleri’ni ''gördüm'' 

Sananlar vardır, 

Onlar için ''yok yoktur''; 

Ama dünyaya güneş kararırken,

Var olan ''hiç yoktur''. 

* 

Yaz ağaçları pusuda: 

Gölgeler, rüzgar:hışır hışır otlarda; 

Plajdan dönen 

Topaç bir hovarda bir gece bekçisi: 

''Tünemiş-baykuş ayyaşı''... 

Oturdu banka, otobüs bekler: 

Sözde, veraseti vasiyetsizin; 

Düşün bakalım! 

Öl`ge’ler katman katman; 

Farkındalık, kamikazelerde. 

- 

Öl’ge: ‘Ölüm belgesi’ anlamında kullandım 

Evlilik Dr.: Mulholland Dr. filminde adı geçen ‘dr’. ancak ‘doktor-evlilik’ anlamında

Not: Bahsi geçen ''sananlar'',gerçek gerçek olmadığında,gerçeğin ikinci yüzü olan iç''teki bir oluşum.Sadece bu zamanlarda,iç''te olabilen bir dış''taki.Böyle zamanlarda,ikisinin arasında bekleyen kudret,genelde dışta olmamasına rağmen dışta kalan bir içsellik.', 'Görünmez-çap''ına şenlik  Tutulan bir  ''İki bacak-pergel'',  Yakalanır  Güneş tutulmasında.  (Şafak için Ve gün batımı;  Tutulması için, Ay’ın...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/no-name-evlilik-dr-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KA-DIN-LA-RI-MIZ', 'ka-din-la-ri-miz-sefer-i-nce-t679e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Asırlardır en güzel varlığa inat,

En itilmiş yalnızlığa kadınlar.

Anamla orak sallarken kuşluğa,

Kadınlığını unutup

Yıllarca taşıdı nasırını,

Kıtlık günlerinden kan akıttı yarına.

	Ana dolu yüreğimde damgan.

Artemisia’nın çisel gözlerinin

Doğuda kurulmuş pazarları 

Neyleyim...

Berklik kuşağına bağlamışlar dillerini.

Dillerin sus pus, emeğin fora,

Kara sabanlı kara toprağa,

Kullapı oldun. Apardı üstüne koca dünya.

Bütün nesiller senden sorula...

	Leee..   leee.... kadınım...

Vietnam’da bir çocuk kaçar geleceğe,

Ardında korumalı kadın parçaları.

Halepçe’de her çocuk bir anaya sarılmış,

Çırpına çırpına ölüm.  Çırpına çırpına...

Ölüm insan ayırt etmiyor.

Kadınım eşarbını dişliye teslim etmiş

Fabrikada.

   Ve yine Adem Havva ile sevişmiş

				Neyleyim....

Sonra kaptıkaçtılarda sıkıştırılmış,

Sonra sağı solu göz yaraları,

Sonra çirkeflerin  taze kanı,

Evlerde bunadı, bunaldı.

			Neyleyim...

Birlikte orak sallardık ana kuşluklara.

Ve ben

Kadın sanmazdım.

Babamın avradı

			Ya da

Oğlanın anası... o kadar...', 'Asırlardır en güzel varlığa inat, En itilmiş yalnızlığa kadınlar. Anamla orak sallarken kuşluğa, Kadınlığını unutup Yıllarca taşıdı nasırını...', ARRAY['Türk Edebiyatı','Şiir','Sefer İnce']::text[], 8.5, '{"poet":"Sefer İnce","poet_slug":"sefer-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ka-din-la-ri-miz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşmayan Sevgili', 'kavusmayan-sevgili-sair-muhsin26-pdc5l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İkisinden de habersiz 

Gökyüzüde aşıktı martıya

Deniz ve gök yüzü tutuştular kavgaya

İtilecekti bir yanlızlığa 

Gelinliğini giymişti martı

Çok sevdiği denizle evlenecekti

Mesıut ve mutluydu ikiside 

Ne var ki...

Deniz, dalgalarla köpürüyor

Gökyüzü şimşeklerle kükrüyor

Rüzgarlara dağıtıyordu

Kanrevan kopmuştu her taraf

Bu nihayetsiz kavgada

Kalmıştım martı arada

Vurulup düşmüştü kumsala

Sonra; çocuklar bulmuştu martıyı

Gömmüşlerdi onu

Hepsinden çok seven kara toprağa

             

                                        07.05.1999', 'İkisinden de habersiz  Gökyüzüde aşıktı martıya Deniz ve gök yüzü tutuştular kavgaya İtilecekti bir yanlızlığa  Gelinliğini giymişti martı Ç...', ARRAY['Türk Edebiyatı','Şiir','Şair Muhsin26']::text[], 8.5, '{"poet":"Şair Muhsin26","poet_slug":"sair-muhsin26","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kavusmayan-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Değişen Neydi! ...', 'degisen-neydi-erdal-asik-ailpu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne oldu söyle bize

değişen neydi dünden bugüne

sen değilmiydin ağlayan

sevgimizi haykıran

karanlıklarda buluşup

yürürdük el ele tutuşup 

kuşlar bile duymazdı sesimizi

geceler saklardı ikimizi

zaman mıydı yoksa

senmiydin ki değişen

içimizdeki sevgiyi 

kokmuş bir cesete çeviren

kara toprak serptin üstüme

bedenim dünyada ruhum sende

bırakmam seni son nefesimde

götürürüm seni gittiğim yere...', 'ne oldu söyle bize değişen neydi dünden bugüne sen değilmiydin ağlayan sevgimizi haykıran karanlıklarda buluşup yürürdük el ele tutuşup  kuş...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/degisen-neydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bence sevgi..', 'bence-sevgi-ferit-teksoy-8im0x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pehlivan gibi güçlü

Mahkumlar gibi suçlu

Dağlar gibi yokuşlu 

Olmalı,bence sevgi

Hep mutlu etmemeli

Kızmalı,gitmemeli

Doymalı,yetmemeli

İsterik,bence sevgi

Hedefi saptırmayan

Seveni kandırmayan

Vurmalı,öldürmeyen

Olmalı,bence sevgi

Fırtınalar görmeli

Depremler geçirmeli

Selde sürüklenmeli

Afettir,bence sevgi

Var iken doyulmayan

Yokken dayanılmayan

İçilen,kanılmayan

Olmalı,bence sevgi

Alında yazı gibi

Ozanın sazı gibi

Şairin sözü gibi

Olmalı,bence sevgi

Heykel gibi ölümsüz

Tablo gibi doyumsuz

Yaşanmalı,yorumsuz

Olmalı,bence sevgi

Yürekte kazı gibi

Damarda gezi gibi

Beyinde sızı gibi

Olmalı,bence sevgi

Ve nihayet sonunda

İki mezar üstünde

Nadide bir çiçek gibi

Açmalı,bence sevgi', 'Pehlivan gibi güçlü Mahkumlar gibi suçlu Dağlar gibi yokuşlu  Olmalı,bence sevgi Hep mutlu etmemeli Kızmalı,gitmemeli Doymalı,yetmemeli İste...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bence-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Ben', 'sensiz-ben-i-brahim-karatas-upjex', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Taç yaprakları ıslanırken

bir çiçeğin

puslu bir gecede

camları buğulanırken

evimin

ıslak bir gecede

kirpiklerime yaslanırken

gözyaşlarım

sessiz bir gecede

gönül nağmelerin seslenirken

bir sen’in

sensiz bir gecede

Seni aradım ağlarken

bir ben’de 

bensiz bir gecede

bir ben’in

bensiz bir gecesinde', 'Taç yaprakları ıslanırken bir çiçeğin puslu bir gecede camları buğulanırken evimin ıslak bir gecede kirpiklerime yaslanırken gözyaşlarım ses...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Karataş']::text[], 8.5, '{"poet":"İbrahim Karataş","poet_slug":"i-brahim-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensiz-ben-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız', 'kiz-erol-dal-isg19', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyandan çekip almak için

İzin ver

Susma 

Konuş ne olur…

Aklımda anlatıkların

Ki dudaklarımda öpüşün

Verdiğinden fazlası olamadı ki hiç

Unuttum herşeyi……………

Haklısın.

Sevişmek sahip olmak değilmiş

Yeni öğrendim.

İyi geceler 

Öptüğüm kız

Sımsıkı sardığım 

aynı zamanda.

İyi geceler 

Dudaklarımı tuz yapan kız

İyi geceler,

Adına 

şiirler yazdığım kız

ED/04/Mekan', 'Dünyandan çekip almak için İzin ver Susma  Konuş ne olur… Aklımda anlatıkların Ki dudaklarımda öpüşün Verdiğinden fazlası olamadı ki hiç Unu...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayrılık Şiiri', 'bir-ayrilik-siiri-cem-ozdemir-rukc7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belli oldu..! 

Ayrılık...

Bu akşam bana bir şiir daha yazdıracak..! 

Yüreğim..

yine hüzün bahçesi gibi..! 

Kulaklarımda..

eski şarkıların en damar nağmeleri..! 

Ve.. gözlerim..

senin yokluğunla doldu..! 

Ağlasam diyorum..

hani, belki rahatlarım..

açılırım biraz..! 

Ama nerdee..? ! 

Gözlerimden boşalacak yağmurlara.. tufanlara..

çoktan razıyken,

şu hâle bak..! 

Oturmuş..

bir tek damla için dua ediyorum..! 

Hani.. ''Boşver..! '' diyesi geliyor insanın..

''Boşver be şair..! Boşver, takma kafanı..! ''

''Hayatta her şeyin çaresi bulunur...'' filan gibilerinden..! 

İyi de..! 

Sen ayrılığın çaresini bilir misin, ey şair..? ! 

Ya, yürek acısının ilacını..? ! 

Anlaşıldı..! 

Ayrılık...

Bu akşam bana bir şiir daha yazdıracak..! 

Hem de, en arabeskinden..! 

En yürek yakıcısından..! 

Hem de, utanmadan..

ağarmış saçlarımdan..

ve de yorgun yüreğimden..! 

Belli oldu..! 

Ayrılık...

Bu akşam fena halde canıma okuyacak..!', 'Belli oldu..!  Ayrılık... Bu akşam bana bir şiir daha yazdıracak..!  Yüreğim.. yine hüzün bahçesi gibi..!  Kulaklarımda.. eski şarkıların en...', ARRAY['Türk Edebiyatı','Şiir','Cem Özdemir']::text[], 8.5, '{"poet":"Cem Özdemir","poet_slug":"cem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-ayrilik-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Olmadın', 'sen-benim-olmadin-derin-oger-28mw4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşktı suların üstünden atlayıp

Sedef gibi yüreğimi kaplayan

Aşktı pembe çiçekli kayısı kokulu

İlk yaz güneşi sıcaklığı rüzgarlarla esen

Aşktı dallı saçaklı dantel dantel kaygılara inat

Baharın güzelliğiyle sarhoş olmaya çağıran aşktı

Düşlerime değdi renk renk desen desen bulutları

Düşlerime düştü gövdesini güneşe veren ağaçları

Karıncalar tavşanlar kurtlar kuşlar bile heyecanlandı

İçimde ad verilmez duygular deli deli köpürüp aktı

Göl turnanın çöl leylanın oldu sen benim olmadın

Sönmeye yatkın bir kıvılcım yanarım.......', 'Aşktı suların üstünden atlayıp Sedef gibi yüreğimi kaplayan Aşktı pembe çiçekli kayısı kokulu İlk yaz güneşi sıcaklığı rüzgarlarla esen Aşkt...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-benim-olmadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Gitsin...', 'unut-gitsin-i-brahim-ethem-bingul-vvcee', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğim puslu

Sönmüştü renklerin sisi

Solmuştu yüzümde ki gülümsemenin rengi

Sen ve sevdandan önce

Bilmediğim bir zamanda

Bilinmez bir mekanda

Bilinse de söylenmez bir durumda

Yaşadığım sen ve sevdam

Şiirlerimin mürekkebi sensin

Yüreğimin çağlayanı da sen

Unuttuğum mutlu gün

Adı da sen

Bilmediyse yüreğin hala yüreğimi

Duymadıysan kokumu ansızın

Ve bunları mısralarda anlayacaksan

Unut beni ve bu şiiri

Unut gitsin....', 'Yüreğim puslu Sönmüştü renklerin sisi Solmuştu yüzümde ki gülümsemenin rengi Sen ve sevdandan önce Bilmediğim bir zamanda Bilinmez bir mekan...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unut-gitsin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız', 'i-mkansiz-ayten-ozlem-yesilcali-utfop', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kagıt kalem kaldı öylece elimde. 

Yazmak istedim ne varsa gönlümde 

Seninle aramızde bir şeyler var. 

Bende direndim durdum imkansız. 

Gözlerim dolu dolu saat sabahın beşi 

Kimi mutsuz benim gibi; 

kiminin yanında eşi. 

Kimki bu beni benden alıp götüren kişi. 

Ugraştım nafile anlatmak imkansız. 

Bogazım dügümlendi,hafızam nerede. 

Aklım fikrim kalmış malesef sende. 

Seninle el ele son verdik biz bu işe. 

Ugraştım olmadı anlatmak imkansız. 

Kaderin önünde yuvarlandım durdum. 

Gözgöze gelip seninle bir bütün oldum. 

Nihayet gönlüme bir sahip buldum. 

Seni şiirlerle anlatmak imkansız.', 'Kagıt kalem kaldı öylece elimde.  Yazmak istedim ne varsa gönlümde  Seninle aramızde bir şeyler var.  Bende direndim durdum imkansız.  Gözle...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/imkansiz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam Yalnızlığını Gülüyordu', 'bir-adam-yalnizligini-guluyordu-t-ayhan-cikin-lziqp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir adam yalnızlığını gülüyordu ağlamaklı

Hangi uzaklardı varamadığı bilmiyordu

Milimetrelerle ölçüyordu aklında yarattığı evreni

Balık yumurtalarını sayıyordu körfezde

Bir adam yalnızlığını gülüyordu ağlamaklı

Hangi dudaklardı öpemediğibilmiyordu

Kadınsı caddelerdi hep ellerinde

Çaresizliğini kaldırımlara tükürüyordu

Avanakça türküler dökülüyordu dudaklarından

Hangi ellerdi tutamadığı bilmiyordu

Bir adam yalnızlığını ağlıyordu gülmekli

Uzak bir sevgiydi özlemlerinde

Yarınlar hasat ediliyordu tarlalarda

Yine ölçüyordu evrenini aklınca

Bir adam yalnızlığını gülüyordu

Aptalca...', 'Bir adam yalnızlığını gülüyordu ağlamaklı Hangi uzaklardı varamadığı bilmiyordu Milimetrelerle ölçüyordu aklında yarattığı evreni Balık yumu...', ARRAY['Türk Edebiyatı','Şiir','T. Ayhan Çıkın']::text[], 8.5, '{"poet":"T. Ayhan Çıkın","poet_slug":"t-ayhan-cikin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-adam-yalnizligini-guluyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatamı yaptım', 'hatami-yaptim-ayten-ozlem-yesilcali-kvvlt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sevmekle hatamı yaptım.

Kimseye degil ben sana taptım.

Sevgi çiçeklerinden başına taç yaptım.

Seni sevmekle söyle hatamı yaptım.

Biliyorum hoşuna gitmiyor nete takılışım.

İçime dert olur mahsun bakışın.

Ayrılıgı hatırlatıyor el sallayışın.

Seni sevmekle söyle hatamı ettim.

Dilerim aşkımız yansın sönmesin.

Kimse verdiği sözden dönmesin.

Sevgi yaşamaya dege asla ölmesin.

Seni sevmekle söyle hatamı ettim.

Seni bulamayınca bana bir haller oluyor.

Gönül bahçemdeki güller soluyor.

Benzim sararıyor gözüm doluyor.

Seni sevmekle söyle hatamı ettim.', 'Seni sevmekle hatamı yaptım. Kimseye degil ben sana taptım. Sevgi çiçeklerinden başına taç yaptım. Seni sevmekle söyle hatamı yaptım. Biliyo...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatami-yaptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şafakta Son Sapakta...', 'bir-safakta-son-sapakta-bekir-mutlu-gokcesu-ikm78', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sabah

Gün doğmadan uyandım

Binlerce yıllık yokluğuna

İçim yanarak hani

Sana geç kalmışlığıma

Sabahın ilk ışıkları

Dokunmaya çalışıyordu

Demini almış

Başı dumanlı

Gecenin saçlarına

Sevda yüklü

Yolunu tutmuş

Bir gemi gibi

Kayıyorken gece

Yaşamlarımızcasına

Söndürmekteydi kandillerini

Şafakta

Maviye sabırsızlanıyordu

Kuşlar feryat figan

Çığlıklarıyla

İçimden bekle dedim

Küsme

Bekle beni son sapakta....', 'Bu sabah Gün doğmadan uyandım Binlerce yıllık yokluğuna İçim yanarak hani Sana geç kalmışlığıma Sabahın ilk ışıkları Dokunmaya çalışıyordu D...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-safakta-son-sapakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmezdim maviyi', 'bilmezdim-maviyi-zafer-zengin-etnika-0r4x3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerim

Hiç mavi olmadı  benim

Bilmezdim Maviyi

Akdeniz de öğrendim

Etlerim pişti tuzundan

Apış arası kaşıntılar

Saplanır sarı kumlar

Saçlarım sarıydı anlamazlar

Öğlen uykularına yattım gölgelerde

Horladım

Vardım

İnsandım

Üst değiştim duldalarda/lime lime

Kimseye anlatmadım/Fakirdim

Gömlek çalardım denizlerden

Üstüme olur mu bilmeden

Rengi beyazdı/sevdiğimden

Ben hiç mavi gülmedim

Uyurken işte

Genç kız ellerinden/Uzaktım

Anı sattım

Gizli kaçtım adalara

Ben hiç mavi gülmedim

Gül''den kızıl gülüşüm

Ben hiç mavi görmedim

Bu yüzden 

Akdeniz''e hasretim

Mavi güldüğüm tek yer benim

Ben hiç mavi sevmedim

Gözlerim kahverengi benim

12 Mayıs 2004 '' İçimin kitabı ''', 'Gözlerim Hiç mavi olmadı  benim Bilmezdim Maviyi Akdeniz de öğrendim Etlerim pişti tuzundan Apış arası kaşıntılar Saplanır sarı kumlar Saçla...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bilmezdim-maviyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskançlık', 'kiskanclik-ayten-ozlem-yesilcali-jyp7r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün gördüm yine nette kahroldum.

Takatım tükendi sararıp soldum.

Sen belki mutlusun ben bedbaht oldum.

Seviyorum kıskandım elimde degil.

Mahsun mahsun baktım netten.

İmkanı yok ayıramam eşinden.

Seviyorum ayrılamam ben senden.

Seviyorum kıskandım elimde degil.

Kıymeti yok canım aşkından ölsem

Yeterki seni başkasıyla görmesem.

Seni çok sevdigimi söylesem.

Seviyorum kıskandım elimde degil.

Elimden kenime bir kaza çıkar diye korkarım.

Gelip geçsin diye nette yollarına bakarım.

Senin için İstanbulu yakarım.

Seviyorum kıskandım elimde degil.', 'Bu gün gördüm yine nette kahroldum. Takatım tükendi sararıp soldum. Sen belki mutlusun ben bedbaht oldum. Seviyorum kıskandım elimde degil. ...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiskanclik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanacak Şiirler', 'yasanacak-siirler-abidin-guneyli-buxz1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün insanlar yaşayıp yazdığını sandılar

O aşk kokan şiirleri / kıskandılar

Oysa yaşamadan yazdığına üzüldün hep

Yazıp da yaşansaydı hayat

Beni yazardın 

Sonra

Sevgiyi dostluğu barışı yazar

Ayrılığı silerdin sözlükten

Ama boş ver

Herkes öyle bilsin kıskansın

Keyfini sür sen de 

Kıskananların gönlünde

Yaşamadan yazdığın şiirlerin

		2 Aralık 1996', 'Bütün insanlar yaşayıp yazdığını sandılar O aşk kokan şiirleri / kıskandılar Oysa yaşamadan yazdığına üzüldün hep Yazıp da yaşansaydı hayat ...', ARRAY['Türk Edebiyatı','Şiir','Abidin Güneyli']::text[], 8.5, '{"poet":"Abidin Güneyli","poet_slug":"abidin-guneyli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasanacak-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Gerçeğini Ara', 'kendi-gercegini-ara-guler-ilgaz-kzcpz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İster misin aramak 

Gerçeği

Ara kendini

Ayrılıkların ayırdığı

Yerde mi ararsın...

İster misin yaşamak

Hayallerini

Ara kendini

Gökte mi ararsın

İster misin bulmak kendini

Boşluğun içinde

Yaratmak için

Ararken kendini

Nerede aramak istersin

Ol-mak için', 'İster misin aramak  Gerçeği Ara kendini Ayrılıkların ayırdığı Yerde mi ararsın... İster misin yaşamak Hayallerini Ara kendini Gökte mi arars...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kendi-gercegini-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şairi Sev De Gör Sevda Neymiş', 'bir-sairi-sev-de-gor-sevda-neymis-abidin-guneyli-lbcvj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevene sevdanın adını sorma

 Bir kez şair sev de gör sevda neymiş

 Şairi sevmenin tadını sorma

  Mecnun’a sırrını sor sevda neymiş

 Sevgi O’nda bitmez uzun süreçtir

Dizleri yorulur beyni hep dinçtir

Yaşı yüz olsa da gönlü hep gençtir

Bir şairi sev de gör sevda neymiş

 Karabiber tarçın her şeyi katar

 Bir yudum sevgiyi dağ gibi yapar

Girersen gönlüne hep sana tapar

Bir şairi sev de gör sevda neymiş

Gözlerinde her ton renkten bulunur

Dünyanın her derdi ondan sorulur

 Vurgundur yüreği çabuk yorulur

 Bir şairi sev de gör sevda neymiş

 Toplumda hep saygı görür sevilir

 On dakika sohbet eden bayılır

 Yine de tahtası eksik sayılır

 Bir şairi sev de gör sevda neymiş

    Abidin GÜNEYLİ', 'Sevene sevdanın adını sorma  Bir kez şair sev de gör sevda neymiş  Şairi sevmenin tadını sorma   Mecnun’a sırrını sor sevda neymiş  Sevgi O’...', ARRAY['Türk Edebiyatı','Şiir','Abidin Güneyli']::text[], 8.5, '{"poet":"Abidin Güneyli","poet_slug":"abidin-guneyli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-sairi-sev-de-gor-sevda-neymis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Aşk Nedir Bilmezsiniz', 'siz-ask-nedir-bilmezsiniz-t-ayhan-cikin-6jfss', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söz söylemeyin bana

aşktan yana

sırılsıklam olmuşum

bir çarık pabucumu satmışım pazarda

- siz bilmezsiniz-

ellerim dün yoktu- ya da vardı-

- görmediniz onu siz-

görmediniz balıkların nasıl seviştiğini

ne bileceksiniz aşkı siz

sevmeyi ne bileceksiniz

kelimelerde değildir ki sevmek

siz ölmediniz ki sevgiden

ayrılık nedir bilmezsiniz

-bilemezsiniz onu siz-

Daha dün bir.. bugün iki

pantolonu delik bir çocuktunuz sokak ortalarında

çiçeklerin nasıl bir aşkla seviştiğini bile görmediniz

ne bileceksiniz aşkı siz

yağmur yağmur yağmadınız

rüzgar rüzgar esmediniz

kar olup bir aşk gibi yapışmadınız

kristal olmadınız siz

-aşkı ne bilirsiniz-

Bakmayın böyle delilendiğime

sevmem dediğime bakmayın siz benim

ben boşaldıkça dolarım aşktan yana

demeyin öyle ''sevmiyorsunuz'' diye

öyle hayin bakmayın bana

vurulmuşum rüzgarlardan

          aşktan, sevgiden, yağmurdan

          buluttan, yokluktan yana.

Siz bilemezsiniz beş kuruşsuzluğun ıstırabını

bilemezsiniz parasız gezmeyi

ve de en çok sevdiğinizi

          sevmedim demeyi.

N''olur öyle hain bakmayın bana

yüreğim yok ki karşı koyayım

dağlarca yücelemem ben 

sevgi.. aşk nedir diyemem

beş kuruşun yaptığını aldırmayın

kader bu.. parasız gelmişiz dünyaya

bu akşam yemeğim de yokmuş

aşkımı inkar etmişim ne çıkar

          n''olur hayin demeyin bana

          demeyin hayin bana.

Siz aşkı bilmezsiniz

yıllarca yağmur yağmur düşünmezsiniz sevmeyi

rüzgar rüzgar esmezsiniz

ıslanmazsınız kaldırımlarda benim gibi

siz.. siz benim gibi sessiz sevemezsiniz

                                                  sevemezsiniz...

                                                                        siz.. 

 (1965)', 'Söz söylemeyin bana aşktan yana sırılsıklam olmuşum bir çarık pabucumu satmışım pazarda - siz bilmezsiniz- ellerim dün yoktu- ya da vardı- -...', ARRAY['Türk Edebiyatı','Şiir','T. Ayhan Çıkın']::text[], 8.5, '{"poet":"T. Ayhan Çıkın","poet_slug":"t-ayhan-cikin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/siz-ask-nedir-bilmezsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirpiklerinin Salıncağında Gönlüm Sallanır', 'kirpiklerinin-salincaginda-gonlum-sallanir-ahmet-capa-0a6pm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir seyyah misali

gezinip uykularımın şehrinde.

Günahsız rüyalarımın hanında konakladın,

Sonrada dörtnala koşturup, düşlerin atını.

Kulağına gizli bir adres mi fısıldadın.

Kalbimin dalgası,

vurmasaydı gönlünün kayalıklarına,

Böyle köpürerek şahlanır mıydı sandın,

Karşılaşan iki ırmak gibi,

çarpışmasaydık zamanın kuytusunda

İçimde böyle gedikler açılır mıydı sandın.

Kuşların havalanırken,

kanatları altında bıraktığı hava gibi,

Yollarda kaldı ayaklarının mutlu izleri,

Filizlendi gölgen buğulu camlar ardında.

Pencerelerin alnından öpüp okşar gibi,

Giydin de üstüne sevda hırkasını,

Bir kirli gömlek gibi atılır mı sandın.

Giderken viran ettin de kalbimi,

Bir yıkık duvar gibi onarılır mı sandın.

Değmesin ellerin, hiçbir çiçeğe okşarcasına,

O çiçeklerki, toprağa çakılı kalmaktan utanır. 

Kıskanç gözkapaklarınla örtme gözlerini,

Kirpiklerinin salıncağında gönlüm sallanır,

(Mayıs 2004 İST.)', 'Bir seyyah misali gezinip uykularımın şehrinde. Günahsız rüyalarımın hanında konakladın, Sonrada dörtnala koşturup, düşlerin atını. Kulağına...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kirpiklerinin-salincaginda-gonlum-sallanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil Üstünde Kaydırmaca', 'dil-ustunde-kaydirmaca-guler-ilgaz-u6f41', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'De ki ben bir bulmacayım

Kimbilir kaç parçadan oluşan

Kimbilir beni çözdüğünde

Sen de çözüleceksin

Benimle', 'De ki ben bir bulmacayım Kimbilir kaç parçadan oluşan Kimbilir beni çözdüğünde Sen de çözüleceksin Benimle...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dil-ustunde-kaydirmaca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzle Kahramanını', 'i-zle-kahramanini-guler-ilgaz-9t6h5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçindeki kahramanı

Serbest bırak izle

Bırak özgürce

Yaratsın gelişimini

Engelleme

Üstesinden gelir nasılsa

Üremenin ve üretmenin

Oluşumun, yaşamın sorumluluğunu

İzle

Onunla sınırsızca uçmayı öğren

Kanatlarında güvenle inanarak', 'İçindeki kahramanı Serbest bırak izle Bırak özgürce Yaratsın gelişimini Engelleme Üstesinden gelir nasılsa Üremenin ve üretmenin Oluşumun, y...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/izle-kahramanini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Bu SoN ŞiiR / SuS-TuM*', 'bu-son-siir-sus-tum-mine-ozdemirtas-scpu2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçbir şey istenmedi.

Verilebileceklerin en azının ötesinde.

Ama yine de dama çizgilerinde satranç, hiç bitmedi.

Hiç bitmedi kız tavlası iskambillerde.

Hiç bir soru sorulmadı

Anlatılanların en azının ötesinde.

Ama yine de kızgın kumlarda buz pateni, hiç bitmedi.

Hiç bitmedi su balesi çöllerde.

Sükut ikrar soyundan ya adettir işte.

ne sorulara cevap geldi ne de çare bulundu derde.

arif olan anlasın diyeydi sanırım ta en başından beri

ne mazeret tükendi ne de bahane

İstem dışı az kullanılmış, bu hikaye de

''Son.''... yazılmadı hiç.ama yine de 

Açık bir burun farkı var ağır çekimde.

Şike sebebi ise; zamansızlık işte.

yoksa bile bile

sabır taşını çatlatır mıydık.? 

böyle alkışsız mı inerdi perde

Şimdilerde, birileri, bir yerlerde

Şerefe / 

Kan içiyor olsa bile / yine de / 

Bir şeyler; / O en derinlerde,

O; sevdaya dair açılmış

Siyah beyaz parantezin içinde

Asılı kalacak boynu bükük

kırık ve mahzun bir şekilde.

ah serçe ah / ne işin vardı telde? gördün işte

13/05/2004....çamlıca..00.30', 'Hiçbir şey istenmedi. Verilebileceklerin en azının ötesinde. Ama yine de dama çizgilerinde satranç, hiç bitmedi. Hiç bitmedi kız tavlası isk...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bu-son-siir-sus-tum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Yolu', 'sevginin-yolu-guler-ilgaz-xn8dd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi dolu

Pırıl pırıl bakan bakış korkulara

Şırıl şırıl akan

Nehirdeki su bentlere

Ilık ılık esen rüzgar hortumlara

Dönüştüğünde

İçini acı kapladığında

O acı güce dönüştüğünde

Korkudan sevgiye

Bentlerden ışığa

Hortumlardan boşluğa, hiçliğe

Dönüştüğünde...

O gücü

Kendini bulma yoluna dönüştürebildiğinde

Bulabilirsin ancak

Kendinin sevgi dolu olduğunu...', 'Sevgi dolu Pırıl pırıl bakan bakış korkulara Şırıl şırıl akan Nehirdeki su bentlere Ilık ılık esen rüzgar hortumlara Dönüştüğünde İçini acı ...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevginin-yolu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama Akış', 'yasama-akis-guler-ilgaz-tkc3y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çizgi çizgi yollar

Renk renk yollar

Gel yanıma birlikte yürüyelim

Ne yol tükenir

Ne söz birlikte

Açılır yollar renk olur

Açılır yollar gökkuşağı gibi sarar

Sarar da yüreğimi derinlerden

Alır en yükseğe götürür

Yol yol olmaktan çıkar

Söz söz olmaktan 

Sen ben olmaktan çıkar da

O yolda

Biz oluruz

Yolda

Sözde

İşte cümbüş

İşte dans

İşte coşku 

Akarız orada

Şelale gibi

Yaşama

BİZ', 'Çizgi çizgi yollar Renk renk yollar Gel yanıma birlikte yürüyelim Ne yol tükenir Ne söz birlikte Açılır yollar renk olur Açılır yollar gökku...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasama-akis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız', 'yalniz-guler-ilgaz-m2hsg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duama 

Avucuma

Gözüme

Kulağıma gir de

Göster bana kendini

Elim elinde yürürken

Gözüm gözün olduğunu bilirken

İçimdeki sesi dinlerken

Dualarım hepimiz için

Nasıl mutlu olabilirim ki

Nasıl yalnız olabilirim ki

Neyi görebilir

Neyi işitebilirim ki

Yalnız...', 'Duama  Avucuma Gözüme Kulağıma gir de Göster bana kendini Elim elinde yürürken Gözüm gözün olduğunu bilirken İçimdeki sesi dinlerken Duaları...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalniz-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derim ki Seninleyim', 'derim-ki-seninleyim-guler-ilgaz-b70wi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derim ki

Kendine güvendiğinde ben de sana güvenirim

Kendine inandığında

Ben de sana inanırım

Kendine acıdığında ancak sana acırım

Kendini üzdüğünde ancak seni üzerim

Kendini boş verdiğinde

Seni boş vermek zor olsa bile

Boş vermek zorunda kalırım...

Sana saygımdan dolayı

Kendine gülümsediğinde...

Bil ki sana gülümserim

Kendine karşı cesaret topladığında savaşmak için

Bil ki topyekün seninleyim

Kendini yenilemeyi seçtiğinde

Öyle bir keyif alırım ki...

Ben de seninle yenilenir.... seninle severim yeniden

Sevgiyle yarattığında kendini

Bil ki seninleyim', 'Derim ki Kendine güvendiğinde ben de sana güvenirim Kendine inandığında Ben de sana inanırım Kendine acıdığında ancak sana acırım Kendini üz...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/derim-ki-seninleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ramazan Güngör ustanın anısına...', 'ramazan-gungor-ustanin-anisina-zafer-zengin-etnika-guemx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kim kaldı derken saatlere

Bir bir gidiyor usta eller ebediyete

Çörten boğazı çalar yaşlı bedeni

Tüyler diken diken olur

Titrerken curasının teli

Bir avaz ki akdeniz

Dinleseniz gidersiniz

Ellerinden öpersiniz

Anadolu hep öykü

Hep türkü bilesiniz

Ustalar sahipsiz gitmezsiniz

- Curam burda değil..olsa çalardım..Düğüne götürdüler

Böyle söylemişti utanıp

Curası şimdi kimde bilinmez

Topal ramazan calmazsa sevilmez herhalde

2 yıl evvel akdeniz gezisinde uğramış el öpmüştük

RAMAZAN GÜNGÖR  ''Topal ramazan '' ustanın evine

ev dediğim bir göz bir yer işte..yaşlıca

yüreği temiz anadolu insanı..Şelpe tekniğinin yaşayan  ne büyük üstasıydı..fethiye bölgesinde mahalli sanatcı olarak bilindi..İnşaat işçiliği yaptığı dönemde düşerek ayaklarından sakatlanmıştır..Bu yüzden topla ramazan diye anılmıştır..

Aklımdaydı bu yıl gidip görmek

Kendi elinden curasını dinlemek..nasip olmadı..

Kaybetmişiz..Çok üzüldüm..Kendisine tanrıdan rahmet..sevenlerine baş sağlığı dilerim..

Arif sağ..Erdal Erzincan..Erol Parlak..Sümer ezgü, ustanın selamı vardı sizlere...Kısmet olmadı söylemek

Omzumuzda yükü kalmasın..şimdi söyleyelim

Not:Dinlemek isteyenler Kalan müzik arşivinden albümünü bulabilir.

Ustanın aziz anısına..saygılarımla..Eyvallah..', 'Kim kaldı derken saatlere Bir bir gidiyor usta eller ebediyete Çörten boğazı çalar yaşlı bedeni Tüyler diken diken olur Titrerken curasının ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ramazan-gungor-ustanin-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Tamamına', 'tamamina-akin-akca-haxzf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilginin duygu içine dağılımı

İnsan yapımı (is gibi, sis değil) 

Japon yapıştırıcısının içine

''Tepeden doğru değil'' 

Gibi görünür.

Halbuki, içteki duygudur,

Gözükürken dış tarafta

(''Dışta gözüken aslında

Değildir ve bu yapıştırıcı''

Ve hatta,dıştaki bilgi''dir o)

Öyle karışmıştır ki, dış ile iç bezenleri: 

Bilgiyle duygunun

Aynılığını ne mümkün hatta sezinlemek:

Bir zamktır neden ile sonuç

Karşısında fikir beyanı..

Zamanla maddenin kardeşliğiyse,

Ki tıpkısıdır bunun, sonuç arayan süreçte

(Süreç üstündeyken, anlamlı kılmaya, sonucun

Yani taşırken sonuç sebebi: 

Varır, bir geçmiş, geleceğe, ‘süreç’ ile:

Gelecek ulaştırır kendini tekrar geçmişe

Ve süreç sürer yine kendisinde) 

Gerçek karmaşaya:

''''Bilgi'' versus ''duygu”

Tamamına''..', 'Bilginin duygu içine dağılımı İnsan yapımı (is gibi, sis değil)  Japon yapıştırıcısının içine ''Tepeden doğru değil''  Gibi görünür. Halbuki, ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tamamina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derecelendirmeler', 'derecelendirmeler-akin-akca-2zapu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalem içine sıkışan yeşilin tepesi,

Eteklerine doğru koşan cennet Araf’ın.

Parlayan dengi-sergüzeşt’i,

Daha şafaklarına doğru tan ağartısının.

Beyazdaki süt, kızıl karmaşa.

Bebek ağladı, sekerek:

Suskun-biberon,

Onu kavrayan mini-el’e geldi.', 'Kalem içine sıkışan yeşilin tepesi, Eteklerine doğru koşan cennet Araf’ın. Parlayan dengi-sergüzeşt’i, Daha şafaklarına doğru tan ağartısını...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/derecelendirmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değersem Parmak Uçlarına Öp Beni', 'degersem-parmak-uclarina-op-beni-derin-oger-gdifx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni hatırla

İster kırık bir masada 

İster yıkık bir kaldırımda

Kuşlara ağaçlara dağlara bak

Beni uzun uzun hatırla

Beni hatırla

İster gözlerindeki uykuyla

İster dudaklarındaki suskunlukla

Gökyüzündeki yıldızlara aya bak

Beni uzun uzun hatırla

Bilirim ağzın tutmaz söz ile anlatmaya

Fırtınalı havalarda çiçeklere bak hatırla

Bilirim gözün tutmaz yaş ile ağlamaya

Yağmurlu havalarda yollara bak hatırla

Düşlerim düşüncelerim birikirse gözpınarlarına

Olur da bir damla olup düşersem yanağından

Önce sil sonra öp parmak uçlarından

Ve beni uzun uzun hatırla.......................', 'Beni hatırla İster kırık bir masada  İster yıkık bir kaldırımda Kuşlara ağaçlara dağlara bak Beni uzun uzun hatırla Beni hatırla İster gözle...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/degersem-parmak-uclarina-op-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARiA - 1', 'karia-1-mehmet-kizilay-5lqlq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KARİA

Nerdesin..? Karia! 

Seni

Tuzlu akdenizde

Selsebil encamıyla! 

Arıyorum.

Vuslata 

Hazır değilim 

Halbuki

Karşılayabilecek onura

Henüz ulaşmadım

Yüzsüzlüğümü bağışla.

Ama,

Aç adam...

..çamurda! 

ekmek kırıntısı bulur ya! ? 

gibi doyarım

Tadı o gibi alırım.

Bilirsin ki

Düğün çiçeği zehirlidir

Ama

Adı

Düğün çiçeğidir.', 'KARİA Nerdesin..? Karia!  Seni Tuzlu akdenizde Selsebil encamıyla!  Arıyorum. Vuslata  Hazır değilim  Halbuki Karşılayabilecek onura Henüz u...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/karia-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARiA - 2', 'karia-2-mehmet-kizilay-s8ju1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karia

Zamanını bilmediğim 

randevuya

gelirsin elbet.

Hemen gelmeyecek olursan

Boğazıma

Yüreğimin attığı

İlmek ilmek düğümler

Beni sana getirir.

gelişini bilmeden

Beklemekteyim Karia! .

Bir düşteyim Karia

Dingin bir düş

Ve hala

İsyan şiirleri yazıyorum.

Hala 

Eylemin coğrafyasını çiziyorum.

Bir düş işte

Dingin bir düş

Gömütlerin günyüzüne

Selam dediği bir düş', 'Karia Zamanını bilmediğim  randevuya gelirsin elbet. Hemen gelmeyecek olursan Boğazıma Yüreğimin attığı İlmek ilmek düğümler Beni sana getir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karia-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARiA - 3', 'karia-3-mehmet-kizilay-55g2m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başımı omzuna yaslamak

Sevincimle sende bitmek

Duygularımı 

Bukağılardan

Çekip kurtararak

Gözümden 

Düşürmeye çabaladığım 

Devingenliğini yitirmiş

Hayallerden firak olup

Bir yetim gibi

Saçlarımı 

Sana okşatmak düşündeyim

Karia 

Mutluluklarım,umutlarım

Bekçisiz 

Güvende olsun

Nöbetsiz,içtimasız hisler

Kendince sana gelsin

Sende bitsin,

Seninle dirilsin Karia', 'Başımı omzuna yaslamak Sevincimle sende bitmek Duygularımı  Bukağılardan Çekip kurtararak Gözümden  Düşürmeye çabaladığım  Devingenliğini yi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karia-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARiA - 4', 'karia-4-mehmet-kizilay-pyl2k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varsın 

Saçlarım..

Her bir telini 

Rüzgara taratmasın

Annem

Uyutmasın dizinde

Varsın 

Çocuklarım..

Baba! deyip,

Minik elleriyle

Nasırlı ellerimi tutmasın

Varsın; 

Gülüşlerim,sevinçlerim

Umutlarım

Ve hayallerimin

Talikine karar verilsin

Mahkemelik mahkemelerde.', 'Varsın  Saçlarım.. Her bir telini  Rüzgara taratmasın Annem Uyutmasın dizinde Varsın  Çocuklarım.. Baba! deyip, Minik elleriyle Nasırlı elle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karia-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARiA - 5', 'karia-5-mehmet-kizilay-alwlt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varsın; 

Yatağından yaşam akan

Doğurgan nehir kurusun

Varsın; 

Dinlence günleri bitsin

Tatlı lal 

Kuşatmasın muhitimi.

Varsın

Dökülsün

Kıvrım kıvrım yeşil saçları

Ve

Yürümesin

Avlumdaki

Dut ağaçları.', 'Varsın;  Yatağından yaşam akan Doğurgan nehir kurusun Varsın;  Dinlence günleri bitsin Tatlı lal  Kuşatmasın muhitimi. Varsın Dökülsün Kıvrı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/karia-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARiA - 6', 'karia-6-mehmet-kizilay-0cvq7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruh üflenmesin

Mutluluk buhurdanından

Kin ve kan ekilmiş toprakta

Yeşeren

İhanet başakları

Hukuk tırpanıyla

Artık yolunsun.

Kalbim; 

Bir ara dursun

Gözlerimdeki ölüme tutkun ışık

Artık sönsün

Bırak

Birazcık da,

Yanaklarım donsun.

Bütün hücrelerime

Molotof..düşmüş(çe) 

Sinirlerim,

Damarlarım ve hücrelerim

Dağılsın.

Bırak.!', 'Ruh üflenmesin Mutluluk buhurdanından Kin ve kan ekilmiş toprakta Yeşeren İhanet başakları Hukuk tırpanıyla Artık yolunsun. Kalbim;  Bir ara...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karia-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARiA - 7', 'karia-7-mehmet-kizilay-yu4yc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırak

Kalbimdeki ıslaklık kurusun

Kanım

Übirkaçkez daha

Pıhtılaşsın

Perhizi bozayım bırak..

Karia! 

Bırak

Ak düşmüş saçlarıma

Bir de

Toprağın rengi değsin

Toprak

Bütün şiddetiyle

Nefesini

Soğuk bedenime üflesin

Küflükse..? 

Küflensin,

Yabancılık çekmesin', 'Bırak Kalbimdeki ıslaklık kurusun Kanım Übirkaçkez daha Pıhtılaşsın Perhizi bozayım bırak.. Karia!  Bırak Ak düşmüş saçlarıma Bir de Toprağı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karia-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARiA - 8', 'karia-8-mehmet-kizilay-avse8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşten yanacağım

Ayazdan donacağım

Yağmurdan ıslanacağım

Acılara abanacağım

Ta yürekten

İnanacağım

Vakit

Geçmiş zaman mı? 

Gelecek zaman mı? 

Sende saklı biliyorum.

Bir nazlı ceylan gibiyim KARİA

Bu yokuşta avla beni

Hem de nazsız..cilvesiz.', 'Güneşten yanacağım Ayazdan donacağım Yağmurdan ıslanacağım Acılara abanacağım Ta yürekten İnanacağım Vakit Geçmiş zaman mı?  Gelecek zaman m...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karia-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARiA - 9', 'karia-9-mehmet-kizilay-tkl8f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karia,

Sen

Beklenen gerçek

Ve

Çoğu kez unutulan

Unutuldukça

Kendini hatırlatan

Kimince

Bir nazariye

Eskatologya

Kimince

Mutlak gerçek

Korkulması

Hesap edilmesi gereken

İki kefeli terazi/adalet

Hesap böyle görülür elbet.', 'Karia, Sen Beklenen gerçek Ve Çoğu kez unutulan Unutuldukça Kendini hatırlatan Kimince Bir nazariye Eskatologya Kimince Mutlak gerçek Korkul...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karia-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Zaman ki Gibi', 'her-zaman-ki-gibi-ayse-birgul-yilmaz-zxfjx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir tartışma sonrası sevgilim yine gitti

Beni kaybettin artık bu defa dönmem dedi

Kapıyı hızla çekti ve gitti, beni terketti

Dönmem diye yemin etti

Arkadaşını gönderip eşyalarını istetecekti

Biliyorum ki o arkadaşı hiç gelmeyecekti

Her zaman ki gibi 

Aradan aylar geçti hiç haber alamadım

Galiba bu defa ciddi

Gurur yaptım aramadım

Bu defa sanırım kesinlikle bitti

Sözünde durdu diye düşünüyordum ki

Karşımda sanki suçlu bir kedi', 'Bir tartışma sonrası sevgilim yine gitti Beni kaybettin artık bu defa dönmem dedi Kapıyı hızla çekti ve gitti, beni terketti Dönmem diye yem...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/her-zaman-ki-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay Olmadı', 'kolay-olmadi-ayse-birgul-yilmaz-0amed', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün eski bir sandığı araladım

İçinde köhnemiş anılarım

Birkaç damla gözyaşı esir aldı

Tövbe etti geriye kalanlarım

Titredi ellerim  doldu gözlerim

Kilitlendi bakışlarım bir zamanlara

Boşunaydı soğukkanlılığım

Dudaklarımı kanatırcasına ısırmam

Boşunaydı unutum sandığım

Kolay olmadı yüreğimi susturmam

Kolay olmadı duygularımı bastırmam', 'Dün eski bir sandığı araladım İçinde köhnemiş anılarım Birkaç damla gözyaşı esir aldı Tövbe etti geriye kalanlarım Titredi ellerim  doldu gö...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kolay-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahverengidir Hasret', 'kahverengidir-hasret-zafer-zengin-etnika-0bumi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül düşer yüzüme

Ben yağmurdan bilirim

Küçük ellerinden severim

Hasreti

Seni düşünmek

Akdenizle sevişmek demek

Yüzme bilmem geceleri

Sevmem işte

Uzağı görmeyen gözlerimi

Kahverengidir

Hasret

Sana kaçtım

Param vardı

Özgürlük satın aldım

Dinlediğim şarkıları

Ben hep sen sandım

Samimiydi kaçışım

Senin bile anladığın

Hasret

Yazmasam insanı

Şöyle bir kaç milyon yıl

Sen varsın diye

Kapatmıyorum sayfayı

Deliye çıkarıyorum adımı

Hasret

Güldün ki

Güzeldin

İçimi titrettin...

Sıcak renkmiş kahverengi

Yeni öğrendim

Oysa ben hep kırmızı bilirdim

Renksizim

Seksenli yıllar takılır ayağıma

Alnımı çarparım duvara

Kan diye sen gelirsin avucuma

Hasretmiş renklerim

İlk aşk/Aşkın bile ne olduğunu bilmediğim

İ z  b u r d a n / K a r m a ş ı k / D ü ş ü n d ü ğ ü m... 

12 Mayıs 2004 '' İçimin kitabı ''', 'Gül düşer yüzüme Ben yağmurdan bilirim Küçük ellerinden severim Hasreti Seni düşünmek Akdenizle sevişmek demek Yüzme bilmem geceleri Sevmem ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kahverengidir-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Şansım Sensin', 'tek-sansim-sensin-ayse-birgul-yilmaz-kp7h7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eski zamanlarda ki insanlar,

Çocukluğumdaki bayramlar

Çocukluğumdaki masallar

Gibisin..

Şu yalan yuvası dünyada

Nasıl böyle kalabildin

Şu yılan yuvası dünyada

Sular kadar durusun, seni Allah korusun

Çocukluğumdaki gülüşlerim gibisin

Öyle saf öyle sade ve içtensin

Benim hayattaki tek şansım sensin', 'Eski zamanlarda ki insanlar, Çocukluğumdaki bayramlar Çocukluğumdaki masallar Gibisin.. Şu yalan yuvası dünyada Nasıl böyle kalabildin Şu yı...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tek-sansim-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alakalandırılan eklemseller', 'alakalandirilan-eklemseller-akin-akca-qrbs5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarım metrelik ranzadan atlarken odanda, aşağı; 

Hiç titreme gelir mi, korkuyla karışık? 

Ürperme gelebilir mi gözleriyle konuşurken sen, kuşların; 

Camı açıp onlara verirken, suya batırılmış ekmeği? 

Ne demeli ki? Hem onlar aynı kuş, verirsin de ekmeği; 

Kalbin buruk, besbelli, var bir acı. Sonra onları izlersin: 

Şaşkınca bakışlar, kaçacakmış gibi kanat çırpmalar.. 

Bazıları da duramaz, kaçarlar. Onların sana 

Yan yan bakışlarını bir kediye benzetebilirsin. 

Ama onların da canı, sen: Belki bir pençe attı; 

Belli ki gurur yaptı, anlarsın ki, kedi davranış sergiledi: 

Yaklaştırmaz ya yanına, basarsan sen onun kuyruğuna: 

Bir tavır sergilemek güzeldir, sessizliktense; 

Hem yok ise senden ona kötülük, pençe attı bilmeden: 

Verdiği, senin bakış açına gösterdiği bir tepkiydi... 

Ama onların da canı, sen: Belki attı bir pençe; ama 

Belli ki gurur yaptı, anlarsın ki kedi davranış sergiledi: 

Demek ki, akılda değil kötülük, o duygularda; 

Ya da kedi için, iç güdü''de: Duygularsa öyle şekil olur da; 

Pek çok kereler odur ‘anlık’, belli koşullar altında: 

Kuşlar da kararlıdır aslında yan yan bakışlarında; 

Göllerin kuytu kısımlarında, yengeç yürüyüşü gibi … 

Bizde aştık iç dürtüleri aklımızla, ancak diyelim: Akıl iyi yine; 

(Fi tarihi-geleceği önsezisi, ayrıcalıklı bir an’ı yaşama yetisi.) 

keşke kediler kadar kararlı olsaydık tavırlarımızda.', 'Yarım metrelik ranzadan atlarken odanda, aşağı;  Hiç titreme gelir mi, korkuyla karışık?  Ürperme gelebilir mi gözleriyle konuşurken sen, ku...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/alakalandirilan-eklemseller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadehteki Dudak İzi', 'kadehteki-dudak-i-zi-oguzkan-bolukbasi-sr6db', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadehteki dudak izi 

Daha dün gibi

Taze ve sıcak kalmış anılarımda

Kırmızı şarabın deminde efkârlanmış

Bir yağmurlu mayıs akşamında

Seninleyim 

Söylenmemiş sözler için geri döndün

Biliyorum

Yarım kalan ne varsa tamamlanmalı hayatı terk etmeden

Bir şeyler içer misin

Mesela şarap 

O kan kırmızısı

İhtirasların ortasında serin rüzgârlar getiren

Yüreğinden

Kelimeleri akıtan 

Sevdayı imbik imbik damıtan

O kan kırmızısı

Neden sonsuza kadar sürmediğini sorma

Değiştik 

Oysa 

Ne demiştik hesapları aşka uymuyor sevgilim

Sözlerde durulmadı sanma

Tüm sözler doğruydu söylendiğinde

Zaman durmadı ki

Söylenenler dursun yerinde

Yine de

Kadehteki dudak izi 

Daha dün gibi', 'Kadehteki dudak izi  Daha dün gibi Taze ve sıcak kalmış anılarımda Kırmızı şarabın deminde efkârlanmış Bir yağmurlu mayıs akşamında Seninley...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kadehteki-dudak-izi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri Dağlara Küsmüş Adam', 'gozleri-daglara-kusmus-adam-hakki-hakan-kaya-huwzk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen; 

yanlızlığı gecenin koynunda

için için ayrılığı tüten

farkedilmesin diye kanayan yaraları

elinde kırmızı dikenler tutan

Sen; 

gözleri dağlara küsmüş adam

Sen; 

elleri karanlığın boynunda

ayaz yıldızlarda sevişen

duyulmaması için iniltileri

hergün binlerce çivit yutan

Sen; 

aşkını yüreğine asmış adam

o gözlerine küstürdüğün dağlar 

her sabah yeni bir güneş doğuruyor', 'Sen;  yanlızlığı gecenin koynunda için için ayrılığı tüten farkedilmesin diye kanayan yaraları elinde kırmızı dikenler tutan Sen;  gözleri d...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozleri-daglara-kusmus-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anımsanamayan bir gece 2', 'animsanamayan-bir-gece-2-mutlu-ayar-ld78s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tutkundum bu gece

hiçbir gece tutulmadığım kadar

tutulmuştum mateme

ben ki yüzyıllardır sönmeyen güneş

ben ki yüzünü görmediğim bütün kadınlara eş

sarılmıştı benliğime 

sonuçsuz bilmece 

çocuğu olmayan kadın gibi 

küskündüm kaderime! 

yutkundum bu gece

hiçbir gece yutkunmadığım kadar 

yutkunmuştum geçmişime

ben ki köhne bir evin bacasından çıkan duman

ben ki unutulmuş dağlarda vurulmuş bir ceylan

yansımıştı ruhuma 

kaybolmuşluğun sızısı

zehrini kaybeden yılan gibi 

masumdum şimdi de! 

vurgundum bu gece

hiçbir aşkta vurulmadığım kadar 

vurulmuştum sinsice 

ben ki yüklemi olmayan cümle gibi yarım

ben ki hiçbir işe yaramayan altından bir nalım

kayboldu tüm bildiklerim 

doğuda bir aşirette

idamı bekleyen mahkum gibi 

pişman değilim ettiklerime! 

suskundum bu gece

hiçbir uykuda olmadığım kadar

susmuştum sadece

ben ki zafere susamış askerim bekliyorum pusuda

ben ki tahtası yanlış çakılmış Nuh’um bekliyorum suda 

salyalı mutluluklar yapıştı 

bebek kadar saf mutsuzluklarıma

ölümü düşünen her mahluk gibi

alışık değildim unutulmaya! 

her şeye rağmen durgundum bu gece

hiçbir saatin durmadığı kadar 

durmuştum gizlice

ben ki kurumaya başlayan gül kadar onurlu 

ben ki sağır bir adamın duymadığı en güzel gürültü

keşfedilmeyi bekliyorum 

büründüğüm şeklimde

sır tutamaz çocuk gibi haykırıyorum 

biliyorum seveceğim zamanı 

sevileceğim yeride!', 'tutkundum bu gece hiçbir gece tutulmadığım kadar tutulmuştum mateme ben ki yüzyıllardır sönmeyen güneş ben ki yüzünü görmediğim bütün kadınl...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/animsanamayan-bir-gece-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salkım Söğüt', 'salkim-sogut-sule-aydemir-tm7bj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '____________sevmek en büyük özgürlüktür



bir söğüdün gölgesindeyim

geleceğimde düşünürüm 

salkımım yeşil

kararır yapraklarım

sevda gölgesinin

en kuytu mezarlığını 

doldurmaktayım 

düşünüyorum

son kez ağladığımı

yaş yirmi dokuz

bir aşk uğruna

eski aşk 

söyler türküsünü

inkar eder elma

diğer yarısını

kurban gider yalana

elma kurdu', '____________sevmek en büyük özgürlüktür bir söğüdün gölgesindeyim geleceğimde düşünürüm  salkımım yeşil kararır yapraklarım sevda gölgesinin...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/salkim-sogut-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '19 Mayıs 1919', '19-mayis-1919-bekir-gedikoglu-0f80p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '˜˜˜˜˜____________________ATATÜRK________________

ANTİ EMPERYALİSTİ

……………TÜRK MİLLETİ İÇİN

……………………………………GEREKİRSE CANINI VERMEYE

………………………………………………………………………………..ANT İÇTİ

……………………………………………………………………..VE BUNU

………………………………………………..BÜTÜN DÜNYAYA

…………………………………..GÖSTERDİ

……………...19 MAYIS 1919’ u	

O İCAT ETTİ…………..

Ankara, 12.05.2004-05-12', '˜˜˜˜˜____________________ATATÜRK________________ ANTİ EMPERYALİSTİ ……………TÜRK MİLLETİ İÇİN ……………………………………GEREKİRSE CANINI VERMEYE ……………………………...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/19-mayis-1919-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünme/Muhasebe*', 'dusunme-muhasebe-bayram-tunca-va7d7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arkamda geçmişim önümdeyse geleceğim

Düşündüm elbet bir gün ben de öleceğim

Yapıp/yapmadıklarımdan hesap vereceğim

Söz, zamanımı daha iyi değerlendireceğim

11.05.2004-11.05', 'Arkamda geçmişim önümdeyse geleceğim Düşündüm elbet bir gün ben de öleceğim Yapıp/yapmadıklarımdan hesap vereceğim Söz, zamanımı daha iyi de...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dusunme-muhasebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-feyziye-alper-x3jtk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyorum,

Şimdi sokaklarında sonbahar geziniyor,

Kalabalıklardan arta kalan bir hüzün...

Sislere gömülüyor sende yaşanan aşklar, acılar.

Masumum diyemezsin! 

Sokaklarında yalan, evlerinde ihanet var.

Parklarında gözyaşı...

Masumum diyemezsin! 

Tanığıdır ışıltılı akşamlarıyla Tunalı,

Kızılay tanığıdır, renkli vitrinleriyle...

Balık ve bira kokusu,

Asi sazları, gözüpek türküleriyle Sakarya.

Kokan güller, solup yiten karanfiller...

Yalnızlığa merhaba der, şişelerin dibinde

Kimsesizliği bir elbise gibi giyinmiş sarhoşların.

Biliyorum,

Şimdi senden çok uzak düşsem de,

Sana sevdam zamana yenik düşmez.

Sokaklarında “mutluaşkyoktur” dizesiyle dolaşan

O kırgın, o kimsesiz ben,

Umudunu kesmedi bu kırılgan dizeden.

Masumum diyemezsin! 

Sevgili şehrim,

Rüzgarların şimdi başka perdeleri aralıyor.

Binlerce öykü yaşanıyor bir gecede.

Sorgulamıyor kimse geçmişi,

Geleceğe dair hayaller kurmuyor.

Seni terkedenler,

Beni bu şehirde hiç yaşamamış sayanlar,

Nereye giderlerse gitsinler,

Dönecekler! 

Sırtlarında ihanetin hançeri,

Kalplerinde yalanın süngüleriyle.

Aşklarımız,âşıklarımız, acılarımız,

Hem sana hem bana geldiğinde; 

Ben senden uzaktayım, biliyorsun.

Öykülerimize sırtını dönenlere,

Açma kapılarını! Vasiyetimdir; 

Kapılarını açma...

Masumum diyemezsin! 

Öykümüz tanıklık ediyor ihanetine.

Yalnız bana aç kapılarını.

Sokaklarında yalnız gezmeye razıyım,

Sarhoş gezmeye razıyım,

Adı, 

İlk aşk gibi alfabenin ilk harfiyle başlayan şehir; 

İlkbaharımda sen vardın, sonbaharımda sen.

Mevsimlerin en uzağını bırak seninle yaşayayım.

Kızılay’da bir vitrin,

Tunalı’da gece, ışık ve yabancılık,

Sakarya’da insanlar, yağmur ve çiçek kokusu...

Dönersem mahrum etme beni...

Açma kapılarını yabancılara açma...

Sonbaharı, uzak diyarlarda ayrı ayrı yaşıyoruz.

İzin ver kışımız birlikte geçsin.

İzin ver, yoksa

Masumum diyemezsin! 

			

		(1998/9 Bulancak-2003 Ankara)', 'Biliyorum, Şimdi sokaklarında sonbahar geziniyor, Kalabalıklardan arta kalan bir hüzün... Sislere gömülüyor sende yaşanan aşklar, acılar. Ma...', ARRAY['Türk Edebiyatı','Şiir','Feyziye Alper']::text[], 8.5, '{"poet":"Feyziye Alper","poet_slug":"feyziye-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/ankara-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülendam''ın Nazı', 'gulendam-in-nazi-hulya-ozdemir-is28c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün kapanırken

Kararsızlığındadır

Gülendam''ın nazı

Adaklar takılır mahçup

Biraz da heyacanlı

Gülibrişim dallarına

Tebessümündedir yüzü

Sıcak gamzelerinde 

Kapatılır tül

Bakışlarındaki acıyı gözlerinde

Saraylı bir tutsaktır

Gülendam! ..

Umut adına yorulur

Altın kafesli bahçelerde 

Saraylı kadınların ayakları 

Siner odalara nefesleri 

Solgun dualarda 

Akşam sıkıntıları

Birikmiştir 

Bahtı Bağlanmış sözcükler

Saçlarında

Yanıtlar kaçamak 

Ağlar

Yere düşen mendiller

Karşılıksız,

Çözülmese de özgürlük bağı 

Demir kafesleri seyretmek  kalır

Aşinalığı.', 'Gün kapanırken Kararsızlığındadır Gülendam''ın nazı Adaklar takılır mahçup Biraz da heyacanlı Gülibrişim dallarına Tebessümündedir yüzü Sıcak...', ARRAY['Türk Edebiyatı','Şiir','Hülya Özdemir']::text[], 8.5, '{"poet":"Hülya Özdemir","poet_slug":"hulya-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gulendam-in-nazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Yaşam mı…! ?', 'yasam-mi-abir-zaki-vtgy2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben, 

yaşamın içini nelerin doldurduğunu sorgularken 

geçiverdi yıllar... 

Yaşamın bir ''Merhaba ve Eyvallah'' lar

kadar basit olduğunu söylediğimi 

hatırlıyorum halen... 

O zamandan bu yana 

değişti mi ki yaşam...? 

...................... kim bilir! 

Çeviren: Muammer Çelik          

5/2004

***************************************************************************************

Life...

Years have passed when I was asked 

What life was all about… 

I still remember when I said 

Life was as simple as 

Hi and Bye…. 

Has it changed from that time…? 

................................who knows…! 

sometime in 1995 

5 / 2004', 'Ben,  yaşamın içini nelerin doldurduğunu sorgularken  geçiverdi yıllar...  Yaşamın bir ''Merhaba ve Eyvallah'' lar kadar basit olduğunu söyled...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yasam-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzsun Bende', 'sonsuzsun-bende-galip-simsek-z4t9q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her güzellik sende durduğu kadar asil olasydı

Ben her güzele aşık olurdum

Her güzel senin kadar güzel olsaydı

Ben sonsuza kadar var olurdum

Sonsuz senin kadar büyük olsaydı

Ben bu sonsuzda kaybolurdum', 'Her güzellik sende durduğu kadar asil olasydı Ben her güzele aşık olurdum Her güzel senin kadar güzel olsaydı Ben sonsuza kadar var olurdum ...', ARRAY['Türk Edebiyatı','Şiir','Galip Şimşek']::text[], 8.5, '{"poet":"Galip Şimşek","poet_slug":"galip-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sonsuzsun-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Geçen Yillarim', 'sensiz-gecen-yillarim-baris-guc-92jdd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahar geldi; erimeyen karlarla kapli yüregimin yamacina

Çiçekler açti, yangin yeri uçsuz bucaksiz daglarima

Sevginle daglamisim yüregimi, korkutmaz beni karanliklar

Yüregim Munzur''a emanet, beni birtek o anlar

Sensiz solarken gençligim, bir tek dilegim var o da; 

Hosçakal demeden hayata, yeniden merhaba diyebilmek sana..........

05.05.2004     sda ozlt      msn:  [email protected]', 'Bahar geldi; erimeyen karlarla kapli yüregimin yamacina Çiçekler açti, yangin yeri uçsuz bucaksiz daglarima Sevginle daglamisim yüregimi, ko...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensiz-gecen-yillarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mucize', 'mucize-baris-pinar-tumer-hj3e8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzü

Bu kadar güzelse

Nerede biter

Hayatlar? 

Peki bizleri

Koruyan ne? 

Melekler mi 

Yoksa inler mi? 

Kanat kanata vermişler? 

Gökyüzü bu kadar güzelse

Bizim için bir bulut sevinmeli.

Onca söz, onca göz

Nerede birikir ki...

Gökyüzünde mi...

Bizim hiç uyumayan bulutta mı? 

Bu kadar güzelse

Hayat 

Bir mucize olmalı....', 'Gökyüzü Bu kadar güzelse Nerede biter Hayatlar?  Peki bizleri Koruyan ne?  Melekler mi  Yoksa inler mi?  Kanat kanata vermişler?  Gökyüzü bu...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mucize-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Umut...', 'umut-naime-erlacin-cuenl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kendini ispatlamanın

krikolarına muhtaç insan

biraz cahiliye kültürü

biraz meraksızlık

hayli ıskalamışlık hükmediyor 

şa''şaalı köşklerde

budalaca “artılar” raks ediyor

“eksiler” kokteylinde

süper modernizmin boyunu aşıp bir gün

elbet yolunu bulacak su

doğurgan limanlara yelken açacak kaptan

bir gün mutlaka

ışıldayacak düşünce ve onur

boyundan büyük duracak insan

yarım kalmışlık bu! 

umarım yarınlarda

yarımlardan

bir bütün doğar…

(13 Mayıs 2004)', 'kendini ispatlamanın krikolarına muhtaç insan biraz cahiliye kültürü biraz meraksızlık hayli ıskalamışlık hükmediyor  şa''şaalı köşklerde bud...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/umut-903-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-engin-tas-3ikg9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'erkenden ölmüş bir yarin cenazesi

ve heveskar kıyametler doğurmuşuz

susayınca ovaları yüreğimizin

oğulu fırat’a can gelini hicran verip

üzümden ibaret yosma ömrümüz

sözden ve gözden bir mengenededir

mevsim usulca kavramış ruhlarımızı

bilir kan damarda değil amaçlardadır

umut duldada gözü kara bir servi

haziran sancısını bilmeden büyür

en yavuz oğlumuz fırat’a esir tarla

olgunluk kırkımda düşer başıma', 'erkenden ölmüş bir yarin cenazesi ve heveskar kıyametler doğurmuşuz susayınca ovaları yüreğimizin oğulu fırat’a can gelini hicran verip üzüm...', ARRAY['Türk Edebiyatı','Şiir','Engin Taş']::text[], 8.5, '{"poet":"Engin Taş","poet_slug":"engin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gercek-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Tarihçesi', 'hasretin-tarihcesi-engin-tas-dhj7x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerimi bağladım gülüşlerin üstüne

sabırdan sigara sardım sancılarıma

yokluğunda ağladım ateşlerin üstüne

yangından yağmurlar yaptım yaralarıma

günahı seninle sevdim özümü aklayarak

tenime terleyen tenine taptım

son gecenin hüznünü gözümde saklayarak

aşina acizliğimi aşkınla aştım

gözlerimi çevirdim güneşin batışına

gelmedin gül-tanem gönlüme gömdüm

hasretini bağladım kalbimin atışına

denize derinden deliye döndüm

günleri çektim ipe ürkerek sensizlikten

bir bela benzeri baktım benime

nihayet közlenerek sudaki bensizlikten

külledim kendimi kendi kendime', 'gözlerimi bağladım gülüşlerin üstüne sabırdan sigara sardım sancılarıma yokluğunda ağladım ateşlerin üstüne yangından yağmurlar yaptım yaral...', ARRAY['Türk Edebiyatı','Şiir','Engin Taş']::text[], 8.5, '{"poet":"Engin Taş","poet_slug":"engin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasretin-tarihcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın Yarası', 'yangin-yarasi-engin-tas-4wwfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu günler sırma günler 

elmas günlerdir

gün doğar sevda karası gözüm karası

anasın sevdama büyüğümsün 

aşkı bilirsin

uzaklığın karakış

uzaklığın yangın yarası

bu yokluk kartal yokluk

olimpiostur

zincirim gül kırmızısı  karanfil kırmızısı

belasın gözüme sevgilimsin

beni bilirsin

yokluğun canımda dağ

yokluğun diş sızısı

bu gözler çılgın gözler

deniz gözlerdir

yüreğim köz arası sevda sarası

ceylansın cerensin

koşmayı bilirsin

ayrılığın dalda kan

ayrılığın zıpkın yarası

bu yerler yavan yerler

yalan yerlerdir

ömrüm çayda çıra sevda duası

şahinim uğruna atmacayım

ölmeyi bilirim

susuşun afat kanatta

susuşun idam sırası', 'bu günler sırma günler  elmas günlerdir gün doğar sevda karası gözüm karası anasın sevdama büyüğümsün  aşkı bilirsin uzaklığın karakış uzakl...', ARRAY['Türk Edebiyatı','Şiir','Engin Taş']::text[], 8.5, '{"poet":"Engin Taş","poet_slug":"engin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yangin-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-engin-tas-jvmyg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dilimin ucunda çizdim

içimden geçenleri

kendimde denediğim kırmızı bir kalemle

çünkü bir yabancının mezarı 

önce ve her daim kendi yüreğidir

ve yabancı yüreğinin  yangınından beslenir

gözünde konaklayan

her yolcunun bakışıyla yaktığı

çünkü bir yabancının yüreği

önce ve her daim hancıdır

ve hancı hatıra mahzenidir

işten aştan ve aşktan demli

ve beter kanar yolcularından

çünkü bir yabancının uykuları

önce ve her daim sancıdır

hanın duvarlarını gezinerek büyür yabancı

‘ yarimi el almış harem diyorlar

maraşlı şeyh oğlu satılmışım ben’ le

büyütüp uğurlar

hasretine yandığı yolcularını

ki onlar bir daha geri dönmezler

ve böylece bir yabancının günleri

önce ve her daim acıdır

ve savunmaz kendini yabancı

ebedi gurbetinde

dağlı prometeus gibi yaşar

çünkü bir yabancının içindeki her yolcu

önce ve her daim bir talancıdır

önce ve her daim bir yalancıdır', 'dilimin ucunda çizdim içimden geçenleri kendimde denediğim kırmızı bir kalemle çünkü bir yabancının mezarı  önce ve her daim kendi yüreğidir...', ARRAY['Türk Edebiyatı','Şiir','Engin Taş']::text[], 8.5, '{"poet":"Engin Taş","poet_slug":"engin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yabanci-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Bir Yangındır', 'ayrilik-bir-yangindir-engin-tas-wemnc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ağardıkça saçlarım saçlarım acılarım

gözümün gazabından gözünü gizliyorum

utangaç bir benizi verip de yangınlara

alevinden geçiyor sevdanı izliyorum

içimi arşınlayan ikiz denizim benim

kuytu gecelerimde korkunç öpülüyorum

gözlerin bir dolunay gözlerin yaz yağmuru

baharın ıslaklığında tenini özlüyorum

acım kadar gerçekken yalancı gülüşlerin

nedense yüreğimi hala örseliyorum

zamanın bir sınırı uzayın sınırı yok

sabrımın sınırını hala iteliyorum

erisem de sudaki tuzun can telaşında

sen kırılma diye dilimi törpülüyorum

adını içimdeki ateşin rengi koydum 

alevimden yükselen yüzünü gözlüyorum

neylersin ey kadınım düştüm bir kez aşkına

her ayrılık bir yangın içimi közlüyorum', 'ağardıkça saçlarım saçlarım acılarım gözümün gazabından gözünü gizliyorum utangaç bir benizi verip de yangınlara alevinden geçiyor sevdanı i...', ARRAY['Türk Edebiyatı','Şiir','Engin Taş']::text[], 8.5, '{"poet":"Engin Taş","poet_slug":"engin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayrilik-bir-yangindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Modern Aşk', 'modern-ask-engin-tas-oe7vv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bırak beni kendi halime

avazıma saklanmış yüzünde 

vuruyorum kendimi

her bakışında aşk yaklaşıyorum kıyıya

varlığın darlığın olmasın diye

gözlerimi giyiyorum

saçlarına yağıyorum tarama beni

göğermiş yaralar gibidir aşkım

kundurasız gecelerde ölüyorum

yüreğim bir ayağı kesilmiş masa

kendimi öğütüyorum her gece sende

düşlerimden asılıyorum 

yangın dediğimiz yürek iflası

ve rehin bir kahkaha

sığıntılı gönüllere kalem kırıyorum

fil tebessümü bir tango bu yaşam

bakışlarımdan hörgüçler taşıyor

orangutan oluyorsun banka önlerinde

beni tımarhaneden mezardan ara

kahrımdan kopup ve koşup gidiyorum

kendimden bir bıçak kenarına', 'bırak beni kendi halime avazıma saklanmış yüzünde  vuruyorum kendimi her bakışında aşk yaklaşıyorum kıyıya varlığın darlığın olmasın diye gö...', ARRAY['Türk Edebiyatı','Şiir','Engin Taş']::text[], 8.5, '{"poet":"Engin Taş","poet_slug":"engin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/modern-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-ali-gencay-jm9ki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'acı 

I- 

topuklarım acıyor 

yitip giden adımlar ve kaldırımlar 

biliyormusun 

gece yine Istanbul''dum 

daracık sokaklardaydım 

Galata ''da sirtaki selseri 

Haliç de safahat izleri 

köhnelere sinmiş yalnızlıklar 

bir kaç göz perde arkalarında 

uyumuştu Istanbul''da yaşayanlar 

uyanıktı Isatanbul''u yaşayanlar 

gündüzüm yok senle 

gecem de yaşananlar 

hengamesi çoktur büyüğün 

büyüklüğün emaresi yalnızlıkları hüzün 

bahar mevsimi nasıl kokar 

kaldırımlar bilirmisin 

ıslandığın da yağmurla 

II- 

köklerim acıyor 

oysa ben bir başak tarlasıyım 

köklerim Anadolu bağrında 

rüzgarlarla seviştim nisan da 

bulutların artığı yağmurlar la 

toprak kokuyor yalnızlıklarım 

biliyormusun 

bu gece Anadolu''ydum 

hiç olmadığım kadarıyla 

elimde eskiden kalma 

kartpostallarda Istanbul 

renk kattım sadece bu 

kağıt kalınlığında yaşanmamışlığa', 'acı  I-  topuklarım acıyor  yitip giden adımlar ve kaldırımlar  biliyormusun  gece yine Istanbul''dum  daracık sokaklardaydım  Galata ''da sir...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/aci-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahane', 'bahane-burhan-kucuk-xuyty', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bahane    

                 -I-

Esti geçti bende kavak yelleri

Esiyor hala senin başın da

Özlemin sensizliğe boğuldu

Gönlüm deniz,gönlüm yayla

                 -II-

Ne sen bana sevdalı

Ne de ben sana deli divane

Avuttuk kendimizi

İşte hepsi bu,hepsi bahane

Burhan KÜÇÜK

Kdz.Ereğli-12.05.2004', 'Bahane                      -I- Esti geçti bende kavak yelleri Esiyor hala senin başın da Özlemin sensizliğe boğuldu Gönlüm deniz,gönlüm yay...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bahane-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Ömür', 'i-ki-omur-engin-tas-uvhm7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben ömrümde iki rüzgar tanıdım

biri meltem saçında konaklayan

biri nefesin yüzümü ısıtan

ve ömrümde iki yağmurda kaldım

biri gökyüzünden yağdı başıma

biri gözlerinden avuçlarıma

sen ömründe iki mevsim yarattın

biri ayrılığın iplere çekildiğim

biri aşkın gönlümü emzirdiğim

ben ömrümde iki ömür (hayat) yaşadım

biri susuşundu köze düştüğüm

biri gülüşün bize dönüştüğüm

ve ömrümde iki uyku uyudum

biri kabusumdu kandan kırmızı

biri kurtuluşum tatlı bir sızı

sen ömründe iki nehir tanıdın

biri girdabı kendimin gidişin

biri umarı ömrümün gelişin

ben ömrümde iki şehir tanıdım

biri aşkımızdı berrak bir sudan

biri kopuşumuz yaman pusudan', 'ben ömrümde iki rüzgar tanıdım biri meltem saçında konaklayan biri nefesin yüzümü ısıtan ve ömrümde iki yağmurda kaldım biri gökyüzünden yağ...', ARRAY['Türk Edebiyatı','Şiir','Engin Taş']::text[], 8.5, '{"poet":"Engin Taş","poet_slug":"engin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iki-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Bu Ya..', 'masal-bu-ya-baris-pinar-tumer-c8e5f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Masallarla büyüdük ya

Büyüdük

Büyürken

Büyülendik...

Masallar besledik ya

içimizde

yemedik yedirdik ya

Hani evvel zamanlarda kaybolduk...

Asma kilitli kapılardan süzüldük

Üç elmada dillendik ya

Hani büyüdük

Büyü

Dük...

Ya

Yalan

Biz sadece

yerle gök arasi

yakamozlarız...

Hani büyürken...', 'Masallarla büyüdük ya Büyüdük Büyürken Büyülendik... Masallar besledik ya içimizde yemedik yedirdik ya Hani evvel zamanlarda kaybolduk... As...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/masal-bu-ya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Camlar Buğulu Hep', 'camlar-bugulu-hep-bahri-karaduman-cf5iz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'anımsamayı yeğlemişti

unutmayı değil

ardına takılıp gitmeseydi mavinin

unuturdu belki çok şeyi

oysa yaşam

tek renkli değildi

mavi maviydi ama

asıl sevda sarıdaydı

ardına takılıp gidince mavinin

unutamadı hiçbir şeyi

geçmişini yaşadı

hep geçmişte kaldı

sarı sevdalar hiç yaşanmadı', 'anımsamayı yeğlemişti unutmayı değil ardına takılıp gitmeseydi mavinin unuturdu belki çok şeyi oysa yaşam tek renkli değildi mavi maviydi am...', ARRAY['Türk Edebiyatı','Şiir','Bahri Karaduman']::text[], 8.5, '{"poet":"Bahri Karaduman","poet_slug":"bahri-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/camlar-bugulu-hep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deneme İlgi', 'deneme-i-lgi-rahim-tas-9amu7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlgi

Alarmlı dürtmeler değil, gülen gözlerle uyandırmaktır ilgi. 

Kravatın yakışmadığını söylemek değil, yakışan kravatı bulmaktır ilgi.

Zengin kahvaltı sofrası hazırlamak değil, canının ne istediğini sormaktır ilgi. 

Çantanın yerini söylemek değil, kapı eşiğinden vermektir ilgi.

Düşünceli beklemeler değil, ceplere konulan sevgi sözcükleridir ilgi.

Al getir emirleri değil, alıp yapmak, yaratmak, kapıda şık karşılamaktır ilgi.

Yanına çağırmak değil, yanına gitmektir ilgi 

Salatayı hazırla demek değil, sofraya en son çatal kaşığı koymaktır ilgi.

Ayrı odalara çekilmek değil, aynı diziyi sevdirebilmektir ilgi.

Sırtını sıvazlamak değil, sırtını sabunlamaktır ilgi.

Aynı yatağı paylaşmak değil, sokulmak, sarılmaktır ilgi.

Dizinin dibinde istemek değil, zaman tanımak zaman ayırmaktır ilgi.

Ve evde her zaman bir çocuğun daha bulunduğunu bilmek, kabullenmektir ilgi.', 'İlgi Alarmlı dürtmeler değil, gülen gözlerle uyandırmaktır ilgi.  Kravatın yakışmadığını söylemek değil, yakışan kravatı bulmaktır ilgi. Zen...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deneme-ilgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyalı Kadınım', 'dunyali-kadinim-nesrin-ozyayci-z6ykq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Afrika da çöl ortasında doğdum,

Yalın ayak, ayaklarım yanarak yürüdüm,

Büyüdüm, serpildim, çölde doğurdum,

Kulağıma halka küpeler taktım,

Kolumda tahta bilezikler.

Başımın üstünde taşıdım zamanı

Asya da gezdim, orta doğuda yaralandım

Sevdayı, beynimde yüreğimde yaşadım,

Her şeyi göklere taşıdım,

Yüceldim her şeyi yücelterek. 

Afrika da, 

Kimsesiz bir kadın olarak yaşadım.

Büyüler yaptım, tütsülerle kendimden geçtim,

Hindistan’a uzandım, uzak doğuya kadar, 

Avrupa’ya  uğradım  zaman zaman,

Amerika’yı en son keşfettim,

Geç kaldım ama

Keşfedildim gizemli yolculuğumda

Keşfedilmeyi bilmeden keşfedildim

Buldum ve hiç kaybetmedim.

(Gaziantep, 2000)', 'Afrika da çöl ortasında doğdum, Yalın ayak, ayaklarım yanarak yürüdüm, Büyüdüm, serpildim, çölde doğurdum, Kulağıma halka küpeler taktım, Ko...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dunyali-kadinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Kokum', 'sonbahar-kokum-baris-pinar-tumer-lrmzo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Okulda

Söyledilerdi

Sonbaharda yapraklar

Dökülür...

Ölü yapraklar...

Ölü gözlerle bakarlar

Ben acırdım onlara

içimde cenaze törenleri

düzenlerdim..

Ben bilmezdim o zamanlar

Kopan her yaprak

benim sessiz kokumdur

Tutulmayan sözümdür

nerede bir söz unutulsa

ben ölürüm

bir yaprak gibi...

Kokum sonbahardan

bense ölümden

konuşur dururum....', 'Okulda Söyledilerdi Sonbaharda yapraklar Dökülür... Ölü yapraklar... Ölü gözlerle bakarlar Ben acırdım onlara içimde cenaze törenleri düzenl...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sonbahar-kokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-nesrin-ozyayci-dkig7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yitirdiklerim arasında,

Bir dağın yamacında, bir servinin gölgesinde,

Umutlarımın ötesinde

Hayal meyyal şeylerde, gökkuşağının renklerinde,

Issız Okyanuslarda, sessiz fırtınalarda, 

Yağan karda, esen yelde,

Yalnızlığımda, varlığımda

Seni yaşamama şaşırdım.

Yitirdiklerimde arasında yaşıyorum seni.

En anlamlı, en hızlı iletişimi

Kaçamak bakışlarında yakaladım.

Gözlerindeki buğuda gördüm,

Beden dilinde yüz yüze iletişimde 

Bana susamışlığını gördüm gülüşünde

Sadece bakışlarından değil

Kıskanmandan, öfkelerinden anladım,

Sevdiğini ve özlediğini.

(Gaziantep

2001)', 'Yitirdiklerim arasında, Bir dağın yamacında, bir servinin gölgesinde, Umutlarımın ötesinde Hayal meyyal şeylerde, gökkuşağının renklerinde, ...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayal-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstersen', 'i-stersen-nesrin-ozyayci-xyz40', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstersen, 

İstersen dünyanın öbür ucuna git,

Seni, elimle koymuş gibi bulacağım.

Ruhumla dokunacağım gölgene

Dokunuşların en anlamlısı

Ve en yücesiyle, sana ulaşacağım

(Gaziantep, 2000)', 'İstersen,  İstersen dünyanın öbür ucuna git, Seni, elimle koymuş gibi bulacağım. Ruhumla dokunacağım gölgene Dokunuşların en anlamlısı Ve en...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/istersen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyin Nesi?', 'neyin-nesi-yuksel-akyuz-jc7sp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güllerimin üstünde

Uçuşan tüller gibi

Savrulup gidiyor seher yeli

Saçlarımı Okşamadan

Devirip geçen

Bu rüzgar da neyin nesi? 

Gözyaşlarım damlıyor günlüğüme

Nisan yağmurları acelesinde

Acemi bir suçlu gibi

Önüne bakan 

Bu gözler de neyin nesi? 

Sözüm var sevmeye her şeyi

Acılarım, bağışladım hepinizi

Sevgi kemiricileri

Size adıyorum bu şiiri

Göğsüme gürültüyle vuran

Bu deli yürek de neyin nesi?', 'Güllerimin üstünde Uçuşan tüller gibi Savrulup gidiyor seher yeli Saçlarımı Okşamadan Devirip geçen Bu rüzgar da neyin nesi?  Gözyaşlarım da...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Akyüz']::text[], 8.5, '{"poet":"Yüksel Akyüz","poet_slug":"yuksel-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/neyin-nesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen;', 'sen-nesrin-ozyayci-83hyq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen; 

Güneşin hiç batmadığı

Özgürlük ülkenden gönderdiğin

Işıkla

Aydınlattın uzaklardaki 

Karanlık  ülkemi.

(Gaziantep, 2000)', 'Sen;  Güneşin hiç batmadığı Özgürlük ülkenden gönderdiğin Işıkla Aydınlattın uzaklardaki  Karanlık  ülkemi. (Gaziantep, 2000)...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-389-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Kokar Gurbet Akşamı', 'huzun-kokar-gurbet-aksami-necmi-unsal-8eo64', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep hüzün  kokar  gurbet  akşamı.

Sıla  burunda  tütmeye  görsün! 

Tırmalar keder  kuşu   adamı.

Zaman  hasreti  gütmeye  görsün! 

Ciğerin  yanar ve  erir  yağın.

Çile  hortumu  yutmaya  görsün! 

Hiç  olup gider en  güzel  çağın.

Ömür  çetele  tutmaya  görsün! 

21 Mart 2004 Pazar, Danimarka-Køge  00.01

5+5', 'Hep hüzün  kokar  gurbet  akşamı. Sıla  burunda  tütmeye  görsün!  Tırmalar keder  kuşu   adamı. Zaman  hasreti  gütmeye  görsün!  Ciğerin  ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huzun-kokar-gurbet-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler', 'sairler-gokhan-oflazoglu-ve9oi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şairler anteni hayatın

sahte yayınları gerçeğe

dönüştüren.

Şairler tokattır, duyarsız

gözlerinizden bezen.

Şairler; yaralı kuşları

gökyüzünün, yerli yersiz

ölümden bahseden.

Şairler hayal ülkesinin erleri

bütün savaşlarda yenilen.

Şairler olmasa ne kadar

rahatsınız. Çok kalmadı, 

onlar da silinir gider zaten.

13/05/2004', 'Şairler anteni hayatın sahte yayınları gerçeğe dönüştüren. Şairler tokattır, duyarsız gözlerinizden bezen. Şairler; yaralı kuşları gökyüzünü...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sairler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-nesrin-ozyayci-16qf1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana baharı anlat, dizelerinde,

Çiçekleri, arıları, kelebekleri,

Doğayı anlat doğallıklar içinde.

Bana sevdayı anlat,

Bakışlardaki heyecanı

Uzaklıklardaki özlemi anlat

Bana yaşamı anlat

Umutsuzluklardaki umudu

Kayıplardaki acıyı anlat bana.

Kucağımda çocuk ol,

Deliliklerden söz et bana

''baharda nisan fırtınasını'' anlat bana.

Yağmurda nasıl ıslandığımızı anlat,

Bahar kokan yaşamdan söz et,

Yaşadıklarımızı anlat. 

Her baharda ''bir nisan ''gününü anlat.

Hizmetkarlığımı yaşat bana 

Senle olan duygularımı yaşat.

Kulaklarıma fısıldayan nağmelerini,

Saçlarıma taktığın 

Kır çiçeklerini anlat

Bana baharı anlat hayat boyu

''baharda nisan fırtınasını'' anlat.

(Gaziantep, 2000)', 'Bana baharı anlat, dizelerinde, Çiçekleri, arıları, kelebekleri, Doğayı anlat doğallıklar içinde. Bana sevdayı anlat, Bakışlardaki heyecanı ...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bahar-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-nesrin-ozyayci-gfyo7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mızrabı gönlüme vurmaktayım,

Bir yanım uzaklarda,

Filistin de, Bosna da, Güneydoğuda

Gönlüm yok olmuş boşlukta, arayışta

Kaybolmuş çocukluğum var arada.

Geleceğimi, umutlarımı yok ettiler,

Gönlümü çalamadılar, kaldı bedenimde.

Çocukluğum ağlıyordu,

Dokunmana gerek yok,

Ağlıyordum yürekten 

Günlerdir saçlarım taranmamış,

Aç, susuz, perişan,

Ayaklarım pabuçsuz

Ateş altında yaşayan, toz dumanda boğulan

Gözlerim görmez olmuş.

Suçluydum

Çünkü Bosnalıydım, Filistinli,

Uçurtma uçurtmak yasaktı bana.

Ben savaşan bir dünyada doğmuştum,

Gizemli yasak bir savaş çocuğuydum

Hasretim, özlemim, gizemim bundandı

Savaş çocuğuydum haberiniz yok.

(Gaziantep, 2001)', 'Mızrabı gönlüme vurmaktayım, Bir yanım uzaklarda, Filistin de, Bosna da, Güneydoğuda Gönlüm yok olmuş boşlukta, arayışta Kaybolmuş çocukluğu...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cocuklugum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şemsiyelik Yalnızlık', 'bir-semsiyelik-yalnizlik-nesrin-ozyayci-2z8ft', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığım; 

Bir şemsiye altına sığabilmek 

Birlikte yan yana yürüyüp,

Yağmurda ıslanmamak

SevgiDost paylaşımı olsa gerek

Adı yalnızlıksa eğer.! 

(Gaziantep, 2001)', 'Yalnızlığım;  Bir şemsiye altına sığabilmek  Birlikte yan yana yürüyüp, Yağmurda ıslanmamak SevgiDost paylaşımı olsa gerek Adı yalnızlıksa e...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-semsiyelik-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzellikleri Görebilmek / anı', 'guzellikleri-gorebilmek-ani-k-muran-esen-cmm4y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar önceydi.  Bir aile dostumuzun  kızlarının nikâh töreni  için Ankara’ya gitmiştik.  Nikâh  Atakule’deki nikah salonunda kıyılacaktı. Nikâha   son anda yetiştik. Nikâh merasimleri bende hep hüzün uyandırmıştır. Gözlerim dolu dolu izlerim  töreni.  “Mutlu günlere ilk adımlarını atan gençleri ilerde acaba nasıl günler bekliyor? “diye düşünürüm.”Her evlenen mutlu olmak için evlenir. Acaba bu gençler mutlu olabilecek mi? ” diye kendi kendime sorarım.

                            Kızım ve eşimle birlikteydik. Onlar  asansöre binerek kuleye çıkmak istediler. Benim onlarla birlikte kuleye çıkmam gibi bir  durum asla söz konusu olamazdı. Çünkü ben asansöre binmem. Daha doğrusu binemem. Dört beş  katlı bir apartmanın asansörüne  bile. Bir- iki dakikalık asansör yolculuğu, bana yıl kadar uzun gelir. Otuz katlı binanın merdivenlerini tırmanmayı göze alırım, yine asansöre binmem. Asansörün içinde nefes almakta güçlük çektiğimi hissederim.Asansör bana kibrit kutusu kadar küçük gelir.  Asansöre binenlere de  “Merdiven çıkmanın çok sağlıklı  olduğunu”  söylerim. Asansör korkuma bir mazerettir bu aslında.Yıllardır bana   birileri  “Canım ne var korkacak! ” dediler durdular hep. Bu sözler hiçbir işe yaramadı.  Asansör korkusu bu işte. Daha doğrusu fobi.  Hiç mantıklı bir açıklaması yok.  Kısacası  binmedim asansöre. Bir kenarda  eşimin ve kızımın dönmelerini beklemeye başladım.

                            									Çok iyi gözlemciyim.  Nerede olursam olayım  etrafımı devamlı gözlemlerim. Etrafımda hep bir şeyler ararım. Bu beni hem can sıkıntısından kurtarır, hem bana mutlaka birşeyler kazandırır. Öyle dalgın gözlerle bakmam etrafıma. Gördüklerimden, izlediklerimden, hatta duyduklarımdan bir şeyler yakalamaya çalışırım. Doğal olarak da bunun sonucunda; birçok kişinin gözünden kaçırdığı  şeyleri yakalayabilirim....

                           O gün de öyle oldu. Eşimin ve kızımın dönmelerini beklerken  etrafı izlemeye başladım. Buradaki insanların hemen hepsinin çok iyi giyimli olduklarını farkettim. Normal bir zamanda, herhangi bir yerde görebileceğiniz  insanlar topluluğu değildi sanki. Özel seçilmiş, belli bir kültürü almış insan topluluğu  gibiydi. Nedense, o insanlar içinde kendimi çok farklı hissettim. Sanki onlardan ayrı, onlardan uzak.

                           O arada biraz ötede iki erkek çocuğu dikkatimi çekti. Nereye gitsem, önce çocuklar çeker dikkatimi, sonra çiçekler. Çocukların  ikisi de ilkokul çağında görünüyordu. Üstleri başları, diğerlerinin aksine pek muntazam değildi. O çevredeki insanlardan farklı görünüyorlardı.  Ancak, öylesine rahat davranıyorlardı ki çocuklar; kendilerinden başka hiç kimse  yoktu sanki orada.  Birbirleriyle itişiyorlar, kakışıyorlardı.  Kovalamaca oynuyorlardı. Tırabzan şeklinde uzatılmış demirlerin altından geçiyor;  üstüne çıkıp yere atlıyorlardı. Bütün dikkatimi onlara vermiştim. 

   

             Bana öğrencilerimi hatırlattılar. Neşeleri hoşuma gitmişti. Onlarla beraber ben de eğleniyordum. Birdenbire kanım kaynayıvermişti onlara. Rahat tavırları, umursamazlıkları  ilgimi çekmişti. Yaptıklarının doğru olup olmadığı umurlarında bile değildi. Benim onları izlediğimin farkında  değillerdi. Neşeyle oyunlarına devam ettiler. 

                   Bir ara güreş tuttular, yerlerde yuvarlandılar. İçimden  “Çocuk olmak ne güzel,” diye geçirdim. Doğrusu onların yerinde olmak istedim. Ya da onlarla birlikte oynamak. Biz büyüklerin yapması hoş karşılanmayacak şeyler,  onlar için normaldi. Çocukların  davranış özgürlüğü vardı. Yanlış bir şey yapsalar dahi onlara kızmıyorduk. ” Çocukluk işte! ”  deyip geçiyorduk. Onlar, büyüklere nazaran  özgürdüler, rahattılar. İşte bu izlediğim çocuklar da böyleydi.

                   Ben onları keyifle izlerken  az ötede, iyi giyimli iki genç bayanın; bu iki çocuğa bakarak, yüzlerini ekşiterek birşeyler konuştuklarını farkettim.  “Ay! ” dedi birisi. ” Şu çocukların pisliğine bir bak. Üstleri başları kir içinde.”......  Dikkatle baktım, gerçekten öyleymiş. Onlar söylemeden hiç farketmemiştim.  Devam etti aynı şık bayan:  “Ayaklarında çorap da yok galiba.”......  Çocukların ayaklarına baktım, gerçekten çorap yoktu. Bu arada çocuklar itişip kakışmaya, yerde yuvarlanmaya, gülüşmeye devam ediyorlardı. Sonra diğer şık bayan aldı sözü:  “ Şunların boyunlarına  bak. Kirden, kaplumbağa  gibi olmuş. Tırnakları da kepçe gib,”  dedi iğrenerek ve yüzünü buruşturarak. 

                      Benim çocuklarda görmediğim şeyleri o şık bayanlar görmüşlerdi. Bu  bayanlar da nereden çıkmıştı! Onlardan önce bu sevimli yavruları ne güzel izliyordum. Ne kirlerini görmüştüm, ne paslarını, ne de uzun tırnaklarını. Canımı sıkmıştı   bayanlar. Neşemi bozmuşlardı. Güzel bir rüyadan uyandırmışları beni.

                          Bu arada eşimle kızım kuleden indiler. Hemen arabamıza atlayıp, dönüş yolculuğuna başladık. Onlar Atakule’deki asansörden gördüklerini bana anlatıyorlardı. Ben ise, biraz önce gördüklerimi ve o iki bayanın konuşmalarını düşünüyordum. O bayanların  çocuklara karşı nasıl böyle acımasız ve katı olabildiklerine  anlam veremiyordum. O bayanlarla benim, çocuklara bakış açımız ne kadar farklıydı. Onlar çocuklardaki yanlışları (“çirkinlikleri”  demeye dilim varmıyor)    görmüşlerdi, ben güzellikleri görmüştüm. Ben çocukları sevmiştim, onlar iğrenmişlerdi. Çocukları izlerken benim yüzüm aydınlanmıştı, onların ise yüzleri ekşimişti. Bu aslında o kadar doğaldı ki. Çünkü ben bir öğretmendim. Öğretmene yakışan da buydu. Ben eğer çocuklarda var olan güzellikleri göremeseydim, yıllarca severek öğretmenlik yapabilir miydim! Öğrencilerimin uzun tırnaklarından, kirli ellerinden iğrenseydim, öğretmen  olabilir miydim? Ya da ne kadar başarılı olabilirdim? 

                              Ben çocuklardaki güzellikleri gördüm hep. O güzelliklerden yola çıktım.   İşte iyi bir öğretmen olmanın sırrı buradaydı: Çocukları sevmekte, onlara  sevgi dolu bir yürekle bakmaktaydı. Onları anlayabilmekteydi. Bana ikide bir  “ Emekliliğiniz gelmiştir artık. Hâlâ niçin emekli olmuyorsunuz? ” diye soranlara verilecek cevap da burada gizliydi aslında.

 Eğer çocukları seviyorsanız, onlardaki güzellikleri yakalayabiliyorsanız, onların herşeyine katlanabilirsiniz. Çocukların eksilerini değil, artılarını göreceksiniz. O artılardan yola çıkacaksınız. Eğer yanlışları düzeltmekten işe başlarsanız, asla başarılı olamazsınız. Çocukları küstürürsünüz. Sonra, seveceksiniz, sevdiğinizi  mutlaka hissettireceksiniz. Çocuk sevildiğini bilecek. Öğretmeni tarafından sevildiğini  bilen çocuğa güven gelir, öğrenme isteği gelir. Onların duyduğu bu güven, sevilme duygusu  ve öğrenme isteği,hem çocuğu başarıya götürür  hem öğretmeni. Sonra da  o eksiler  zamanla  kaybolur gider. 

                         Çocuklarda, çoğumuzun göremediği öyle  güzellikler var ki. Bunu ancak,  çocuklara sevgiyle yaklaşanlar görebilir. Öğretmenlik yıllarımda, her çocuktaki güzelliği görmekte hiç zorlanmadım. Kendilerini çok iyi anladım, onların dünysına giridim.O nedenle, onları eğitirken ve öğretirken, pek fazla sıkıntı yaşamadım. Çocuklara bu şekilde yaklaşmam, başarılı olmamda çok büyük bir rol oynadı. Benim işimi kolaylaştırdı. 



                         Çocuklar bir dünya, çocuklar bir kaynak.Onlara yaklaşmayı deneyin bir.Eminim, benim gördüklerimi siz de göreceksiniz....Ama önce çocuklara  sevgi dolu  bir  yürekle bakmayı öğrenin.Lütfen!', 'Yıllar önceydi.  Bir aile dostumuzun  kızlarının nikâh töreni  için Ankara’ya gitmiştik.  Nikâh  Atakule’deki nikah salonunda kıyılacaktı. N...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/guzellikleri-gorebilmek-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-nesrin-ozyayci-vuv1x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk adımım küçük ve yavaştı, 

Ellerim kollarım bağlı

Dilim söylemezdi, 

Bilmezdim hani konuşmayı,

Süründüm, emekledim, kalktım, 

Tutundum bir dala.

Tutunarak yürüdüm, ağırca,

Hızım kesildi meydanda, bir başıma,

Başardım bütünümle, azimle

Yaşadım, yoruldum yoğrulurcasına

Özdeşleştim çiçekle, çocukla, tikenle

Bülbülle, kuşlarla ötüştüm,

Dinledim, dinlettim uzunca

İçimde, dışıma taşan güzelliklerle

Hoşluklarla yarıştım meydanlarda

Yiğitçe, onurluca, hakça

Haykırdım sesimi duymayanlara

Orada, burada, her yerde

Yanlışlar bağladı, yasaklar dağladı

Hoşgörü sınırları sınırladı beni

Yaşadım, koştum, düştüm 

Ama eğilmedim, eğdirmedim 

İnsanca yaşamak adına yaşadım. Bir ömür.

(Gaziantep, 2000)', 'İlk adımım küçük ve yavaştı,  Ellerim kollarım bağlı Dilim söylemezdi,  Bilmezdim hani konuşmayı, Süründüm, emekledim, kalktım,  Tutundum bi...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/omur-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çocuk', 'bir-cocuk-nesrin-ozyayci-q1o60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aydın yüzlü bir çocuk,

Aydınlık bir geleceğe,

Aşık atıyordu, çember çeviriyordu,

Bilye yuvarlıyordu, derin çukurlara,

Işık yakıyordu, gelecek yarına 

Işıl ışıl gözleriyle, güneşe bakar gibiydi,

Senaryolar çiziyordu yüzünde

Bir çocuk, tek ayağı üzerinde,

Zıplıyordu, zıp, zıp

Bana koşuyor, çarpıyordu delicesine

Haylaz, yaramaz bir çocuktu,

İçimde kalan.

Çocukluğumu tamamlıyordu.

(Gaziantep, 2001)', 'Aydın yüzlü bir çocuk, Aydınlık bir geleceğe, Aşık atıyordu, çember çeviriyordu, Bilye yuvarlıyordu, derin çukurlara, Işık yakıyordu, gelece...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-cocuk-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteklerim', 'i-steklerim-nesrin-ozyayci-bcdyc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yorulmamı istediğindendir yorgunluğum 

direnmemi istediğindendir direncim

koşturdun beni güzelliklere,

koştum...

tek başıma yaşamamı istedin,

çokluklar içinde, yapayalnız

yorgunluğum bundandır

isteklerinden yoruldum.

(Gaziantep 2001)', 'yorulmamı istediğindendir yorgunluğum  direnmemi istediğindendir direncim koşturdun beni güzelliklere, koştum... tek başıma yaşamamı istedin...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/isteklerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz Ruhlar', 'olumsuz-ruhlar-nesrin-ozyayci-il363', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her mevsimde canlıdırlar 

Ayrı bir yaşam, ayrı bir heyecanları vardır

Ne uğursuzluğu vardır gecelerinin,

Ne de yığılmış sorunlarının çokluğu

Ölümsüz ruhlar asla şaşırtmazlar.

(Gaziantep, 2001)', 'Her mevsimde canlıdırlar  Ayrı bir yaşam, ayrı bir heyecanları vardır Ne uğursuzluğu vardır gecelerinin, Ne de yığılmış sorunlarının çokluğu...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olumsuz-ruhlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-nesrin-ozyayci-9p255', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güle güle demeğe 

Seni uğurlamaya geldim

Fırtınada, içime işlemiş ayaz soğukluğuyla,

Kutuplardan geldim

Harmanda elleri nasırlı

Dudakları çatlamış

Bir ağustos sıcağında,

Afrika’dan geldim.

Yalınayak bir köy kadını olarak geldim

Sarılmak içimden gelmiyor 

Sen istedin bu vedayı

Git...

Yolun açık olsun,

Unutmak istiyorum sadece, 

Her şeyi silip süpürüp

Yeniden başlamak istiyorum.

O, yaşam denen çukura 

Bir kere değil bin kere düşsem de

Sadece kendim olmak istiyorum

Dostça kal...

(Gaziantep, 2001)', 'Güle güle demeğe  Seni uğurlamaya geldim Fırtınada, içime işlemiş ayaz soğukluğuyla, Kutuplardan geldim Harmanda elleri nasırlı Dudakları ça...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hoscakal-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İman Beni', 'i-man-beni-halil-karabulut-cwmmo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alemde ne gördüm ise

Hep eyledi hayran beni.

Düşürdü çok düşünceye,

Eylediğim seyran beni.

Yere baktım göğe baktım,

Düşünmekle geçti vaktım.

Aczimi bildim,bıraktım

Hak yaratmış noksan beni.

Ak hava,su,kara toprak

Yetiştirir yeşil yaprak.

Çiçek açar kırmızı,ak

Şaşırır gülistan beni.

Dışında ten,içinde can,

Yaşar insan,nebat,hayvan.

Bu intizam,devri devran

Hayretlere koyan beni.

Sır içinde sır var ama,

Çözülmez işler,muamma! 

Gözüm görmez,bakar ama

Perdelemiş süphan beni.

Halilim,sözü bitirem,

Yetmez ki akıl yetirem.

Koymaz,boş verem oturam

İçimdeki iman beni...', 'Alemde ne gördüm ise Hep eyledi hayran beni. Düşürdü çok düşünceye, Eylediğim seyran beni. Yere baktım göğe baktım, Düşünmekle geçti vaktım....', ARRAY['Türk Edebiyatı','Şiir','Halil Karabulut']::text[], 8.5, '{"poet":"Halil Karabulut","poet_slug":"halil-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iman-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-nesrin-ozyayci-qnbss', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günün ilk ışığı, kuş cıvıltılarıyla

Gelmek istiyorum habersizce,

Gökyüzünün kızıllığı, utancımın allığıyla,

Kapını aralayarak girmek istiyorum.

Uyanıksın biliyorum 

Bu sevdanın uykusuzluğuyla

Koynunda uyumak istiyorum

Çocuk gibi öperek, severek

Koklayarak uyumak istiyorum.

(Gaziantep, 2001)', 'Günün ilk ışığı, kuş cıvıltılarıyla Gelmek istiyorum habersizce, Gökyüzünün kızıllığı, utancımın allığıyla, Kapını aralayarak girmek istiyor...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sana-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hissi Kablel Vuku', 'hissi-kablel-vuku-cafer-tayyar-ozkan-hcsfs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cihana bir daha gelmek nasip olsa.

Kaderime senin adını yazardım.

Sana bir daha gelmek nasip olursa.

Saygını, sevgimle paylaşmanı isterdim...

Gönülde yatan candan parçasın,

Kalpte sönmeyen aşk ateşisin,

Sen benimsin, benim olacaksın.

Ey can tanesi, 

Ne seninle, ne de sensiz... 

Zor kazanılan, kolay kaybedilmez,

Canan hüzünlüyken, cana kıyılmaz,

Hasretin gece karanlığında depreşirken,

Sensiz nefes almaya, inan sabredilmez...

Hayatta her şey kaybedilir, unutulur, 

Lakin gerçek sevgi asla unutulmaz.

O, canla istenir, düşlerde yaşatılır,

Ayrı bir dünya kurulur gönüllerde,

Hissi kablel vuku bulur kalplerde...

19.05.2003 13:55 Bursa', 'Cihana bir daha gelmek nasip olsa. Kaderime senin adını yazardım. Sana bir daha gelmek nasip olursa. Saygını, sevgimle paylaşmanı isterdim.....', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hissi-kablel-vuku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşündürür', 'dusundurur-halil-karabulut-hwj9o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayran eder gökler yerler,

Dağlar beni düşündürür.

Kudreti-Hak,gizli sırlar,

Bağlar,beni düşündürür.

Dünya bir değirmen taşı,

Döner durur kendi başı.

Acep nedir desem yaşı,

Çağlar beni düşündürür.

Bu alem bir kitap demek,

Mümkün değil şerh eylemek.

Anasından doğan bebek,

Ağlar,beni düşündürür.

Halil bu hikmeti bilmez,

Gelen gider,burda kalmaz.

Ölenlerden haber gelmez

Sağlar beni düşündürür.', 'Hayran eder gökler yerler, Dağlar beni düşündürür. Kudreti-Hak,gizli sırlar, Bağlar,beni düşündürür. Dünya bir değirmen taşı, Döner durur ke...', ARRAY['Türk Edebiyatı','Şiir','Halil Karabulut']::text[], 8.5, '{"poet":"Halil Karabulut","poet_slug":"halil-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dusundurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşamayız', 'kavusamayiz-caner-kuru-y0wi2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kader bu sevgilim ağlama boşa

Çekmek zorundasın gelince başa

Ağlasan da değmez döktüğün yaşa

Dağlar kavuşsa biz kavuşamayız

Rüyalar da bile buluşamayız.

Hayalden öteye gitmez bu sevda 

Doğru olan tek şey tek çare veda

Neyin var neyin yok etsende feda

Dağlar kavuşsa biz kavuşamayız

Rüyalar da bile buluşamayız.

Dilimi yakıyor demesi bile 

Biliyorum çok zor bitmesi böyle

Yansa da gönlümüz aynı ateşle

Dağlar kavuşsa biz kavuşamayız

Rüyalar da bile buluşamayız.', 'Kader bu sevgilim ağlama boşa Çekmek zorundasın gelince başa Ağlasan da değmez döktüğün yaşa Dağlar kavuşsa biz kavuşamayız Rüyalar da bile ...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kavusamayiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-necmettin-davulcu-hucqc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevgi sensin

sevgi gözlerin

ellerine konan öksüz bir kuş sevgi

sonsuz açlıkta bir yürek

bir dokunuş

sevgi bir bulut

sevgi mavide kırmızıyı görmek

dokunmak bir çocuğa

sevgi yıldızları gözlerinde saklamak

sevgi sensin

sevgi gözlerin', 'sevgi sensin sevgi gözlerin ellerine konan öksüz bir kuş sevgi sonsuz açlıkta bir yürek bir dokunuş sevgi bir bulut sevgi mavide kırmızıyı g...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgi-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlidir', 'gizlidir-halil-karabulut-zz2p4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kainatta neye ettimse nazar,

Gördüm ki Hikmet-i Suphan gizlidir.

Dünya,teşhir olmuş bir büyük pazar,

Hemi satan,hemi alan gizlidir.

İbretle seyrettim ben bu şemayı,

Gördüm onda türlü türlü simayı.

seren bu meydana bunca eşyayı,

Getiren,götüren kervan gizlidir.

İster zahir,ister batından giriş,

Kavramaz bu sırrı gözdeki görüş.

Hesaplı,kitaplı yapılmış her iş

Her şeyde ayrı bir plan gizlidir.

Anlamaz Halik''in kudretin kişi,

Çözülmez muamma onun her işi.

Kah erkek doğurur ana,kah dişi

Olunmaz bu hikmet,beyan gizlidir.

kurtlar,kuşlar,bütün envai sinek,

Bilir geldiğini zamanı tünek.

Arada vasıta kırmızı inek,

Yeşil otta,beyaz ayran gizlidir.

Birer mahluk iken,kurt ile koyun,

Arada düşmanlık bilmem ne oyun? 

Hocam,bilir misin içtiğin suyun

İçinde ateşi suzan gizlidir.

yıldızlar,şehrini kurmuş fezaya,

Hareket verilmiş güneşe,aya.

Denizler seyahat eder semaya,

Sanma sözlerimde yalan gizlidir.

bitmez yaratanın bu inkilabı,

şekilden şekile sokar turabı.

Halil der,alem bir kanuna tabi,

Kanun gizli,icra,kılan gizlidir...', 'Kainatta neye ettimse nazar, Gördüm ki Hikmet-i Suphan gizlidir. Dünya,teşhir olmuş bir büyük pazar, Hemi satan,hemi alan gizlidir. İbretle ...', ARRAY['Türk Edebiyatı','Şiir','Halil Karabulut']::text[], 8.5, '{"poet":"Halil Karabulut","poet_slug":"halil-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gizlidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Yeli', 'seher-yeli-necmettin-davulcu-ixx9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'neden gittin gurbet ele

sen seher yeli misin

aklımı başımdan aldın

gül menekşe nergis misin

dağ başında gezer oldum

yaprak yaprak

             deli deli tozar oldum

akil oldum viran oldum

çağlar iken sende durdum', 'neden gittin gurbet ele sen seher yeli misin aklımı başımdan aldın gül menekşe nergis misin dağ başında gezer oldum yaprak yaprak           ...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seher-yeli-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keskin Yel', 'keskin-yel-naime-erlacin-6j9lk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uzaktan gelip 

kıyılarıma vuran rüzgâr! 

acının kokusunu alıyorum

beşerin hikâyesini 

kemirgen sevdasını insanın

rengi değişiyor göğün

güneşi devşiriyor bulutlar

kalbimde 

çığlıklar

yalnızlık sarıyor her yanımı

titriyorum 

içim ağlıyor 

tutamıyorum rüzgârı

keskin yeli sever dizeler

lodosa veririz yaprakları

gönlümüz 

rüzgârın göğsünde inler

es keskin yel! 

uğultunun 

can alıcı terazisi

ne diyebilirim ki

acı tartıyoruz

büyümek buysa 

yaşıyoruz! 

(13 Mayıs 2004)', 'uzaktan gelip  kıyılarıma vuran rüzgâr!  acının kokusunu alıyorum beşerin hikâyesini  kemirgen sevdasını insanın rengi değişiyor göğün güneş...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/keskin-yel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmez ki Ne Zaman Nerde', 'bilinmez-ki-ne-zaman-nerde-necmettin-davulcu-kfpvg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'boşversem dünyayı arada bir

unutsam sevinçlerimi

görmesem

            yoksaysam hüzünlerimi

sevdiğim kadınlar olmasa hiç

adımı bilmesem

dere kenarında otursam

                   ama akan suyu görmesem

yürürken patikada örneğin

                   ayağıma takılan çakıltaşlarını duymasam

bir gece

korkularımın yüreğimi doldurduğu an

gökten saçlarına kayan yıldızların yerine

ben baksam yeryüzüne

mutluluğu

acıyı

sevgiyi koklasam insanların yüzünde

gözbebeklerine dolsam

bilinmez ki ne zaman nerde', 'boşversem dünyayı arada bir unutsam sevinçlerimi görmesem             yoksaysam hüzünlerimi sevdiğim kadınlar olmasa hiç adımı bilmesem dere...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bilinmez-ki-ne-zaman-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Bombardımanı', 'sevgi-bombardimani-nesrin-ozyayci-n4ylz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yerel bir Türk kadınından evrensel kimliğimle 

Bir sevgi bombardımanı yağsın isteğim

Sınırsız evrenin her köşesine 

Savaşan dünyanın barış kokan nefesine

Bir sevgi bombardımanı  yağdırmaktır istediğim

Gök kubbeden yeryüzüne sicim gibi

Bardaktan boşanırcasına

Bir sevgi bombardımanı yağdırmak istediğim

Tüm dinlerden mezheplere aşiretlere insanlığa

Sevgi bombardımanı yağdırmak istiyorum

Gök kubbeden yeryüzüne 

Sicim gibi bardaktan boşanırcasına...

(Gaziantep, 2001)', 'Yerel bir Türk kadınından evrensel kimliğimle  Bir sevgi bombardımanı yağsın isteğim Sınırsız evrenin her köşesine  Savaşan dünyanın barış k...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-bombardimani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekonomik Aşk', 'ekonomik-ask-abdullah-atay-9jpqb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gidişle; 

Badem gözlü.

Bal sözlü.

Elma yanaklı.

Kiraz dudaklı.

Balık etli.

Yufka yürekli.

Süt tenli.

Çikolata benli.

Fıstık mı fıstık! ..

Tatlı mı tatlı! ..

Bir sevgili bulacağım.

İşte o zaman; 

Çarşı pazar dolaşmayacağım...

Açıp gönül soframı,

Onunla doyacağım...', 'Bu gidişle;  Badem gözlü. Bal sözlü. Elma yanaklı. Kiraz dudaklı. Balık etli. Yufka yürekli. Süt tenli. Çikolata benli. Fıstık mı fıstık! .....', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ekonomik-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum...', 'gidiyorum-tulay-sustam-jtoc3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Heybeme doldurdum yalnızlığımı...

İlk defa yolculuğa çıkarken yanıma bir şey almıyorum...

Sabahın ilk saatlerinde çıkacağım yola

Giydim yine her zaman ki gibi beyaz takımlarımı

Metruk bir han misali yüreğim

Kuşandım bütün pusatlarımı

Denizde boğulmazsam dayarım sakaklarıma

Elim bir kez olsun titrerse namerdim...

Pişman olursam bu yolculuktan

Arkama dönüp bakarsam namerdim...

Küçük bir kayık götürür beni

Kürek çekerim akıntıya doğru...

Hem ağlarım, hem kürek çekerim

Gözyaşlarımla kayığımı batırırım

Nasılsa yüzmeyi bilmem

Çırpınırsam, bağırırsam namerdim...

Dalgalar savurur cansız bedenimi

Bir yosunun kolların da takılır kalırım

Hiç kimseden görmediğim sıcaklığı hissederim

Sonra bir balıkçı ağına takılırım

Üç, beş balıkçı asırlılar ağlara

Çekerler beni kendilerine doğru

Çıkarırlar su üstüne...

Şaşırır öylece kalırlar

Gözlerim açık giderim

Kapatmaya çalışırlar gözkapaklarımı

Onlar inadına kapanmazlar

Hiçbir şey de gözüm kalmadı

Her şeyi de yaşadım, yaşattım

Hiç tanımadığım insanların derdine yandım

Acılarına oturup ağladım

Karıncayı bile incitmedim

Düşene hiçbir zaman tekme atmadım

Tuttum ellerinden aydınlığa çıkardım

Yanarım, ağlarım, sızlarım

Anne olamadığıma yanarım

O yüzden gözlerim açık giderim

Kimse arkamdan bir damla gözyaşı dökmesin

Bir vedayı bile çok görüyorum artık

Kimse beni suçlamasın....

Geride hiçbir şey bırakmadığımı zannetmesinler

Kalemimi, kağıdımı okula hiç gitmeyen

Ekmek parası için ayakkabı boyayan

Yüreği bembeyaz, elleri simsiyah Mustafa’ya bıraktım

Yüreğimi; hiç sevilmemiş, acıların kadını

Her zaman kırmızı güller satan Emine Teyze’ye bıraktım

Şiirlerimi; “Abla ne olur tartılır mısın? “ diyen

Minicik elleri, siyah saçları, al al yanakları olan

Esmer güzeli Gönül’e bıraktım

Ben ona İrem diyorum...

Kızım olsaydı eğer adını İrem koyardım

Gelir mezarımın başına minicik ellerini açar

Benim için duâlar eder...

Mustafa şiirler yazar, İrem bana şiirler okur

Emine Teyze tomurcuk kırmızı gülleri bırakır gider

Mustafa inanmaz öldüğüme...

En güzel boyadığı ayakkabıları getirir bana

“Tülay Abla hadi kalk yerinden gezmeye gidelim “ der.

Ne onu ben duyarım, ne de o görür benim gülümsediğimi

Beni çok severler, bende onları...

Ben onların biricik ablaları...

Onları bırakıp gittiğime yanarım...

Onlar kadar kimse beni sevmedi ki...

(İstanbul, 13.05.2004)', 'Heybeme doldurdum yalnızlığımı... İlk defa yolculuğa çıkarken yanıma bir şey almıyorum... Sabahın ilk saatlerinde çıkacağım yola Giydim yine...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/gidiyorum-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim külüstür', 'bizim-kulustur-halil-karabulut-qs60f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Epeyce eskimiş bizim külüstür,

Bir gün bir çamura çöker bir yerde.

Fireni bozulur,iş işten geçer,

Ya da rot çubuğu çıkar bir yerde.

Bunca yükü elli yıldır götürür,

Bir gün işi yarı yolda bitirir.

Ya lastik patlatın janta oturur,

Ya bilya dağıtır teker bir yerde.

Çalıştıkça hırıl hırıl hırlıyor,

İç aletler cırıl cırıl cırlıyor.

Ses bozuk geliyor,motor zorluyor

korkarım ki,yatak yakar bir yerde.

Hasılı efendim,arıza çoktur,

Tamir mümkün değil,parçası yoktur.

Her usta anlamaz,tabibi tektir

O da gizli gizli bakar bir yerde.

Anla aşık halil,bu haller niçin? 

Zamanı yaklaştı ebedi göçün! 

bir de hurdasını kaldırmak için

Emmi,dayı zahmet çeker bir yerde...', 'Epeyce eskimiş bizim külüstür, Bir gün bir çamura çöker bir yerde. Fireni bozulur,iş işten geçer, Ya da rot çubuğu çıkar bir yerde. Bunca yü...', ARRAY['Türk Edebiyatı','Şiir','Halil Karabulut']::text[], 8.5, '{"poet":"Halil Karabulut","poet_slug":"halil-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bizim-kulustur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyetim', 'vasiyetim-nesrin-ozyayci-hwj5l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben baharda ölmeliyim

Tan yeri ağarırken, 

Elimde kalemim, aklımdan geçenlerle

Yazarken ölmeliyim.

Herkes uykuda ben uyanıkken,

Sessiz bir sabahın eşiğinde

Gecemin gündüz olduğu bir karanlıkta

Ölmeliyim...

Kekik kokan mutfağımda, 

Önümde kitabım

Yemek masamda otururken.

Yazdıklarım anlamını yitirmişken

Yaşama son düşüncelerimi bağışlamışken 

Üzerimde pazenden bir sabahlıkla

Yazarken ölmeliyim.

Tabakta dilinmiş yarım portakal, 

Kabuğunda sigara  külü silkelenmiş

Ve sigaram halen yanıyorken ölmeliyim.

Öldüğümde bir yolum olsun,

Bir vasiyetim olsun istiyorum yazdıklarımdan; 

Önce Üniversitemin önünden geçmek

Doyamadığım öğrencilerimi anımsamak için

Kütüphanenin önünden geçmek istemiyorum

Yaşarken öldürüldüğüm içerden istemiyorum, 

Evimin dışarıdan pencerelerini görmek istiyorum.

İçeriden baktığım buraları görmek istiyorum.

Balkonumu, sandalyemi sigaramı görmek istiyorum

Kırkayaktan, Maarife doğru

Beklendiğim camları görmek istiyorum

Duygularımı, yaşamımı gömdüğüm iş yerimi

İkinci dünyamı görmek istiyorum

Kırkayak Parkında salladığım çocukluğumla

Vedalaşmak istiyorum...

Uğur Mumcu Parkından geçirin beni

Yaşlılığıma elvedaı çocukluğuma merhaba dediğim,

Yaşadığım salıncakları görmek istiyorum.

Kavaklıkta ağaçlara anlattığım sırlarımla

Vedalaşmak istiyorum.

Yalnızlığımı paylaşan masamı görmek istiyorum

En son çalıştığım kurumun önünden geçirin beni

Kapısı  mutlaka açık olmalı

Telefonları çalıyor olmalı

Terasta öğrencilerim el sallamalı

Hocam demeli... Hocam güle güle demeliler

Bir hoca nöbet tutmalı benim yerime,

Gözyaşı istemiyorum, gerek yok ağlamanıza

Yanımda canıma can katan parçalarım olmalı

Çocuklarım, dostlarım, arkadaşlarım, öğrencilerim...

Yalınayak tartıcı çocuklar,

Sokak çocukları,

Meslektaşlarım, rakiplerim, 

Kuralsız, kravatsız bürokratlar olmalı

Sınırsız bir coşku olmalı

Yaşamımda istediğim, ama olmayan 

Herkes ama herkes

Ellerinde kır çiçekleriyle uğurlamalılar

Benim benle sonsuzluğa yolculuğumda.

Selam söyleyin bütün dostlarıma 

Altmışlı yıllardan, iki binli yıllara

Tüm arkadaşlarıma selam götürün,

Bildik aşina tüm yüzlere selam iletin

Sevenlerime, sevmeyenlerime

Dostlarıma, düşmanlarıma

Çiçekler gönderin,

Şiirler takın yakalarına

Gözlerinde tek damla istemiyorum

Hepsini sevgiyle kucaklıyorum.

Anam karşılamalı beni o çalımlı edasıyla

Son yolculuğunda veda öpücüğünü bir yanağıma bıraktığı

Diğer yanağımı öperek karşılamalı beni.

Sitem dolu ağlamaklı değil 

Gülerek karşılamalı,

Babam mı? yaşamaz ki ben öldüğümde...

Kendi halimle kalmalıyım

Kuşlar ötüşmeli başucumda

En tepede olmalı mezarım, esmeli püfür püfür

Yağmurlar, karlar önce bana düşmeli

Güneş en çok bana vurmalı,

Isınmalı ruhum, ısıtmalı içimi...

İsteğim bunlar, bense ölümümü yaşıyorum.

Gezdirdim bu caddelerde bu mekanlarda

Siz mutlu olun yeter...

(Gaziantep, 2001)', 'Ben baharda ölmeliyim Tan yeri ağarırken,  Elimde kalemim, aklımdan geçenlerle Yazarken ölmeliyim. Herkes uykuda ben uyanıkken, Sessiz bir s...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/vasiyetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümüm', 'olumum-nesrin-ozyayci-6k2an', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün öleceğim. 

Ya beynim kanayacak ya yüreğim

Ölümüm bunlardan olacak.

Habersiz öleceğim, sessizce, bir anda

En fazla bir gecede.

Belki de bir göz kırpışı kadar kısa zamanda.

(gaziantep, 2001)', 'Bir gün öleceğim.  Ya beynim kanayacak ya yüreğim Ölümüm bunlardan olacak. Habersiz öleceğim, sessizce, bir anda En fazla bir gecede. Belki ...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Özyaycı']::text[], 8.5, '{"poet":"Nesrin Özyaycı","poet_slug":"nesrin-ozyayci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olumum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulur', 'unutulur-meral-yagcioglu-z55bu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutulmaz deme sakın

Unutulur

Yaşananlar unutulur

Unutulur sevgililer

Unutur yaralı yürek

Yaşanmış o bitmez

Sevdalar unutulur

Geçmişten kalan 

Yangın günlerin

Külleri savrulup

Uçar gider kaf dağının ardına

Terk edenler unutulur

Unutulur unutup gidenler

Sürse de birkaç gün kırgınlık

Asırlar boyu gelse de insana

Zaman takılıp kalsa da sonsuzda

Ölüm demek olsa da ayrılık

Aşk ateşinde kavrulan

Gönül kendini yeniler

Zaman çalar yüreğine

Deva olur derdine güneşle ay

Mehtapla yıldızlar sevişir kumsalda

Ölü karanfilleri söküp atar yüreğinden

Yerine  gelincik bahçesi

Düzenler elleriyle

Gönül teli bir türkü tutturur

Aşkın sevdanın türküsüyle

Yeni sevdalara

Yelken açar

Yeni umutlara

Merhaba der

Kırık aşk hikayeleri unutulur

Unutulur unutup gidenler

		17/08/1994', 'Unutulmaz deme sakın Unutulur Yaşananlar unutulur Unutulur sevgililer Unutur yaralı yürek Yaşanmış o bitmez Sevdalar unutulur Geçmişten kala...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/unutulur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel İşte', 'gel-i-ste-caner-kuru-xg7av', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün geceme karıştı

Mehtap da bir güneş de.

Daha ne bekliyorsun

Geleceksen gel işte...

Yanmak varsa yanarım,

Kanmak varsa kanarım,

Her an seni anarım,

Geleceksen gel işte...

Gönlüm en son durakta

Koyma beni merakta

Naz yapmayı bırak da,

Geleceksen gel işte...', 'Gün geceme karıştı Mehtap da bir güneş de. Daha ne bekliyorsun Geleceksen gel işte... Yanmak varsa yanarım, Kanmak varsa kanarım, Her an sen...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktora Gittim', 'doktora-gittim-halil-karabulut-4q1ye', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir doktora gittim,nazik

Dedi:senin kalbin bozuk! 

Dedim:Doktor,aman düzelt,

Gençliğime olur yazık.

Doktor dedi:Yaş kaç bayım? 

Dedim:Yolun başındayım.

daha dünyaya doymadım

Henüz yetmiş yaşındayım.

doktor dedi:kalbin hasta,

Arıza kapakta,kasta.

Dedim:Doktor tamir eyle,

Sensin hekim,sensin usta.

Doktor dedi:kalpte kan az,

Uykusuzluğa dayanmaz.

Dedim:doktor,uyutma ha,

Uyursa belki uyanmaz.

Doktor dedi:Kalbin şaşık,

Atışlar karma karışık! 

Dedim:Doktor kınama ha,

Kalbim bir güzele aşık! 

Doktor dedi:yaşın yetmiş,

hep organlar iflas etmiş! 

Dedim:Doktor desene ki

''Halil senin işin bitmiş! ''...', 'Bir doktora gittim,nazik Dedi:senin kalbin bozuk!  Dedim:Doktor,aman düzelt, Gençliğime olur yazık. Doktor dedi:Yaş kaç bayım?  Dedim:Yolun ...', ARRAY['Türk Edebiyatı','Şiir','Halil Karabulut']::text[], 8.5, '{"poet":"Halil Karabulut","poet_slug":"halil-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/doktora-gittim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-burak-killioglu-5htjj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir, iki, üüüçç...Tıp! 

En iyisi konuşmamak,

Gözlerimi kapatıp.', 'Bir, iki, üüüçç...Tıp!  En iyisi konuşmamak, Gözlerimi kapatıp....', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sustum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Bi Veda', 'oylesine-bi-veda-sirma-mersin-0e401', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.............................Dünde kalan günler için................

Söylediklerimi, yazabilme imkanım yok...

Duygularım durmadan konuşuyorken, mantığım susmamı istiyor... 

Anlayacağın! 

Tüm suskunluğumun; ardındakileri, haykıracağım bir gün.

Kelimelerin sesi, cümle kurabilmem için yeterli değil...

Satırlar duyuyor,

Sen duymuyorsun...

.............................................................

.............................................................

Bak! ....

Saat gecenin kaçı? 

Ve ben...

Hala yatakta...

Kendi kendime düşüncelerimle, kavga ediyorum..

Kaybetmenin korkusu yüreğime yerleşmişken...

Söylemekten çekindiğim herşeyi, sayfalara döküyorum.

Anlatamadığım onca şeyi; bu yazıda anlarsın.

Anladığında ise! 

Senin bana geç, benimse yok olduğumu  fark edeceksin.

Keşkelere bir cümle daha ekleyerek...

Bitecek bir yaşam.

Yanıbaşındakini fark edemeden...

13.05.04', '.............................Dünde kalan günler için................ Söylediklerimi, yazabilme imkanım yok... Duygularım durmadan konuşuyork...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oylesine-bi-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-burak-killioglu-fp5uk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş de senin gibi,

Saçların gibi

Sapsarı parlarken akşamüstü,

Yanaştım tanıdık ama

Sanki meçhul bir kıyıya.

Köpük köpük dalga olup

Taştım bendimden

Yarı bitkin, yarı uyanık

Bakarken karşı yakaya.', 'Güneş de senin gibi, Saçların gibi Sapsarı parlarken akşamüstü, Yanaştım tanıdık ama Sanki meçhul bir kıyıya. Köpük köpük dalga olup Taştım ...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gunes-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrail', 'azrail-halil-karabulut-shs3j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Behey azrail,azrail,

Sen hiç yüze gülmez misin? 

Minnet etsem,rica etsem,

Benimle dost olmaz mısın? 

Bir ziyafet çeksem sana,

Yiyip içsen kana kana.

Bağışlasan canım bana

Hiç iltimas bilmez misin? 

sen bir şahin,ben bir serçe,

Nolur vurma bana pençe! 

bir zavallıyı gizlice

Azat edip salmaz mısın? 

Aldın anam,babam,dedem,

Gayrı bize basma kadem.

memur değil misin madem

Rüşvet versem almaz mısın? 

Kul olup kapında dursam,

Eşiğine yüzüm sürsem.

Eteğin öpüp yalvarsam

Merhamete gelmez misin? 

Bir halilden ne olacak,

Gitmeyip,burda kalacak...

Sorarsa mevla soracak

Bir bahane bulmaz mısın?', 'Behey azrail,azrail, Sen hiç yüze gülmez misin?  Minnet etsem,rica etsem, Benimle dost olmaz mısın?  Bir ziyafet çeksem sana, Yiyip içsen ka...', ARRAY['Türk Edebiyatı','Şiir','Halil Karabulut']::text[], 8.5, '{"poet":"Halil Karabulut","poet_slug":"halil-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/azrail-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim Baharı', 'neyleyim-bahari-necmettin-davulcu-m5cfc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'buralarda bahar havası var diyorlar

gözlerini görmeyince neyleyim baharı

güneş ısıtırmış üşümüş bedenleri

kızıl saçların değmeyince yüzüme

                              neyleyim güneşi

toprak bahar kokarmış

dansedermiş çiçekler rüzgarla

tenini koklamayınca neyleyim çiçeği', 'buralarda bahar havası var diyorlar gözlerini görmeyince neyleyim baharı güneş ısıtırmış üşümüş bedenleri kızıl saçların değmeyince yüzüme  ...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neyleyim-bahari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elâ Gözlü Yar', 'el-gozlu-yar-halit-demir-rau8y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaprağa çiğ düşmüş, bahar gelince

Dalında durur mu, meyve değince

Sen durmaz yanımdan, hemen gidince

Gidişine kurbanım Ela gözlü yar.

Mızrap saza vurup, ağıt dökende

Dize dize söz olup, efkar inende

Aklıma bir anda,siman gelende 

Selvine kurbanım, Ela gözlü yar

Sevgim Ummanlarda, dolaştı durdu

Vuslata varmadan, kapında durdu

Mîâdım gelmeden,  ecelim doldu

Kirpiğine kurbanım, Ela Gözlü Yar

Bakışın ok olur, sinemden vurur

Göz göze gelirse, yakar kavurur

Saçların rüzgarda, savrulur durur

Zülfüne kurban, Ela Gözlü Yar

Gülistan içinde, bülbüller öter

Sensiz mekanıma, baykuşlar tüner

Ellerin dokunsa, kül korâ döner

Ellerine kurbanım, Ela gözlü Yar 

Halimi sorarsan, perişan bir halde

Gömleğim yırtılmış, ceket bir elde

Niçin bu haldeyim, onu bir düşün de

Düşüne kurbanım, Ela Gözlü Yar

Sen ki hislerime, oldun tercüman 

Yazılır mı sevdiğim, aşkına ferman

İçime de bin dert var, sen ol ki derman

Merhemine kurbanım, Ela Gözlü Yar

Halit Demir. 13.05.2004', 'Yaprağa çiğ düşmüş, bahar gelince Dalında durur mu, meyve değince Sen durmaz yanımdan, hemen gidince Gidişine kurbanım Ela gözlü yar. Mızrap...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ela-gozlu-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-burak-killioglu-v3g71', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanın kıymetini çalışınca anladım.

Geçen her saat, her gün

Sanki yaşanmadan bitti.

Seni unuttuğumu sanıp daha çok hatırladım.

Akıp giden her bir metre, her bir adım

Biraz daha sana itti.

Seni sevdiğimi ise sen olmayınca anladım.

Gülen her güzel yüz, her bir göz

Yalnızca sana aitti.

Bir ses duydum diye ansızın uyandım.

Gördüğüm her düş, her bir rüya

Sabun köpüğü bir hayaldi.', 'Zamanın kıymetini çalışınca anladım. Geçen her saat, her gün Sanki yaşanmadan bitti. Seni unuttuğumu sanıp daha çok hatırladım. Akıp giden h...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayal-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma, Geçmişime, Geleceğime, Herşeyime...', 'askima-gecmisime-gelecegime-herseyime-tansel-yucelen-58a6g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İPEK''ime... (Sevgilime...) 

nasıl birşeysin anlamadım sen

biliyorum değilsin buralardan

ait olamazsın yaşadığımız dünyaya

hangi sonsuzluktan geldin

benim meleğim

cennetten mi

yoksa daha da güzel bir yerden mi

- canım benim

yaşamamışım senden önce aşkı

tatmamışım sevgiyi güveni

aldanmışım boş duygularla herşeye

sonra anlamışım seni tanıdığımda

geçmişimin bomboş

geleceğimin senle dolu olacağına

- canım benim

aşk işte bu

sevgi işte bu

bu iki sözcük hayatımda anlam buldu - sende

gerçeklik kazandı - sadece sende

- canım benim

sana adıyorum

bugüne kadar yaptığım tüm aşk şarkılarını

yazdığım tüm tutku şiirlerini

sevgiyle koparttığım tüm güzel çiçekleri

ve

seni yaşamışım

bugüne kadar yaptığım tüm şarkılarda

seni aramışım

bugüne kadar yazdığım tüm yazılarda

seni koklamışım

sevgiyle koparttığım tüm çiçek yapraklarında

- canım benim

seni seviyorum herşeyden çok

sevmediğim ve sevemeyeceğim kadar hiçbirşeyi ve kimseyi

ruhunu

bakışlarını

konuşmalarını

güzelliğini

tatlılığını

beni ben yapışını

hiçbir kimsenin anlamadığı kadar beni anlayışını

senin herşeyini

seni

sadece seni

- canımSIN beniM', 'İPEK''ime... (Sevgilime...)  nasıl birşeysin anlamadım sen biliyorum değilsin buralardan ait olamazsın yaşadığımız dünyaya hangi sonsuzluktan...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/askima-gecmisime-gelecegime-herseyime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle', 'gule-gule-sirma-mersin-htumi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '..........................................Biten ilişkilerin ardından kalanlar............

Gözlerim doluyor,

Düşündükce geçmişi...

Sahipsizliğe takılı kalmış yüreğim! 

Sevgisizliğin ağırlığı altında ezilmişken...

Yaşam! ...

Tokadını bi kez daha atıyor, duygularıma...

Hep bi küçük umudun; peşinde dolaşan hayallerim.

Sebepsiz bir ayrılığın yüzünden kopuyor...

Haykırış ve yalvarışların hiçbiri, seni getirmiyor bana...

Geçen onca senenin hatrını bile; çiziyorsan bir kalemde.

Döktüğüm onca gözyaşı,

Verdiğim onca sevgi,

Boşuna mıydı? ...

Bahaneleri sıraladığın cümleler,

Hançer gibi saplanıyorken, yüreğime...

Cevapsız suallerin içine düştüm.

Sahte mutluluk oyunu ile; devam ediyorken, herşey! 

Kazanan kader, kaybeden bendim...

Sen, mutluluğa bi adım; 

Bense sensizliğe bi adım kadar yakındım...

Mutluluğunun adresi; bi başka yürekse...

Sana GÜLE GÜLE...

13.05.04', '..........................................Biten ilişkilerin ardından kalanlar............ Gözlerim doluyor, Düşündükce geçmişi... Sahipsizli...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gule-gule-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılarda Unutma Beni', 'sarkilarda-unutma-beni-huseyin-cayikli-4reyu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çok eskidendi...

bir şarkı bestelendi giden ve gidecek olan sevgiliye şu sözler yazılıydı bir not kağıdına... sokaklar ıssız ve soğuktu yalnızlık üşütüyordu.kaybolan adamdı...

şarkı şöyleydi

sigaramın dumanına sarsam saklasam seni

yokluğuna yol yol olsa uzasa unutmam seni

gitme gitme gittiğin yollardan dönülmez geri 

gitme gitme el olursun sevdiğim incitir beni

akşam vakti sardı yine hüzünler

kalbim yangın yeri

gel kurtar beni senden

akşam vakti dolaştım sokaklarda

yırtık bir afiş seni gördüm duvarda...

gitme gitme gittiğin yollardan dönülmez geri 

gitme gitme el olursun sevdiğim incitir beni

şarkı yazılmış gitmekte ve gidecek olan sevgiliye güftesi hazır bir şekilde emanet edildi...bir kadın geçti şimdi deniz üstünde kadının yanında ayrılıkları hiçe sayan bir adam...adamın gözleri buğulandı biliyordu ayrılaklar yazdırır adama...ve her gidiş gözyaşıydı...

ve ben bittim o gitti...aslında kadın yanlızdı korkuyordu içini ısıtacak düşüncelerin yanında unutmadan ağlıyordu kadın...Adam iskeleye yakındı bir sahil şehriydi...yürüdü yağmurlarda ıslandı...per tezgahlarında kitaplarda onu aradı...kadın yoktu bir aşk ellerinden adamın akıp gidiyordu...zor oluyordu yaşamak oysa...kadın halini biliyordu ama ses çıkarmıyordu.adam seviyordu yani ben seviyordum o seviyordu ellerimiz birleşecekken birşeyler engel oluyordu...

adam duvara yazı yazdı... elleri kanıyordu...o şarkıda ki gibi

unutma beni...', 'çok eskidendi... bir şarkı bestelendi giden ve gidecek olan sevgiliye şu sözler yazılıydı bir not kağıdına... sokaklar ıssız ve soğuktu yaln...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sarkilarda-unutma-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Sitem', 'dosta-sitem-murat-demir-5b6ud', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba dost demek için

Gözgöze gelmekmi gerek

İnsan olmak yetmiyor mu

İlla da sevmekmi gerek

Hatırlayıp anmak için

Mateme girmekmi gerek

Sağ olmamız yetmiyor mu

Düşüpte ölmekmi gerek

Murat Demir kimdir diye

Birini yormakmı gerek

Antoloji yetmiyor mu

Ozan’a sormakmı gerek

Sayın Ahmet ERDEM''in affına sığınılarak yazılmıştır.', 'Merhaba dost demek için Gözgöze gelmekmi gerek İnsan olmak yetmiyor mu İlla da sevmekmi gerek Hatırlayıp anmak için Mateme girmekmi gerek Sa...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dosta-sitem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni sensiz bırakma', 'beni-sensiz-birakma-aysel-sevim-ntnbd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine seni bekliyorum

Ayazlı bir gecenin ortasındayım

Soğuk hayalinle sevişiyorum.

Dağınık saçların

Buz damlaları gibi çarpıyor yüzüme

Gözlerinde öfkeli ve haşin bir bakış! 

Ellerinin hırçın darbeleriyle ısınıyorum

Çaresizliğim kollarında damla damla eriyor

Al parça parça et duygularımı

Savur uzak diyarlara

Beni bende bırakma

Ban sensiz bir hiçim anla

Bir ses ver,bir yanıt ver haykırışlarıma

Kaybolurum yokluğunda

Beni sensiz bırakma

Bu yolsuz akşamlarda

Hasretinle dertleşiyorum.

Seni dinliyorum şarkılarda

Mehtap gibi doğuyorsun yüzüme.

Karanlık gecelerin vahşi yalnızlığında

Seninle aydınlanıyor kuytu köşeler

Seni soruyor bana buluştuğumuz yerler

Seni anlatıyor hep girdiğimiz mahzenler

Baktığım her noktada gözlerini görüyorum

Öylesine ışıl ışıl, öğlesine sevgi dolu

Dalıp dalıp gidiyorum, 

Uyanmak istemiyorum bu rüyadan.

Kalbimdeki aşk ateşi daha alevleniyor.

Bütün umutlarım hasretinle can çekişiyor

Her şeyi gözlerinden aldım

İmkansızlıklara yenilen aşkımızı

Gözlerine veriyorum.', 'Yine seni bekliyorum Ayazlı bir gecenin ortasındayım Soğuk hayalinle sevişiyorum. Dağınık saçların Buz damlaları gibi çarpıyor yüzüme Gözler...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beni-sensiz-birakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Yasaksın', 'sen-bana-yasaksin-aysel-sevim-wvfdq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bana Yasaksın

Ellerimi uzatsam dokunabilecek kadar yakın

Bir o kadar da uzaksın

Sen bana yasaksın

Ellerin yasak

Gözlerin yasak.

Gözlerine bir baksam o an zaman duracak

Ellerine tutunsam kıyametler kopacak

Sen bana yasaksın.

Kalplerimiz aynı hisleri paylaşsa da

Düşüncelerimiz ayni yöne aksa da

Olamayız biz birbirimizle

Her şey gizli kalmalı içimizde

Sen bana yasaksın

Hayalini kurmak yasak rüyama girmek yasak

Öylesine yasaksın işte

Seni arıyor gözlerim baktığım yerde

Kimseye ısınamıyorum, yakınlık duyamıyorum

Seni görmek istiyorum herkeste

Ömrüm oldukça yaşayacaksın içimde

Sen bana yasaksın

Aşkımız hep taze kalacak

Günden güne solsa da her karşılaştığımızda

Yeniden canlanacak

Sen bana yasaksın

Aramıza yasaklardan bir duvar örülecek

Ve her bakışımızda o duvar görülecek

Her bakışmamızda hayaller devrilecek

Belki asla kavuşamayacağız

Yüreğimizdeki sevda bizi birleştirecek

Engellerle yasaklar daha da büyüyecek.

Sen bana yasaksın.

Belki asla görüşmeyeceğiz

Aramıza mesafeler girecek

Yasak aşkımız yeni sevgilerle

Yasak ilişkilerle her defa yenilenecek

Aşkımız asla bitmeyecek

Sen bana yasaksın.', 'Sen bana Yasaksın Ellerimi uzatsam dokunabilecek kadar yakın Bir o kadar da uzaksın Sen bana yasaksın Ellerin yasak Gözlerin yasak. Gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sen-bana-yasaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bugünüm Yarınımsın', 'sen-bugunum-yarinimsin-aysel-sevim-lo0ny', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarılsaydım sana bir kez olsun doya doya

Ellerini tutsaydım kimse koparamasaydı

Rüyalarımda hep benimlesin sarılıyoruz

Bir türlü değişmiyor sana karşı hislerim

Aşkının ıstırabı öylesine yakıyor ki içimi

Mutlu olamıyorum, sarmışsın benliğimi

Senden başka hiç kimseyi görmüyor gözlerim

Aklım ermiyor bir türlü, neden seni böyle sevdim

Ruhum bedenimden ayrı,hep seninle beraber

Dünyalar vaat etseler ben yalnız seni isterim

Öyle ki uğrunda her an bu canı feda ederim

Razı olurdum ölmeye sevdiğini bilseydim

Sen bu günüm yarınımsın,

Emelim arzularımsın

Ruhumu besleyen gıdam

Düşünmeden vereceğim tek kararımsın

Aklımdasın, fikrimdesin, anılarımsın

Rüyalarım, hayallerim,ve hayatımsın.

Seni seviyorum,

Hayatım boyunca bende yaşayacaksın

Belki hiç görüşmeyeceğiz

Belki sen başkasının olacaksın

Sakın şunu unutma:

Benim tek ve son aşkım olarak kalacaksın', 'Sarılsaydım sana bir kez olsun doya doya Ellerini tutsaydım kimse koparamasaydı Rüyalarımda hep benimlesin sarılıyoruz Bir türlü değişmiyor ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-bugunum-yarinimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım Yaprak Gibi', 'umutlarim-yaprak-gibi-aysel-sevim-yunw2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün yine efkârlıyım

İçim İçime sığmıyor

Umutlarım yaprak gibi

Yerden yere savruluyor

Sevdalanan deli gönlüm

Bir çıkar yol bulamıyor

Boşa geçti benim ömrüm

Gönlüm hiç akıllanmıyor.

Başımı döndürür aşkı

Sevgim çıkmaza dalıyor

Feryatlarla, figanlarla

Yine gözlerim ağlıyor.

Geldim hayatın sonuna

Nedense O hiç gelmiyor

Yalan yanlış bu dünyada

Ölüm hep beni bekliyor', 'Bugün yine efkârlıyım İçim İçime sığmıyor Umutlarım yaprak gibi Yerden yere savruluyor Sevdalanan deli gönlüm Bir çıkar yol bulamıyor Boşa g...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umutlarim-yaprak-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Duygularla Tanışıyorum', 'yeni-duygularla-tanisiyorum-aysel-sevim-ie3h6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine sabah oluyor

Yine tan ağarıyor

Gözlerim bir damla uykuya hasret

Gönlüm bir düşünce duvarı

Kalbim zindan gibi ışık arıyor

Bedenim karanlıkların kucağında

Ruhumda bir okyanus

Dalıp gidiyorum ta derinlere

Yüreğimi kurtlar kemiriyor.

Hayallerim allak-bullak

Hayatımda bir güzellik başlamadan bitiyor

Umutlarım param parça

Okyanusun derinliklerinde kayboluyor

Yakalayabildiklerimin kuyruğuna tutunuyorum

Beni bilmediğim bir meçhule götürüyor

Bu umutla bilmediğim yerlerde dolaşıyorum

Uğradığım her yerde hüzünler beliriyor

Çıkmak istiyorum hüznün bataklığından

Çırpındıkça ne yazık, batıyor batıyorum

Bütün bekleyişlerim bir anda tükeniyor

Yemi umutlar satın alıyorum

Yeni bir yaşam hevesi başlıyor içimde

Yeni bir dünyayla selamlaşıyorum

Solan çiçekler canlanıyor gönlümde

Gönlüm yeni aşklara yelken açıyor

Yeni duygularla tanışıyorum.

Yeniler görmeye alışıyorum.', 'Yine sabah oluyor Yine tan ağarıyor Gözlerim bir damla uykuya hasret Gönlüm bir düşünce duvarı Kalbim zindan gibi ışık arıyor Bedenim karanl...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yeni-duygularla-tanisiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Pişmanlık', 'son-pismanlik-aysel-sevim-3bh5b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Koşarsın bir gün benim peşimden

Çok çekersin bu gururun yüzünden

Boşuna bahsetme sevgi sözünden

Sevmek kim, sen kim bunu bilelim.

Sana gönlümü verdim havalara çıktın

Bu dünyada sevilen yalnız kendini sandın

Aşkını puanladım, yazık sınıfta kaldın

Buna da hile kattın, dur sadede gelelim

Hepimiz aynı insan, Allah’ın yarattığı

Gel dostça geçinelim, unut bu düşmanlığı

Birazcık olsun sevgi, gözlerin aradığı

Dünya bu yalan işte, bari bunu görelim

Vazgeç bu gururundan bir kez sevmeyi dene

Yükseklerde uçma hep çile verme kendine

Son pişmanlık fayda vermez,fırsat geçse eline

İyiliğe koşalım,iyiliğe gidelim.', 'Koşarsın bir gün benim peşimden Çok çekersin bu gururun yüzünden Boşuna bahsetme sevgi sözünden Sevmek kim, sen kim bunu bilelim. Sana gönlü...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-pismanlik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Aşık', 'deli-asik-yilmaz-hatun-onw6i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düştüm derdime ararken dermanı,

Elime verdiler zalim fermanı,

Layık görmediler bana cananı,

İçime döküldü zehrin yamanı.

Aşıktım deli eklendi başıma,

Şikayet etsem çare yok yadıma,

Işıksız yok boğuldum karanlığıma,

Kerbelaymış fani dünya canıma...', 'Düştüm derdime ararken dermanı, Elime verdiler zalim fermanı, Layık görmediler bana cananı, İçime döküldü zehrin yamanı. Aşıktım deli eklend...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Hatun']::text[], 8.5, '{"poet":"Yılmaz Hatun","poet_slug":"yilmaz-hatun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deli-asik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimin İçindeki Duygular', 'gozlerimin-i-cindeki-duygular-aysel-sevim-gg3b1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel olan ne varsa ben hepsine aldandım

Sahte gülücüklere, sahte sözlere kandım

Hayatın bu yükünü taşımaktan yıprandım

Benim kaderim böyle, değişmez ki arkadaş

Küstüğüm olur ama hiçbir zaman kin tutmam

Bir dostumu tutar da diğerini unutmam

Ben gerçekçi biriyim, düzü eğriye satmam

Kimse artık kendini övemez ki arkadaş

Göz pınarım içinde ne duygular saklıdır

Şerefsizlik etmeyen tüm insanlar haklıdır

Yaşananlar içinde aşk her zaman farklıdır

Aşıklar bir gün olsun gülemez ki arkadaş.', 'Güzel olan ne varsa ben hepsine aldandım Sahte gülücüklere, sahte sözlere kandım Hayatın bu yükünü taşımaktan yıprandım Benim kaderim böyle,...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerimin-icindeki-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Kalbinle Çarpıyor', 'kalbim-kalbinle-carpiyor-aysel-sevim-o8fqy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benden ayrılmaya karar vermeden

Hiç düşündün mü acep ne olur sonum

Kimseler sevmez seni benimle deli deli

Kimse anlamaz seni benim sandığım gibi

Biz ikimiz birbirimiz için yaratılmışız

Ne ben sensiz olurum, nede sen bensiz 

Biz birbirimizden kopamayız

Bu aşkın biletini kesmeden

İyice ölçüp biçmelisin

Beni bir başkasıyla görmeye

Biliyorum dayanamazsın

Bu ayrılı acı verecektir sana

Bir gün bile dayanamazsın yokluğuma

Geri dönüşü olmaz sonra

İyi biliyorum beni özlersin

Kimseyi kolay kolay sevemezsin

Sen benim içimde ayrı bir bensin

Kalbim kalbinle aynı anda çarpıyor

Aynı anda aynı şeyleri düşünüyoruz

Mekanlarımız ayrı ya zevklerimiz aynı

Birbirimizi tamamlıyoruz.

Bu aşkı böyle kolay bitiremezsin

Paylaştığımız onca güzelliği

Bir kalemde silip atamazsın

Başkalarının mutluğuna bizi

Feda edemezsin', 'Benden ayrılmaya karar vermeden Hiç düşündün mü acep ne olur sonum Kimseler sevmez seni benimle deli deli Kimse anlamaz seni benim sandığım ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kalbim-kalbinle-carpiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimelerin Veda Kokan Buğusu', 'kelimelerin-veda-kokan-bugusu-aysel-sevim-agr20', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hazin bir veda akşamıydı

Buruk bir hüzündü gözlerimden akan

Cam kırıkları gibi dağıldı üzerime

Beni parça parça dağıttı sevdan

Buruk bir andı yaşanılan

Bir anlık heves miydi? 

Ruhumuzda fırtınalar koparan

Bedeli bu kadar ucuz mu olacaktı? 

Pahalı bir aşktan kalan

Neydi büyük sevdamızı 

Bozgunlara uğratan.

Son bir sözdü beklediğim

Kenetlenmiş dudaklarından kopup

Kalbimin derinliklerinde yankılanan

Bu hain gecenin acımasız bu saatinde

Saniye saniye, damla damla yüreğime sızan

Boğazıma takılıp,beni böyle acıtan

Sensizliğin korkusu muydu? 

Biliyorum, kendimi alıştırmalıyım buna

Çaresiz ve yorgun olsam da

Hazırlıklı olmalıyım, birazdan duyacağım

O soğuk kelimenin veda kokan buğusuna.', 'Hazin bir veda akşamıydı Buruk bir hüzündü gözlerimden akan Cam kırıkları gibi dağıldı üzerime Beni parça parça dağıttı sevdan Buruk bir and...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kelimelerin-veda-kokan-bugusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acımadın, Koydun,Gittin Ne diye?', 'acimadin-koydun-gittin-ne-diye-aysel-sevim-kl2nc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu ayrılıktan zararlı çıkan

İnan ki sadece sen olacaksın

Çok haykıracaksın arkamdan

Hiçbir şey bulamayacaksın.

Pişmanlık ateşi yakacak içini

Anlayacaksın elbet kendi suçunu

Affet, affet diye ağlayacaksın

Önümde diz çöküp yalvaracaksın.

Ben seni ölesiye sevmiştim diye

Acımadın, terk ettin, gittin ne diye? 

Dönmem artık sana göz göre göre

Benim gibi sende kan kusacaksın.', 'Bu ayrılıktan zararlı çıkan İnan ki sadece sen olacaksın Çok haykıracaksın arkamdan Hiçbir şey bulamayacaksın. Pişmanlık ateşi yakacak içini...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/acimadin-koydun-gittin-ne-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiridye', 'i-stiridye-baris-pinar-tumer-0frlf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden sonra

oldu

senden sonra

gittin

ve

oldu

Bir yürek

Borçlusun bana

Bir yürek...

içinde

minik bir inci saklı

Gözyaşı...', 'Senden sonra oldu senden sonra gittin ve oldu Bir yürek Borçlusun bana Bir yürek... içinde minik bir inci saklı Gözyaşı......', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istiridye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy10) İbret Levhaları -Mensuriye-', 'zy10-i-bret-levhalari-mensuriye-zulfikar-yapar-kaleli-2l5jo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dostumun dostu benim 

Elbette ki dostumdur. 

Nitekim ata dostları, 

Dostların en makbulüdür. 

“Düşmanımın düşmanı, 

Benim dostum”olamaz.

Çünkü bizim gönlümüzde düşmanlığa yer yoktur. 

Gönüller sevgi dolmalı. 

Orada düşmanlığa yer kalmamalı.

Dostlukların anlam kazandığı günler, 

İnsanların dara düştükleri günlerdir. 

	

Varlıklı insanlara dost olmayı istemek kolay, 

..............Dost olmak zordur. 

Oysa mazluma dost olmak nefislere zor 

.............Gelse de çok kolaydır.

Çünkü, mazlum zaten dost olmaya hazırdır.

	

Bazıları alıcı kuşların ömürlerinin 

Neden az olduğunu düşünmezler. 

Onlar sadece kargaların uzun yaşama

Sebeplerinin hesabını yaparlar.

Bilmezler ki kartalların nüfuz alanı 

Kargalarınkinden daha çoktur.

Asalet soydan gelir, huydan gelmez.

Bu yüzden huyun değişmesiyle

İnsan, asaletli olmaz. 

Derler ki: “Katrandan olmaz şeker,

Olsa da cinsine çeker.” 

Kenarın gör bezin al, Anasın gör kızın al.”

Bin türlü zahmetle zaferine 

Katkıda bulunulan kişilerin divanında

El pençe durmak ne kadar manidardır.

Dün size ihtiyaç duyanlar, 

Yarın da muhtaç olacaklardır. 

Kendini bugün ucuza satmak aptallıktır. 

Karıncalar kendi işlerini kendileri görürler.

Bu yüzden kimseye eyvallahları yoktur.

Bitlerin beslenmek için hem ucuz, 

Hem de aptallara ihtiyaçları vardır.

Çanak yalamakla nimet bulanlar, 

Nimeti bulunca hem çanak yalamaya, hem de

Yalatanı sırtlarında gezdirmeye mecburdurlar.

Aksi “hainlikle” damgalanır.

Bazıları kuzuya kurt, aslana çakal gibidir. 

Ömrünün beşte biri kabadayılık,

Kalanı etek öpmekle geçer. 

Onun kahramanlık edasında bile küçüldüğü hissedilir.

İnsanların bir kısmı aklının ermediğinden değil, 

Gözünün görmediğinden makam sevdalısıdır.

Kul olacaklarını görebilse zaten buna yeltenmezler. 

Benim ilgi alanım devlet makamlarından ziyade, 

Gönül makamları olmuştur.

Kişinin düşmanlık beslediği kapıya 

Sığınması kadar acze düştüğünü anı yoktur. 

Aşağılık duygusunun alçalttığı kişilerin 

Yükseltecekleri hiçbir şey yoktur.

...............Onlar esarettedir.', 'Dostumun dostu benim  Elbette ki dostumdur.  Nitekim ata dostları,  Dostların en makbulüdür.  “Düşmanımın düşmanı,  Benim dostum”olamaz. Çün...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/zy10-ibret-levhalari-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy13) Soğan Gibi Kokmak! -Mensuriye-', 'zy13-sogan-gibi-kokmak-mensuriye-zulfikar-yapar-kaleli-u7ke2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanları küçümseyip yüz çeviren; 

böbürlenerek, kibirlenerek 

yürüyen bilsin ki, 

Büyüklük taslayan her zorbanın 

kalbini mühürler. 

Kulluk etmeyi büyüklüklerine yediremeyenler, 

alçalmış olarak ölürler. 

Yaradan kibirliyi alçaltır, 

alçak gönüllüyü yükseltir. 

Kendini beğenen kimseyi

yerin dibine batırır 

kıyamete kadar orada debelenir durur. 

Kibir, borç ve azgınlıktan uzak olan 

cennete girer. 

Cimrilik, azgın nefis 

ve kendini beğenme helâk edicidir. 

Yaratan kibirli kimseyi, 

komşuları arasında en aşağı seviyeye 

düşürmedikçe bu dünyadan almaz. 

Kavakların boylarının uzunluğuna bakıp 

onları önemli bir şey sanmamalı. 

Bütün kibirli, meyvesiz ve gölgesiz 

varlıkların başları bulutlarda sallanır.

Gurura kapılarak emrindekilere 

zulüm edenler cezasını ağır öderler. 

İnsanlara yüksekten bakan, 

gurur ve kibir sahibi 

aşağılık duygusunu yüzünden 

kin ve hiddet taşır. 

Şurasını unutmamak gerekir ki; 

Kin büyüdükçe, kin besleyen küçülür. 

Sevgi de kin de mutlaka karşılık görür.

Babadan kalan devlet veya 

gümüş tepsi içinde sunulan devletin 

ebedi olmadığını bile bile 

onlara kibirlenmek 

hangi aklın kârıdır anlayamam. 

Sen bu fani dünyada

emanetçi olduğunun farkında değil misin? 

Kendine verilen makamına 

ve malına gösterdiğin  titizliği, 

yarın mutlaka elinden alınacak 

ve sorgulanacak olan asıl emanet için 

niçin göstermiyorsun? 

Bazıları geçici devletleriyle büyük 

olduklarını zannediyorlar. 

Elinde aslan kabzalı, 

çatal başlı kılıcı ile her an 

maiyetinin başını vurmaya hazırlar. 

Makamları küçülttüklerinin farkında bile değiller. 

Çünkü küçük insanların makamı 

büyüttüğü görülmemiştir. 

Onlar büyük sorumlulukların altında 

ancak ezilirler. 

Devletleri ellerinden alındığında

koskoca bir hiç olurlar. 

Bir gönül kırmanın bin devletle 

telafi edilemeyeceğini bilerek gönül kırmak, 

devlet elden gidince yere bakmayı gerektirmez mi? 

Bu devletlere olan bağlılık ve bu sevgi, 

asıl devlet sahibine  gösterilmesi gereken 

sevgi ve saygıyı nedense akla getirmiyor. 

Dünyalık için saatlik planlar yapılır da, 

yaratılış gayesi akıllara gelmez.

Elimize geçirdiğimiz devletin cazibesine 

kendimizi o kadar kaptırmışız ki; 

öteyi ancak cenaze merasiminde aklımıza getiriyor, 

sabaha unutuyoruz. 

Günler sayılı, 

sonun ne olacağını bilmiyoruz ama, 

bir dakika sonrası için de garantimiz de, 

hazırlığımız da yok. 

Unutmayın ki; devleti çok olanın 

hesabı da çok ve zorlu olur.

 	

Gurur, kibir insanı mutluluktan uzaklaştırır. 

Ve yine unutmayalım ki; 

bir insan kendisini 

yüksek görme hırsıyla söz söylerse 

.............................soğan gibi kokar.', 'İnsanları küçümseyip yüz çeviren;  böbürlenerek, kibirlenerek  yürüyen bilsin ki,  Büyüklük taslayan her zorbanın  kalbini mühürler.  Kulluk...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/zy13-sogan-gibi-kokmak-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy12) Özgürlüğün Sırları -Mensuriye-', 'zy12-ozgurlugun-sirlari-mensuriye-zulfikar-yapar-kaleli-ykm2b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nefsinden feragat etmeyen, 

gerçek özgürlüğü bulamaz.

Başkalarının özgürlüğünü tanımayanlar, 

özgürlüğe layık değillerdir.

Kendi için olduğu kadar,

hasımları için de özgürlük hakkını istemeyen 

ve kabul etmeyen bir kimse

özgür olmaya layık değildir.

Özgürlüğe karşı güveni olmayan

toplum derhal yıkılır.

“Ya hür bir millet olarak yaşayalım, 

ya da ölelim” diyor Lincoln.

Doğru söylüyor.

Düşünceye gem vurmak, 

zihne gem vurmak demektir,

bu ise, rüzgarı zaptetmekten de zordur.

“Özgürlük ağacı ancak, 

zalimlerin kanıyla sulanınca gelişir”.(Barere)     

Çünkü bu onun tabi gübresidir.

“Uygar” yamyamların sunduğu,

Zulüm ve kahrın döktüğü kanlarla! ! ! 

Özgürlük verilmez, alınır.

Özgürlük hiçbir zaman hapsedilmez, 

hatta şiddete uğradığı oranda genişler.

Özgürlük, ancak her gün yeniden

Özgürlüğünü kazanan insana layıktır.

özgür insanın vücudu  esir edilebilir

ama ruhu yakalanamaz.

Özgür insan mahpus olabilir,

fakat asla esir olamaz.

Kanuna gönül rızası ile itaat etmek,

Özgürlüğün en yüksek bir ifadesi değil midir? 

Özgürlük ancak onu sevenlere

.....................muhafazaya

ve savunmaya hazır olanlara verilir.', 'Nefsinden feragat etmeyen,  gerçek özgürlüğü bulamaz. Başkalarının özgürlüğünü tanımayanlar,  özgürlüğe layık değillerdir. Kendi için olduğu...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/zy12-ozgurlugun-sirlari-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy08) Hayat Bilgisi -ll -Mensuriye-', 'zy08-hayat-bilgisi-ll-mensuriye-zulfikar-yapar-kaleli-ceov1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat bir hikayedir. 

Mühim olan, 

Eserin uzun olması değil, iyi olmasıdır.

Bu yüzden midir ne? 

“En kötü insanlar en iyi yerlerde otururlar” diyor Aristo.

Hayatın ne kadar kısa olduğunu anlamak için 

İnsan çok yaşamalıdır.

İyi kullanmadan uzun süre yaşamış insan,

En az yaşamış demektir.

Mutlular için kısa mutsuzlar için uzundur hayat.

Uzun yaşamak için değil, 

Doğru yaşamak için çalışmak gerekir.

Onu sönüklükten kurtaran, 

Hayatın küçük güçlükleridir.

Mücadelesiz hayat,

Tabutunun tahtası çürümeden, 

Adı unutulup  gidenlerin hayatı olabilir.

Hayatta daima tatlı ile acı karışıktır.

Geçmiş hayatını gururla hatırlayabilen kimse,

Hayatını iki kere yaşıyor demektir.

Maddi hayat muvazeneye, 

Manevi hayat doğruluğa dayanır.

Hayat her şeyi her şeye malik eder 

Fakat çok pay alanların

Adları kalmaz.

...........Hayatını vatan yolunda kaybeden 

...........Hiçbir zaman ölmez.

...........Ancak, itibar da görmez.

Doğduğumuz zaman dünyaya 

Hiçbir şey getirmedik ki,

Giderken de hiçbir şey götüremeyiz! .

Bu yüzden hayatı yük etmeye değmez.

Hayat ağır bir yük değildir,

Zaten yol da uzun sürmeyecektir.

Hayatın her dakikası birdir.

Hayattan faydalanmasını,

Zevk almasını bilmeyen kimse 

Hayalet gibidir.

Her beşik içindekine sorar:

............................Nereden? 

Ve her kefen sorar: 

............................Nereye? .', 'Hayat bir hikayedir.  Mühim olan,  Eserin uzun olması değil, iyi olmasıdır. Bu yüzden midir ne?  “En kötü insanlar en iyi yerlerde otururlar...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/zy08-hayat-bilgisi-ll-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy07) Hayat Bilgisi -l -Mensuriye-', 'zy07-hayat-bilgisi-l-mensuriye-zulfikar-yapar-kaleli-t4mwa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki dipsiz karanlık ortasında

bir kibrit alevidir.

ki, hayat; 

Silgi kullanmadan 

Resim çizme sanatına denilmektedir

Hızla akan bir nehirdir,

Altın gibi pırıltıları akıp gider,

Sonunda bize sadece kum kalır

.............Hayat bir bileği taşıdır,

.............El altından kolay kayar.

Küçücük şeylerden meydana gelen

Kocaman bir demettir.

Şerefle bitirilmesi gereken en ağır görevdir.

Ve harekettir, hareketsizlik ölümdür.

.................................Doğumla başlayan, 

.................................Ölümle biten bir okuldur. 

Ki orada herkes hem öğretmen, hem öğrencidir.

İnsanın hayatı, insanın hayalidir.

Bu bir soluk ve bir gölgeden başka bir şey değildir.

Ne bir bayram, ne bir yas günüdür, 

.......................Hayat iş günüdür.

Hiçbir şey onun kadar kıymetli,

Hiçbir şey onun kadar tatlı da değildir.

Değeri uzun yaşanmasında değil,

İyi yaşanmasındadır.

Hayat; 

İnsana bağışlanmış değil,

Ödünç verilmiştir.

Ve, değerli madenler gibi 

Biraz ağır çekmelidir.

İyi ve güzel bir şey yapınca 

Hayat öyle güzel ki.

Bu yüzden yaşla değil, yaşamakla anlaşılır.

Bize verilen değil, 

Bizim yazdığımız roman olmalıdır

Canı, can vererek almamışız 

...............ki değerini bilelim.', 'İki dipsiz karanlık ortasında bir kibrit alevidir. ki, hayat;  Silgi kullanmadan  Resim çizme sanatına denilmektedir Hızla akan bir nehirdir...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/zy07-hayat-bilgisi-l-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy05) Dokuma Hatası! ! -Mensuriye-', 'zy05-dokuma-hatasi-mensuriye-zulfikar-yapar-kaleli-i1lo5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her yol bir gönle gider.

Ve gözyaşları gönlün 

Tükenmez çağlayanlarıdır.

Umudun da, umutsuzluğun da 

Mekânıdır 

Yönlerin birleştiği tek yöndür gönül.

Birbirine paralel doğruların da.

Paralel doğrular kesişmez kuralına inat,

Kesiştiği yerdir. 

Her çare gönül içindir.

Çünkü hayat gönle bağlanmıştır.

Tırmanan ve çıkan,

Buluşmanın hazzını tadar, gönlün baharında.

Her dinin kâbesidir gönül,

Gerçeklerin tekidir.

Dost, dost gönlün ürünüdür.

Gösteriş için dostluk,

Fayda için düşmanlıktan kötüdür.

Her mevsimin çiçeğidir, vicdan bahçesinde dostluk,.

Hüneri; hiç solmamasıdır bahçenin. 

Çirkinliği yenenler güzelliğin aşığı olmuştur.

Süreklidir doğması, her sabah yeniden

Gönlü dost olanın. 

Onda fikir taze, ruh zindedir. 

Anılarını yazar zalim.

Kara vicdanının lekesi üzerinde.

silinmez asla karası mazluma zulmedenin.

En uzak köşeler, hakta birleşen, 

Hakta oluşan dönemeçlerdir.

İç içe, hislerle çatılmış hedefler, 

Metotlar ve bütün âlem onun bir aracıdır.

Sebepte,sonuçta, amaçta, 

Duranda, yürüyende her şeyde O. 

Güneş varsa, gölgeler de vardır.

 Kalp gölgesi ile birleşmez.

Gölge hayali aslın,

Hayal sonucun atığıdır. 

Mazlum semaya çekilir,

Zulüm çektikçe.

Bu merdivenin sonunda rahmet,

Bağış ve selameti, 

Saadeti vardır cefa yolcusunun.

Alçalır zalim zulmettikçe. 

Zalimin alçaklığından doğar 

mazlumun büyüklüğü.

Bu hal candan öteye taşır insanı. 

Ve lakin ben, 

İnsanı insanla yan yana koyuyorum, 

Heyhat! Seçemiyorum 

Sanırsın bir kördüğüm. 

Hangisi o yüce mucize? 

Hangisi dokuma hatası 

Belli değil........! !', 'Her yol bir gönle gider. Ve gözyaşları gönlün  Tükenmez çağlayanlarıdır. Umudun da, umutsuzluğun da  Mekânıdır  Yönlerin birleştiği tek yönd...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/zy05-dokuma-hatasi-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızkulesi', 'kizkulesi-meral-yagcioglu-3jhg7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizin ortasında

Adeta nazlı bir kız edasıyla

Süzülüp, salınankız kulesi

Gece olsun,gündüz olsun

Bana güç verir

Tam karşısında kıyıdaki o kocaman

Taşa oturur dertli kaldırırım kadehimi

Şerefe der başlarız dertleşmeye

Aheste gelir dalgaların sesi

Kulağıma name olur 

Kemanın tellerine vurur gönülden

Okşar tenimi, parmak uçları  ıslak

Kucak dolusu hasret taşır kıyı boyunca 

Yalnızlığımı paylaşır

Yıldızlı, yıldızsız  gecelerde

Dost olur yanı başımda

Nemli dizleri ne uzanır yatarım

Ilık meltemin yumuşak esintisinde

Nasihat eder sessiz, sessiz kulağıma

Fısıltılarla cesaret olur yüreğime

Arkadaş olur asırlık prenses 

Kıyıya ulaşan dalgaların ritmiyle

Dans edip mutluluğa salar  beni

Ana olur, sımsıcak koynuna alır

Kol kanat gerer korkularımı yok eder

Sevgili olur, aşk aleviyle yanan yüreğimde

Kopan fırtınaları dindirir

Yıldızların altında kumsalda oynaşır benimle

Güneşin doğmasıyla ışığım olur

Aydınlatır,ısıtır buzdan kalbimi

Yeni umutlarla başlarım güne

Garip bir haz verir bana

Uzaktan uzağa seyretmek bile

Huzur verir yüreğime

Yüzyıllardır yalnızlığını

Marmara’yla paylaşan

Martılarla söyleşen

Görkemli  kızkulesi

Bütün gizemiyle

Denizin ortasında

Nazlı, nazlı salındıkça

Bana yoldaş olur

Hem gündüz hem de gece 

18/04/2001', 'Denizin ortasında Adeta nazlı bir kız edasıyla Süzülüp, salınankız kulesi Gece olsun,gündüz olsun Bana güç verir Tam karşısında kıyıdaki o k...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kizkulesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy11) İki Büyük Felaket -Mensuriye-', 'zy11-i-ki-buyuk-felaket-mensuriye-zulfikar-yapar-kaleli-rxdm1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adalet güzeldir.

İdarecilerde bulunursa

Daha da güzeldir.

Emir mevkiinde bulunanlar idarecilerdir.

Cennete girecek üç sınıf var 

Bunlardan biri de adil yöneticilerdir.

Adil yöneticinin bir gün

Adaletle hükmetmesi

Bir kişinin kendi kendine altmış yıl

Nafile ibadet etmesinden 

Daha hayırlıdır.

Pascal diyor ki; 

Kılıcın yapamadığını adalet yapar.

Kuvvete dayanmayan adalet aciz, 

Adalete dayanmayan kuvvet zalimdir.

Kuvvetsiz adalet

Ve adaletsiz kuvvet

İki büyük felakettir.

Kılıç zaferleri, 

Zekâ siyasi üstünlüğü,

Adalet de ahlaki başarıyı temin eder.

Adaletin kuvvetli, 

Kuvvetin de adaletli olması gerekir.

Adaletin hakim olduğu yerde

Silahın yeri yoktur.

Adalet merhametten ziyade 

Her cemiyetin temelini teşkil eder.

Devletlerin sarsılmayan temelini

Adalet teşkil eder.

Çünkü:

Mülkün temeli adalettir', 'Adalet güzeldir. İdarecilerde bulunursa Daha da güzeldir. Emir mevkiinde bulunanlar idarecilerdir. Cennete girecek üç sınıf var  Bunlardan b...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/zy11-iki-buyuk-felaket-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy14) Utanma Yüzsüzlüğü -Mensuriye-', 'zy14-utanma-yuzsuzlugu-mensuriye-zulfikar-yapar-kaleli-50x6l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Utanmak ne güzel bir hasettir. 

Hâyânın hepsi hayırdır. 

Ve hâyâ ancak hayır getirir. 

Hâyâ imanın dallarından bir daldır. 

Her dinin bir ahlakı vardır. 

İslâm’ın ahlakı da hâyâdır. 

Haya duygusu kaybolan kimsenin kalbi ölür. 

İman çıplaktır. 

Elbisesi takva, süsü utanmak, 

meyvesi ise ilimdir. 

Utanmak güzeldir. 

Utanmak kadınlarda olursa daha da güzeldir. 

Haya imandan, arsızlık cefadandır, 

Utanmak yetmiş bölümdür 

ve utanmak imandandır. 

Hâyâ insanların gözlerindedir. 

Yani göz gözden utanır. 

Utanç duymamak kadar 

utanç verici bir şey yoktur. 

Kötü insanları görmek artık 

beni şaşırtmıyor, 

ancak utanmadıklarını görünce şaşırıyorum. 

Allah bir kalbi, 

kendisinden hâyâyı gidermekle 

cezalandırdığı kadar hiçbir şeyle 

cezalandırmamıştır. 

Her şeyin kendine yakışan bir ziyneti, 

bir meyvesi vardır. 

Hâyânın meyvesi de hayırdır. 

Yusuf Bin Esbap diyor ki: 

“Biz öyle kimseler tanıdık ki onlar, 

Allah’tan cenneti istemekten hâyâ ederlerdi”. 

Bugün utanabilmeyi Allah 

bazı kullarından kaldırmış olmalı ki 

bu kadar utanmaz insan kılıklı türemiştir. 

Elmanın bile yüzünün kızardığı bir zamanda, 

insanların yüzünün kızarmaması 

ne kadar acıdır. 

”Haklı bir fikrin meyve vermemesi 

mümkün değildir”, diyor Tolstoy. 

O zaman aklıma 

demek ki; 

bizim fikrimizin de meyvesi bu 

demekten başka bir şey gelmiyor elimden. 

İnsanın utanmaz gözden, 

kızarmaz yüzden başka sermayesi 

kalmamışsa 

onun yapacağı sadece 

hâyâsızlıktır, arsızlıktır. 

Allah buyuruyor ki; 

ne mutlu o kullarıma ki 

benden hâyâ ederler de 

yalnız kaldıkları zaman günah işlemezler. 

İnsanların bir kısmı 







cenneti istemekten bile hâyâ ederken, 

bir kısmı hiç utanmadan 

bu mazlum milletin hakkını 

hakkı sayarak midesine indirebiliyor. 

Bunların şerrinden Allah 

memleketi de, milleti de korusun. 

İnsanın ar damarı çatlamaya görsün 

artık onun yapamayacağı kötülük yoktur. 

Allah’tan korkmayandan korkulur. 

Allah’ım bu yüzsüzlerin, 

bu beyinsizlerin 

ve bu utanmazların yüzünden bizi 

...........................helâk eder misin?', 'Utanmak ne güzel bir hasettir.  Hâyânın hepsi hayırdır.  Ve hâyâ ancak hayır getirir.  Hâyâ imanın dallarından bir daldır.  Her dinin bir ah...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/zy14-utanma-yuzsuzlugu-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Sevdan için....', 'sevdan-icin-baris-pinar-tumer-6cura', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevda içindi

 Sevda için

dedim 

inanmadın

sarhoş olup

gökyüzüne 

içtim

ay 

tükürdü yüzüme

sevda dedim 

o da inanmadı

beni sevesin diye

bulutlarla  elele verip

ismini geçtik geceye

gündüzler temize geçti

sevgimi

tabiat döndü benden yüzünü

beni sev istedim

Sadece sev

sonunda takas ettim

ruhumu rüzgârla

sana eseyim diye

evren senden yana

meğer

kalbin için

 kuyruk varmış

sevdayla değil

sıraylaymış

bekliyorum en sonda.....', 'Sevda içindi  Sevda için dedim  inanmadın sarhoş olup gökyüzüne  içtim ay  tükürdü yüzüme sevda dedim  o da inanmadı beni sevesin diye bulut...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevdan-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erguvan', 'erguvan-hasan-aydin-i3nqu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaktan bakınca Boğazın süsü

Çamların zarif, hafif örtüsü

Uçuk ama narin bir kadın gibi sırnaşık

Öyle güzel, öyle hafif, sarmaşık

Yeşil örtünün eflâtun nakışları

İstanbul''u süzüyor erguvan bakışları

Tepelerden sahile akarken öbek öbek

Neşelenir Üsküdar, kahkaha atar Bebek

Bahar Nisanla gelir, erguvanla gülümser

Erguvansız Boğazda çamlar bahara küser', 'Uzaktan bakınca Boğazın süsü Çamların zarif, hafif örtüsü Uçuk ama narin bir kadın gibi sırnaşık Öyle güzel, öyle hafif, sarmaşık Yeşil örtü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aydın']::text[], 8.5, '{"poet":"Hasan Aydın","poet_slug":"hasan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/erguvan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdime Çare', 'derdime-care-baris-pinar-tumer-41rgl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep

sizleri seyredip

hayaller kurdum

bulutlar...

bir seylere

benzettim

fal baktim sizlerden

Merak eder dururum

acaba 

siz beni 

neye benzetirsiniz? 

sizi 

samimi buldum da

o yüzden açarim

derdimi

bir tas ustasi

oldu sevgilim

aramiza 

uzakliklar yonttu

tastan sert 

tenden yumusak

yerden bahane gibi

sudan da öyle

acaba gökten nasil

görünüyoruz? 

Derdime bir çare....', 'Hep sizleri seyredip hayaller kurdum bulutlar... bir seylere benzettim fal baktim sizlerden Merak eder dururum acaba  siz beni  neye benzeti...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/derdime-care-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taç Ettim Seni', 'tac-ettim-seni-erdal-sayil-ue2o3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Görmek istiyorum, artık seni; 

Ki,bu kadar dilsiz kaldığım yeter...! 

Bir his doluyor içime yepyeni; 

Belki o da beni bir nebze sever...! 

Bütün kelimelerimi dökeceğim,

Onları gönlümden sökeceğim,

Hasretin bileğini bükeceğim; 

Sana erişmek her şeye değer...

Alıp, o narin yüzünü ellerime,

Ortak edeceğim seni hallerime,

Bu sana değişmez vaadim olsun; 

Taç ettim seni, önceki güllerime...!', 'Görmek istiyorum, artık seni;  Ki,bu kadar dilsiz kaldığım yeter...!  Bir his doluyor içime yepyeni;  Belki o da beni bir nebze sever...!  B...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tac-ettim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesmeyelim Tadını', 'kesmeyelim-tadini-ahmet-agdere-irb46', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Amaç paylaşmak ise yazımızı, 

Bırakalım da yazılsın tamamı! 

Olmaz şiiri yarı yolda kesmek,

Damaktayken kesmeyelim tadını! 

(Gruplarda şiirlerini yarım yazanlara)', 'Amaç paylaşmak ise yazımızı,  Bırakalım da yazılsın tamamı!  Olmaz şiiri yarı yolda kesmek, Damaktayken kesmeyelim tadını!  (Gruplarda şiirl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kesmeyelim-tadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soluk', 'soluk-baris-pinar-tumer-06eat', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir

kutsal ağacım

Köklerim

yeryüzünün

Köklerine

hüzünle bağlı

nefesim

nefesine

bir tek 

anla bağlı

kutsal bir

ağacım artık

yazgım 

yeryüzünün yazgısı

soluk alıyorum

verirken

yerler sarsılıyor

isminin ilk hecesinden...', 'Bir kutsal ağacım Köklerim yeryüzünün Köklerine hüzünle bağlı nefesim nefesine bir tek  anla bağlı kutsal bir ağacım artık yazgım  yeryüzünü...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/soluk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlere Dair', 'gidenlere-dair-murat-onat-vta3y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolcu boynu bükük, yorgun gider,

Gözü yaşlı, yüzü solgun gider.

Fakirimin karnı aç, cebi boş.

Zenginlerse cebi dolgun gider.

Ömür harcar hiçe kimi ruhlar,

Kimi Yunus gibi olgun gider.

Tadına varamaz da ihtiyar,

Körpecik bebekler doygun gider.

Kalan yok vesselam herkes gider,

Kimi çoşkun kimi durgun gider.

1999', 'Yolcu boynu bükük, yorgun gider, Gözü yaşlı, yüzü solgun gider. Fakirimin karnı aç, cebi boş. Zenginlerse cebi dolgun gider. Ömür harcar hiç...', ARRAY['Türk Edebiyatı','Şiir','Murat Onat']::text[], 8.5, '{"poet":"Murat Onat","poet_slug":"murat-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gidenlere-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemim', 'gemim-murat-onat-d413q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Upuzun güvertesi cevizden oyma,

Bir usta kaptan, tayfasını sayma.

Adını da ben koymuştum; alınteri.

Gerçekten farksızdı, dümeni, her yeri.

Saatlerce seyretsem bıkmazdım ondan,

Görebilmek için çok kaçtım balkondan.

Bir gün gemimi bulamadım vitrinde,

Gördüm onu bir zenginin ellerinde.

Şimdi boğazda gördüğüm her bir gemi,

Daha dün gibi yakar, yakar sinemi.

1995', 'Upuzun güvertesi cevizden oyma, Bir usta kaptan, tayfasını sayma. Adını da ben koymuştum; alınteri. Gerçekten farksızdı, dümeni, her yeri. S...', ARRAY['Türk Edebiyatı','Şiir','Murat Onat']::text[], 8.5, '{"poet":"Murat Onat","poet_slug":"murat-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gemim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Cini', 'eski-cini-baris-pinar-tumer-jexyb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sesine uyandım

dün gece

Bir küçük

Eski cini

anılarımın

arasında geziniyor...

Pıt...pıt... pıt...

Ayak sesleri

Bir aşağı bir yukarı

pıt.... pıt... pıt... pıt....

Yağmurdanmış ayakları

koparıp koparıp

kendine hayat

işliyor

madem öyle

al götür dedim

zaten

onlar yüzünden

uyku girmezdi gözüme...

satamadan gelme sakın!', 'Sesine uyandım dün gece Bir küçük Eski cini anılarımın arasında geziniyor... Pıt...pıt... pıt... Ayak sesleri Bir aşağı bir yukarı pıt.... p...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eski-cini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heybemde Barhanam Çile ve Hüzün', 'heybemde-barhanam-cile-ve-huzun-hayrettin-durmus-uvakf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Heybemde Barhanam Çile ve Hüzün

Dağlara sis çöker gönlüme hasret

Gam yüklü kervanlar dolar içime.

Boğazımda düğümlenen hıçkırık 

Gelmiyor hesaba, sığmaz biçime.

Heybemde barhanam çile ve hüzün

Başka yükü karıştırmam göçüme.

Yüreğimde bergüzarın olmasa

Rüzgârları takar mıyım saçıma? 

Bumerang acısı vız gelir bana

Sensiz olmak gider benim gücüme.', 'Heybemde Barhanam Çile ve Hüzün Dağlara sis çöker gönlüme hasret Gam yüklü kervanlar dolar içime. Boğazımda düğümlenen hıçkırık  Gelmiyor he...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Durmuş']::text[], 8.5, '{"poet":"Hayrettin Durmuş","poet_slug":"hayrettin-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/heybemde-barhanam-cile-ve-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Görüşmek üzere*', 'gorusmek-uzere-kubilay-enginol-drljv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sabah uyandı

Mevsimlerden,bahardı

Yüzünü yıkadı,aynaya baktı

Tanımadığı bir yüz,aynadaydı

Tanıdık geldi yüz biraz

Göz kırptı ona haylaz,haylaz

Canlıydı gözleri,neşeli

Tamam,tanımıştı,gençliği idi

Sarıldılar,girdiler kolkola

Oturdular neşe içinde kahvaltıya

Gençliği dedi,bugün işi as

Beraber dolaşalım,geçmişte biraz

Çıktılar beraber,gittiler parka

Doyasıya sallandılar,hayat salıncağında

Muziplik yapıp,kapı zillerini çaldılar

Kızanları görünce,hemen saklandılar

Gittiler ilk aşkın kazındığı ağaca

Yaşıyordu hala,pamuk helvacı amca

Kapanmıştı,muhallebici olmuştu,çantacı

Ne anılar vardı orada tatlı,acı

Yoruldular,bir bank''a oturdular

Geçmişteki olanları,hatıraları paylaştılar

Akşam oldu vedalaşma vakti

Gözleri doldu

Birdaha sefere beraberinde getir çocukluğumu', 'Bir sabah uyandı Mevsimlerden,bahardı Yüzünü yıkadı,aynaya baktı Tanımadığı bir yüz,aynadaydı Tanıdık geldi yüz biraz Göz kırptı ona haylaz,...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gorusmek-uzere-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-sair-ayseozdemir-a8ekw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur sağnak sağnak yağsa da,

Şimşekler ruhuma bıçak gibi saplansa da,

Yeşil o derin yeşil gözlerinde

Boğulmak yeterdi bir ömür bana.

Geceyi ışıtan sadece bir lamba,

Oysa önceleri sen dolardın odama,

Hayalin gezerdi yorgun düşmüş kollarımda.

Ve ben her gece sana yazardım,

Sensiz yaşadığım günlerin,

Özlem yüklü dramını.

Yoksun yanımda,

Yanında yokum.

Günaydın canım benim,

Günaydın kocaman yüreklim.

Bu gece uykumu yine,

Rüyalarla beslemek yerine,

Sigarayla zehirledim,

İnan seni çok özledim.

Kavuşmalarda olmasa,

Hasretinden öleceğim.

   

             1995/ADANA', 'Yağmur sağnak sağnak yağsa da, Şimşekler ruhuma bıçak gibi saplansa da, Yeşil o derin yeşil gözlerinde Boğulmak yeterdi bir ömür bana. Gecey...', ARRAY['Türk Edebiyatı','Şiir','Şair Ayseozdemir']::text[], 8.5, '{"poet":"Şair Ayseozdemir","poet_slug":"sair-ayseozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozlem-161-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelemeyeceğim Ahmed...', 'gelemeyecegim-ahmed-hakan-kose-1h5lx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- Bağdat''ta doğmuş olan küçük Halid''in çalınmış çocukluğuna ağıt... -

Ben gelemeyeceğim bugün Ahmed

Sen de çıkma bundan sonra

Hani biz daha küçücükken

Hani anlatırdı ya ninemiz

Düzeltip ak örtüsünü 

Bir gün buyurmuş ki efendimiz

	

	''Ashabım! 

	Şimdi beni dikkatle dinleyiniz

	Size apaçık bir düşmandır Şeytan

	Onun arzımızda kulları vardır

	Öyle şerîrdir ki zaman zaman

	İnsan aklı almaz ettiklerini

	İşte onları gördüğünüzde

	Sığınınız yüce Rabb''imize

	Zinhâr onlara uymayınız

	Zîrâ size vaad ettikleri cennet

	Sahtedir, ateştir, kandır,

	Sığınınız yüce Rabb''imize

	Ve biliniz, şeytan düşmandır

	Ve arzımızda kulları vardır...'' 

Hatırladın değil mi Ahmed? 

Ben bugün gelemeyeceğim

Hem sen de çıkma bundan sonra

Zira şeytanın şerîr kulları 

Artık yakınımızda, yanımızda

Dün Şeyma''yı götürdüler

Babam nicedir görünmüyor

Annem ısrarla gelecek diyor

Hem Şeyma''yı da getirecek

Ama sen çıkma dışarı diyor

Ben bugün gelemeyeceğim Ahmed

Zira şeytanın şerîr kulları 

Ablamı, Şeyma''mı götürdüler

Hem evimize bir erkek lazım

Bilmem babamı ne zaman getirecekler

Sen de çıkma artık Ahmed

Ve bil ki şeytan düşmandır

Ve etrafımızda kulları vardır...', '- Bağdat''ta doğmuş olan küçük Halid''in çalınmış çocukluğuna ağıt... - Ben gelemeyeceğim bugün Ahmed Sen de çıkma bundan sonra Hani biz daha ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Köse']::text[], 8.5, '{"poet":"Hakan Köse","poet_slug":"hakan-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gelemeyecegim-ahmed-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmiş,Geçmiş Tek Bahar...', 'gelmis-gecmis-tek-bahar-i-brahim-ethem-bingul-wa5ao', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanıyamamıştım seni bir tanem

Aşkta yoktu öncem,yoktu tecrübem

Sevda sabahını özlüyor gecem

Sen sonbaharımda ilk baharımsın..

İlk ve son aşkımsın, gülüm başkasın

Yazılmamış şiir,gök kuşağımsın

Sen sevda pınarım,sığınağımsın

Kavrulan kalbimde hayat bağımsın..

Buz tutmuş duygular çözüldü aşkla

Çöle dönmüş kalbim senle bambaşka

El değmemiş hisler gelmezken akla

Seninle boy verdi anlamaz mısın..

Tanıyamamışım seni bir tanem

Seninleyim şimdi senden vaz geçmem

Gülüm,göz bebeğim,aşkım,düşüncem

Beni sevmez,bana sarılmaz mısın...', 'Tanıyamamıştım seni bir tanem Aşkta yoktu öncem,yoktu tecrübem Sevda sabahını özlüyor gecem Sen sonbaharımda ilk baharımsın.. İlk ve son aşk...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelmis-gecmis-tek-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp ve yitik bir şehirdim', 'kayip-ve-yitik-bir-sehirdim-gencay-coskun-ql68z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kayıp ve yitik 

Bir şehirdim 

Ağlıyordum 

Birazdan 

Kendi göz yaşlarımla

Sular altında 

Kalacaktım

Cıvıl cıvıl sokaklarım 

Sessizliğe bürünüp 

Yalnızlığın efendisine 

Kendi kendi

Teslim edecekti

Kayıp ve yitik 

Bir şehirdim 

Susuyordum 

Kendi yalnızlığımda

Kendim boğuluyordum 

Kayıp ve yitik 

Bir şehirdim 

Susuyordum 

Kendi yalnızlığımda

Kendim kendime küsüyordum 

Bir ışık gelsin diye 

En uzun kulelerimi 

Sular üstünde tutmaya 

Havayı solumaya 

Güneşi tutmaya 

Acı acı 

İçimden 

Çabalıyordum 

Küsüyordum hayata

Hayatın umuru 

Bile olmuyordu 

Nede olsa 

Benden 

Geldiğim 

Yerlerde 

Daha çok vardı 

Benimse 

Benden başka 

Bir yaratanım

Birden birlik 

İçinde 

Bir ben vardı 

Kayıp ve yitik 

Bir şehirdim 

Çok geçmez 

Birazdan

Sevgisiz 

Ölüyordum 

Kayıp ve yitik 

Bir şehirdim 

Erkenden 

Törensiz 

Kendi içlerime 

Gömülüyordum', 'Kayıp ve yitik  Bir şehirdim  Ağlıyordum  Birazdan  Kendi göz yaşlarımla Sular altında  Kalacaktım Cıvıl cıvıl sokaklarım  Sessizliğe bürünü...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/kayip-ve-yitik-bir-sehirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-baris-pinar-tumer-33lad', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde

İnsan sesleri vardı

Ve her biri

Memnun oluyordu 

Tanıştığına

Yalnızlığımı

Görüp de gelmişlerdi

dolmuşlardı içime

Kadeh tokuşturuyorlardı

Benimle tanışmanın şerefine...

Şerefe! Şerefe! 

Anlamak istemediler

suskunlukla cevap verişimi

Yalnızlığın

lafı mı olurmuş aramızda...

Söyleyecek sözüm yok....', 'İçimde İnsan sesleri vardı Ve her biri Memnun oluyordu  Tanıştığına Yalnızlığımı Görüp de gelmişlerdi dolmuşlardı içime Kadeh tokuşturuyorla...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizlik-162-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yazarım Arada Bir', 'siir-yazarim-arada-bir-zeki-ergin-w5c8z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şiir sever 

şiir yazarım arada bir

diyemesem de kendime şair

bir şair kadar özgür

bir şair kadar duyarlıyım hayata 

hep kıskanırım 

kuşları balıkları

sınırtanımazlar 

avcılara av olana kadar

tel örgü yoktur yollarında

dağlar denizler aşarlar

ne de kelepçe kollarında

_erenköy 13may''04

_şarkılar savrulur Ege''den yt,mar''14', 'şiir sever  şiir yazarım arada bir diyemesem de kendime şair bir şair kadar özgür bir şair kadar duyarlıyım hayata  hep kıskanırım  kuşları ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/siir-yazarim-arada-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair Soru İşaretleri Ve Sen....', 'hayata-dair-soru-i-saretleri-ve-sen-baris-pinar-tumer-2otbh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatın soru işaretleri

üşüşmüştü başıma

Bense 

Onlardan

Baston yapıyordum

Hayata dayanmak için

Noktalar kalıyordu geriye

Onları da ipe diziyordum

Aleme ibret için

Derken seni tanıdım...

Ne iyi ettin de

Geldin...

Hoşgeldin...

Tam da sorularımla 

Boğuştuğum anda

Çözümlerini getirdin

Artık

Bastona ihtiyacım yok

Sen varsın ya....

İnsan seni tanıyınca

Şiir yazıyor

Hele bir de yaşarsa

Şair oluyor...

Sen....

Soru işaretlerini

Küpe yaptım 

astım kulaklarıma

Hayat! 

Kızma bana

Seni ciddiye almıyorum diye

Seviyorum

Heeeeyyytttt!', 'Hayatın soru işaretleri üşüşmüştü başıma Bense  Onlardan Baston yapıyordum Hayata dayanmak için Noktalar kalıyordu geriye Onları da ipe dizi...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hayata-dair-soru-isaretleri-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Bir Ülkenin Buluttaki Yankısına Yakarış', 'yitik-bir-ulkenin-buluttaki-yankisina-yakaris-abdullah-yusuf-f0q1p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(çocukluğunda erik ağaçları taşlanan bir adamın

işlenmemiş günahlarına yazılmıştır.) 



içerimde biryerleri eksilterek gelen rüzgar

kıtalarca akarsuyun üstünde titreten

bilmediğim biryere götüren akşam.



bir boşnak beni tanıdı diye böyle uzak

böyle gitmiş bir mevsime yanarak

ağaçlar hala yaprak döküyor diye yaşamak.



uzak gözlerinde gergef bir mağara kar tanesi

kan çekilince parmakuçların titrer ey çocuk

mızıkan yorgun soğuktan üşümüş..



gücümü kemiren bir damarım kanıyor ısrarla

şehir kimseye hesap sormadığı için

gitmemek anlamsız

bu şehirden kaçmak vaktidir artık.



güneşin 

ellerimde kanadığı biryerde bekliyorum seni

pervasız bir bulut gibi çökerken hatrıran

çehreler zamana umarsız

kan çanağı gözlerinde ıssız bir gecenin

göğsümü katran rengi bir ateşe tutar gibi

rüzgarlara kanat tutmasını öğrenmişim

bir dünya çekip gidiyor içimden oysa

ben bekliyorum seni; bekliyor herşey..



ölümün cesur soğukluğunu avuçlarımdan kovdum

baharından bir bukle nefes çalmış gibi

artık ben

yaşamak işine mecbur meftun bir adamım

korkarak yaşanmaz hayat üstüne gidiyorum

herdaim kara gözlerini koklar gibi duruldu zaman

bir dünya çekip gidiyor içimden

bekliyorum; bekliyor herşey..', '(çocukluğunda erik ağaçları taşlanan bir adamın işlenmemiş günahlarına yazılmıştır.)  içerimde biryerleri eksilterek gelen rüzgar kıtalarca ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yusuf']::text[], 8.5, '{"poet":"Abdullah Yusuf","poet_slug":"abdullah-yusuf","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yitik-bir-ulkenin-buluttaki-yankisina-yakaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken Şarkılar Öldüren Adam', 'giderken-sarkilar-olduren-adam-abdullah-yusuf-jqkdu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'soğukta yandı adam

soğuk

dayandı

soğuk da 

yandı.

iğdiş edilmiş bir şehrin yarası kanadı

kuş kanatladı şehri

kanatlandı kan.

gövdesinden ayrılmış bir boyunla hasbihal ederek

erilmez sırların üzüntüsünü yaşadık

soğuk da yakarmış

kanarmış kuşun da yarası

anlaşıldı

yaşadık ve de.', 'soğukta yandı adam soğuk dayandı soğuk da  yandı. iğdiş edilmiş bir şehrin yarası kanadı kuş kanatladı şehri kanatlandı kan. gövdesinden ayr...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yusuf']::text[], 8.5, '{"poet":"Abdullah Yusuf","poet_slug":"abdullah-yusuf","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/giderken-sarkilar-olduren-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıklar vardı', 'karanliklar-vardi-gencay-coskun-gzej1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle kızgın 

Öyle küskün 

Bir mevsimdi

Yapraklar

Dökülmezdi

Bodoslamasına

İntihar ederdi

Gözlerin renklerinde 

Gizli gizli 

Karanlıklar vardı 

Bu karanlıklar 

Saklanmış 

Aldatan 

Yalanlara

Yardım ve yataklık 

Yapardı 

Küfür gibi 

Acıtırdı canı

Çıkmadıkça can 

Acıda çıkmazdı

Çıkacaksa bile acı

Yine acıyla çıkacaktı

Acıda olsa 

Gerçek

Yalan kadar 

Acıtamazdı canı

Gün ışığına çıkamamış 

Gerçeklerin 

Sızısı 

Fena halde acıtıyordu canı

İkiliklerden fazlası 

Daima zarardı 

Gönülde tek 

Olan 

Sonsuza kadar 

Tek olacaktı

Kökü olmayan 

Düşünceler

Karanlıkta

Ateş kadar 

Tehlikeli

Ne kadar 

Söndürsen

O kadar 

Derinden yanardı

İçinden dışından 

İnsan karardı', 'Öyle kızgın  Öyle küskün  Bir mevsimdi Yapraklar Dökülmezdi Bodoslamasına İntihar ederdi Gözlerin renklerinde  Gizli gizli  Karanlıklar vard...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/karanliklar-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağulanan Bir Ateş Sarkıyor Boynundan Akasyaların', 'agulanan-bir-ates-sarkiyor-boynundan-akasyalarin-abdullah-yusuf-jfa92', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şimdi küçük bir adamı çekip atardın

sen ellerinden gökyüzünün

toprak senin bilge duruşundaki defne

kokusuna meftun olurdu

aşk diye varılmış bir coğrafyanın sancısı

yankılanırdı mabedinde

mabedin senin kozalardan ve manolya

yapraklarından

sen kimdin

kim sen olduğun için

geldi

penceresi açılmasaydı içeriye girerdi

baygınlıklar

şimdi eğer böyle gözükmeseydin suyun teninde

kırılgan

küçük bir adamı çekip atardın sen ellerinden

gökyüzünün', 'şimdi küçük bir adamı çekip atardın sen ellerinden gökyüzünün toprak senin bilge duruşundaki defne kokusuna meftun olurdu aşk diye varılmış ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yusuf']::text[], 8.5, '{"poet":"Abdullah Yusuf","poet_slug":"abdullah-yusuf","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/agulanan-bir-ates-sarkiyor-boynundan-akasyalarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '/Nefesimsin/son soluğum/', 'nefesimsin-son-solugum-i-lkgul-celebioglu-56rqz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yüreğime sığmadı bu ayrılığın acısı

gözlerden boşalan yaşlar 

ümitsizliğin çırpınışları oysa

artık ümidimde yok gibi

senden ve sevdandan yana

gittin büsbütün uzaklara kaybettim izini

..............................

.................

yüreğim yüzmeyi bilmez biliyormusun? 

alabora olmuş hırçın dalgalara yenilmiş.

sen umursamazlığındasın hâlâ

bu gidişimin! 

..............

....

ben gidiyorum ebedi sonsuzluğa

son nefesimide adını anarak veriyorum

nefesimsin 

ve

sensiz 

soluk 

alamıyorum.........', 'yüreğime sığmadı bu ayrılığın acısı gözlerden boşalan yaşlar  ümitsizliğin çırpınışları oysa artık ümidimde yok gibi senden ve sevdandan yan...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nefesimsin-son-solugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni benden başka', 'seni-benden-baska-ayten-ozlem-yesilcali-zejxp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yara arz edeyim kendi halimi.

Nerden sevdim bilemedim zalimi.

Çok ugraştım tutamadım dilimi.

Bunu benden başka bilen oldumu.

Benden selam edin o nazlı yara.

Üzülüp dert edip giymesin kara.

Hasta oldum düştüm yollara.

Seni benden başka soran oldumu.

Sinirler bozuk gözler kararmış.

Rengi kaçmış ak duadaklar morarmış.

Çok görmeyin kıskananlar sorarmış.

Seni benden başka öpen oldumu.

İşte böyle olur sevenlerin halleri.

Soldu aşk bagımın gülleri.

Bilmem incindimi yarın belleri.

Seni benden başka saran oldumu.

Sevdigim bir zalim bunu bilmedi.

Yaktı aşk ateşin döktü külünü.

Ben kokladım dost bagının gülünü.

Seni benden başka seven oldumu.', 'Yara arz edeyim kendi halimi. Nerden sevdim bilemedim zalimi. Çok ugraştım tutamadım dilimi. Bunu benden başka bilen oldumu. Benden selam ed...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-benden-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemenin Sıkıntısı', 'beklemenin-sikintisi-metin-yalti-48f05', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşamın erken indiği gündü

Aysa geç kalmıştı mehtabına

Bütün suç bulutların olsada

Bilirsin beklemenin sıkıntısını

İçimdeki sıkıntı yüzümden okunuyor.

Bilirsin ay yüzlü kız

Demli bir bardak çayın buğusu gibi

Benliğimi sardığını...

Bu seferde geç kalma bari

Dünyaya geç kalman misali

Ay yüzlüm, baharım benim

Sana kızamadığımı bilsende

Hiçbir zaman hiçbir şeye

Ve sevdiğine

Ve sevenlerine,

Geç kalma sen gene de..

Aşkla dolu bir yürek

Hızlı çarpar her daim

Bu nedenle yorgun yürektir sevgilim.

Günün bir vaktinde

Genellikle  bir akşam üzeri

-Seni beklerken-

      Durmaya aday yürektir.

Çabuk o sevgilim

Gözlerim özlem

Yüreğim heyecan dolu

Yüreğim yorgun

Günse akşam üzeri...

Hadi gel

Birer bardak demli çay içelim

Vakit akşam üzeri...

11/5/04/  Sadabat', 'Akşamın erken indiği gündü Aysa geç kalmıştı mehtabına Bütün suç bulutların olsada Bilirsin beklemenin sıkıntısını İçimdeki sıkıntı yüzümden...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beklemenin-sikintisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Anlarsın Baba', 'sen-beni-anlarsin-baba-metin-yalti-yve3u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittiğinden beri acın içimde ilk günkü gibi

Özlemine dayanmak öylesine zor

Anımsadığımda kopuyor içimden bir şey 

Yokluğuna bir türlü alışamadım baba

Sağlığında   gelmezdim sana bu kadar 

Şimdi  bir hafta atlasam daralıyor içim 

Ne zaman gelirsem ferahlıyorum

Beni anlıyorsun değil mi baba? 

Geçen yazdan bu yana sıkıntıdayım

Ne anneme yüzüm var ne kardeşlerime

“Bu kız iyi kadın olur” demiştin  ya bana

En büyük desteğim karım haklıymışsın baba

Kızım da büyük destek  annesi gibi

Oğlan sanırım  bana çekmiş bazı  üzüyor bizi

Şimdi söylediklerini anımsıyorum da

Dilerim düşmez benim hatalarıma baba

Şükür ki yetiştirmişsiniz ağabeyimi

Çekmedi hiçbir zaman benden elini... 

Kız kardeşlerim de öyle yeğenlerimde

Ben neden böyleyim bilemiyorum baba

Annem ve abım  çok üzgün her bir halime

Ben de üzgünüm onların bu  hallerine

Eğer bir şey gelirse bir gün başlarına

Ben sebep olacağım korkarım baba...

Eşin dostun yüzüne çıkamıyorum 

Sana gelmeye bile utanıyorum

Kimse inanmasa da Tanrı şahidim

Bu naçar kalmayı hak etmiyorum baba

Herkes çek elini diyorlar  bu işten bana

Tamam da ne yaparım bu yaştan sonra

Her inişin bir çıkışı olur mutlaka

İçimde hala ümit var ne dersin baba? 

Gözü yaşlı   karım akşamdan sabaha

Karamsarlığım artmakta her gün biraz daha

Sen orda  daha yakınsın söyle Allaha

Bana bir kolaylık versin hatırına baba...

Hangi işe el attımsa elimde kaldı

Oysa ki amacım herkesi rahat ettirmekti

Bu kadar eğitim bunca yıl deneyim havada kaldı

Senin yanına mı gelsem ne dersin baba? 

1/5/2004 / Zincirlikuyu', 'Gittiğinden beri acın içimde ilk günkü gibi Özlemine dayanmak öylesine zor Anımsadığımda kopuyor içimden bir şey  Yokluğuna bir türlü alışam...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sen-beni-anlarsin-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevilmeden sevmek.', 'sevilmeden-sevmek-ayten-ozlem-yesilcali-ug2ze', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninlede sensizde olmuyor.

Ben durmuşumda yürek durmuyor.

Beklerim yar halimi sormuyor.

Sevilmeden sevmek ne zor şeyimiş.

Bekliyorum telefonlar çalmıyor.

Neler çektiğimi o yar bilmiyor.

Sel oldu gözyaşlarım dinmiyor.

Sevilmeden sevmek ne zor şeyimiş.

Sabredip deniyorum o yari.

Diyordu sevmişti beni.

Belkide kandırdı kendini.

Sevilmeden sevmek ne zor şeyimiş.

Saatler geçti kaygılar arttı.

Tahamül tükendi canıma yetti.

Seni görmeden günlerim geçti.

Sevilmeden sevmek ne zor şeyimiş.', 'Seninlede sensizde olmuyor. Ben durmuşumda yürek durmuyor. Beklerim yar halimi sormuyor. Sevilmeden sevmek ne zor şeyimiş. Bekliyorum telefo...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevilmeden-sevmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonlar', 'sonlar-gencay-coskun-x9058', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonlar

Karanlık Bakışla 

Geliyordu 

Sen bu kapıda dur

Diyordu

Her geliş

Parçalayarak 

Vuruyordu 

Her vuruş 

Öldürüyordu

Her ölüm 

Sanıldığı 

Gibi 

Her şeyi 

Sona erdiremiyordu

Sona ermeyen 

Her şey 

Daha çok 

Yakıyordu 

Her yangın 

Küllenmiyordu

Aslında yananda 

Yok olanda

Gülden kulelerdi

Ama izi kalırdı 

Yağmurlarda

Döküldükleri yanaklarda

Sızım sızım ağlarken 

Yağmurlarda

Karanlık bakışla

Sonlar 

Geliyordu

Diller suskundu ama 

Hadi durma 

Git artık 

Diyordu', 'Sonlar Karanlık Bakışla  Geliyordu  Sen bu kapıda dur Diyordu Her geliş Parçalayarak  Vuruyordu  Her vuruş  Öldürüyordu Her ölüm  Sanıldığı ...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sonlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-ayten-ozlem-yesilcali-6w1rz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmenin yaşı yok derler.

Dogruymuş sevdim işte.

Sevdigimi haykırdım her görüşte.

Bende dedi yüzüme bakıp.

sigara agzında  alay edecesine.

Sanki kimligini haykırıyordu futursuzca.

Yalanlar dizi dizi,düşmüyor dilde.

İnandırdıgını sanıyor zavallı.

Her yalan söyleyişte.

Ne yapayım dostlarım.

Sevdigim yalancı işte..', 'Sevmenin yaşı yok derler. Dogruymuş sevdim işte. Sevdigimi haykırdım her görüşte. Bende dedi yüzüme bakıp. sigara agzında  alay edecesine. S...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalanci-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On bir torba', 'on-bir-torba-gencay-coskun-0wr51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'On bir torba

İçinde 

Tam on bir yürek vardı 

O yürekleri torbaya 

Koyanların 

On bir bin dünyası olsa

On bir binini de 

Köküne Kibrit suyu

Çalarım 

Benim kardeşim 

Benim ağbim 

On bir yüreğin 

Gerçek sahibi 

On bir yüreğin 

Analarıdır

Korkaklık İşlemişse 

Baştaki Şerefsiz 

Genetiği 

Ayrı ayrı 

Oynanmış 

Tohumları olan 

Cengaverlere

Alacaksın bu 

(Zatı şahane)  cengaverleri 

Torba geçirip kafasına 

Salacaksın 

Eskiden Kızılderili 

Yurdu olan 

Ağlayan topraklara

On bir torbaya 

On bir yüreği

Koyanları da

Onlara 

Yalakalık 

Yapanları da

Seyirci 

Olanları da

Zıkkım şerbetlerini

Terslerinden 

İçecekler

Utanmazlar 

Daha yok mu 

Diyecekler…..

Güç bilgide

Bilgi gönüldedir.

Kızıl derili değilim 

Ama

Her an olabilirim.

Ama bu sefer 

Son değilim.', 'On bir torba İçinde  Tam on bir yürek vardı  O yürekleri torbaya  Koyanların  On bir bin dünyası olsa On bir binini de  Köküne Kibrit suyu Ç...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/on-bir-torba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-ferit-teksoy-vjbxi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bahar günüydü,aylardan Mayıs

Çiçekler rengarenk,toprak uyanmış

İçimde bir özlem adı konmamış

İşte öyle bir gün gelmiştin,gülüm

Heyecan getirdin yaslı dünyama

Yeni umut kattın umutlarıma

Anlam kazandırdın duygularıma

Böyle boşluktayken gelmiştin,gülüm

Bilmem ki yıllardır nerelerdeydin

Yerini bilseydim gelir beklerdim

Yemin olsun geri gidebilseydim

Ömrün yarısını verirdim,gülüm

Yirmi yıllık rötar neler yaptı bak! 

Seni benden aldı,beni yıktı bak! 

Pehlivandım güya şu halime bak! 

Paçayı çok fena kaptırdım,gülüm

Kime sitem etsem? ..bilemiyorum

Gülmek istiyorum! ..gülemiyorum

Serde erkeklik var..sinemiyorum

Cepheden kaçmam ben bilesin,gülüm! ..', 'Bir bahar günüydü,aylardan Mayıs Çiçekler rengarenk,toprak uyanmış İçimde bir özlem adı konmamış İşte öyle bir gün gelmiştin,gülüm Heyecan g...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gulum-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir Misin Aşkı', 'bilir-misin-aski-suleyman-yilmaz-f3xls', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bilir misin ki aşkı

dökülen iki damla gözyaşı değil...

bu beyaz sayfalara yazılmış 

süslü kelime 

şiir değil

Sen bilir misin ki aşkı.

Değen el ila elüstü değil

arzu edilen tende bir dokunuş

vucüt içinde titreyen nefis değil

Sen bilir misin ki aşkı

Madde ila maddiyat değil

o kadar mübtelası olduğun dünya

edinilen mal makam değil

Sen bilir misin ki aşkı

caddelerde sokaklarda gösteriş değil

yüzükler üstüne yazılmış 

akit ila anlaşma değil

Sen bilir misin ki aşkı

Söz ila anlatım göz ile görüş değil

menfaatlerle yaklaştığın 

umduğun karlı iş değil

Süleyman sen bilir misin ki aşkı

hayal ettiğin şey değil

karın doyurduğun ekmek ila aş

gelip geçici tokluk değil

Sen bilir misin ki aşkı

kazanılan parayla pul değil

erkeğe kadında

kadını ziynette eriten 

güzel gösterilen dünya süsü değil', 'Sen bilir misin ki aşkı dökülen iki damla gözyaşı değil... bu beyaz sayfalara yazılmış  süslü kelime  şiir değil Sen bilir misin ki aşkı. De...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yılmaz']::text[], 8.5, '{"poet":"Süleyman Yılmaz","poet_slug":"suleyman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bilir-misin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Diyorlar', 'kader-diyorlar-suleyman-yilmaz-1fnre', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kimi garip kimi sefa sürer

dünya hali altta kalan inler

Mevla yazmış kader diyorlar

bu kafayla birbirin yiyorlar

toplanmış nede çok bileler

kadın erkek karışıp bir gezeler

uymuş bu düzene her fertler

olur böyle deyip te ahkam keseler

her kafadan bir film çekeler

aynı tas aynı hamam edeler

bozulmaya yüz tutmuş toplum seçeler

akışmış sürü içine kurt diyeler

işlediler faturayı tek tarafa keseler

iflas etti düzene alkış tutan ebeler

kötüye gidene yardsım edeler

bu zamanda tepetaklak oldu işler

taktılar kafaya avrupa diyeler

bizde kalmadı elde elde ilim seçeler

uçmayı bilmeyen minik serçecikler bilmezler

haçlılar bize neler ettiler

iş güç bitti top peşinde koşalar

akar oluk gibi topa caza paralar

karşımıza dikildi siyah kutu decallar

hem avrat hem erkek oynatırlar

emekli cami yolu yolak edeler

ne yapalım biz bundan sonra diyeler

gençlikte ibadeti yasak göreler

inşaallah ermeye can bulalar

zengin aklı çok işine karışma diyeler 

fakirin imkanı yok köle yapalar

gözün dikme yukarlara kör edeler

yolsuzluğu gördüm ama görmedim diyeler

bu zamanda dümen başında ki beyler

işlerine yarayınca ne de çok seveler

iyi de tutalar beyler gibi ebeler

terse gidersen Süleyman ters dilin keseler', 'kimi garip kimi sefa sürer dünya hali altta kalan inler Mevla yazmış kader diyorlar bu kafayla birbirin yiyorlar toplanmış nede çok bileler ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yılmaz']::text[], 8.5, '{"poet":"Süleyman Yılmaz","poet_slug":"suleyman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kader-diyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uymaz Yar', 'uymaz-yar-suleyman-yilmaz-ce2g9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'vurdu yine gönlüm karaya

usandım seni araya araya

yar diye duvarlara

duvarlar dile geldi senden ses yok hala

gönlüm bir gemi yüzer sularda

kasırga fırtına dolu okyanuslarda

batınca elimi uzattım kurtarsana 

balina tuttu elimi taşıdı karaya

sen yoktun geceleri karanlığında

dilim fısıldadı yar bir baksana

mışıl mışıl uyursun sen uykuda

arılar soksun dilini

yar duymaz nasıl olsa

yine gönlüm çıktı seni aramaya

gözün kalmış lüks bir arabada

haberini aldım oturmuşsun bir makama

gör işte gönlüm güvenilmez koltuk diye bakana

yıllar sonra arkandan seslendim sana

nerde kaldı o poz çalımlar bana 

senin de sürtmüşler yar duvarlara kafanı

sen de bastonb ben de baston 

şükür kavuştuk yar', 'vurdu yine gönlüm karaya usandım seni araya araya yar diye duvarlara duvarlar dile geldi senden ses yok hala gönlüm bir gemi yüzer sularda k...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yılmaz']::text[], 8.5, '{"poet":"Süleyman Yılmaz","poet_slug":"suleyman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uymaz-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan kırmızı felsefe', 'kan-kirmizi-felsefe-zafer-zengin-etnika-wsvto', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözümle gördüm bilyeyi

Binlerce bedeni deldi

Tanrıdan bile güçlü dilleri

Kötülüğü resmedendi

Kin varsa elinde

Ve kızmışsan birine

Çevir makarayı geri

Ver birazda sesi

Bağırr

Bağırr

Bırak gitsin

Giden dönmesin

Dönen ölmesin

Kalan ağlar sanırlar

Gidenleri saymazlar

Ateştir köpeğin dişi

Isırdım mı kuduz elleri

Ki adları medeni

Kan saçan ateş kuşları

Özürdür sığındıkları

Görmezler ölüp giden canları

Nasıl affetsin insan bunları

Red derim

Kurumuş terim

Bedeliyse ödeyin

Kurşundur emeğim

Yakanlara sürerim

Resmine bakıp ayı ısıran çocuğun söylencesi

Bir gece vakti izlerken havai fişekleri

Eğlendiriyor kendini 

Gazoz sesi

Sırtın üşüyor mu

Gömleğin sıyrılmış yakandan

Gözlerin düşüyor mu

Bir kan ki hiç konuşmaz

Dicle gibi

Fırat gibi akar

Şehirler kurarlar rengine

Verirler uzaktan gelenin eline

Red ederim

Tufan gelir akşamları

Çocuklar saklar uykuları

Kapıdan dinlenir çığlıkları

Hayat gider kesilir ufukları

Küser ayrılık kendine

Küser kendi ömrüne

Sarılır sırması ışıldayan tepeye

Rüzgar yer yüzüne

Ateş red ederim/Kan ederim

Basurdur dunyanın dünyanın yukarısı

Yama tutmaz yakası/Kan kırmızı

Yok değil mi! kimsenin itirazı

K A N  K I R M I Z I  F E L S E F E

Kabul ederim...

12 Mayıs 2004 '' İçimin kitabı ''', 'Gözümle gördüm bilyeyi Binlerce bedeni deldi Tanrıdan bile güçlü dilleri Kötülüğü resmedendi Kin varsa elinde Ve kızmışsan birine Çevir maka...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/kan-kirmizi-felsefe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '! Şair Oldum....', 'sair-oldum-baris-pinar-tumer-jqev2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni yaşayınca

şair oluyor insan

demiştim ya

yetmezmiş

seni görmek 

bile

insanı

şair edermiş....', 'Seni yaşayınca şair oluyor insan demiştim ya yetmezmiş seni görmek  bile insanı şair edermiş.......', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sair-oldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Hatırlattıkları', 'olumun-hatirlattiklari-ahmet-capa-74j91', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yok olmak korkusunun ağır zırhlarına büründü,

Ve canı tenden çeken bir son nefes gibi,

Pişmanlıklar kılıcını çekti yine bugün,

Gaipten bir ses yankılanır ömrümüzün duvarlarında,

Zamanın herhangi bir anında,

Bir akşamüstü ya da bir sabah,

Azrail şarkısını söyleyecek dudaklarımızda.

Ölüm yırtılan takvim yapraklarında gizlidir,

Ve bir gün o yaprakları,

Senin yerine başkası koparacak,

Sonsuzluğun kaydına düşecekler adımızı,

Mermer işçileri hangi gün bizim için çalışacak,

Bizki bu ummanda bir sandal misali,

Limanda servilerin davetkâr sesi,

Ayağından tutulup fırlatılan bir çocuk gibi,

Hangi rüzgârlar bizi kıyılara çarpacak.

Ömrümüzün bakiyesi iflasa gider,

Yankısında hayatın sedalar diner,

Göğsümüzün üstünde bir fidan biter,

Yaprağına konup da seneler akacak.

Bir çığ gibi yuvarlanıp zaman uçurumunda,

Yokluklar ovasında ruhlar buluşacak,

Minarelerden yükselince sedalar,

Bilinmez ki bu ezanlar hangi Sala’ ya çıkacak.

Bir gün devrilecek varlığımızın bahtsız ağacı,

Ödeme zamanımızdır artık Azrail’ in alacağını,

Durunca ömrümüzün yorgun kervanı,

Dudaklardan bilmemki ne dualar akacak.

(Mayıs 2004 İst.)', 'Yok olmak korkusunun ağır zırhlarına büründü, Ve canı tenden çeken bir son nefes gibi, Pişmanlıklar kılıcını çekti yine bugün, Gaipten bir s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/olumun-hatirlattiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'The Secret', 'the-secret-guclu-sonmez-feggm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Do you see me from there

Do you feel what I feel

Our souls are marked forever

Come with me to survive from the fear

Before the time has gone

Feel the power to fly in the sky

Dance with me in the fire of the Sun

We have something others can''t buy

Do you hear that scream

That''s a holy man''s cry

I swear I''ve seen the dream

There''s something we can hold on to not to die

I know it''s not on earth, it''s not in heaven

This way takes us somewhere else

Where there are more than four seasons

There''s a secret the holy man never tells

Don''t miss the time nor the point

Trust what I''m doing, I have a reason

We don''t need others to join

Our blood is so hot that we can fight the demon

(Pittsburgh, 1993)', 'Do you see me from there Do you feel what I feel Our souls are marked forever Come with me to survive from the fear Before the time has gone...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/the-secret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykır ki Unutayım', 'haykir-ki-unutayim-cemil-akkaya-i139y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seviyorum ama nedensiz

bıraktım yıkık dökük sevgileri

bıraktım senden sonra aşkı

bir şarap gibi döktüm yüreğime

ben şarhoş oldukça

unuturum sandım sendeki aşkı

olmadı unutamadım sendeki aşkı

senden kalmış yıldızları

koparamadım saçlarından

atamadım yüreğimden

yakamadım sensizliği

avutamadım bu yüreği

avutamadım sevgini

sen ol yine çık karşıma

bak yüzüme

haykır yüzüme

sevmedim de

yalandı de

unuttum de

deki bir olsun unutayım seni

sevmeyeyim bir daha

haykırmıyayım bir daha

taki bendeki sevgini

söküp atana dek...', 'seviyorum ama nedensiz bıraktım yıkık dökük sevgileri bıraktım senden sonra aşkı bir şarap gibi döktüm yüreğime ben şarhoş oldukça unuturum ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Akkaya']::text[], 8.5, '{"poet":"Cemil Akkaya","poet_slug":"cemil-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/haykir-ki-unutayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkum', 'mahkum-bora-zihni-jqyii', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acımasız bir tufan sonrası savrulan duygularım,

Aşka küsüp,yanan yüreğim,

Aylarca susan şiirlerim.

Yaraya tuz basan,

Bir sürü hatıra. 

Ne kaldı bu aşktan bana geriye? 

...

Kime kızmalıyım bilmiyorum ama.

Ben yaşadım bu aşkı ben çekmeliyim cezasını.

Aldatılmayı.

Hiçbir ortak aramadan.', 'Acımasız bir tufan sonrası savrulan duygularım, Aşka küsüp,yanan yüreğim, Aylarca susan şiirlerim. Yaraya tuz basan, Bir sürü hatıra.  Ne ka...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mahkum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Oda', 'dort-oda-bora-zihni-fim40', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz olanı, seninle olandan  değerli kılmayı, 

İçimdeki seni, gözlerimden akıtmayı.

Dört odacıkta bulamadığım

Bendeki seni

Unutmayı.

Öğrendim artık, 

Aşkını sensiz yaşamayı.', 'Sensiz olanı, seninle olandan  değerli kılmayı,  İçimdeki seni, gözlerimden akıtmayı. Dört odacıkta bulamadığım Bendeki seni Unutmayı. Öğren...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dort-oda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanan Bir Ömür', 'yanan-bir-omur-bora-zihni-i5a80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Örtülmüş bir yalnızlığın içinde

Tozlanan seni bulup,

Sıcak bir nefesle gün ışığına çıkarmak.

Ve...

Deli bir Bora gibi hayatına girip,

Bir ömür boyu ölüme sunmak.,

Söyle,

Öyle mi Dağ çiçeğim? 

...

Hayır,

Yanan bir ömürde, seni ateşe  sunmamak.

Ağlama yağmur  gözlüm,ağlama.

Sen üzülme, sen üzülme.', 'Örtülmüş bir yalnızlığın içinde Tozlanan seni bulup, Sıcak bir nefesle gün ışığına çıkarmak. Ve... Deli bir Bora gibi hayatına girip, Bir öm...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanan-bir-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iki Yabancı', 'iki-yabanci-sema-gorur-oyb4r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz seninle iki yabancıyız,

Bir ara zoraki göz gôze gelmiş,

Koşulları ve şartları tutku sanacak kadar acemi

Iki yabancıyız.

Sen, dolup taşan hayatının bir köşesine

Benide sıkıştırmayı umut edecek kadar

Cesur bir yürek…

Ben, sevgi yağmuruna tutulmayı

Ümit edecek kadar hayalperest ve ürkek…

Bu tutku değil! 

Kendi kendimizin esiri olmuşuz,

Basma kalıp fikirler koğuşumuz olmuş! 

Doğduğumuz günden var olan sınırları aşmaya

Ne hayallerimiz yeter, nede yüreğimiz…

Sende yürek te var,  uçsuz bucaksız hayaller de

Ama ben varmıyım? 

Ben koğuşunda, 

Mecburiyetten seçtiğin

Bir kader arkadaşı olmak istemem! …

Ben kalbinde bir sızı, gözünde yaş,

Dudağında tebessüm,

Ciğerinde nefes olmak isterim! 

Sana yoldaş, sırdaş, arkadaş,

Sevgili olmak isterim! 

Bana bakan gözler yıldız saçmalı yüreğime,

Elimi tutan eller 

Kıvılcım kıvılcım ateş düşürmeli kalbime! 

Geçmişini, hayatını bir kenara at,

Hayallerini yüreğini koy ortaya

Ve bir düşün…

Gözlerimi, yüreğimi,

Yalın sevgimi

Kayıtsız şartsız

Göğüsleyebilirmisin?', 'Biz seninle iki yabancıyız, Bir ara zoraki göz gôze gelmiş, Koşulları ve şartları tutku sanacak kadar acemi Iki yabancıyız. Sen, dolup taşan...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/iki-yabanci-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ölmeden', 'ask-olmeden-suskun-resital-tlifn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekliyorum, 

