INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicrana Güfte Olmasın', 'hicrana-gufte-olmasin-cafer-tayyar-ozkan-9i3x1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel, aşkımızla kenetlensin bedenlerimiz,

Sevdayı fütursuzca tatsın gönüllerimiz,

Geride yaşamadığımız tek şey kalmasın,

Kadere ağıt yakmasın, hasret kalplerimiz...

Böyle yaparsan açık gidecek gözlerimiz,

Ancak mahşerde yaşanacak ukdelerimiz,

Yürekler nefsin kapısında acı çekmesin,

Hicrana güfte olmasın, vuslat sözlerimiz...

11 Kasım 2003 Ankara', 'Gel, aşkımızla kenetlensin bedenlerimiz, Sevdayı fütursuzca tatsın gönüllerimiz, Geride yaşamadığımız tek şey kalmasın, Kadere ağıt yakmasın...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hicrana-gufte-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözü Sözle Kırma', 'gozu-sozle-kirma-derin-oger-fays6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözdür ruhuna bir bakış arayan

