INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kale', 'kale-derin-deniz-3y1io', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sağımız

             yasaklar

solumuz 

             günahlar

üstümüzde özgürce

                                gökyüzü

altımızda şehrin en yüksek yeri

ayaklarımızı batırıyoruz denize...

                                                                        30/04/04

                                                                          20:15', 'Sağımız              yasaklar solumuz               günahlar üstümüzde özgürce                                 gökyüzü altımızda şehrin en y...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kale-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-i-lhami-basegmez-oj8he', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorgunum uzandım yanı başına

Başımı dizine koyamıyorum

Soluk alışların kulaklarımda

Elini elime alamıyorum

Bir gün bile ayrılamam diyordun

Kaç gün oldu anne sayamıyorum

Canlısın içimde canlı dipdiri

Sadece sesini duyamıyorum

Susuz toprak gibi paramparçayım

Can suyum kesilmiş dolamıyorum

Yanımdasın her an yanı başımda

Arıyorum seni bulamıyorum', 'Yorgunum uzandım yanı başına Başımı dizine koyamıyorum Soluk alışların kulaklarımda Elini elime alamıyorum Bir gün bile ayrılamam diyordun K...', ARRAY['Türk Edebiyatı','Şiir','İlhami Başeğmez']::text[], 8.5, '{"poet":"İlhami Başeğmez","poet_slug":"i-lhami-basegmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anneme-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borç...', 'borc-derin-deniz-b176l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce ''Araz''a

çokca dudak payına

halen borçluyum ben

Sunay Akın''a

Öderim borcumu

geçmişime bakın

zamanı geldiğinde

fazlasıyla Sunay Akın

                                                                               01/05/04

                                                                                  21:00', 'Önce ''Araz''a çokca dudak payına halen borçluyum ben Sunay Akın''a Öderim borcumu geçmişime bakın zamanı geldiğinde fazlasıyla Sunay Akın     ...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/borc-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Birgun', 'belki-birgun-vurgun-gonlum-r3uug', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Basımda kasırga gözlerimde nem 

Sanki bir el onu silecek gibi

Kendimi sorguya ah veke bilsem.

Kader san ki bana gulecek gibi.

Hep uzaklardasın paslandı bahtım 

Bir bakıs buyu bozacak gibi.

Aylardır umutsuz umutsuz baktım

Penceremde guneş doğacak gibi.', 'Basımda kasırga gözlerimde nem  Sanki bir el onu silecek gibi Kendimi sorguya ah veke bilsem. Kader san ki bana gulecek gibi. Hep uzaklardas...', ARRAY['Türk Edebiyatı','Şiir','Vurgun Gönlüm']::text[], 8.5, '{"poet":"Vurgun Gönlüm","poet_slug":"vurgun-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/belki-birgun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-i-lhami-basegmez-vaef5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Otuz yıldır alışamadık yokluğuna; 

Otuz yıl özledik günler geceler boyu...

Annemi sana getirdim baba,dindi özlemin.

Sevdiğine kavuştun,huzur içinde uyu...', 'Otuz yıldır alışamadık yokluğuna;  Otuz yıl özledik günler geceler boyu... Annemi sana getirdim baba,dindi özlemin. Sevdiğine kavuştun,huzur...', ARRAY['Türk Edebiyatı','Şiir','İlhami Başeğmez']::text[], 8.5, '{"poet":"İlhami Başeğmez","poet_slug":"i-lhami-basegmez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/babama-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım...', 'yarim-derin-deniz-pbcjo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldızların yarısı vardı gökyüzünde

''çıplaklık özgürlüktür'' dedi

ve çıkardı üstünü

yarı çıplak

yarı özgür

yarı seviştik

yarım kalan bir gecede

vakit gece yarısıydı...

                                                                    03/05/04

                                                                      14:00', 'Yıldızların yarısı vardı gökyüzünde ''çıplaklık özgürlüktür'' dedi ve çıkardı üstünü yarı çıplak yarı özgür yarı seviştik yarım kalan bir gece...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yarim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önceler Ve Şimdiler...', 'onceler-ve-simdiler-derin-deniz-fwl7z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öncelerde bir şeyler kaybederdim

                                    değerli değersiz eşyalar

şimdilerde yanlışlıkla

yanlış otobüslere

binip yalnızlığımla beraber

kendimi kaybediyorum

                                      değerli değersiz zamanlar

önceler için

                  nedenim Aşk

şimdiler için de

                   nedenim Aşk

(önemli sual:ya sonralar...?) 

                                                                                     04/05/04

                                                                                      23:30', 'Öncelerde bir şeyler kaybederdim                                     değerli değersiz eşyalar şimdilerde yanlışlıkla yanlış otobüslere binip...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/onceler-ve-simdiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Ve Geceler...', 'dusler-ve-geceler-derin-deniz-9lxp5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşlerime ve gecelerime

almıyorum seni

onları,

senin üstüne inşa ediyorum

inşaat alanına girmek tehlikeli ve yasaktır', 'Düşlerime ve gecelerime almıyorum seni onları, senin üstüne inşa ediyorum inşaat alanına girmek tehlikeli ve yasaktır...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dusler-ve-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göl....üm', 'gol-um-baris-pinar-tumer-iiqrx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimde

Bir göl dalgınlığı

Taşıyorum

Nicedir...

Bir göl yalnızlığı

İçimde

Sırlarımı

derinlere attıkça

İyice derinleşiyorum

Bir göl oluyorum

En sır tutan halimle...

Hayallerimi yüzdürüyorum

Kendi tenimde

Her batışında

İyice derinleşiyor

Sularım....

Göl......

Kıyımda gezeyim deme

rengime aldanma

Daha da derinleşirsem

durgunluğum

sana taşar

Bir göl yalnızlığı

taşıyorum

içerimde.........', 'Gözlerimde Bir göl dalgınlığı Taşıyorum Nicedir... Bir göl yalnızlığı İçimde Sırlarımı derinlere attıkça İyice derinleşiyorum Bir göl oluyor...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gol-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız yanlış...', 'yalniz-yanlis-derin-deniz-vbu7m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanlış şehirlerin

yanlış adreslerinde

yapayalnızdık

bu yalnız bir yalnışlıktı...

                                                                                   15/05/04

                                                                                    07:30', 'Yanlış şehirlerin yanlış adreslerinde yapayalnızdık bu yalnız bir yalnışlıktı...                                                            ...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalniz-yanlis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim kim de...', 'kim-kim-de-derin-deniz-va5gf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyorum

artık yazmamak gerek

ne sana

ne seni...

Ölüm varmış GüL üm

yollarına düşene

düştüm yollarına

yollarında düştüm

düştüm de kalkamadım

Kim kimde ne kadar kaldı bilinmez

sen de ki ben güzel bir anı

bende ki sen cana batıyor

kanıyor...

kanatıyor...

                                                                    15/05/04

                                                                     03:00', 'Biliyorum artık yazmamak gerek ne sana ne seni... Ölüm varmış GüL üm yollarına düşene düştüm yollarına yollarında düştüm düştüm de kalkamadı...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kim-kim-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Gelini Adım..', 'gurbet-gelini-adim-baris-pinar-tumer-8ozur', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Gece aynaya bakma

gurbete gelin olma''

dedi babaannem

Aynalara baktım

o günden beri

gece

geceleri....

Gurbet dedikleri

Ne uzakmış meğer

akan gözyaşlarım

yol oldu da 

yine uzanamadı sana

anacığım....

Gurbet denilen

ne çıkmaz sokakmış

ne çok yüzü varmış

aynaları kırdım da

yine kavuşamadım sana

her parça kırık

daha bir uzak....

Aynalara gece

baktığımdan beri

gurbet gelini 

adım....

Aslında

Bırakmazdı beni anam

karnından uzağa

gurbet dedikleri

kundağımdan öteymiş 

anam.....', '''Gece aynaya bakma gurbete gelin olma'' dedi babaannem Aynalara baktım o günden beri gece geceleri.... Gurbet dedikleri Ne uzakmış meğer akan...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gurbet-gelini-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tırtıl...', 'tirtil-derin-deniz-yqejd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir tırtıl sevdim

küçük,güçlü bir tırtıl

dutlarımı bülbül

yapraklarımı o yedi

Puslandı yüzü

paslandı dili

sus pus oldu bülbül

o,ipek ağlarla ördü

yapraklarım bitince

verdi elime

ipeksi yalnızlığını...

Bitince yaparaklar

kelebek oldu

konmadan gitti

kalbime tırtıl...

                             

                                                                                           15/05/04

                                                                                             10:18', 'Bir tırtıl sevdim küçük,güçlü bir tırtıl dutlarımı bülbül yapraklarımı o yedi Puslandı yüzü paslandı dili sus pus oldu bülbül o,ipek ağlarla...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tirtil-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle olmak...!', 'seninle-olmak-hikmet-guner-9eji5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstemezmiyim yanında olmak,

Dudaklarını,dudaklarıma dokundurup,

Nefesini içimde hissetmek.

Gözlerinin içine bakıp, Ellerinle elele olmak.

İstemezmiyim seninle yanyana olmak,

İstemezmiyim uzun gecelerde seninle olmak,

Saatleri durdurmak, sabahlara kadar,

öyle hep kollarında olmak...', 'İstemezmiyim yanında olmak, Dudaklarını,dudaklarıma dokundurup, Nefesini içimde hissetmek. Gözlerinin içine bakıp, Ellerinle elele olmak. İs...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seninle-olmak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçları...', 'saclari-derin-deniz-mk2ju', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(uzundur karası denizin)

Saçlarını verdim körfeze

karışınca birbirine

kızıla döndü maviler

çıkınca sahte boya

karıştı aklı körfezin

beyaz beyaz köpürdü

badem çiçekleri

akasya öbekleri gibi

boşaldı Ege

bıraktı kendini denize

tek bir tel kaldı elimde

yüreğime doluyor

Devrime saklıyorum

(saçları kızıldı)

küçük bir balıktım ben

boğuldum enginliğinde

kayboldum derinliğinde

yok oldum denizlerinde...

''küçük balık

küçük balık

denizin nerede? 

denizim yok

denizim yok

ararım her yerde...''', '(uzundur karası denizin) Saçlarını verdim körfeze karışınca birbirine kızıla döndü maviler çıkınca sahte boya karıştı aklı körfezin beyaz be...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/saclari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın Sahili...', 'askimin-sahili-i-brahim-ethem-bingul-o8z6b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkımın sahilinde

Denizin dalgaları

Döverken kayaları

Köpürür dövünen su

Benim de bu sularda

Rengim beyaza döner

Aşkım sulara döner

Çırpınan bu denizin

Olurum bir parçası...

Hicranımı duydukça

Dalgalanır hislerim,

Her vuruşta

Kaya gibi bedenim

Kendi darbemle erir,

Bu ıstırap ne acı

Parçalanır ciğerim...

İçte yürek yangınım

Çeker beni denize

Şimdi engin suların

Bakın sevdalısıyım', 'Aşkımın sahilinde Denizin dalgaları Döverken kayaları Köpürür dövünen su Benim de bu sularda Rengim beyaza döner Aşkım sulara döner Çırpınan...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askimin-sahili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böylesine!', 'boylesine-ali-fikri-karadeniz-1rcdz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben....

Kendimi bildim bileli

Hiç sevmedim böyle derinden! 

Yağmurlar böylesine yağmamıştı gönülden

Şimşekler kalbime böylesine atmamıştı

Böylesine nehirler kanımda dolaşmamıştı...

Ben...

Kendimi bildim bileli

Hiç sevmedim böyle derinden! 

Gözlerim böylesine güzel görmemişti

Böylesine  sesi kulaklarım duymamıştı

Kalbim böylesine kanamamıştı...

Ben...

Kendimi bildim bileli

Hiç sevmedim böyle derinden! 

Güneş böylesine bedenimi ısıtmamıştı

Geceleri yıldızlar böylesine parlamamıştı

Böylesine yakamozun denizle dansı olmamıştı...

Ben...

Kendimi bildim bileli

Hiç sevmedim böyle derinden! 

Çiçekler böylesine boyanmamıştı

Ateş böcekleri böylesine yanmamıştı

Böylesine şarkılar namelerle dolmamıştı...

Ben...

Kendimi bildim bileli

Hiç sevmedim böyle derinden! 

Göz yaşlarım bedenimi böylesine ıslatmamıştı

Ellerin, beyaz saçlarım böylesine terlememişti

Böylesine dua’larım secdede kilitlenmemişti...

Ben...

Kendimi bildim bileli

Hiç sevmedim böyle derinden! 

Rüyalarım böylesine nurlarla dolmamıştı

Hayallerim ayyuka böylesine çıkmamıştı

Böylesine yaşamamıştım hiçbir şeyi..

Ben...

Kendimi bildim bileli

Hiç sevmedim böyle derinden! 

Duygular böylesine kalbime merdiven dayamamıştı

Ümitler dünyama böylesine tohum saçmamıştı

Böylesine beynim zamana karşı yol almamıştı...

Ben...

Kendimi bildim bileli

Hiç sevmedim böyle derinden! 

Sonbaharda böylesine yapraklar sararmamıştı

Kışta beyazlık böylesine  etrafı kaplamamıştı

İlkbaharda kelebek böylesine  havalanmamıştı

Böylesine bir yaz kanımı kaynatmamıştı...

Ben...

Kendimi bildim bileli

Hiç sevmedim böyle derinden! 

Ağaçlar böylesine boy atmamıştı

Rüzgarlar duygularımı böylesine savurmamıştı

Böylesine haykırmamıştım dünyaya

Ben Seni böyle Sevdim derinden! ! !', 'Ben.... Kendimi bildim bileli Hiç sevmedim böyle derinden!  Yağmurlar böylesine yağmamıştı gönülden Şimşekler kalbime böylesine atmamıştı Bö...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/boylesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnfaz', 'i-nfaz-ahmet-turan-altunsu-v6pnz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Suçüstü kıvamında yakalandın ey iblis:

Ruhumu iğfal eden bir karanlık güç gibi

Karanlığa paravan; güler bir yüz, mutantan…

Lâkin; sanki kalbimden alınacak öç gibi! ..

Bir gönüllü bayraktar olmaya mı soyundun; 

Sızlayan yüreğime sapladın hançerini? ..

İhanet oyununda peşrevci başı oldun; 

Sevdalı düşlerime kapattın pencereni! 

Elveda ey nazenin duygularım, elveda! 

Bahçemdeki çiçekler; güller, sümbüller üzgün! ..

Ölmek mi bu hissiyât? Zalim belli olsa da,

Ne mahkemesi belli, ne hâkîm olmak mümkün! ..

                                                 15.05.2004 - Ankara -', 'Suçüstü kıvamında yakalandın ey iblis: Ruhumu iğfal eden bir karanlık güç gibi Karanlığa paravan; güler bir yüz, mutantan… Lâkin; sanki kalb...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/infaz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Denizi', 'sevgi-denizi-hikmet-yakisir-jos4i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bir sevgi deniziyim.

İstersen,

Yelken açıp aşk şarkıları oku.

Martılar eşlik eder.

İstersen

Tanımak için ruhumun derinliklerini,

Yunuslar rehberlik eder.

İstersen,

Ruhumdan bir daha çıkma, boğul.

Sevgi denizimde.

Çünkü....

Ben bir sevgi deniziyim.

Ben bir dost’um.

İstersen

Başını omuzuma koy, ağla.

Seninle ağlarım.

İstersen,

Fıkralar anlat, gül.

Seninle gülerim.

İstersen,

Çocukluğunu yaşa, oyun oyna.

Seninle oynarım.

Çünkü....

Ben dost’unum.

Ben bir sevgiliyim,

İstersen,

Şiirler fısılda kulağıma,

Sevgi denizine dalalım.

İstersen,

Çiy düşmüş teninle sar,

Fırtınalar koparalım.

İstersen,

Ateşinle kavur beni,

Kül olalım.

Çünkü...

Sevgilinim, sevgilimsin.

Ne dersin can? 

13 Mayıs 2004', 'Ben bir sevgi deniziyim. İstersen, Yelken açıp aşk şarkıları oku. Martılar eşlik eder. İstersen Tanımak için ruhumun derinliklerini, Yunusla...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sevgi-denizi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-hikmet-yakisir-1ft4l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana seni gönderiyorum,

Bendeki seni,

Yanında beni gönderiyorum,

Sendeki beni.

Sana dargın değilim yar,

Kırgınım.

Gözlerim seni arar can,

Sensizim.

Duymak istiyorum sesini,

Duyamıyorum.

Görmek istiyorum yüzünü,

Göremiyorum.

Çaresizim yar...

İsyankarım yarrrrr...

İsyankarrr...

Beynimden silebilirim

Düşünmemek için.seni.

Gözlerimi kapayabilirim,

Görmemek için seni

Kulaklarımı tıkayabilirim

Duymamak için sesini.

Birde kalbim var benim.

Ordan da silemem ki seni.

İsyanım bundandır yar...

İsyankarım yarrr,

İsyankarrr.........

06 Mayıs 2004', 'Sana seni gönderiyorum, Bendeki seni, Yanında beni gönderiyorum, Sendeki beni. Sana dargın değilim yar, Kırgınım. Gözlerim seni arar can, Se...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/isyan-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıkların Generali', 'ayriliklarin-generali-ahmet-capa-5tawh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dimdik bakan gözleriyle,

Anılar beynimde ayaklanıyor,

Elinde meşaleler.

Kuytularımda unuttuklarımı

İsyana sürüklüyor.

Süvarisi biz değiliz onların

Bu yüzden mazi atının yuları tutulmaz,

deli bir tay çılgınlığında

ve koştururken yaylasında yoklukların,

Eyerinde hiç bir şey unutulmaz.

Yürek ülkemin başkentindesin

Bu yüzden midir Ankara’ da oluşun.

Resmin diyerek

duvarıma haritalar astım,

Bu yüzdendir kör bir duvarı mabet sayışım.

Keşke haritalara insanları da koysalar.

Şimdi gece 02-04 nöbetlerinde

Çapraza dikilmiş bir asker gibi,

Senin uykularını bekliyorum.

Gözlerinin nizamiyesi neden açılmıyor.

Sen gittin de,

Yokluğunun her gününde 

Omzuma bir rütbe taktın,

Hatıralar ordusunun

tam teçhizatlı askerleri,

İçtima düzeninde önümde bekler,

Sen beni ayrılıkların generali yaptın.

Yokluğunun kışlasında

Tezkere gelmek bilmez,

Sen ayrılık biletini 

hangi yolculuğa aldın.

Saçını düşürüp de camlara,

Kahredercesine kaldırdın elini,

Sen bana mı, 

bütün bir şehre mi el salladın.

Aşkın ocağında kül ettin de,

Bilmem ki beni,

Zümrüd-ü Anka mı sandın,

1999 Hudut Karakolu Akçakale/Ş.Urfa', 'Dimdik bakan gözleriyle, Anılar beynimde ayaklanıyor, Elinde meşaleler. Kuytularımda unuttuklarımı İsyana sürüklüyor. Süvarisi biz değiliz o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ayriliklarin-generali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitirdin Her Şeyi...', 'bitirdin-her-seyi-i-brahim-ethem-bingul-ft4bd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Telefonlarımın hiç biri cevap vermiyor

Meşgul sinyali de yok

Anlamışsındır, hepsi kapalı değil mi? 

Artık bulamazsın beni, anladın mı? 

Bitti, bitirdin sen her şeyi

Duydum, yerime de gelmişsin

Beni sormuşsun

Yokum işte anlamalısın

Arama, bulamazsın evde değilim,

Gittim artık bilmelisin

Bitti, bitirdin her şeyi..

Esirisin o gururunun

Prangalar ellerinde, boynunda

Bir kelimenin kurbanısın da

İş işten geçti

Berbat ettin her şeyi

Niye ararsın, ne diyeceksin

Biliyorum özür dileyip yeniden

Sevilmeyi beklersin

Beyhude bekleme, bitti

Berbat ettin her şeyi..

Ha, şayet çok istiyorsan beni

Yeni adresimi vereyim,

Ararsan bulursun

Ama unutma, gelirken yanında

Bir çiçek bulundur,

Bir de...

Okursan Fatiha..

Şimdi iyi düşün yeni baştan

Ben miyim, yoksa sen misin kurtulan...', 'Telefonlarımın hiç biri cevap vermiyor Meşgul sinyali de yok Anlamışsındır, hepsi kapalı değil mi?  Artık bulamazsın beni, anladın mı?  Bitt...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bitirdin-her-seyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-mehmet-elmacioglu-84439', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Billur inciler döker

Kara bulut kümeleri

Yüreğimizdeki sevgiler

Büyüsün diye sanki

Yalnızca dizelerde belki

Böyle güzel yakar

Gökyüzünün gecelerini

Yağmur sonu yıldızlar.', 'Billur inciler döker Kara bulut kümeleri Yüreğimizdeki sevgiler Büyüsün diye sanki Yalnızca dizelerde belki Böyle güzel yakar Gökyüzünün gec...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Sayfa', 'bos-sayfa-erol-dal-571vw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu satıra kadar temizdi sayfam.

Yazdım; 

Kirlendi.

ED/Mekan/04

.', 'Bu satıra kadar temizdi sayfam. Yazdım;  Kirlendi. ED/Mekan/04 ....', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bos-sayfa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irmaklar hep yalnız akardı', 'irmaklar-hep-yalniz-akardi-gencay-coskun-dpjox', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Solgun anılardı

Rengi bambaşka diyarlardı 

Ne gökyüzü gökyüzüne 

Ne yeryüzü yeryüzüne 

Benziyordu 

Belki birazcık

Benzetiliyordu

Bir garip yeşildi

Küçük volkanların kustuğu 

Beynimde 

Gri Bulutlar vardı 

Dokunsalar 

Yağacaklardı

Irmaklar hep yalnız akardı

Bense yağmura camlardan bakardım 

Demini çoktan almış çayım 

İçtikçe uykusuzluğa 

Sözde bahanem olurdu

Çakmaklardı hediyelerim 

Ömrümde sigara içmemiştim

Bahardı başımı döndüren 

Hayatta kıştan başka mevsim tanımazdım

Yeni gelen baharla 

Az önce tanıştırıldım 

Konuştukça yeni gelen mevsimle 

Nedense bir garip tanıdık geldi

Sonradan öğrendim 

Kendi yağmurlarımda 

Islanmayı 

Eritemediğim duygularımı 

Islatmayı 

Tüm baharlar benim için 

Islatırdı dünyayı 

Toplanırdı damlalar 

Akarlardı bir yerlere

Ama 

Irmaklar hep yalnız akardı

Düşünmek 

Zorunda olmadığım 

Anlarım 

Savunulmadan geçen tek bir günüm

Ve bir sinema 

Sinemada uzun bir film 

Filmin sonu 

Benim sonum olsun', 'Solgun anılardı Rengi bambaşka diyarlardı  Ne gökyüzü gökyüzüne  Ne yeryüzü yeryüzüne  Benziyordu  Belki birazcık Benzetiliyordu Bir garip y...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/irmaklar-hep-yalniz-akardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarım Gelmiş', 'dostlarim-gelmis-i-hsan-dinibutun-nb9e5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dostlarım gelmiş yıllar sonra

Aç kapıyı, kur sofrayı içelim doyasıya

Hoşgeldiniz, sefalar getirdiniz bizlere,

Gülelim, eğlenelim bu gece.

Şarkılar susmasın,

Boşalmasın kadehler; 

Mezeler tükenmesin,

Bu gece hiç bitmesin

Hoş geldiniz sefalar getirdiniz bizlere,

Gülelim, eğlenelim bu gece', 'Dostlarım gelmiş yıllar sonra Aç kapıyı, kur sofrayı içelim doyasıya Hoşgeldiniz, sefalar getirdiniz bizlere, Gülelim, eğlenelim bu gece. Şa...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dostlarim-gelmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Lafın Kısası', 'uzun-lafin-kisasi-okan-savci-tcmci', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevmek zaman aldı...

Zaman da seni aldı benden...', 'Seni sevmek zaman aldı... Zaman da seni aldı benden......', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/uzun-lafin-kisasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Titreyen Ellerin Hala Avucumda', 'titreyen-ellerin-hala-avucumda-okan-savci-ygo78', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bu kente benziyorsun,

Bir gününde dört iklim.

Hükmünü bende sürüyorsun......

Sararıyorum bir vakit.....

Sonra,

Çığ düşürüyorsun geceme

Derken buzlarım yine seninle eriyor...

Bir de yansaydım ateşinde? 

Ne iyi olurdu! 

Ama bu şehre bir türlü yaz gelmiyor......

Giderken, 

Mevsim kıştı hatırlarsın........

Titreyen ellerin hala avucumda! 

Sana bahar geldi mi bilmem? 

Bildiğim; 

Geceleri güzel yüzünü yastığıma koyup

Uyuyorsun başucumda...

Nasıl da keyifli? bir bilsen! 

Senden habersiz,

Seninle sohbet ediyorum......

O an,

Zaman ne kadar da güzel! 

Sabah hiç gelmesin istiyorum.....

Unuttum sesini,

Konuşsan tanıyamam.....

Oysa dün gibi bu firar? 

İşte sana bir tezat daha! 

Sen bu kadar aklımdayken,

Sesin neden yabancı bana? ? ? 

Aşk! 

Her yalanın toplamıydı...

Ve sen, zamanı onun içine kattın! 

Şimdi,

Yaşadığın geceleri kıskanıyorum......

Rüyalarına hiç giremedim ya? 

Bu şiiri o yüzden yazıyorum....', 'Sen bu kente benziyorsun, Bir gününde dört iklim. Hükmünü bende sürüyorsun...... Sararıyorum bir vakit..... Sonra, Çığ düşürüyorsun geceme D...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/titreyen-ellerin-hala-avucumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu akşam', 'bu-aksam-mehmet-elmacioglu-pp4ls', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu akşam başka vurdu şişe

Yıllar öncesini anımsadım

Durup dururken yine.

Belki yalnızlık körfeze indi diye

Deki ömür kırka geldi diye.

Terketmiştim oysa,kimbilir niye? 

elim uzandı sigaraya

Saldım dumanını,vardı değdi aya.

Ay döndü kızıla

Çekti eteğini

Kaçtı gizlendi dağa,

Oda aldı taç etti başına,

Kıral oldu koskocaman dünyaya

Belli bu akşam başka vurdu şişe.

Dellendi dağlanmış yüreğim,

Döndü kor ateşe.

Savruldu karanlığa inat,

Benzedi ışık seline.

Bilmemki niye şaşırdı görünce,

Çoban yıldızı düştü elime.

Ben ağladım o güldü

Elim yandı attım yere. 

Ben güldüm o ağladı.

Nereden çıktı, dokundu öylesine, 

Bir kuşun kanadı

Kırıldı şişe..', 'Bu akşam başka vurdu şişe Yıllar öncesini anımsadım Durup dururken yine. Belki yalnızlık körfeze indi diye Deki ömür kırka geldi diye. Terke...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bu-aksam-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Astımım', 'astimim-baykal-kaanalp-1ka6x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dünden

kuşbakışı bir uzaklıkta olan

ağır ağdalı sözlerin

bugün

cuk oturdu masama

senin sözlerinle konuşur oldu

gözlerim

senin yaktığın çırayla

tutuştu yüreğim

dünden 

kuşbakışı bir uzaklıkta olan

bunaltan sıcaklığın

bugün

soğudu tenimde

senin sıcaklığınla ısınır oldu

ellerim

senin getirdiğin havayla

sona erdi astımım', 'dünden kuşbakışı bir uzaklıkta olan ağır ağdalı sözlerin bugün cuk oturdu masama senin sözlerinle konuşur oldu gözlerim senin yaktığın çıray...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/astimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitapsızın birine', 'kitapsizin-birine-zafer-zengin-etnika-q6edj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Et''e sevdalı deli

Örgütlemiş çeteyi

Kaçak sokacak şehre ekşiyi

Herkesin en kurnazı

Selam dediysek gülme

Cilve işve bilme

Hürmet insansın diye

Elimizin tersini dönderme

Bil haddini

Güvenmiyorken kendine

Baskasını deneme

Yapcaksan işini

Kendin koyul yola

Sahtekarlık yapma

Adam tutma

Kadınsın aklın  başına topla

Kalırsın ortada

Canım eli yakamdayken

Sen bıçak dayama boğaza

Akıldan şaşma

Kurnazla dost olma

Olursun başa bela

Haydi şimdi yolana

Selam selam sana

Selamınıda aldın ki

Durma koş yoluna

Yolun açık ola

Her adamı bir sanma

Her kadını dost anma

Oyun kurup durma

Yalanla cıkma karsıma

Nasılsa cıkar meydana

İnsandan korkmuyorsan

Ses cıkarmıyorsam

Sabır var anla

Bir daha mesaj yazma

Kalsın arkadaslıkta..dostlukta

Uymaz bu tür benim yoluma

Yolun açık olsun..gerçek yoldaşın..eywallah

15 Mayıs 2004  '' kitapsızın birine ''', 'Et''e sevdalı deli Örgütlemiş çeteyi Kaçak sokacak şehre ekşiyi Herkesin en kurnazı Selam dediysek gülme Cilve işve bilme Hürmet insansın diy...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kitapsizin-birine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Ver', 'geri-ver-baykal-kaanalp-qqnq5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eriyen kardan adam

benden aldığın

elma şekerini

geriver

geri ver boncuklarımı

uc uca ekleyip

gülücükleri birleştirdiğim

sonra uçurtma yapıp

şehre salıverdiğim

geri ver güvercinlerimi

bir sevgiliden diğerine

haber uçurduğum

gizli gizli name yoladığım

kurdelelerimi ayaklarına

bağladığım

geri ver çaldığın

çocukluğumu

oyunlarımı

hatta kısa düşlerimi

yaladığım dondurmamı

hatta üstünden düştüğüm

kaydırağımı

hatta hiç sevemediğim

okulumu

matematik dersimi bile

eriyen kardan adam

benden aldığın

elma şekerini

geri ver', 'eriyen kardan adam benden aldığın elma şekerini geriver geri ver boncuklarımı uc uca ekleyip gülücükleri birleştirdiğim sonra uçurtma yapıp ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/geri-ver-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bşlmk', 'bslmk-baykal-kaanalp-1bif2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yolun başındayım

başlamak için

hiç bir sebebim yok

sıkıntılı yolculuklara

yol arkadaşım yok

yollara dökülmeye

yol olmaya

olmayan araçlara

araç olmaya

olmayan yollara

yol istemem 

yokuş istemem

iniş hiç istemem

yolun başındayım

kalbim sıkışık

hala karasızım

başlamak için 

başlamaya', 'yolun başındayım başlamak için hiç bir sebebim yok sıkıntılı yolculuklara yol arkadaşım yok yollara dökülmeye yol olmaya olmayan araçlara ar...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bslmk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aah', 'aah-sair-isikdan-xct14', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tende soğumuş yürek

zannedersin 

ay tutulmuş

kozasından yeni çıkan

kelebeğim 

melek olmuş', 'tende soğumuş yürek zannedersin  ay tutulmuş kozasından yeni çıkan kelebeğim  melek olmuş...', ARRAY['Türk Edebiyatı','Şiir','Şair Işıkdan']::text[], 8.5, '{"poet":"Şair Işıkdan","poet_slug":"sair-isikdan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ufukta Yeşeren Mavi Sabahta Tanım I', 'ben-ufukta-yeseren-mavi-sabahta-tanim-i-sadik-softa-octvq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Samanyolunda yıldız,bahtımda parlar söner; 

Ufkum sararır birden, fırtınalarla döner.

Beyazlarla dökülür, saadet gibi bana; 

Saçlarımda iz yapar, raslarım bir yabana.

Gülüşleri dizilir, kirpiğin kanadına; 

Bulutların gözyaşı, süzülür inadına.

Gözlerimde yol bulur, uçar o bakışların; 

Yüreğimde bir tufan koparır bakışların.

Sonra sükûtu çöker, dudaklarım sımsıkı; 

Kalbimle tokalaşır, acılar sıkı fıkı.

Getirir dalga dalga, saçlarında elemi; 

Yüreğime damlatır, gözlerindeki nemi.

Geceyi ıslattıkça, gün gözünden dökülür; 

Ceylan bakışlar sorar, gün geceden sökülür.

Çankırı-14.05.2004', 'Samanyolunda yıldız,bahtımda parlar söner;  Ufkum sararır birden, fırtınalarla döner. Beyazlarla dökülür, saadet gibi bana;  Saçlarımda iz y...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-ufukta-yeseren-mavi-sabahta-tanim-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Sesin Kulaklarımda...', 'sesin-kulaklarimda-erdal-asik-0catn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uykusuzum geceleri

sen gittiğinden beri

kabus dolu hayallerim

ağlamak istiyorum

göz yaşlarım kurumuş

sanki gönlüm çöl olmuş

seraplar görüyorum

sana uzanamıyorum

sevda çöllerinde

fırtınalar var gönlümde

sense çok uzaklarda

sesin hala kulaklarımda', 'uykusuzum geceleri sen gittiğinden beri kabus dolu hayallerim ağlamak istiyorum göz yaşlarım kurumuş sanki gönlüm çöl olmuş seraplar görüyor...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sesin-kulaklarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir güçlü ki; bakışın', 'bir-guclu-ki-bakisin-zafer-zengin-etnika-yz56v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herşey giderken işte

Bir ölüme alışamadım

Nerden biliyorum! 

.........mı uğurlamamdan

Son dokunan bendim

Pala bıyıkların da ayrılığa

Yaş küçük

Geç fark ediyor ayrılığı

Bir umut işte! 

Döner belki geriye

Turna sevmelerim 

S e b e b s i z  d e ğ i l...

Herşeyle

Ve herkesle

Dört mevsim

A n l a ş m ı ş k e n

Şu ölümle anlaşamadım

Varsın yiğit olsun elleri

Çekip koparıyorsa gülleri

S e l a m l a m a m

Bir defa olur

Bir daha borç a l m a m 

Saklıdır hakkım 

İki laf da ben ederim..

Alacağın bir c a n..

Kurun kaç

Y a ş ı n  k a ç

Para eder gerçekliğin

Kılıç bileyen adaletin

Kim der git diye

Sevemedim işte

Güllerimi koparan 

ölümü işte

Sana anlatamadım maviyi yine

Umutdan ses yok çocuk

Bir güçlü ki; ba k ı ş ı n

Ö p e m e d i ğ i m... 

Dokunma canıma

Umutla sakladığıma

D o k u n m a! ! ! 

Sana mühlet

Kabadayı aklım

Evvelini yakarım

Kül olur ayarın

6 Mayıs 2004 '' İçimin kitabı''', 'Herşey giderken işte Bir ölüme alışamadım Nerden biliyorum!  .........mı uğurlamamdan Son dokunan bendim Pala bıyıkların da ayrılığa Yaş küç...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bir-guclu-ki-bakisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlayış', 'hatirlayis-murat-soyak-1bgfk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hatırlayış

1

kefenini hazır tutan bir babanın oğullarıydık

bir yanımız bağ bahçe

bir yanımız ahir dünya

komşumuz olurdu İbrahim

bir kitap vardı evimizde

kendi yağımızda kavrulurduk

ve yandık ha koşun desek

sesimize ses veren olurdu

misafir,heybesinde kıssalar demetiyle gelen

ne güzeldi dinlemek

anlattıkça bal akar dilinden

sohbetle ısınırdı içimiz

artık kim korkar geceden

2

aldı beni nerelere götürdü şiir

hadi gitmek bir şey değil de

nasıl döneceğim bu güne

nasıl döneceğim bahçeli evden

kibrit kutusu apartman dairesine

alacağın olsun şiir

bu akşam bana bunu da yaptın

alacağın olsun', 'Hatırlayış 1 kefenini hazır tutan bir babanın oğullarıydık bir yanımız bağ bahçe bir yanımız ahir dünya komşumuz olurdu İbrahim bir kitap va...', ARRAY['Türk Edebiyatı','Şiir','Murat Soyak']::text[], 8.5, '{"poet":"Murat Soyak","poet_slug":"murat-soyak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hatirlayis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ufukta Yeşeren Mavi Sabahta Tanım II', 'ben-ufukta-yeseren-mavi-sabahta-tanim-ii-sadik-softa-jy1rw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dudaklarımda elem, korkuları silmişim; 

Tebessümler sunarken, bakışında dilmişim.

Geceye feryat benim, sevdalara selmişim; 

Gün sabaha uzarken, rüyalara elmişim.

Yolcumu bekliyordum, ufkun avuçlarından; 

Kalbimden yürüyordum, sabahın burçlarından.

Göz nurum beslendikçe, sabahlar zehir sundu; 

Şimdi gerçekler çıplak, soyundukça soyundu.

Duygular inançlıydı, iman ettim, inandım; 

Sevdaya kalp verirken, sade, saf inanandım.

Bundan böyle mabedim, viraneye dönecek; 

O''ndan başka sevgiye, tüm ışıklar sönecek.

Geceyi ıslattıkça, gün sabahla sökülür; 

Ceylan bakışlar arar, yücelir aşk dökülür.

Çankırı-15.05.2004', 'Dudaklarımda elem, korkuları silmişim;  Tebessümler sunarken, bakışında dilmişim. Geceye feryat benim, sevdalara selmişim;  Gün sabaha uzark...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-ufukta-yeseren-mavi-sabahta-tanim-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koş Evlat Sen Yakala', 'kos-evlat-sen-yakala-emel-manav-6dleq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün yere bakardın karamı kara

Bugün bakışların bir başka

Aşka mı? düştün yoksa

Koş evlat sen yakala! 

Kal orada hiç çıkma

Tadını çıkar doya oynaya

Ben çok tren kaçırdım

Koş evlat sen yakala! 

Sakın sende kaçırma

Kim ne derse desin umursama

Aşkı  sevgiyi  ben yaşayamadım 

Koş evlat sen yakala!', 'Dün yere bakardın karamı kara Bugün bakışların bir başka Aşka mı? düştün yoksa Koş evlat sen yakala!  Kal orada hiç çıkma Tadını çıkar doya ...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kos-evlat-sen-yakala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğuna Sevgi Aşıla', 'cocuguna-sevgi-asila-emel-manav-crj7w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne yapmalı, ne etmeli

Çocuğumuza sevgi aşılamalı

Sonra yürütmeye kakmalı

Geleceğin sevgi tohumları

Bence böyle atılmalı

Zalim değildir zulüm görmez! 

Verdiği sözden asla dönmez! 

Mayası sevgidir birde vatanı

Yargılamaz dinlemeden insanı.

Bitmez onun dost kervanı', 'Ne yapmalı, ne etmeli Çocuğumuza sevgi aşılamalı Sonra yürütmeye kakmalı Geleceğin sevgi tohumları Bence böyle atılmalı Zalim değildir zulüm...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cocuguna-sevgi-asila-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S e b e b i m', 's-e-b-e-b-i-m-zafer-zengin-etnika-ig628', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne 

Şiirsiz

Ne

Sensiz

Ne

Akdenizsiz

Olmuyor

Oluyorsa ben bilmem

Şiirsiz

Sensiz

Bir de

Akdenizsiz

Sebebimdir gidemem

Gidemem gül çürür yanağımda

Değmese de rengi bana

Tütün değer bıyığıma

Sebebimdir kesemem

Aşk 

Şiirsiz

Aşk 

Sensiz

Aşk

Akdenzisiz

Olmuyor

Oluyorsa ben diyemem

Batıktır sonrasında çıkan

Ovulmaz öyküler yazan

Derim çürür göze ayan

Sebebimdir deşemem

Hasret

Şiirsiz

Hasret

Sensiz

Hasret

Akdenizsiz

Olmuyor

Oluyorsa ben bilmem

Gözüm gürdü saçlarını

Değmese de rengi bana

Kokun durur burnumda

Sebebimdir çekemem

İşim var yazla

Diyemem

Tenim ve terimle

Yanıp kavrulacağım

Esmerdir kaçtığım deniz

Şair babadır saklandığım

Bahçesinde sesi

Eli cebinde resmi

Bir yanında 

	Kulaçladığı akdenizi

''Datça''ya ve Can baba''ya saygılarımla''

10 Mayıs 2004 '' İçimin kitabı ''', 'Ne  Şiirsiz Ne Sensiz Ne Akdenizsiz Olmuyor Oluyorsa ben bilmem Şiirsiz Sensiz Bir de Akdenizsiz Sebebimdir gidemem Gidemem gül çürür yanağı...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/s-e-b-e-b-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar ve Simit', 'martilar-ve-simit-musfik-saltik-ijgeb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geminin güvertesine dizilmiş hayvanları  seven iyi insanlar.

Ellerindeki simitten küçük parçalar koparıp havaya atıyorlar.

Geminin ardında telaşla uçuşan  martılar birbirleriyle yarışıyorlar.

Denize düşmeden simit parçalarını havada kapıp yutuyorlar.

İlk bakışta  güzel bir manzara gibi geliyor insana bu paylaşım

Ama biraz derinlemesine düşününce hiç de öyle değil  gerçekler.

Bir deniz kuşu  martı, o denize dalmalı, balık yakalamalı

O karnını taze balıklarla doyurmalı bu işte bir yanlışlık olmalı.

Ardından hemen ikinci soru takılıyor insanın aklına

O insanlar  gerçekten kuşları sevdikleri için mi simit atıyorlar.

Yoksa  bilinçsizce  kirlettikleri denizde yok olan balıkları  bulamayan

Açlıktan bir parça simide muhtaç olan martıların çığlıklarından utanıp.

Kendilerini bağışlatmaya mı bir anlamda  günah  çıkartmaya mı çalışıyorlar. 

Bir gün vapura bindiğinizde bir de böyle bakın martılara ve onlara simit atan  insanlara.

Neşeli kahkahalar mı martıların çıkarttığı sesler yoksa isyan çığlıklarımı 

Sonra  bir de  o insanların yüzüne bakın  huzur mu yüzlerindeki ifade  suçluluk mu 

Biraz farklı gözle  bakınca nasılda farklı görünüyor değimli gerçekler.

Belki şimdi bunlara deli saçması sözler , amma da saçmalamış diyorsunuz

Belki sizde martılara simit atıyorsunuz, bunu sadece bir eğlence olarak görüyorsunuz.

Bir kere daha düşünün martıların bağırışlarını ve onlara simit atarken ki  duygularınızı.

Neşeli kahkahalar mı çıkarttıkları sesler, onları simide muhtaç eden bizlere  isyan çığlıkları mı, 

Sıradan  bir eğlencemi yaptığınız yoksa  bir nebze olsun  özür dilemek mi, günah çıkartmak mı 

                                                                                                                          Mayıs 2004', 'Geminin güvertesine dizilmiş hayvanları  seven iyi insanlar. Ellerindeki simitten küçük parçalar koparıp havaya atıyorlar. Geminin ardında t...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/martilar-ve-simit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilemma', 'dilemma-ramazan-kalinsaz-12eaj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Br sevda tortusu gönlüne çöker

Bir gece ansızın dağlarmış meğer 

Adandığın umut belini büker 

Bir delikanlı da ağlarmış meğer

Bir sevda yap-bozu değilmiş gönül

Anladım her güzel aklı bağlarmış

Beyhude önünde eğilmiş gönül

Yazık ki huzuru çile sağlarmış', 'Br sevda tortusu gönlüne çöker Bir gece ansızın dağlarmış meğer  Adandığın umut belini büker  Bir delikanlı da ağlarmış meğer Bir sevda yap-...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kalınsaz']::text[], 8.5, '{"poet":"Ramazan Kalınsaz","poet_slug":"ramazan-kalinsaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dilemma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıktan,karar için, yükselenin üstüne yükselen', 'karanliktan-karar-icin-yukselenin-ustune-yukselen-akin-akca-qb8p9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nur-baki adına olduğunda ışık sırra-kadem; 

Kadim dosttur olasılıklar, düzen için beşeriye. 

İnsan bunu bildiğinde, koştuğunda ve uçtuğunda 

Sonsuz-enginliği’nde, ışığın kendisine bilincinde, 

Almış olduğu rüzgar onun, onun dost-sırtı''na. 

Ve böylece durup, seven uzaklaşacak 

Ve sonra şıpsevdi düşün’lerde 

Gayret düğümü’nü hatırlayacak: 

Salgısında dişi örümceğin, 

Ama his vardır hazanında kudretin. 

Ormandan bir ev vardı, iki kişiyi taşıyan: 

Kubla Khan''ın sarayı gibi; 

Müzikle inşa edilen, hem kendisi müzik olan: 

* 

Sesinde içinden yükselen karanlığın, 

Kapıları zorlanıyordu ulvi dergahın. 

Yemin veren başkalaşımında sözlerin; 

Tarla vardı güneşin yüzünde, eleğin. 

Nadasa ekili bir tarla, güneş ile coşar da; 

Dergah olduğunda şato, kasvetli, 

Kapıları zorlandığında, güneş patlar, 

Kıymetli, kendini arttırır, karanlığı yarar. 

Bir mektup, kan tüküren, kandır tükürdüğü; 

Ama, yutmadı onu ve hala işlevsel. 

Ağza bakla ıslanmayan yalanlardı havaya 

Üfürdüğü, yılmayandan geldi, toprağa bel. 

Anıtların-gözü daim olacak Nemrut’ta. 

Al-Hamra ki, Müslüman Hristiyan 

Orada kardeş idi. Onu besleyen, o ki: 

Granada! Kuşatan, işlevsel-ebedi, kuşaklara. 

Sesinde içinden yükselen karanlığın, 

Büyük ağaç zorluyordu kapılarını dergahın: 

Kitap okuyan bir baba, göstermeye çaba; 

Mum ışığı çökeltisinde, son sayfasında kitabın. 

Karanlığın içinden seslenen, girdapları aşan; 

Bağrışlarda frekanslara da karanlık ekleyen; 

Şu yerküre-yurdu''nun dört bir tarafına tohum iken … 

Ama dur! Yine tıkırtılar, kapıları aşındırıyorlar. 

Sesinde içinden yükselen karanlığın, 

‘Tek yönden mengeneler’ için, hapis-dergah''ın: 

Güç kazanmak için tekrar gerilediklerinde; 

Kapı açıldı, bir çocuktu çıkan, merakın.', 'Nur-baki adına olduğunda ışık sırra-kadem;  Kadim dosttur olasılıklar, düzen için beşeriye.  İnsan bunu bildiğinde, koştuğunda ve uçtuğunda ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/karanliktan-karar-icin-yukselenin-ustune-yukselen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüme Uçan Aşkın Kıvılcımı', 'dusume-ucan-askin-kivilcimi-yuksel-ozbek-eppg9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşüme Uçan Aşkın Kıvılcımı

Yağmur damlası hafifliğindesin.

Oysa,

Sana düşüşüm,şimşek ağırlığında.

Kölelik

            Sonrası 

                         Özgürlük

                                         Değerindesin.

Yeşilliğinde boğulsun karanlık.

Düşüme uçan aşkın kıvılcımı,

Kelebek kanadı göğsünde

                           Soğurken,

Yüzyılların öcünü alır ayrılık,

Koparır,

            Filizlenen,

                             Usumdaki seni.

Düş kokulu gezginliğinde

        Çocuk gülüşlü sadelik.

        Özleme yatan aşkın kıvılcımında

         Umuda büyümeli  ayçiçekleri.

Güneşin sıcaklığı kardeşliğinde yıkansın! 

Düşüme uçan aşkın kıvılcımı,

Kelebek kanadı göğsünde

                           Soğurken,

Yüzyılların öcünü alır ayrılık,

Kapanır aşkın gözü,

Uzar,ezginliğin saçları,

Kararır yokluğun.

Tutkulu yaşama yapış kalır

geride.

Bir de; 

Umuda büyüyen ayçiçekleri.', 'Düşüme Uçan Aşkın Kıvılcımı Yağmur damlası hafifliğindesin. Oysa, Sana düşüşüm,şimşek ağırlığında. Kölelik             Sonrası              ...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Özbek']::text[], 8.5, '{"poet":"Yüksel Özbek","poet_slug":"yuksel-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dusume-ucan-askin-kivilcimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefes Alışında Hisset Yaşamı', 'nefes-alisinda-hisset-yasami-yuksel-ozbek-pt5wn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Örnek bir çocuk gibi

Dışında durdum hayatın! 

İdealin peşinden vazgeçen 

korkak,olmadım.

Kendi geçmişini yiyen

Zaman timsahını,sevemedim.

Gözyaşlarında boğulan iğrençlikte,

Yarınların dışsallığında 

Sadece “ben” de kalamadım! ! 

Yağmur ormanlarında kaybolan

                                      Güz.

Yüreğimin sığlığında neden büyüdün? ! 

Oysa:

Mutsuzluk yazgısına direnişti

                  Yaşam öyküm.

Kötülüğünde boğulan gecede,

Yaya kalmış aşkım,

Fesleğen inadında kokmalısın.

Altı milyarda çoğalan yalnızlığım; 

İnce bir dokunuşla sevgiye,

Ilık bir ses tonuyla nefeste 

                                Sönmeli.

Serüvenim orda bitmeli.

Çocukluğum orda! 

Orda girmeliyim içine,

Hayatın!', 'Örnek bir çocuk gibi Dışında durdum hayatın!  İdealin peşinden vazgeçen  korkak,olmadım. Kendi geçmişini yiyen Zaman timsahını,sevemedim. Gö...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Özbek']::text[], 8.5, '{"poet":"Yüksel Özbek","poet_slug":"yuksel-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/nefes-alisinda-hisset-yasami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖKTE YEŞEREN KARANFiLLER', 'gokte-yeseren-karanfiller-mehmet-kizilay-1gqjn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bana

hüznünle gelişine

kızmıyorum..

gözlerinden dökülen sözcükleri

yüreğime boşaltmana da..

mehtaba kızgınım..

kızıyorum o''na..

kendini 

geceye yamayan

ödünç verdiğin ışıkla  beslenen

mehtap

gözümde küçülüyor

günden güne..

doğru değilse de bunlar

kabul ettirdim kendime

yokluğuna kızgınım

kızıyorum yalnızlığıma 

bir gün

hiç istemediğim o gün yani

sen ölecek olursan

ne olur erguvan bakışların

onları da götürür müsün..

istesem 

ben de bırakır mısın..

bu çarpık bacaklı 

çelimsiz mehtap

nereden ışık dilenip te..

ışık yettirecek 

koca dünyaya

acıyorum o gün...

insanlara.! 

güneşe de kızıyorum

kızgınım o''na da..

hergün hergün

seni görme umuduyla

mesafeleri aşıp gelen güneş

dünyaya doğan güneş

duyacak olursa öldüğünü

ne olur dünyanın hali

ne olur insanların hali.

ne olur 

göğsünden emzirdiğin

gökte yeşeren karanfil

ne olur tabiat..

yoksa biter mi hayat..

sadece benim için mi biter..

nolur sadece 

ben öleyim YETER...

Mehmet KIZILAY - Karanfil Şiirler', 'bana hüznünle gelişine kızmıyorum.. gözlerinden dökülen sözcükleri yüreğime boşaltmana da.. mehtaba kızgınım.. kızıyorum o''na.. kendini  gec...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/gokte-yeseren-karanfiller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanmak', 'aldanmak-gokhan-oflazoglu-ig6vp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalana muhtaç ruhlarımız,

defalarca söylense inanırız,

böyle daha rahat dayanırız.

Gerçek tahripkardır.

Aldatın bizi, yıkılmasın dünyamız.

16/05/2004', 'Yalana muhtaç ruhlarımız, defalarca söylense inanırız, böyle daha rahat dayanırız. Gerçek tahripkardır. Aldatın bizi, yıkılmasın dünyamız. 1...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aldanmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yevm-i SAKIT', 'yevm-i-sakit-mehmet-kizilay-2xone', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu bir yalvarış değil

haykırış da değil..

bu duyduğun

iniltilerimin feveranı..

haykırışlar

umut istasyonunda

yüklendiğim

umut yüklü haykırışlarım

yola vurulan kervan ve 

diğer yol mecburu dostlarım 

hep birlikte

uçuşuverdi..

 çöl yolunda

kum taneciği misali

bitmez dediğin sevdaya

yaptığın bunca ihanet

cehennem yolunda

dağ kadar yakıt..

utanmıyacaksan sevin 

cehennemde üşümeyeceksin 

anlamadıysan anlatayım

bugün 

öfkelerin depreştiği bugün

yevm-i sakıt

hadi durma artık

getir gözyaşlarını 

kan gölüne akıt

utanmadan ağla..ağla..', 'bu bir yalvarış değil haykırış da değil.. bu duyduğun iniltilerimin feveranı.. haykırışlar umut istasyonunda yüklendiğim umut yüklü haykırış...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yevm-i-sakit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bir atışta vurdum BENİ', 'bir-atista-vurdum-beni-mehmet-kizilay-9x703', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'pusudaydım

kaç gecedir pusudaydım

düşman yaklaştı

böğrümden vuracak 

ya da 

korkutacaktı

ayağa kalktım

atıverdim silahımı

vur beni dedim

onurlu savaşçılara benzer gibi.? .

kendime ihanet ettim

sattım kendimi

ve de ummani sevdamı

vurulmamak uğruna..

attım silahımı yere.

tuttum

düşmanın elindeki

kan değmiş namluyu

dayadım hayın bedenime

bir atışta yere serdim

boşu boşuna olan 

bir yaşama 

karar verdim..

kime faydası olacaksa 

bu bedenin yaşamasının..bilmeden..

Umut İstasyonu''ndan...', 'pusudaydım kaç gecedir pusudaydım düşman yaklaştı böğrümden vuracak  ya da  korkutacaktı ayağa kalktım atıverdim silahımı vur beni dedim onu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-atista-vurdum-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-gokhan-oflazoglu-vop0i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar çok fikir var,

herkes ben haklıyım diyor.

Hayat; o büyük gerçek

kimseyi dinlemiyor.

Bir bakmışız başka bir

boyuttayız ve bir yenisi

hazırlanıyor.

16/05/2004', 'Ne kadar çok fikir var, herkes ben haklıyım diyor. Hayat; o büyük gerçek kimseyi dinlemiyor. Bir bakmışız başka bir boyuttayız ve bir yenisi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olan ve olmayan bulunandaki', 'olan-ve-olmayan-bulunandaki-akin-akca-5e9zv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dengelendiği en sabitkar karmaşasında bu zaman burgacında; 

Zenginliğinde,küle devingen tekerrürlerinde aktif-alıngan alevin … 

Ötesinde dağların,hem içinde onların … 

Önceki daha berrak ‘ama - yollar’dan, 

Patikasında,engin tepelere tırmanan ayaklar için … 

(Ama bu vücutta var bir de kafa:Sevgi gibi,nefret içerisindeki; 

Sen de ki, 

Hakim olandır içerideki, 

Ona bu şansı veren olmasından ötürü,dışarıdaki)

Cama fırlattığım top,camın kırılmasından sonra atılır 

Desem ki,durmazdı zaman. 

Hayır,değil kara delik için,mantık için. 

Öyle ki,kendisi bile değil: 

Zamansız’lığı zamanın,anlamınca sıyrılmıştır 

‘Kendisi olmayan ya da olamayan kendinden’ artık. 

Gökyüzüne dökülür zamanı yaratan eller, 

Ellere sıfatını verir zaman ve oracıkta bekler. 

Kayıp otobanı ''çöl gece-bilinmezi''nin 

Ve ''kargacık burgacık - Ege kıyıları-ağaçlar'' yerlere soluk seren: 

Acı üretkenliğinde içtekinin,yaratılan:Dıştaki,gerçek yaratan; 

Parmakların belkemiği,yırtıklar olup yumruklar halinde ötüşken; 

Kendisi beliremeyen gecenin özütü: 

Akmayan zaman ve zaman akar; 

Sonsuz döngüsünde,bir çöl nefesinde; 

Hörgüç:Sıra dışı,çalışkan-işçisi,su saklar.', 'Dengelendiği en sabitkar karmaşasında bu zaman burgacında;  Zenginliğinde,küle devingen tekerrürlerinde aktif-alıngan alevin …  Ötesinde dağ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olan-ve-olmayan-bulunandaki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir çocuk vardı', 'bir-cocuk-vardi-etem-kara-la166', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çocuk vardı,

                    masumdu, 

                                zarasızdı,

Hiçte hata yapmazdı.

Ve  bundan dolayı olsa gerek 

Hiç bir şeyde yapamazdı

Bir çocuk vardı

Büyükleri için efendiydi

arakadaşları içinse, belirsiz...

Bir çocuk vardı...

Daha doğrusu,

Bir sürü çocuk vardı; 

                    bu ülkede

                               bu kültürde...

Yirimisinde ölmüşlerdi,

Kırkeşinde de gömüldüler.', 'Bir çocuk vardı,                     masumdu,                                  zarasızdı, Hiçte hata yapmazdı. Ve  bundan dolayı olsa gerek ...', ARRAY['Türk Edebiyatı','Şiir','Etem Kara']::text[], 8.5, '{"poet":"Etem Kara","poet_slug":"etem-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-cocuk-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonu türküdür', 'sonu-turkudur-zafer-zengin-etnika-u9flx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Katıksız bir bakış ellerin

Küçücük 

Sancısız

Ürker soğukluğundan

Dokunsam

Yanacaklar

Dokunmasam

Yalnızlar

Uzat öpeyim gözlerinden

Buradan erken gitmeden

Gider ki; sonu türküdür

***'' Dolanı dolanı gelir..Zulüm yavaşça yavaşça

Kalem alıp yaz derdimi..Gülüm yavaşça yavaşça''

Sana yaksaydım türküyü

Parmaklarım yanardı

İzi kalırdı sancımın

Dil söylesin

Gülüm dinlesin diye

Hep dağ başlarını seçtim

Bildim ki; 

Sesin hep hasret

Elin hep gurbet

Ben olmayaydım da

Sana bir fidan rastlayaydı

Güleç yüzlü filinta

Senden çok severdim

Kavuşmanı

Dedim işte

Saklanan son mavzer

Saklanan son mermi

Birazda

Şairin kendinedir

Bazan gül

Bazen mermi sürer namluya

Elleri yanar

Güle dokunmasa

/İzi kalır sancının / Çocuk körpe / Türkü dağ...

16 Mayıs 2004 '' İçimin kitabı '' 

*** Feyzullah çınar usta''nın '' Yavaşça'' adlı deyişinden alınmıştır. Saygıyla anıyorum...', 'Katıksız bir bakış ellerin Küçücük  Sancısız Ürker soğukluğundan Dokunsam Yanacaklar Dokunmasam Yalnızlar Uzat öpeyim gözlerinden Buradan er...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sonu-turkudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olmuyor Anne', 'sensiz-olmuyor-anne-said-demirel-uc8wo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her gece aklıma düştüğün zaman

Yastığım göl olur, yatağım deniz

Ben bu acılarla yüzerken sensiz

Benim için dua et anneciğim

Uzaktan uzağa kucak açsam da

Kollarım havada boş kalır anne

O sıcak sevgine hasret kalsam da

Ümidim yoklukta toz kalır anne

Ümidi yollara, sevgini içime gömdüm

Asıl kıymetini gurbette bildim

El açıp Allah’a candan yalvardım

Affına sığındım affeyle anne

(Ankara - 11/07/1997) 

(Kitap: Boş Noktalar, 2003, Sayfa: 27)', 'Her gece aklıma düştüğün zaman Yastığım göl olur, yatağım deniz Ben bu acılarla yüzerken sensiz Benim için dua et anneciğim Uzaktan uzağa ku...', ARRAY['Türk Edebiyatı','Şiir','Said Demirel']::text[], 8.5, '{"poet":"Said Demirel","poet_slug":"said-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensiz-olmuyor-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekar Kaldık', 'bekar-kaldik-said-demirel-ymeao', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öşündere korkunç akar

Alımlı kız beni yakar

Parmağına yüzük takar

Nişanlı sansınlar diye

Ballık Mağara’da tarla

Evlerinin yeri yayla

Babasını şehre yolla

Dağa kaçırayım diye

Selvi boyu sallanıyor

Yaş on sekiz ballanıyor

Sırma saçlar dalgalanıyor

Rüzgar alsın götürsün diye

Evlerimiz karşı karşı

Olsun istiyormuş maaşlı

Hemen bir iş bulmalı

Bu kızı alayım diye

Ana; akşama düğürcü gidin

Beni öve öve bitirin

İkisi de seviyor deyin

Nişanımız olsun diye

Baba; tarlayı, takımı sat

Alayım Ankara’dan bir kat

Düğünde beşibirlik tak

Maşallah desinler diye

Bu iş çoktan uzadı

Yaşımız otuza vardı

Bu yıl da ev boş kaldı

Evlenmedik, bekar kaldık diye

(Değirmendere - 28/07/1998) 

(Kitap: Boş Noktalar, 2003, Sayfa: 43-44)', 'Öşündere korkunç akar Alımlı kız beni yakar Parmağına yüzük takar Nişanlı sansınlar diye Ballık Mağara’da tarla Evlerinin yeri yayla Babasın...', ARRAY['Türk Edebiyatı','Şiir','Said Demirel']::text[], 8.5, '{"poet":"Said Demirel","poet_slug":"said-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bekar-kaldik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtilal Artığı', 'i-htilal-artigi-hayrettin-turk-iydbk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buz kesen bir mart sabahı

Yıllarımı ardımda bırakıp

Ayrılmıştım senden; 

Sevdamdın,

Gençliğimdin…

Ramazan gecelerinde

Caddelerinde çığlıklar atar

Boş asfaltlarında top oynardık; 

Her cadden

Ve her insanınla 

Benimdin…

İlk silahı seninle tanıdım

İlk çatışmayı

ve ilk kelepçeyi; 

Caddelerinde kemiklerimi kırdılar

Ödül olarak

Sen bana ihtilali sundun…

Sende sevdam vardı

Sokaklarında ayak izlerim

Gecelerinde gözyaşlarım; 

Duvarlarında ise

Sevdamı anlatmayan yazılarım…

Şimdi; 

Sıcak bir temmuz sabahı

Caddelerindeyim gene

Havanı çekiyorum içime

İçim acıyor

Ağlıyorum…

Dolanıyorum caddelerinde

Her yerde dolandığım gibi

Döndüğüm bir köşede

Ne olduğunu bilmeden

Ve bir kez bile

Bir tanıdık görmeden…

Anlıyorum seni

Milat öncesi zamanlarda kalmış

İhtilal artığı bir cana

Yer yok caddelerinde

Oysa ki; 

Sen benimdin

Ben senin olamadım…

Üç beş yitik can ziyareti

Ve dualar kabristanda

Sonra elveda gene sana

Söz, 

Gene geleceğim

Caddelerinden toplayıp ayak izlerimi

Omuzlar üstünde taşıtacağım kendimi

Kucağında dalacağım sonsuzluğa…', 'Buz kesen bir mart sabahı Yıllarımı ardımda bırakıp Ayrılmıştım senden;  Sevdamdın, Gençliğimdin… Ramazan gecelerinde Caddelerinde çığlıklar...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ihtilal-artigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meta / Ticari-Vasiyeti (''Da Good'')', 'meta-ticari-vasiyeti-da-good-akin-akca-25flv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buy

And sell

For hundreds.

And a thousand:

(Whatta dynamo? Oh!)

One human in ''a thousand''; 

But, one by one

And hundreds of thousands in a million with billions:

A mega bomb! 

The good,

Like a table with a meaning of garbage,

But a table,

Needles to say, carries an ‘unconscious doubt o’stamp’:

Sometimes toxic, sometimes not; 

Extraordinarily-mushroom like-activated:

So strange,

For being ''the best''; 

So as to be ‘the real (non-)   epic fairy’, but people.

Real fairy is table: Table''s not pretending; 

Human, pretend-activated

Pretendingly protected.

Neither table nor people

For human? But,

Table seems like a mushroom,

People ain''t.

-

türkçesi -

Al 

Ve sat: 

(Vücutlar alınan, vücutlar satılan; 

Vücutlar mesut, ruhlar acı çeken)

''Yüzler'' için (Güruh için)

Ve bir ''bin''; 

(Olsa kaç yazar bir dinamo, bobin)

Fakat, teker teker. 

Ve ''yüzler'' ki, onlar binler''de ve binlerce milyon, milyarlar''la 

Boom! 

Meta (Eşya) : 

Lidyalılar örgüsü mü mevzu? 

Bir masa gibi, sarf çöp hüviyetinde; 

(Değerlidir onu bile bulamıyor olmaktan, 

Fakat sarf anlamlı olmak)

Fakat bir masa - gerek var mı ki, söylemeye - 

‘Bilinç dışı bir şüphe pulu’ taşır hörgücünde: 

Bazen zehirli, değil bazen; 

Sıradışı-duraksayamayan 

Ki bir mantar oluşumu yerden bitti: 

Çok garip, 

En iyi olmak için, 

Kahramanca (çarpışmayan)

Gerçek masalsı olmaya - insan için. 

Gerçek masal, masa; masalsı olamayan. 

Gerçek masalsı, insan - 

yeşilce-yalansı korunan. 

Ne masa ne insan, canlılık için? 

Fakat,masa mantar gibi sırıtıyor; 

Ki, insansa değil böyle (bile)  yampiri.', 'Buy And sell For hundreds. And a thousand: (Whatta dynamo? Oh!) One human in ''a thousand'';  But, one by one And hundreds of thousands in a m...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/meta-ticari-vasiyeti-da-good-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zardoz zararlısı-1', 'zardoz-zararlisi-1-akin-akca-qlh7m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(Edinilmişlik-yetkisi ile

 ''arzuların yankısız akıl-itkisi'' 

Bir olur da; Diğer yanda ama

 aynı mekanda, farzet bir ölümlü,

 zorla alı konulur ya.. )

...

:Zardoz’da ebed ile tapınak 

E ve insanlar için tapınmak: 

… Yunan tanrılarına 

Kuruldu bir salıncak. 

* 

Küveze kapayanlar kendilerini, 

Bir karar arefesinde; 

Bir ölümlü için yeterince imkansızı, 

Karar alınacak …

Ama, o fazla yaşamıştı; 

Zarar etmeye, yakasında büyüklerin. 

Ölemeyenler ölmeye başladı, 

(Derken)  Mükemmel denge bozuldu. 

Ama karıncalar iş bölümünü bıraktı; 

İnsan gibi insan gibi yaratıcı oldu. 

Kitle ölümler ile geldi ölümsüzlük; 

Huzur bulmaya başladı, yaşanmışlık. 

Huzurun huzurundaki huzursuzluk 

Huzur bulmuştu: Huzur bulur oldu, 

Erbunak çıldıran kadim aza’lar: 

Onlar, genç kızlar, bir mağarada yaşarlar; 

Fırlatılır,atılır, taciz edilir, farkına varmazlar. 

Olanı biteni anlamaya çalışan bir fani-duyarlı: 

Sean, baktı birine, dokundu ve itti; 

Başı -onlardan- bağlı, beyazdı rengi; 

Kız oralı olmadı, hissetmemişti, 

Yürümeye devam etti: 

Kaldırdı onu Zed, fırlattı, samanların üstüne attı. 

Ve bir at arabası, Sean yine, çekiyor arabayı; 

At arabasına sürülü, taşıyor bir tanrıyı; 

Koridorundan bir mekanın apansız geçtiler, 

Orda ebedi bunaklar vardı; 

Ama ölemiyorlardı, hepsi aşırı yaşlıydı: 

(Oynayıp koşuşturuyordu yaşlılar; 

Yılbaşı seyri-seferi gibi bir ortam…)

Nasıl olduysa, nedense, sonra oldu: 

Bir sürü tanrı eli, yuvarlak masa etraflı; 

Birleşti havada, konuştu, titreşti: 

(Kötü ruh''u çağırmaktan kötü bir ruh çağırma eylemi.)

Sessiz bir miting, topluca, vardı; 

Hepsi de onun için toplanmıştı; 

O tanrı cezalandırıldı; 

Yaşlandırıldı, ebedi ihtiyarlığa mahkum.. 

Yeri artık, erbunak olmayan 

Ebedi bunak yaşlıların yanı,

Ki onlar cıvıldaşıyorlar ama oynamıyorlar; 

Bilinçsiz hem, ve devamlı kavga ediyorlar. 

Önceki köle taciri, at koşan; cezalandırılan tanrı: 

Saçı artık bembeyaz, yüzü onun pörsümüş. 

Yardım, Sean''a etti; 

Putlar, kırılmaya başlandı; 

Her şey doğasına göre oldu.. 

Bir şekil, bazı bazı, ama uyuşturuldu. 

(Yine de: İş bölümü sanatı; 

Makinalaşmış ütopyası, 

Enkaz özgür artık.)

Göbek bağını o kesti,Sean; 

Bu mükemmel kubbenin. 

- 

05:58 / 16 Mayıs Pazar 2004 (''Zardoz'' adlı film ile ilgili olarak) 

-

Son versiyon (düzeltilmiş haliyle) 

(Edinilmişlik-yetkisi ile

 ''arzuların yankısız akıl-itkisi'' 

Bir olur da; Diğer yanda ama

 aynı mekanda, farzet bir ölümlü,

 zorla alı konulur ya.. )

...

